def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Render a literary clock quote for a given time.")
    parser.add_argument(
        "--time",
        default=None,
        help="Time in HH:MM 24-hour format. Required unless --mode goodnight.",
    )
    parser.add_argument(
        "--output",
        default=None,
        help=(
            "Output PNG path. Defaults to output/current.png (overwritten on every "
            "run) so repeated ad-hoc invocations don't leak one file per HH:MM into "
            "output/. Pass an explicit path when you want a persistent per-time "
            "artifact. run_clock.py always passes --output explicitly, so the "
            "runtime loop is unaffected by this default."
        ),
    )
    parser.add_argument("--width", type=int, default=DEFAULT_WIDTH)
    parser.add_argument("--height", type=int, default=DEFAULT_HEIGHT)
    parser.add_argument(
        "--mode",
        choices=["production", "debug", "card", "goodnight"],
        default="debug",
        help=(
            "Render mode. 'production' hides debug UI; 'debug' shows bucket/quality/time "
            "metadata; 'card' draws a centered source card (title/author/Gutenberg ID/"
            "matched phrase) instead of the full quote — used by the source-card button. "
            "'goodnight' draws the sleep frame in the active theme — used by "
            "--quiet-image=auto and --startup-image=auto. By default that is the "
            "bundled sleep quote rendered through the normal literary layout; pass "
            "--message to draw a bare centered headline instead."
        ),
    )
    parser.add_argument(
        "--message",
        default=None,
        help=(
            "Draw this headline for --mode goodnight instead of the bundled sleep "
            "quote. A headline has no attribution line and no accent-coloured "
            "phrase, so the default (omitting this flag) is what reproduces the "
            "'To sleep, perchance to dream.' frame in the active theme. "
            "Ignored outside --mode goodnight."
        ),
    )
    parser.add_argument(
        "--theme",
        choices=sorted(THEMES),
        default="default",
        help="Color theme to use when rendering.",
    )
    parser.add_argument(
        "--history-path",
        default=pick_quote_module.DEFAULT_HISTORY_PATH,
        help="Path to the anti-repeat display history JSONL. Pass an empty string to disable.",
    )
    parser.add_argument(
        "--history-days",
        type=int,
        default=pick_quote_module.DEFAULT_HISTORY_DAYS,
        help="Number of days of history to consider when filtering repeats. 0 disables.",
    )
    # Corpus / sidecar locations. run_clock forwards its resolved values so
    # the render subprocess reads exactly the files the curator UI writes
    # (under the systemd sandbox, the writable state dir). Defaults point a
    # bare ``render_quote.py --time HH:MM`` at the bundled assets.
    parser.add_argument(
        "--database",
        default=pick_quote_module.DEFAULT_DATABASE_PATH,
        help="Baked display-ready quote database (output of bake_quote_database.py).",
    )
    parser.add_argument(
        "--input",
        default=pick_quote_module.DEFAULT_INPUT_PATH,
        help="Raw attributed corpus, used as the fallback when --database is missing.",
    )
    parser.add_argument(
        "--overrides",
        default=pick_quote_module.DEFAULT_OVERRIDES_PATH,
        help="Selection-overrides sidecar (bans / boosts / preferred buckets).",
    )
    parser.add_argument(
        "--pin-quote",
        default=None,
        metavar="SOURCE_ID:LINE",
        help=(
            "Render this exact corpus row instead of picking one. Used by "
            "run_clock for theme-change repaints so the panel keeps showing "
            "the same quote the anti-repeat filter would otherwise exclude. "
            "Falls back to a normal pick when the row no longer exists; a "
            "malformed value is ignored with a warning."
        ),
    )
    parser.add_argument(
        "--pin-matched-text",
        default=None,
        metavar="TEXT",
        help=(
            "Disambiguator for --pin-quote. One source line can carry several "
            "time phrases, so SOURCE_ID:LINE is not a unique row key; passing "
            "the peeked matched_text alongside it pins the exact row the "
            "caller chose instead of whichever duplicate comes first on disk. "
            "A row that matches the key but not this text is skipped, and the "
            "render falls back to a normal pick."
        ),
    )
    parser.add_argument(
        "--photo-path",
        default=None,
        metavar="PATH",
        help=(
            "Image file or directory for the `photo` theme. Sets "
            f"{PHOTO_PATH_ENV} for this process. run_clock never passes this "
            "flag to the render subprocess — it exports the environment "
            "variable instead, so an operator's own --render-script cannot be "
            "broken by an unrecognised argument (see _corpus_render_args)."
        ),
    )
    args = parser.parse_args()
    if args.mode != "goodnight" and not args.time:
        parser.error("--time is required unless --mode goodnight")
    return args


def pick_quote(
    time_str: str,
    history_path: str | None = None,
    history_days: int = pick_quote_module.DEFAULT_HISTORY_DAYS,
    database_path: str | None = None,
    input_path: str | None = None,
    overrides_path: str | None = None,
    pin_key: tuple | None = None,
) -> dict:
    """Pick the quote to render.

    The three corpus/sidecar paths default to the bundled assets but are
    overridable so ``run_clock`` can point the render subprocess at the
    operator's writable copies — the ones the curator UI mutates. Threading
    ``overrides_path`` through is what makes a UI-issued ban reach the panel.
    """
    return pick_quote_module.select_quote(
        time_str=time_str,
        history_path=history_path,
        history_days=history_days,
        database_path=database_path or pick_quote_module.DEFAULT_DATABASE_PATH,
        input_path=input_path or pick_quote_module.DEFAULT_INPUT_PATH,
        overrides_path=overrides_path or pick_quote_module.DEFAULT_OVERRIDES_PATH,
        pin_key=pin_key,
    )


def parse_pin_quote(value: str | None, matched_text: str | None = None) -> tuple | None:
    """Parse a ``SOURCE_ID:LINE`` --pin-quote value; None/malformed → None.

    ``matched_text`` (from ``--pin-matched-text``) is appended as a third
    element when supplied. It is required for correctness whenever the pin has
    to survive a corpus with duplicate ``(source_id, line_number)`` keys — see
    the pin block in ``pick_quote.select_quote``.

    Fail-open: a malformed pin must degrade to a normal pick with a stderr
    warning, never kill the render subprocess mid-loop.
    """
    if not value:
        return None
    source_id, sep, line = value.partition(":")
    if sep and source_id:
        try:
            key = (source_id, int(line))
        except ValueError:
            pass
        else:
            return key if matched_text is None else (*key, matched_text)
    print(f"warning: ignoring malformed --pin-quote {value!r}", file=sys.stderr)
    return None


_FONT_CACHE: dict[tuple, ImageFont.ImageFont] = {}


def _normalize_candidates(candidates) -> tuple:
    """Normalize the load_font candidates list into a hashable cache key.

    Plain string entries become ``(path, None)``; tuple entries pass through.
    """
    return tuple((c, None) if not isinstance(c, tuple) else tuple(c) for c in candidates)


def load_font(candidates: list, size: int):
    """Load the first reachable TrueType font in ``candidates``, memoized.

    Each entry is a path string or a ``(path, variation_name)`` tuple; for
    the tuple form ``set_variation_by_name`` selects the named instance. This
    is load-bearing for variable fonts whose default instance is Thin (e.g.
    Bitter). A variation name the file doesn't expose silently falls back to
    the default instance; the next candidate is tried only if the file is
    missing or unreadable.

    Cached per process on ``(normalised_candidates, size)`` — ``fit_quote``
    calls this many times per render with the same chain at different sizes.

    Contract: callers must NOT mutate the returned font (e.g. call
    ``set_variation_by_name`` on it). Variation pinning lives in the
    candidate tuple so it is part of the cache key; a mutation would corrupt
    other cache consumers.
    """
    global _FONT_FALLBACK_WARNED
    normalized = _normalize_candidates(candidates)
    cache_key = (normalized, size)
    cached = _FONT_CACHE.get(cache_key)
    if cached is not None:
        return cached
    for path, variation in normalized:
        if not Path(path).exists():
            continue
        try:
            font = ImageFont.truetype(path, size=size)
        except OSError:
            continue
        if variation:
            try:
                font.set_variation_by_name(variation)
            except (OSError, ValueError, AttributeError):
                pass
        _FONT_CACHE[cache_key] = font
        return font
    if not _FONT_FALLBACK_WARNED:
        print(
            "warning: no TrueType font found; falling back to PIL bitmap default. "
            "Install fonts-noto-core or the bundled fonts/ directory.",
            file=sys.stderr,
            flush=True,
        )
        _FONT_FALLBACK_WARNED = True
    # Deliberately NOT caching the bitmap fallback: a transient miss would
    # pin the process to degraded rendering for its lifetime (contact_sheet
    # renders 144 frames in one process). Re-scanning is cheap; the
    # warn-once comes from _FONT_FALLBACK_WARNED, not from caching.
    return ImageFont.load_default()


def strip_underscore_emphasis(text: str) -> str:
    """Drop Gutenberg's ``_emphasis_`` markers, paired or not (issue #308).

    Paired spans go first; then any single underscore at a word edge (an
    unpaired or mangled marker such as ``_It had run down…`` or
    ``[Stiffly_._]``). Runs of two or more are kept: ``Mr. ____`` is a
    suppressed name, and a dunder like ``__init__`` must not be read as
    ``_init_`` emphasis. A marker standing alone between two spaces takes one
    space with it so no double gap is left.
    """
    if not text or "_" not in text:
        return text or ""
    text = re.sub(r"(?<![A-Za-z0-9_])_([^_\n]+?)_(?![A-Za-z0-9_])", r"\1", text)
    # A lone marker as its own word: drop it and one adjacent space.
    text = re.sub(r"(?:(?<=\s)|^)_(?:[ \t]+|$)", "", text)
    # Only at a word edge, so an in-word ``var_name`` is left alone.
    return re.sub(r"(?<![A-Za-z0-9_])_(?!_)|(?<!_)_(?![A-Za-z0-9_])", "", text)


def normalize_dashes(text: str) -> str:
    if not text or "--" not in text:
        return text or ""
    return re.sub(r"(?<!-)--(?!-)", "\u2014", text)


# ---------------------------------------------------------------------------
# Missing-glyph fallback
# ---------------------------------------------------------------------------
#
# PIL's font fallback is file-level, not glyph-level: a face with no glyph for
# a character draws its ``.notdef`` box (tofu). Several bundled display faces
# lack common marks (Iceland has no ``…``; ~20 faces have no ``′``), so
# ``render`` rewrites such characters to ASCII stand-ins — *only* those the
# theme's body / matched-phrase faces actually lack, so a theme whose fonts
# carry the glyph stays byte-identical.

# A codepoint no font maps: the last Unicode noncharacter. Rendering it yields
# the face's ``.notdef`` glyph, whatever that looks like (a box, a hollow
# rectangle, or nothing at all).
_NOTDEF_PROBE = "\U0010FFFF"

# Characters with an ASCII fallback, checked only when they occur in the text.
# The em-dash is special-cased in ``_apply_glyph_fallbacks`` (spacing-aware);
# its entry here is the bare fallback used at a text edge.
GLYPH_FALLBACKS: dict[str, str] = {
    "\u2026": "...",  # … horizontal ellipsis
    "\u2032": "'",  # ′ prime
    "\u2033": "''",  # ″ double prime
    "\u2019": "'",  # ’ right single quote / apostrophe
    "\u2018": "'",  # ‘ left single quote
    "\u201c": '"',  # “ left double quote
    "\u201d": '"',  # ” right double quote
    "\u2014": "-",  # — em dash (see _EM_DASH_BETWEEN_RE)
    "\u2013": "-",  # – en dash
}

# An em dash between two non-space characters becomes a spaced hyphen: an
# unspaced ``word-word`` would read as a hyphenated compound, and ``--`` cannot
# be used because ``normalize_dashes`` turns it straight back into an em dash.
_EM_DASH_BETWEEN_RE = re.compile(r"(?<=\S)\s*\u2014\s*(?=\S)")

# (font identity, char) -> True when the face has a real glyph. The cmap does
# not change with size or variation instance, so the key is the font file.
_GLYPH_PRESENT_CACHE: dict[tuple, bool] = {}


def _glyph_signature(font, ch: str) -> tuple:
    mask = font.getmask(ch)
    return (mask.size, bytes(mask), font.getbbox(ch))


def font_has_glyph(font, ch: str) -> bool:
    """Return True when ``font`` has a real glyph for ``ch`` (not ``.notdef``).

    Compares the rendered mask and bbox of ``ch`` against those of a codepoint
    no font maps, which PIL draws as the face's ``.notdef``. Works whether
    ``.notdef`` is a box or blank (a blank ``.notdef`` differs from any visible
    glyph). A real glyph drawn identically to ``.notdef`` would be misread as
    missing; none of the characters in ``GLYPH_FALLBACKS`` look like that.
    Memoised per (font file, char), so the cost is paid once per process.
    """
    ident = getattr(font, "path", None)
    key = ((ident, getattr(font, "index", 0)) if ident else ("id", id(font)), ch)
    cached = _GLYPH_PRESENT_CACHE.get(key)
    if cached is not None:
        return cached
    try:
        present = _glyph_signature(font, ch) != _glyph_signature(font, _NOTDEF_PROBE)
    except (AttributeError, OSError, TypeError, ValueError):
        present = True  # can't tell: leave the text alone
    if ident:  # never cache on id() — a freed font's id can be reused
        _GLYPH_PRESENT_CACHE[key] = present
    return present


_GLYPH_FALLBACK_ROLES = ("quote_regular", "quote_bold")
_GLYPH_FALLBACK_FIELDS = ("display_quote", "matched_text", "author", "title")


def _missing_fallback_chars(theme: str, texts) -> set[str]:
    """Characters in ``texts`` with a fallback that a ``theme`` text face lacks."""
    wanted = {ch for text in texts for ch in GLYPH_FALLBACKS if ch in text}
    if any("--" in text for text in texts):
        wanted.add("\u2014")  # normalize_dashes will produce one
    if not wanted:
        return set()
    fonts = [load_font(theme_font_candidates(theme, role), size=32) for role in _GLYPH_FALLBACK_ROLES]
    return {ch for ch in wanted if not all(font_has_glyph(f, ch) for f in fonts)}


def _apply_glyph_fallbacks(text: str, missing: set[str]) -> str:
    if not text or not missing:
        return text
    if "\u2014" in missing:
        text = normalize_dashes(text)
        text = _EM_DASH_BETWEEN_RE.sub(" - ", text)
    for ch in missing:
        text = text.replace(ch, GLYPH_FALLBACKS[ch])
    return text


def apply_theme_glyph_fallbacks(quote_row: dict, theme: str) -> dict:
    """Return ``quote_row`` with characters ``theme``'s fonts lack made ASCII.

    Applied to ``display_quote`` / ``matched_text`` / ``author`` / ``title``
    with the *same* substitution set, so ``resolve_display_match`` still finds
    the matched phrase inside the rewritten quote. Returns the row itself,
    unchanged, when nothing needs substituting — the common case, and the one
    that keeps every theme whose faces carry the glyphs byte-identical.
    """
    texts = [v for v in (quote_row.get(k) for k in _GLYPH_FALLBACK_FIELDS) if isinstance(v, str) and v]
    missing = _missing_fallback_chars(theme, texts)
    if not missing:
        return quote_row
    row = dict(quote_row)
    for key in _GLYPH_FALLBACK_FIELDS:
        value = row.get(key)
        if isinstance(value, str) and value:
            row[key] = _apply_glyph_fallbacks(value, missing)
    return row


def choose_layout(text: str) -> str:
    length = len((text or "").strip())
    if length <= 90:
        return "hero"
    if length <= 170:
        return "standard"
    return "dense"


TIME_PHRASE_PREFIXES = [
    "five minutes past",
    "ten minutes past",
    "quarter past",
    "twenty minutes past",
    "twenty-five minutes past",
    "half past",
    "twenty-five minutes to",
    "twenty minutes to",
    "quarter to",
    "ten minutes to",
    "five minutes to",
]

# Pre-compiled longest-first so the first prefix that matches the candidate
# wins ("twenty-five minutes past" beats "minutes past" for the same row).
# Order is load-bearing — keep this list sorted by descending prefix length.
_TIME_PHRASE_PATTERNS: list[tuple[str, re.Pattern[str]]] = [
    (
        prefix,
        re.compile(
            rf"(?<![A-Za-z0-9])(?<![A-Za-z0-9]-){re.escape(prefix)}"
            rf"(?:[ ,]+[A-Za-z0-9]+(?:-[A-Za-z0-9]+)*)?(?![A-Za-z0-9])(?!-[A-Za-z0-9])",
            re.IGNORECASE,
        ),
    )
    for prefix in sorted(TIME_PHRASE_PREFIXES, key=len, reverse=True)
]


def _direct_match_pattern(normalized_match: str) -> re.Pattern[str]:
    return re.compile(
        rf"(?<![A-Za-z0-9])(?<![A-Za-z0-9]-){re.escape(normalized_match)}(?![A-Za-z0-9])(?!-[A-Za-z0-9])",
        re.IGNORECASE,
    )


def resolve_display_match(text: str, match_text: str) -> str:
    normalized_match = " ".join((match_text or "").split()).strip()
    if not normalized_match:
        return ""

    direct = _direct_match_pattern(normalized_match).search(text)
    if direct:
        return direct.group(0)

    lower_match = normalized_match.lower()
    for prefix, pattern in _TIME_PHRASE_PATTERNS:
        if not lower_match.startswith(prefix):
            continue
        for m in pattern.finditer(text):
            candidate = m.group(0).strip(" ,.;:!?")
            if candidate.lower().startswith(lower_match):
                return candidate

    return normalized_match


def _font_ascent(font) -> int:
    """Return the font's ascent in pixels, or 0 when unavailable.

    Used for per-chunk baseline alignment in the body draw loop: PIL's
    default anchor is ``"la"`` (ascender top), so mixing faces with different
    ascents on one line (gothic: EB Garamond + UnifrakturMaguntia) would
    float the bold phrase by ``body_ascent − bold_ascent`` pixels. The bitmap
    fallback doesn't expose ``getmetrics`` reliably; returning 0 gives every
    chunk the same offset instead of crashing.
    """
    try:
        return font.getmetrics()[0]
    except (AttributeError, OSError):
        return 0


def tokenize_quote(text: str, match_text: str) -> list[tuple[str, bool]]:
    normalized_match = resolve_display_match(text, match_text)
    if not normalized_match:
        return [(text, False)]
    match = _direct_match_pattern(normalized_match).search(text)
    if not match:
        return [(text, False)]

    idx = match.start()
    match_end = match.end()
    while match_end < len(text) and text[match_end] in '”"\'’.,;:!?':
        match_end += 1

    return [
        (text[:idx], False),
        (text[idx:match_end], True),
        (text[match_end:], False),
    ]


def wrap_styled_text(draw, segments, regular_font, bold_font, max_width, bold_stroke: int = 0):
    """Wrap a tokenised styled segment list into rendered lines.

    ``bold_stroke`` is the faux-bold stroke width applied to bold tokens
    (see ``_BOLD_STROKE_BY_THEME``); bold tokens are measured with it so the
    wrap matches what is painted. Spaces keep their natural advance.

    **A line may only break at whitespace.** ``tokenize_quote`` splits at the
    matched phrase, and that seam can fall mid-word (``"… (at a "`` /
    ``"quarter to seven"`` / ``") with …"``); breaking there would leave a
    dangling ``)`` or a stranded ``(``. Segments are therefore regrouped
    into *words* — non-space pieces glued across segment boundaries — and
    only whole words are placed. Each piece keeps its own style, so
    ``seven)`` still paints ``seven`` bold and ``)`` regular. A word wider
    than ``max_width`` gets a line of its own, intact.
    """
    # Memoised per font object: wrap_styled_text runs many times per render
    # with the same two fonts.
    space_widths: dict[int, int] = {}

    def space_width_for(font) -> int:
        font_id = id(font)
        width = space_widths.get(font_id)
        if width is None:
            bbox = draw.textbbox((0, 0), " ", font=font)
            width = bbox[2] - bbox[0]
            space_widths[font_id] = width
        return width

    # Pass 1: regroup the segments into a flat item stream. An item is either
    # a space token ``(" ", is_bold)`` or a word — a list of styled pieces
    # with no whitespace between them. ``open_word`` is True while the last
    # emitted piece was not followed by a space, so the next piece (even one
    # from a differently-styled segment) extends that word instead of
    # starting a new one.
    items: list = []
    open_word = False
    for text, is_bold in segments:
        parts = text.split(" ")
        for i, part in enumerate(parts):
            if part:
                if open_word:
                    items[-1].append((part, is_bold))
                else:
                    items.append([(part, is_bold)])
                open_word = True
            if i < len(parts) - 1:
                items.append((" ", is_bold))
                open_word = False

    # Pass 2: place whole words, breaking only at the space tokens.
    lines = []
    current = []
    current_width = 0
    for item in items:
        if isinstance(item, tuple):
            _, is_bold = item
            font = bold_font if is_bold else regular_font
            space_width = space_width_for(font)
            if current and current_width + space_width > max_width:
                lines.append(current)
                current = []
                current_width = 0
            else:
                current.append(item)
                current_width += space_width
            continue

        word_width = 0
        for piece, is_bold in item:
            font = bold_font if is_bold else regular_font
            stroke = bold_stroke if is_bold else 0
            bbox = draw.textbbox((0, 0), piece, font=font, stroke_width=stroke)
            word_width += bbox[2] - bbox[0]
        if current and current_width + word_width > max_width:
            lines.append(current)
            current = []
            current_width = 0
        current.extend(item)
        current_width += word_width

    if current:
        lines.append(current)
    return lines


def wrap_text(draw, text, font, max_width):
    words = text.split()
    lines = []
    current = []
    for word in words:
        trial = " ".join(current + [word])
        bbox = draw.textbbox((0, 0), trial, font=font)
        if bbox[2] - bbox[0] <= max_width:
            current.append(word)
        else:
            if current:
                lines.append(" ".join(current))
            current = [word]
    if current:
        lines.append(" ".join(current))
    return lines


def fit_quote(draw, text, match_text, max_width, max_height, font_max, font_min, line_height_mult, theme: str = "default"):
    segments = tokenize_quote(text, match_text)
    regular_candidates = theme_font_candidates(theme, "quote_regular")
    bold_candidates = theme_font_candidates(theme, "quote_bold")
    bold_stroke = _bold_stroke_for_theme(theme)
    for size in range(font_max, font_min - 1, -2):
        regular_font = load_font(regular_candidates, size=size)
        bold_font = load_font(bold_candidates, size=size)
        wrapped = wrap_styled_text(draw, segments, regular_font, bold_font, max_width, bold_stroke=bold_stroke)
        line_height = int(size * line_height_mult)
        total_height = len(wrapped) * line_height
        if total_height <= max_height:
            return regular_font, bold_font, wrapped, line_height, size
    regular_font = load_font(regular_candidates, size=font_min)
    bold_font = load_font(bold_candidates, size=font_min)
    wrapped = wrap_styled_text(draw, segments, regular_font, bold_font, max_width, bold_stroke=bold_stroke)
    return regular_font, bold_font, wrapped, int(font_min * line_height_mult), font_min


# A last line is a widow when it carries a single word or less than this
# fraction of the measure. ``fit_quote_balanced`` then re-wraps on a
# narrower measure (and, failing that, at slightly smaller sizes) without
# adding a line, so a word or two drop down to keep it company.
_WIDOW_MIN_FRACTION = 0.3
_BALANCE_MEASURES = (0.95, 0.90, 0.85, 0.80, 0.75, 0.70)


def _trim_line(line):
    """Drop the leading / trailing space tokens of a wrapped line."""
    start = 0
    while start < len(line) and line[start][0].strip() == "":
        start += 1
    end = len(line)
    while end > start and line[end - 1][0].strip() == "":
        end -= 1
    return line[start:end]


def _line_ink_width(draw, line, regular_font, bold_font, bold_stroke: int = 0) -> int:
    """Pixel width of a wrapped line at its natural spacing, bold tokens
    measured with the theme's faux-bold stroke (the way the renderer
    paints them) and spaces at their natural advance."""
    total = 0
    for chunk, is_bold in _trim_line(line):
        font = bold_font if is_bold else regular_font
        stroke = bold_stroke if (is_bold and chunk.strip()) else 0
        bbox = draw.textbbox((0, 0), chunk, font=font, stroke_width=stroke)
        total += bbox[2] - bbox[0]
    return total


def is_widow_line(draw, line, regular_font, bold_font, measure: int, bold_stroke: int = 0) -> bool:
    """True when ``line`` would strand a widow: one word, or less than
    ``_WIDOW_MIN_FRACTION`` of ``measure`` in ink."""
    trimmed = _trim_line(line)
    gaps = sum(1 for chunk, _ in trimmed if chunk == " ")
    if gaps == 0:
        return True
    return _line_ink_width(draw, trimmed, regular_font, bold_font, bold_stroke) < measure * _WIDOW_MIN_FRACTION


def _min_body_fill(draw, lines, regular_font, bold_font, bold_stroke: int, measure: int) -> float:
    """Fill ratio of the *shortest* non-last line against ``measure`` --
    the block's raggedness in one number (1.0 for a one-line block)."""
    if len(lines) < 2:
        return 1.0
    return min(_line_ink_width(draw, line, regular_font, bold_font, bold_stroke) for line in lines[:-1]) / measure


# ``fit_quote_balanced`` walks 2 px size steps below the largest fitting
# size, down to ``_BALANCE_MIN_SIZE_FRACTION`` of it (never below the
# layout's ``font_min``), before giving the widow up. It never accepts a
# re-wrap whose shortest body line is under ``_BALANCE_MIN_FILL`` of the
# measure (or shorter than the unbalanced wrap's shortest line, if that is
# already shorter): trading a one-word last line for a half-empty middle
# line is not a repair.
_BALANCE_MIN_SIZE_FRACTION = 0.8
_BALANCE_MIN_FILL = 0.55


def fit_quote_balanced(draw, text, match_text, max_width, max_height, font_max, font_min, line_height_mult, theme: str = "default"):
    """``fit_quote`` plus widow control for the literary layout.

    Returns ``(regular_font, bold_font, wrapped, line_height, size,
    wrap_width)``. When the fitted wrap's last line is a widow, the text is
    re-wrapped at the same size on narrower measures (``_BALANCE_MEASURES``)
    until the last line fills out without adding a line or opening a
    half-empty middle line (``_BALANCE_MIN_FILL``). Failing that, the search
    repeats at 2 px smaller sizes down to ``_BALANCE_MIN_SIZE_FRACTION``,
    accepting the first natural wrap with no widow or the first passing
    re-wrap; failing *that*, the original wrap is returned.

    ``wrap_width`` is the measure the lines were wrapped to; the caller must
    justify against it, not ``max_width``, or the slack distribution undoes
    the balancing. The left edge doesn't move, so a balanced block hangs a
    little short of the right margin.
    """
    regular_font, bold_font, wrapped, line_height, size = fit_quote(
        draw, text, match_text, max_width, max_height, font_max, font_min, line_height_mult, theme=theme
    )
    bold_stroke = _bold_stroke_for_theme(theme)
    if len(wrapped) < 2 or not is_widow_line(draw, wrapped[-1], regular_font, bold_font, max_width, bold_stroke):
        return regular_font, bold_font, wrapped, line_height, size, max_width

    segments = tokenize_quote(text, match_text)
    regular_candidates = theme_font_candidates(theme, "quote_regular")
    bold_candidates = theme_font_candidates(theme, "quote_bold")
    smallest = max(font_min, math.ceil(size * _BALANCE_MIN_SIZE_FRACTION))
    for step in range(0, (size - smallest) // 2 + 1):
        candidate_size = size - 2 * step
        if step == 0:
            regular, bold, base = regular_font, bold_font, wrapped
        else:
            regular = load_font(regular_candidates, size=candidate_size)
            bold = load_font(bold_candidates, size=candidate_size)
            base = wrap_styled_text(draw, segments, regular, bold, max_width, bold_stroke=bold_stroke)
        candidate_line_height = int(candidate_size * line_height_mult)
        if len(base) * candidate_line_height > max_height:
            continue
        fill_floor = min(_BALANCE_MIN_FILL, _min_body_fill(draw, base, regular, bold, bold_stroke, max_width))
        if step and not is_widow_line(draw, base[-1], regular, bold, max_width, bold_stroke):
            return regular, bold, base, candidate_line_height, candidate_size, max_width
        for factor in _BALANCE_MEASURES:
            candidate_width = int(max_width * factor)
            candidate = wrap_styled_text(draw, segments, regular, bold, candidate_width, bold_stroke=bold_stroke)
            if len(candidate) != len(base):
                break
            # Judge widow and fill against the candidate's own measure: the
            # eye compares the last line with the lines above it.
            if is_widow_line(draw, candidate[-1], regular, bold, candidate_width, bold_stroke):
                continue
            if _min_body_fill(draw, candidate, regular, bold, bold_stroke, candidate_width) < fill_floor:
                continue
            return regular, bold, candidate, candidate_line_height, candidate_size, candidate_width
    return regular_font, bold_font, wrapped, line_height, size, max_width


def line_width(draw, line, regular_font, bold_font):
    width = 0
    for chunk, is_bold in line:
        font = bold_font if is_bold else regular_font
        bbox = draw.textbbox((0, 0), chunk, font=font)
        width += bbox[2] - bbox[0]
    return width


def draw_text(draw, xy, text, font, fill):
    draw.text(xy, text, font=font, fill=fill)


def draw_faux_gray_text(image: Image.Image, xy, text, font, dark=(0, 0, 0), light=(255, 255, 255), pattern_offset=(0, 0)):
    mask = Image.new("L", image.size, 0)
    mask_draw = ImageDraw.Draw(mask)
    mask_draw.text(xy, text, font=font, fill=255)
    # Scan only the glyph bbox; pixels outside it are zero in the mask.
    bbox = mask.getbbox()
    if bbox is None:
        return
    x0, y0, x1, y1 = bbox
    px = image.load()
    mx = mask.load()
    ox, oy = pattern_offset
    for y in range(y0, y1):
        for x in range(x0, x1):
            if mx[x, y]:
                px[x, y] = dark if ((x + ox) + (y + oy)) % 2 == 0 else light


def draw_faux_3way_text(
    image: Image.Image,
    xy,
    text,
    font,
    ink_a,
    ink_b,
    ink_c,
    density_a: float,
    density_b: float,
    pattern_offset=(0, 0),
):
    """Paint ``text`` as a three-ink Bayer stipple.

    Partitions the 4×4 Bayer tile by two thresholds: cells below
    ``round(density_a*16)`` get ``ink_a``, below
    ``round((density_a + density_b)*16)`` ``ink_b``, the rest ``ink_c`` —
    the same partition as ``_fill_swatch_stipple_3way``, so text and the
    ``diags`` reference swatch share one hue. Used by ``chanbara``'s quote
    marks (burnt orange, R+Y+G 50/40/10).
    """
    mask = Image.new("L", image.size, 0)
    mask_draw = ImageDraw.Draw(mask)
    mask_draw.text(xy, text, font=font, fill=255)
    # Bound the scan to the inked glyph region (see draw_faux_gray_text).
    bbox = mask.getbbox()
    if bbox is None:
        return
    bx0, by0, bx1, by1 = bbox
    px = image.load()
    mx = mask.load()
    ox, oy = pattern_offset
    threshold_a = round(density_a * 16)
    threshold_b = round((density_a + density_b) * 16)
    for y in range(by0, by1):
        for x in range(bx0, bx1):
            if mx[x, y]:
                tile = BAYER_4x4[(y + oy) % 4][(x + ox) % 4]
                if tile < threshold_a:
                    px[x, y] = ink_a
                elif tile < threshold_b:
                    px[x, y] = ink_b
                else:
                    px[x, y] = ink_c


# Themes whose layout draws no oversized quote marks at all. Distinct from
# setting both ornament slots to ``page_bg`` (which still paints, invisibly on
# a flat ground but visibly on a washed one).
_THEMES_WITHOUT_ORNAMENT_MARKS: frozenset[str] = frozenset({"betweenus", "betweenus_dark"})


def _paint_ornament_mark(image, xy, text, font, theme: str, colors: dict, pattern_offset=(0, 0)) -> None:
    """Dispatch the oversized opening / closing quote-mark painter.

    Most themes paint via ``draw_faux_gray_text`` (a 50/50 checkerboard of
    ``ornament_dark`` / ``ornament_light``). ``chanbara`` uses a three-ink
    burnt-orange stipple (R+Y+G 50/40/10) so the marks read as weathered
    rust-orange rather than solid fire-engine red.
    """
    if theme in _THEMES_WITHOUT_ORNAMENT_MARKS:
        # The marks paint OUTSIDE the body rect, on the stippled paper, where
        # even a page_bg glyph would punch a ghost hole in the wash.
        return
    if theme == "chanbara":
        draw_faux_3way_text(
            image,
            xy,
            text,
            font=font,
            ink_a=SPECTRA6["red"],
            ink_b=SPECTRA6["yellow"],
            ink_c=SPECTRA6["green"],
            density_a=0.50,
            density_b=0.40,
            pattern_offset=pattern_offset,
        )
        return
    draw_faux_gray_text(
        image,
        xy,
        text,
        font=font,
        dark=colors["ornament_dark"],
        light=colors["ornament_light"],
        pattern_offset=pattern_offset,
    )


def draw_text_dithered(image: Image.Image, xy, text, font, dark, light, pattern_offset=(0, 0), light_density: float = 0.5, stroke_width: int = 0):
    """Paint ``text`` as a ``dark``/``light`` Bayer stipple within its bbox.

    Like ``draw_faux_gray_text`` but bbox-limited, which matters because body
    paths call it once per word chunk. Uses the same
    ``((x + ox) + (y + oy)) % 2`` checkerboard so the two paths interleave
    cleanly when a theme uses both.

    ``light_density`` picks the pattern:

    * ``0.5`` (default) — 50/50 checkerboard.
    * ``0.25`` — one ``light`` pixel per 2×2 tile (the ``draw_atomic_border``
      ground pattern).
    * Anything in ``(0.25, 0.5)`` — 4×4 ordered Bayer, ``light`` when
      ``BAYER_4x4[y % 4][x % 4] < round(light_density * 16)``. ``deco`` uses
      0.375 for a red-biased tangerine. The 0.25 and 0.5 branches must stay
      byte-identical for their existing callers.

    The mask is thresholded at ≥128, not every nonzero pixel: antialiased
    edge pixels painted at full ink would grow a 1 px halo that survives
    ``snap_image_to_palette`` as a hot fringe. ≥128 reproduces the silhouette
    plain ``draw.text`` + palette snap produces, so small text doesn't thicken.

    ``stroke_width`` is forwarded to the mask draw as a faux bold (``glacier``
    uses 1 px, since Iceland has no Bold); the bbox is padded by it so the
    thickened rim never clips.
    """
    draw = ImageDraw.Draw(image)
    bbox = draw.textbbox(xy, text, font=font, stroke_width=stroke_width)
    x0, y0, x1, y1 = bbox
    # Pad by a pixel for glyph stems that sit on the bbox edge, then clamp.
    pad = 1 + stroke_width
    x0 = max(0, x0 - pad)
    y0 = max(0, y0 - pad)
    x1 = min(image.width, x1 + pad)
    y1 = min(image.height, y1 + pad)
    if x1 <= x0 or y1 <= y0:
        return
    region_w = x1 - x0
    region_h = y1 - y0
    mask = Image.new("L", (region_w, region_h), 0)
    mask_draw = ImageDraw.Draw(mask)
    mask_draw.text((xy[0] - x0, xy[1] - y0), text, font=font, fill=255, stroke_width=stroke_width, stroke_fill=255)
    px = image.load()
    mx = mask.load()
    ox, oy = pattern_offset
    if light_density <= 0.25:
        # Sparse 1-in-4: light only where both axes are even in the
        # offset frame, so one light pixel per 2×2 tile (25% light).
        for y in range(region_h):
            ay = y + y0
            for x in range(region_w):
                if mx[x, y] >= 128:
                    ax = x + x0
                    px[ax, ay] = light if ((ax + ox) % 2 == 0 and (ay + oy) % 2 == 0) else dark
    elif light_density >= 0.5:
        for y in range(region_h):
            ay = y + y0
            for x in range(region_w):
                if mx[x, y] >= 128:
                    ax = x + x0
                    px[ax, ay] = dark if ((ax + ox) + (ay + oy)) % 2 == 0 else light
    else:
        # 4×4 ordered Bayer for intermediate densities (deco's 0.375).
        threshold = round(light_density * 16)
        for y in range(region_h):
            ay = y + y0
            for x in range(region_w):
                if mx[x, y] >= 128:
                    ax = x + x0
                    px[ax, ay] = light if BAYER_4x4[(ay + oy) % 4][(ax + ox) % 4] < threshold else dark



def draw_text_chroma_shift(
    image: Image.Image,
    xy,
    text: str,
    font,
    *,
    core=None,
    left=None,
    right=None,
    offset: int = 2,
    ground=None,
) -> None:
    """Paint ``text`` with its colour channels separated, as bled composite video.

    Synthesises a *defect* rather than a colour: the red and blue records of
    an analogue signal drifting out of registration.

    The pass order is load-bearing: the two chroma ghosts go down first at
    opposite horizontal offsets, then the core covers the middle, leaving a
    red fringe on one edge and a blue on the other. Core-first would put
    colour *over* the letterform and read as a coloured outline.

    Unlike ``pulp``'s misregistration (two plates offset one way — a printing
    fault), the separation here is symmetric about the glyph: a signal
    splitting, not a sheet slipping.

    ``ground`` restricts the ghosts to the inks they may overwrite, so a later
    line's fringe cannot eat an earlier line's core (as in
    ``paint_neon_mask``).
    """
    x, y = int(xy[0]), int(xy[1])
    if not text.strip():
        return
    box = font.getbbox(text)
    pad = offset + 2
    w = box[2] - box[0] + 2 * pad
    h = box[3] - box[1] + 2 * pad
    if w <= 0 or h <= 0:
        return
    mask = Image.new("L", (w, h), 0)
    ImageDraw.Draw(mask).text((pad - box[0], pad - box[1]), text, font=font, fill=255)
    mp = mask.load()
    px = image.load()
    width, height = image.size
    base_x, base_y = x + box[0] - pad, y + box[1] - pad

    for ink, dx in ((left, -offset), (right, offset)):
        if ink is None:
            continue
        for my in range(h):
            iy = base_y + my
            if not 0 <= iy < height:
                continue
            for mx in range(w):
                if mp[mx, my] <= 128:
                    continue
                ix = base_x + mx + dx
                if 0 <= ix < width and (ground is None or px[ix, iy] in ground):
                    px[ix, iy] = ink
    if core is not None:
        for my in range(h):
            iy = base_y + my
            if not 0 <= iy < height:
                continue
            for mx in range(w):
                if mp[mx, my] > 128:
                    ix = base_x + mx
                    if 0 <= ix < width:
                        px[ix, iy] = core
    mask.close()


def paint_neon_mask(
    image: Image.Image,
    mask: Image.Image,
    core,
    glow,
    *,
    radius: int = 5,
    gamma: float = 2.4,
    cap: float = 0.5,
    ground=None,
    tile=BAYER_4x4,
    glow_minor=None,
    glow_minor_share: float = 0.0,
    core_minor=None,
    core_minor_share: float = 0.0,
) -> None:
    """Paint a glyph/shape mask as a lit neon tube: solid ``core`` strokes
    wrapped in a ``glow`` bloom stippled onto the surrounding ground.

    Other synthesised tones mix two inks at a **constant** density; a bloom
    is one ink at a *falling* density. The halo is the mask blurred
    (``ImageFilter.GaussianBlur``) and read back as a per-pixel Bayer
    **density**, so the eye integrates a gradient out of a binary field.

    Tuning:

    * ``radius`` must stay TIGHT — comparable to the stroke width. A wide blur
      of a dense text line is a solid rectangle and reads as a coloured box.
    * ``gamma`` > 1 pulls the mid-tones down so the bloom decays over ~6-10 px
      instead of plateauing and cutting off at a visible edge.
    * ``cap`` keeps the densest ring below solid, so the halo always shows
      stipple texture; a saturated ring reads as a painted outline.

    ``mask`` must be an ``"L"`` image the same size as ``image`` (shared
    coordinates). Work is confined to the mask bbox grown by the blur pad.
    ``core=None`` paints only the halo.

    ``ground`` optionally restricts the halo to pixels currently holding one
    of those colours, so a later glow can't eat earlier cores or decoration.

    **Synthesised glows.** When the panel lacks the glow colour (``bakelite``'s
    amber), ``glow_minor`` / ``glow_minor_share`` mix a second ink at a
    constant ratio: the lit pixels are tile ranks ``0..n-1`` and the lowest
    ``glow_minor_share`` of that run take the minor ink, so density carries
    the glow and the ratio the hue, steady down the whole falloff.
    ``core_minor`` does the same for the stroke. The ratio must ride the
    density's own read — a second read of the same Bayer tile is perfectly
    correlated with the first, and keying the ratio on it makes the halo
    change hue as it fades (``pride`` uses the same rank partition).

    ``tile`` selects the ordered matrix: 4x4 suits a solid glow; a *split*
    glow wants ``BAYER_8x8``, because a short lit run can't hold a fraction
    accurately.
    """
    bbox = mask.getbbox()
    if bbox is None:
        return
    width, height = image.size
    pad = max(2, int(radius * 3))
    x0 = max(0, bbox[0] - pad)
    y0 = max(0, bbox[1] - pad)
    x1 = min(width, bbox[2] + pad)
    y1 = min(height, bbox[3] + pad)
    if x1 <= x0 or y1 <= y0:
        return
    halo = mask.filter(ImageFilter.GaussianBlur(radius))
    px = image.load()
    mp = mask.load()
    hp = halo.load()
    size = len(tile)
    levels = size * size
    core_cut = levels * core_minor_share
    for y in range(y0, y1):
        row = tile[y % size]
        for x in range(x0, x1):
            rank = row[x % size]
            if mp[x, y] > 128:
                if core is not None:
                    px[x, y] = core_minor if core_minor is not None and rank < core_cut else core
                continue
            level = hp[x, y] / 255.0
            if level <= 0.02:
                continue
            lit = min(cap, level ** gamma) * levels
            if rank < lit and (ground is None or px[x, y] in ground):
                px[x, y] = glow_minor if glow_minor is not None and rank < lit * glow_minor_share else glow


def _place_quote(draw: ImageDraw.ImageDraw, quote_row: dict, rect, *, theme: str,
                 font_max: int, font_min: int, line_height_mult: float) -> list:
    """Fit the quote into ``rect`` and position every styled chunk, ragged right.

    Returns ``(x, y, chunk, font, is_bold, width, line_height)`` per chunk, with
    ``y`` already baseline-aligned across the regular and bold faces, so a theme
    can draw the text, box the matched phrase, or mark each line from the same
    list. The fitting is ``fit_quote``'s; only the sizing is the theme's.
    """
    x0, y0, x1, y1 = rect
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    regular, bold, wrapped, line_height, _ = fit_quote(
        draw, display_quote, quote_row.get("matched_text") or "",
        x1 - x0, y1 - y0, font_max=font_max, font_min=font_min, line_height_mult=line_height_mult, theme=theme,
    )
    placed = []
    y = y0
    ascent = _font_ascent(regular)
    for line in wrapped:
        x = x0
        for chunk, is_bold in line:
            font = bold if is_bold else regular
            w = int(round(draw.textlength(chunk, font=font)))
            placed.append((x, y + (ascent - _font_ascent(font)), chunk, font, is_bold, w, line_height))
            x += w
        y += line_height
    return placed


def _paint_placed(draw: ImageDraw.ImageDraw, placed, ink, accent) -> None:
    """Draw ``_place_quote`` chunks in solid ``ink``, the matched phrase in ``accent``."""
    for x, y, chunk, font, is_bold, *_ in placed:
        draw.text((x, y), chunk, font=font, fill=accent if is_bold else ink)


def wrap_quote_into_masks(draw, size, quote_row: dict, rect, *, theme: str,
                         font_max: int = 34, font_min: int = 15,
                         line_height_mult: float = 1.4,
                         align: str = "center") -> tuple[Image.Image, Image.Image, int]:
    """Lay a quote out into two ``"L"`` masks — prose and matched phrase — and
    return them with the block's bottom y.

    The shared front half of every *lit* frame (``izakaya``, ``abyssal``,
    ``bakelite``): a bloom needs its mask before anything is painted, and the
    prose and the time phrase need separate masks so each takes its own
    colour and falloff. One shared mask gives the phrase the prose's glow;
    blooming per *chunk* double-exposes where two halos meet in a line. The
    caller makes its own ``paint_neon_mask`` calls.

    Lines are centred with leading/trailing whitespace chunks trimmed, and
    chunks are baseline-aligned via ``_font_ascent`` so the bold phrase sits
    on the prose's line even when the faces' ascents differ.

    ``align="left"`` flushes lines to the rect's left edge (``observation``'s
    ragged-right transcript).
    """
    x0, y0, x1, y1 = rect
    box_w, box_h = x1 - x0, y1 - y0
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    quote_font, quote_font_bold, wrapped, line_height, _ = fit_quote(
        draw, display_quote, quote_row.get("matched_text") or "", box_w, box_h,
        font_max=font_max, font_min=font_min, line_height_mult=line_height_mult, theme=theme,
    )
    prose = Image.new("L", size, 0)
    hot = Image.new("L", size, 0)
    prose_draw, hot_draw = ImageDraw.Draw(prose), ImageDraw.Draw(hot)

    y = y0 + max(0, (box_h - len(wrapped) * line_height) // 2)
    body_ascent = _font_ascent(quote_font)
    for line in wrapped:
        start, end = 0, len(line)
        while start < end and line[start][0].strip() == "":
            start += 1
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        segment = line[start:end]
        width_px = sum(draw.textbbox((0, 0), c, font=quote_font_bold if b else quote_font)[2]
                       for c, b in segment)
        x = x0 if align == "left" else x0 + max(0, (box_w - width_px) // 2)
        for chunk, is_bold in segment:
            font = quote_font_bold if is_bold else quote_font
            target = hot_draw if is_bold else prose_draw
            target.text((x, y + (body_ascent - _font_ascent(font))), chunk, font=font, fill=255)
            x += draw.textbbox((0, 0), chunk, font=font)[2]
        y += line_height
    return prose, hot, y


def paint_hatched_tone(
    image: Image.Image,
    rect: tuple[int, int, int, int],
    tone,
    angle_deg: float,
    spacing: float,
    ink,
    *,
    ground=None,
    phase: float = 0.0,
    max_duty: float = 0.85,
    gamma: float = 1.0,
) -> None:
    """Paint continuous tone as line-work — the engraver's alternative to the
    pixel stipple.

    Modulates the **weight** of a parallel line family under a tone field, at
    constant pitch, so the grey reads as *drawing* — intaglio's tone
    mechanism. Keep the pitch constant: tone-varying spacing reads as
    scanlines with noise.

    ``tone`` is a callable ``(x, y) -> float`` in 0..1 in panel coordinates.
    Per pixel, ``u = -x*sin(a) + y*cos(a) + phase``; the pixel takes ``ink``
    when its distance to the nearest line centre is under half the pitch
    times the duty ``min(max_duty, tone**gamma)``. Continuous coordinates
    give any angle even weight.

    Cross-hatching is a second call at a second angle with a shadows-only
    tone (``max(0, t - 0.5) * 2``), as an engraver adds the second family.

    ``max_duty`` is the analogue of ``paint_neon_mask``'s ``cap``: even tone
    1.0 shows paper between the lines, or the hatch collapses to a flat fill.
    ``ground`` restricts painting to pixels holding one of those colours.

    Keep ``spacing >= 4`` and the angle off 0/45/90 degrees, or the family
    beats against the pixel lattice into thick-thin banding.
    """
    a = math.radians(angle_deg)
    sin_a, cos_a = math.sin(a), math.cos(a)
    x0, y0, x1, y1 = rect
    x0, y0 = max(0, x0), max(0, y0)
    x1, y1 = min(image.size[0], x1), min(image.size[1], y1)
    px = image.load()
    half = 0.5 * spacing
    for y in range(y0, y1):
        for x in range(x0, x1):
            t = tone(x, y)
            if t <= 0.0:
                continue
            duty = min(max_duty, t ** gamma if gamma != 1.0 else t)
            u = -x * sin_a + y * cos_a + phase
            delta = abs(u - round(u / spacing) * spacing)
            if delta < half * duty and (ground is None or px[x, y] in ground):
                px[x, y] = ink


def paint_relief_mask(
    image: Image.Image,
    mask: Image.Image,
    *,
    highlight,
    shadow,
    face=None,
    face_minor=None,
    face_minor_share: float = 0.0,
    radius: int = 3,
    strength: float = 4.0,
    cap: float = 0.65,
    ground=None,
    tile=BAYER_8x8,
    shade_face: bool = True,
    contact=None,
    contact_cut: int = 55,
) -> None:
    """Paint a glyph/shape mask as a *raised* (or sunken) surface lit from the
    upper left — the inverse of ``paint_neon_mask``: light falling ON the mask
    instead of radiating from it.

    ``shade_face=True`` (default) lights the mask's own surface — right for
    *large* shapes (a bead, a bolt head). ``False`` confines the lighting to
    the *exterior* — solid face, rim light outside the upper-left edge, core
    shadow outside the lower-right — which thin letterforms need: shading a
    2-3 px stroke's own face leaves no face, and the glyph decays to a grey
    ghost.

    The blurred mask is read as a height field; its gradient against the
    upper-left house light (as ``vitrail`` / ``kanagawa`` use) decides which
    side of each edge is lit: faces toward the light take ``highlight`` at a
    density proportional to slope, faces away take ``shadow``. ``radius`` is
    the die's fillet, ``strength`` the relief depth, and ``cap`` keeps even
    the steepest face stippled (a saturated face reads as an outline).

    ``face`` optionally fills the interior first, with ``face_minor`` /
    ``face_minor_share`` mixing a second ink on the tile's own rank read (the
    ``paint_neon_mask`` split-band rule). ``face=None`` for shapes an earlier
    pass already filled.

    ``contact`` optionally lays a solid ring of that ink in the exterior band
    where the halo is at least ``contact_cut``, *under* the directional pass —
    the ambient-occlusion crease round a raised form. Lambert alone gives
    near-zero shading on the edges lying along the light direction, and on a
    mottled ground the letterform bleeds into the plate there. The highlight
    paints over the ring afterwards. Raising ``contact_cut`` narrows it;
    ``contact=None`` (default) disables it.

    **Set ``contact_cut`` from the halo profile of a *stroke*, not of a large
    shape.** One pixel outside a 3 px stem a radius-2 halo is ~93 and two
    pixels out ~57, versus ~150 just outside a broad edge; a cut tuned on a
    broad edge (96) creases a glyph nowhere, silently. The default suits a
    radius-2 blur on body text.

    Swap ``highlight`` and ``shadow`` for deboss. ``ground`` restricts
    *exterior* writes (contact ring included) so relief never eats
    neighbouring decoration; interior pixels belong to the mask.
    """
    bbox = mask.getbbox()
    if bbox is None:
        return
    width, height = image.size
    pad = max(2, radius * 3)
    x0 = max(1, bbox[0] - pad)
    y0 = max(1, bbox[1] - pad)
    x1 = min(width - 1, bbox[2] + pad)
    y1 = min(height - 1, bbox[3] + pad)
    if x1 <= x0 or y1 <= y0:
        return
    halo = mask.filter(ImageFilter.GaussianBlur(radius))
    px = image.load()
    mp = mask.load()
    hp = halo.load()
    size = len(tile)
    levels = size * size
    face_cut = levels * face_minor_share
    inv = 1.0 / 510.0  # central difference over 2 px of an 8-bit field
    for y in range(y0, y1):
        row = tile[y % size]
        for x in range(x0, x1):
            rank = row[x % size]
            inside = mp[x, y] > 128
            if inside and face is not None:
                px[x, y] = face_minor if face_minor is not None and rank < face_cut else face
            if inside and not shade_face:
                continue
            exterior_ok = inside or ground is None or px[x, y] in ground
            if contact is not None and not inside and exterior_ok and hp[x, y] >= contact_cut:
                px[x, y] = contact
            gx = (hp[x + 1, y] - hp[x - 1, y]) * inv
            gy = (hp[x, y + 1] - hp[x, y - 1]) * inv
            shade = (gx + gy) * 0.7071  # Lambert term against upper-left light
            lit = min(cap, abs(shade) * strength) * levels
            if rank >= lit:
                continue
            if not exterior_ok:
                continue
            px[x, y] = highlight if shade > 0 else shadow


# Sobel slopes for ``shade_height_field``, read as +d/dx and +d/dy. The Y
# weights look upside down and the X weights do not, because
# ``ImageFilter.Kernel`` applies its rows in reverse order but its columns as
# written — fenced by ``TestShadeHeightField``, since a flipped sign silently
# moves the light to the wrong corner. ``scale=2`` reports a unit ramp as 4
# grey levels: quarter-level slope resolution keeps a soft dome from
# terracing, at the cost of clipping slopes steeper than 32 levels per pixel.
_SOBEL_X = ImageFilter.Kernel((3, 3), (-1, 0, 1, -2, 0, 2, -1, 0, 1), scale=2, offset=128)
_SOBEL_Y = ImageFilter.Kernel((3, 3), (1, 2, 1, 0, 0, 0, -1, -2, -1), scale=2, offset=128)
_HEIGHT_FIELD_LUTS: dict = {}


def _height_field_lut(light, relief: float, ambient: float, diffuse: float,
                      specular: float, shininess: float) -> bytes:
    """A 65536-entry ``(gx << 8 | gy) → tone`` table: Blinn-Phong for every
    slope pair the two Sobel images can report. Memoised per parameter set so
    the per-pixel pass is a plain table lookup."""
    key = (tuple(light), relief, ambient, diffuse, specular, shininess)
    cached = _HEIGHT_FIELD_LUTS.get(key)
    if cached is not None:
        return cached
    lx, ly, lz = light
    norm = math.sqrt(lx * lx + ly * ly + lz * lz)
    lx, ly, lz = lx / norm, ly / norm, lz / norm
    hx, hy, hz = lx, ly, lz + 1.0                       # Blinn half-vector, viewer on +z
    hn = math.sqrt(hx * hx + hy * hy + hz * hz)
    hx, hy, hz = hx / hn, hy / hn, hz / hn
    out = bytearray(65536)
    for a in range(256):
        nx = -(a - 128) * relief
        for b in range(256):
            ny = -(b - 128) * relief
            inv = 1.0 / math.sqrt(nx * nx + ny * ny + 1.0)
            ndl = (nx * lx + ny * ly + lz) * inv
            ndh = (nx * hx + ny * hy + hz) * inv
            tone = ambient + diffuse * max(0.0, ndl)
            if ndh > 0.0:
                tone += specular * ndh ** shininess
            out[a << 8 | b] = max(0, min(255, int(tone * 255 + 0.5)))
    table = bytes(out)
    _HEIGHT_FIELD_LUTS[key] = table
    return table


def shade_height_field(
    height: Image.Image,
    *,
    light=(-0.55, -0.62, 0.56),
    relief: float = 0.025,
    ambient: float = 0.1,
    diffuse: float = 0.85,
    specular: float = 0.7,
    shininess: float = 28.0,
) -> Image.Image:
    """Render an ``"L"`` height field as a lit continuous-tone surface.

    A *3-D render* rather than a stipple rule (the eighth tone axis in
    ``docs/spectra6_color_recipes.md``): every pixel gets a normal, is shaded
    Blinn-Phong under one light, and the result stays continuous tone for
    error diffusion to carry onto the inks — an airbrush, which is what
    ``biomech``'s smooth gradients and specular glints need.

    Unlike ``paint_relief_mask`` (lights a flat mask's blurred edge and
    writes ink per pixel in Python), this takes a caller-built height field
    (blurred shapes unioned with ``ImageChops.lighter``, carved with
    ``subtract``) and returns *tone*, leaving inks to
    ``dither_image_to_palette``. The per-pixel work is C-speed: two 3x3 Sobel
    ``ImageFilter.Kernel`` passes (``offset=128`` keeps the sign) and one
    lookup into a memoised 65536-entry table.

    ``light`` is screen-space (x right, y down, z toward the viewer), upper
    left by convention. ``relief`` converts height per pixel into normal tilt,
    per Sobel level (four per unit slope); a field blurred at radius *r* peaks
    near ``255/(2r)``, so the default turns a radius-5 dome through most of a
    hemisphere. A flat pixel shades to ``ambient + diffuse * lz`` — mid-grey,
    not black; darkening recesses (multiply by the height) is the caller's
    choice.
    """
    gx = height.filter(_SOBEL_X).tobytes()
    gy = height.filter(_SOBEL_Y).tobytes()
    lut = _height_field_lut(tuple(light), relief, ambient, diffuse, specular, shininess)
    tone = bytes(lut[a << 8 | b] for a, b in zip(gx, gy))
    return Image.frombytes("L", height.size, tone)


def _flow_stroke_hash(cx: int, cy: int, salt: int) -> float:
    """Deterministic 0..1 value per stroke cell — ``_bakelite_grain``'s hash
    with a ``salt`` term so multiple passes over one canvas decorrelate."""
    h = (cx * 0x1F1F1F1F) ^ (cy * 0x2545F491) ^ (salt * 0x9E3779B9)
    h = ((h ^ (h >> 13)) * 0x27D4EB2D) & 0xFFFFFFFF
    return ((h ^ (h >> 15)) & 0xFFFF) / 65535.0


def paint_flow_strokes(
    image: Image.Image,
    rect: tuple[int, int, int, int],
    direction,
    ink_at,
    *,
    cell: int = 11,
    length: int = 18,
    width: int = 2,
    steps: int = 3,
    ground=None,
    salt: int = 0,
) -> None:
    """The painterly pass: short streamline strokes advected through a
    caller-supplied direction field, each stroke a single ink chosen at its
    origin.

    Fakes *facture* at stroke scale where the stipples fake tone at pixel
    scale: partial coverage of blue strokes over black reads as brushed night
    water because the marks are long (15-25 px) and coherent enough to read
    direction at panel distance. That needs field wavelengths well above the
    placement pitch (>= 80 px against a 10-13 px ``cell`` in ``nocturne``);
    a faster-turning field shreds the strokes back into noise.

    One candidate per ``cell x cell`` square inside ``rect``; the origin is
    jittered by an integer position hash (never ``random`` — frames must
    re-render byte-identically), and the same hash is passed to
    ``ink_at(x, y, r)`` as ``r``. ``ink_at`` returning ``None`` skips the
    stroke — that is how the caller carries density and tone. Each stroke is
    integrated along the field in ``steps`` segments of ``length/steps``, so
    it bends with the field.

    Strokes render through a scratch mask and land only on ``ground`` pixels
    (the ``paint_neon_mask`` discipline), so a pass never eats earlier cores
    or text. ``salt`` decorrelates multiple passes on one canvas.
    """
    x0, y0, x1, y1 = rect
    scratch = Image.new("L", image.size, 0)
    scratch_draw = ImageDraw.Draw(scratch)
    sp = scratch.load()
    px = image.load()
    w, h = image.size
    seg = max(1.0, length / steps)
    for cy in range(y0, y1, cell):
        for cx in range(x0, x1, cell):
            r = _flow_stroke_hash(cx, cy, salt)
            jx = _flow_stroke_hash(cx, cy, salt ^ 0x5BD1E995)
            jy = _flow_stroke_hash(cx, cy, salt ^ 0x85EBCA6B)
            ox = cx + jx * cell
            oy = cy + jy * cell
            ink = ink_at(int(ox), int(oy), r)
            if ink is None:
                continue
            points = [(ox, oy)]
            sx, sy = ox, oy
            reach = seg * (0.6 + 0.4 * r)
            for _ in range(steps):
                ang = direction(sx, sy)
                sx += math.cos(ang) * reach
                sy += math.sin(ang) * reach
                points.append((sx, sy))
            scratch_draw.line(points, fill=255, width=width)
            bx0 = max(0, int(min(p[0] for p in points)) - width)
            by0 = max(0, int(min(p[1] for p in points)) - width)
            bx1 = min(w - 1, int(max(p[0] for p in points)) + width)
            by1 = min(h - 1, int(max(p[1] for p in points)) + width)
            for yy in range(by0, by1 + 1):
                for xx in range(bx0, bx1 + 1):
                    if sp[xx, yy] == 0:
                        continue
                    if ground is None or px[xx, yy] in ground:
                        px[xx, yy] = ink
                    sp[xx, yy] = 0


def _draw_text_body(image: Image.Image, draw, xy, text, font, fill, theme: str):
    """Draw body / attribution text, rerouting per-theme fills to stipples.

    Only the listed (theme, fill) pairs are stippled; everything else is a
    solid ``draw.text``. Most reroutes treat a THEMES slot as a *sentinel* —
    the slot names a native ink and this seam paints the synthesised mix:

    * ``nightvision`` — green body → G+W 1:1 mint; yellow phrase → Y+G
      5/8:3/8 lime.
    * ``grimoire`` — red phrase → B+W sky blue (matches its quote marks).
    * ``gothic`` — red phrase → R+Y 1:1 amber; ``betweenus_dark`` — yellow
      phrase → the same amber.
    * ``deco`` / ``grimdark`` — red phrase → R+Y 5/8:3/8 tangerine (deco's
      matches ``draw_deco_border``'s post-pass threshold).
    * ``blueprint`` / ``scholar`` — red phrase → R+K maroon; ``mucha`` /
      ``fillmore`` — red body → R+K maroon.
    * ``illuminated`` / ``risograph`` — blue phrase → R+B violet.
    * ``bauhaus`` — blue phrase → B+K navy.
    * ``glacier`` — green phrase → G+B 5/8:3/8 teal plus a faux-bold stroke.
    * ``herbarium`` — green phrase → G+K forest green; ``mucha`` — green
      phrase → G+B cyan.
    * ``firmament`` — yellow phrase → Y+W cream; ``anna_atkins`` — yellow
      phrase → B+W sky blue, and every glyph gets a black halo first.

    Border ornaments paint outside this seam, so they keep solid inks.
    """
    if theme == "anna_atkins" and text.strip():
        # anna_atkins draws text straight on the dithered plate, so stamp a
        # thin black outline behind each glyph first; the real glyph is drawn
        # on top by the branches below, inside the black ring.
        draw.text(xy, text, font=font, fill=SPECTRA6["black"], stroke_width=2, stroke_fill=SPECTRA6["black"])
    if theme == "nightvision" and fill == SPECTRA6["green"]:
        draw_text_dithered(image, xy, text, font, dark=fill, light=SPECTRA6["white"])
    elif theme == "grimoire" and fill == SPECTRA6["red"]:
        # Sky blue (B+W 1:1), the recipe this theme's quote marks use, so the
        # phrase and ornaments share one moon-silver register. The red
        # ``accent`` is a sentinel and is never painted — hence ``dark=blue``
        # rather than ``dark=fill`` — which keeps the phrase clear of the
        # border's red pentagrams and sigils. (Solid white left it
        # undifferentiated from the body; a 3/4-red mix read dim.)
        draw_text_dithered(image, xy, text, font, dark=SPECTRA6["blue"], light=SPECTRA6["white"])
    elif theme == "gothic" and fill == SPECTRA6["red"]:
        # Amber (R+Y 1:1): warm candle-flame on black, clear of the red
        # border ornaments.
        draw_text_dithered(image, xy, text, font, dark=fill, light=SPECTRA6["yellow"])
    elif theme == "deco" and fill == SPECTRA6["red"]:
        # 3/8 yellow on 5/8 red on BAYER_4x4; must match
        # ``draw_deco_border``'s post-pass threshold so phrase and border
        # share one tangerine.
        draw_text_dithered(image, xy, text, font, dark=fill, light=SPECTRA6["yellow"], light_density=0.375)
    elif theme in ("blueprint", "scholar") and fill == SPECTRA6["red"]:
        # Maroon (R+K 1:1): blueprint's red pencil pressed hard, scholar's
        # aged red-lead annotation. Border marks stay solid red.
        draw_text_dithered(image, xy, text, font, dark=fill, light=SPECTRA6["black"])
    elif theme == "illuminated" and fill == SPECTRA6["blue"]:
        # Violet (R+B 1:1) — Tyrian purple, in the same register as the
        # border's R+B+K plum cabochons. The red body never hits this branch.
        draw_text_dithered(image, xy, text, font, dark=SPECTRA6["red"], light=SPECTRA6["blue"])
    elif theme == "glacier" and fill == SPECTRA6["green"]:
        # Teal (G+B 5/8:3/8, Bayer threshold 6/16). 50/50 cyan read too close
        # to the blue body and solid green read muddy; the green bias pulls
        # the phrase off the body while staying cool. Plus a
        # ``stroke_width=1`` faux bold, since Iceland ships only Regular and
        # hue alone doesn't carry the differentiation.
        draw_text_dithered(image, xy, text, font, dark=fill, light=SPECTRA6["blue"], light_density=0.375, stroke_width=_bold_stroke_for_theme(theme))
    elif theme == "risograph" and fill == SPECTRA6["blue"]:
        # Violet (R+B 1:1) — the riso red-over-blue overprint. Keeps the
        # theme's no-black invariant by construction.
        draw_text_dithered(image, xy, text, font, dark=SPECTRA6["red"], light=fill)
    elif theme == "bauhaus" and fill == SPECTRA6["blue"]:
        # Navy (B+K 1:1), a deeper variant of the border's solid blue square
        # so all three primaries still show solid in the border.
        draw_text_dithered(image, xy, text, font, dark=fill, light=SPECTRA6["black"])
    elif theme == "nightvision" and fill == SPECTRA6["yellow"]:
        # Lime (Y+G 5/8:3/8, density 0.375): yellow-biased because a 50/50
        # Y+G reads washed-out olive — the HUD readout glow.
        draw_text_dithered(image, xy, text, font, dark=fill, light=SPECTRA6["green"], light_density=0.375)
    elif theme == "herbarium" and fill == SPECTRA6["green"]:
        # Forest green (G+K 1:1, the recipes doc's dark green): pressed plant
        # material against the cream ground, distinct from the border's Y+G
        # olive leaf.
        draw_text_dithered(image, xy, text, font, dark=fill, light=SPECTRA6["black"])
    elif theme in ("mucha", "fillmore") and fill == SPECTRA6["red"]:
        # Maroon (R+K 1:1). Both themes keep the red sentinel in ``text`` so
        # every body path hits this seam:
        #
        # * ``mucha`` — a synthesised body colour, the oxblood of period
        #   poster lettering; its green phrase lands on cyan below.
        # * ``fillmore`` — tames the fatiguing red-on-yellow body, as red ink
        #   darkened on yellow stock. The blue phrase and blob primaries stay
        #   solid, so all six inks still appear.
        draw_text_dithered(image, xy, text, font, dark=fill, light=SPECTRA6["black"])
    elif theme == "mucha" and fill == SPECTRA6["green"]:
        # Cyan (G+B 1:1): a cool accent against the warm maroon body.
        draw_text_dithered(image, xy, text, font, dark=fill, light=SPECTRA6["blue"])
    elif theme == "firmament" and fill == SPECTRA6["yellow"]:
        # Cream (Y+W 1:1): gilt constellation labels on the navy ground.
        # The white body falls through to the ``else`` branch.
        draw_text_dithered(image, xy, text, font, dark=fill, light=SPECTRA6["white"])
    elif theme == "grimdark" and fill == SPECTRA6["red"]:
        # Forge amber (R+Y 5/8:3/8 on BAYER_4x4, as ``deco``): molten metal on
        # the bulkhead, tied to the gold trim. 50/50 would read washed-out
        # because yellow out-luminates red.
        draw_text_dithered(image, xy, text, font, dark=fill, light=SPECTRA6["yellow"], light_density=0.375)
    elif theme == "anna_atkins" and fill == SPECTRA6["yellow"]:
        # Yellow sentinel → B+W sky blue (the ``glacier`` recipe): a ghostly
        # cyanotype element distinct from the crisp white body. The yellow
        # shows literally only in the debug banner, outside this seam.
        draw_text_dithered(image, xy, text, font, dark=SPECTRA6["blue"], light=SPECTRA6["white"])
    elif theme == "betweenus_dark" and fill == SPECTRA6["yellow"]:
        # Yellow sentinel → R+Y 1:1 amber, the apricot the app's dark
        # ``want`` (#DFA07C) lands on. On black the mix's brightness is the
        # point; the recipes doc's washed-out caveat is about white grounds.
        draw_text_dithered(image, xy, text, font, dark=SPECTRA6["red"], light=SPECTRA6["yellow"])
    else:
        draw.text(xy, text, font=font, fill=fill)


def _paint_theme_border(image: Image.Image, theme: str, colors: dict) -> None:
    """Dispatch to the decorative-border helper registered for ``theme``.

    The single seam ``render`` and ``render_source_card`` share: a new
    border registers in ``_BORDER_PAINTERS`` (and, if it paints in the
    top-right, ``_DEBUG_LABEL_RIGHT_INSET``).
    """
    painter = _BORDER_PAINTERS.get(theme)
    if painter is not None:
        painter(image, colors)


def draw_bauhaus_border(image: Image.Image, colors: dict) -> None:
    """Paint a Bauhaus-inspired geometric frame around the canvas margin.

    A thin black outer rectangle plus four corner accents in the Bauhaus
    primaries: red circles (TL + BR), a blue square (TR) and a yellow
    triangle (BL).

    Yellow is hardcoded from ``SPECTRA6`` (as ``draw_comic_corner_stripes``
    and ``draw_marker_border`` do) because the bauhaus ``THEMES`` entry has
    only three accent slots; adding a fourth would re-pin every cross-theme
    invariant test for one glyph.

    The corner shapes sit tangent to the canvas edges and overlap the
    outer rectangle's corners. None reaches past x=30, well outside the
    quote block (``SIDE_MARGIN + 18`` is the innermost text feature).
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    frame_inset = 14
    frame_color = colors["text"]
    accent_color = colors["accent"]
    ornament_color = colors["ornament_dark"]
    yellow_primary = SPECTRA6["yellow"]

    # Outer rectangle outline.
    draw.rectangle(
        (frame_inset, frame_inset, width - 1 - frame_inset, height - 1 - frame_inset),
        outline=frame_color,
        width=2,
    )

    corner_size = 22
    corner_margin = 6
    # Top-left: red filled circle.
    draw.ellipse(
        (corner_margin, corner_margin,
         corner_margin + corner_size, corner_margin + corner_size),
        fill=ornament_color,
    )
    # Top-right: blue filled square.
    draw.rectangle(
        (width - corner_margin - corner_size, corner_margin,
         width - corner_margin, corner_margin + corner_size),
        fill=accent_color,
    )
    # Bottom-left: yellow filled triangle, right angle at the corner and
    # hypotenuse rising to the top-right, so it points in at the quote.
    bl_left = corner_margin
    bl_top = height - corner_margin - corner_size
    bl_right = corner_margin + corner_size
    bl_bottom = height - corner_margin
    draw.polygon(
        [(bl_left, bl_bottom), (bl_right, bl_bottom), (bl_right, bl_top)],
        fill=yellow_primary,
    )
    # Bottom-right: red filled circle, mirroring the top-left and completing
    # the diagonal colour balance.
    draw.ellipse(
        (width - corner_margin - corner_size, height - corner_margin - corner_size,
         width - corner_margin, height - corner_margin),
        fill=ornament_color,
    )

    # Concentric outline ring around the two corner circles (a Kandinsky
    # concentric-circle study), radius corner_size/2 + 6 in the frame
    # colour; only a quarter-arc stays on canvas. Pure outline, clear of
    # the filled discs.
    half = corner_size // 2
    ring_pad = 6
    for ccx, ccy in (
        (corner_margin + half, corner_margin + half),
        (width - corner_margin - half, height - corner_margin - half),
    ):
        draw.ellipse(
            (ccx - half - ring_pad, ccy - half - ring_pad,
             ccx + half + ring_pad, ccy + half + ring_pad),
            outline=frame_color,
            width=1,
        )

    # Off-centre primary semicircles bulging inward from the top and
    # bottom frames — the playful punctuation of a Bauhaus poster edge.
    # Deliberately set away from the frame midpoints (x=0.68w / 0.32w,
    # never x=width//2) so the composition stays asymmetric and the
    # sampled top/bottom frame-midpoint pixels keep their frame colour.
    semi_r = 14
    top_sx = int(width * 0.68)
    draw.pieslice(
        (top_sx - semi_r, frame_inset - semi_r, top_sx + semi_r, frame_inset + semi_r),
        start=0, end=180, fill=accent_color,
    )
    bot_sx = int(width * 0.32)
    bot_y = height - 1 - frame_inset
    draw.pieslice(
        (bot_sx - semi_r, bot_y - semi_r, bot_sx + semi_r, bot_y + semi_r),
        start=180, end=360, fill=yellow_primary,
    )

    # Two floating primary elements drifting in the otherwise-empty side
    # margins (x≈32 / width-32, well clear of the dense-layout text column
    # at x 60–740) — a small red square on the left and a small blue disc
    # on the right, echoing the corner shapes' forms. Vertically offset
    # from the side-frame midpoints (y=0.34h / 0.66h, never y=height//2)
    # so the sampled left/right frame-midpoint pixels stay frame-coloured.
    sq = 12
    lx, ly = 32, int(height * 0.34)
    draw.rectangle((lx - sq // 2, ly - sq // 2, lx + sq // 2, ly + sq // 2), fill=ornament_color)
    rcx, rcy = width - 32, int(height * 0.66)
    draw.ellipse((rcx - 6, rcy - 6, rcx + 6, rcy + 6), fill=accent_color)


def draw_risograph_border(image: Image.Image, colors: dict, clear_rect: tuple[int, int, int, int] | None = None) -> None:
    """Paint a lively risograph-inspired print frame.

    ``clear_rect`` is the body-text rectangle ``render`` threads through
    (see ``_CLEAR_RECT_PADS``). When given, the bars and overprint circles
    are painted first, then the rect is knocked back to the paper and
    framed with a misregistered red-over-blue double rule, so the quote
    sits on a pasted-up label with the print-test shapes behind it.

    The look is deliberate misregistration: a primary frame in the text
    colour, a shifted duplicate in the accent colour, crop / register
    marks and a few chunky side blocks, like a print test sheet.

    The shifted registration crosses are painted in a sentinel and
    bbox-post-passed through a 3-way Bayer partition into lavender
    (R + B + W at ~1/3 each), the paler tone where two plates wash
    together. Lavender pulls no black, so the theme's no-black-ink
    invariant holds.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    base = colors["text"]
    accent = colors["accent"]
    shadow = colors.get("subtle", base)

    outer = 20
    inner = 34
    dx, dy = 5, 3

    # Skip any frame rule that would invert (y1 < y0) on a small preview canvas:
    # the curator /api/preview path renders below the native 800×480, and an
    # inverted box raises ValueError in PIL's draw_rectangle.
    if width > 2 * outer and height > 2 * outer:
        draw.rectangle((outer + dx, outer + dy, width - 1 - outer + dx, height - 1 - outer + dy), outline=accent, width=2)
        draw.rectangle((outer, outer, width - 1 - outer, height - 1 - outer), outline=base, width=2)
    if width > 2 * inner and height > 2 * inner:
        draw.rectangle((inner, inner, width - 1 - inner, height - 1 - inner), outline=shadow, width=1)

    # Chunky print bars.
    draw.rectangle((42, 54, 74, 170), fill=accent)
    draw.rectangle((56, 68, 88, 184), outline=base, width=2)
    draw.rectangle((width - 88, height - 184, width - 56, height - 68), fill=base)
    draw.rectangle((width - 102, height - 198, width - 70, height - 82), outline=accent, width=2)

    # Overprint-style circles.
    draw.ellipse((width - 118, 58, width - 54, 122), outline=base, width=2)
    draw.ellipse((width - 112 + dx, 64 + dy, width - 48 + dx, 128 + dy), outline=accent, width=2)
    draw.ellipse((54, height - 128, 118, height - 64), outline=accent, width=2)
    draw.ellipse((48 + dx, height - 122 + dy, 112 + dx, height - 58 + dy), outline=base, width=2)

    # Registration / crop marks.
    def cross(cx: int, cy: int, color: tuple[int, int, int]) -> None:
        draw.line((cx - 10, cy, cx + 10, cy), fill=color, width=1)
        draw.line((cx, cy - 10, cx, cy + 10), fill=color, width=1)
        draw.ellipse((cx - 4, cy - 4, cx + 4, cy + 4), outline=color, width=1)

    marks = [
        (outer, outer),
        (width - outer, outer),
        (outer, height - outer),
        (width - outer, height - outer),
    ]
    lavender_sentinel = (1, 1, 1)
    for cx, cy in marks:
        cross(cx, cy, base)
        cross(cx + dx, cy + dy, lavender_sentinel)

    # 3-way Bayer post-pass on the sentinel crosses: cells 0-4 → red,
    # cells 5-9 → blue, cells 10-15 → white (~1/3 each, the documented
    # lavender R+B+W recipe). Bbox-scoped per cross.
    pixels = image.load()
    ink_red = SPECTRA6["red"]
    ink_blue = SPECTRA6["blue"]
    ink_white = SPECTRA6["white"]
    for cx, cy in marks:
        sx, sy = cx + dx, cy + dy
        x0 = max(0, sx - 12)
        y0 = max(0, sy - 12)
        x1 = min(width - 1, sx + 12)
        y1 = min(height - 1, sy + 12)
        for py in range(y0, y1 + 1):
            row = BAYER_4x4[py & 3]
            for px in range(x0, x1 + 1):
                if pixels[px, py] == lavender_sentinel:
                    cell = row[px & 3]
                    if cell < 5:
                        pixels[px, py] = ink_red
                    elif cell < 10:
                        pixels[px, py] = ink_blue
                    else:
                        pixels[px, py] = ink_white

    # Colour-registration bar centred in the top margin: the ink-density
    # strip a print shop runs at the sheet edge. Red, blue, lavender
    # (sentinel + post-pass, as for the crosses), red, blue. It sits in
    # the band between the shifted frame's top rule (y=23-24) and the
    # inner rule (y=34), clear of the y=22 gap the illuminated
    # cross-gating test samples at (400, 22). No black ink.
    swatch_w = 22
    swatch_h = 8
    swatch_gap = 4
    bar_kinds = ("red", "blue", "lavender", "red", "blue")
    bar_total = len(bar_kinds) * swatch_w + (len(bar_kinds) - 1) * swatch_gap
    bar_x0 = (width - bar_total) // 2
    bar_y = 24
    lavender_bboxes: list[tuple[int, int, int, int]] = []
    for i, kind in enumerate(bar_kinds):
        sx0 = bar_x0 + i * (swatch_w + swatch_gap)
        sx1 = sx0 + swatch_w
        sy1 = bar_y + swatch_h
        if kind == "red":
            draw.rectangle((sx0, bar_y, sx1, sy1), fill=ink_red)
        elif kind == "blue":
            draw.rectangle((sx0, bar_y, sx1, sy1), fill=ink_blue)
        else:  # lavender overprint swatch
            draw.rectangle((sx0, bar_y, sx1, sy1), fill=lavender_sentinel)
            lavender_bboxes.append((sx0, bar_y, sx1, sy1))
    for x0, y0, x1, y1 in lavender_bboxes:
        for py in range(max(0, y0), min(height, y1 + 1)):
            row = BAYER_4x4[py & 3]
            for px in range(max(0, x0), min(width, x1 + 1)):
                if pixels[px, py] == lavender_sentinel:
                    cell = row[px & 3]
                    if cell < 5:
                        pixels[px, py] = ink_red
                    elif cell < 10:
                        pixels[px, py] = ink_blue
                    else:
                        pixels[px, py] = ink_white

    if clear_rect is not None:
        x0, y0, x1, y1 = clear_rect
        draw.rectangle((x0, y0, x1, y1), fill=colors["page_bg"])
        # Two plates, one slightly off: the base (red) rule on the label's
        # edge and the accent (blue) pass shifted by the same (dx, dy) the
        # outer frame uses, so the label is misregistered like the rest
        # of the sheet. Both rules sit inside the clear-rect pad, clear of
        # the first and last text lines.
        draw.rectangle((x0, y0, x1, y1), outline=base, width=2)
        draw.rectangle((x0 + dx, y0 + dy, x1 + dx, y1 + dy), outline=accent, width=2)


def draw_scholar_border(image: Image.Image, colors: dict) -> None:
    """Paint a restrained academic-journal margin treatment.

    Scholar gets subtle editorial structure rather than loud decoration,
    the vocabulary of a hand-set critical edition:

    * a **double blue frame** (outer + inner rule);
    * **printer's corner brackets** — short L-ticks tucked just inside
      the inner frame's four corners, the way a carefully composed page
      registers its type area;
    * a centred **asterism** (the three-dot ``⁂`` section break) at the
      head and a centred **folio ornament** (a short rule pierced by a
      small red lozenge) at the foot — the traditional academic dingbats;
    * thin **margin ruling lines** down both sides that turn the three
      footnote reference numbers from floating marks into proper hanging
      marginalia, each tagged with a small red tick.

    Everything stays blue + red so the page still reads as a curated
    journal offprint, not one attacked by graduate students.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    body = colors["text"]
    accent = colors["accent"]
    outer_inset = 18
    inner_inset = 26
    draw.rectangle(
        (outer_inset, outer_inset, width - 1 - outer_inset, height - 1 - outer_inset),
        outline=body,
        width=1,
    )
    draw.rectangle(
        (inner_inset, inner_inset, width - 1 - inner_inset, height - 1 - inner_inset),
        outline=body,
        width=1,
    )

    # Printer's corner brackets — short right-angle ticks set a few px
    # inside the inner frame at each corner. Reads as the registration
    # marks of a well-composed type area.
    bracket_inset = inner_inset + 6
    bracket_arm = 14
    left = bracket_inset
    right = width - 1 - bracket_inset
    top = bracket_inset
    bottom = height - 1 - bracket_inset
    for cx, cy, hx, vy in (
        (left, top, +1, +1),
        (right, top, -1, +1),
        (left, bottom, +1, -1),
        (right, bottom, -1, -1),
    ):
        draw.line([(cx, cy), (cx + hx * bracket_arm, cy)], fill=body, width=1)
        draw.line([(cx, cy), (cx, cy + vy * bracket_arm)], fill=body, width=1)

    # Side margin ruling lines — define the marginalia columns the
    # footnote numbers hang in. x=40 / width-40 stay clear of the widest
    # (dense, max_width=680 → text left edge 60) quote column.
    rule_x_left = 40
    rule_x_right = width - 1 - 40
    rule_top = inner_inset + 22
    rule_bottom = height - 1 - inner_inset - 22
    for rx in (rule_x_left, rule_x_right):
        draw.line([(rx, rule_top), (rx, rule_bottom)], fill=body, width=1)

    # Hanging footnote reference marks in the ruled margins, each with a
    # small red tick on the outer side so the number reads as an
    # editorial annotation rather than stray ink.
    marker_font = load_font(META_FONT_BOLD_CANDIDATES, size=14)
    for label, y in [("1", 104), ("2", height // 2 - 8), ("3", height - 118)]:
        bbox = draw.textbbox((0, 0), label, font=marker_font)
        xoff = (bbox[2] - bbox[0]) // 2
        draw_text(draw, (52 - xoff, y), label, font=marker_font, fill=accent)
        draw_text(draw, (width - 52 - xoff, y), label, font=marker_font, fill=accent)
        draw.line([(rule_x_left, y + 8), (rule_x_left + 5, y + 8)], fill=accent, width=1)
        draw.line([(rule_x_right - 5, y + 8), (rule_x_right, y + 8)], fill=accent, width=1)

    # Head asterism (⁂) — three small red lozenges in a triangle, the
    # classic typographic section break, centred above the type area.
    acx = width // 2
    acy = 42
    lz = 3  # lozenge half-size
    for px, py in ((acx, acy - 4), (acx - 7, acy + 5), (acx + 7, acy + 5)):
        draw.polygon(
            [(px, py - lz), (px + lz, py), (px, py + lz), (px - lz, py)],
            fill=accent,
        )

    # Foot folio ornament — a short centred blue rule pierced by a small
    # red lozenge, the page-foot dingbat of a printed offprint.
    fy = height - 40
    draw.line([(acx - 34, fy), (acx - 8, fy)], fill=body, width=1)
    draw.line([(acx + 8, fy), (acx + 34, fy)], fill=body, width=1)
    draw.polygon(
        [(acx, fy - 4), (acx + 4, fy), (acx, fy + 4), (acx - 4, fy)],
        fill=accent,
    )


def draw_blueprint_border(image: Image.Image, colors: dict, clear_rect: tuple[int, int, int, int] | None = None) -> None:
    """Paint a cyanotype drafting sheet: dithered ground + frame + grid + crosshairs.

    * **Layer 0: 50/50 white-on-blue checkerboard ground.** Every
      ``page_bg`` pixel on one half of a 1-px checkerboard becomes white,
      so the panel's saturated blue averages to a paler cyanotype wash
      (the trick ``atomic`` uses for its green). Painted first so the
      later layers overpaint it; skipped when ``page_bg`` is absent so
      direct-call test paths stay valid.
    * **Outer frame** in the body-text colour (white in production).
    * **Graph-paper grid** at 20px spacing inside the frame. When
      ``clear_rect`` is given the grid skips that window so the quote
      gets a calmer field.
    * **Corner registration crosshairs** in the accent colour, matching
      the matched-phrase highlight.
    """
    width, height = image.size
    page_bg = colors.get("page_bg")
    frame_inset = 16
    frame_color = colors.get("subtle", colors["text"])
    border_color = colors["text"]
    mark_color = colors["accent"]

    # Layer 0: 50/50 white-on-blue checkerboard. Only exact ``page_bg``
    # pixels are touched, in case a caller painted accents first.
    if page_bg is not None:
        dither_light = SPECTRA6["white"]
        pixels = image.load()
        for y in range(height):
            for x in range(width):
                if (x + y) & 1 and pixels[x, y] == page_bg:
                    pixels[x, y] = dither_light

    draw = ImageDraw.Draw(image)

    grid_spacing = 20
    grid_left = frame_inset + 1
    grid_right = width - 2 - frame_inset
    grid_top = frame_inset + 1
    grid_bottom = height - 2 - frame_inset

    if clear_rect is not None:
        clear_left, clear_top, clear_right, clear_bottom = clear_rect
    else:
        clear_left = clear_top = clear_right = clear_bottom = None

    x = frame_inset + grid_spacing
    while x <= grid_right:
        if clear_rect is None or x < clear_left or x > clear_right:
            draw.line((x, grid_top, x, grid_bottom), fill=frame_color, width=1)
        else:
            if grid_top < clear_top:
                draw.line((x, grid_top, x, clear_top), fill=frame_color, width=1)
            if clear_bottom < grid_bottom:
                draw.line((x, clear_bottom, x, grid_bottom), fill=frame_color, width=1)
        x += grid_spacing

    y = frame_inset + grid_spacing
    while y <= grid_bottom:
        if clear_rect is None or y < clear_top or y > clear_bottom:
            draw.line((grid_left, y, grid_right, y), fill=frame_color, width=1)
        else:
            if grid_left < clear_left:
                draw.line((grid_left, y, clear_left, y), fill=frame_color, width=1)
            if clear_right < grid_right:
                draw.line((clear_right, y, grid_right, y), fill=frame_color, width=1)
        y += grid_spacing

    draw.rectangle(
        (frame_inset, frame_inset, width - 1 - frame_inset, height - 1 - frame_inset),
        outline=border_color,
        width=1,
    )

    arm = 8
    centres = [
        (frame_inset, frame_inset),
        (width - 1 - frame_inset, frame_inset),
        (frame_inset, height - 1 - frame_inset),
        (width - 1 - frame_inset, height - 1 - frame_inset),
    ]
    for cx, cy in centres:
        draw.line((cx - arm, cy, cx + arm, cy), fill=mark_color, width=1)
        draw.line((cx, cy - arm, cx, cy + arm), fill=mark_color, width=1)

    # --- Drafting callouts. Both sit in the clear margins, so the quote
    # (never above y=72, attribution bottom-left) overpaints nothing and
    # no _DEBUG_LABEL_RIGHT_INSET entry is needed: the dimension line is at
    # y=40, below the y=14-29 banner band, and the scale bar hugs the
    # bottom-right.
    callout_font = load_font(META_FONT_CANDIDATES, size=12)

    # Top overall-width dimension line: end ticks, a rule broken in the
    # centre for the figure, inward arrowheads. Rule + ticks in the body
    # ink; arrowheads + figure in the accent ink.
    dim_y = 40
    dim_l = 120
    dim_r = width - 1 - 120
    mid = width // 2
    figure = str(width)  # "800" at the panel's reference width
    fb = draw.textbbox((0, 0), figure, font=callout_font)
    fw = fb[2] - fb[0]
    gap = fw // 2 + 8
    draw.line((dim_l, dim_y - 8, dim_l, dim_y + 8), fill=border_color, width=1)
    draw.line((dim_r, dim_y - 8, dim_r, dim_y + 8), fill=border_color, width=1)
    draw.line((dim_l, dim_y, mid - gap, dim_y), fill=border_color, width=1)
    draw.line((mid + gap, dim_y, dim_r, dim_y), fill=border_color, width=1)
    for ax, adir in ((dim_l, 1), (dim_r, -1)):
        draw.polygon(
            [(ax, dim_y), (ax + adir * 6, dim_y - 3), (ax + adir * 6, dim_y + 3)],
            fill=mark_color,
        )
    draw.text((mid - fw // 2, dim_y - (fb[3] - fb[1]) // 2 - fb[1]), figure, font=callout_font, fill=mark_color)

    # Bottom-right graduated scale bar: five 16 px cells alternating
    # filled / outline, "SCALE 1:1" above, clear of the corner crosshair
    # and the bottom-left attribution.
    bar_cells = 5
    cell_w = 16
    bar_w = bar_cells * cell_w
    bar_x = width - 1 - frame_inset - 12 - bar_w
    bar_y = height - 1 - frame_inset - 18
    for i in range(bar_cells):
        x0 = bar_x + i * cell_w
        if i % 2 == 0:
            draw.rectangle((x0, bar_y, x0 + cell_w, bar_y + 6), fill=border_color)
        else:
            draw.rectangle((x0, bar_y, x0 + cell_w, bar_y + 6), outline=border_color, width=1)
    draw.text((bar_x, bar_y - 16), "SCALE 1:1", font=callout_font, fill=border_color)


def draw_illuminated_border(image: Image.Image, colors: dict) -> None:
    """Paint a manuscript-style border: cream-washed vellum + double
    rubricated rule + plum corner cabochons.

    * **Layer 0: sparse cream ground wash.** A 4×4 Bayer dither flips
      ~12.5% of the white ``page_bg`` pixels (cells < 2) to yellow, which
      averages to a faint aged-vellum tone (the threshold ``dispatch``'s
      Layer 0 uses).
    * **Double rubricated rule**: two thin red rectangles with a narrow
      blank band between them.
    * **Plum corner cabochons**: each gem is painted in a sentinel, then
      a per-jewel bbox post-pass assigns red / blue / black through a
      3-way 4×4 Bayer partition (cells 0-4 / 5-9 / 10-15), the R+B+K
      deep-plum recipe in ``spectra6_color_recipes.md``.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    body = colors["text"]       # rubricated red
    accent = colors["accent"]   # lapis blue; selects the plum-jewel branch below
    page_bg = colors.get("page_bg")
    cream_light = SPECTRA6["yellow"]

    # Layer 0: sparse 1-in-8 yellow-on-white cream wash. Only exact
    # ``page_bg`` pixels are flipped, so palette-mismatch test paths stay valid.
    pixels = image.load()
    if page_bg is not None:
        for y in range(height):
            row = BAYER_4x4[y & 3]
            for x in range(width):
                if pixels[x, y] == page_bg and row[x & 3] < 2:
                    pixels[x, y] = cream_light

    outer_inset = 14
    inner_inset = 22
    # Outer rule.
    draw.rectangle(
        (outer_inset, outer_inset, width - 1 - outer_inset, height - 1 - outer_inset),
        outline=body,
        width=1,
    )
    # Inner rule — the "doubled" rubrication line.
    draw.rectangle(
        (inner_inset, inner_inset, width - 1 - inner_inset, height - 1 - inner_inset),
        outline=body,
        width=1,
    )

    jewel_radius = 5
    centres = [
        (outer_inset, outer_inset),
        (width - 1 - outer_inset, outer_inset),
        (outer_inset, height - 1 - outer_inset),
        (width - 1 - outer_inset, height - 1 - outer_inset),
    ]
    # Plum cabochons only for the standard palette (accent = lapis blue).
    # A direct caller with a non-standard accent gets a solid jewel in that
    # accent, so ``uses_theme_colours_not_hardcoded_rgb`` still holds.
    if accent == SPECTRA6["blue"]:
        jewel_sentinel = (1, 1, 1)
        for cx, cy in centres:
            draw.ellipse(
                (cx - jewel_radius, cy - jewel_radius, cx + jewel_radius, cy + jewel_radius),
                fill=jewel_sentinel,
            )
        # 3-way Bayer translation: cells 0-4 → red, 5-9 → blue, 10-15 → black.
        ink_red = SPECTRA6["red"]
        ink_blue = SPECTRA6["blue"]
        ink_black = SPECTRA6["black"]
        for cx, cy in centres:
            x0 = max(0, cx - jewel_radius - 1)
            y0 = max(0, cy - jewel_radius - 1)
            x1 = min(width - 1, cx + jewel_radius + 1)
            y1 = min(height - 1, cy + jewel_radius + 1)
            for py in range(y0, y1 + 1):
                row = BAYER_4x4[py & 3]
                for px in range(x0, x1 + 1):
                    if pixels[px, py] == jewel_sentinel:
                        cell = row[px & 3]
                        if cell < 5:
                            pixels[px, py] = ink_red
                        elif cell < 10:
                            pixels[px, py] = ink_blue
                        else:
                            pixels[px, py] = ink_black
    else:
        for cx, cy in centres:
            draw.ellipse(
                (cx - jewel_radius, cy - jewel_radius, cx + jewel_radius, cy + jewel_radius),
                fill=accent,
            )

    # Head ornament: three red lozenges in the "⁂" section-break
    # triangle, each with a blue centre dot (rubric + lapis). At y≈42,
    # below the y=14-29 debug-banner band and above the text (y >= 72).
    hcx = width // 2
    hy = 42
    lz = 4  # lozenge half-size
    for px, py in ((hcx, hy - 5), (hcx - 11, hy + 5), (hcx + 11, hy + 5)):
        draw.polygon(
            [(px, py - lz), (px + lz, py), (px, py + lz), (px - lz, py)],
            fill=body,
        )
        draw.point((px, py), fill=accent)

    # Foot line-filler: a centred red rule pierced by a red lozenge and
    # flanked by two blue ones, the filler scribes ran to the end of a
    # short line. Centred, clear of the bottom-left attribution.
    fy = height - 1 - outer_inset - 14
    draw.line((hcx - 44, fy, hcx - 8, fy), fill=body, width=1)
    draw.line((hcx + 8, fy, hcx + 44, fy), fill=body, width=1)
    draw.polygon([(hcx, fy - lz), (hcx + lz, fy), (hcx, fy + lz), (hcx - lz, fy)], fill=body)
    for fx in (hcx - 50, hcx + 50):
        draw.polygon(
            [(fx, fy - 3), (fx + 3, fy), (fx, fy + 3), (fx - 3, fy)],
            fill=accent,
        )


def draw_gothic_border(image: Image.Image, colors: dict) -> None:
    """Paint a Gothic-tracery border: double rule + maroon quatrefoils + cream mid-edge diamonds.

    An outer red rule and inner white rule (a two-colour doubled
    rubrication, unlike ``illuminated``'s single ink).

    Four corner quatrefoils, each four lobes around a white centre dot.
    Lobes are painted red, then a per-lobe bbox post-pass flips half to
    black on ``(x+y)&1`` parity: the R+K 1:1 maroon recipe (as in
    ``dispatch``'s stamp), read as iron-aged tracery.

    Four mid-edge diamonds in cream: painted yellow, then half flipped to
    white on parity (the Y+W 1:1 recipe). This gives the mid-edges their
    own register, distinct from the corner maroon, and echoes the
    candlelit-rubric matched phrase.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    body = colors["text"]      # white ink
    accent = colors["accent"]  # rubric red

    outer_inset = 14
    inner_inset = 22
    draw.rectangle(
        (outer_inset, outer_inset, width - 1 - outer_inset, height - 1 - outer_inset),
        outline=accent,
        width=1,
    )
    draw.rectangle(
        (inner_inset, inner_inset, width - 1 - inner_inset, height - 1 - inner_inset),
        outline=body,
        width=1,
    )

    # Corner quatrefoils: four lobes in a + around the corner anchor plus
    # a white centre dot for silhouette legibility. Lobes paint red as a
    # sentinel; the post-pass below makes them maroon.
    lobe_radius = 5
    lobe_offset = 4
    sentinel_red = SPECTRA6["red"]
    sentinel_yellow = SPECTRA6["yellow"]
    maroon_dark = SPECTRA6["black"]
    cream_light = SPECTRA6["white"]
    centres = [
        (outer_inset, outer_inset),
        (width - 1 - outer_inset, outer_inset),
        (outer_inset, height - 1 - outer_inset),
        (width - 1 - outer_inset, height - 1 - outer_inset),
    ]
    lobe_bboxes: list[tuple[int, int, int, int]] = []
    for cx, cy in centres:
        for dx, dy in ((0, -lobe_offset), (lobe_offset, 0), (0, lobe_offset), (-lobe_offset, 0)):
            lx, ly = cx + dx, cy + dy
            draw.ellipse(
                (lx - lobe_radius, ly - lobe_radius, lx + lobe_radius, ly + lobe_radius),
                fill=sentinel_red,
            )
            lobe_bboxes.append((lx - lobe_radius, ly - lobe_radius, lx + lobe_radius, ly + lobe_radius))
        draw.ellipse((cx - 2, cy - 2, cx + 2, cy + 2), fill=body)

    pixels = image.load()
    # Maroon post-pass on each lobe bbox — flip half of the red pixels
    # to black per (x+y)&1 parity inside the per-lobe bbox.
    for x0, y0, x1, y1 in lobe_bboxes:
        x0 = max(0, x0)
        y0 = max(0, y0)
        x1 = min(width - 1, x1)
        y1 = min(height - 1, y1)
        for py in range(y0, y1 + 1):
            for px in range(x0, x1 + 1):
                if (px + py) & 1 == 0 and pixels[px, py] == sentinel_red:
                    pixels[px, py] = maroon_dark

    # Mid-edge cream diamonds — painted in yellow as a sentinel, then a
    # per-diamond bbox post-pass flips half of the painted pixels to
    # white per parity for the documented Y+W cream recipe.
    diamond = 4
    midpoints = [
        (width // 2, outer_inset),
        (width // 2, height - 1 - outer_inset),
        (outer_inset, height // 2),
        (width - 1 - outer_inset, height // 2),
    ]
    for cx, cy in midpoints:
        draw.polygon(
            [(cx, cy - diamond), (cx + diamond, cy), (cx, cy + diamond), (cx - diamond, cy)],
            fill=sentinel_yellow,
        )
    for cx, cy in midpoints:
        x0 = max(0, cx - diamond)
        y0 = max(0, cy - diamond)
        x1 = min(width - 1, cx + diamond)
        y1 = min(height - 1, cy + diamond)
        for py in range(y0, y1 + 1):
            for px in range(x0, x1 + 1):
                if (px + py) & 1 == 0 and pixels[px, py] == sentinel_yellow:
                    pixels[px, py] = cream_light

    # Head + foot trefoil finials, centred in the top and bottom margins
    # just inside the inner frame. Solid rubric red, not the corners'
    # maroon: red+black nearly vanishes on the black ground. Each lobe
    # gets a white centre dot like the quatrefoils. Centred so the top one
    # clears the right-aligned DEBUG MODE banner and the foot one the
    # bottom-left attribution.
    trefoil_r = 5
    trefoil_spread = 8
    for base_cx, base_cy, point_up in (
        (width // 2, inner_inset + 13, True),
        (width // 2, height - 1 - inner_inset - 13, False),
    ):
        vy = -1 if point_up else 1
        lobes = (
            (0, vy * trefoil_spread),               # apex lobe
            (-trefoil_spread, -vy * 2),             # lower-left lobe
            (trefoil_spread, -vy * 2),              # lower-right lobe
        )
        for dx, dy in lobes:
            lx, ly = base_cx + dx, base_cy + dy
            draw.ellipse(
                (lx - trefoil_r, ly - trefoil_r, lx + trefoil_r, ly + trefoil_r),
                fill=accent,
            )
            draw.ellipse((lx - 1, ly - 1, lx + 1, ly + 1), fill=body)
        # Short stem joining the lobes at the trefoil centre.
        draw.ellipse((base_cx - 2, base_cy - 2, base_cx + 2, base_cy + 2), fill=accent)


def _draw_grimoire_sun(draw: ImageDraw.ImageDraw, cx: int, cy: int, accent: tuple[int, int, int]) -> None:
    """Solar ☉ (gold / the Sun): outline circle with a filled centre dot."""
    r = 7
    draw.ellipse((cx - r, cy - r, cx + r, cy + r), outline=accent, width=2)
    draw.ellipse((cx - 2, cy - 2, cx + 2, cy + 2), fill=accent)


def _draw_grimoire_moon(
    draw: ImageDraw.ImageDraw,
    cx: int,
    cy: int,
    accent: tuple[int, int, int],
    page_bg: tuple[int, int, int],
) -> None:
    """Lunar ☽: a red disk carved by a smaller page-bg disk offset right,
    leaving a left-opening crescent (the alchemical lunar convention)."""
    r = 7
    draw.ellipse((cx - r, cy - r, cx + r, cy + r), fill=accent)
    # Carving disk shifted +4 in x; the overlap stays inside the outer
    # disk, so page_bg is never painted outside the symbol footprint.
    inner_r = 6
    offset = 4
    draw.ellipse(
        (cx - inner_r + offset, cy - inner_r, cx + inner_r + offset, cy + inner_r),
        fill=page_bg,
    )


def _draw_grimoire_mars(
    draw: ImageDraw.ImageDraw, cx: int, cy: int, accent: tuple[int, int, int]
) -> None:
    """Martial ♂: outline circle offset down-left, with a diagonal shaft
    and a V-barb arrowhead pointing NE. Barbs are two short strokes meeting
    at the tip so the arrow still reads at mid-edge symbol scale."""
    r = 6
    # Circle centre pushed down-left so the NE arrow has room without
    # the circle bumping the mid-edge anchor.
    bcx, bcy = cx - 3, cy + 3
    draw.ellipse((bcx - r, bcy - r, bcx + r, bcy + r), outline=accent, width=2)
    # Long diagonal shaft from upper-right of circle outward to NE.
    shaft_start = (bcx + 4, bcy - 4)
    tip = (bcx + 11, bcy - 11)
    draw.line((*shaft_start, *tip), fill=accent, width=2)
    # Two barbs at the tip, each perpendicular to the 45° shaft, forming
    # the canonical arrowhead V. The first barb runs horizontal-left
    # from the tip, the second runs vertical-down from the tip — taken
    # together they "open" the arrowhead in the right direction.
    barb = 5
    draw.line((tip[0] - barb, tip[1], tip[0], tip[1]), fill=accent, width=2)
    draw.line((tip[0], tip[1], tip[0], tip[1] + barb), fill=accent, width=2)


def _draw_grimoire_venus(
    draw: ImageDraw.ImageDraw, cx: int, cy: int, accent: tuple[int, int, int]
) -> None:
    """Venusian ♀: outline circle offset up, with a vertical shaft below
    it and a horizontal crossbar (the complement to Mars)."""
    r = 6
    bcx, bcy = cx, cy - 4
    draw.ellipse((bcx - r, bcy - r, bcx + r, bcy + r), outline=accent, width=2)
    # Vertical shaft from circle bottom downward.
    shaft_top = (bcx, bcy + r)
    shaft_bottom = (bcx, bcy + r + 7)
    draw.line((*shaft_top, *shaft_bottom), fill=accent, width=2)
    # Horizontal crossbar across the shaft, ~2/3 of the way down.
    crossbar_y = bcy + r + 4
    draw.line((bcx - 4, crossbar_y, bcx + 4, crossbar_y), fill=accent, width=2)


def draw_grimoire_border(image: Image.Image, colors: dict) -> None:
    """Paint an alchemical-grimoire border: outer rule + four magic-circle
    inscribed pentagrams + four planetary sigils on the mid-edges.

    Shares ``gothic``'s black/white/red palette but not its silhouette: a
    single thin red rule, an inscribed pentagram (star + ring) at each
    corner, and the four classical planetary sigils breaking the
    mid-edges (Sun ☉ top, Moon ☽ bottom, Mars ♂ left, Venus ♀ right).

    **Pentagrams.** Five vertices of a regular pentagon of radius
    ``pent_radius`` joined in skip-one order (``0 → 2 → 4 → 1 → 3 → 0``),
    first vertex at the top (``angle = -π/2``) so the star stands upright,
    inside a ring of radius ``ring_radius`` ~3 px outside the tips so the
    strokes don't merge.

    **Mid-edge sigils.** Drawn from PIL primitives rather than glyphs,
    because font coverage of ``U+2609`` onward varies across the bundled
    faces. They sit on the outer rule and punch through it, as
    ``gothic``'s mid-edge diamonds do.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    accent = colors["accent"]  # rubric red
    page_bg = colors.get("page_bg", SPECTRA6["black"])

    outer_inset = 14
    draw.rectangle(
        (outer_inset, outer_inset, width - 1 - outer_inset, height - 1 - outer_inset),
        outline=accent,
        width=1,
    )

    # Four inscribed pentagrams at the inset corners. ``corner_offset``
    # keeps each ring (radius + 2 px stroke half-width) clear of the
    # outer rule.
    pent_radius = 11
    ring_radius = 14
    corner_offset = ring_radius + 2
    centres = [
        (outer_inset + corner_offset, outer_inset + corner_offset),
        (width - 1 - outer_inset - corner_offset, outer_inset + corner_offset),
        (outer_inset + corner_offset, height - 1 - outer_inset - corner_offset),
        (width - 1 - outer_inset - corner_offset, height - 1 - outer_inset - corner_offset),
    ]
    skip_one = (0, 2, 4, 1, 3, 0)
    for cx, cy in centres:
        vertices = []
        for i in range(5):
            angle = -math.pi / 2 + i * (2 * math.pi / 5)
            vx = cx + pent_radius * math.cos(angle)
            vy = cy + pent_radius * math.sin(angle)
            vertices.append((vx, vy))
        path = [vertices[i] for i in skip_one]
        draw.line(path, fill=accent, width=2)
        # Surrounding ring — the "magic circle" containing the pentacle.
        draw.ellipse(
            (cx - ring_radius, cy - ring_radius, cx + ring_radius, cy + ring_radius),
            outline=accent,
            width=2,
        )

    # Four planetary sigils centred on the mid-edges of the outer rule,
    # each ~14 px tall. The moon carves its crescent with ``page_bg``
    # inside its own footprint.
    #
    # Each planet gets its own stippled colour (post-pass below): Sun →
    # tangerine (R + 3/8 Y at Bayer threshold 6), Moon → sky (blue sentinel,
    # half to white on (x+y)&1), Mars → maroon (R+K 1:1), Venus → violet
    # (R+B 1:1). The ±16 px bboxes overlap no other layer, so the
    # post-passes are safe to bbox-scope.
    mid_top = (width // 2, outer_inset)
    mid_bottom = (width // 2, height - 1 - outer_inset)
    mid_left = (outer_inset, height // 2)
    mid_right = (width - 1 - outer_inset, height // 2)
    moon_disc_blue = SPECTRA6["blue"]
    _draw_grimoire_sun(draw, *mid_top, accent)
    _draw_grimoire_moon(draw, *mid_bottom, moon_disc_blue, page_bg)
    _draw_grimoire_mars(draw, *mid_left, accent)
    _draw_grimoire_venus(draw, *mid_right, accent)

    # Per-planet bbox post-pass. ``sigil_radius`` generously covers the
    # Mars / Venus off-anchor geometry.
    pixels = image.load()
    sigil_radius = 16
    planet_passes = (
        # (centre, sentinel_ink, light_ink, density)
        (mid_top, SPECTRA6["red"], SPECTRA6["yellow"], 0.375),   # ☉ Sun → tangerine
        (mid_bottom, moon_disc_blue, SPECTRA6["white"], 0.5),    # ☽ Moon → sky
        (mid_left, SPECTRA6["red"], SPECTRA6["black"], 0.5),     # ♂ Mars → maroon
        (mid_right, SPECTRA6["red"], SPECTRA6["blue"], 0.5),     # ♀ Venus → violet
    )
    for (cx, cy), dark_ink, light_ink, density in planet_passes:
        bx0 = max(0, cx - sigil_radius)
        by0 = max(0, cy - sigil_radius)
        bx1 = min(width - 1, cx + sigil_radius)
        by1 = min(height - 1, cy + sigil_radius)
        threshold = round(density * 16)
        if density <= 0.25:
            for py in range(by0, by1 + 1):
                for px in range(bx0, bx1 + 1):
                    if (px & 1) == 0 and (py & 1) == 0 and pixels[px, py] == dark_ink:
                        pixels[px, py] = light_ink
        elif density >= 0.5:
            for py in range(by0, by1 + 1):
                for px in range(bx0, bx1 + 1):
                    if (px + py) & 1 == 0 and pixels[px, py] == dark_ink:
                        pixels[px, py] = light_ink
        else:
            for py in range(by0, by1 + 1):
                row = BAYER_4x4[py & 3]
                for px in range(bx0, bx1 + 1):
                    if row[px & 3] < threshold and pixels[px, py] == dark_ink:
                        pixels[px, py] = light_ink

    # "Tria prima" ``∴`` triads (salt · sulfur · mercury) flanking the Sun
    # and Moon: three red dots each side, filling the top / bottom bands
    # (y≈18-40 / y≈440-462) between the corner pentagrams and the sigils,
    # clear of the body block (y≈72-410).
    triad_r = 2
    triad_spread = 6
    for cy, point_up in ((outer_inset + 14, True), (height - 1 - outer_inset - 14, False)):
        vy = -1 if point_up else 1
        for cx in (width // 2 - 60, width // 2 + 60):
            apex = (cx, cy + vy * triad_spread)
            base_l = (cx - triad_spread, cy - vy * triad_spread // 2)
            base_r = (cx + triad_spread, cy - vy * triad_spread // 2)
            for dx, dy in (apex, base_l, base_r):
                draw.ellipse((dx - triad_r, dy - triad_r, dx + triad_r, dy + triad_r), fill=accent)


def draw_deco_border(image: Image.Image, colors: dict) -> None:
    """Paint an art-deco poster frame: doubled hairline rule + stepped
    skyscraper-step corner ornaments + a top-centre rising-sun fan.

    * **Doubled hairline frame**: rectangles at insets 14 and 22, 1 px
      stroke in ``colors["text"]``.
    * **Stepped corner ornaments**: three concentric L-shapes per corner
      in ``colors["accent"]``, vertex at the inner-frame corner, arms
      12 / 18 / 24 px, 1 px stroke.
    * **Centred rising-sun fan**: a small accent dot on the inner frame's
      top edge with five short rays fanning upward through the band
      between the two rules, ending at y = outer_inset + 1. Centred, so
      it never reaches the right-aligned ``DEBUG MODE`` banner.

    ``deco`` is deliberately **absent** from ``_DEBUG_LABEL_RIGHT_INSET``
    (like ``atomic`` and ``dispatch``): the top-right steps end at
    x ≤ width-14, ≥6 px clear of the default label edge
    (``SIDE_MARGIN = 20``).

    **Final pass: red→orange Bayer dither.** Spectra 6 has no orange, so
    ~3/8 of the ``accent`` pixels flip to yellow on ``BAYER_4x4``
    (cells < 6). Red-biased because a 50/50 mix reads as washed-out amber
    (yellow is far more luminous). Threshold and phase match
    ``draw_text_dithered``'s ``light_density=0.375`` branch so border and
    matched phrase share one orange. Runs only when ``accent`` is
    Spectra-6 red; custom-palette direct calls keep a solid accent.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    frame_color = colors["text"]
    accent_color = colors["accent"]

    outer_inset = 14
    inner_inset = 22
    draw.rectangle(
        (outer_inset, outer_inset, width - 1 - outer_inset, height - 1 - outer_inset),
        outline=frame_color,
        width=1,
    )
    draw.rectangle(
        (inner_inset, inner_inset, width - 1 - inner_inset, height - 1 - inner_inset),
        outline=frame_color,
        width=1,
    )

    # Stepped skyscraper-corner ornaments: three concentric L-shapes
    # inside the inner frame, vertex at the inner-frame corner, arms
    # along the two adjacent sides, growing 12 / 18 / 24 px.
    corner_origins = [
        # (corner_x, corner_y, dx, dy) — corner anchor (inner-frame corner)
        # plus the unit-vector pair pointing inward along the two sides.
        (inner_inset + 1, inner_inset + 1, +1, +1),                       # top-left
        (width - 2 - inner_inset, inner_inset + 1, -1, +1),                # top-right
        (inner_inset + 1, height - 2 - inner_inset, +1, -1),               # bottom-left
        (width - 2 - inner_inset, height - 2 - inner_inset, -1, -1),       # bottom-right
    ]
    for step in (1, 2, 3):
        step_length = 6 + step * 6  # 12 / 18 / 24
        step_offset = step * 2       # 2 / 4 / 6 px gap between concentric L's
        for cx, cy, dx, dy in corner_origins:
            ax = cx + dx * step_offset
            ay = cy + dy * step_offset
            # Horizontal arm along the top/bottom edge of the L.
            draw.line(
                [(ax, ay), (ax + dx * step_length, ay)],
                fill=accent_color,
                width=1,
            )
            # Vertical arm along the left/right edge of the L.
            draw.line(
                [(ax, ay), (ax, ay + dy * step_length)],
                fill=accent_color,
                width=1,
            )

    # Top-centre rising-sun fan: a dot on the inner frame's top edge with
    # five rays fanning up through the y ∈ [14, 22] band between the
    # rules. Rays cap at y = outer_inset + 1 so they never touch the outer
    # hairline.
    fan_cx = width // 2
    fan_cy = inner_inset
    fan_dot_r = 2
    draw.ellipse(
        (fan_cx - fan_dot_r, fan_cy - fan_dot_r, fan_cx + fan_dot_r, fan_cy + fan_dot_r),
        fill=accent_color,
    )
    ray_top_y = outer_inset + 1
    ray_height = fan_cy - ray_top_y
    # Five rays spread across a 90° arc centred straight up (-π/2),
    # symmetric about the vertical axis: angles -π/2 ± k·(π/8).
    for k in (-2, -1, 0, 1, 2):
        angle = -math.pi / 2 + k * (math.pi / 8)
        end_x = fan_cx + math.cos(angle) * ray_height / max(abs(math.sin(angle)), 0.001) \
                if k != 0 else fan_cx
        end_y = ray_top_y
        # Clamp end_x to the fan footprint (~ray_height) so the side rays
        # don't streak off to the canvas edge for small |sin(angle)|.
        max_dx = ray_height
        if end_x < fan_cx - max_dx:
            end_x = fan_cx - max_dx
        elif end_x > fan_cx + max_dx:
            end_x = fan_cx + max_dx
        draw.line(
            [(fan_cx, fan_cy), (end_x, end_y)],
            fill=accent_color,
            width=1,
        )

    # Mid-edge stepped chevrons: three nested chevrons at the left and
    # right mid-edges opening toward the page centre, echoing the corner
    # steps. Painted in the accent *before* the tangerine pass so they get
    # the same orange. Each is 5 px further in and 4 px taller.
    mid_y = height // 2
    for edge_x, dir_in in ((inner_inset + 1, +1), (width - 2 - inner_inset, -1)):
        for step in (0, 1, 2):
            ax = edge_x + dir_in * step * 5
            arm = 6 + step * 4
            # Two arms meeting at a point on the frame side, opening inward.
            draw.line([(ax, mid_y - arm), (ax + dir_in * arm, mid_y)], fill=accent_color, width=1)
            draw.line([(ax, mid_y + arm), (ax + dir_in * arm, mid_y)], fill=accent_color, width=1)

    # Final pass: synthesise orange (see docstring). Threshold (6) and
    # phase match ``draw_text_dithered``'s ``light_density=0.375`` branch.
    if accent_color == SPECTRA6["red"]:
        light = SPECTRA6["yellow"]
        threshold = 6  # round(0.375 * 16) — keep in sync with _draw_text_body
        pixels = image.load()
        for y in range(image.height):
            row = BAYER_4x4[y % 4]
            for x in range(image.width):
                if row[x % 4] < threshold and pixels[x, y] == accent_color:
                    pixels[x, y] = light

        # Cream core on the fan rays: in the inner band (y ∈ [fan_cy-5,
        # fan_cy], where the rays converge) the remaining red pixels flip
        # to white on (x+y)&1, giving ~3/8 Y + 5/16 W + 5/16 R that fades
        # into tangerine at the tips, a sunburst with a bright centre.
        # Bbox-scoped to x ∈ [fan_cx ± ray_height] so the corner steps
        # stay tangerine.
        cream_band_top = max(0, fan_cy - 5)
        cream_band_bot = min(image.height - 1, fan_cy)
        cream_x_lo = max(0, fan_cx - ray_height)
        cream_x_hi = min(image.width - 1, fan_cx + ray_height)
        cream_light = SPECTRA6["white"]
        for y in range(cream_band_top, cream_band_bot + 1):
            for x in range(cream_x_lo, cream_x_hi + 1):
                if (x + y) & 1 == 0 and pixels[x, y] == accent_color:
                    pixels[x, y] = cream_light


def draw_glacier_border(image: Image.Image, colors: dict) -> None:
    """Paint an icy / aurora border: thin outer rule + four corner
    frost-crystal clusters + four mid-edge snowflake-tick stars.

    * **Outer frame**: one rectangle at inset 14, 1 px, ``colors["text"]``
      (blue).
    * **Frost-crystal clusters**: three filled triangles fanning out from
      each corner along the adjacent sides, two blue and the longest
      tipped in ``colors["accent"]`` (green, the aurora). ~8–14 px, well
      outside the quote block (the layout always leaves ≥30 px of corner).
    * **Mid-edge snowflake ticks**: a small four-armed star (radius ~6 px)
      at each edge midpoint, a filled diamond plus a thin cross.

    The top-right cluster (x ≥ width-30, y ≤ 30) overlaps the default
    ``DEBUG MODE`` label band, so ``glacier`` has an entry in
    ``_DEBUG_LABEL_RIGHT_INSET``.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    body_color = colors["text"]
    accent_color = colors["accent"]

    outer_inset = 14
    draw.rectangle(
        (outer_inset, outer_inset, width - 1 - outer_inset, height - 1 - outer_inset),
        outline=body_color,
        width=1,
    )

    # Frost-edge wash: sparse sky-blue frost in the top and bottom
    # margins, densest at the frame edge and tapering inward (a gradient
    # Bayer threshold), like ice creeping across a window. Bands stay in
    # the ≤44 px margins (text never starts before y=72) and flip only
    # *white* ground pixels, so the blue body text stays legible. Skipped
    # on non-white grounds (the unit-test sentinel render).
    pixels = image.load()
    band_depth = 44
    inner_l = outer_inset + 1
    inner_r = width - 1 - outer_inset
    white = SPECTRA6["white"]
    for band_top, grad_dir in ((outer_inset + 1, +1), (height - 1 - outer_inset - band_depth, -1)):
        for row in range(band_depth):
            y = band_top + row
            if y < 0 or y >= height:
                continue
            # Distance from the frame edge (0 at edge → band_depth at inner lip).
            edge_dist = row if grad_dir > 0 else band_depth - 1 - row
            # Peak ~5/16 frost at the edge, fading linearly to bare.
            thresh = max(0, 5 - (edge_dist * 5) // band_depth)
            if thresh <= 0:
                continue
            for x in range(inner_l, inner_r):
                if BAYER_4x4[y % 4][x % 4] < thresh and pixels[x, y] == white:
                    pixels[x, y] = body_color

    # Frost-crystal clusters: from each corner a spray of shards fans into
    # the page: four slim blue splinters (horizontal, vertical, two
    # intermediate) plus the longest diagonal one in the accent, with two
    # dendrite barbs like hoar-frost side-arms, and a blue hub dot.
    corner_anchors = [
        # (anchor_x, anchor_y, dx, dy) — inner-frame corner plus the
        # unit-vector pair pointing into the page.
        (outer_inset + 2, outer_inset + 2, +1, +1),                       # top-left
        (width - 3 - outer_inset, outer_inset + 2, -1, +1),                # top-right
        (outer_inset + 2, height - 3 - outer_inset, +1, -1),               # bottom-left
        (width - 3 - outer_inset, height - 3 - outer_inset, -1, -1),       # bottom-right
    ]
    short_arm = 9
    mid_arm = 12
    long_arm = 16
    base_half = 3  # half-width of each shard's base near the corner
    for ax, ay, dx, dy in corner_anchors:
        # Horizontal shard — tip along the top/bottom edge.
        tip_h = (ax + dx * short_arm, ay)
        draw.polygon([tip_h, (ax, ay - base_half * dy), (ax, ay + base_half * dy)], fill=body_color)
        # Vertical shard — tip along the left/right edge.
        tip_v = (ax, ay + dy * short_arm)
        draw.polygon([tip_v, (ax - base_half * dx, ay), (ax + base_half * dx, ay)], fill=body_color)
        # Two intermediate blue shards filling the 45° fan, offset toward
        # each edge so the spray reads as a crystalline spread.
        tip_m1 = (ax + dx * mid_arm, ay + dy * (mid_arm // 2))
        draw.polygon([tip_m1, (ax + dx * base_half, ay), (ax, ay + dy * base_half)], fill=body_color)
        tip_m2 = (ax + dx * (mid_arm // 2), ay + dy * mid_arm)
        draw.polygon([tip_m2, (ax, ay + dy * base_half), (ax + dx * base_half, ay)], fill=body_color)
        # Diagonal shard — the longest, tipped in accent for aurora.
        tip_d = (ax + dx * long_arm, ay + dy * long_arm)
        draw.polygon(
            [tip_d, (ax + dx * base_half, ay - dy * base_half), (ax - dx * base_half, ay + dy * base_half)],
            fill=accent_color,
        )
        # Dendrite barbs feathering off the diagonal shard (accent, so
        # the sky-blue post-pass below lifts them with the main spine).
        mid_d = (ax + dx * (long_arm - 5), ay + dy * (long_arm - 5))
        draw.line([mid_d, (mid_d[0] + dx * 4, mid_d[1])], fill=accent_color, width=1)
        draw.line([mid_d, (mid_d[0], mid_d[1] + dy * 4)], fill=accent_color, width=1)
        # Hub dot.
        draw.ellipse([ax - 1, ay - 1, ax + 1, ay + 1], fill=body_color)

    # Mid-edge snowflake ticks: six-armed frost stars (three spokes at
    # 0°/60°/120° with a forked barb at each tip) on a filled blue hub
    # diamond, in body colour so they read as frost, not an accent.
    star_r = 7
    midpoints = [
        (width // 2, outer_inset),               # top
        (width // 2, height - 1 - outer_inset),  # bottom
        (outer_inset, height // 2),              # left
        (width - 1 - outer_inset, height // 2),  # right
    ]
    diamond_r = 3
    # Unit directions for three spokes (and their negatives → six arms).
    spokes = [(1.0, 0.0), (0.5, 0.866), (-0.5, 0.866)]
    for mx, my in midpoints:
        draw.polygon(
            [(mx, my - diamond_r), (mx + diamond_r, my), (mx, my + diamond_r), (mx - diamond_r, my)],
            fill=body_color,
        )
        for ux, uy in spokes:
            ex, ey = mx + ux * star_r, my + uy * star_r
            nx, ny = mx - ux * star_r, my - uy * star_r
            draw.line([(nx, ny), (ex, ey)], fill=body_color, width=1)
            # Forked barbs at both tips.
            for tip_x, tip_y, sgn in ((ex, ey, -1), (nx, ny, +1)):
                bx, by = tip_x + sgn * ux * 3, tip_y + sgn * uy * 3
                draw.line([(tip_x, tip_y), (bx - uy * 2, by + ux * 2)], fill=body_color, width=1)
                draw.line([(tip_x, tip_y), (bx + uy * 2, by - ux * 2)], fill=body_color, width=1)

    # Aurora-on-ice post-pass: flip ~50% of the accent (green) shard pixels
    # to white on a 1×1 checkerboard (the G+W 1:1 mint recipe), lifting the
    # long shard into a highlight while the blue shards stay solid.
    # Bbox-scoped: the shards reach at most long_arm+2 px from each anchor.
    pixels = image.load()
    for ax, ay, dx, dy in corner_anchors:
        x0 = min(ax + dx * (long_arm + 2), ax - base_half - 1)
        x1 = max(ax + dx * (long_arm + 2), ax + base_half + 1)
        y0 = min(ay + dy * (long_arm + 2), ay - base_half - 1)
        y1 = max(ay + dy * (long_arm + 2), ay + base_half + 1)
        x0 = max(0, x0)
        y0 = max(0, y0)
        x1 = min(width - 1, x1)
        y1 = min(height - 1, y1)
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if (x + y) & 1 == 0 and pixels[x, y] == accent_color:
                    pixels[x, y] = SPECTRA6["white"]


def draw_chalkboard_border(image: Image.Image, colors: dict) -> None:
    """Paint a classroom-chalkboard surround: doubled white wooden frame,
    chalk dust in the bottom-left corner, a green-chalk check-mark in the
    upper-right margin, and coral eraser smudges along the bottom.

    * **Doubled wooden frame**: outer rectangle at inset 8, 3 px, plus an
      inner one at inset 18, 1 px. The ~7 px band between stays unfilled
      so the black ground reads as dark wood rather than a flat strip.
    * **Chalk-dust scatter**: a fixed stipple of 1 px white dots in the
      inner frame's bottom-left corner, where the chalk tray sits.
    * **Green-chalk check-mark**: a ``✓`` in solid Spectra-6 green at the
      upper-right inner margin. At y≈45, below the ``DEBUG MODE`` band
      (y=14-29), so ``chalkboard`` needs no ``_DEBUG_LABEL_RIGHT_INSET``
      entry. Solid, because a stippled green no longer reads as chalk.
    * **Coral eraser-smudge dots**: five small red dots along the bottom
      inner edge, half their pixels flipped to white on parity (the R+W
      1:1 coral recipe, as ``draw_placard_border``'s tacks).
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    frame_color = colors["text"]  # white chalk frame on the black slate
    accent_color = colors["accent"]  # yellow chalk-stick (matched phrase)
    chalk_green = SPECTRA6["green"]
    smudge_red = SPECTRA6["red"]

    # Outer thick wooden surround.
    outer_inset = 8
    draw.rectangle(
        (outer_inset, outer_inset, width - 1 - outer_inset, height - 1 - outer_inset),
        outline=frame_color,
        width=3,
    )
    # Inner thin frame — the inside lip of the wood.
    inner_inset = 18
    draw.rectangle(
        (inner_inset, inner_inset, width - 1 - inner_inset, height - 1 - inner_inset),
        outline=frame_color,
        width=1,
    )

    # Chalk-dust stipple inside the inner frame's BL corner, in a 40×30 px
    # box. Coordinates are fixed (not RNG'd) so every render is identical.
    bl_x = inner_inset + 4
    bl_y = height - 1 - inner_inset - 4
    chalk_offsets = (
        (0, 0),  (5, -2), (11, 0), (18, -3), (23, 1),
        (3, -8), (9, -7), (16, -9), (22, -7), (28, -10),
        (1, -14), (7, -16), (15, -15), (20, -19), (26, -17),
        (5, -22), (12, -23), (19, -24), (24, -26),
    )
    for dx, dy in chalk_offsets:
        cx = bl_x + dx
        cy = bl_y + dy
        # Single-pixel rectangle, not an ellipse, so PIL doesn't
        # anti-alias the dot into greys for snap_image_to_palette.
        draw.rectangle((cx, cy, cx, cy), fill=frame_color)

    # Green-chalk check-mark: a 5 px down-right stroke joining an 11 px
    # up-right one at the elbow, 2 px wide so it reads as a chalk swipe.
    # Below the debug-banner band, ending at x ≈ width-30 inside the frame.
    tick_elbow_x = width - 1 - inner_inset - 22
    tick_elbow_y = 50
    draw.line(
        ((tick_elbow_x - 5, tick_elbow_y - 5), (tick_elbow_x, tick_elbow_y)),
        fill=chalk_green,
        width=2,
    )
    draw.line(
        ((tick_elbow_x, tick_elbow_y), (tick_elbow_x + 11, tick_elbow_y - 12)),
        fill=chalk_green,
        width=2,
    )

    # Coral eraser smudges: five small circles 110 px apart at
    # y=height-inner-9, just inside the bottom of the inner frame. Painted
    # red; the post-pass below makes them coral (R+W 1:1).
    smudge_radius = 3
    smudge_centres = [
        (180 + i * 110, height - 1 - inner_inset - 9) for i in range(5)
    ]
    for cx, cy in smudge_centres:
        draw.ellipse(
            (cx - smudge_radius, cy - smudge_radius, cx + smudge_radius, cy + smudge_radius),
            fill=smudge_red,
        )

    # Coral post-pass (the ``draw_placard_border`` tack recipe),
    # bbox-scoped per smudge.
    pixels = image.load()
    for cx, cy in smudge_centres:
        x0 = max(0, cx - smudge_radius)
        y0 = max(0, cy - smudge_radius)
        x1 = min(width - 1, cx + smudge_radius)
        y1 = min(height - 1, cy + smudge_radius)
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if (x + y) & 1 == 0 and pixels[x, y] == smudge_red:
                    pixels[x, y] = SPECTRA6["white"]
    # Handwriting practice-guide rule in the top-left margin: solid top,
    # dashed midline, solid baseline, the ruling the Playwrite GB J Guides
    # face is designed around. In white chalk at y≈34-58 (above the y≥72
    # text) and on the left, clear of the right-aligned debug banner.
    guide_x0 = inner_inset + 12
    guide_x1 = guide_x0 + 210
    guide_top = 34
    guide_mid = 46
    guide_base = 58
    draw.line((guide_x0, guide_top, guide_x1, guide_top), fill=frame_color, width=1)
    draw.line((guide_x0, guide_base, guide_x1, guide_base), fill=frame_color, width=1)
    for dash_x in range(guide_x0, guide_x1, 12):  # dashed midline
        draw.line((dash_x, guide_mid, dash_x + 6, guide_mid), fill=frame_color, width=1)

    # Gold-star sticker just left of the check (tick + star): a small
    # five-point star in the accent, in the same y≈50 band, so still no
    # _DEBUG_LABEL_RIGHT_INSET entry.
    star_cx = tick_elbow_x - 40
    star_cy = tick_elbow_y - 4
    star_r = 9
    star_pts = []
    for k in range(10):
        ang = -math.pi / 2 + k * math.pi / 5
        rr = star_r if k % 2 == 0 else star_r * 0.42
        star_pts.append((star_cx + rr * math.cos(ang), star_cy + rr * math.sin(ang)))
    draw.polygon(star_pts, fill=accent_color)

    # The accent is not used past the star.
    del accent_color


def draw_placard_border(image: Image.Image, colors: dict) -> None:
    """Paint a hand-painted shop-sign / sandwich-board surround: doubled
    sign-painter's frame (sepia outer + black inner) plus four red
    thumbtack corner accents.

    * **Sepia outer frame**: rectangle at inset 14, painted red, then half
      its perimeter pixels flipped to green on ``(x+y)&1`` parity (the R+G
      1:1 rust-brown recipe ``saloon``'s foxing uses), weathered wood.
    * **Inner black frame**: inset 18, 1 px, ``colors["text"]``. The ~3 px
      gap reads as a doubled brush stroke.
    * **Coral thumbtack corner accents**: four small ``colors["accent"]``
      circles just inside each corner, half flipped to white on parity
      (R+W 1:1 coral): faded sign red.
    * **Sign-painter header + footer dividers**: a short centred black rule
      carrying a small coral diamond. Header at y≈34 (above the y≥72 text);
      footer centred, clear of the bottom-left attribution.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    frame_color = colors["text"]
    accent_color = colors["accent"]

    # Outer frame painted red as a sentinel, so the post-pass below can
    # find its pixels without coordinate bookkeeping; the green flip turns
    # it sepia.
    outer_inset = 14
    draw.rectangle(
        (outer_inset, outer_inset, width - 1 - outer_inset, height - 1 - outer_inset),
        outline=SPECTRA6["red"],
        width=1,
    )
    inner_inset = 18
    draw.rectangle(
        (inner_inset, inner_inset, width - 1 - inner_inset, height - 1 - inner_inset),
        outline=frame_color,
        width=1,
    )

    # Sepia post-pass: walk the outer frame's perimeter only (a bbox walk
    # would touch interior pixels) and flip red→green on (x+y)&1.
    pixels = image.load()
    outer_x0, outer_y0 = outer_inset, outer_inset
    outer_x1, outer_y1 = width - 1 - outer_inset, height - 1 - outer_inset
    for x in range(outer_x0, outer_x1 + 1):
        for y in (outer_y0, outer_y1):
            if (x + y) & 1 == 0 and pixels[x, y] == SPECTRA6["red"]:
                pixels[x, y] = SPECTRA6["green"]
    for y in range(outer_y0 + 1, outer_y1):
        for x in (outer_x0, outer_x1):
            if (x + y) & 1 == 0 and pixels[x, y] == SPECTRA6["red"]:
                pixels[x, y] = SPECTRA6["green"]
    # ``frame_color`` (black) was only needed for the inner rule.
    del frame_color

    # Red thumbtacks at the inner corners. Centre y=38, radius 4 → bbox
    # y=34-42, so the TR tack sits fully below the y=14-29 debug-label band.
    tack_radius = 4
    tack_inset = 38
    tack_centres = [
        (tack_inset, tack_inset),
        (width - 1 - tack_inset, tack_inset),
        (tack_inset, height - 1 - tack_inset),
        (width - 1 - tack_inset, height - 1 - tack_inset),
    ]
    for cx, cy in tack_centres:
        draw.ellipse(
            (cx - tack_radius, cy - tack_radius, cx + tack_radius, cy + tack_radius),
            fill=accent_color,
        )

    # Weathered-paint post-pass: flip ~50% of each tack's red pixels to
    # white on a 1×1 checkerboard (R+W coral). Bbox-scoped per tack.
    pixels = image.load()
    for cx, cy in tack_centres:
        x0 = max(0, cx - tack_radius)
        y0 = max(0, cy - tack_radius)
        x1 = min(width - 1, cx + tack_radius)
        y1 = min(height - 1, cy + tack_radius)
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if (x + y) & 1 == 0 and pixels[x, y] == accent_color:
                    pixels[x, y] = SPECTRA6["white"]

    # Header + footer dividers (see docstring): black rules plus a red
    # diamond the coral post-pass below weathers to match the tacks.
    ink = colors["text"]
    div_cx = width // 2
    head_y = inner_inset + 16
    foot_y = height - 1 - inner_inset - 16
    new_red_centres = []
    for dy in (head_y, foot_y):
        draw.line([(div_cx - 80, dy), (div_cx - 10, dy)], fill=ink, width=1)
        draw.line([(div_cx + 10, dy), (div_cx + 80, dy)], fill=ink, width=1)
        draw.polygon([(div_cx, dy - 4), (div_cx + 4, dy), (div_cx, dy + 4), (div_cx - 4, dy)], fill=accent_color)
        new_red_centres.append((div_cx, dy))

    # Coral post-pass on the new divider diamonds (R+W checkerboard, the
    # same weathered-coral recipe the corner tacks use).
    for cx, cy in new_red_centres:
        for y in range(cy - 5, cy + 6):
            for x in range(cx - 6, cx + 7):
                if 0 <= x < width and 0 <= y < height and (x + y) & 1 == 0 and pixels[x, y] == accent_color:
                    pixels[x, y] = SPECTRA6["white"]

    # Side-margin hanging price tags: a short black rule dropping to a
    # small coral diamond at each left/right mid-edge, carrying the
    # divider vocabulary into the side margins. At x≈inner_inset+10 /
    # width-inner_inset-10, clear of the body (dense layout starts x≥60).
    side_tag_centres = []
    cy_mid = height // 2
    for edge_x, hdir in ((inner_inset + 10, 1), (width - 1 - inner_inset - 10, -1)):
        # Short vertical rule from above the diamond down to it.
        draw.line([(edge_x, cy_mid - 20), (edge_x, cy_mid - 5)], fill=ink, width=1)
        draw.polygon(
            [(edge_x, cy_mid - 5), (edge_x + 5, cy_mid), (edge_x, cy_mid + 5), (edge_x - 5, cy_mid)],
            fill=accent_color,
        )
        side_tag_centres.append((edge_x, cy_mid))
    # Coral post-pass on the side-tag diamonds (same R+W recipe).
    for cx, cy in side_tag_centres:
        for y in range(cy - 6, cy + 7):
            for x in range(cx - 7, cx + 8):
                if 0 <= x < width and 0 <= y < height and (x + y) & 1 == 0 and pixels[x, y] == accent_color:
                    pixels[x, y] = SPECTRA6["white"]


def draw_chanbara_border(image: Image.Image, colors: dict) -> None:
    """Paint a samurai-cinema title-card surround: large off-canvas
    rising-sun disc with a red-to-maroon radial edge gradient, plus a
    small maroon artist's-chop seal in the top-left corner.

    * **Rising-sun disc**: a filled ``colors["accent"]`` (red) circle,
      centre ``(width + 30, height + 30)``, radius 220; PIL clips the
      off-canvas part, leaving an arc through the bottom-right quadrant.
      A radial post-pass then flips half the red pixels in the outer
      40 px shell to black on ``(x+y)&1`` parity (R+K 1:1 maroon), so the
      disc darkens from vermilion to oxblood at the rim. White text reads
      on both. Pinned bottom-right so the top-right stays clear of the
      ``DEBUG MODE`` banner.
    * **Artist's chop seal**: a 28×36 px red rectangle at ``(24, 24)``,
      maroon-post-passed the same way (an aged hanko). Its white "ichi"
      stroke is painted *after* the post-pass so it stays solid.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    accent_color = colors["accent"]
    light_color = colors.get("ornament_light", SPECTRA6["white"])

    # Large rising-sun disc anchored off-canvas in the bottom-right; only
    # its upper-left arc lands on the canvas.
    sun_cx = width + 30
    sun_cy = height + 30
    sun_radius = 220
    draw.ellipse(
        (sun_cx - sun_radius, sun_cy - sun_radius,
         sun_cx + sun_radius, sun_cy + sun_radius),
        fill=accent_color,
    )

    # Radial maroon post-pass on the disc's outer 40 px shell, restricted
    # to the BR quadrant (the only place the disc paints). Squared
    # distances avoid a sqrt() per pixel.
    sentinel_red = SPECTRA6["red"]
    maroon_dark = SPECTRA6["black"]
    pixels = image.load()
    inner_r_sq = (sun_radius - 40) * (sun_radius - 40)
    outer_r_sq = sun_radius * sun_radius
    quad_x0 = width // 2
    quad_y0 = height // 2
    for py in range(quad_y0, height):
        dy = py - sun_cy
        dy_sq = dy * dy
        for px in range(quad_x0, width):
            dx = px - sun_cx
            d_sq = dx * dx + dy_sq
            if inner_r_sq <= d_sq <= outer_r_sq:
                if (px + py) & 1 == 0 and pixels[px, py] == sentinel_red:
                    pixels[px, py] = maroon_dark

    # Artist's chop seal: a red rectangle, sentinel for the post-pass below.
    chop_left = 24
    chop_top = 24
    chop_w = 28
    chop_h = 36
    chop_right = chop_left + chop_w
    chop_bottom = chop_top + chop_h
    draw.rectangle(
        (chop_left, chop_top, chop_right, chop_bottom),
        fill=accent_color,
    )

    # Maroon post-pass on the chop seal's bbox (the disc-rim recipe),
    # clipped to the image bounds for small preview canvases.
    for py in range(chop_top, min(chop_bottom + 1, height)):
        for px in range(chop_left, min(chop_right + 1, width)):
            if (px + py) & 1 == 0 and pixels[px, py] == sentinel_red:
                pixels[px, py] = maroon_dark

    # White "ichi" stroke through the chop's centre, painted after the
    # post-pass so it lands solid; inset 5 px from each side so it reads
    # as a mark, not a bisection.
    stroke_y = chop_top + chop_h // 2
    draw.line(
        [(chop_left + 5, stroke_y), (chop_right - 5, stroke_y)],
        fill=light_color,
        width=2,
    )

    # Vertical brush-tick column in the left margin, the signature / date
    # column a samurai-cinema poster runs beside the seal: five uneven
    # sumi strokes, red sentinel then maroon post-pass to match the chop.
    # At x≈14-40, y≈196-280: below the oversized opening quote mark
    # (y≈20-140), and left of the body (dense layout starts at x≥60).
    tick_cx = chop_left + chop_w // 2
    tick_specs = ((196, 11), (212, 9), (228, 12), (244, 8), (260, 10))
    for ty, half in tick_specs:
        draw.line([(tick_cx - half, ty), (tick_cx + half, ty)], fill=sentinel_red, width=2)
    # Ink-spatter flecks trailing off the lowest ticks (same sentinel).
    for fx, fy in ((tick_cx + 15, 266), (tick_cx - 13, 272), (tick_cx + 6, 278)):
        draw.ellipse((fx - 1, fy - 1, fx + 1, fy + 1), fill=sentinel_red)
    # Maroon post-pass over the brush-tick column bbox (x±18, y 188-282).
    col_x0 = max(0, tick_cx - 18)
    col_x1 = min(width - 1, tick_cx + 18)
    for py in range(188, min(283, height)):
        for px in range(col_x0, col_x1 + 1):
            if (px + py) & 1 == 0 and pixels[px, py] == sentinel_red:
                pixels[px, py] = maroon_dark


# R+B+W 3-way Bayer cuts on ``BAYER_4x4`` (cells below the first → red, below
# the second → blue, the rest → white). Lavender is 5/5/6; lilac 4/4/8 is
# paler, with a heavier white lift.
_LCARS_LAVENDER_CUTS = (5, 10)
_LCARS_LILAC_CUTS = (4, 8)


def _lcars_paint_rbw_block(pixels, left: int, top: int, right: int, bot: int,
                           sentinel, cuts: tuple[int, int]) -> None:
    """3-way Bayer post-pass of ``sentinel`` pixels to red / blue / white at
    ``cuts`` (``_LCARS_LAVENDER_CUTS`` or ``_LCARS_LILAC_CUTS``). ``sentinel``
    must be off-palette (``(1, 1, 1)``). Bbox-scoped so neighbouring blocks in
    other sentinels stay untouched."""
    ink_red = SPECTRA6["red"]
    ink_blue = SPECTRA6["blue"]
    ink_white = SPECTRA6["white"]
    red_cut, blue_cut = cuts
    for py in range(top, bot + 1):
        row = BAYER_4x4[py % 4]
        for px in range(left, right + 1):
            if pixels[px, py] == sentinel:
                cell = row[px % 4]
                if cell < red_cut:
                    pixels[px, py] = ink_red
                elif cell < blue_cut:
                    pixels[px, py] = ink_blue
                else:
                    pixels[px, py] = ink_white


def _lcars_post_pass_tangerine(pixels, left: int, top: int, right: int, bot: int,
                               sentinel_red) -> None:
    """Bbox-scoped R+Y biased Bayer: ~3/8 yellow on red. Threshold and
    phase match ``draw_deco_border``'s final pass and ``_draw_text_body``'s
    ``deco`` branch, so all three land on one tangerine. Only touches
    ``sentinel_red`` pixels."""
    yellow = SPECTRA6["yellow"]
    threshold = 6  # round(0.375 * 16)
    for y in range(top, bot + 1):
        row = BAYER_4x4[y % 4]
        for x in range(left, right + 1):
            if row[x % 4] < threshold and pixels[x, y] == sentinel_red:
                pixels[x, y] = yellow


def _lcars_post_pass_coral(pixels, left: int, top: int, right: int, bot: int,
                           sentinel_red) -> None:
    """Bbox-scoped R+W 50/50 checkerboard (coral). Only touches
    ``sentinel_red`` pixels, so solid red elsewhere stays saturated."""
    white = SPECTRA6["white"]
    for py in range(top, bot + 1):
        for px in range(left, right + 1):
            if (px + py) & 1 and pixels[px, py] == sentinel_red:
                pixels[px, py] = white


def draw_lcars_border(image: Image.Image, colors: dict) -> None:
    """Paint a Michael Okuda LCARS interface frame: an L of chrome down the
    left edge and along the top and bottom, rounded where it wraps each
    canvas corner, with a stack of coloured rail blocks and an "LCARS"
    wordmark.

    * **Bars and elbows.** ``T`` (44 px at 800×480) is both the bar
      thickness and the rail width. The top bar (y = 0..T-1) is split into
      a tangerine segment and a lavender one with a small black gap; the
      bottom bar is one tangerine ribbon. Each corner is an annular
      quarter-circle elbow: outer radius ``R_out``, inner radius
      ``R_in = R_out - T``, common centre ``(R_out, R_out)`` (mirrored at
      the bottom), so the chrome has uniform thickness T.
    * **Tangerine.** Spectra 6 has no orange. The chrome is painted in
      ``ornament_dark`` (red) and ~3/8 of it flipped to yellow on
      ``BAYER_4x4`` (cells < 6), as ``draw_deco_border`` does; a 50/50 mix
      reads as washed-out amber. Bbox-scoped, so the body is untouched.
    * **Seven rail blocks** between the elbows, plain rectangles within the
      rail column, separated by black gaps: lavender, yellow, coral, lilac,
      red, coral, blue, with uneven heights. Lavender / lilac are 3-ink
      R+B+W stipples and coral is R+W 1:1 (sentinel + bbox post-pass, see
      ``spectra6_color_recipes.md``).
    * **Block labels**: short fixed numeric codes in black, right-aligned
      in each block.
    * **"LCARS" wordmark** right-aligned in the top bar's lavender
      segment, and a **"STARDATE" callout** in the bottom bar, both black
      in the ornament face (Antonio Bold).

    The top bar spans the y = 14..29 ``DEBUG MODE`` band, so in debug mode
    the yellow label sits on the chrome (reduced contrast, still legible;
    production has no label). ``lcars`` has no ``_DEBUG_LABEL_RIGHT_INSET``
    entry.

    The rail column is x = 0..T-1 (0..43); the widest body (``dense``,
    ``max_width`` 680) starts at x = 60, so rail and text never meet.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size

    # Chrome is painted in ``ornament_dark`` (red) as a sentinel; the
    # tangerine / coral post-passes convert it. Labels on the blocks are
    # black, the Okudagram contrast.
    sentinel_red = colors["ornament_dark"]
    label_ink_on_block = SPECTRA6["black"]

    # --- Geometry ---
    # Every constant scales with the canvas: ``/api/preview`` calls this at
    # sizes down to ``PREVIEW_MIN_*`` = 80×60, and fixed native constants
    # would invert PIL bboxes (``rail_top > rail_bot``) and 500 the
    # endpoint. Below scale 0.5 the chrome is sub-pixel, so paint nothing.
    scale = min(width / 800.0, height / 480.0)
    if scale < 0.5:
        return
    # ``T`` is both bar thickness and rail width; the annular elbow needs
    # them equal so R_out − R_in matches both. ``R_out`` sets how rounded
    # the canvas-corner curve is.
    T = max(8, int(round(44 * scale)))
    bar_thickness = T
    rail_width = T
    R_out = max(16, int(round(72 * scale)))   # outer elbow radius
    R_in = R_out - T                           # derived
    # Rail blocks are plain rectangles confined to the rail column, so they
    # read as flush sidebar segments rather than floating pill buttons.
    block_right = rail_width - 1

    top_bar_y1 = 0
    top_bar_y2 = bar_thickness - 1
    bottom_bar_y2 = height - 1
    bottom_bar_y1 = bottom_bar_y2 - bar_thickness + 1

    page_bg = colors.get("page_bg", SPECTRA6["black"])
    lavender_sentinel = (1, 1, 1)

    # ===========================================================
    # Layer 1: paint top/bottom bars + rail straight runs
    # ===========================================================
    # The straight runs start at ``R_out``: x, y ∈ [0, R_out) is the
    # elbow's footprint, painted in Layer 2. The top bar is two segments
    # with a ~6 px black divider.
    segment_gap = max(2, int(round(6 * scale)))
    top_bar_left = R_out
    top_bar_right = width - 1
    top_bar_inner_w = top_bar_right - top_bar_left + 1
    seg1_w = int(top_bar_inner_w * 0.55)
    seg1_left = top_bar_left
    seg1_right = seg1_left + seg1_w - 1
    seg2_left = seg1_right + 1 + segment_gap
    seg2_right = top_bar_right
    # First (tangerine) segment of the top bar.
    draw.rectangle(
        (seg1_left, top_bar_y1, seg1_right, top_bar_y2),
        fill=sentinel_red,
    )
    # Second (lavender) segment of the top bar.
    draw.rectangle(
        (seg2_left, top_bar_y1, seg2_right, top_bar_y2),
        fill=lavender_sentinel,
    )
    # Bottom bar: one tangerine ribbon from R_out, clear of the elbow; the
    # STARDATE callout gives it weight.
    draw.rectangle(
        (R_out, bottom_bar_y1, width - 1, bottom_bar_y2),
        fill=sentinel_red,
    )
    # No uniform rail strip: the straight rail between the elbows is only
    # the stacked blocks, with black gaps as separators. A tangerine strip
    # under them would swallow any warm block.

    # ===========================================================
    # Layer 2: annular-quadrant elbows (BOTH outer + inner rounded)
    # ===========================================================
    # Each elbow is the annulus between two concentric quarter-circles
    # centred at (R_out, R_out) (top elbow): the outer arc (radius R_out)
    # rounds the canvas corner, the inner arc (radius R_in = R_out − T)
    # rounds the page-interior side.
    #
    # Paint the outer-disc quadrant in the sentinel, then carve the inner
    # one in page_bg. For the top-left quadrant the pieslice angles run
    # 180° → 270°.
    # Top elbow:
    draw.pieslice(
        (0, 0, 2 * R_out - 1, 2 * R_out - 1),
        start=180, end=270,
        fill=sentinel_red,
    )
    if R_in > 0:
        draw.pieslice(
            (T, T, 2 * R_out - T - 1, 2 * R_out - T - 1),
            start=180, end=270,
            fill=page_bg,
        )
    # Bottom elbow, mirrored: centre (R_out, height - R_out), angles
    # 90° → 180°.
    bottom_disc_y1 = height - 2 * R_out
    bottom_disc_y2 = height - 1
    draw.pieslice(
        (0, bottom_disc_y1, 2 * R_out - 1, bottom_disc_y2),
        start=90, end=180,
        fill=sentinel_red,
    )
    if R_in > 0:
        draw.pieslice(
            (T, bottom_disc_y1 + T, 2 * R_out - T - 1, bottom_disc_y2 - T),
            start=90, end=180,
            fill=page_bg,
        )

    # ===========================================================
    # Layer 2: rail blocks between the two elbows
    # ===========================================================
    # Seven blocks; the stippled tones are off the native palette and need
    # sentinel paint + bbox post-pass, hence the ``_lcars_paint_*`` helpers.
    # The rail's straight section runs y ∈ [R_out, height − R_out − 1],
    # with a 3 px gutter at each end so the end blocks don't merge into the
    # elbow arcs.
    rail_gutter = max(1, int(round(3 * scale)))
    rail_top = R_out + rail_gutter
    rail_bot = height - R_out - rail_gutter - 1
    rail_height = rail_bot - rail_top + 1
    block_gap = max(1, int(round(3 * scale)))
    # ``block_specs`` is (kind, label, proportion of height); the
    # proportions sum to 1.0 and vary on purpose, as LCARS block heights
    # did. Labels stay at 3-5 chars: the block is only ~rail_width wide
    # and a longer code clips at the left edge.
    # No tangerine / peach blocks: they share R+Y pixels with the chrome
    # and vanish into it. The mix is pastel stipples (lavender, lilac,
    # coral) plus native red / yellow / blue (critical / advisory /
    # informational in LCARS convention).
    block_specs = [
        ("lavender", "40-27", 0.14),
        ("yellow",   "65-54", 0.16),
        ("coral",    "97-56", 0.13),
        ("lilac",    "76-54", 0.16),
        ("red",      "22-43", 0.13),
        ("coral",    "57-65", 0.15),
        ("blue",     "18-82", 0.13),
    ]
    assert abs(sum(p for _, _, p in block_specs) - 1.0) < 1e-6
    available_v = rail_height - block_gap * (len(block_specs) - 1)
    pixels = image.load()
    blocks: list[tuple[int, int, int, int, str]] = []
    cursor_y = rail_top
    for kind, label, prop in block_specs:
        bh = int(round(available_v * prop))
        top = cursor_y
        bot = cursor_y + bh - 1
        left = 0
        right = block_right
        # Native-ink blocks fill directly; stippled ones paint a sentinel
        # and convert it with a per-block bbox post-pass.
        if kind == "coral":
            draw.rectangle((left, top, right, bot), fill=sentinel_red)
            _lcars_post_pass_coral(pixels, left, top, right, bot, sentinel_red)
        elif kind == "lavender":
            draw.rectangle((left, top, right, bot), fill=lavender_sentinel)
            _lcars_paint_rbw_block(pixels, left, top, right, bot, lavender_sentinel, _LCARS_LAVENDER_CUTS)
        elif kind == "lilac":
            draw.rectangle((left, top, right, bot), fill=lavender_sentinel)
            _lcars_paint_rbw_block(pixels, left, top, right, bot, lavender_sentinel, _LCARS_LILAC_CUTS)
        elif kind == "yellow":
            draw.rectangle((left, top, right, bot), fill=SPECTRA6["yellow"])
        elif kind == "red":
            # Solid red is unambiguous here: the tangerine chrome is
            # separated from this block by a gap and the elbow geometry.
            draw.rectangle((left, top, right, bot), fill=SPECTRA6["red"])
        elif kind == "blue":
            draw.rectangle((left, top, right, bot), fill=SPECTRA6["blue"])
        blocks.append((left, top, right, bot, label))
        cursor_y += bh + block_gap

    # ===========================================================
    # Layer 3: convert the chrome sentinels to tangerine + lavender
    # ===========================================================
    # Convert the chrome's sentinel red (top-bar left segment, bottom
    # bar, both elbows) to tangerine in two sweeps over the chrome's y
    # extent; the rail blocks lie outside both sweeps. The lavender
    # top-bar segment uses another sentinel and gets its own pass.
    # Top region: covers the top bar + the entire top elbow annulus.
    _lcars_post_pass_tangerine(pixels, 0, top_bar_y1, width - 1, R_out - 1, sentinel_red)
    # Bottom region: covers the bottom bar + the entire bottom elbow.
    _lcars_post_pass_tangerine(pixels, 0, height - R_out, width - 1, bottom_bar_y2, sentinel_red)
    # Lavender segment of the top bar.
    _lcars_paint_rbw_block(pixels, seg2_left, top_bar_y1, seg2_right, top_bar_y2, lavender_sentinel,
                           _LCARS_LAVENDER_CUTS)

    # ===========================================================
    # Layer 4: black labels centred inside each block
    # ===========================================================
    block_label_font = load_font(META_FONT_BOLD_CANDIDATES, max(6, int(round(10 * scale))))
    label_pad_right = 4   # inset from the block's right edge
    for left, top, right, bot, label in blocks:
        baseline_bbox = draw.textbbox((0, 0), label, font=block_label_font)
        label_w = baseline_bbox[2] - baseline_bbox[0]
        label_h = baseline_bbox[3] - baseline_bbox[1]
        # Right-align inside the block.
        label_x = right - label_pad_right - label_w - baseline_bbox[0]
        label_y = top + (bot - top - label_h) // 2 - baseline_bbox[1]
        draw.text(
            (label_x, label_y),
            label,
            font=block_label_font,
            fill=label_ink_on_block,
        )

    # ===========================================================
    # Layer 5: large "LCARS" wordmark in the top bar
    # ===========================================================
    # Right-aligned inside the top bar's lavender segment, black on
    # lavender, sized to most of the bar height.
    wordmark_font = load_font(theme_font_candidates("lcars", "ornament"), max(10, int(round(26 * scale))))
    wordmark_text = "LCARS"
    wordmark_bbox = draw.textbbox((0, 0), wordmark_text, font=wordmark_font)
    wordmark_w = wordmark_bbox[2] - wordmark_bbox[0]
    wordmark_h = wordmark_bbox[3] - wordmark_bbox[1]
    wordmark_x = width - 16 - wordmark_w
    wordmark_y = top_bar_y1 + (bar_thickness - wordmark_h) // 2 - wordmark_bbox[1]
    draw.text(
        (wordmark_x, wordmark_y),
        wordmark_text,
        font=wordmark_font,
        fill=label_ink_on_block,
    )

    # ===========================================================
    # Layer 6: bottom-right "STARDATE" callout
    # ===========================================================
    # A secondary heading at the bottom right (the reference wallpaper's
    # "DATA NODE 188"), black on the tangerine bottom bar, smaller than
    # the wordmark so the string fits the bar.
    stardate_font = load_font(theme_font_candidates("lcars", "ornament"), max(7, int(round(14 * scale))))
    stardate_text = "STARDATE 47988.1"
    sd_bbox = draw.textbbox((0, 0), stardate_text, font=stardate_font)
    sd_w = sd_bbox[2] - sd_bbox[0]
    sd_h = sd_bbox[3] - sd_bbox[1]
    sd_x = width - 16 - sd_w
    sd_y = bottom_bar_y1 + (bar_thickness - sd_h) // 2 - sd_bbox[1]
    draw.text(
        (sd_x, sd_y),
        stardate_text,
        font=stardate_font,
        fill=label_ink_on_block,
    )


def draw_dispatch_border(image: Image.Image, colors: dict) -> None:
    """Paint a vintage-office dispatch border: cream-washed ground +
    thin frame + alternating black/sepia tractor-feed perforations +
    maroon rubber-stamp imprint.

    * **Layer 0: sparse cream ground wash.** A 4×4 Bayer dither turns
      ~12.5% of the white ``page_bg`` pixels yellow, which averages to aged
      manila paper. Every pixel stays a pure ink, so palette-snap is a
      no-op and glyph edges stay crisp.
    * **Outer thin black frame**, like a typed memo's letterhead rule.
    * **Tractor-feed perforations**: a column of small dots ~40 px apart
      in each side margin. Every other pair is sepia (red sentinel, half
      flipped to green on parity, R+G 1:1) instead of black, as carbon
      bleed.
    * **Maroon rubber stamp** in the upper right at y≈40–70 (below the
      debug-label band, clear of the opening quote mark and the text):
      two concentric ellipses and four hatch lines, no lettering. Red
      sentinel, half flipped to black on ``(x+y)&1`` (R+K 1:1 maroon).
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    ink = colors["text"]
    page_bg = colors.get("page_bg")
    cream_light = SPECTRA6["yellow"]
    sepia_light = SPECTRA6["green"]
    sentinel_red = SPECTRA6["red"]
    maroon_dark = SPECTRA6["black"]

    # Layer 0: sparse 1-in-8 yellow-on-white Bayer cream wash. Only exact
    # ``page_bg`` pixels are touched, in case a caller painted accents first.
    pixels = image.load()
    if page_bg is not None:
        for y in range(height):
            row = BAYER_4x4[y & 3]
            for x in range(width):
                if pixels[x, y] == page_bg and row[x & 3] < 2:
                    pixels[x, y] = cream_light

    # Outer thin frame.
    frame_inset = 14
    draw.rectangle(
        (frame_inset, frame_inset, width - 1 - frame_inset, height - 1 - frame_inset),
        outline=ink,
        width=1,
    )

    # Tractor-feed perforations on both side margins. Every other pair is
    # painted in a red sentinel that the post-pass below turns sepia.
    hole_radius = 2
    hole_spacing = 40
    hole_top = 22
    hole_bottom = height - 22
    left_x = 7
    right_x = width - 1 - 7
    sepia_centres: list[tuple[int, int]] = []
    y = hole_top
    pair_idx = 0
    while y <= hole_bottom:
        if pair_idx & 1:
            fill = sentinel_red
            sepia_centres.append((left_x, y))
            sepia_centres.append((right_x, y))
        else:
            fill = ink
        draw.ellipse(
            (left_x - hole_radius, y - hole_radius, left_x + hole_radius, y + hole_radius),
            fill=fill,
        )
        draw.ellipse(
            (right_x - hole_radius, y - hole_radius, right_x + hole_radius, y + hole_radius),
            fill=fill,
        )
        y += hole_spacing
        pair_idx += 1

    # Sepia post-pass on the alternating perforations only.
    for cx, cy in sepia_centres:
        x0 = max(0, cx - hole_radius)
        y0 = max(0, cy - hole_radius)
        x1 = min(width - 1, cx + hole_radius)
        y1 = min(height - 1, cy + hole_radius)
        for py in range(y0, y1 + 1):
            for px in range(x0, x1 + 1):
                if (px + py) & 1 == 0 and pixels[px, py] == sentinel_red:
                    pixels[px, py] = sepia_light

    # Maroon rubber-stamp imprint: two concentric ellipse outlines plus
    # short diagonal hatch lines, painted in red as a sentinel.
    stamp_cx = width - 55
    stamp_cy = 55
    outer_hw, outer_hh = 25, 15
    inner_hw, inner_hh = 19, 10
    draw.ellipse(
        (stamp_cx - outer_hw, stamp_cy - outer_hh, stamp_cx + outer_hw, stamp_cy + outer_hh),
        outline=sentinel_red,
        width=1,
    )
    draw.ellipse(
        (stamp_cx - inner_hw, stamp_cy - inner_hh, stamp_cx + inner_hw, stamp_cy + inner_hh),
        outline=sentinel_red,
        width=1,
    )
    for dx in (-9, -3, 3, 9):
        draw.line(
            (stamp_cx + dx - 3, stamp_cy + 3, stamp_cx + dx + 3, stamp_cy - 3),
            fill=sentinel_red,
            width=1,
        )

    # Maroon post-pass on the stamp's bbox only.
    stamp_x0 = max(0, stamp_cx - outer_hw - 1)
    stamp_y0 = max(0, stamp_cy - outer_hh - 1)
    stamp_x1 = min(width - 1, stamp_cx + outer_hw + 1)
    stamp_y1 = min(height - 1, stamp_cy + outer_hh + 1)
    for py in range(stamp_y0, stamp_y1 + 1):
        for px in range(stamp_x0, stamp_x1 + 1):
            if (px + py) & 1 == 0 and pixels[px, py] == sentinel_red:
                pixels[px, py] = maroon_dark

    # Two-hole filing punch centred in the top margin: two thin black
    # rings at y≈40, below the y=14-29 debug-banner band and above the text
    # (y≥72), clear of the side perforations and the stamp.
    punch_y = 40
    punch_r = 7
    punch_gap = 46
    cx0 = width // 2
    for hole_cx in (cx0 - punch_gap, cx0 + punch_gap):
        draw.ellipse(
            (hole_cx - punch_r, punch_y - punch_r, hole_cx + punch_r, punch_y + punch_r),
            outline=ink,
            width=1,
        )

    # Typed "— FILE COPY —" footer in the theme's typewriter face, centred
    # (clear of the bottom-left attribution) inside the frame below the
    # quote.
    footer_font = load_font(theme_font_candidates("dispatch", "quote_regular"), size=14)
    footer_text = "— FILE COPY —"
    fb = draw.textbbox((0, 0), footer_text, font=footer_font)
    fw = fb[2] - fb[0]
    footer_y = height - 1 - frame_inset - 18
    draw.text((cx0 - fw // 2 - fb[0], footer_y), footer_text, font=footer_font, fill=ink)

    # The accent slot is unused: the stamp and perforations use sentinels.
    accent = colors["accent"]
    del accent


def draw_atomic_border(image: Image.Image, colors: dict) -> None:
    """Atomic-age decorative border: dithered ground + rounded frame + atom + starbursts.

    * **Layer 0: sparse 1-in-4 white-on-green dither ground.** The
      top-left pixel of every 2×2 tile that matches ``page_bg`` becomes
      white; the 25/75 mix reads as a softer Sputnik green, greener than
      a 50/50 checkerboard. Painted first so the decoration overpaints it.
      Every pixel stays a pure ink, so ``snap_image_to_palette`` is a
      no-op and glyph edges stay sharp (the ``alchemy`` halftone trick).
    * **Rounded-corner outer frame** in red, Googie curve language.
    * **Atom symbol** centred at the top: three ellipse orbits (0°, 60°,
      120°) and a red nucleus. PIL can't rotate an ellipse, so each orbit
      is a 64-point polyline rotated by hand. At y=44 with semi-major 24,
      it fits above the text (block_top ≥ 72); centred, it misses the
      right-aligned ``DEBUG MODE`` banner.
    * **Twin starbursts** at the left and right mid-edges: eight rays from
      a small dot, outside the centred text block.

    Decoration uses the theme's ``accent`` (red), except the starbursts and
    bottom boomerang, which are stippled to tangerine.
    """
    width, height = image.size
    page_bg = colors["page_bg"]
    accent = colors["accent"]

    # Layer 0: sparse 1-in-4 white-on-green dither (one white pixel per
    # 2×2 tile). Only exact ``page_bg`` pixels are touched.
    dither_light = SPECTRA6["white"]
    pixels = image.load()
    for y in range(height):
        for x in range(width):
            if (x & 1) == 0 and (y & 1) == 0 and pixels[x, y] == page_bg:
                pixels[x, y] = dither_light

    draw = ImageDraw.Draw(image)

    # Rounded outer frame.
    frame_inset = 14
    frame_radius = 24
    draw.rounded_rectangle(
        (frame_inset, frame_inset, width - 1 - frame_inset, height - 1 - frame_inset),
        radius=frame_radius,
        outline=accent,
        width=2,
    )

    # Atom symbol: three rotated ellipse outlines + nucleus.
    atom_cx = width // 2
    atom_cy = 44
    orbit_a = 24  # semi-major axis (fits below frame at y=14, above quote_top ≥ 72)
    orbit_b = 8
    n_points = 64
    for angle_deg in (0, 60, 120):
        angle = math.radians(angle_deg)
        cos_a = math.cos(angle)
        sin_a = math.sin(angle)
        points = []
        for i in range(n_points + 1):
            t = 2.0 * math.pi * i / n_points
            x_unrot = orbit_a * math.cos(t)
            y_unrot = orbit_b * math.sin(t)
            px = atom_cx + x_unrot * cos_a - y_unrot * sin_a
            py = atom_cy + x_unrot * sin_a + y_unrot * cos_a
            points.append((px, py))
        draw.line(points, fill=accent, width=1)
    # Nucleus.
    nucleus_r = 4
    draw.ellipse(
        (atom_cx - nucleus_r, atom_cy - nucleus_r, atom_cx + nucleus_r, atom_cy + nucleus_r),
        fill=accent,
    )

    # Twin starbursts at the mid-edges, painted in a red sentinel; the
    # post-pass below flips ~3/8 to yellow (R+Y 5/8:3/8 tangerine, as
    # ``deco``'s matched phrase). The atom stays solid red: solid orbits
    # against warm-stippled rays.
    starburst_outer = 11
    starburst_inner = 4
    centres = ((34, height // 2), (width - 34, height // 2))
    for star_cx, star_cy in centres:
        for angle_deg in range(0, 360, 45):
            angle = math.radians(angle_deg)
            cos_a = math.cos(angle)
            sin_a = math.sin(angle)
            x1 = star_cx + starburst_inner * cos_a
            y1 = star_cy + starburst_inner * sin_a
            x2 = star_cx + starburst_outer * cos_a
            y2 = star_cy + starburst_outer * sin_a
            draw.line((x1, y1, x2, y2), fill=SPECTRA6["red"], width=1)
        # Centre dot.
        draw.ellipse(
            (star_cx - 2, star_cy - 2, star_cx + 2, star_cy + 2),
            fill=SPECTRA6["red"],
        )

    # Tangerine post-pass, bbox-scoped per starburst; only sentinel-red
    # pixels flip, so the green ground and its white flecks pass through.
    sentinel_red = SPECTRA6["red"]
    flip_yellow = SPECTRA6["yellow"]
    for star_cx, star_cy in centres:
        x0 = max(0, star_cx - starburst_outer)
        y0 = max(0, star_cy - starburst_outer)
        x1 = min(width - 1, star_cx + starburst_outer)
        y1 = min(height - 1, star_cy + starburst_outer)
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if BAYER_4x4[y & 3][x & 3] < 6 and pixels[x, y] == sentinel_red:
                    pixels[x, y] = flip_yellow

    # Atomic "boomerang" centred in the bottom margin (the Googie / Formica
    # kidney motif): a chevron polygon of two tapered wings with an
    # electron dot off one tip. Red sentinel + the starbursts' tangerine
    # post-pass. Centred (clear of the bottom-left attribution) at
    # y≈height-40, below the quote.
    boom_cx = width // 2
    boom_cy = height - 40
    boomerang = [
        (boom_cx - 38, boom_cy - 6),   # left tip (top edge)
        (boom_cx - 6, boom_cy + 6),    # elbow inner
        (boom_cx + 38, boom_cy - 6),   # right tip (top edge)
        (boom_cx + 30, boom_cy + 2),   # right tip (bottom edge)
        (boom_cx, boom_cy + 13),       # elbow outer
        (boom_cx - 30, boom_cy + 2),   # left tip (bottom edge)
    ]
    draw.polygon(boomerang, fill=sentinel_red)
    # Orbiting-electron dot off the right tip.
    draw.ellipse((boom_cx + 44, boom_cy - 10, boom_cx + 50, boom_cy - 4), fill=sentinel_red)
    bx0 = max(0, boom_cx - 50)
    by0 = max(0, boom_cy - 12)
    bx1 = min(width - 1, boom_cx + 52)
    by1 = min(height - 1, boom_cy + 15)
    for y in range(by0, by1 + 1):
        for x in range(bx0, bx1 + 1):
            if BAYER_4x4[y & 3][x & 3] < 6 and pixels[x, y] == sentinel_red:
                pixels[x, y] = flip_yellow


# Cycle of marker-ink colours used by ``draw_marker_border``. Hardcoded
# (like ``_COMIC_STRIPE_PALETTE``) because the marker theme's THEMES entry
# has no yellow or green slot, and extending the schema would re-pin every
# cross-theme invariant test. The theme's point is to use every ink.
_MARKER_BORDER_PALETTE = (
    SPECTRA6["red"],
    SPECTRA6["blue"],
    SPECTRA6["green"],
    SPECTRA6["yellow"],
    SPECTRA6["black"],
)


def draw_marker_border(image: Image.Image, colors: dict) -> None:
    """Paint a fridge-doodle marker frame: multi-colour dashed perimeter,
    asterisk sparkles at every corner, and mid-edge filled marker dots.

    The brief is "use the full capabilities of the display", so the border
    uses all five non-white inks:

    * **Perimeter dashed scribble.** 3 px marker dashes around all four
      edges at a thin inset, cycling ``_MARKER_BORDER_PALETTE``; the
      corners stay empty for the asterisks.
    * **Corner asterisks.** Eight rays (horizontal, vertical, two
      diagonals) round a filled dot: red TL, blue TR, green BL, yellow BR.
      The TR one overlaps the debug-banner band, so
      ``_DEBUG_LABEL_RIGHT_INSET`` pushes the label inward past it.
    * **Mid-edge marker dots.** Two stippled circles hugging the dashes:
      mint (G+W 1:1) on the left, violet (R+B 1:1) on the right.

    ``colors`` is unused but kept so the signature matches the other
    border painters.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size

    # Perimeter dashed scribble. ``inset`` is the edge-to-centre-line
    # distance; ``corner_clear`` keeps dashes off the corners. Dash / gap
    # lengths give ~10–14 dashes per edge, about two palette cycles.
    inset = 12
    corner_clear = 36
    dash_len = 18
    gap_len = 10
    stride = dash_len + gap_len
    thickness = 3

    palette = _MARKER_BORDER_PALETTE
    palette_len = len(palette)
    dash_index = 0

    def _next_colour() -> tuple[int, int, int]:
        nonlocal dash_index
        col = palette[dash_index % palette_len]
        dash_index += 1
        return col

    # Top edge — left to right.
    x = corner_clear
    while x + dash_len <= width - corner_clear:
        draw.line((x, inset, x + dash_len, inset), fill=_next_colour(), width=thickness)
        x += stride
    # Right edge — top to bottom.
    y = corner_clear
    while y + dash_len <= height - corner_clear:
        draw.line(
            (width - 1 - inset, y, width - 1 - inset, y + dash_len),
            fill=_next_colour(),
            width=thickness,
        )
        y += stride
    # Bottom edge — right to left.
    x = width - corner_clear
    while x - dash_len >= corner_clear:
        draw.line((x - dash_len, height - 1 - inset, x, height - 1 - inset), fill=_next_colour(), width=thickness)
        x -= stride
    # Left edge — bottom to top.
    y = height - corner_clear
    while y - dash_len >= corner_clear:
        draw.line((inset, y - dash_len, inset, y), fill=_next_colour(), width=thickness)
        y -= stride

    # Corner asterisks: horizontal + vertical + two diagonals round a
    # filled centre dot, clear of the dashes so the corner doesn't blot.
    aster_inset = 24
    ray = 11
    centre_radius = 3
    corners = (
        (aster_inset, aster_inset, SPECTRA6["red"]),
        (width - 1 - aster_inset, aster_inset, SPECTRA6["blue"]),
        (aster_inset, height - 1 - aster_inset, SPECTRA6["green"]),
        (width - 1 - aster_inset, height - 1 - aster_inset, SPECTRA6["yellow"]),
    )
    for cx, cy, ink in corners:
        # Cardinal arms.
        draw.line((cx - ray, cy, cx + ray, cy), fill=ink, width=2)
        draw.line((cx, cy - ray, cx, cy + ray), fill=ink, width=2)
        # Diagonal arms — slightly shorter so the asterisk reads as
        # a hand-drawn star rather than a pinwheel.
        diag = int(ray * 0.78)
        draw.line((cx - diag, cy - diag, cx + diag, cy + diag), fill=ink, width=2)
        draw.line((cx - diag, cy + diag, cx + diag, cy - diag), fill=ink, width=2)
        # Filled centre dot.
        draw.ellipse(
            (cx - centre_radius, cy - centre_radius, cx + centre_radius, cy + centre_radius),
            fill=ink,
        )

    # Mid-edge marker dots in two stippled mixes: left mint (G+W 1:1, a
    # highlighter wash), right violet (R+B 1:1, a blue pass over red).
    # Each is painted in a sentinel and half flipped to its companion ink
    # on a checkerboard. The dashes and asterisks keep the five solid inks.
    dot_radius = 7
    mid_dots = (
        # (cx, cy, sentinel_dark, light_ink, label)
        (inset + 2, height // 2, SPECTRA6["green"], SPECTRA6["white"], "mint highlighter"),
        (width - 1 - inset - 2, height // 2, SPECTRA6["red"], SPECTRA6["blue"], "violet overlap"),
    )
    pixels = image.load()
    for cx, cy, dark_ink, light_ink, _ in mid_dots:
        draw.ellipse(
            (cx - dot_radius, cy - dot_radius, cx + dot_radius, cy + dot_radius),
            fill=dark_ink,
        )
        bx0 = max(0, cx - dot_radius)
        by0 = max(0, cy - dot_radius)
        bx1 = min(width - 1, cx + dot_radius)
        by1 = min(height - 1, cy + dot_radius)
        for py in range(by0, by1 + 1):
            for px in range(bx0, bx1 + 1):
                if (px + py) & 1 == 0 and pixels[px, py] == dark_ink:
                    pixels[px, py] = light_ink

    # Doodle "twinkle" sparkles in the top + bottom centre margins: a
    # tapered four-point star plus a tiny companion, red at the top and
    # blue at the bottom. The top one (x=width//2-70) clears the
    # right-aligned DEBUG MODE banner and the bottom one the attribution,
    # so marker's TR-asterisk inset entry is still enough.
    def _twinkle(tx: int, ty: int, ink: tuple[int, int, int]) -> None:
        draw.line((tx, ty - 7, tx, ty + 7), fill=ink, width=2)
        draw.line((tx - 7, ty, tx + 7, ty), fill=ink, width=2)
        for ddx, ddy in ((-3, -3), (3, -3), (-3, 3), (3, 3)):
            draw.point((tx + ddx, ty + ddy), fill=ink)
        # Tiny companion sparkle.
        draw.line((tx + 14, ty - 4, tx + 14, ty + 1), fill=ink, width=1)
        draw.line((tx + 12, ty - 2, tx + 17, ty - 2), fill=ink, width=1)
    _twinkle(width // 2 - 70, 26, SPECTRA6["red"])
    _twinkle(width // 2 + 60, height - 1 - 24, SPECTRA6["blue"])


# Deterministic foxing-speckle layout for ``draw_saloon_border``, computed
# once at module load with a fixed seed so every render is byte-identical
# (the golden suite, contact sheet and pick-equivalence tests rely on it).
def _build_saloon_foxing_points(
    width: int, height: int, density: int, *, seed: int
) -> list[tuple[int, int, int]]:
    """Scatter ``density`` foxing speckles across a (width × height) field.

    Each speckle is ``(x, y, radius)``: radius 0 is a single pixel, radius
    1 a 3×3 darker spot (~15%). Exactly ``density`` points are returned.
    """
    rng = random.Random(seed)
    points: list[tuple[int, int, int]] = []
    for _ in range(density):
        x = rng.randint(2, width - 3)
        y = rng.randint(2, height - 3)
        # ~85% single pixel (subtle), ~15% 3×3 cluster (darker spot).
        radius = 1 if rng.random() < 0.15 else 0
        points.append((x, y, radius))
    return points


# ~360 speckles at 800×480 reads as aged paper at viewing distance; text
# painted on top hides them except in the gaps, so legibility holds.
_SALOON_FOXING = _build_saloon_foxing_points(
    DEFAULT_WIDTH, DEFAULT_HEIGHT, density=360, seed=0xB2A1
)


def draw_saloon_border(image: Image.Image, colors: dict) -> None:
    """Paint a 19th-century saloon-broadside / wanted-poster background.

    A layered ground that reads as aged hand-printed paper, painted bottom
    to top:

    1. **Foxing speckles** from ``_SALOON_FOXING`` (fixed seed, so every
       render is byte-identical), half red and half green (R+G sepia).
       Text painted on top hides them except in the gaps.
    2. **Top + bottom banner bands**: a thick and a hairline black rule
       sandwiching a row of alternating red diamonds and black dashes. They
       live in the header / footer zones (y < ~58, y > height-58) where no
       body text lands.
    3. **Double-rule frame**: a 3 px sepia outer rule and a 1 px black
       inner rule.
    4. **Corner fleurons**: a black diamond at each outer corner with two
       red triangular wings along the edges.
    5. **Mid-edge red diamonds** punched into the outer rule.
    6. **Side-margin drop pendants** hanging from the left / right
       mid-edge diamonds.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    ink = colors["text"]       # black
    accent = colors["accent"]  # red (foxing, ornaments, fleuron wings)
    bg = colors["page_bg"]

    # The banner / frame rules inset 40 px from each side, so at width ≤ 80
    # (the /api/preview minimum) the rectangles invert and PIL raises
    # ValueError. Skip the decoration there; only width can invert.
    if width <= 80:
        return

    # ------------------------------------------------------------------
    # Layer 1: Foxing speckles. ``_SALOON_FOXING`` is computed for
    # 800×480; other canvas sizes (e.g. contact-sheet tiles) rescale the
    # coordinates to keep the same density. Single pixels and 3×3 spots mix.
    #
    # Half the speckles are green on (px+py) parity, so red+green averages
    # to rust-brown (the R+G 1:1 sepia recipe). Parity keys off the source
    # (px, py), not the rescaled (x, y), so the colour choice is the same
    # at every canvas size.
    sx = width / DEFAULT_WIDTH
    sy = height / DEFAULT_HEIGHT
    foxing_alt = SPECTRA6["green"]
    for px, py, radius in _SALOON_FOXING:
        x = int(px * sx)
        y = int(py * sy)
        speckle_fill = foxing_alt if (px + py) & 1 == 0 else accent
        if radius == 0:
            draw.point((x, y), fill=speckle_fill)
        else:
            draw.rectangle((x - 1, y - 1, x + 1, y + 1), fill=speckle_fill)

    # ------------------------------------------------------------------
    # Layer 2: Top + bottom decorative banner bands: a thick outer rule
    # and a hairline inner rule sandwiching a row of red diamonds and
    # black dashes, read as a typeset divider.
    #
    # Y-positions clear the debug chrome: the ``DEBUG MODE`` banner is
    # y≈14-29, so the top thick rule starts at y=34; the bottom dotted
    # rule is at y=443 and its text at y=451-466, so the bottom thick rule
    # ends at y=440. Body text starts around y=72, 14 px below the top
    # hairline at y=58.
    band_outer_y_top = 34
    band_inner_y_top = 58
    band_outer_y_bot = height - 1 - 39
    band_inner_y_bot = height - 1 - 63
    band_rule_thick = 3
    band_rule_thin = 1

    # Top: thick rule (outer), hairline rule (inner).
    draw.rectangle(
        (40, band_outer_y_top, width - 1 - 40, band_outer_y_top + band_rule_thick - 1),
        fill=ink,
    )
    draw.rectangle(
        (40, band_inner_y_top, width - 1 - 40, band_inner_y_top + band_rule_thin - 1),
        fill=ink,
    )
    # Bottom: hairline rule (inner), thick rule (outer).
    draw.rectangle(
        (40, band_inner_y_bot - band_rule_thin + 1, width - 1 - 40, band_inner_y_bot),
        fill=ink,
    )
    draw.rectangle(
        (40, band_outer_y_bot - band_rule_thick + 1, width - 1 - 40, band_outer_y_bot),
        fill=ink,
    )

    # Banner ornaments: alternating red diamonds and short black dashes
    # between the rules. The strip is below the debug label, so no
    # _DEBUG_LABEL_RIGHT_INSET entry is needed for it.
    diamond_size = 5
    dash_len = 14
    ornament_step = 36
    band_mid_y_top = (band_outer_y_top + band_rule_thick + band_inner_y_top) // 2
    band_mid_y_bot = (band_inner_y_bot + band_outer_y_bot - band_rule_thick) // 2
    n_ornaments = (width - 160) // ornament_step
    start_x = (width - n_ornaments * ornament_step) // 2 + ornament_step // 2
    for i in range(n_ornaments):
        cx = start_x + i * ornament_step
        if i % 2 == 0:
            # Red diamond.
            for cy in (band_mid_y_top, band_mid_y_bot):
                draw.polygon(
                    [
                        (cx, cy - diamond_size),
                        (cx + diamond_size, cy),
                        (cx, cy + diamond_size),
                        (cx - diamond_size, cy),
                    ],
                    fill=accent,
                )
        else:
            # Short black dash.
            for cy in (band_mid_y_top, band_mid_y_bot):
                draw.line(
                    (cx - dash_len // 2, cy, cx + dash_len // 2, cy),
                    fill=ink,
                    width=2,
                )

    # ------------------------------------------------------------------
    # Layer 3: Outer + inner double-rule frame. Tight insets leave the
    # foxing between the page edge and the frame visible.
    #
    # The 3 px outer rule is painted in a red sentinel; the post-pass walks
    # its four edge strips and flips half to green on (x+y)&1 (R+G sepia,
    # as the foxing), a rusted-iron frame. The red-pixel guard tolerates
    # PIL's edge rounding.
    outer_inset = 12
    inner_inset = 18
    outer_rule_width = 3
    draw.rectangle(
        (outer_inset, outer_inset, width - 1 - outer_inset, height - 1 - outer_inset),
        outline=SPECTRA6["red"],
        width=outer_rule_width,
    )
    pixels = image.load()
    outer_x0, outer_y0 = outer_inset, outer_inset
    outer_x1, outer_y1 = width - 1 - outer_inset, height - 1 - outer_inset
    sepia_light = SPECTRA6["green"]
    sentinel_red = SPECTRA6["red"]
    # Top edge strip — 3 rows.
    for y in range(outer_y0, outer_y0 + outer_rule_width):
        for x in range(outer_x0, outer_x1 + 1):
            if (x + y) & 1 == 0 and pixels[x, y] == sentinel_red:
                pixels[x, y] = sepia_light
    # Bottom edge strip — 3 rows.
    for y in range(outer_y1 - outer_rule_width + 1, outer_y1 + 1):
        for x in range(outer_x0, outer_x1 + 1):
            if (x + y) & 1 == 0 and pixels[x, y] == sentinel_red:
                pixels[x, y] = sepia_light
    # Left edge strip, 3 columns, skipping the rows the top/bottom strips
    # covered so the corner cells are flipped once.
    for x in range(outer_x0, outer_x0 + outer_rule_width):
        for y in range(outer_y0 + outer_rule_width, outer_y1 - outer_rule_width + 1):
            if (x + y) & 1 == 0 and pixels[x, y] == sentinel_red:
                pixels[x, y] = sepia_light
    # Right edge strip — 3 columns, same exclusion as the left strip.
    for x in range(outer_x1 - outer_rule_width + 1, outer_x1 + 1):
        for y in range(outer_y0 + outer_rule_width, outer_y1 - outer_rule_width + 1):
            if (x + y) & 1 == 0 and pixels[x, y] == sentinel_red:
                pixels[x, y] = sepia_light

    draw.rectangle(
        (inner_inset, inner_inset, width - 1 - inner_inset, height - 1 - inner_inset),
        outline=ink,
        width=1,
    )

    # ------------------------------------------------------------------
    # Layer 4: Corner fleurons: a black diamond on each outer-rule corner
    # with two short red triangular wings along the adjacent edges.
    diamond_corner = 9
    wing_len = 14
    wing_w = 5
    corners = (
        # (cx, cy, dx_along_top_or_bot, dy_along_side)
        (outer_inset, outer_inset, 1, 1),                              # TL
        (width - 1 - outer_inset, outer_inset, -1, 1),                 # TR
        (outer_inset, height - 1 - outer_inset, 1, -1),                # BL
        (width - 1 - outer_inset, height - 1 - outer_inset, -1, -1),   # BR
    )
    for cx, cy, dx, dy in corners:
        # Black filled diamond on the corner anchor.
        draw.polygon(
            [
                (cx, cy - diamond_corner),
                (cx + diamond_corner, cy),
                (cx, cy + diamond_corner),
                (cx - diamond_corner, cy),
            ],
            fill=ink,
        )
        # Red wing along the horizontal edge.
        draw.polygon(
            [
                (cx + dx * (diamond_corner + 2), cy - wing_w),
                (cx + dx * (diamond_corner + 2 + wing_len), cy),
                (cx + dx * (diamond_corner + 2), cy + wing_w),
            ],
            fill=accent,
        )
        # Red wing along the vertical edge.
        draw.polygon(
            [
                (cx - wing_w, cy + dy * (diamond_corner + 2)),
                (cx, cy + dy * (diamond_corner + 2 + wing_len)),
                (cx + wing_w, cy + dy * (diamond_corner + 2)),
            ],
            fill=accent,
        )

    # ------------------------------------------------------------------
    # Layer 5: Mid-edge red diamonds painted over the outer rule, so they
    # read as punched ornaments that break up the long rules.
    mid_diamond = 7
    midpoints = (
        (width // 2, outer_inset),
        (width // 2, height - 1 - outer_inset),
        (outer_inset, height // 2),
        (width - 1 - outer_inset, height // 2),
    )
    for cx, cy in midpoints:
        draw.polygon(
            [
                (cx, cy - mid_diamond),
                (cx + mid_diamond, cy),
                (cx, cy + mid_diamond),
                (cx - mid_diamond, cy),
            ],
            fill=accent,
        )

    # ------------------------------------------------------------------
    # Layer 6: Side-margin drop pendants: two diminishing red diamonds
    # joined by a thin tick, hanging inward from each left/right mid-edge
    # diamond into the empty side margins (x≈12 / x≈787, outside the
    # body's x 60–740). Solid red, not sepia, so they read as printed
    # ornament rather than foxing.
    pendant_sizes = (5, 3)
    pendant_gap = 7
    for edge_x in (outer_inset, width - 1 - outer_inset):
        cy = height // 2
        offset = mid_diamond + pendant_gap
        for size in pendant_sizes:
            dcy = cy + offset
            draw.line((edge_x, dcy - offset + mid_diamond, edge_x, dcy - size), fill=accent, width=1)
            draw.polygon(
                [
                    (edge_x, dcy - size),
                    (edge_x + size, dcy),
                    (edge_x, dcy + size),
                    (edge_x - size, dcy),
                ],
                fill=accent,
            )
            offset += size + pendant_gap

    # ``bg`` is unused.
    del bg


def draw_newsprint_border(image: Image.Image, colors: dict) -> None:
    """Paint a broadsheet-style Scotch-rule border around the canvas margin.

    * **Layer 0: newsprint halftone + faint sepia foxing.** On a 4×4 Bayer
      tile, ``page_bg`` pixels with value < 2 turn black (the 12.5% grey
      pulp halftone), value 6 red and value 9 green. The red and green
      cells sit one row apart in the same column and average to R+G 1:1
      sepia (aged lignin). Values 6 and 9 are chosen to miss every pinned
      border / cross-gating sample coordinate
      (``test_newsprint_inner_hairline_is_one_pixel_and_has_gap_above``,
      ``test_blueprint_border_is_theme_gated`` at (6, 16),
      ``test_illuminated_border_is_theme_gated`` at (400, 22)). The colour
      lives on the paper only, so ``test_newsprint_theme_has_no_colour_accent``
      still holds. All pixels are pure inks, so palette-snap is a no-op.
    * **Scotch rule frame**: a heavy outer and a hairline inner rectangle
      with white between, and nothing else.
    * **Broadsheet typographic furniture**: a thick+thin masthead rule with
      two column-rule ticks, a centred folio rule at the foot, and a small
      black printer's diamond on each. Ink only; all clear of the text
      (y ≥ 72).
    """
    width, height = image.size
    page_bg = colors.get("page_bg")
    ink = colors["text"]

    # Layer 0: halftone + sepia foxing (see docstring). Only exact
    # ``page_bg`` pixels are touched; skipped when ``page_bg`` is absent so
    # direct-call test paths that only provide ``text`` stay valid.
    if page_bg is not None:
        _BAYER_4 = BAYER_4x4
        sepia_red = SPECTRA6["red"]
        sepia_green = SPECTRA6["green"]
        pixels = image.load()
        for y in range(height):
            row = _BAYER_4[y & 3]
            for x in range(width):
                if pixels[x, y] != page_bg:
                    continue
                cell = row[x & 3]
                if cell < 2:
                    pixels[x, y] = ink           # 12.5% black halftone
                elif cell == 6:
                    pixels[x, y] = sepia_red     # 6.25% red speckle at (1, 3)
                elif cell == 9:
                    pixels[x, y] = sepia_green   # 6.25% green speckle at (2, 3)

    draw = ImageDraw.Draw(image)

    # Outer heavy rule.
    outer_inset = 10
    outer_weight = 3
    draw.rectangle(
        (outer_inset, outer_inset, width - 1 - outer_inset, height - 1 - outer_inset),
        outline=ink,
        width=outer_weight,
    )
    # Inner hairline rule, with a gap of white between the two.
    inner_inset = 18
    draw.rectangle(
        (inner_inset, inner_inset, width - 1 - inner_inset, height - 1 - inner_inset),
        outline=ink,
        width=1,
    )

    # Broadsheet typographic furniture, ink only (the foxing lives on the
    # paper, not the typography), all clear of the text (y ≥ 72).
    rule_l = inner_inset + 6
    rule_r = width - 1 - inner_inset - 6
    # Masthead nameplate rule — a thick+thin Scotch pair spanning the
    # inner frame near the top (y≈38), the separator under a broadsheet's
    # nameplate.
    mast_y = inner_inset + 20
    draw.line([(rule_l, mast_y), (rule_r, mast_y)], fill=ink, width=2)
    draw.line([(rule_l, mast_y + 5), (rule_r, mast_y + 5)], fill=ink, width=1)
    # Two column-rule ticks descending from the masthead, stopping above
    # the text (y≤68 < 72).
    for col_x in (width // 3, 2 * width // 3):
        draw.line([(col_x, mast_y + 10), (col_x, mast_y + 30)], fill=ink, width=1)
    # Folio rule at the foot, short and centred (clear of the bottom-left
    # attribution).
    folio_y = height - 1 - inner_inset - 20
    folio_cx = width // 2
    draw.line([(folio_cx - 90, folio_y), (folio_cx + 90, folio_y)], fill=ink, width=1)
    # Printer's dingbat: a small black diamond on the masthead and folio rules.
    for dcx, dy in ((width // 2, mast_y + 5), (folio_cx, folio_y)):
        draw.polygon([(dcx, dy - 4), (dcx + 4, dy), (dcx, dy + 4), (dcx - 4, dy)], fill=ink)


def draw_nightvision_border(image: Image.Image, colors: dict) -> None:
    """Paint a HUD-style nightvision field without closing the outer frame."""
    draw = ImageDraw.Draw(image)
    width, height = image.size
    body = colors["text"]
    accent = colors.get("accent", body)
    subtle = colors.get("subtle", body)

    margin = 12
    arm = 26
    thickness = 2
    right_x = width - 1 - margin
    bottom_y = height - 1 - margin

    # Corner brackets only; the outer frame stays open.
    draw.rectangle((margin, margin, margin + arm, margin + thickness - 1), fill=body)
    draw.rectangle((margin, margin, margin + thickness - 1, margin + arm), fill=body)
    draw.rectangle((right_x - arm, margin, right_x, margin + thickness - 1), fill=body)
    draw.rectangle((right_x - thickness + 1, margin, right_x, margin + arm), fill=body)
    draw.rectangle((margin, bottom_y - thickness + 1, margin + arm, bottom_y), fill=body)
    draw.rectangle((margin, bottom_y - arm, margin + thickness - 1, bottom_y), fill=body)
    draw.rectangle((right_x - arm, bottom_y - thickness + 1, right_x, bottom_y), fill=body)
    draw.rectangle((right_x - thickness + 1, bottom_y - arm, right_x, bottom_y), fill=body)

    # Faint scanlines contained inside the page, leaving the bracket gaps intact.
    for y in range(margin + 18, bottom_y - 6, 14):
        draw.line((margin + 30, y, right_x - 30, y), fill=subtle, width=1)

    # Sage post-pass on the scanlines only: flip ~25% of their green
    # pixels to white (``BAYER_4x4`` cells 0-3), the W+G 3:1 pale-sage
    # recipe, so they read as ambient glow rather than crisp CRT lines.
    # Limited to the scanline x range, so the corner brackets stay solid.
    if subtle == SPECTRA6["green"]:
        pixels = image.load()
        sage_light = SPECTRA6["white"]
        for scan_y in range(margin + 18, bottom_y - 6, 14):
            row = BAYER_4x4[scan_y & 3]
            for sx in range(margin + 30, right_x - 30):
                if row[sx & 3] < 4 and pixels[sx, scan_y] == subtle:
                    pixels[sx, scan_y] = sage_light

    # Mid-edge targeting ticks that float inside the canvas rather than joining the frame.
    tick = 12
    cx = width // 2
    cy = height // 2
    top_y = margin + 20
    bottom_tick_y = bottom_y - 20
    left_x = margin + 20
    right_tick_x = right_x - 20
    draw.line((cx - 48, top_y, cx - 48 + tick, top_y), fill=accent, width=2)
    draw.line((cx + 48 - tick, top_y, cx + 48, top_y), fill=accent, width=2)
    draw.line((cx - 48, bottom_tick_y, cx - 48 + tick, bottom_tick_y), fill=accent, width=2)
    draw.line((cx + 48 - tick, bottom_tick_y, cx + 48, bottom_tick_y), fill=accent, width=2)
    draw.line((left_x, cy - 32, left_x, cy - 32 + tick), fill=accent, width=2)
    draw.line((left_x, cy + 32 - tick, left_x, cy + 32), fill=accent, width=2)
    draw.line((right_tick_x, cy - 32, right_tick_x, cy - 32 + tick), fill=accent, width=2)
    draw.line((right_tick_x, cy + 32 - tick, right_tick_x, cy + 32), fill=accent, width=2)

    # Tiny corner telemetry, kept clear of the debug-banner region.
    meta_font = load_font(META_FONT_CANDIDATES, size=12)
    draw_text(draw, (24, 20), 'SIG 92%', font=meta_font, fill=accent)
    draw_text(draw, (24, height - 34), 'GAIN AUTO', font=meta_font, fill=accent)
    draw_text(draw, (width - 122, 40), 'AZ 041  EL 17', font=meta_font, fill=accent)

    # HUD bearing-scale ruler along the bottom inner margin: graduated
    # ticks, a taller one every fourth, and a yellow centre caret, between
    # the corner brackets and below GAIN AUTO, clear of the quote.
    scale_y = bottom_y - 3
    scale_l = margin + 110
    scale_r = right_x - 110
    for i, sx in enumerate(range(scale_l, scale_r + 1, 22)):
        notch = 8 if i % 4 == 0 else 4
        draw.line((sx, scale_y, sx, scale_y - notch), fill=body, width=1)
    # Centre index caret — a small downward yellow triangle over the tape.
    draw.polygon(
        [(cx, scale_y - 10), (cx - 4, scale_y - 16), (cx + 4, scale_y - 16)],
        fill=accent,
    )

    # Rangefinder ladder notches on the two bottom brackets' vertical arms.
    # Bottom brackets only, so the top stays clear of the debug band.
    for arm_x, arm_dir in ((margin, +1), (right_x, -1)):
        for step in (8, 14, 20):
            ny = bottom_y - step
            draw.line(
                (arm_x + arm_dir * (thickness + 1), ny, arm_x + arm_dir * (thickness + 5), ny),
                fill=body,
                width=1,
            )



_COMIC_STRIPE_PALETTE = (
    SPECTRA6["blue"],
    SPECTRA6["green"],
    SPECTRA6["red"],
    SPECTRA6["black"],
)


def draw_comic_corner_stripes(image: Image.Image, colors: dict) -> None:
    """Paint a comic-book panel: Ben-Day halftone corner, racing-stripe
    chevron, and a heavy black panel gutter.

    * **Ben-Day halftone dots**: a grid of small red dots filling a
      right-triangle in the top-left corner, balancing the bottom-right
      stripes. The grid starts ≥22 px in from both edges so the corner,
      and the ``(15, 15)`` pixel the theme-gating test samples, stays
      yellow page_bg.
    * **Racing-stripe chevron**: four parallel 45° bands (bottom-left to
      top-right) cycling ``_COMIC_STRIPE_PALETTE`` (blue / green / red /
      black), with yellow gaps, masked to a right-isoceles triangle in the
      bottom-right corner with legs ``height // 2``. The hypotenuse runs at
      the stripes' own slope, so no band is clipped at an angle, and the
      longest dense-layout lines never reach it. Painted before any text,
      so a glyph that does land there sits on top.
    * **Heavy black panel border** just inside the canvas edge, painted
      last over the dots and stripes.

    The stripe palette is hardcoded because the comic THEMES entry has
    only two non-bg slots (text=black, accent=red), and extending the
    schema would re-pin the cross-theme invariant tests. The gap colour
    comes from ``colors["page_bg"]``.
    """
    width, height = image.size

    # Ben-Day halftone dots: a red dot grid masked to a top-left right
    # triangle (cx + cy ≤ tri_legs), inset ≥22 px so the gutter corner and
    # the sampled (15, 15) pixel stay yellow.
    dot_draw = ImageDraw.Draw(image)
    # Default to red dots / black gutter so unit tests that pass only
    # ``page_bg`` still render the full panel.
    dot_color = colors.get("accent", SPECTRA6["red"])
    dot_r = 3
    dot_step = 16
    dot_inset = 26
    tri_legs = 150
    cy = dot_inset
    while cy <= tri_legs:
        cx = dot_inset
        while cx <= tri_legs:
            if cx + cy <= tri_legs:
                dot_draw.ellipse((cx - dot_r, cy - dot_r, cx + dot_r, cy + dot_r), fill=dot_color)
            cx += dot_step
        cy += dot_step

    qx = width // 2
    qy = height // 2
    qw = width - qx
    qh = height - qy

    # Paint stripes onto a sub-image the size of the lower-right quadrant,
    # so bands clip on its bounds without per-stripe polygon math.
    quadrant = Image.new("RGB", (qw, qh), color=colors["page_bg"])
    qd = ImageDraw.Draw(quadrant)

    stripe_thickness = 19
    stripe_gap = 11
    period = stripe_thickness + stripe_gap
    palette = _COMIC_STRIPE_PALETTE

    # Each band runs at slope -1 through (c, qh) at the sub-image bottom
    # and (c + qh, 0) at the top, extended past both bounds so PIL's line
    # caps don't leave a gap at the canvas edge. Only four bands are kept:
    # indices 17-20 at the native 400×240 quadrant, the same relative
    # position at other sizes.
    stripe_cs = list(range(-qh - period, qw + period + 1, period))
    keep_count = min(4, len(stripe_cs))
    if qh == 240 and qw == 400:
        kept_indices = {17, 18, 19, 20}
    else:
        default_qh = 240
        default_qw = 400
        default_stripe_cs = list(range(-default_qh - period, default_qw + period + 1, period))
        default_keep_indices = {17, 18, 19, 20}
        target_mid = sum(default_keep_indices) / len(default_keep_indices)
        scale = len(stripe_cs) / len(default_stripe_cs)
        scaled_mid = target_mid * scale
        keep_start = round(scaled_mid - (keep_count - 1) / 2)
        keep_start = max(0, min(keep_start, max(0, len(stripe_cs) - keep_count)))
        kept_indices = set(range(keep_start, min(len(stripe_cs), keep_start + keep_count)))

    overshoot = max(stripe_thickness, stripe_gap)
    for i, c in enumerate(stripe_cs):
        if i in kept_indices:
            color = palette[i % len(palette)]
            qd.line(
                [(c - overshoot, qh + overshoot), (c + qh + overshoot, -overshoot)],
                fill=color,
                width=stripe_thickness,
            )

    # Right-isoceles triangle mask (legs qh) at the quadrant's bottom-right,
    # hypotenuse parallel to the stripes. Mode "L" so paste() uses it as
    # per-pixel alpha.
    mask = Image.new("L", (qw, qh), 0)
    md = ImageDraw.Draw(mask)
    md.polygon([(qw - qh, qh), (qw, 0), (qw, qh)], fill=255)

    image.paste(quadrant, (qx, qy), mask=mask)

    # Heavy black panel border, painted last over the dots and stripes.
    # Inset 2 / width 4 puts the stroke at x/y 2–5, clear of every comic
    # gating-test sample point ((6,16), (12,12), (400,11), (15,15),
    # (20,20), (36,56)).
    border_draw = ImageDraw.Draw(image)
    panel_inset = 2
    border_draw.rectangle(
        (panel_inset, panel_inset, width - 1 - panel_inset, height - 1 - panel_inset),
        outline=colors.get("text", SPECTRA6["black"]),
        width=4,
    )


# Deterministic stone-grain speckle layout for ``draw_roman_border``,
# computed once at module scope like ``_SALOON_FOXING`` (byte-identical
# renders). Sparser than saloon's foxing: limestone reads cleaner than pulp
# paper, and heavy stipple fights dense quotes. Only the outer ring is
# speckled; the central face stays clear.
def _build_roman_stone_grain(
    width: int, height: int, density: int, *, seed: int, exclude_inset: int
) -> list[tuple[int, int, int]]:
    """Scatter ``density`` stone-grain speckles in a ring round the canvas
    edge, leaving the central rectangle (``exclude_inset`` from each edge)
    clear.

    Each speckle is ``(x, y, radius)`` with radius 0 (single pixel) or 1
    (3×3), as in ``_build_saloon_foxing_points``.
    """
    rng = random.Random(seed)
    points: list[tuple[int, int, int]] = []
    attempts = 0
    while len(points) < density and attempts < density * 8:
        attempts += 1
        x = rng.randint(2, width - 3)
        y = rng.randint(2, height - 3)
        # Skip points inside the central face, where the quote sits.
        if exclude_inset <= x < width - exclude_inset and exclude_inset <= y < height - exclude_inset:
            continue
        radius = 1 if rng.random() < 0.18 else 0
        points.append((x, y, radius))
    return points


# ~140 speckles in the ring outside an inset-26 exclusion at 800×480: enough
# to read as limestone grain, and the exclusion keeps them off the text. At
# the top and bottom the ring reaches a little inside the tabula's outer
# rule (rect_inset_y=14), but stays outside the text area.
_ROMAN_STONE_GRAIN = _build_roman_stone_grain(
    DEFAULT_WIDTH, DEFAULT_HEIGHT, density=140, seed=0x5C1B, exclude_inset=26
)


def draw_roman_border(image: Image.Image, colors: dict) -> None:
    """Paint a Roman lapidary stone-tablet frame.

    Layers, bottom to top:

    1. **Stone-grain speckles** in the outer ring from
       ``_ROMAN_STONE_GRAIN`` (fixed seed); ~18% are 3×3 darker spots.
    2. **Tabula ansata outline**: a black rectangle with two trapezoidal
       dovetail handles (``ansae``) extending outward from the left and
       right mid-edges, the Roman votive-tablet shape.
    3. **Inner channel rule**: a hairline a few px inside the rectangle,
       the V-cut channel round the inscribed face.
    4. **SPQR cartouche** in red at top centre on the carved face, just
       below the channel rule and above the text (quote_top ≥ 72), with
       red interpunct dots (``·``) between the letters. Centred, so it
       misses the right-aligned ``DEBUG MODE`` banner.
    5. **Mid-edge interpunct dots** in red on the channel rule.
    6. **Laurel sprig** at bottom centre: two short black stems with three
       olive (Y+G 1:1) leaves each and a red berry at the join.
    7. **Carved corner stops**: small red triangles in each channel corner.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    ink = colors["text"]       # black
    accent = colors["accent"]  # red rubrum

    # ------------------------------------------------------------------
    # Layer 1: Stone-grain speckles in the outer ring. ``_ROMAN_STONE_GRAIN``
    # is computed for 800×480; rescale so other sizes (e.g. contact-sheet
    # tiles) keep the same density.
    sx = width / DEFAULT_WIDTH
    sy = height / DEFAULT_HEIGHT
    for px, py, radius in _ROMAN_STONE_GRAIN:
        x = int(px * sx)
        y = int(py * sy)
        if radius == 0:
            draw.point((x, y), fill=ink)
        else:
            draw.rectangle((x - 1, y - 1, x + 1, y + 1), fill=ink)

    # ------------------------------------------------------------------
    # Layer 2: Tabula ansata outline: the rectangle plus two trapezoidal
    # dovetail handles at the left and right mid-edges, narrow side
    # facing out (the Arch of Titus silhouette), about half the
    # rectangle's height so they read as ears, not pegs. Insets are
    # tight so the face has the most room for text; the ansae need the
    # side margin for ``handle_outer_offset``.
    rect_inset_x = 30
    rect_inset_y = 14
    rect_left = rect_inset_x
    rect_right = width - 1 - rect_inset_x
    rect_top = rect_inset_y
    rect_bot = height - 1 - rect_inset_y

    # ``ansa`` dimensions are fixed pixels, not a fraction of the
    # rectangle height: the ratio that reads as a Roman tablet is about
    # 70:40 (inner:outer), and scaling would give ~218 px handles at 800×480.
    handle_outer_offset = 22       # how far the ansa extends past the rectangle
    handle_inner_height = 90       # vertical span where the ansa meets the rectangle
    handle_outer_height = 56       # vertical span at the ansa's outer edge
    rect_mid = (rect_top + rect_bot) // 2

    rule_thick = 3

    # Outer silhouette as one closed polyline, clockwise from the top-left,
    # so the corners join cleanly with no inner cross-rule.
    tabula_outline = [
        # Top edge.
        (rect_left, rect_top),
        (rect_right, rect_top),
        # Right ansa: inner top → outer top → outer bottom → inner bottom.
        (rect_right, rect_mid - handle_inner_height // 2),
        (rect_right + handle_outer_offset, rect_mid - handle_outer_height // 2),
        (rect_right + handle_outer_offset, rect_mid + handle_outer_height // 2),
        (rect_right, rect_mid + handle_inner_height // 2),
        # Bottom edge.
        (rect_right, rect_bot),
        (rect_left, rect_bot),
        # Left ansa: inner bottom → outer bottom → outer top → inner top.
        (rect_left, rect_mid + handle_inner_height // 2),
        (rect_left - handle_outer_offset, rect_mid + handle_outer_height // 2),
        (rect_left - handle_outer_offset, rect_mid - handle_outer_height // 2),
        (rect_left, rect_mid - handle_inner_height // 2),
    ]
    # Close the polygon by repeating the first point.
    draw.line(tabula_outline + [tabula_outline[0]], fill=ink, width=rule_thick)

    # ------------------------------------------------------------------
    # Layer 3: Inner channel rule: a hairline rectangle inside the central
    # rectangle only (not the ansae), the V-cut groove round the
    # inscribed face.
    channel_inset = 8
    draw.rectangle(
        (
            rect_left + channel_inset,
            rect_top + channel_inset,
            rect_right - channel_inset,
            rect_bot - channel_inset,
        ),
        outline=ink,
        width=1,
    )

    # ------------------------------------------------------------------
    # Layer 4: SPQR cartouche at top centre, on the carved face below the
    # channel rule and above quote_top (≈y=72). The channel band is too
    # narrow for legible 18 pt Cinzel, and a real inscription carves SPQR
    # on the face anyway. The theme's ornament chain degrades to a heavy
    # serif if Cinzel is missing.
    cart_font = load_font(theme_font_candidates("roman", "ornament"), size=18)
    cart_letters = ("S", "P", "Q", "R")
    interpunct_r = 2
    letter_gap = 18  # gap between adjacent letter centres' interpunct slots
    # Measure the letters first so the cartouche can be centred.
    letter_widths = []
    letter_height = 0
    for ch in cart_letters:
        bbox = draw.textbbox((0, 0), ch, font=cart_font)
        letter_widths.append(bbox[2] - bbox[0])
        letter_height = max(letter_height, bbox[3] - bbox[1])
    cart_total_w = sum(letter_widths) + (len(cart_letters) - 1) * letter_gap
    cart_start_x = (width - cart_total_w) // 2
    # Letters are drawn from 8 px below the channel rule
    # (rect_top + channel_inset = 22), i.e. from y=30, above the body text.
    cart_band_top = rect_top + channel_inset + 8
    # Draw letters with red interpunct dots between each pair.
    cursor_x = cart_start_x
    for i, ch in enumerate(cart_letters):
        draw.text((cursor_x, cart_band_top), ch, font=cart_font, fill=accent)
        cursor_x += letter_widths[i]
        if i < len(cart_letters) - 1:
            dot_cx = cursor_x + letter_gap // 2
            dot_cy = cart_band_top + letter_height // 2
            draw.ellipse(
                (
                    dot_cx - interpunct_r,
                    dot_cy - interpunct_r,
                    dot_cx + interpunct_r,
                    dot_cy + interpunct_r,
                ),
                fill=accent,
            )
            cursor_x += letter_gap

    # ------------------------------------------------------------------
    # Layer 5: Mid-edge interpunct dots painted over the inner channel
    # rule, breaking its long runs.
    mid_dot_r = 4
    mid_points = (
        (width // 2, rect_top + channel_inset),                    # top
        (width // 2, rect_bot - channel_inset),                    # bottom
        (rect_left + channel_inset, (rect_top + rect_bot) // 2),   # left
        (rect_right - channel_inset, (rect_top + rect_bot) // 2),  # right
    )
    for cx, cy in mid_points:
        draw.ellipse(
            (cx - mid_dot_r, cy - mid_dot_r, cx + mid_dot_r, cy + mid_dot_r),
            fill=accent,
        )

    # ------------------------------------------------------------------
    # Layer 6: Laurel sprig at bottom centre on the face, mirroring the
    # SPQR band: two black stems with three leaves each, angled outward.
    #
    # Leaves are painted yellow and half flipped to green on (x+y)&1 per
    # leaf bbox (the Y+G 1:1 olive recipe, laurel's colour). Stems and the
    # red berry stay solid for contrast.
    laurel_band_y = rect_bot - channel_inset - 8
    laurel_cx = width // 2
    stem_len = 36
    leaf_count = 3
    leaf_a, leaf_b = 5, 2  # leaf ellipse semi-axes (long, short)
    leaf_centres: list[tuple[int, int]] = []
    for sign in (-1, 1):
        # Stem: a short rule slanting slightly up toward the centre, so the
        # two stems converge under the berry.
        stem_x0 = laurel_cx + sign * 6
        stem_y0 = laurel_band_y + 1
        stem_x1 = stem_x0 + sign * stem_len
        stem_y1 = laurel_band_y - 3
        draw.line((stem_x0, stem_y0, stem_x1, stem_y1), fill=ink, width=1)
        # Leaves: three small axis-aligned ellipses along the stem; at this
        # size an unrotated ellipse reads as a leaf.
        for j in range(1, leaf_count + 1):
            t = j / (leaf_count + 1)
            leaf_cx = int(stem_x0 + sign * stem_len * t)
            leaf_cy = int(stem_y0 + (stem_y1 - stem_y0) * t) - 3
            draw.ellipse(
                (leaf_cx - leaf_a, leaf_cy - leaf_b, leaf_cx + leaf_a, leaf_cy + leaf_b),
                fill=SPECTRA6["yellow"],
            )
            leaf_centres.append((leaf_cx, leaf_cy))
    # Olive post-pass on each leaf bbox; only yellow (leaf) pixels flip.
    pixels = image.load()
    olive_light = SPECTRA6["green"]
    sentinel_yellow = SPECTRA6["yellow"]
    for leaf_cx, leaf_cy in leaf_centres:
        x0 = max(0, leaf_cx - leaf_a)
        y0 = max(0, leaf_cy - leaf_b)
        x1 = min(width - 1, leaf_cx + leaf_a)
        y1 = min(height - 1, leaf_cy + leaf_b)
        for py in range(y0, y1 + 1):
            for px in range(x0, x1 + 1):
                if (px + py) & 1 == 0 and pixels[px, py] == sentinel_yellow:
                    pixels[px, py] = olive_light
    # Centre laurel "berry" — a small filled red dot at the join.
    draw.ellipse(
        (laurel_cx - 2, laurel_band_y - 4, laurel_cx + 2, laurel_band_y),
        fill=accent,
    )

    # ------------------------------------------------------------------
    # Layer 7: Carved corner stops: a small red right-triangle in each
    # inner-channel corner, the corner terminal masons cut where two
    # channel rules meet. 10 px legs at ≈(38,22)/(761,457), clear of the
    # text (≈x60-740, y72-410).
    chan_l = rect_left + channel_inset
    chan_r = rect_right - channel_inset
    chan_t = rect_top + channel_inset
    chan_b = rect_bot - channel_inset
    stop_leg = 10
    for corner_x, corner_y, hdir, vdir in (
        (chan_l, chan_t, 1, 1),    # TL
        (chan_r, chan_t, -1, 1),   # TR
        (chan_l, chan_b, 1, -1),   # BL
        (chan_r, chan_b, -1, -1),  # BR
    ):
        draw.polygon(
            [
                (corner_x, corner_y),
                (corner_x + hdir * stop_leg, corner_y),
                (corner_x, corner_y + vdir * stop_leg),
            ],
            fill=accent,
        )


def _draw_pentagram(draw: ImageDraw.ImageDraw, cx: int, cy: int, radius: int, color, line_width: int = 1) -> None:
    """Draw a pentagram (5-pointed star inscribed in a circle).

    First vertex at -90° (12 o'clock), then +72° steps; the star joins every
    second vertex (0→2→4→1→3→0), inside an outline circle.
    """
    # Outer protective circle.
    draw.ellipse(
        (cx - radius, cy - radius, cx + radius, cy + radius),
        outline=color,
        width=line_width,
    )
    # Five outer vertices.
    points = [
        (
            cx + radius * math.cos(math.radians(-90 + i * 72)),
            cy + radius * math.sin(math.radians(-90 + i * 72)),
        )
        for i in range(5)
    ]
    # Pentagram path: every second vertex, one closed path.
    order = [0, 2, 4, 1, 3, 0]
    for i in range(len(order) - 1):
        draw.line(
            [points[order[i]], points[order[i + 1]]],
            fill=color,
            width=line_width,
        )


def _draw_alchemical_triangle(
    draw: ImageDraw.ImageDraw,
    cx: int,
    cy: int,
    radius: int,
    color,
    point_up: bool,
    with_bar: bool,
    line_width: int = 2,
) -> None:
    """Four classical-element triangle glyphs.

    +-----------------+--------------+-------------+
    | ``point_up``    | bare         | bar         |
    +=================+==============+=============+
    | True            | 🜂 Fire       | 🜁 Air        |
    | False           | 🜄 Water      | 🜃 Earth      |
    +-----------------+--------------+-------------+

    The bar marks the "lighter" of each pair (air is light-fire, earth is
    light-water). Drawn as an outlined equilateral triangle inscribed in
    a circle of ``radius``.
    """
    half_base = radius * math.sin(math.radians(60))
    apex_offset = radius
    base_offset = radius * 0.5
    if point_up:
        apex = (cx, cy - apex_offset)
        left = (cx - half_base, cy + base_offset)
        right = (cx + half_base, cy + base_offset)
    else:
        apex = (cx, cy + apex_offset)
        left = (cx - half_base, cy - base_offset)
        right = (cx + half_base, cy - base_offset)
    draw.polygon([apex, right, left], outline=color, width=line_width)

    if with_bar:
        # Horizontal bar at the triangle's mid-height, slightly shorter
        # than the triangle width there so the ends stay inside the outline.
        bar_y = (apex[1] + (left[1] + right[1]) / 2) / 2
        # ``t``: fractional distance from the apex at ``bar_y``.
        if point_up:
            t = (bar_y - apex[1]) / (left[1] - apex[1]) if left[1] != apex[1] else 0
        else:
            t = (apex[1] - bar_y) / (apex[1] - left[1]) if apex[1] != left[1] else 0
        local_half = half_base * t
        bar_half = max(3, local_half - 2)
        draw.line(
            (cx - bar_half, bar_y, cx + bar_half, bar_y),
            fill=color,
            width=line_width,
        )


def draw_alchemy_border(image: Image.Image, colors: dict) -> None:
    """Paint a full transmutation-circle ritual diagram on the panel:
    rectangular ritual boundary + four corner pentagrams + big
    inscribed transmutation circle (double ring + incantation
    tick-band + inscribed pentagram + inner pentagon) + the four
    classical-element glyphs at the outer corners of the inner figure.

    0. **Parchment halftone**: 14 of every 16 yellow ``page_bg`` pixels
       become white on a 4×4 Bayer tile, leaving pale ivory flecked with
       yellow instead of the panel's vivid yellow.
    1. **Outer ritual rule**: a red rectangle, line width 2.
    2. **Four corner pentagrams** in red, radius 22, each in its circle,
       inside the rule.
    3. **Inscribed transmutation circle** centred on the canvas: two
       concentric rings with radial ticks between them (standing in for
       inscribed incantation text), a large inscribed pentagram, and the
       inner pentagon it generates. The body quote overlays it, so the
       whole figure is a 50% blue stipple (dotted hairlines) the black
       serif sits on.
    4. **Four classical-element glyphs** at the outer corners of the
       inner figure, each in its own stippled colour: 🜃 Earth (olive,
       top-left), 🜄 Water (sky, top-right), 🜂 Fire (tangerine,
       bottom-left), 🜁 Air (violet, bottom-right). The heavy downward
       elements sit on top, the light upward ones below; the centre
       positions are left to the circle's arcs.

    The red boundary and corner sigils frame the text; the blue circle
    stands behind it (the red operative / blue philosophical split of
    alchemical manuscripts).
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    rule_color = colors["accent"]               # red ritual boundary
    sigil_color = colors["accent"]              # red corner pentagrams
    hermetic_color = colors["ornament_dark"]    # blue elemental glyphs
    page_bg = colors["page_bg"]                 # yellow — used by the Layer-0 halftone
    stroke = 2

    # ------------------------------------------------------------------
    # Layer 0: Parchment halftone. 14 of every 16 page_bg yellow pixels
    # turn white on a 4×4 Bayer tile, leaving a sparse diagonal pair of
    # yellow flecks per tile that averages to pale ivory. Every pixel is a
    # pure ink, so ``snap_image_to_palette`` is a no-op and glyph edges
    # stay sharp. Painted first so the decoration overpaints it; only
    # exact ``page_bg`` pixels are touched.
    _BAYER_4 = (
        (0, 8, 2, 10),
        (12, 4, 14, 6),
        (3, 11, 1, 9),
        (15, 7, 13, 5),
    )
    halftone_white = SPECTRA6["white"]
    halftone_threshold = 2    # 14 of 16 Bayer cells become white → 87.5% density
    pixels = image.load()
    for y in range(height):
        row = _BAYER_4[y & 3]
        for x in range(width):
            if pixels[x, y] == page_bg and row[x & 3] >= halftone_threshold:
                pixels[x, y] = halftone_white

    # ------------------------------------------------------------------
    # Layer 1: Outer red ritual boundary.
    outer_inset = 14
    draw.rectangle(
        (outer_inset, outer_inset, width - 1 - outer_inset, height - 1 - outer_inset),
        outline=rule_color,
        width=stroke,
    )

    # ------------------------------------------------------------------
    # Layer 2: Corner pentagrams, offset so each circle (radius 22) sits
    # a few px inside the outer rule, contained by it.
    pent_radius = 22
    pent_offset = outer_inset + 26     # = 40
    pent_centres = [
        (pent_offset, pent_offset),
        (width - 1 - pent_offset, pent_offset),
        (pent_offset, height - 1 - pent_offset),
        (width - 1 - pent_offset, height - 1 - pent_offset),
    ]
    for cx, cy in pent_centres:
        _draw_pentagram(draw, cx, cy, pent_radius, sigil_color, line_width=stroke)

    # ------------------------------------------------------------------
    # Geometry shared by the magic circle and the element glyphs.
    centre_x = width // 2
    centre_y = height // 2
    top_y = pent_offset
    bot_y = height - 1 - pent_offset
    flank_radius = 22               # element glyphs; big enough that bar / no-bar reads under the 4 px stroke
    flank_spacing = 80              # px between centre and outer-corner glyph

    # ------------------------------------------------------------------
    # Layer 3: Inscribed transmutation circle: concentric rings carrying a
    # tick band, an inscribed pentagram and the inner pentagon, all at
    # line width 1 so the body quote stays dominant.
    outer_ring_r = 222
    inner_ring_r = 212

    # The inner figure runs straight through the body text, so it paints
    # in a sentinel and is converted below to a 50% (x+y) parity stipple
    # of blue on the parchment: each hairline becomes a faint dotted
    # construction line the black serif sits on. The red outer rule and
    # corner sigils stay solid; they frame the text and don't cross it.
    solid_hermetic = hermetic_color
    hermetic_color = (5, 5, 5)

    # 3a. Outer + inner concentric rings, the band between them where the
    # incantation would be lettered.
    draw.ellipse(
        (centre_x - outer_ring_r, centre_y - outer_ring_r,
         centre_x + outer_ring_r, centre_y + outer_ring_r),
        outline=hermetic_color, width=1,
    )
    draw.ellipse(
        (centre_x - inner_ring_r, centre_y - inner_ring_r,
         centre_x + inner_ring_r, centre_y + inner_ring_r),
        outline=hermetic_color, width=1,
    )

    # 3b. Incantation tick band: 72 radial dashes between the rings (one
    # per 5°), the rhythm of inscribed letters. Real text along that arc
    # would be sub-pixel on the panel and dither into noise.
    tick_count = 72
    for i in range(tick_count):
        theta = math.radians(i * 360 / tick_count)
        cos_t = math.cos(theta)
        sin_t = math.sin(theta)
        x0 = centre_x + (inner_ring_r + 1) * cos_t
        y0 = centre_y + (inner_ring_r + 1) * sin_t
        x1 = centre_x + (outer_ring_r - 1) * cos_t
        y1 = centre_y + (outer_ring_r - 1) * sin_t
        draw.line((x0, y0, x1, y1), fill=hermetic_color, width=1)

    # 3c. Inscribed pentagram (0→2→4→1→3→0), vertices a few px inside the
    # inner ring so the star reads as inscribed, not touching.
    inscribed_pent_r = 195
    inscribed_pent_vertices = [
        (
            centre_x + inscribed_pent_r * math.cos(math.radians(-90 + i * 72)),
            centre_y + inscribed_pent_r * math.sin(math.radians(-90 + i * 72)),
        )
        for i in range(5)
    ]
    pent_path_order = [0, 2, 4, 1, 3, 0]
    for i in range(len(pent_path_order) - 1):
        draw.line(
            (inscribed_pent_vertices[pent_path_order[i]],
             inscribed_pent_vertices[pent_path_order[i + 1]]),
            fill=hermetic_color, width=1,
        )

    # 3d. Inner pentagon through the pentagram's five inner intersections:
    # circumradius = pentagram radius / phi² (≈ 2.618), vertices rotated
    # 36° from the outer ones (-54°, 18°, 90°, …). The body quote overlays
    # this "operative chamber".
    phi_squared = (1 + math.sqrt(5)) ** 2 / 4   # ≈ 2.618
    inner_pent_r = inscribed_pent_r / phi_squared
    inner_pentagon_vertices = [
        (
            centre_x + inner_pent_r * math.cos(math.radians(-54 + i * 72)),
            centre_y + inner_pent_r * math.sin(math.radians(-54 + i * 72)),
        )
        for i in range(5)
    ]
    draw.polygon(inner_pentagon_vertices, outline=hermetic_color, width=1)

    figure_x0 = max(0, centre_x - outer_ring_r - 2)
    figure_y0 = max(0, centre_y - outer_ring_r - 2)
    figure_x1 = min(width - 1, centre_x + outer_ring_r + 2)
    figure_y1 = min(height - 1, centre_y + outer_ring_r + 2)
    for py in range(figure_y0, figure_y1 + 1):
        for px in range(figure_x0, figure_x1 + 1):
            if pixels[px, py] == hermetic_color:
                pixels[px, py] = solid_hermetic if (px + py) & 1 == 0 else halftone_white
    hermetic_color = solid_hermetic

    # ------------------------------------------------------------------
    # Layer 4: Four classical-element glyphs at the outer corners of the
    # inner figure: heavy downward elements top-left / top-right, light
    # upward ones bottom-left / bottom-right. The centre positions are
    # left to the circle's arcs.
    #
    # Each element gets its own 2-ink mix: earth → olive (Y+G 1:1), water
    # → sky (B+W 1:1), fire → tangerine (R+Y 5/8:3/8), air → violet
    # (R+B 1:1), with a heavier stroke (``triangle_stroke``) than the
    # ritual rule.
    #
    # Each triangle is painted in a unique off-palette sentinel, and a
    # per-element bbox post-pass converts exactly those pixels. Don't use
    # an on-palette sentinel: Earth's bbox overlaps the Layer-0 yellow
    # flecks, and a yellow sentinel would flip them too (a visible green
    # rectangle round the glyph).
    #
    # Air is 2-ink violet rather than 3-ink lavender because only the
    # rectangle-only ``_fill_swatch_stipple_3way`` does 3-way mixes.
    triangle_stroke = 4
    earth_sentinel = (1, 1, 1)
    water_sentinel = (2, 2, 2)
    fire_sentinel = (3, 3, 3)
    air_sentinel = (4, 4, 4)
    elements = (
        # (cx, cy, point_up, with_bar, sentinel, dark_ink, light_ink, density, label)
        (centre_x - 2 * flank_spacing, top_y, False, True,
         earth_sentinel, SPECTRA6["yellow"], SPECTRA6["green"], 0.5, "🜃 Earth/olive"),
        (centre_x + 2 * flank_spacing, top_y, False, False,
         water_sentinel, SPECTRA6["blue"], SPECTRA6["white"], 0.5, "🜄 Water/sky"),
        (centre_x - 2 * flank_spacing, bot_y, True, False,
         fire_sentinel, SPECTRA6["red"], SPECTRA6["yellow"], 0.375, "🜂 Fire/tangerine"),
        (centre_x + 2 * flank_spacing, bot_y, True, True,
         air_sentinel, SPECTRA6["red"], SPECTRA6["blue"], 0.5, "🜁 Air/violet"),
    )
    for cx, cy, point_up, with_bar, sentinel, dark_ink, light_ink, density, _ in elements:
        _draw_alchemical_triangle(
            draw, cx, cy, flank_radius, sentinel,
            point_up=point_up, with_bar=with_bar, line_width=triangle_stroke,
        )
        # Per-element bbox post-pass, padded 4 px past flank_radius so
        # antialiased corner pixels stay in scope.
        bx0 = max(0, cx - flank_radius - 4)
        by0 = max(0, cy - flank_radius - 4)
        bx1 = min(width - 1, cx + flank_radius + 4)
        by1 = min(height - 1, cy + flank_radius + 4)
        threshold = round(density * 16)
        if density <= 0.25:
            for py in range(by0, by1 + 1):
                for px in range(bx0, bx1 + 1):
                    if pixels[px, py] == sentinel:
                        pixels[px, py] = light_ink if (px & 1) == 0 and (py & 1) == 0 else dark_ink
        elif density >= 0.5:
            for py in range(by0, by1 + 1):
                for px in range(bx0, bx1 + 1):
                    if pixels[px, py] == sentinel:
                        pixels[px, py] = light_ink if (px + py) & 1 == 0 else dark_ink
        else:
            for py in range(by0, by1 + 1):
                row = BAYER_4x4[py & 3]
                for px in range(bx0, bx1 + 1):
                    if pixels[px, py] == sentinel:
                        pixels[px, py] = light_ink if row[px & 3] < threshold else dark_ink
    # The element triangles use their own inks; ``hermetic_color`` is done.
    del hermetic_color


def draw_swiss_border(image: Image.Image, colors: dict) -> None:
    """Paint the Swiss International theme's deliberately minimal frame.

    The identity is what's missing: two marks near the top, the
    Müller-Brockmann / Vignelli grid.

    * A 1 px black hairline at ``y = 60``, dividing a small header zone
      from the body: the asymmetric-grid gesture of Swiss poster design.
    * A 6×6 px red square at ``(width - 40, 42)``, the only chromatic
      accent besides the matched phrase.

    No corners, no frame, no second rule, no Layer-0 wash. The rule uses
    ``colors["text"]`` and the square ``colors["accent"]``.
    """
    draw = ImageDraw.Draw(image)
    width, _ = image.size
    ink = colors["text"]
    accent = colors["accent"]
    rule_y = 60
    draw.line((SIDE_MARGIN, rule_y, width - SIDE_MARGIN, rule_y), fill=ink, width=1)
    # The red square sits between the y=14..29 debug-banner band and the
    # y=60 rule, just above the rule so it reads as a tag on it.
    square_x = width - 40
    square_y = 42
    square_size = 6
    draw.rectangle(
        (square_x, square_y, square_x + square_size, square_y + square_size),
        fill=accent,
    )


def draw_herbarium_border(image: Image.Image, colors: dict) -> None:
    """Paint a 19th-century pressed-plant specimen-sheet frame.

    * **Layer 0: sparse 1-in-8 yellow-on-white cream wash** (the Y+W
      Bayer-threshold-2 recipe of ``illuminated`` / ``dispatch``). Only
      exact ``page_bg`` pixels flip, so non-standard test palettes stay
      valid.
    * **Engraver's hairline rule** at inset 14 px, single and black; a
      double rule would compete with the specimen.
    * **Pressed leaf** in the bottom-right: an ~84×42 px oval painted in
      a yellow sentinel and half flipped to green on ``(x+y) & 1`` (Y+G
      olive, dried-leaf colour), with a solid green midrib and three
      pairs of veins. Painted before the text, so text sits on top.
    * **Specimen cartouche** in the bottom-left, the leaf's diagonal
      counterweight: a ~140×32 px black outline holding ``"Tempus fugit"``
      in small IM Fell English italic (META_FONT chain fallback).
    * **Four pinhole dots** at the inner corners of the rule, where the
      specimen would be pinned.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    ink = colors["text"]
    page_bg = colors.get("page_bg")
    cream_light = SPECTRA6["yellow"]
    olive_sentinel = cream_light
    olive_other = SPECTRA6["green"]

    pixels = image.load()
    if page_bg is not None:
        for y in range(height):
            row = BAYER_4x4[y & 3]
            for x in range(width):
                if pixels[x, y] == page_bg and row[x & 3] < 2:
                    pixels[x, y] = cream_light

    outer_inset = 14
    draw.rectangle(
        (outer_inset, outer_inset, width - 1 - outer_inset, height - 1 - outer_inset),
        outline=ink,
        width=1,
    )

    # Pressed leaf (bottom-right): a horizontal ellipse in the olive
    # sentinel (yellow), half flipped to green below.
    leaf_w = 84
    leaf_h = 42
    leaf_inset = 38
    leaf_cx = width - 1 - leaf_inset - leaf_w // 2
    leaf_cy = height - 1 - leaf_inset - leaf_h // 2
    leaf_left = leaf_cx - leaf_w // 2
    leaf_right = leaf_cx + leaf_w // 2
    leaf_top = leaf_cy - leaf_h // 2
    leaf_bot = leaf_cy + leaf_h // 2
    draw.ellipse((leaf_left, leaf_top, leaf_right, leaf_bot), fill=olive_sentinel)
    # Stem extending up-right from the leaf, same olive sentinel.
    stem_x0 = leaf_right - 4
    stem_y0 = leaf_cy
    stem_x1 = stem_x0 + 18
    stem_y1 = stem_y0 - 14
    draw.line((stem_x0, stem_y0, stem_x1, stem_y1), fill=olive_sentinel, width=2)
    # Midrib in solid green, which the post-pass leaves alone.
    draw.line((leaf_left + 6, leaf_cy, leaf_right - 6, leaf_cy), fill=olive_other, width=1)
    # Three pairs of side veins fanning outward from the midrib.
    for offset in (-12, 0, 12):
        vx = leaf_cx + offset
        draw.line((vx, leaf_cy, vx - 8, leaf_top + 6), fill=olive_other, width=1)
        draw.line((vx, leaf_cy, vx + 8, leaf_bot - 6), fill=olive_other, width=1)
    # Olive post-pass: flip half the yellow sentinel pixels to green.
    bx0 = max(0, leaf_left - 1)
    by0 = max(0, leaf_top - 16)  # cover the stem too
    bx1 = min(width - 1, max(leaf_right, stem_x1) + 1)
    by1 = min(height - 1, leaf_bot + 1)
    for py in range(by0, by1 + 1):
        for px in range(bx0, bx1 + 1):
            if pixels[px, py] == olive_sentinel and (px + py) & 1:
                pixels[px, py] = olive_other

    # Specimen cartouche (bottom-left). Outline rectangle + small Latin tag.
    label_w = 140
    label_h = 32
    label_inset = 32
    label_x0 = label_inset
    label_y0 = height - 1 - label_inset - label_h
    label_x1 = label_x0 + label_w
    label_y1 = label_y0 + label_h
    draw.rectangle((label_x0, label_y0, label_x1, label_y1), outline=ink, width=1)
    # IM Fell italic at 14 px so the label reads as a tag, not a heading;
    # the META chain guarantees it renders.
    label_text = "Tempus fugit"
    label_font_candidates = [
        IMFELLENGLISH_ITALIC,
        IMFELLENGLISH_REGULAR,
        "/usr/share/fonts/truetype/dejavu/DejaVuSerif-Italic.ttf",
        *META_FONT_CANDIDATES,
    ]
    label_font = load_font(label_font_candidates, size=14)
    bbox = draw.textbbox((0, 0), label_text, font=label_font)
    text_w = bbox[2] - bbox[0]
    text_h = bbox[3] - bbox[1]
    tx = label_x0 + (label_w - text_w) // 2
    ty = label_y0 + (label_h - text_h) // 2 - bbox[1]
    draw.text((tx, ty), label_text, font=label_font, fill=ink)
    # A writing rule under the tag, so the box reads as a specimen label.
    draw.line((label_x0 + 8, label_y1 - 6, label_x1 - 8, label_y1 - 6), fill=ink, width=1)

    # Four pinhole dots at the inner corners of the engraver's rule.
    pinhole_offset = 3
    pinhole_radius = 1
    for cx, cy in (
        (outer_inset + pinhole_offset, outer_inset + pinhole_offset),
        (width - 1 - outer_inset - pinhole_offset, outer_inset + pinhole_offset),
        (outer_inset + pinhole_offset, height - 1 - outer_inset - pinhole_offset),
        (width - 1 - outer_inset - pinhole_offset, height - 1 - outer_inset - pinhole_offset),
    ):
        draw.ellipse(
            (cx - pinhole_radius, cy - pinhole_radius, cx + pinhole_radius, cy + pinhole_radius),
            fill=ink,
        )

    # Second specimen: a small fern frond in the top-left margin,
    # counterweighting the bottom-right leaf; same olive recipe.
    fern_x = 54
    fern_top = 34
    fern_bot = 108
    draw.line((fern_x, fern_top, fern_x, fern_bot), fill=olive_sentinel, width=2)
    for fy in range(fern_top + 8, fern_bot, 11):
        span = max(4, (fern_bot - fy) // 6)  # leaflets taper toward the tip
        draw.line((fern_x, fy, fern_x - 10, fy - span), fill=olive_sentinel, width=1)
        draw.line((fern_x, fy, fern_x + 10, fy - span), fill=olive_sentinel, width=1)
    for py in range(fern_top - 2, fern_bot + 2):
        for px in range(fern_x - 12, fern_x + 12):
            if 0 <= px < width and 0 <= py < height and pixels[px, py] == olive_sentinel and (px + py) & 1:
                pixels[px, py] = olive_other

    # Gummed linen tape strips holding the main leaf flat.
    for ty_strip in (leaf_cy - 18, leaf_cy + 16):
        draw.rectangle(
            (leaf_cx - 22, ty_strip - 3, leaf_cx + 22, ty_strip + 3),
            fill=SPECTRA6["white"],
            outline=ink,
        )


def _draw_mucha_vine(
    draw: ImageDraw.ImageDraw,
    pixels,
    width: int,
    height: int,
    cx: int,
    cy: int,
    direction: int,
    stem_ink,
    leaf_ink,
    leaf_other,
    berry_sentinel,
) -> tuple[int, int, int, int]:
    """Paint one S-shaped vine with three trefoil leaves and a berry at the tip.

    ``direction`` is ``+1`` for a vine running down-right from ``(cx, cy)``
    (top-left corner) and ``-1`` for the mirror running up-left
    (bottom-right corner). Returns the ornament's bbox for the caller's
    post-passes.
    """
    # S-shaped stem as a 7-point polyline over 110 px (PIL has no curve
    # primitive; ``atomic``'s orbits use the same trick).
    stem_pts: list[tuple[int, int]] = []
    for i in range(7):
        t = i / 6.0
        # Two-lobe S: x swings ~18 px round the centre while y advances
        # linearly along ``direction``.
        x_off = round(18 * math.sin(t * math.pi * 1.6) * direction)
        y_off = round(direction * t * 110)
        stem_pts.append((cx + x_off, cy + y_off))
    draw.line(stem_pts, fill=stem_ink, width=2)

    # Three trefoil leaves sprouting along the stem at t = 1/4, 1/2, 3/4.
    leaf_centres: list[tuple[int, int]] = []
    for t_frac in (0.25, 0.5, 0.75):
        idx = round(t_frac * (len(stem_pts) - 1))
        sx, sy = stem_pts[idx]
        # Leaves alternate left / right of the stem.
        side = direction if t_frac == 0.5 else -direction
        leaf_centres.append((sx + side * 16, sy + (8 if t_frac < 0.5 else -6) * direction))

    leaf_radii = (9, 5)  # lobe offset from the leaf centre / lobe radius
    for lcx, lcy in leaf_centres:
        # Each trefoil is three overlapping circles fanning from the
        # attachment point, in the leaf sentinel for the olive post-pass.
        for angle_deg in (-30, 0, 30):
            angle = math.radians(angle_deg)
            ex = lcx + round(leaf_radii[0] * math.cos(angle) * direction)
            ey = lcy + round(leaf_radii[0] * math.sin(angle))
            draw.ellipse(
                (ex - leaf_radii[1], ey - leaf_radii[1], ex + leaf_radii[1], ey + leaf_radii[1]),
                fill=leaf_ink,
            )

    # Berry at the stem tip in ``berry_sentinel``; the caller does the
    # R+Y tangerine post-pass.
    tip_x, tip_y = stem_pts[-1]
    berry_radius = 5
    draw.ellipse(
        (tip_x - berry_radius, tip_y - berry_radius, tip_x + berry_radius, tip_y + berry_radius),
        fill=berry_sentinel,
    )

    # Ornament bbox, padded so the trefoils and berry are inside.
    xs = [p[0] for p in stem_pts] + [lc[0] for lc in leaf_centres] + [tip_x]
    ys = [p[1] for p in stem_pts] + [lc[1] for lc in leaf_centres] + [tip_y]
    bx0 = max(0, min(xs) - leaf_radii[0] - 2)
    by0 = max(0, min(ys) - leaf_radii[0] - 2)
    bx1 = min(width - 1, max(xs) + leaf_radii[0] + 2 + berry_radius)
    by1 = min(height - 1, max(ys) + leaf_radii[0] + 2 + berry_radius)
    return (bx0, by0, bx1, by1)


def draw_mucha_border(image: Image.Image, colors: dict) -> None:
    """Paint an Art Nouveau / Mucha frame: cream Layer-0 wash + thin
    teal rule + organic vine ornaments at two diagonal corners.

    * **Layer 0: cream ground wash**, the Y+W Bayer recipe of
      ``illuminated`` / ``dispatch``: aged ivory poster stock.
    * **Thin teal rule** at inset 18: painted green, then half its
      perimeter flipped to blue on ``(x+y) & 1`` (G+B cyan), matching the
      cyan matched phrase from ``_draw_text_body``.
    * **Vines at the top-left and bottom-right corners**: an S-shaped
      stem (red sentinel → R+K maroon, as the body), trefoil leaves
      (yellow sentinel → Y+G olive, as ``roman``'s laurel) and a berry
      blossom at the tip (→ R+Y 5/8:3/8 tangerine on ``BAYER_4x4``, as
      ``deco``). The other two corners stay bare on purpose: Mucha
      composes asymmetrically.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    page_bg = colors.get("page_bg")
    cream_light = SPECTRA6["yellow"]
    # Sentinels are on-palette inks; each is post-passed to the second ink
    # of its recipe straight after painting.
    stem_sentinel = SPECTRA6["red"]
    stem_other = SPECTRA6["black"]
    leaf_sentinel = SPECTRA6["yellow"]
    leaf_other = SPECTRA6["green"]
    berry_sentinel = SPECTRA6["red"]
    berry_other = SPECTRA6["yellow"]
    rule_sentinel = SPECTRA6["green"]
    rule_other = SPECTRA6["blue"]

    pixels = image.load()
    # Layer 0: sparse 1-in-8 yellow-on-white cream wash.
    if page_bg is not None:
        for y in range(height):
            row = BAYER_4x4[y & 3]
            for x in range(width):
                if pixels[x, y] == page_bg and row[x & 3] < 2:
                    pixels[x, y] = cream_light

    rule_inset = 18
    # Outer rule in the green sentinel, post-passed to cyan.
    draw.rectangle(
        (rule_inset, rule_inset, width - 1 - rule_inset, height - 1 - rule_inset),
        outline=rule_sentinel,
        width=1,
    )
    # Perimeter post-pass: flip half the green pixels to blue → cyan.
    for x in range(rule_inset, width - rule_inset):
        for y in (rule_inset, height - 1 - rule_inset):
            if pixels[x, y] == rule_sentinel and (x + y) & 1:
                pixels[x, y] = rule_other
    for y in range(rule_inset, height - rule_inset):
        for x in (rule_inset, width - 1 - rule_inset):
            if pixels[x, y] == rule_sentinel and (x + y) & 1:
                pixels[x, y] = rule_other

    # Top-left vine.
    tl_bbox = _draw_mucha_vine(
        draw, pixels, width, height,
        cx=rule_inset + 22, cy=rule_inset + 22, direction=+1,
        stem_ink=stem_sentinel, leaf_ink=leaf_sentinel,
        leaf_other=leaf_other, berry_sentinel=berry_sentinel,
    )
    # Bottom-right vine.
    br_bbox = _draw_mucha_vine(
        draw, pixels, width, height,
        cx=width - 1 - rule_inset - 22, cy=height - 1 - rule_inset - 22, direction=-1,
        stem_ink=stem_sentinel, leaf_ink=leaf_sentinel,
        leaf_other=leaf_other, berry_sentinel=berry_sentinel,
    )

    # Stem post-pass: R+K 1:1 maroon, stem sentinel only, so the yellow
    # leaves are left for their own pass.
    for bbox in (tl_bbox, br_bbox):
        bx0, by0, bx1, by1 = bbox
        for py in range(by0, by1 + 1):
            for px in range(bx0, bx1 + 1):
                if pixels[px, py] == stem_sentinel and (px + py) & 1:
                    pixels[px, py] = stem_other
    # Leaf post-pass: Y+G 1:1 olive.
    for bbox in (tl_bbox, br_bbox):
        bx0, by0, bx1, by1 = bbox
        for py in range(by0, by1 + 1):
            for px in range(bx0, bx1 + 1):
                if pixels[px, py] == leaf_sentinel and (px + py) & 1:
                    pixels[px, py] = leaf_other
    # Berry post-pass: R+Y 5/8:3/8 → tangerine. The berry shares the
    # stem's red sentinel, so it is redone in a small radius round each tip.
    for bbox, direction in ((tl_bbox, +1), (br_bbox, -1)):
        bx0, by0, bx1, by1 = bbox
        # The stem pass turned half the berry's red pixels black, so the
        # tip region is repainted tangerine. The tip isn't returned by the
        # helper; it is recovered from the bbox.
        if direction == +1:
            tip_x = bx1 - 7
            tip_y = by1 - 7
        else:
            tip_x = bx0 + 7
            tip_y = by0 + 7
        # Five-petal blossom at the tip, in the berry sentinel so the
        # tangerine pass below picks it up.
        petal_r = 4
        petal_dist = 7
        for k in range(5):
            ang = -math.pi / 2 + k * (2 * math.pi / 5)
            px_c = tip_x + round(petal_dist * math.cos(ang))
            py_c = tip_y + round(petal_dist * math.sin(ang))
            draw.ellipse(
                (px_c - petal_r, py_c - petal_r, px_c + petal_r, py_c + petal_r),
                fill=berry_sentinel,
            )
        core_radius = 6   # central berry: repaint every pixel
        halo_radius = 14  # petal ring: repaint only sentinel petal pixels
        core_sq = core_radius * core_radius
        halo_sq = halo_radius * halo_radius
        for py in range(max(0, tip_y - halo_radius), min(height - 1, tip_y + halo_radius) + 1):
            row = BAYER_4x4[py & 3]
            for px in range(max(0, tip_x - halo_radius), min(width - 1, tip_x + halo_radius) + 1):
                dx = px - tip_x
                dy = py - tip_y
                d_sq = dx * dx + dy * dy
                if d_sq <= core_sq:
                    # Central berry: repaint the whole disc (overwriting the
                    # stem pass's blacks) at threshold 6/16 → tangerine.
                    pixels[px, py] = berry_other if row[px & 3] < 6 else berry_sentinel
                elif d_sq <= halo_sq and pixels[px, py] == berry_sentinel:
                    # Petal ring: only the petal pixels flip; the ground
                    # between petals stays, so five petals read, not a disc.
                    pixels[px, py] = berry_other if row[px & 3] < 6 else berry_sentinel


_KANAGAWA_BIRD_ANCHORS: tuple[tuple[float, float, int, int, int], ...] = (
    # (cx_frac, cy_frac, wingspan, left_droop, right_droop): distant
    # ink-stroke birds in the upper sky, well above the text. Two strokes
    # each with asymmetric droop so the five read as distinct birds;
    # 18-26 px wingspans at 2 px stroke stay visible on the sky wash.
    (0.20, 0.06, 22,  6,  9),    # banking right
    (0.34, 0.04, 18,  4,  4),    # gliding level
    (0.52, 0.08, 26, 10,  4),    # banking left
    (0.66, 0.05, 20,  5,  8),    # banking right
    (0.82, 0.07, 18,  6,  3),    # banking left
)


# Seigaiha (青海波 / "blue ocean waves") tile radius: mid-way between a dense
# woven-fabric look (smaller) and a graphic tile motif (larger).
_SEIGAIHA_TILE_RADIUS = 28
# Concentric white arcs in each tile. With row overlap radius // 2 = 14,
# each tile shows a 14 px crescent: room for three arcs ~5 px apart.
_SEIGAIHA_RING_RADII: tuple[int, ...] = (23, 18, 13)


def _draw_seigaiha_band(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    band_top_y: int,
    band_bottom_y: int,
    blue_ink: tuple[int, int, int],
    white_ink: tuple[int, int, int],
    black_ink: tuple[int, int, int],
    *,
    radius: int = _SEIGAIHA_TILE_RADIUS,
) -> None:
    """Fill the horizontal band ``(0, band_top_y) – (width, band_bottom_y)``
    with the seigaiha (青海波 / "blue ocean waves") tile pattern.

    Each tile is an indigo upper half-disk (pie slice 180°–360°) with three
    thin white arcs at ``_SEIGAIHA_RING_RADII``. Rows are ``radius // 2``
    apart, so each row overpaints the lower half of the one above and only
    a 14 px crescent per scale shows. Alternate rows shift by half the
    column spacing so the scales interlock, and the tiling overshoots the
    band edges so no border shows.

    The deepest rows get a navy stipple (B+K 1:1, the recipe of the
    kanagawa matched phrase), so the sea darkens toward the bottom.
    """
    width = image.size[0]
    row_spacing = max(8, radius // 2)
    col_spacing = radius

    # Top of the "deepest" rows, post-passed to navy after the tiles.
    deepest_band_top = max(band_top_y, band_bottom_y - row_spacing * 2)

    y = band_top_y
    row = 0
    while y <= band_bottom_y + row_spacing:
        x_offset = (col_spacing // 2) if row % 2 == 1 else 0
        x = -col_spacing + x_offset
        while x <= width + col_spacing:
            # Filled upper half-disk (the scale body) in indigo.
            draw.pieslice(
                (x - radius, y - radius, x + radius, y + radius),
                180, 360, fill=blue_ink,
            )
            # Three concentric white arc stripes inside the scale.
            for ring_r in _SEIGAIHA_RING_RADII:
                draw.arc(
                    (x - ring_r, y - ring_r, x + ring_r, y + ring_r),
                    180, 360, fill=white_ink, width=1,
                )
            x += col_spacing
        y += row_spacing
        row += 1

    # Navy depth post-pass on the deepest rows: half the blue pixels flip
    # to black on (x+y)&1 (B+K 1:1). Bounds are clamped to the canvas,
    # because PIL's PixelAccess raises on negative indices instead of
    # clipping like the drawing primitives.
    pixels = image.load()
    py_start = max(0, deepest_band_top)
    py_end = min(image.size[1] - 1, band_bottom_y)
    for py in range(py_start, py_end + 1):
        for px in range(width):
            if pixels[px, py] == blue_ink and ((px + py) & 1) == 0:
                pixels[px, py] = black_ink


def draw_kanagawa_border(
    image: Image.Image,
    colors: dict,
    clear_rect: tuple[int, int, int, int] | None = None,
) -> None:
    """Paint a stylised Japanese seascape: graduated sky-blue Bayer wash,
    five ink-stroke birds, a stippled horizon, the seigaiha (青海波) tile
    band at the bottom, and a maroon hanko seal in the bottom-right. No
    outer frame: ukiyo-e prints have none (as ``fillmore``).

    * **Layer 0: graduated sky wash.** Only ``page_bg`` pixels above the
      horizon (y ≈ 0.55 × height) are touched; the Bayer threshold tapers
      from ~5/16 blue at the top to 0 at the horizon: morning haze.
    * **Distant birds** from ``_KANAGAWA_BIRD_ANCHORS``: black two-stroke
      Vs in the upper sky.
    * **Horizon line**: a sparse stippled blue line at y ≈ 0.62 × height.
    * **Seigaiha band** (bottom ~34%): see ``_draw_seigaiha_band``.
    * **Hanko seal** (~32×38 px): a red rounded rectangle half flipped to
      black on ``(x+y)&1`` (R+K maroon), with a stylised 川 ("river") in
      2 px white strokes painted after the post-pass so they stay solid.

    When ``clear_rect`` is given (the standard render path, as for
    ``blueprint``), the body rect becomes a cream paper card over the
    textile, so the band can run up to the text without hurting
    legibility.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    page_bg = colors.get("page_bg")
    white_ink = SPECTRA6["white"]
    black_ink = SPECTRA6["black"]
    red_ink = SPECTRA6["red"]
    blue_ink = SPECTRA6["blue"]

    pixels = image.load()

    # ------------------------------------------------------------------
    # Layer 0: vertically graduated sky-blue Bayer wash.
    horizon_y = round(height * 0.55)
    if page_bg is not None:
        for y in range(horizon_y):
            thr = max(0, round(5 * (1 - y / max(1, horizon_y))))
            if thr == 0:
                continue
            row = BAYER_4x4[y & 3]
            for x in range(width):
                if pixels[x, y] == page_bg and row[x & 3] < thr:
                    pixels[x, y] = blue_ink

    # ------------------------------------------------------------------
    # Distant birds in the upper sky.
    for cx_frac, cy_frac, wingspan, left_droop, right_droop in _KANAGAWA_BIRD_ANCHORS:
        bx = round(cx_frac * width)
        by = round(cy_frac * height)
        wing = wingspan // 2
        draw.line((bx - wing, by - left_droop, bx, by), fill=black_ink, width=2)
        draw.line((bx, by, bx + wing, by - right_droop), fill=black_ink, width=2)

    # ------------------------------------------------------------------
    # Horizon line just above the seigaiha band, two rows. Bounds-guarded
    # so y+1 can't run off the canvas on tiny previews (80x60).
    horizon_line_y = round(height * 0.62)
    if page_bg is not None and 0 <= horizon_line_y < height:
        horizon_row = BAYER_4x4[horizon_line_y & 3]
        for px in range(width):
            if pixels[px, horizon_line_y] == page_bg and horizon_row[px & 3] < 4:
                pixels[px, horizon_line_y] = blue_ink
        next_y = horizon_line_y + 1
        if next_y < height:
            next_row = BAYER_4x4[next_y & 3]
            for px in range(width):
                if pixels[px, next_y] == page_bg and next_row[px & 3] < 4:
                    pixels[px, next_y] = blue_ink

    # ------------------------------------------------------------------
    # Seigaiha tile band from y = 0.66 × height to the bottom (~163 px at
    # 480, about 12 rows).
    band_top_y = round(height * 0.66)
    _draw_seigaiha_band(
        image, draw, band_top_y, height - 1, blue_ink, white_ink, black_ink
    )

    # ------------------------------------------------------------------
    # Hanko seal (bottom-right): a red rounded rectangle softened to
    # oxblood by a maroon post-pass (R+K 1:1, as ``dispatch`` and
    # ``chanbara``), then a stylised 川 in 2 px white strokes. 32×38 px
    # gives the strokes room; smaller reads as scratches.
    seal_w = 32
    seal_h = 38
    seal_margin = 26
    seal_x0 = width - seal_margin - seal_w
    seal_y0 = height - seal_margin - seal_h
    seal_x1 = seal_x0 + seal_w
    seal_y1 = seal_y0 + seal_h
    # ``rounded_rectangle`` clips out-of-bounds coordinates, so on a tiny
    # canvas (the 80x60 preview, ``seal_y0`` = -4) it paints what fits.
    draw.rounded_rectangle((seal_x0, seal_y0, seal_x1, seal_y1), radius=3, fill=red_ink)
    # Maroon post-pass, bounds clamped first: PixelAccess raises on
    # negative indices. Skipped when the seal is fully off-canvas.
    seal_px0 = max(0, seal_x0)
    seal_py0 = max(0, seal_y0)
    seal_px1 = min(width - 1, seal_x1)
    seal_py1 = min(height - 1, seal_y1)
    if seal_px0 <= seal_px1 and seal_py0 <= seal_py1:
        for py in range(seal_py0, seal_py1 + 1):
            for px in range(seal_px0, seal_px1 + 1):
                if pixels[px, py] == red_ink and ((px + py) & 1) == 0:
                    pixels[px, py] = black_ink
    # Stylised 川: three vertical white strokes, the leftmost kinked at the
    # top like a brush entering down-right. 2 px matches a hanko's weight.
    stroke_inset_x = 7
    stroke_inset_y = 6
    sx0 = seal_x0 + stroke_inset_x
    sx1 = seal_x1 - stroke_inset_x
    sxm = (seal_x0 + seal_x1) // 2
    sy0 = seal_y0 + stroke_inset_y
    sy1 = seal_y1 - stroke_inset_y
    # Left stroke — kinked at the top (brush-down motion).
    draw.line((sx0 + 3, sy0, sx0, sy0 + 4), fill=white_ink, width=2)
    draw.line((sx0, sy0 + 4, sx0, sy1), fill=white_ink, width=2)
    # Middle stroke — slightly shorter than the flanking strokes.
    draw.line((sxm, sy0 + 5, sxm, sy1 - 3), fill=white_ink, width=2)
    # Right stroke.
    draw.line((sx1, sy0, sx1, sy1), fill=white_ink, width=2)

    # ------------------------------------------------------------------
    # Body-text knockout: a cream rounded paper card. Inside clear_rect,
    # a white rounded rectangle (radius 12) with a 2 px drop shadow and a
    # 1 px outline, then a sparse yellow stipple. Rounded corners read as
    # a pressed paper card laid on the textile; the corners outside the
    # arc stay seigaiha, which is safe because the kanagawa clear-rect pad
    # keeps the text well inside the card.
    if clear_rect is not None and page_bg is not None:
        cx0, cy0, cx1, cy1 = clear_rect
        cx0 = max(0, cx0)
        cy0 = max(0, cy0)
        cx1 = min(width - 1, cx1)
        cy1 = min(height - 1, cy1)
    # Skip the knockout if the clamped rect collapsed: ``rounded_rectangle``
    # raises ``ValueError`` when ``x1 < x0`` or ``y1 < y0``, which the
    # 80x60 preview can produce.
    if (
        clear_rect is not None
        and page_bg is not None
        and cx1 > cx0
        and cy1 > cy0
    ):
        # Drop shadow: a black rounded rect offset 2 px right and down; the
        # card covers all but a 2 px ledge, read as a lifted paper edge.
        # Deeper would cast a hard shadow.
        draw.rounded_rectangle(
            (cx0 + 2, cy0 + 2, cx1 + 2, cy1 + 2),
            radius=12, fill=black_ink,
        )
        draw.rounded_rectangle((cx0, cy0, cx1, cy1), radius=12, fill=white_ink)
        # 1 px black outline round the card (follows the rounded corners).
        draw.rounded_rectangle(
            (cx0, cy0, cx1, cy1), radius=12, outline=black_ink, width=1,
        )
        # Cream stipple: a yellow dot at four fixed (x, y) positions per
        # 8×8 tile, ~6.25% density. The off-grid anchors avoid the
        # period-4 lattice a 4×4 Bayer pattern shows against the indigo;
        # W + Y averages to warm vellum.
        yellow_ink = SPECTRA6["yellow"]
        cream_anchors = frozenset({(1, 3), (5, 6), (2, 7), (6, 2)})
        for py in range(cy0, cy1 + 1):
            y8 = py & 7
            for px in range(cx0, cx1 + 1):
                x8 = px & 7
                if pixels[px, py] == white_ink and (x8, y8) in cream_anchors:
                    pixels[px, py] = yellow_ink


def _build_fillmore_blob(cx: int, cy: int, scale: float, seed: int) -> list[tuple[int, int]]:
    """Return an 18-point free-form "melted amoeba" polygon centred on ``(cx, cy)``.

    Deterministic per ``seed``. Nominal radius is ~80×``scale`` px.
    """
    rng = random.Random(seed)
    n = 18
    base_r = 80 * scale
    points: list[tuple[int, int]] = []
    for i in range(n):
        angle = (i / n) * 2 * math.pi
        # Per-vertex radial wobble, ~0.55..1.25 of base_r, keeps it organic.
        wobble = 0.55 + rng.random() * 0.7
        r = base_r * wobble
        x = cx + round(r * math.cos(angle))
        y = cy + round(r * math.sin(angle))
        points.append((x, y))
    return points


def draw_fillmore_border(image: Image.Image, colors: dict) -> None:
    """Paint a 1960s Fillmore poster frame: Layer-0 white wash that
    tempers the saturated-yellow ground, plus corner blob panels in
    diagonal balance, sized to clear the body text area.

    * **Layer 0: sparse 1-in-8 white-on-yellow Bayer wash.** ~2/16 of
      the yellow ``page_bg`` pixels (``BAYER_4x4 < 2``) turn white, the
      cream-wash primitive run in reverse: the saturated yellow softens
      toward sun-faded poster stock without becoming cream. Only exact
      ``page_bg`` pixels flip.
    * **Green blob** in the top-left: a seeded 18-point polygon with a red
      5-point star at its centre, inside the y < 72 top margin.
    * **Blue blob** in the bottom-right, same size, with a yellow disc.

    No outer frame: the corner blobs ground the composition, as on real
    Fillmore posters. Together with the body and matched phrase, all six
    native inks appear on the page.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    green_ink = SPECTRA6["green"]
    blue_ink = SPECTRA6["blue"]
    red_ink = SPECTRA6["red"]
    yellow_ink = SPECTRA6["yellow"]
    page_bg = colors.get("page_bg")

    # Layer 0: sparse 1-in-8 white-on-yellow Bayer wash. Only exact
    # ``page_bg`` pixels flip; skipped when ``page_bg`` is absent so
    # direct-call test paths providing only ``text`` stay valid.
    if page_bg is not None:
        pixels = image.load()
        for y in range(height):
            row = BAYER_4x4[y & 3]
            for x in range(width):
                if pixels[x, y] == page_bg and row[x & 3] < 2:
                    pixels[x, y] = SPECTRA6["white"]

    # Green blob (TL). At scale=0.4 (base radius 32) this seed spans
    # x≈4..74, y≈8..66, inside the y<72 top margin.
    tl_cx = 38
    tl_cy = 38
    tl_blob = _build_fillmore_blob(tl_cx, tl_cy, scale=0.4, seed=1)
    draw.polygon(tl_blob, fill=green_ink)
    # Small red 5-point star inside the green blob.
    star_r_outer = 12
    star_r_inner = 5
    star_pts: list[tuple[int, int]] = []
    for i in range(10):
        angle = -math.pi / 2 + i * math.pi / 5
        r = star_r_outer if i % 2 == 0 else star_r_inner
        star_pts.append((
            tl_cx + round(r * math.cos(angle)),
            tl_cy + round(r * math.sin(angle)),
        ))
    draw.polygon(star_pts, fill=red_ink)

    # Blue blob (BR), mirrored, same scale.
    br_cx = width - 38
    br_cy = height - 38
    br_blob = _build_fillmore_blob(br_cx, br_cy, scale=0.4, seed=2)
    draw.polygon(br_blob, fill=blue_ink)
    # Small yellow filled circle inside the blue blob.
    inner_r = 12
    draw.ellipse(
        (br_cx - inner_r, br_cy - inner_r, br_cx + inner_r, br_cy + inner_r),
        fill=yellow_ink,
    )


# Seed for the deterministic firmament star scatter (see
# ``_build_firmament_stars``). Stars stay in the top margin (y 4-64) and
# the bottom margin (y height-64 to height-4), clear of the body text
# (block_top ≥ 72) and the attribution.
_FIRMAMENT_STAR_SEED = 0xF18


def _build_firmament_stars(width: int, height: int) -> list[tuple[int, int, int]]:
    """Return 150 deterministic (x, y, magnitude) stars in the top and
    bottom decoration margins. Magnitude 1 = brightest (8-point sparkle),
    2 = 4-point cross, 3 = 2x2 cluster, 4 = single pixel. Reseeded per call,
    so any canvas size gives a stable scatter.
    """
    rng = random.Random(_FIRMAMENT_STAR_SEED)
    stars: list[tuple[int, int, int]] = []
    side_margin = 20

    def _add(count: int, magnitude: int) -> None:
        for _ in range(count):
            x = rng.randint(side_margin, width - side_margin - 1)
            # Top or bottom margin band (each ~60 px tall), 50/50.
            if rng.random() < 0.5:
                y = rng.randint(4, 64)
            else:
                y = rng.randint(height - 64, height - 4)
            stars.append((x, y, magnitude))

    _add(80, 4)   # very faint pinprick stars
    _add(40, 3)   # faint 2x2 clusters
    _add(20, 2)   # medium 4-point crosses
    _add(10, 1)   # bright 8-point sparkles
    return stars


def _paint_firmament_star(pixels, width: int, height: int, sx: int, sy: int, magnitude: int) -> None:
    """Paint one yellow star at (sx, sy). Magnitude sets the shape:

    * mag 4: single pixel
    * mag 3: 2×2 cluster
    * mag 2: 4-point cross with 2px arms + a centre dot
    * mag 1: 8-point sparkle, long N/S/E/W rays tapering from 3px to 1px
      plus shorter diagonals, like the bright stars of 17th-century
      celestial atlases.
    """
    yellow = SPECTRA6["yellow"]

    def _set(ax: int, ay: int) -> None:
        if 0 <= ax < width and 0 <= ay < height:
            pixels[ax, ay] = yellow

    if magnitude >= 4:
        _set(sx, sy)
    elif magnitude == 3:
        for dy in (0, 1):
            for dx in (0, 1):
                _set(sx + dx, sy + dy)
    elif magnitude == 2:
        # 4-point cross: a 2x2 core with one-pixel arms.
        for dy in (0, 1):
            for dx in (0, 1):
                _set(sx + dx, sy + dy)
        _set(sx + 2, sy)
        _set(sx + 2, sy + 1)
        _set(sx - 1, sy)
        _set(sx - 1, sy + 1)
        _set(sx, sy + 2)
        _set(sx + 1, sy + 2)
        _set(sx, sy - 1)
        _set(sx + 1, sy - 1)
    else:
        # Magnitude 1: 8-point sparkle. 3x3 core, 1 px cardinal rays to
        # 5 px, 2 px diagonal stubs.
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                _set(sx + dx, sy + dy)
        # Long cardinal rays, 1 px wide past the core.
        for offset in range(2, 6):
            _set(sx, sy - offset)  # N
            _set(sx, sy + offset)  # S
            _set(sx - offset, sy)  # W
            _set(sx + offset, sy)  # E
        # Inter-cardinal sparkle accents (2px diagonal stubs).
        for offset in (2, 3):
            _set(sx - offset, sy - offset)  # NW
            _set(sx + offset, sy - offset)  # NE
            _set(sx - offset, sy + offset)  # SW
            _set(sx + offset, sy + offset)  # SE


def draw_firmament_border(image: Image.Image, colors: dict) -> None:
    """Paint a 17th-century celestial-atlas frame around the quote.

    Layers, in Z-order:

    * **Layer 0: navy ground.** ``page_bg`` is black; half of it flips to
      blue on ``(x + y) & 1`` (B+K navy). Idempotent: the second
      ``_paint_theme_border`` call after the text finds no ``page_bg``
      pixels left to flip (the shape ``mucha`` / ``fillmore`` / ``atomic``
      use).
    * **Layer 1: Milky Way.** Two irregular rotated blobs (top, right of
      centre; bottom, left of centre) filled with a dense scatter of
      yellow pin-stars and sparse red / blue "nebular dust", thinning
      toward the rim; everything else reverts to the navy ground.
    * **Layer 2: star field** from ``_build_firmament_stars``, confined to
      the top and bottom margins.
    * **Layer 3: constellations**: Cassiopeia (TL), Orion's Belt (BR),
      Lyra with Vega (TR) and Crux (BL), joined by 1 px white lines and
      labelled in small Cardo italic.
    * **Layer 4: corner ornaments**: a yellow sun with a carved face (TL),
      a sky-blue (B+W) crescent moon with craters (TR, centre y=50, below
      the y=14-29 debug band, so no ``_DEBUG_LABEL_RIGHT_INSET`` entry), a
      white portolan compass rose with a yellow pivot and "N" (BL), and
      a tangerine Saturn with an equatorial band and two cyan (G+B)
      rings (BR).
    * **Layer 4b: Roman-numeral hour markers** XII / III / VI / IX at the
      page's cardinal edges, an astrolabe rim.
    * **Layer 5: ecliptic arc**: a shallow sky-blue arc across the top
      margin.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    page_bg = colors.get("page_bg")
    pixels = image.load()

    blue_ink = SPECTRA6["blue"]
    white_ink = SPECTRA6["white"]
    yellow_ink = SPECTRA6["yellow"]
    red_ink = SPECTRA6["red"]
    green_ink = SPECTRA6["green"]
    black_ink = SPECTRA6["black"]
    # Off-palette sentinels, one per ornament, so each post-pass filters
    # on its own sentinel. Don't use SPECTRA6["blue"]: Layer 0 makes half
    # the ground blue, and the post-pass would stipple all of it inside
    # the ornament's bbox.
    milky_sentinel = (2, 2, 2)
    moon_sentinel = (3, 3, 3)
    arc_sentinel = (4, 4, 4)

    # ---- Layer 0: Navy ground wash (B+K 1:1 via (x+y)&1 parity) ----
    if page_bg is not None:
        for y in range(height):
            for x in range(width):
                if pixels[x, y] == page_bg and (x + y) & 1:
                    pixels[x, y] = blue_ink

    # ---- Layer 1: Milky Way (dense star scatter inside two flowing blobs) ----
    # The Milky Way is a dense star field, so it is drawn as one: two
    # irregular blob silhouettes (not rectangles) painted in a sentinel,
    # then each sentinel pixel is resolved by a per-position hash
    # (reproducible without threading RNG state). Density falls off with
    # distance from the blob centre, so the cloud feathers into the navy:
    #   * yellow pin-star (bucket < 3, survives to the rim)
    #   * red / blue specks: warm / cool nebular dust
    #   * everything else reverts to the Layer 0 navy ground

    blob_rng = random.Random(_FIRMAMENT_STAR_SEED ^ 0x42)

    def _build_blob(cx: float, cy: float, base_r: float, aspect: float = 1.0,
                    angle: float = 0.0) -> tuple[list[tuple[float, float]], float, float, float, float]:
        n = 32
        points = []
        ca, sa = math.cos(angle), math.sin(angle)
        for i in range(n):
            t = 2.0 * math.pi * i / n
            # Per-vertex radial wobble (two random factors, ~0.55-1.20 ×
            # base_r) so the silhouette reads organic, not geometric.
            r = base_r * (0.65 + 0.40 * blob_rng.random()) * (
                0.85 + 0.30 * blob_rng.random()
            )
            # Build along the blob's own (long, short) axes, then rotate by
            # ``angle`` so the band lies on a diagonal like the Milky Way's
            # arm in classical atlases.
            lx = r * math.cos(t) * aspect
            ly = r * math.sin(t)
            points.append((cx + lx * ca - ly * sa, cy + lx * sa + ly * ca))
        # Also return the centre and axes, so the scatter can compute a
        # radial density falloff in the blob's own space.
        return points, cx, cy, base_r * aspect, base_r

    # Top blob: a shallow diagonal band tilted down-right, between
    # Cassiopeia (TL) and Lyra (TR), below the ecliptic arc.
    top_blob = _build_blob(width / 2 + 30, 52, 34, aspect=2.2, angle=0.18)
    # Bottom blob, tilted the opposite way.
    bottom_blob = _build_blob(width / 2 - 60, height - 30, 30, aspect=2.4, angle=-0.20)

    for poly, bcx, bcy, blob_rx, blob_ry in (top_blob, bottom_blob):
        draw.polygon(poly, fill=milky_sentinel)
        xs = [p[0] for p in poly]
        ys = [p[1] for p in poly]
        x0, x1 = max(0, int(min(xs))), min(width, int(max(xs)) + 1)
        y0, y1 = max(0, int(min(ys))), min(height, int(max(ys)) + 1)
        inv_rx = 1.0 / max(1.0, blob_rx)
        inv_ry = 1.0 / max(1.0, blob_ry)
        for y in range(y0, y1):
            for x in range(x0, x1):
                if pixels[x, y] != milky_sentinel:
                    continue
                # ``edge`` is the normalised radial distance (0 at the
                # centre, ~1 at the silhouette); fewer hash buckets keep
                # paint as it grows.
                ndx = (x - bcx) * inv_rx
                ndy = (y - bcy) * inv_ry
                edge = ndx * ndx + ndy * ndy
                star_hash = (x * 73856093) ^ (y * 19349663)
                bucket = star_hash % 120
                # Core (edge<0.35) keeps ~9%, mid ~5%, rim (edge>0.85) only
                # the 1/40 pin-stars.
                if edge < 0.35:
                    keep = bucket < 11
                elif edge < 0.85:
                    keep = bucket < 6
                else:
                    keep = bucket < 3
                if not keep:
                    pixels[x, y] = blue_ink if (x + y) & 1 else black_ink
                elif bucket < 3:
                    pixels[x, y] = yellow_ink   # pin-star (survives to the rim)
                elif bucket < 7:
                    pixels[x, y] = red_ink      # warm nebular dust
                else:
                    pixels[x, y] = blue_ink     # cool nebular dust

    # ---- Layer 2: Star field ----
    for sx, sy, mag in _build_firmament_stars(width, height):
        _paint_firmament_star(pixels, width, height, sx, sy, mag)

    # ---- Layer 3: Constellation polylines + Latin labels ----
    # Cardo Italic for the constellation names, as on 17th-century atlas
    # labels; the bitmap default is the fallback if the font is missing.
    try:
        label_font = ImageFont.truetype(CARDO_ITALIC, 11)
    except OSError:
        label_font = ImageFont.load_default()

    # Cassiopeia — W shape, top-left margin. Five canonical stars.
    cassiopeia = [(60, 34), (95, 50), (130, 28), (165, 50), (200, 36)]
    for cx, cy in cassiopeia:
        _paint_firmament_star(pixels, width, height, cx, cy, magnitude=1)
    draw.line(cassiopeia, fill=white_ink, width=1)
    # Latin label below the W, white italic.
    draw.text((90, 60), "CASSIOPEIA", font=label_font, fill=white_ink)

    # Orion's Belt — three stars in a tilted line, bottom-right margin.
    orion_belt = [
        (width - 220, height - 30),
        (width - 160, height - 36),
        (width - 100, height - 42),
    ]
    for cx, cy in orion_belt:
        _paint_firmament_star(pixels, width, height, cx, cy, magnitude=1)
    draw.line(orion_belt, fill=white_ink, width=1)
    draw.text((width - 196, height - 18), "ORION", font=label_font, fill=white_ink)

    # Lyra: a small parallelogram in the top-right margin, between the
    # Milky Way and the moon. The first vertex is Vega.
    lyra = [
        (width - 280, 28),
        (width - 240, 18),
        (width - 220, 42),
        (width - 268, 52),
    ]
    for cx, cy in lyra:
        _paint_firmament_star(pixels, width, height, cx, cy, magnitude=2)
    # Vega — promote the first vertex to a brighter sparkle.
    _paint_firmament_star(pixels, width, height, lyra[0][0], lyra[0][1], magnitude=1)
    # Close the parallelogram (4 segments).
    lyra_closed = lyra + [lyra[0]]
    draw.line(lyra_closed, fill=white_ink, width=1)
    draw.text((width - 280, 60), "LYRA", font=label_font, fill=white_ink)

    # Crux (Southern Cross): four stars in a cross, bottom-left margin,
    # between the compass rose and the body.
    crux = [
        (200, height - 56),   # top
        (216, height - 42),   # right
        (200, height - 28),   # bottom
        (184, height - 42),   # left
    ]
    _paint_firmament_star(pixels, width, height, crux[0][0], crux[0][1], magnitude=1)
    for cx, cy in crux[1:]:
        _paint_firmament_star(pixels, width, height, cx, cy, magnitude=2)
    # Two crossing lines.
    draw.line((crux[0], crux[2]), fill=white_ink, width=1)
    draw.line((crux[1], crux[3]), fill=white_ink, width=1)
    draw.text((132, height - 18), "CRUX AUSTRALIS", font=label_font, fill=white_ink)

    # ---- Layer 4: Four corner astronomy ornaments ----

    # TL Sun: a filled yellow disc with 16 rays every 22.5° alternating long
    # and short, and an implied face (two eyes and a smile) carved in the
    # navy ground's own (x+y)&1 pattern, so it reads as relief. Solid
    # yellow, no post-pass.
    sun_cx, sun_cy = 36, 36
    sun_r = 11
    draw.ellipse(
        (sun_cx - sun_r, sun_cy - sun_r, sun_cx + sun_r, sun_cy + sun_r),
        fill=yellow_ink,
    )
    # Rays alternate long / short. An even count keeps the alternation
    # unbroken all the way round (issue #342).
    for i in range(16):
        angle = math.radians(i * 22.5)
        is_long = i % 2 == 0
        ray_inner = sun_r + (1 if is_long else 3)
        ray_outer = sun_r + (12 if is_long else 6)
        x1 = sun_cx + ray_inner * math.cos(angle)
        y1 = sun_cy + ray_inner * math.sin(angle)
        x2 = sun_cx + ray_outer * math.cos(angle)
        y2 = sun_cy + ray_outer * math.sin(angle)
        draw.line((x1, y1, x2, y2), fill=yellow_ink, width=1)
    # Face: two eye dots at cy-2 and a 5 px smile at cy+3, in the navy
    # ground stipple.
    for ex in (sun_cx - 3, sun_cx + 3):
        pixels[ex, sun_cy - 2] = blue_ink if (ex + sun_cy - 2) & 1 else black_ink
    # Smile.
    for dx in (-2, -1, 0, 1, 2):
        sy = sun_cy + 3 + (1 if abs(dx) >= 2 else 0)
        pixels[sun_cx + dx, sy] = blue_ink if (sun_cx + dx + sy) & 1 else black_ink

    # TR crescent moon: a sentinel disc carved by a page_bg disc offset
    # left, post-passed to sky-blue (B+W 1:1), with two crater dots.
    moon_cx, moon_cy = width - 36, 50
    moon_r = 13
    draw.ellipse(
        (moon_cx - moon_r, moon_cy - moon_r, moon_cx + moon_r, moon_cy + moon_r),
        fill=moon_sentinel,
    )
    # Carve the shadow.
    carve_r = 11
    carve_cx = moon_cx - 5
    draw.ellipse(
        (carve_cx - carve_r, moon_cy - carve_r, carve_cx + carve_r, moon_cy + carve_r),
        fill=page_bg if page_bg is not None else black_ink,
    )
    # Sky-blue post-pass, scoped to the moon bbox.
    mx0, mx1 = moon_cx - moon_r - 1, moon_cx + moon_r + 1
    my0, my1 = moon_cy - moon_r - 1, moon_cy + moon_r + 1
    for y in range(max(0, my0), min(height, my1 + 1)):
        for x in range(max(0, mx0), min(width, mx1 + 1)):
            if pixels[x, y] == moon_sentinel:
                pixels[x, y] = white_ink if (x + y) & 1 else blue_ink
    # Two craters: navy dots in the lit part.
    for cx_off, cy_off in ((4, -2), (6, 3)):
        ax, ay = moon_cx + cx_off, moon_cy + cy_off
        if 0 <= ax < width and 0 <= ay < height:
            pixels[ax, ay] = blue_ink if (ax + ay) & 1 else black_ink

    # BL compass rose (portolan wind rose): four large white cardinal
    # wedges, four small diagonal ones, a yellow pivot diamond and an "N"
    # above the north point.
    rose_cx, rose_cy = 40, height - 44
    long_r = 18
    short_r = 8
    side = 4  # half-width of the cardinal wedge at the base
    # Cardinal wedges: filled triangles from a narrow base to the tip.
    cardinals = [
        ((rose_cx, rose_cy - long_r), (rose_cx - side, rose_cy), (rose_cx + side, rose_cy)),   # N
        ((rose_cx + long_r, rose_cy), (rose_cx, rose_cy - side), (rose_cx, rose_cy + side)),   # E
        ((rose_cx, rose_cy + long_r), (rose_cx - side, rose_cy), (rose_cx + side, rose_cy)),   # S
        ((rose_cx - long_r, rose_cy), (rose_cx, rose_cy - side), (rose_cx, rose_cy + side)),   # W
    ]
    for triangle in cardinals:
        draw.polygon(triangle, fill=white_ink)
    # Diagonal points — thinner short wedges.
    diag_side = 2
    for angle_deg in (45, 135, 225, 315):
        angle = math.radians(angle_deg)
        cos_a, sin_a = math.cos(angle), math.sin(angle)
        # Perpendicular for the base width.
        perp_x, perp_y = -sin_a, cos_a
        tip = (rose_cx + short_r * cos_a, rose_cy + short_r * sin_a)
        base_a = (rose_cx + diag_side * perp_x, rose_cy + diag_side * perp_y)
        base_b = (rose_cx - diag_side * perp_x, rose_cy - diag_side * perp_y)
        draw.polygon((tip, base_a, base_b), fill=white_ink)
    # Inner filled yellow diamond (the "pivot").
    draw.polygon(
        ((rose_cx, rose_cy - 3), (rose_cx + 3, rose_cy),
         (rose_cx, rose_cy + 3), (rose_cx - 3, rose_cy)),
        fill=yellow_ink,
    )
    # "N" label above the north point.
    try:
        n_font = ImageFont.truetype(CARDO_BOLD, 11)
    except OSError:
        n_font = ImageFont.load_default()
    draw.text((rose_cx - 4, rose_cy - long_r - 13), "N", font=n_font, fill=yellow_ink)

    # BR Saturn: a red-sentinel disc (→ tangerine, R+Y 5/8:3/8) with a
    # black equatorial band, and two ring ellipses (outer + inner with a
    # 1 px Cassini division) as 96-point polylines tilted 18°, in a green
    # sentinel (→ cyan, G+B 1:1). The post-pass filters on each sentinel,
    # so disc and rings don't collide.
    saturn_cx, saturn_cy = width - 56, height - 48
    saturn_r = 11
    draw.ellipse(
        (saturn_cx - saturn_r, saturn_cy - saturn_r,
         saturn_cx + saturn_r, saturn_cy + saturn_r),
        fill=red_ink,
    )
    # Outer + inner ring, 1 px Cassini division between them.
    angle = math.radians(18)
    cos_a, sin_a = math.cos(angle), math.sin(angle)
    n_points = 96
    for ring_a, ring_b in ((22, 8), (19, 6)):
        ring_points = []
        for i in range(n_points + 1):
            t = 2.0 * math.pi * i / n_points
            xu = ring_a * math.cos(t)
            yu = ring_b * math.sin(t)
            ring_points.append((
                saturn_cx + xu * cos_a - yu * sin_a,
                saturn_cy + xu * sin_a + yu * cos_a,
            ))
        draw.line(ring_points, fill=green_ink, width=1)
    # Equatorial band: a black line drawn after the disc, matching
    # neither sentinel, so it survives the post-pass.
    band_y = saturn_cy + 1
    draw.line(
        (saturn_cx - saturn_r + 2, band_y, saturn_cx + saturn_r - 2, band_y),
        fill=black_ink, width=1,
    )
    # Saturn post-pass: two sentinel filters (red → tangerine, green →
    # cyan) in one corner bbox.
    sat_pad = 24
    sat_x0 = max(0, saturn_cx - sat_pad)
    sat_x1 = min(width, saturn_cx + sat_pad + 1)
    sat_y0 = max(0, saturn_cy - sat_pad)
    sat_y1 = min(height, saturn_cy + sat_pad + 1)
    for y in range(sat_y0, sat_y1):
        for x in range(sat_x0, sat_x1):
            px_val = pixels[x, y]
            if px_val == red_ink and BAYER_4x4[y & 3][x & 3] < 6:
                pixels[x, y] = yellow_ink
            elif px_val == green_ink and (x + y) & 1:
                pixels[x, y] = blue_ink

    # ---- Layer 4b: Roman-numeral hour markers ----
    # XII / III / VI / IX at the four cardinal page positions: an
    # astrolabe rim. Small Cardo italic at the canvas edges, clear of the
    # ornaments and the body.
    try:
        roman_font = ImageFont.truetype(CARDO_ITALIC, 12)
    except OSError:
        roman_font = ImageFont.load_default()
    # XII: top, left of the top Milky Way blob (centred at width/2 + 30).
    draw.text((width // 2 - 60, 4), "XII", font=roman_font, fill=white_ink)
    # VI: bottom, right of the bottom blob (centred at width/2 - 60).
    draw.text((width // 2 + 60, height - 16), "VI", font=roman_font, fill=white_ink)
    # III: right edge, at the vertical centre.
    draw.text((width - 16, height // 2 - 6), "III", font=roman_font, fill=white_ink)
    # IX — left edge, mirroring III.
    draw.text((4, height // 2 - 6), "IX", font=roman_font, fill=white_ink)

    # ---- Layer 5: Ecliptic arc ----
    # The upper half (180°–360°) of a wide ellipse in bbox
    # (40, 20)-(width-40, 140): peak at y=20, ends at y=80. Painted in an
    # off-palette sentinel so the post-pass can't touch Layer 0's blue.
    # The post-pass bbox comes from the arc's own geometry (down to the
    # ellipse's centre row, where the ends sit), so no sentinel pixel at
    # the ends survives to be snapped to black (issue #341).
    arc_bbox = (40, 20, width - 40, 140)
    draw.arc(arc_bbox, start=180, end=360, fill=arc_sentinel, width=1)
    ax0, ay0 = arc_bbox[0], arc_bbox[1]
    ax1, ay1 = arc_bbox[2], (arc_bbox[1] + arc_bbox[3]) // 2
    for y in range(max(0, ay0), min(height, ay1 + 1)):
        for x in range(max(0, ax0), min(width, ax1 + 1)):
            if pixels[x, y] == arc_sentinel:
                pixels[x, y] = white_ink if (x + y) & 1 else blue_ink


# Seeds for ``draw_cartograph_border``'s deterministic placement. A fixed
# chart keeps renders byte-identical and keeps the map silhouette stable
# from minute to minute. The values are arbitrary, chosen so the foxing,
# coastline wobble and place-name jitter don't visibly correlate.
_CARTOGRAPH_FOXING_SEED = 0xCA70
_CARTOGRAPH_COAST_TL_SEED = 0xC0A571
_CARTOGRAPH_COAST_BR_SEED = 0xC0A5B7


# Three Latin chart labels in the open-sea regions, not inside the
# coastlines (a sepia-stippled label inside a sepia coast would vanish).
# ``cx_frac`` / ``cy_frac`` are canvas-relative. Italic IM Fell English.
#
# Positions clear, at 800×480:
#   * the body clear_rect (typically (104..696, 116..360) with cartograph's
#     22/12/12 pad),
#   * the y=14-29 debug-mode banner band (top right),
#   * the TL coastline bbox (0,0)..(176, 96),
#   * the BR coastline bbox (624, 384)..(799, 479),
#   * the compass rose bbox (40..104, 372..436),
#   * the sea-serpent bbox ~(706..774, 252..276).
_CARTOGRAPH_PLACE_NAMES = (
    # Top sea, centred, label centre y≈48: below the debug band and above
    # the cartouche top in every layout (dense: 72 - 12 = 60).
    ("Mare Incognitum", 0.50, 0.10),
    # Top-right sea, same row, cx≈672: clear of Mare Incognitum and the
    # right edge.
    ("Insula Aurea", 0.84, 0.10),
    # Bottom sea, between the compass rose and the BR coast, centre
    # y≈413: below the dense cartouche (~y=400) and above the debug strip
    # (y≈454-466). Deliberately tight; any lower and it touches the strip.
    ("Terra Nova", 0.48, 0.86),
)


# Three small islands in the open sea, so the chart reads as populated.
# Each is ``(cx_frac, cy_frac, scale_w, scale_h, seed)``: a small seeded
# 8-point blob at (cx_frac × width, cy_frac × height), placed between the
# cartouche, coastlines, compass, serpent and labels.
_CARTOGRAPH_ISLANDS = (
    # Top sea, between the TL coastline and the "Mare Incognitum" label.
    (0.32, 0.16, 16, 10, 0xC0A511),
    # Bottom sea, between the compass rose and "Terra Nova", balancing the
    # BR landmass.
    (0.30, 0.85, 20, 12, 0xC0A522),
    # Bottom sea, between "Terra Nova" and the serpent.
    (0.62, 0.85, 14, 9, 0xC0A533),
)


# Graticule: meridians and parallels every 80 px (9 × 5 lines at
# 800×480), dotted every 3rd pixel so it reads as a faint reference grid.
_CARTOGRAPH_GRATICULE_SPACING = 80
_CARTOGRAPH_GRATICULE_DOT_PERIOD = 3


def _paint_cartograph_dotted_sepia_line(
    pixels,
    width: int,
    height: int,
    x0: int,
    y0: int,
    x1: int,
    y1: int,
    dot_period: int,
    ground_ink_a,
    ground_ink_b,
    red_ink,
    green_ink,
) -> None:
    """Paint a dotted sepia line from ``(x0, y0)`` to ``(x1, y1)``.

    Dots alternate R/G in place by ``(px + py) & 1`` parity (sepia at
    viewing distance, no post-pass). Only pixels still equal to
    ``ground_ink_a`` (white) or ``ground_ink_b`` (cream yellow) are
    painted, so the line sits on the parchment and never overpaints
    earlier texture.

    ``dot_period``: 1 = solid, 2 = every other pixel, 3 = every third.
    The graticule uses 3 and the rhumb lines 2, so rhumbs dominate.
    """
    length = max(1, int(round(math.hypot(x1 - x0, y1 - y0))))
    for i in range(0, length + 1, dot_period):
        t = i / length
        px = round(x0 + (x1 - x0) * t)
        py = round(y0 + (y1 - y0) * t)
        if not (0 <= px < width and 0 <= py < height):
            continue
        current = pixels[px, py]
        if current not in (ground_ink_a, ground_ink_b):
            continue
        # Parity inverted vs. the coastline / island / label post-passes:
        # reds land at ``(px+py)&1 == 0``. Those post-passes flip parity-1
        # reds to green; reds at parity 1 here would be clobbered inside
        # any coastline or island bbox, breaking the R+G alternation.
        pixels[px, py] = green_ink if (px + py) & 1 else red_ink


def _draw_cartograph_graticule(
    pixels,
    width: int,
    height: int,
    ground_white,
    ground_cream,
    red_ink,
    green_ink,
) -> None:
    """Paint a faint sepia latitude / longitude graticule across the chart.

    The graticule is what turns decorated coastlines and a compass rose
    into a chart. Meridians at ``x = 80, 160, ..., 720`` and parallels at
    ``y = 80, 160, ..., 400`` (``_CARTOGRAPH_GRATICULE_SPACING``), dotted
    every 3rd pixel in in-place R/G sepia, so the grid reads as faint
    structure under the text. 3 px degree ticks mark each line at the
    canvas edges.

    Only cream-washed ground pixels are painted, so everything later
    layers over it; the cartouche knockout later re-washes the body rect,
    erasing the graticule there like a scroll laid over the map.
    """
    spacing = _CARTOGRAPH_GRATICULE_SPACING
    dot_period = _CARTOGRAPH_GRATICULE_DOT_PERIOD
    # Vertical meridians
    for x in range(spacing, width, spacing):
        _paint_cartograph_dotted_sepia_line(
            pixels, width, height, x, 0, x, height - 1,
            dot_period, ground_white, ground_cream, red_ink, green_ink,
        )
    # Horizontal parallels
    for y in range(spacing, height, spacing):
        _paint_cartograph_dotted_sepia_line(
            pixels, width, height, 0, y, width - 1, y,
            dot_period, ground_white, ground_cream, red_ink, green_ink,
        )
    # Edge ticks: 3 px solid sepia stubs where each line meets the canvas
    # edge, with the same inverted parity as
    # ``_paint_cartograph_dotted_sepia_line``.
    tick_len = 3
    for x in range(spacing, width, spacing):
        for offset in range(tick_len):
            # Top edge
            if 0 <= offset < height and pixels[x, offset] in (ground_white, ground_cream):
                pixels[x, offset] = green_ink if (x + offset) & 1 else red_ink
            # Bottom edge
            py = height - 1 - offset
            if 0 <= py < height and pixels[x, py] in (ground_white, ground_cream):
                pixels[x, py] = green_ink if (x + py) & 1 else red_ink
    for y in range(spacing, height, spacing):
        for offset in range(tick_len):
            # Left edge
            if 0 <= offset < width and pixels[offset, y] in (ground_white, ground_cream):
                pixels[offset, y] = green_ink if (offset + y) & 1 else red_ink
            # Right edge
            px = width - 1 - offset
            if 0 <= px < width and pixels[px, y] in (ground_white, ground_cream):
                pixels[px, y] = green_ink if (px + y) & 1 else red_ink


def _draw_cartograph_rhumb_lines(
    pixels,
    width: int,
    height: int,
    cx: int,
    cy: int,
    ground_white,
    ground_cream,
    red_ink,
    green_ink,
) -> None:
    """Paint eight rhumb lines radiating from the compass rose centre.

    One ray per principal bearing (N / NE / E / … / NW) out to the canvas
    edge minus a 12 px gap, the portolan-chart signature. Denser dotted
    sepia (period 2) than the graticule (period 3), so the compass is the
    focal feature. Only cream-washed ground pixels are painted, so later
    layers sit on top.
    """
    edge_pad = 12
    for angle_deg in (0, 45, 90, 135, 180, 225, 270, 315):
        angle = math.radians(angle_deg)
        dx = math.sin(angle)
        dy = -math.cos(angle)  # 0° = up
        # Find the closer edge in each axis (or skip if dx/dy is 0).
        t_x = float("inf")
        t_y = float("inf")
        if dx > 0:
            t_x = (width - edge_pad - cx) / dx
        elif dx < 0:
            t_x = (edge_pad - cx) / dx
        if dy > 0:
            t_y = (height - edge_pad - cy) / dy
        elif dy < 0:
            t_y = (edge_pad - cy) / dy
        t = min(t_x, t_y)
        if t == float("inf") or t <= 0:
            continue
        ex = round(cx + dx * t)
        ey = round(cy + dy * t)
        _paint_cartograph_dotted_sepia_line(
            pixels, width, height, cx, cy, ex, ey,
            dot_period=2, ground_ink_a=ground_white, ground_ink_b=ground_cream,
            red_ink=red_ink, green_ink=green_ink,
        )


def _draw_cartograph_island(
    draw: ImageDraw.ImageDraw,
    cx: int,
    cy: int,
    scale_w: int,
    scale_h: int,
    ink_sentinel,
    seed: int,
) -> tuple[int, int, int, int]:
    """Paint a small wobbled-polygon island centred on ``(cx, cy)``.

    An 8-vertex polygon with seeded radial wobble, half-axes ``scale_w`` /
    ``scale_h``. Painted in ``ink_sentinel`` (red) for the caller's R+G
    sepia post-pass, like the coastlines.

    Returns the bbox for the post-pass.
    """
    rng = random.Random(seed)
    n_pts = 8
    pts: list[tuple[int, int]] = []
    for i in range(n_pts):
        angle = (i / n_pts) * 2 * math.pi
        # Wobble 0.7..1.3, gentler than the coastline, so islands read as
        # compact landmasses rather than straggly archipelagos.
        wobble = 0.7 + rng.random() * 0.6
        x = cx + round(scale_w * wobble * math.cos(angle))
        y = cy + round(scale_h * wobble * math.sin(angle))
        pts.append((x, y))
    draw.polygon(pts, fill=ink_sentinel)
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    return (min(xs) - 1, min(ys) - 1, max(xs) + 1, max(ys) + 1)


def _draw_cartograph_compass_rose(
    draw: ImageDraw.ImageDraw,
    cx: int,
    cy: int,
    ink_sentinel,
) -> tuple[int, int, int, int]:
    """Paint an 8-point compass rose centred on ``(cx, cy)``.

    Four long cardinal triangles (32 px) and four shorter ordinals (18 px)
    fan from a small pivot circle, all in ``ink_sentinel`` for the caller's
    post-pass (in cartograph, R+Y 5/8:3/8 tangerine, a warm vermilion on
    the cream ground).

    Returns ``(x0, y0, x1, y1)``, padded 2 px so no sentinel pixel falls
    outside the caller's iteration window.
    """
    cardinal_len = 32
    ordinal_len = 18
    # Cardinals first, then ordinals. ``base_half`` is the half-width of
    # each triangle's base: 5 px cardinals dominate, 3 px ordinals keep
    # the 8-point rose silhouette rather than an even star.
    spikes = (
        (0, cardinal_len, 5),    # N
        (90, cardinal_len, 5),   # E
        (180, cardinal_len, 5),  # S
        (270, cardinal_len, 5),  # W
        (45, ordinal_len, 3),    # NE
        (135, ordinal_len, 3),   # SE
        (225, ordinal_len, 3),   # SW
        (315, ordinal_len, 3),   # NW
    )
    for angle_deg, length, base_half in spikes:
        angle = math.radians(angle_deg)
        # Tip: 0° is north, clockwise in screen space.
        tx = cx + round(length * math.sin(angle))
        ty = cy - round(length * math.cos(angle))
        # Base corners perpendicular to the spike axis.
        perp = math.radians(angle_deg + 90)
        bx0 = cx + round(base_half * math.sin(perp))
        by0 = cy - round(base_half * math.cos(perp))
        bx1 = cx - round(base_half * math.sin(perp))
        by1 = cy + round(base_half * math.cos(perp))
        draw.polygon([(tx, ty), (bx0, by0), (bx1, by1)], fill=ink_sentinel)
    # Centre pivot, same ink.
    draw.ellipse((cx - 3, cy - 3, cx + 3, cy + 3), fill=ink_sentinel)
    pad = 2
    return (cx - cardinal_len - pad, cy - cardinal_len - pad,
            cx + cardinal_len + pad, cy + cardinal_len + pad)


def _draw_cartograph_sea_serpent(
    draw: ImageDraw.ImageDraw,
    cx: int,
    cy: int,
    ink,
) -> None:
    """Paint a small "here be dragons" sea serpent (~50 × 12 px).

    Solid ``ink``, no post-pass: engraved margin doodles had no halftone.
    A small triangular head at the left and three humps tapering to a
    tail; fewer humps read as a wave, more as a centipede.
    """
    # Wavy polyline through three humps.
    pts = [
        (cx - 24, cy + 4),
        (cx - 19, cy - 2),
        (cx - 14, cy + 4),
        (cx - 8, cy - 4),
        (cx - 2, cy + 4),
        (cx + 4, cy - 5),
        (cx + 10, cy + 4),
        (cx + 18, cy + 2),
    ]
    for i in range(len(pts) - 1):
        draw.line((pts[i], pts[i + 1]), fill=ink, width=2)
    # Head: a small filled triangle at the left end, an open snout.
    head_pts = [
        (cx - 24, cy + 4),
        (cx - 30, cy + 2),
        (cx - 28, cy + 7),
    ]
    draw.polygon(head_pts, fill=ink)


def _point_in_polygon(x: float, y: float, poly: list[tuple[int, int]]) -> bool:
    """Even-odd ray-cast point-in-polygon test (treats ``poly`` as closed)."""
    inside = False
    n = len(poly)
    j = n - 1
    for i in range(n):
        xi, yi = poly[i]
        xj, yj = poly[j]
        if (yi > y) != (yj > y):
            x_cross = xi + (y - yi) * (xj - xi) / (yj - yi) if yj != yi else xi
            if x < x_cross:
                inside = not inside
        j = i
    return inside


def _draw_cartograph_contours(
    draw: ImageDraw.ImageDraw,
    land_poly: list[tuple[int, int]],
    bbox: tuple[int, int, int, int],
    ink,
    seed: int,
) -> None:
    """Trace topographic contours over a synthetic height field, clipped
    to ``land_poly``, the way a chart hatches terrain relief.

    A few seeded Gaussian hills and basins are summed over the land's bbox
    and marching squares traces each of several elevation thresholds,
    giving nested multi-peak contours rather than shrunken copies of the
    coastline. Cells whose centre is off the land polygon are skipped.
    """
    x0, y0, x1, y1 = bbox
    x0 = max(0, int(x0))
    y0 = max(0, int(y0))
    x1 = int(x1)
    y1 = int(y1)
    w = x1 - x0
    h = y1 - y0
    if w < 8 or h < 8:
        return

    rng = random.Random(seed)
    # 3–4 Gaussian features (hills positive, basins negative). Spread
    # scales with the land size so contour spacing looks consistent.
    span = max(w, h)
    n_features = rng.randint(3, 4)
    features = []
    for _ in range(n_features):
        fx = x0 + rng.uniform(0.15, 0.85) * w
        fy = y0 + rng.uniform(0.15, 0.85) * h
        amp = rng.uniform(0.6, 1.0) * (1 if rng.random() < 0.65 else -1)
        sigma = rng.uniform(0.18, 0.34) * span
        features.append((fx, fy, amp, 2.0 * sigma * sigma))

    def height(px: float, py: float) -> float:
        total = 0.0
        for fx, fy, amp, two_sig_sq in features:
            dx = px - fx
            dy = py - fy
            total += amp * math.exp(-(dx * dx + dy * dy) / two_sig_sq)
        return total

    # Sample on a ~5 px grid: smooth enough, cheap enough in pure Python.
    step = 5
    gx = list(range(x0, x1 + step, step))
    gy = list(range(y0, y1 + step, step))
    grid = [[height(px, py) for px in gx] for py in gy]
    lo = min(min(row) for row in grid)
    hi = max(max(row) for row in grid)
    if hi - lo < 1e-6:
        return
    # Six iso-levels across the range, skipping the extremes (they'd trace
    # specks at the very peaks / pits).
    levels = [lo + (hi - lo) * f for f in (0.18, 0.32, 0.46, 0.60, 0.74, 0.88)]

    def interp(pa, va, pb, vb, lvl):
        # Linear crossing point between grid nodes pa (val va) and pb (vb).
        if abs(vb - va) < 1e-9:
            return pa
        t = (lvl - va) / (vb - va)
        return (pa[0] + (pb[0] - pa[0]) * t, pa[1] + (pb[1] - pa[1]) * t)

    for lvl in levels:
        for iy in range(len(gy) - 1):
            for ix in range(len(gx) - 1):
                # Cell corners (TL, TR, BR, BL) with field values.
                tlp = (gx[ix], gy[iy])
                tlv = grid[iy][ix]
                trp = (gx[ix + 1], gy[iy])
                trv = grid[iy][ix + 1]
                brp = (gx[ix + 1], gy[iy + 1])
                brv = grid[iy + 1][ix + 1]
                blp = (gx[ix], gy[iy + 1])
                blv = grid[iy + 1][ix]
                # Skip cells whose centre isn't on land.
                ccx = (gx[ix] + gx[ix + 1]) / 2.0
                ccy = (gy[iy] + gy[iy + 1]) / 2.0
                if not _point_in_polygon(ccx, ccy, land_poly):
                    continue
                code = (
                    (1 if tlv > lvl else 0)
                    | (2 if trv > lvl else 0)
                    | (4 if brv > lvl else 0)
                    | (8 if blv > lvl else 0)
                )
                if code == 0 or code == 15:
                    continue
                # Crossing points on each edge (top, right, bottom, left).
                top = interp(tlp, tlv, trp, trv, lvl)
                right = interp(trp, trv, brp, brv, lvl)
                bottom = interp(blp, blv, brp, brv, lvl)
                left = interp(tlp, tlv, blp, blv, lvl)
                # Marching-squares segment table (ambiguous saddles 5/10
                # split into two segments).
                segs = {
                    1: [(left, top)], 2: [(top, right)], 3: [(left, right)],
                    4: [(right, bottom)], 5: [(left, top), (right, bottom)],
                    6: [(top, bottom)], 7: [(left, bottom)], 8: [(left, bottom)],
                    9: [(top, bottom)], 10: [(left, bottom), (top, right)],
                    11: [(right, bottom)], 12: [(left, right)], 13: [(top, right)],
                    14: [(left, top)],
                }.get(code, [])
                for a, b in segs:
                    draw.line(
                        (round(a[0]), round(a[1]), round(b[0]), round(b[1])),
                        fill=ink, width=1,
                    )


def _draw_cartograph_coastline(
    draw: ImageDraw.ImageDraw,
    corner: tuple[int, int],
    extent: tuple[int, int],
    ink_sentinel,
    seed: int,
) -> tuple[int, int, int, int]:
    """Paint an irregular coastline as a filled polygon anchored at
    ``corner`` and extending toward ``extent``.

    ``corner`` is the canvas corner the land sits in (e.g. ``(0, 0)``);
    ``extent`` is the far point it sweeps toward (e.g. ``(180, 100)``).
    The shoreline is a 26-point seeded polyline closed back along the
    corner edges, with interior contour lines from
    ``_draw_cartograph_contours``.

    Painted in ``ink_sentinel`` for the caller's R+G sepia post-pass (the
    aged-ink recipe of ``newsprint`` / ``saloon`` / ``placard``).

    Returns ``(x0, y0, x1, y1)``, the bbox for the post-pass.
    """
    rng = random.Random(seed)
    corner_x, corner_y = corner
    extent_x, extent_y = extent
    # Direction signs, so the wobble pushes toward the corner's outside
    # (away from the body).
    sign_x = 1 if extent_x >= corner_x else -1
    sign_y = 1 if extent_y >= corner_y else -1
    n_pts = 26
    pts: list[tuple[int, int]] = []
    # Two-octave wobble: a slow swell carves broad bays and headlands, a
    # fast jitter adds the nibble of an engraved shoreline. A single
    # octave reads as a straight hypotenuse (a triangle, not land).
    slow_phase = rng.random() * math.tau
    slow_freq = 2.0 + rng.random() * 1.5
    for i in range(1, n_pts + 1):
        t = i / n_pts
        # Base position along the diagonal; the power curve flattens the
        # middle so the coast isn't a straight diagonal.
        bx = corner_x + round((extent_x - corner_x) * t)
        by = corner_y + round((extent_y - corner_y) * (1.0 - (1.0 - t) ** 1.8))
        # Swell + jitter, both toward the corner's outside, so the ragged
        # edge faces the open sea.
        swell = math.sin(slow_phase + t * slow_freq * math.tau)
        wobble_x = round((swell * 22 + (rng.random() - 0.5) * 26)) * sign_x
        wobble_y = round((swell * 18 + (rng.random() - 0.5) * 20)) * sign_y
        pts.append((bx + wobble_x, by + wobble_y))
    # Close back along the corner edges (y-axis edge first) so the polygon
    # hugs the corner.
    pts.insert(0, (corner_x, extent_y))
    pts.append((extent_x, corner_y))
    pts.append((corner_x, corner_y))
    draw.polygon(pts, fill=ink_sentinel)

    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    bbox = (min(xs) - 1, min(ys) - 1, max(xs) + 1, max(ys) + 1)

    # Interior contour lines (marching squares over a synthetic height
    # field). Offset copies of the coastline bunch into a band and leave the
    # interior flat. Drawn in black, not the red sentinel, so the sepia
    # post-pass leaves them as crisp relief lines.
    _draw_cartograph_contours(draw, pts, bbox, SPECTRA6["black"], seed ^ 0x5EA1)

    return bbox


def draw_cartograph_border(
    image: Image.Image,
    colors: dict,
    clear_rect: tuple[int, int, int, int] | None = None,
) -> None:
    """Paint a hand-drawn antique cartographer's chart frame.

    Eleven layers, painted in Z-order:

    * **Layer 0 — cream Y+W Bayer wash.** Sparse 1-in-16 yellow
      stipple over every ``page_bg`` pixel, warming the flat white to
      vellum.
    * **Layer 1 — sepia graticule.** Dotted R/G meridians and parallels
      every 80 px (period-3 density) plus 3-px degree ticks at the
      frame; the strongest "this is a chart" cue.
    * **Layer 2 — sepia rhumb lines.** Eight rays at 45° from the
      compass-rose centre, at period-2 density so they read as a focal
      feature over the graticule.
    * **Layer 3 — sepia foxing.** ~120 seeded single-pixel dots, R or G
      by parity, which the eye averages to rust-brown.
    * **Layer 4 — two corner coastlines** (TL, BR) in R+G sepia via the
      sentinel-then-bbox-post-pass pattern. Seeded so the same chart
      recurs at every render.
    * **Layer 5 — three islands** (:data:`_CARTOGRAPH_ISLANDS`), same
      recipe.
    * **Layer 6 — compass rose** (bottom-left) in R+Y 5/8:3/8 tangerine,
      painted after the rhumb lines so it sits on top of them.
    * **Layer 7 — sea-serpent doodle** in solid black, as period margin
      doodles were inked.
    * **Layer 8 — three Latin place names** in IM Fell italic, R+G
      sepia (:data:`_CARTOGRAPH_PLACE_NAMES`); falls back through
      ``META_FONT_CANDIDATES``.
    * **Layer 9 — cartouche knockout.** With ``clear_rect``: a rounded
      white card, a fresh cream wash, a thin red outer rule and a thin
      black inner rule, erasing the map under the body text.
    * **Layer 10 — registration crosses** at the four inner-rule
      corners.

    When ``clear_rect`` is None (direct calls, ``render_static_message``,
    ``render_source_card``) Layers 9 and 10 are skipped; the map layers
    still paint.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    page_bg = colors.get("page_bg")
    cream_light = SPECTRA6["yellow"]
    red_ink = SPECTRA6["red"]
    green_ink = SPECTRA6["green"]
    yellow_ink = SPECTRA6["yellow"]
    black_ink = SPECTRA6["black"]
    white_ink = SPECTRA6["white"]

    pixels = image.load()

    # ------------------------------------------------------------------
    # Layer 0 — cream Y+W Bayer wash on page_bg pixels. Threshold < 1
    # = ~6.25% yellow, half the density ``illuminated`` / ``dispatch``
    # use, because the foxing layer (Layer 3) adds more warmth on top and
    # a denser ground would compete with the body text.
    if page_bg is not None:
        for y in range(height):
            row = BAYER_4x4[y & 3]
            for x in range(width):
                if pixels[x, y] == page_bg and row[x & 3] < 1:
                    pixels[x, y] = cream_light

    # ------------------------------------------------------------------
    # Layer 1 — sepia graticule, painted only over ground pixels so it
    # lies under everything painted later.
    _draw_cartograph_graticule(
        pixels, width, height,
        ground_white=white_ink, ground_cream=cream_light,
        red_ink=red_ink, green_ink=green_ink,
    )

    # ------------------------------------------------------------------
    # Layer 2 — sepia rhumb lines from the compass-rose centre, denser
    # than the graticule (every other pixel vs every third).
    rose_cx = 72
    rose_cy = height - 80
    _draw_cartograph_rhumb_lines(
        pixels, width, height, rose_cx, rose_cy,
        ground_white=white_ink, ground_cream=cream_light,
        red_ink=red_ink, green_ink=green_ink,
    )

    # ------------------------------------------------------------------
    # Layer 3 — sepia foxing scatter at seeded positions.
    if page_bg is not None:
        rng = random.Random(_CARTOGRAPH_FOXING_SEED)
        n_dots = 120
        for _ in range(n_dots):
            fx = rng.randint(2, width - 3)
            fy = rng.randint(2, height - 3)
            # Only paint over ground (cream or white), skipping graticule
            # and rhumb pixels.
            current = pixels[fx, fy]
            if current not in (cream_light, white_ink):
                continue
            # Parity picks R or G so neighbouring dots average to sepia.
            # Inverted vs. the coastline / island / label post-passes so
            # foxing reds survive them (see
            # ``_paint_cartograph_dotted_sepia_line``).
            pixels[fx, fy] = green_ink if (fx + fy) & 1 else red_ink

    # ------------------------------------------------------------------
    # Layer 4 — two diagonal-corner coastlines. Paint as red sentinel,
    # then post-pass to sepia (R+G) by flipping half the painted red
    # pixels to green per (x+y)&1 parity inside each bbox.
    tl_bbox = _draw_cartograph_coastline(
        draw,
        corner=(0, 0),
        extent=(round(width * 0.20), round(height * 0.18)),
        ink_sentinel=red_ink,
        seed=_CARTOGRAPH_COAST_TL_SEED,
    )
    br_bbox = _draw_cartograph_coastline(
        draw,
        corner=(width - 1, height - 1),
        extent=(round(width * 0.80), round(height * 0.82)),
        ink_sentinel=red_ink,
        seed=_CARTOGRAPH_COAST_BR_SEED,
    )
    # Post-pass: flip half the red pixels inside each bbox to green
    # for sepia.
    for bx0, by0, bx1, by1 in (tl_bbox, br_bbox):
        bx0 = max(0, bx0)
        by0 = max(0, by0)
        bx1 = min(width - 1, bx1)
        by1 = min(height - 1, by1)
        for py in range(by0, by1 + 1):
            for px in range(bx0, bx1 + 1):
                if pixels[px, py] == red_ink and (px + py) & 1:
                    pixels[px, py] = green_ink

    # ------------------------------------------------------------------
    # Layer 5 — three islands, red-sentinel polygons post-passed to R+G
    # sepia like the coastlines.
    island_bboxes: list[tuple[int, int, int, int]] = []
    for cx_frac, cy_frac, scale_w, scale_h, seed in _CARTOGRAPH_ISLANDS:
        island_cx = round(width * cx_frac)
        island_cy = round(height * cy_frac)
        island_bboxes.append(_draw_cartograph_island(
            draw, island_cx, island_cy, scale_w, scale_h, red_ink, seed,
        ))
    for bx0, by0, bx1, by1 in island_bboxes:
        bx0 = max(0, bx0)
        by0 = max(0, by0)
        bx1 = min(width - 1, bx1)
        by1 = min(height - 1, by1)
        for py in range(by0, by1 + 1):
            for px in range(bx0, bx1 + 1):
                if pixels[px, py] == red_ink and (px + py) & 1:
                    pixels[px, py] = green_ink

    # ------------------------------------------------------------------
    # Layer 6 — compass rose, centred on the rhumb-line origin so the
    # rays read as emanating from it, and painted on top of them.
    rose_bbox = _draw_cartograph_compass_rose(draw, rose_cx, rose_cy, ink_sentinel=red_ink)
    # Tangerine post-pass: flip red to yellow where ``BAYER_4x4 < 6`` (R+Y
    # 5/8:3/8). Bounded to the rose bbox so the other red sentinels are
    # untouched.
    bx0, by0, bx1, by1 = rose_bbox
    bx0 = max(0, bx0)
    by0 = max(0, by0)
    bx1 = min(width - 1, bx1)
    by1 = min(height - 1, by1)
    for py in range(by0, by1 + 1):
        row = BAYER_4x4[py & 3]
        for px in range(bx0, bx1 + 1):
            if pixels[px, py] == red_ink and row[px & 3] < 6:
                pixels[px, py] = yellow_ink

    # ------------------------------------------------------------------
    # Layer 7 — sea-serpent doodle in the bottom-mid sea, between the
    # "Terra Nova" label and the BR coastline. That ~50x20 px zone stays
    # clear of the cartouche on every layout; the right margin does not
    # (the dense cartouche leaves only ~37 px there).
    _draw_cartograph_sea_serpent(draw, round(width * 0.69), round(height * 0.84), ink=black_ink)

    # ------------------------------------------------------------------
    # Layer 8 — three Latin place names, red sentinel post-passed to
    # sepia like the coastlines.
    label_font_candidates = [
        IMFELLENGLISH_ITALIC,
        IMFELLENGLISH_REGULAR,
        "/usr/share/fonts/truetype/dejavu/DejaVuSerif-Italic.ttf",
        *META_FONT_CANDIDATES,
    ]
    label_font = load_font(label_font_candidates, size=15)
    for label_text, cx_frac, cy_frac in _CARTOGRAPH_PLACE_NAMES:
        lx = round(width * cx_frac)
        ly = round(height * cy_frac)
        bbox = draw.textbbox((lx, ly), label_text, font=label_font)
        # Centre the label on (lx, ly).
        draw_x = lx - (bbox[2] - bbox[0]) // 2
        draw_y = ly - (bbox[3] - bbox[1]) // 2
        draw.text((draw_x, draw_y), label_text, font=label_font, fill=red_ink)
        # Post-pass to R+G sepia; the 1 px pad catches hinting jitter
        # outside the text bbox.
        lbbox = draw.textbbox((draw_x, draw_y), label_text, font=label_font)
        lx0 = max(0, lbbox[0] - 1)
        ly0 = max(0, lbbox[1] - 1)
        lx1 = min(width - 1, lbbox[2] + 1)
        ly1 = min(height - 1, lbbox[3] + 1)
        for py in range(ly0, ly1 + 1):
            for px in range(lx0, lx1 + 1):
                if pixels[px, py] == red_ink and (px + py) & 1:
                    pixels[px, py] = green_ink

    # ------------------------------------------------------------------
    # Layers 9 & 10 — cartouche knockout + registration corners. Only
    # paint when render() threaded clear_rect through.
    if clear_rect is None or page_bg is None:
        return
    cx0, cy0, cx1, cy1 = clear_rect
    cx0 = max(0, cx0)
    cy0 = max(0, cy0)
    cx1 = min(width - 1, cx1)
    cy1 = min(height - 1, cy1)
    # Skip the knockout if the clamped rect collapsed.
    if cx1 <= cx0 or cy1 <= cy0:
        return

    # Rounded white fill; radius 10 reads as a paper card without going
    # soft against the angular coastlines.
    cartouche_radius = 10
    draw.rounded_rectangle((cx0, cy0, cx1, cy1), radius=cartouche_radius, fill=white_ink)
    # Fresh cream wash inside the knockout (same recipe as Layer 0).
    for py in range(cy0, cy1 + 1):
        row = BAYER_4x4[py & 3]
        for px in range(cx0, cx1 + 1):
            if pixels[px, py] == white_ink and row[px & 3] < 1:
                pixels[px, py] = cream_light

    # Doubled rule: thin red outer, thin black inner 3 px in.
    draw.rounded_rectangle((cx0, cy0, cx1, cy1), radius=cartouche_radius, outline=red_ink, width=1)
    inner_inset = 3
    if cx1 - cx0 > inner_inset * 2 and cy1 - cy0 > inner_inset * 2:
        draw.rounded_rectangle(
            (cx0 + inner_inset, cy0 + inner_inset, cx1 - inner_inset, cy1 - inner_inset),
            radius=max(2, cartouche_radius - inner_inset),
            outline=black_ink,
            width=1,
        )

    # Layer 10 — registration crosses (3 px arms) at the inner-rule
    # corners.
    tick_arm = 3
    tick_inset = inner_inset + 6  # past the inner rule + small breathing
    for tcx, tcy in (
        (cx0 + tick_inset, cy0 + tick_inset),
        (cx1 - tick_inset, cy0 + tick_inset),
        (cx0 + tick_inset, cy1 - tick_inset),
        (cx1 - tick_inset, cy1 - tick_inset),
    ):
        draw.line((tcx - tick_arm, tcy, tcx + tick_arm, tcy), fill=black_ink, width=1)
        draw.line((tcx, tcy - tick_arm, tcx, tcy + tick_arm), fill=black_ink, width=1)


def _grimdark_cog(draw, cx: int, cy: int, radius: int, teeth_n: int, color, *,
                  tooth_len: int = 4, tooth_w: int = 3, hub: int | None = None,
                  hub_color=None) -> None:
    """Draw an Adeptus-Mechanicus-style toothed cog/gear centred on (cx, cy).

    A filled disc with ``teeth_n`` trapezoidal teeth radiating from the rim,
    plus an optional hollow hub. Pure ``ImageDraw`` (polygons + ellipses) so
    it clips silently at small preview sizes and stays on-palette. Used for
    the bottom cog-skull's gear ring and the bulkhead-seam machinery nodes.
    """
    draw.ellipse((cx - radius, cy - radius, cx + radius, cy + radius), fill=color)
    for i in range(teeth_n):
        a = 2 * math.pi * i / teeth_n
        ca, sa = math.cos(a), math.sin(a)
        nx, ny = -sa, ca  # unit perpendicular, for the tooth's width
        bx, by = cx + ca * (radius - 1), cy + sa * (radius - 1)
        tx, ty = cx + ca * (radius + tooth_len), cy + sa * (radius + tooth_len)
        draw.polygon(
            [
                (round(bx + nx * tooth_w), round(by + ny * tooth_w)),
                (round(bx - nx * tooth_w), round(by - ny * tooth_w)),
                (round(tx - nx * tooth_w), round(ty - ny * tooth_w)),
                (round(tx + nx * tooth_w), round(ty + ny * tooth_w)),
            ],
            fill=color,
        )
    if hub is not None and hub > 0:
        draw.ellipse(
            (cx - hub, cy - hub, cx + hub, cy + hub),
            fill=hub_color if hub_color is not None else SPECTRA6["black"],
        )


def _grimdark_skull(draw, cx: int, cy: int, s: int, bone, void) -> None:
    """Draw a memento-mori skull of half-height ``s`` centred on (cx, cy).

    Parametrised off the s=12 reference design so the same primitive serves
    the big bottom cog-skull and the smaller flanking skulls. Cranium + jaw
    in ``bone``; eye sockets, nasal cavity and (at larger sizes) tooth gaps
    carved back to ``void``. ImageDraw-only, clip-safe, on-palette.
    """
    k = s / 12.0

    def r(v: float) -> int:
        return round(v * k)

    # Cranium + jaw.
    draw.ellipse((cx - r(12), cy - r(14), cx + r(12), cy + r(6)), fill=bone)
    draw.polygon(
        [(cx - r(8), cy + r(3)), (cx + r(8), cy + r(3)), (cx + r(5), cy + r(14)), (cx - r(5), cy + r(14))],
        fill=bone,
    )
    # Eye sockets + nasal cavity carved to the void.
    draw.ellipse((cx - r(9), cy - r(7), cx - r(2), cy + r(1)), fill=void)
    draw.ellipse((cx + r(2), cy - r(7), cx + r(9), cy + r(1)), fill=void)
    draw.polygon([(cx, cy - r(2)), (cx + r(2), cy + r(4)), (cx - r(2), cy + r(4))], fill=void)
    # Tooth gaps only at larger sizes — at small s they muddy into the jaw.
    if s >= 11:
        for tx in (cx - r(4), cx, cx + r(4)):
            draw.line((tx, cy + r(5), tx, cy + r(13)), fill=void, width=1)


# Deterministic seed for grimdark's industrial gunmetal mottle so re-renders
# of a given time stay byte-identical.
_GRIMDARK_MOTTLE_SEED = 0x40_0B


def _grimdark_paint_mottle(image: Image.Image, width: int, height: int) -> None:
    """Layer-0 dark-grey industrial mottle over the black void ground.

    Spectra 6 has no grey, so gunmetal is synthesised by stippling sparse
    white into the black ``page_bg`` (the K+W recipe, ~5-25% white reads as
    charcoal). A faint base gives a uniform tone; seeded blotches then lighten
    (scuffs) or darken (grime) local patches. This is the fallback when the
    gunmetal plate is missing. Only void pixels are flipped and every write is
    bounds-clipped, so it is safe at thumbnail preview sizes.
    """
    pixels = image.load()
    void = SPECTRA6["black"]
    grey_ink = SPECTRA6["white"]

    # Faint base: a ~4.5% hash-scatter of white (film grain; an ordered
    # Bayer grid would read as a dot screen). A different hash constant from
    # the blotches below keeps the two decorrelated.
    base_thresh = round(0.045 * 65535)
    for y in range(height):
        for x in range(width):
            if pixels[x, y] != void:
                continue
            hb = ((x * 374761393) ^ (y * 668265263) ^ ((x + y) * 1274126177)) & 0xFFFF
            if hb < base_thresh:
                pixels[x, y] = grey_ink

    # Weathering blotches: soft discs whose extra density falls from a random
    # peak to nothing at the rim; ~1/3 erode the base back to void (grime),
    # the rest add white (scuffs). An integer hash supplies the scatter.
    rng = random.Random(_GRIMDARK_MOTTLE_SEED)
    blotches = max(6, (width * height) // 9000)
    for _ in range(blotches):
        bx = rng.randint(0, width - 1)
        by = rng.randint(0, height - 1)
        br = rng.randint(18, 58)
        peak = rng.uniform(0.10, 0.24)
        darken = rng.random() < 0.34
        x0 = max(0, bx - br)
        x1 = min(width - 1, bx + br)
        y0 = max(0, by - br)
        y1 = min(height - 1, by + br)
        br2 = br * br
        for y in range(y0, y1 + 1):
            dy = y - by
            for x in range(x0, x1 + 1):
                dx = x - bx
                d2 = dx * dx + dy * dy
                if d2 > br2:
                    continue
                dens = peak * (1.0 - (d2 ** 0.5) / br)
                h = ((x * 2654435761) ^ (y * 40503) ^ ((x * y) & 0xFFFF)) & 0xFFFF
                if h / 65535.0 >= dens:
                    continue
                if darken:
                    if pixels[x, y] == grey_ink:
                        pixels[x, y] = void
                elif pixels[x, y] == void:
                    pixels[x, y] = grey_ink


def draw_grimdark_border(image: Image.Image, colors: dict) -> None:
    """Paint the Imperial Gothic frame: gold + blood doubled trim, an Aquila,
    a Mechanicus cog-skull, riveted bulkhead seams, and corner machinery.

    Every element is solid Spectra-6 ink (gold = yellow, blood = red, bone =
    white, void = black) laid with ``ImageDraw`` primitives, so it stays
    on-palette and clips silently at ``/api/preview`` thumbnail sizes
    (``TestPreviewSizeRendering``). The forge-amber matched-phrase glow is
    painted separately in ``_draw_text_body``.

    Composition:

    * **Layer-0 gunmetal plate** — ``grimdark_gunmetal.png`` dithered to
      white+black at render time, falling back to ``_grimdark_paint_mottle``
      when the asset is missing.
    * **Doubled trim** — thick gold outer rule, thin blood-red inner rule.
    * **Imperial Aquila** — the double-headed eagle, centred in the top
      margin, which keeps it clear of the right-aligned ``DEBUG MODE`` banner
      (so no ``_DEBUG_LABEL_RIGHT_INSET`` entry is needed).
    * **Mechanicus cog-skull** — a bone skull inside a gold toothed cog,
      flanked by two smaller skulls, centred in the bottom margin clear of
      the attribution.
    * **Riveted bulkhead seams** — gold rivets down each side rail with two
      cog nodes per side.
    * **Corner rivets** — gold discs with a blood centre at the inner corners.
    * **Mid-edge studs** — blood diamonds on the gold side rules.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    gold = SPECTRA6["yellow"]   # imperial gilt trim / Aquila
    blood = SPECTRA6["red"]     # inner rule / rivet cores / studs
    bone = SPECTRA6["white"]    # skull
    void = SPECTRA6["black"]    # ground / skull recesses

    # --- Layer 0: gunmetal plate dithered to white+black, or the synthesised
    # stipple when the asset is unavailable (stripped install).
    plate = _load_dithered_plate(GRIMDARK_PLATE, width, height, palette=_GUNMETAL_PALETTE)
    if plate is not None:
        image.paste(plate, (0, 0))
    else:
        _grimdark_paint_mottle(image, width, height)

    # --- Doubled imperial trim. ImageDraw rectangles clip, but an inverted
    # bbox (inset >= half-dimension) raises, so guard at tiny preview sizes.
    outer_inset = 12
    inner_inset = 19
    if width > 2 * outer_inset and height > 2 * outer_inset:
        draw.rectangle(
            (outer_inset, outer_inset, width - 1 - outer_inset, height - 1 - outer_inset),
            outline=gold,
            width=3,
        )
    if width > 2 * inner_inset and height > 2 * inner_inset:
        draw.rectangle(
            (inner_inset, inner_inset, width - 1 - inner_inset, height - 1 - inner_inset),
            outline=blood,
            width=1,
        )

    cx = width // 2

    # --- Imperial Aquila in the top margin (centred on (cx, ay)). Only paint
    # when the full wingspan fits inside the inner trim — at thumbnail widths
    # there isn't room, and a clipped half-eagle reads as noise.
    ay = 40
    half_span = 40
    if cx - half_span > inner_inset and ay + 18 < height:
        # Torso — a vertical gold diamond.
        draw.polygon(
            [(cx, ay - 14), (cx + 7, ay), (cx, ay + 16), (cx - 7, ay)],
            fill=gold,
        )
        # Twin heads angled outward, each with a downward-hooked beak.
        for sign in (-1, 1):
            hx = cx + sign * 8
            hy = ay - 13
            draw.ellipse((hx - 4, hy - 5, hx + 4, hy + 3), fill=gold)
            draw.polygon(
                [(hx + sign * 4, hy - 1), (hx + sign * 12, hy + 1), (hx + sign * 4, hy + 4)],
                fill=gold,
            )
        # Swept wings: the underside steps back toward the torso in three
        # downward feather points, reading as a heraldic pinion rather than
        # a smooth bat membrane.
        for sign in (-1, 1):
            wing = [
                (cx + sign * 5, ay - 9),            # inner shoulder
                (cx + sign * half_span, ay - 13),   # raised outer tip
                (cx + sign * (half_span - 5), ay + 1),
                (cx + sign * 31, ay - 2),           # notch
                (cx + sign * 27, ay + 9),           # primary feather (down)
                (cx + sign * 21, ay - 1),           # notch
                (cx + sign * 16, ay + 9),           # secondary feather (down)
                (cx + sign * 11, ay + 0),           # notch
                (cx + sign * 7, ay + 6),            # inner covert
            ]
            draw.polygon(wing, fill=gold)

    # --- Mechanicus cog-skull in the bottom margin (centred on (cx, sy)):
    # a gold toothed gear ring with a bone skull set inside it, plus two
    # smaller flanking skulls reading as an ossuary shelf.
    sy = height - 36
    if sy - 24 > inner_inset and cx - 24 > inner_inset:
        # Gear ring behind the skull — the Adeptus Mechanicus cog. Drawn first
        # so the skull paints on top, leaving the toothed rim showing around it.
        _grimdark_cog(draw, cx, sy, 21, 12, gold, tooth_len=4, tooth_w=3)
        draw.ellipse((cx - 16, sy - 16, cx + 16, sy + 16), fill=void)  # hollow the hub
        # Flanking ossuary skulls — small, just inside the side machinery.
        flank = 66
        if cx - flank - 8 > inner_inset:
            for fx in (cx - flank, cx + flank):
                _grimdark_skull(draw, fx, sy + 2, 8, bone, void)
        # Central skull set into the cog.
        _grimdark_skull(draw, cx, sy, 12, bone, void)

    # --- Riveted bulkhead seams down each side rail (x ~ 25, well clear of
    # the quote column): gold rivets plus two cog nodes per side.
    rail_x_left = inner_inset + 6
    rail_x_right = width - 1 - inner_inset - 6
    if rail_x_left + 10 < rail_x_right and height > 160:
        cog_ys = (round(height * 0.30), round(height * 0.70))
        for rail_x in (rail_x_left, rail_x_right):
            for ry in range(inner_inset + 30, height - inner_inset - 24, 40):
                draw.ellipse((rail_x - 3, ry - 3, rail_x + 3, ry + 3), fill=gold)
                draw.ellipse((rail_x - 1, ry - 1, rail_x + 1, ry + 1), fill=void)
            for cy_node in cog_ys:
                _grimdark_cog(draw, rail_x, cy_node, 8, 8, gold, tooth_len=3, tooth_w=2, hub=3, hub_color=void)

    # --- Corner rivets — gold hex-bolt discs with a blood centre, tucked
    # just inside the blood inner rule.
    rivet_r = 4
    rivet_inset = inner_inset + 7
    for rx, ry in (
        (rivet_inset, rivet_inset),
        (width - 1 - rivet_inset, rivet_inset),
        (rivet_inset, height - 1 - rivet_inset),
        (width - 1 - rivet_inset, height - 1 - rivet_inset),
    ):
        if rivet_r <= rx < width - rivet_r and rivet_r <= ry < height - rivet_r:
            draw.ellipse((rx - rivet_r, ry - rivet_r, rx + rivet_r, ry + rivet_r), fill=gold)
            draw.ellipse((rx - 1, ry - 1, rx + 1, ry + 1), fill=blood)

    # --- Mid-edge studs — small blood diamonds riveted onto the gold side
    # rules at the vertical midpoint.
    my = height // 2
    if my - 5 > outer_inset and my + 5 < height - outer_inset:
        for mx in (outer_inset, width - 1 - outer_inset):
            draw.polygon(
                [(mx, my - 5), (mx + 4, my), (mx, my + 5), (mx - 4, my)],
                fill=blood,
            )


# The King in Yellow — Robert W. Chambers, 1895.
#
#     Along the shore the cloud waves break,
#     The twin suns sink behind the lake,
#         The shadows lengthen
#             In Carcosa.
#     Strange is the night where black stars rise,
#     And strange moons circle through the skies ...
#
# ``carcosa`` stages the page as the play itself: a tattered yellow curtain
# drawn back at either side, the Yellow Sign hung over the proscenium, black
# stars in a sickly sky, and — along the foot — the towers of Carcosa standing
# against twin suns as they sink into Lake Hali. Everything is solid Spectra-6
# ink laid with ``ImageDraw`` primitives, plus two sparse haze washes and one
# tangerine post-pass on the curtain folds, all bounds-checked so the painter
# clips cleanly at the ``/api/preview`` thumbnail sizes.
#
# The Yellow Sign here is an original glyph — Chambers never describes it, and
# the well-known triskelion is a later artist's design — so it is drawn as
# three hooked arms spiralling off a ring, asymmetric enough to feel wrong.

# (x as a fraction of width, y, radius) for the black stars in the top margin.
# Positioned by hand so none crowds the Yellow Sign at the top centre.
_CARCOSA_BLACK_STARS: tuple[tuple[float, int, int], ...] = (
    (0.17, 20, 5),
    (0.29, 40, 4),
    (0.38, 16, 3),
    (0.62, 18, 4),
    (0.72, 42, 5),
    (0.83, 22, 3),
)
# (x fraction, radius) for the twin suns, both sitting on the horizon.
_CARCOSA_SUNS: tuple[tuple[float, int], ...] = ((0.655, 30), (0.765, 19))
# Carcosa's skyline as (x fraction, half width, height, spire) — a spire of 0
# is a flat-topped tower. Kept low enough that both suns' crowns stay clear:
# the city stands *against* the suns, it does not hide them.
_CARCOSA_TOWERS: tuple[tuple[float, int, int, int], ...] = (
    (0.596, 2, 7, 5),
    (0.61, 3, 12, 8),
    (0.626, 2, 20, 12),
    (0.64, 4, 9, 6),
    (0.655, 2, 26, 14),
    (0.668, 3, 14, 9),
    (0.684, 2, 10, 7),
    (0.70, 3, 17, 10),
    (0.716, 2, 8, 5),
    (0.735, 3, 12, 8),
    (0.752, 2, 22, 12),
    (0.768, 4, 9, 6),
    (0.785, 2, 14, 9),
    (0.803, 3, 7, 5),
)


def _carcosa_haze(image: Image.Image, x0: int, x1: int, y_near: int, y_far: int, peak: float) -> None:
    """Scatter a sparse yellow haze over black, densest at ``y_near``.

    Density falls linearly to zero at ``y_far`` (either side of ``y_near``), and
    only black pixels are touched so nothing already painted is overwritten. A
    positional hash rather than a Bayer rank, because at these densities an
    ordered tile lays a visible lattice (see :func:`position_noise`).
    """
    width, height = image.size
    px = image.load()
    black = SPECTRA6["black"]
    yellow = SPECTRA6["yellow"]
    span = y_far - y_near
    if span == 0:
        return
    lo, hi = sorted((y_near, y_far))
    for y in range(max(0, lo), min(height, hi + 1)):
        density = peak * (1.0 - (y - y_near) / span)
        if density <= 0:
            continue
        cut = int(density * 256)
        for x in range(max(0, x0), min(width, x1)):
            if px[x, y] == black and position_noise(x, y) < cut:
                px[x, y] = yellow


def _carcosa_star(cx: float, cy: float, r: float) -> list[tuple[float, float]]:
    """A four-pointed star: long cardinal rays, pinched waist."""
    waist = max(1.0, r * 0.32)
    points = []
    for i in range(8):
        angle = math.pi / 4 * i - math.pi / 2
        radius = r if i % 2 == 0 else waist
        points.append((cx + radius * math.cos(angle), cy + radius * math.sin(angle)))
    return points


def _carcosa_paint_drape(image: Image.Image, draw: ImageDraw.ImageDraw, side: int, scale: float) -> None:
    """One tattered yellow curtain, tied back, down the left (-1) or right (+1).

    The inner edge is torn — two incommensurate sines plus a notch every so
    often — and the hem breaks into hanging strands. Fold creases run from the
    rail to the tie-back and fan out below it; each crease is laid as a 3 px
    red shadow under a 1 px black line, and the red is then Bayer-flipped to
    the R+Y 5/8:3/8 tangerine so the folds read as shadowed, decaying cloth.
    """
    width, height = image.size
    yellow = SPECTRA6["yellow"]
    red = SPECTRA6["red"]
    black = SPECTRA6["black"]
    top_w = 34 * scale
    tie_w = 12 * scale
    hem_w = 29 * scale
    tie_y = int(height * 0.56)
    hem_y = int(height * 0.79)

    def edge(y: int) -> float:
        if y <= tie_y:
            t = y / max(1, tie_y)
            w = top_w + (tie_w - top_w) * (t ** 1.4)
        else:
            t = (y - tie_y) / max(1, hem_y - tie_y)
            w = tie_w + (hem_w - tie_w) * math.sqrt(t)
        tear = 1.6 * math.sin(y * 0.31) + 1.1 * math.sin(y * 0.117 + 1.3)
        if (y // 6) % 9 == 4:
            tear -= 4 * scale  # a rent in the cloth
        return max(2.0, w + tear * scale)

    def fx(x: float) -> float:
        return x if side < 0 else width - 1 - x

    step = 3
    inner = [(fx(edge(y)), y) for y in range(0, hem_y + 1, step)]
    # Ragged hem: strands of irregular length hanging below ``hem_y``.
    hem = []
    x = edge(hem_y)
    strand = 0
    while x > 0:
        drop = int((10 + 22 * abs(math.sin(strand * 2.3 + side))) * scale)
        hem.append((fx(x), hem_y + drop))
        x -= 3 * scale
        hem.append((fx(max(0.0, x)), hem_y + int(drop * 0.3)))
        x -= 3 * scale
        strand += 1
    polygon = [(fx(0), 0)] + inner + hem + [(fx(0), hem_y)]
    draw.polygon(polygon, fill=yellow)

    # Fold creases: rail → tie-back, then tie-back → hem.
    tie_x = tie_w * 0.5
    creases = []
    for frac in (0.3, 0.62, 0.9):
        creases.append(((top_w * frac, 0), (tie_x, tie_y)))
    for frac in (0.25, 0.7):
        creases.append(((tie_x, tie_y), (hem_w * frac, hem_y)))
    for (ax, ay), (bx, by) in creases:
        draw.line([(fx(ax + 1), ay), (fx(bx + 1), by)], fill=red, width=3)
    for (ax, ay), (bx, by) in creases:
        draw.line([(fx(ax), ay), (fx(bx), by)], fill=black, width=1)
    # Tangerine shadow: flip 3/8 of the crease red to yellow on the 4x4 tile.
    px = image.load()
    x_lo = 0 if side < 0 else max(0, int(width - 1 - top_w - 4))
    x_hi = min(width, int(top_w + 4)) if side < 0 else width
    for y in range(0, min(height, hem_y + 1)):
        for xx in range(x_lo, x_hi):
            if px[xx, y] == red and BAYER_4x4[y % 4][xx % 4] < 6:
                px[xx, y] = yellow

    # Blood-red tie-back cord, knotted once, with a tassel hanging off it.
    cord_x1 = fx(tie_w + 3 * scale)
    draw.line([(fx(0), tie_y - 2), (cord_x1, tie_y + 1)], fill=red, width=max(1, int(3 * scale)))
    knot = max(1, int(3 * scale))
    draw.ellipse((cord_x1 - knot, tie_y - knot + 1, cord_x1 + knot, tie_y + knot + 1), fill=red)
    draw.line([(cord_x1, tie_y + knot), (cord_x1 - side * 2 * scale, tie_y + 16 * scale)], fill=red, width=1)

    # Moth-holes and black stars eaten through the cloth.
    for fy, fxr, r in ((0.12, 0.45, 3), (0.31, 0.55, 2), (0.47, 0.5, 1.5), (0.68, 0.6, 2)):
        y = int(height * fy)
        cx = fx(edge(y) * fxr)
        rr = r * scale
        if rr >= 2:
            draw.polygon(_carcosa_star(cx, y, rr * 1.8), fill=black)
        else:
            draw.ellipse((cx - 1, y - 1, cx + 1, y + 1), fill=black)


def _carcosa_paint_sign(draw: ImageDraw.ImageDraw, cx: float, cy: float, s: float, ink) -> None:
    """The Yellow Sign: three hooked arms spiralling off a small ring.

    Each arm is an Archimedean spiral swept through 110 degrees and closed by
    a short backward hook; the arms are rotated 120 degrees apart but the third
    is drawn longer, so the glyph is almost — not quite — symmetric.
    """
    stroke = max(1, int(round(s / 7)))
    ring = s * 0.22
    draw.ellipse((cx - ring, cy - ring, cx + ring, cy + ring), outline=ink, width=stroke)
    for arm, base in enumerate((-90.0, 30.0, 150.0)):
        reach = s * (1.12 if arm == 2 else 0.95)
        points = []
        for i in range(15):
            t = i / 14
            theta = math.radians(base + 110 * t)
            r = ring + (reach - ring) * t
            points.append((cx + r * math.cos(theta), cy + r * math.sin(theta)))
        # The hook: curl back inward from the arm's tip.
        tip_theta = math.radians(base + 110)
        hook_r = reach * 0.66
        points.append((cx + hook_r * math.cos(tip_theta + 0.45), cy + hook_r * math.sin(tip_theta + 0.45)))
        draw.line(points, fill=ink, width=stroke, joint="curve")
    # A single dot beneath, like a punctuation mark that is not in any alphabet.
    dot = max(1.0, s * 0.09)
    dy = cy + s * 1.3
    draw.ellipse((cx - dot, dy - dot, cx + dot, dy + dot), fill=ink)


def _carcosa_paint_sky(image: Image.Image, draw: ImageDraw.ImageDraw, scale: float) -> None:
    """The sickly top margin: a thin yellow haze and the black stars rising in it."""
    width, height = image.size
    yellow = SPECTRA6["yellow"]
    black = SPECTRA6["black"]
    margin = int(40 * scale)
    band = int(56 * scale)
    _carcosa_haze(image, margin, width - margin, 0, band, 0.09)
    for fx, y, r in _CARCOSA_BLACK_STARS:
        cx, cy, rr = width * fx, y * scale, r * scale
        if rr < 2 or cy + rr >= height:
            continue
        # Clear a pocket in the haze, then draw the star as a black shape with
        # a yellow rim — a black star has to be outlined to be seen at all.
        halo = rr + 2
        draw.ellipse((cx - halo, cy - halo, cx + halo, cy + halo), fill=black)
        draw.polygon(_carcosa_star(cx, cy, rr + 1), fill=black, outline=yellow)


def _carcosa_paint_lake(image: Image.Image, draw: ImageDraw.ImageDraw, scale: float) -> None:
    """Lake Hali along the foot: cloud-waves, twin suns, Carcosa, reflections."""
    width, height = image.size
    yellow = SPECTRA6["yellow"]
    white = SPECTRA6["white"]
    black = SPECTRA6["black"]
    horizon = height - int(32 * scale)
    margin = int(42 * scale)
    if horizon <= 0 or width <= 2 * margin:
        return

    # Glow of the setting suns over the far shore.
    _carcosa_haze(image, margin, width - margin, horizon - 1, horizon - int(34 * scale), 0.12)

    # The twin suns, half-sunk.
    for fx, r in _CARCOSA_SUNS:
        cx, rr = width * fx, r * scale
        draw.pieslice((cx - rr, horizon - rr, cx + rr, horizon + rr), 180, 360, fill=yellow)

    # Carcosa, black against the suns and the glow.
    for fx, half, h, spire in _CARCOSA_TOWERS:
        cx = width * fx
        hw, hh, sp = half * scale, h * scale, spire * scale
        top = horizon - hh
        draw.rectangle((cx - hw, top, cx + hw, horizon), fill=black)
        if sp:
            draw.polygon([(cx - hw, top), (cx, top - sp), (cx + hw, top)], fill=black)
        # One lit window in the taller towers — someone is awake in Carcosa.
        if h >= 17:
            wy = top + hh * 0.3
            draw.line([(cx, wy), (cx, wy + 2)], fill=yellow, width=1)

    # The shore line itself.
    draw.line([(margin, horizon), (width - margin, horizon)], fill=yellow, width=1)

    # Cloud-waves breaking along the shore to the left of the city: rows of
    # small white crests that thin out as they near the water.
    wave_r = max(2, int(5 * scale))
    x_end = width * 0.55
    for row, dy in enumerate((3, 9, 15)):
        y = horizon + int(dy * scale)
        x = margin + (row % 2) * wave_r
        while x + 2 * wave_r < x_end:
            if (int(x) // (2 * wave_r) + row) % (row + 1) == 0:
                draw.arc((x, y - wave_r, x + 2 * wave_r, y + wave_r), 200, 340, fill=white, width=1)
            x += 2 * wave_r + int(3 * scale)

    # The suns' reflections in the lake: broken dashes that narrow with depth.
    for fx, r in _CARCOSA_SUNS:
        cx = width * fx
        for i, dy in enumerate(range(3, int(26 * scale), 3)):
            half = r * scale * (1.0 - i * 0.11)
            if half < 1:
                break
            shift = 2.5 * math.sin(i * 1.9 + fx * 10) * scale
            y = horizon + dy
            if y >= height:
                break
            gap = max(1.0, half * 0.25)
            draw.line([(cx - half + shift, y), (cx - gap + shift, y)], fill=yellow, width=1)
            draw.line([(cx + gap + shift, y), (cx + half + shift, y)], fill=yellow, width=1)


def draw_carcosa_border(image: Image.Image, colors: dict) -> None:
    """Paint the King in Yellow stage: curtains, the Sign, the sky, Lake Hali.

    Composition, back to front:

    * **Sky** — a sparse yellow haze across the top margin, fading by y≈56,
      with six black stars rising in it (black four-pointed stars, rimmed in
      yellow so a black shape can be seen against black).
    * **The Yellow Sign** — centred at the top, clear of the right-aligned
      ``DEBUG MODE`` banner.
    * **Tattered curtains** — one down each side, drawn back to a blood-red
      tie-back cord, torn along the inner edge and frayed into strands at the
      hem, with tangerine-shadowed folds and holes eaten through them.
    * **Lake Hali** — along the foot, the towers of Carcosa stand in
      silhouette against twin suns as they sink, cloud-waves break along the
      shore to the left, and the suns' reflections break up in the water.

    Only the curtains reach the side margins (x ≤ 34 at the rail; the body
    column starts at x≈60); the sky stays above y≈56 and the lake below
    y≈416, the bands the shared layout leaves free.
    """
    del colors  # every ink here is the theme's own; the THEMES slots are the text's.
    width, height = image.size
    scale = min(1.0, width / 800, height / 480)
    draw = ImageDraw.Draw(image)
    _carcosa_paint_sky(image, draw, scale)
    sign_s = 22 * scale
    if sign_s >= 5:
        _carcosa_paint_sign(draw, width / 2, 28 * scale, sign_s, SPECTRA6["yellow"])
    _carcosa_paint_lake(image, draw, scale)
    for side in (-1, 1):
        _carcosa_paint_drape(image, draw, side, scale)


# Fixed seed for the letter theme's aged-paper texture, so re-renders stay
# byte-identical.
_LETTER_PAPER_SEED = 0x1E77E2


def _letter_paint_aged_paper(image: Image.Image, width: int, height: int, page_bg,
                             cream_light, sepia_a, sepia_b, rng: random.Random) -> None:
    """Synthesised aged-paper Layer 0 — the graceful fallback for ``letter``
    when the committed ``letter_aged_paper.png`` plate is missing.

    Two textures, every pixel an ink so palette-snap is a no-op. Deliberately
    subtle: it should read as old paper, not compete with the handwriting.

      (a) Uneven cream tan: yellow-wash density modulated by an edge
          vignette, a low-amplitude mottle (precomputed per-row / per-column
          sine tables, no per-pixel trig) and a fine grain jitter. Centre
          ≈9% yellow, corners ≈14%.
      (b) Foxing: seeded R+G sepia spots biased toward the edges.

    The creases and wax seal are painted by ``draw_letter_border`` after this
    returns.
    """
    if page_bg is None:
        return
    pixels = image.load()
    col = [math.sin(x * 0.013) + 0.6 * math.sin(x * 0.031 + 1.7) for x in range(width)]
    row_mottle = [math.sin(y * 0.015 + 0.5) + 0.6 * math.sin(y * 0.029 + 2.3) for y in range(height)]
    half_w = max(1.0, width * 0.5)
    half_h = max(1.0, height * 0.5)
    for y in range(height):
        brow = BAYER_4x4[y & 3]
        ry = row_mottle[y]
        edge_y = 1.0 - min(y, height - 1 - y) / half_h
        for x in range(width):
            if pixels[x, y] != page_bg:
                continue
            edge_x = 1.0 - min(x, width - 1 - x) / half_w
            edge = edge_x if edge_x > edge_y else edge_y
            mottle = (col[x] + ry) * 0.5
            grain = (((x * 131 + y * 57) % 17) - 8) / 8.0
            density = 0.085 + 0.05 * (edge * edge) + 0.02 * mottle + 0.02 * grain
            if brow[x & 3] < density * 16:
                pixels[x, y] = cream_light

    # (b) Foxing: each spot a 2x2 or 3x3 R/G checkerboard so it carries a
    # balanced pair and averages to rust-brown (a circular mask leaves
    # imbalanced plus-shapes that read as lone red or green specks).
    n_spots = max(10, (width * height) // 9000)
    for _ in range(n_spots):
        fx = int(rng.triangular(0, width - 1, rng.choice((0, width - 1))))
        fy = int(rng.triangular(0, height - 1, rng.choice((0, height - 1))))
        spot_w = rng.choice((2, 2, 3))
        for dy in range(spot_w):
            for dx in range(spot_w):
                px, py = fx + dx, fy + dy
                if 0 <= px < width and 0 <= py < height and pixels[px, py] in (page_bg, cream_light):
                    pixels[px, py] = sepia_a if (px + py) & 1 else sepia_b


def draw_letter_border(image: Image.Image, colors: dict,
                       clear_rect: tuple[int, int, int, int] | None = None) -> None:
    """Wax-sealed letter decoration: aged, lightly-crumpled paper ground +
    fold/crumple creases + a pressed oxblood / maroon wax seal in the
    bottom-right corner.

    Everything stays in the margins and paints before the text, so the
    creases sit behind the glyphs as real folds do and the quote block never
    reaches the seal's corner. Layers, bottom to top:

    * **Layer 0 — aged paper.** ``letter_aged_paper.png`` dithered to
      white/yellow/red/green (W+Y cream, R+G foxing), so palette-snap is a
      no-op; ``_letter_paint_aged_paper`` synthesises it when the asset is
      missing.
    * **Writing-area knockout** — with ``clear_rect``, the body rect is reset
      to clean cream with a feathered edge, so foxing doesn't speckle the
      thin script strokes.
    * **Crumple creases** — two dotted fold creases at the thirds, plus (in
      the fallback path only) a few soft tonal wrinkles. Painted only on bare
      paper; the body text overpaints them.
    * **The wax seal** (bottom-right) — an oxblood dome lit from the upper
      left: a scalloped rim (two summed sinusoids), a Bayer ramp anchored on
      R+K maroon (red on the lit shoulder, white for coral gloss, black
      climbing toward the rim), a stippled cast shadow, a specular hotspot, a
      ring of shaded beads and a recessed hourglass emblem, plus a few
      spatter flecks. It sits clear of the attribution and the y=14-29 debug
      band, so ``letter`` needs no ``_DEBUG_LABEL_RIGHT_INSET`` entry.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    page_bg = colors.get("page_bg")
    ink = colors["text"]
    wax_red = colors["accent"]
    maroon_dark = SPECTRA6["black"]
    cream_light = SPECTRA6["yellow"]

    sepia_a = SPECTRA6["red"]
    sepia_b = SPECTRA6["green"]
    rng = random.Random(_LETTER_PAPER_SEED)

    # ---- Layer 0: aged paper ------------------------------------------
    # Committed plate dithered to W/Y/R/G, or the synthesised fallback when
    # the asset is unavailable (stripped install). Both yield pure Spectra-6.
    # The creases and seal paint over either.
    plate = _load_dithered_plate(LETTER_PLATE, width, height, palette=_AGED_PAPER_PALETTE)
    if plate is not None:
        image.paste(plate, (0, 0))
    else:
        _letter_paint_aged_paper(image, width, height, page_bg, cream_light, sepia_a, sepia_b, rng)
    pixels = image.load()

    # ---- Body-text writing area: clean cream knockout -----------------
    # The plate's foxing speckle around the thin Dancing Script strokes reads
    # as blur, so with ``clear_rect`` the rect is reset to clean cream (white
    # + light yellow stipple), feathered so it blends into the foxed margins.
    if clear_rect is not None and page_bg is not None:
        cx0, cy0, cx1, cy1 = clear_rect
        feather = 16
        for py in range(max(0, cy0), min(height - 1, cy1) + 1):
            for px in range(max(0, cx0), min(width - 1, cx1) + 1):
                edge_d = min(px - cx0, cx1 - px, py - cy0, cy1 - py)
                # Feathered ring: clean with probability rising inward.
                if edge_d < feather and ((px * 131 + py * 57) % 16) / 16.0 >= edge_d / feather:
                    continue
                # ~1/16 yellow (≈6%), matching the plate's pale-cream centre,
                # so only the removed foxing distinguishes the area.
                pixels[px, py] = cream_light if BAYER_4x4[py & 3][px & 3] == 0 else page_bg

    # ---- Crumple creases ----------------------------------------------
    # Two dotted black fold creases at the thirds, plus soft tonal wrinkles
    # (a cream ridge with a white highlight) that read as light catching the
    # sheet rather than as scratches. Painted only on bare paper / cream.
    paper_tones = (page_bg, cream_light)
    margin = 26
    crease_step = 4
    for frac in (1, 2):
        cy = (height * frac) // 3
        if cy + 1 >= height:
            continue
        for x in range(margin, width - margin, crease_step):
            if pixels[x, cy] in paper_tones:
                pixels[x, cy] = ink
            vx = x + crease_step // 2
            if vx < width - margin and (x // crease_step) & 1 and pixels[vx, cy + 1] in paper_tones:
                pixels[vx, cy + 1] = ink

    # Soft tonal wrinkles, fallback path only: over the plate's W+Y stipple a
    # solid cream ridge reads as a hard bright streak.
    if page_bg is not None and plate is None:
        for _ in range(5):
            wx = rng.randint(60, max(61, width - 60))
            wy = rng.randint(50, max(51, height - 50))
            angle = rng.uniform(0.0, math.pi)
            length = rng.randint(50, 130)
            dxu, dyu = math.cos(angle), math.sin(angle)
            nxp, nyp = -dyu, dxu  # unit perpendicular → highlight side
            for s in range(length):
                px = int(wx + (s - length // 2) * dxu)
                py = int(wy + (s - length // 2) * dyu)
                if 0 <= px < width and 0 <= py < height and pixels[px, py] in paper_tones:
                    pixels[px, py] = cream_light
                hx, hy = int(px + nxp), int(py + nyp)
                if 0 <= hx < width and 0 <= hy < height and pixels[hx, hy] in paper_tones:
                    pixels[hx, hy] = page_bg

    # ---- Wax seal (bottom-right) -------------------------------------
    # Scale the seal to the canvas so preview thumbnails get a proportional
    # seal.
    base_r = max(10, min(40, int(min(width, height) * 0.085)))
    scx = width - base_r - 32
    scy = height - base_r - 38
    if scx <= base_r or scy <= base_r:
        # Too small to seat a seal; the paper and creases carry the theme.
        return

    # Depth model: a glossy dome lit from the upper-left — coral highlight,
    # red body, R+K maroon core shadow — plus a cast shadow and a specular
    # hotspot.
    highlight_ink = SPECTRA6["white"]  # R+W coral at <100% density; pure gloss at 100%
    light_dx, light_dy = -0.7071, -0.7071  # light from the upper-left

    # (0) Clean cream bed behind the seal, so foxing doesn't show as noise
    # around the bead. Cream and plate are both W+Y, so only the foxing is
    # removed; the rim ring thins it out gradually so no edge shows.
    if page_bg is not None:
        knock_r = base_r * 1.7
        feather = knock_r * 0.78
        kx0 = max(0, int(scx - knock_r))
        kx1 = min(width - 1, int(scx + knock_r))
        ky0 = max(0, int(scy - knock_r))
        ky1 = min(height - 1, int(scy + knock_r))
        for py in range(ky0, ky1 + 1):
            for px in range(kx0, kx1 + 1):
                d = math.hypot(px - scx, py - scy)
                if d > knock_r:
                    continue
                if d > feather:
                    # Rim: thin the foxing out toward the edge.
                    if pixels[px, py] in (sepia_a, sepia_b):
                        keep = (knock_r - d) / (knock_r - feather)  # 1 at feather → 0 at rim
                        if ((px * 131 + py * 57) % 16) / 16.0 < keep:
                            pixels[px, py] = page_bg
                    continue
                # ~1/16 yellow, as in the writing-area knockout.
                pixels[px, py] = cream_light if BAYER_4x4[py & 3][px & 3] == 0 else page_bg

    # (1) Soft cast shadow, offset down-right and fading to its rim. Drawn
    # before the seal so only the lower-right crescent survives.
    # ``page_bg is None`` guards the sentinel-render test path.
    if page_bg is not None:
        shadow_dx = max(3, base_r // 9)
        shadow_dy = max(4, base_r // 7)
        shx, shy = scx + shadow_dx, scy + shadow_dy
        shadow_r = base_r * 1.06
        sx0 = max(0, int(shx - shadow_r))
        sy0 = max(0, int(shy - shadow_r))
        sx1 = min(width - 1, int(shx + shadow_r))
        sy1 = min(height - 1, int(shy + shadow_r))
        # Fall on all four paper inks, including the plate's R/G foxing, so
        # foxing specks don't poke through the shadow.
        paper_inks = (page_bg, cream_light, sepia_a, sepia_b)
        for py in range(sy0, sy1 + 1):
            for px in range(sx0, sx1 + 1):
                if pixels[px, py] not in paper_inks:
                    continue
                d = math.hypot(px - shx, py - shy)
                if d >= shadow_r:
                    continue
                density = 0.6 * (1.0 - d / shadow_r)
                if BAYER_4x4[py & 3][px & 3] < density * 16:
                    pixels[px, py] = maroon_dark

    # (2) Irregular pressed-wax rim: sum of two sinusoids around the circle.
    seal_pts = []
    steps = 72
    for i in range(steps):
        theta = (i / steps) * 2 * math.pi
        wobble = 1.0 + 0.05 * math.sin(theta * 5) + 0.035 * math.sin(theta * 8 + 1.3)
        r = base_r * wobble
        seal_pts.append((scx + r * math.cos(theta), scy + r * math.sin(theta)))
    draw.polygon(seal_pts, fill=wax_red)

    # Seal bbox for the per-pixel shading pass below.
    rim = base_r + 4
    bx0 = max(0, scx - rim)
    by0 = max(0, scy - rim)
    bx1 = min(width - 1, scx + rim)
    by1 = min(height - 1, scy + rim)

    # (3) Dome shading. ``t`` is the shadow amount (0 lit, 1 deepest): a
    # directional term plus rim darkening on the shadow side only, so the
    # lit shoulder stays bright to the edge. ``t`` is Bayer-dithered into a
    # ramp anchored on R+K maroon: white for coral gloss at the highlight,
    # black density climbing past 50% toward the rim. The base ink between
    # dithered pixels stays ``wax_red``.
    for py in range(by0, by1 + 1):
        for px in range(bx0, bx1 + 1):
            if pixels[px, py] != wax_red:
                continue
            nx = (px - scx) / base_r
            ny = (py - scy) / base_r
            directional = nx * light_dx + ny * light_dy  # +lit … -shadow
            r2 = nx * nx + ny * ny
            t = 0.5 - 0.5 * max(-1.0, min(1.0, directional / 1.05))
            if t > 0.5:  # shadow side: deepen toward the rim
                t += 0.20 * max(0.0, r2 - 0.45)
            else:        # lit side: only a whisper of edge falloff
                t += 0.06 * max(0.0, r2 - 0.55)
            t = max(0.0, min(1.0, t))
            cell = BAYER_4x4[py & 3][px & 3]
            if t < 0.25:
                # Lit shoulder: white dithered into red for a coral gloss,
                # brightest at the terminator-free highlight.
                density = (0.25 - t) / 0.25 * 0.5
                if cell < density * 16:
                    pixels[px, py] = highlight_ink
            else:
                # Body → core shadow: ~35% black below the highlight, ~50%
                # (true maroon) at mid-tone, up to ~90% at the rim.
                density = min(0.9, 0.35 + (t - 0.25) * 0.733)
                if cell < density * 16:
                    pixels[px, py] = maroon_dark

    # (4) Specular hotspot — solid white where the dome faces the light,
    # for the wet-wax sheen the coral dither alone can't give.
    spec_x = scx + int(-0.42 * base_r)
    spec_y = scy + int(-0.42 * base_r)
    spec_r = max(1, base_r // 14)
    draw.ellipse(
        (spec_x - spec_r, spec_y - spec_r, spec_x + spec_r, spec_y + spec_r),
        fill=highlight_ink,
    )

    # (5) Beaded rim: signet beading just inside the edge. Each bead is a
    # maroon dot with a 1 px coral highlight on its lit side, so the ring
    # catches the dome's light rather than reading as a flat dotted circle.
    bead_r = base_r * 0.82
    n_beads = 18
    for i in range(n_beads):
        theta = (i / n_beads) * 2 * math.pi
        bxp = scx + bead_r * math.cos(theta)
        byp = scy + bead_r * math.sin(theta)
        lit = (math.cos(theta) * light_dx + math.sin(theta) * light_dy) > 0
        draw.ellipse((bxp - 1, byp - 1, bxp + 1, byp + 1), fill=maroon_dark)
        if lit:
            hx, hy = int(bxp + light_dx), int(byp + light_dy)
            if bx0 <= hx <= bx1 and by0 <= hy <= by1:
                pixels[hx, hy] = highlight_ink

    # (6) Recessed hourglass emblem (the time motif). Each groove is a
    # maroon stroke over a coral highlight offset down-right onto the far
    # inner wall, so it reads as engraved into the wax.
    eh = base_r * 0.5   # half-height of the hourglass
    ew = base_r * 0.32  # half-width at the flared ends
    top_y = scy - eh
    bot_y = scy + eh
    upper = [(scx - ew, top_y), (scx + ew, top_y), (scx, scy)]
    lower = [(scx - ew, bot_y), (scx + ew, bot_y), (scx, scy)]
    cap_top = ((scx - ew - 1, top_y), (scx + ew + 1, top_y))
    cap_bot = ((scx - ew - 1, bot_y), (scx + ew + 1, bot_y))
    # Highlight pass first (offset +1,+1), then the maroon groove on top,
    # leaving a coral sliver on the lower-right of every stroke.
    for offset, colour in ((1, highlight_ink), (0, maroon_dark)):
        draw.line([(x + offset, y + offset) for x, y in upper] + [(upper[0][0] + offset, upper[0][1] + offset)], fill=colour, width=2)
        draw.line([(x + offset, y + offset) for x, y in lower] + [(lower[0][0] + offset, lower[0][1] + offset)], fill=colour, width=2)
        draw.line((cap_top[0][0] + offset, cap_top[0][1] + offset, cap_top[1][0] + offset, cap_top[1][1] + offset), fill=colour, width=2)
        draw.line((cap_bot[0][0] + offset, cap_bot[0][1] + offset, cap_bot[1][0] + offset, cap_bot[1][1] + offset), fill=colour, width=2)

    # (7) A couple of stray wax flecks beside the seal — drip character,
    # each with a 1 px maroon shadow so it sits on the page like the bead.
    for fx, fy, fr in (
        (scx - base_r - 6, scy + base_r - 4, 2),
        (scx + base_r - 2, scy - base_r + 8, 1),
    ):
        if 0 <= fx - fr and fx + fr < width and 0 <= fy - fr and fy + fr < height:
            sxp, syp = fx + 1, fy + 2
            if page_bg is not None and 0 <= sxp < width and 0 <= syp < height:
                if pixels[sxp, syp] in (page_bg, cream_light, sepia_a, sepia_b):
                    pixels[sxp, syp] = maroon_dark
            draw.ellipse((fx - fr, fy - fr, fx + fr, fy + fr), fill=wax_red)
            # Tone the fleck toward oxblood so it matches the shaded seal.
            for py in range(max(0, fy - fr), min(height - 1, fy + fr) + 1):
                for px in range(max(0, fx - fr), min(width - 1, fx + fr) + 1):
                    if pixels[px, py] == wax_red and (px + py) & 1:
                        pixels[px, py] = maroon_dark


# Copper-trace routes for ``draw_circuit_border``: polylines of (x_frac,
# y_frac) waypoints, stroked in gold with ``joint="curve"`` corners (the
# teardrop bends of a PCB autorouter). They hug the perimeter margins (the
# body block is knocked out via ``clear_rect``) and stay clear of the
# y=14-29 DEBUG-banner band.
_CIRCUIT_TRACES: tuple[tuple[tuple[float, float], ...], ...] = (
    # Top bus — left-to-right across the top margin with a centred jog.
    ((0.06, 0.10), (0.40, 0.10), (0.46, 0.16)),
    ((0.55, 0.16), (0.61, 0.10), (0.86, 0.10)),
    # Left rail down the side margin with two right-angle branches inward.
    ((0.05, 0.16), (0.05, 0.55), (0.12, 0.62)),
    ((0.05, 0.34), (0.11, 0.34)),
    # Right rail down the side margin.
    ((0.95, 0.18), (0.95, 0.60), (0.88, 0.67)),
    ((0.95, 0.42), (0.89, 0.42)),
    # Bottom bus across the bottom margin with a 45° jog.
    ((0.09, 0.90), (0.42, 0.90), (0.48, 0.84)),
    ((0.58, 0.84), (0.64, 0.90), (0.92, 0.90)),
    # Two short diagonal traces for visual variety.
    ((0.15, 0.21), (0.21, 0.27), (0.21, 0.40)),
    ((0.85, 0.24), (0.79, 0.30), (0.79, 0.45)),
)
# Silkscreen reference designators (text, x_frac, y_frac) beside the routed
# pads. The crystal "Y1" is drawn separately as a component outline — the
# quartz oscillator, the literal clock element on a real board.
_CIRCUIT_DESIGNATORS: tuple[tuple[str, float, float], ...] = (
    ("R1", 0.40, 0.10),
    ("R2", 0.61, 0.10),
    ("C1", 0.05, 0.55),
    ("C4", 0.95, 0.60),
    ("U1", 0.21, 0.40),
    ("D2", 0.79, 0.45),
)


def draw_circuit_border(
    image: Image.Image,
    colors: dict,
    clear_rect: tuple[int, int, int, int] | None = None,
) -> None:
    """Paint a printed-circuit-board (PCB) composition around the quote.

    The clock as if etched onto the board that drives the panel. Layers,
    deepest → shallowest:

    * **Layer 0 — forest soldermask wash.** Half the green ``page_bg`` pixels
      flipped to black on the ``(x + y) & 1`` checkerboard: G+K 1:1 reads as
      FR-4 bottle-green and keeps ``circuit`` distinct from ``atomic``'s mint.
      Idempotent (only green pixels flip), which matters because ``render``
      calls every border painter twice.
    * **Copper traces** (gold) from ``_CIRCUIT_TRACES``.
    * **Plated pads** at every trace endpoint — gold ring, dark drill.
    * **Mounting holes** in the four corners, inset 28 px. The top-right one
      overlaps the DEBUG-banner band, hence ``circuit``'s
      ``_DEBUG_LABEL_RIGHT_INSET`` entry.
    * **Y1 crystal** in the bottom-left margin.
    * **Silkscreen designators** (white) plus an ``IDLE HOURS · REV 2.0``
      legend bottom-right.

    With ``clear_rect`` the body region is reset to clean soldermask and
    framed with a white silkscreen component outline and a pin-1 marker.
    """
    width, height = image.size
    page_bg = colors.get("page_bg")
    gold = colors.get("accent", SPECTRA6["yellow"])
    silk = colors.get("text", SPECTRA6["white"])
    green_ink = SPECTRA6["green"]
    black_ink = SPECTRA6["black"]
    pixels = image.load()
    draw = ImageDraw.Draw(image)

    # ------------------------------------------------------------------
    # Layer 0 — forest soldermask wash (G+K 1:1 over the flat-green ground).
    if page_bg == green_ink:
        for y in range(height):
            row_odd = y & 1
            for x in range(width):
                if ((x & 1) ^ row_odd) and pixels[x, y] == green_ink:
                    pixels[x, y] = black_ink

    trace_w = max(2, round(width / 320))
    pad_r = max(3, round(width / 130))

    def _pad(px: int, py: int, r_out: int = pad_r) -> None:
        r_in = max(1, r_out - 3)
        draw.ellipse((px - r_out, py - r_out, px + r_out, py + r_out), fill=gold)
        draw.ellipse((px - r_in, py - r_in, px + r_in, py + r_in), fill=black_ink)

    # ------------------------------------------------------------------
    # Copper traces + pads at their endpoints.
    for route in _CIRCUIT_TRACES:
        pts = [(round(fx * width), round(fy * height)) for fx, fy in route]
        if len(pts) >= 2:
            draw.line(pts, fill=gold, width=trace_w, joint="curve")
        for px, py in (pts[0], pts[-1]):
            _pad(px, py)

    # ------------------------------------------------------------------
    # Corner mounting holes — white keep-out ring around a dark drill.
    mount_inset = 28
    mount_r = max(5, round(width / 62))
    for mx, my in (
        (mount_inset, mount_inset),
        (width - 1 - mount_inset, mount_inset),
        (mount_inset, height - 1 - mount_inset),
        (width - 1 - mount_inset, height - 1 - mount_inset),
    ):
        draw.ellipse((mx - mount_r, my - mount_r, mx + mount_r, my + mount_r), outline=silk, width=2)
        drill = max(2, mount_r - 4)
        draw.ellipse((mx - drill, my - drill, mx + drill, my + drill), fill=black_ink)

    # ------------------------------------------------------------------
    # Silkscreen designators (white) beside the routed pads.
    label_font = load_font([SPACEMONO_REGULAR, *META_FONT_CANDIDATES], size=max(9, round(width / 72)))
    for text, fx, fy in _CIRCUIT_DESIGNATORS:
        lx = round(fx * width) + pad_r + 3
        ly = round(fy * height) - pad_r - 2
        draw.text((lx, ly), text, font=label_font, fill=silk)

    # ------------------------------------------------------------------
    # Y1 quartz crystal in the bottom-left margin — component outline,
    # two pads, and a label. The literal clock element on the board.
    can_cx = round(0.22 * width)
    can_cy = round(0.92 * height)
    can_hw = max(12, round(width / 40))
    can_hh = max(5, round(height / 64))
    draw.rounded_rectangle(
        (can_cx - can_hw, can_cy - can_hh, can_cx + can_hw, can_cy + can_hh),
        radius=3, outline=silk, width=2,
    )
    _pad(can_cx - can_hw, can_cy + can_hh + 3, r_out=max(3, pad_r - 1))
    _pad(can_cx + can_hw, can_cy + can_hh + 3, r_out=max(3, pad_r - 1))
    draw.text((can_cx + can_hw + 6, can_cy - can_hh), "Y1", font=label_font, fill=silk)

    # Board legend, bottom-right silkscreen.
    legend = "IDLE HOURS · REV 2.0"
    legend_bb = draw.textbbox((0, 0), legend, font=label_font)
    legend_w = legend_bb[2] - legend_bb[0]
    draw.text((width - mount_inset - legend_w, round(0.945 * height)), legend, font=label_font, fill=silk)

    # ------------------------------------------------------------------
    # Body-text knockout — clean forest board + white silkscreen outline.
    if clear_rect is None or page_bg is None:
        return
    cx0, cy0, cx1, cy1 = clear_rect
    cx0 = max(0, cx0)
    cy0 = max(0, cy0)
    cx1 = min(width - 1, cx1)
    cy1 = min(height - 1, cy1)
    if cx1 <= cx0 or cy1 <= cy0:
        return
    # Reset to clean soldermask, wiping anything routed across the body.
    for py in range(cy0, cy1 + 1):
        row_odd = py & 1
        for px in range(cx0, cx1 + 1):
            pixels[px, py] = black_ink if ((px & 1) ^ row_odd) else green_ink
    # Silkscreen "component outline" framing the populated area + pin-1 dot.
    draw.rounded_rectangle((cx0, cy0, cx1, cy1), radius=6, outline=silk, width=1)
    draw.rectangle((cx0 - 1, cy0 - 1, cx0 + 3, cy0 + 3), fill=silk)


def _anna_atkins_fern(draw: ImageDraw.ImageDraw, x0: float, y0: float, length: float,
                      angle: float, scale: float, curl: float, ink) -> None:
    """A single white fern frond: a curving rachis with paired pinnate
    leaflets tapering to the tip, as 1 px line art over the plate."""
    pts = []
    x, y, a = x0, y0, angle
    n = max(4, int(length))
    for i in range(n):
        a += curl
        x += math.cos(a)
        y += math.sin(a)
        pts.append((x, y))
    for i in range(1, len(pts)):
        draw.line((pts[i - 1][0], pts[i - 1][1], pts[i][0], pts[i][1]), fill=ink, width=1)
    # Pinnate leaflets along the rachis.
    for i in range(2, len(pts) - 1, 3):
        px, py = pts[i]
        t = i / len(pts)
        span = max(3.0, (1 - t) * 14.0 * scale)
        # local tangent → perpendicular leaflet direction
        tx, ty = pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]
        plen = math.hypot(tx, ty) or 1.0
        nx, ny = -ty / plen, tx / plen
        lean = 0.5  # leaflets sweep toward the tip
        dx, dy = tx / plen, ty / plen
        for side in (-1, 1):
            ex = px + (nx * side + dx * lean) * span
            ey = py + (ny * side + dy * lean) * span
            draw.line((px, py, ex, ey), fill=ink, width=1)
    # A tiny terminal flourish.
    tipx, tipy = pts[-1]
    draw.ellipse((tipx - 1, tipy - 1, tipx + 1, tipy + 1), fill=ink)


def _anna_atkins_ferns(draw: ImageDraw.ImageDraw, width: int, height: int) -> None:
    """White fern sprigs in the corner margins, clear of the quote. Fixed
    positions so both border-painter passes render identically."""
    ink = SPECTRA6["white"]
    # (x0, y0, length, angle, scale, curl) — anchored in the margins.
    sprigs = [
        (40, 150, 80, -1.35, 0.9, 0.03),     # left edge, reaching up
        (44, 330, 70, -1.7, 0.8, -0.025),    # lower-left
        (width - 44, 360, 78, -1.45, 0.9, -0.03),  # lower-right
        (width - 60, 150, 64, -1.9, 0.75, 0.03),   # upper-right
    ]
    for x0, y0, length, angle, scale, curl in sprigs:
        _anna_atkins_fern(draw, x0, y0, length, angle, scale, curl, ink)


def _anna_atkins_handwrite(image: Image.Image, text: str, cx: int, cy: int,
                           font, angle: float) -> None:
    """Stamp a slightly rotated white handwritten label.

    The rotated mask is pasted as solid white where it is opaque — a binary
    stamp, so antialiased edges can't leave a blue halo after palette snap."""
    tmp = Image.new("L", (1, 1), 0)
    bbox = ImageDraw.Draw(tmp).textbbox((0, 0), text, font=font)
    tw, th = max(1, bbox[2] - bbox[0]), max(1, bbox[3] - bbox[1])
    pad = 6
    mask = Image.new("L", (tw + 2 * pad, th + 2 * pad), 0)
    ImageDraw.Draw(mask).text((pad - bbox[0], pad - bbox[1]), text, font=font, fill=255)
    if angle:
        mask = mask.rotate(angle, expand=True, resample=Image.BICUBIC)
    mw, mh = mask.size
    px0, py0 = cx - mw // 2, cy - mh // 2
    base = image.load()
    mpx = mask.load()
    white = SPECTRA6["white"]
    for my in range(mh):
        ay = py0 + my
        if ay < 0 or ay >= image.height:
            continue
        for mx in range(mw):
            ax = px0 + mx
            if 0 <= ax < image.width and mpx[mx, my] >= 128:
                base[ax, ay] = white


def _anna_atkins_labels(image: Image.Image, draw: ImageDraw.ImageDraw, width: int, height: int) -> None:
    """Handwritten white Latin species labels in copperplate, in the
    margins beside the specimens."""
    font = load_font([PINYONSCRIPT_REGULAR, DANCINGSCRIPT_VARIABLE, *ORNAMENT_FONT_CANDIDATES], size=26)
    # (text, cx, cy, angle) — kept in the corners, clear of the centred panel.
    labels = [
        ("Cystoseira fibrosa", 96, 408, 4),
        ("Ptilota plumosa", width - 96, 96, -5),
        ("Dictyota dichotoma", width - 104, 432, 3),
    ]
    for text, cx, cy, angle in labels:
        _anna_atkins_handwrite(image, text, cx, cy, font, angle)


def draw_anna_atkins_border(image: Image.Image, colors: dict) -> None:
    """Anna Atkins 1843 botanical cyanotype plate (see the THEMES entry).

    Layers, deepest → shallowest:

    * **Layer 0 — dithered cyanotype photogram.** The committed plate
      (``assets/anna_atkins_cyanotype.png``) Floyd–Steinberg-dithered to the
      inks via ``dither_image_to_palette``: deep blues break into a
      blue/black stipple, specimen edges into a blue+white haze. If the asset
      is missing, the flat blue ground is deepened with a blue→black Bayer
      stipple instead.
    * **White fern sprigs** in the corner margins.
    * **Handwritten Latin labels** (Pinyon Script), rotated and stamped
      binary.
    * **Thin white plate rule** at inset 12.

    There is deliberately no body-text knockout: the quote sits directly on
    the photogram, and ``_draw_text_body`` stamps a per-glyph black halo
    under the text for legibility over bright fronds.
    """
    draw = ImageDraw.Draw(image)
    width, height = image.size
    page_bg = colors.get("page_bg")
    pixels = image.load()
    WHITE = SPECTRA6["white"]
    BLACK = SPECTRA6["black"]

    # Layer 0 — dithered photogram (or Prussian-deepened flat ground fallback).
    plate = _load_dithered_plate(ANNA_ATKINS_PLATE, width, height, palette=_CYANOTYPE_PALETTE)
    if plate is not None:
        image.paste(plate, (0, 0))
    elif page_bg is not None:
        for y in range(height):
            row = BAYER_4x4[y & 3]
            for x in range(width):
                if pixels[x, y] == page_bg and row[x & 3] < 6:
                    pixels[x, y] = BLACK

    _anna_atkins_ferns(draw, width, height)
    _anna_atkins_labels(image, draw, width, height)

    draw.rectangle((12, 12, width - 13, height - 13), outline=WHITE, width=1)



# ---------------------------------------------------------------------------
# synoptic — a meteorological surface analysis (issue #215).
#
# The weather chart of the navigation family (``firmament`` celestial atlas,
# ``astrarium`` instrument, ``cartograph`` terrestrial chart): a field laid
# over geography — nested isobars, pressure centres and front symbols.
#
# The occluded front is drawn purple on a real chart because it is a cold
# and a warm front merged, so the R+B 1:1 mix is semantically right here.
#
# The time rides the validity stamp, ``VALID 1630 LT`` — a real chart
# carries its observation time, so a number genuinely belongs.
#
# Shared literary layout plus this painter and a ``clear_rect`` knockout.
# Everything is drawn with ImageDraw primitives that PIL clips, so the
# ``/api/preview`` thumbnail path crops rather than raises.
# ---------------------------------------------------------------------------
# Pressure centres as (x, y, label, innermost radius) in 800x480 space, in
# opposite corners so the isobars sweep diagonally across the page.
_SYNOPTIC_CENTRES = (
    (74, 96, "H", 26),
    (716, 388, "L", 24),
)
_SYNOPTIC_RINGS = 5
_SYNOPTIC_RING_STEP = 26
_SYNOPTIC_BASE_PRESSURE = {"H": 1032, "L": 984}
_SYNOPTIC_ISOBAR_POINTS = 48
# Fronts as (kind, polyline). Kinds: "cold" (blue, triangles), "warm" (red,
# semicircles), "occluded" (purple, alternating). Hand-placed so the three
# sweep across the middle band without crossing the quote cartouche.
_SYNOPTIC_FRONTS = (
    ("cold", ((36, 74), (150, 46), (272, 60), (368, 30))),
    ("warm", ((470, 44), (566, 70), (664, 58), (768, 82))),
    ("occluded", ((44, 430), (170, 452), (300, 436), (410, 458))),
)
_SYNOPTIC_PIP_SPACING = 34
_SYNOPTIC_PIP_SIZE = 7
# Station plots as (x, y, wind barb angle in degrees, number of full barbs).
_SYNOPTIC_STATIONS = (
    (26, 240, 210, 2), (30, 340, 250, 3), (128, 442, 160, 1),
    (610, 118, 300, 2), (770, 210, 20, 3), (556, 452, 120, 1),
    (312, 30, 340, 2), (452, 464, 70, 1),
)
_SYNOPTIC_GRATICULE_STEP = 64


def _synoptic_isobar(cx: float, cy: float, radius: float, squash: float, seed: int) -> list[tuple[float, float]]:
    """One closed isobar as a polyline, gently deformed so it is not an ellipse.

    Two low-order harmonics on the radius make it smooth but irregular with
    no randomness, so the chart stays byte-deterministic.
    """
    points = []
    for i in range(_SYNOPTIC_ISOBAR_POINTS):
        angle = math.tau * i / _SYNOPTIC_ISOBAR_POINTS
        wobble = 1.0 + 0.10 * math.sin(2 * angle + seed) + 0.05 * math.sin(3 * angle - seed)
        r = radius * wobble
        points.append((cx + r * math.cos(angle), cy + r * math.sin(angle) * squash))
    points.append(points[0])
    return points


def _synoptic_paint_graticule(draw: ImageDraw.ImageDraw, width: int, height: int) -> None:
    """Faint dotted lat/long grid — the geography the analysis is drawn over."""
    faint = SPECTRA6["blue"]
    for x in range(_SYNOPTIC_GRATICULE_STEP, width, _SYNOPTIC_GRATICULE_STEP):
        for y in range(0, height, 6):
            draw.point((x, y), fill=faint)
    for y in range(_SYNOPTIC_GRATICULE_STEP, height, _SYNOPTIC_GRATICULE_STEP):
        for x in range(0, width, 6):
            draw.point((x, y), fill=faint)


def _synoptic_paint_isobars(draw: ImageDraw.ImageDraw, width: int, height: int) -> None:
    """Nested pressure contours around each centre, with pressure labels."""
    black = SPECTRA6["black"]
    label_font = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=11)
    centre_font = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=30)
    for index, (cx, cy, label, inner) in enumerate(_SYNOPTIC_CENTRES):
        cx = cx * width / 800.0
        cy = cy * height / 480.0
        step = _SYNOPTIC_BASE_PRESSURE[label]
        for ring in range(_SYNOPTIC_RINGS):
            radius = inner + ring * _SYNOPTIC_RING_STEP
            points = _synoptic_isobar(cx, cy, radius, 0.82, seed=index * 1.7 + ring * 0.4)
            draw.line([(int(px), int(py)) for px, py in points], fill=black, width=1)
            # Pressure figure riding the contour, the way a real chart breaks
            # the line to letter it. Outermost ring only, to avoid a thicket.
            if ring == _SYNOPTIC_RINGS - 1:
                value = step - 4 * ring if label == "H" else step + 4 * ring
                lx, ly = points[_SYNOPTIC_ISOBAR_POINTS // 8]
                draw.text((int(lx), int(ly)), str(value), font=label_font, fill=black, anchor="mm")
        draw.text((int(cx), int(cy)), label, font=centre_font,
                  fill=SPECTRA6["blue"] if label == "H" else SPECTRA6["red"], anchor="mm")


def _synoptic_front_pips(points, spacing):
    """Walk a polyline and yield (x, y, normal angle) every ``spacing`` px.

    Each pip needs the local direction as well as a position, hence the walk
    by arc length rather than over the vertices.
    """
    pips = []
    carry = spacing / 2.0
    for (x0, y0), (x1, y1) in zip(points, points[1:]):
        seg = math.hypot(x1 - x0, y1 - y0)
        if seg < 1e-6:
            continue
        angle = math.atan2(y1 - y0, x1 - x0)
        travelled = carry
        while travelled <= seg:
            t = travelled / seg
            pips.append((x0 + (x1 - x0) * t, y0 + (y1 - y0) * t, angle))
            travelled += spacing
        carry = travelled - seg
    return pips


def _synoptic_paint_front(image, draw, kind, points, width, height):
    """One front: the line, then its symbol furniture.

    Cold gets triangles, warm semicircles, occluded alternates the two. The
    occluded line and pips are painted in an off-palette sentinel and
    bbox-post-passed to R+B purple, because ``ImageDraw`` has no per-pixel
    fill.
    """
    red, blue = SPECTRA6["red"], SPECTRA6["blue"]
    scaled = [(x * width / 800.0, y * height / 480.0) for x, y in points]
    sentinel = (7, 7, 7)
    ink = {"cold": blue, "warm": red, "occluded": sentinel}[kind]
    draw.line([(int(x), int(y)) for x, y in scaled], fill=ink, width=3, joint="curve")

    size = _SYNOPTIC_PIP_SIZE
    for index, (px, py, angle) in enumerate(_synoptic_front_pips(scaled, _SYNOPTIC_PIP_SPACING)):
        if kind == "occluded":
            shape = "triangle" if index % 2 == 0 else "semicircle"
        else:
            shape = "triangle" if kind == "cold" else "semicircle"
        # Normal to the left of travel, the symbol side for these west-to-east
        # fronts.
        nx, ny = math.sin(angle), -math.cos(angle)
        if shape == "triangle":
            tip = (px + nx * size * 1.6, py + ny * size * 1.6)
            back = (math.cos(angle) * size, math.sin(angle) * size)
            draw.polygon([(int(tip[0]), int(tip[1])),
                          (int(px - back[0]), int(py - back[1])),
                          (int(px + back[0]), int(py + back[1]))], fill=ink)
        else:
            box = (int(px - size), int(py - size), int(px + size), int(py + size))
            start = math.degrees(angle) + 180
            draw.pieslice(box, start, start + 180, fill=ink)
    if kind == "occluded":
        _synoptic_resolve_occluded(image, scaled, size)


def _synoptic_resolve_occluded(image, scaled, size) -> None:
    """Flip the occluded front's sentinel ink to the R+B 1:1 purple.

    Scoped to the front's own bounding box so it cannot touch the isobars or
    the graticule, and keyed on the sentinel colour so it is idempotent.
    """
    width, height = image.size
    px = image.load()
    red, blue = SPECTRA6["red"], SPECTRA6["blue"]
    xs = [x for x, _ in scaled]
    ys = [y for _, y in scaled]
    pad = size * 3
    x0 = max(0, int(min(xs) - pad))
    x1 = min(width, int(max(xs) + pad) + 1)
    y0 = max(0, int(min(ys) - pad))
    y1 = min(height, int(max(ys) + pad) + 1)
    for y in range(y0, y1):
        for x in range(x0, x1):
            if px[x, y] == (7, 7, 7):
                px[x, y] = red if (x + y) & 1 else blue


def _synoptic_paint_stations(draw: ImageDraw.ImageDraw, width: int, height: int) -> None:
    """Station model plots — circle plus a wind barb with feathers.

    Instantly legible as "weather chart" even to a reader who cannot decode
    one.
    """
    black = SPECTRA6["black"]
    for sx, sy, bearing, barbs in _SYNOPTIC_STATIONS:
        cx = sx * width / 800.0
        cy = sy * height / 480.0
        draw.ellipse((int(cx - 5), int(cy - 5), int(cx + 5), int(cy + 5)), outline=black, width=2)
        angle = math.radians(bearing)
        shaft = 26
        ex, ey = cx + math.cos(angle) * shaft, cy + math.sin(angle) * shaft
        draw.line((int(cx), int(cy), int(ex), int(ey)), fill=black, width=2)
        # Feathers hang off the far end, perpendicular-ish to the shaft.
        for i in range(barbs):
            t = 1.0 - i * 0.22
            bx, by = cx + math.cos(angle) * shaft * t, cy + math.sin(angle) * shaft * t
            fx = bx + math.cos(angle + 2.2) * 9
            fy = by + math.sin(angle + 2.2) * 9
            draw.line((int(bx), int(by), int(fx), int(fy)), fill=black, width=2)


def _synoptic_paint_stamp(draw: ImageDraw.ImageDraw, width: int, height: int, time_str: str) -> None:
    """``VALID HHMM LT`` — the chart's observation time, and the clock.

    Labelled **LT** (local time), not the UTC a real analysis uses, because
    the clock renders naive local wall time and ``VALID 1230 UTC`` would be a
    false claim. Converting to UTC would make the theme's time carrier
    disagree with the quote; reading the host's zone abbreviation would make
    the frame (and its golden fixture) machine-dependent — the
    ``CLOCK_DEPENDENT_THEMES`` hazard.
    """
    black, red = SPECTRA6["black"], SPECTRA6["red"]
    digits = (time_str or "").replace(":", "")[:4] or "0000"
    font = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=13)
    text = f"VALID {digits} LT"
    box = draw.textbbox((0, 0), text, font=font)
    pad = 6
    w, h = box[2] - box[0], box[3] - box[1]
    x1, y1 = width - 16, height - 14
    x0, y0 = x1 - w - 2 * pad, y1 - h - 2 * pad
    if x0 < 0 or y0 < 0:
        return
    draw.rectangle((x0, y0, x1, y1), fill=SPECTRA6["white"], outline=black, width=1)
    draw.text((x0 + pad - box[0], y0 + pad - box[1]), text, font=font, fill=red)


def draw_synoptic_border(image: Image.Image, colors: dict, clear_rect=None, time_str: str | None = None) -> None:
    """Surface analysis behind the quote (see the section comment above).

    ``time_str`` is optional because the ``_BORDER_PAINTERS`` contract passes
    only ``(image, colors, clear_rect)``: ``render`` calls this painter by name
    with the clock, while the registry path (the button-C source card) gets a
    chart with no validity stamp, which is correct for a source card.
    """
    width, height = image.size
    draw = ImageDraw.Draw(image)
    _synoptic_paint_graticule(draw, width, height)
    _synoptic_paint_isobars(draw, width, height)
    for kind, points in _SYNOPTIC_FRONTS:
        _synoptic_paint_front(image, draw, kind, points, width, height)
    _synoptic_paint_stations(draw, width, height)
    if time_str:
        _synoptic_paint_stamp(draw, width, height, time_str)
    if clear_rect is not None:
        # The quote sits in a chart-legend box.
        x0, y0, x1, y1 = clear_rect
        x0 = max(0, x0)
        y0 = max(0, y0)
        x1 = min(width - 1, x1)
        y1 = min(height - 1, y1)
        if x1 > x0 and y1 > y0:
            draw.rectangle((x0, y0, x1, y1), fill=colors.get("page_bg", SPECTRA6["white"]))
            draw.rectangle((x0, y0, x1, y1), outline=SPECTRA6["black"], width=2)
            draw.line((x0 + 8, y0 + 8, x1 - 8, y0 + 8), fill=SPECTRA6["blue"], width=1)
            draw.line((x0 + 8, y1 - 8, x1 - 8, y1 - 8), fill=SPECTRA6["blue"], width=1)


# ---------------------------------------------------------------------------
# betweenus / betweenus_dark — the *Between Us* app's card UI, light and dark.
#
# Between Us (github.com/gkoch02/BetweenUs) is a two-person checklist app whose
# signature gesture — a serif headline with its operative phrase in italic
# terracotta — is exactly what this clock does with a quote, so the app's
# typographic move is the layout's move and the rest of the frame is the app's
# furniture. Full design notes: docs/themes.md (`betweenus`).
#
# Composition (both variants share ``draw_betweenus_border``):
#
# * **Paper** — the app's paper → paper2 gradient as a sparse wash thresholded
#   on ``position_noise`` (light: yellow on white, ~3% → ~9% toward the foot;
#   dark: red on black ~6% → ~2.5% plus a trace of white). Quote-independent,
#   so it is cached per geometry in a bounded LRU.
# * **The card** — the body knockout, a rounded card (radius 18) with a 1 px
#   ``line`` edge, floated on a soft shadow read off a blurred offset
#   silhouette (dark clears the warm specks instead of casting black). The
#   card interior is flat: a speckled ground under body text is noise on eInk.
# * **Brand row** — "Between *Us*" top-left and a daypart pill top-right.
# * **Progress bar** — filled to the fraction of the day elapsed, gold →
#   tangerine. No digits; the registry path (source card, ``--message``) has no
#   time and draws an empty track. The sleep frame goes through ``render`` with
#   a time, so it carries a real track and pill.
# * **Legend** — the app's five answer tiers along the foot, each mapped onto a
#   documented recipe (see ``_BETWEENUS_LEGEND``).
#
# Fraunces' default axis instance is **Black**, so every candidate pins an
# instance by name. The matched phrase is italic, not bold: solid red in
# light (a stipple would shred italic hairlines), the R+Y 1:1 amber reroute in
# dark. The oversized quote marks are skipped (``_THEMES_WITHOUT_ORNAMENT_MARKS``):
# they paint on the paper outside the card, where a ``page_bg`` glyph would
# punch a hole in the wash.

_BETWEENUS_THEMES: frozenset[str] = frozenset({"betweenus", "betweenus_dark"})
# The app's 16 pt screen inset, scaled to the panel.
_BETWEENUS_MARGIN = 28
# The app's 22 pt card corner radius, scaled to the panel.
_BETWEENUS_CARD_RADIUS = 18
# Brand-row text baseline and the progress track's top edge. The card top is
# never above y=54 (dense body at y≥72, padded by 18), so the track fits at
# 44..48 and the app's count row is folded into the pill.
_BETWEENUS_BRAND_BASELINE = 34
_BETWEENUS_BAR_TOP = 44
_BETWEENUS_BAR_HEIGHT = 5
# Where the legend's dot centres sit, measured up from the foot.
_BETWEENUS_LEGEND_RISE = 24
# Drop-shadow geometry: the card silhouette offset down-right, blurred and
# read back as a density. Peak stays well below solid so the shadow keeps
# stipple texture rather than reading as a black bar.
_BETWEENUS_SHADOW_OFFSET = (3, 4)
_BETWEENUS_SHADOW_BLUR = 5
_BETWEENUS_SHADOW_PEAK = 0.45
# Off-palette sentinels for shapes that take a two-ink recipe in a post-pass.
_BETWEENUS_SENTINEL_LINE = (7, 7, 7)
_BETWEENUS_SENTINEL_TRACK = (8, 8, 8)
_BETWEENUS_SENTINEL_FILL = (9, 9, 9)
_BETWEENUS_SENTINEL_DOTS = tuple((10 + i, 10 + i, 10 + i) for i in range(5))

# The five answer tiers. Each recipe is ``(ink_a, ink_b, share_b)``: paint
# ``ink_b`` where the 8x8 Bayer rank is below ``share_b * 64``, ``ink_a``
# elsewhere; ``share_b == 0`` is a solid fill. Light column = the app's light
# tints, dark column = its lightened dark tints.
#
# ``Hard No`` is the app's ``limit`` (issue #257). It is named "slate green"
# but measures #5D6B66, a dark cool *neutral*; solid green reads as plainly
# green, and the nearest mix (K+W gray) is what ``Neutral`` already paints. So
# it takes the achromatic extreme — black on light, white on dark — and stone
# keeps the middle.
_BETWEENUS_LEGEND: tuple[tuple[str, tuple, tuple], ...] = (
    ("Love it", ("red", None, 0.0), ("red", "white", 0.5)),          # deep terracotta → salmon
    ("Like it", ("red", "yellow", 0.375), ("red", "yellow", 0.5)),   # warm terracotta → apricot
    ("Neutral", ("black", "white", 0.5), ("black", "white", 0.5)),   # stone
    ("Curious", ("yellow", "red", 0.375), ("yellow", "white", 0.5)), # ochre → pale gold
    ("Hard No", ("black", None, 0.0), ("white", None, 0.0)),         # slate → ink / bone
)

_BETWEENUS_DAYPART_LABELS = {
    "midnight": "Midnight",
    "night": "Night",
    "dawn": "Dawn",
    "morning": "Morning",
    "noon": "Noon",
    "afternoon": "Afternoon",
    "dusk": "Dusk",
    "evening": "Evening",
}

# The paper wash is cached per canvas geometry, which is caller-controlled
# via the ungated ``/api/preview`` (~1.1 MB per distinct size), so the cache
# is a small LRU: enough for the native panel plus the curator thumbnails.
_BETWEENUS_PAPER_CACHE: "collections.OrderedDict[tuple[int, int, bool], Image.Image]" = collections.OrderedDict()
_BETWEENUS_PAPER_CACHE_MAX = 4


def _betweenus_is_dark(colors: dict) -> bool:
    return colors.get("page_bg") == SPECTRA6["black"]


def position_noise(x: int, y: int) -> int:
    """A 0..255 positional hash — white noise, deterministic per pixel.

    A sparse wash thresholds this rather than a Bayer rank: at 3-9% density an
    ordered tile lays a visible dot lattice, where a hash scatter reads as
    paper fibre. (``bakelite``'s "hash reads as sandpaper" warning is about
    mid-density fields.) For a whole-canvas field use :func:`_white_noise`,
    the C-speed equivalent.
    """
    h = (x * 374761393 + y * 668265263) & 0xFFFFFFFF
    h = ((h ^ (h >> 13)) * 1274126177) & 0xFFFFFFFF
    return (h ^ (h >> 16)) & 0xFF


def _betweenus_paper(width: int, height: int, dark: bool) -> Image.Image:
    """The gradient paper wash, built once per canvas geometry and cached."""
    key = (width, height, dark)
    cached = _BETWEENUS_PAPER_CACHE.get(key)
    if cached is not None:
        _BETWEENUS_PAPER_CACHE.move_to_end(key)
        return cached.copy()
    white = SPECTRA6["white"]
    black = SPECTRA6["black"]
    red = SPECTRA6["red"]
    yellow = SPECTRA6["yellow"]
    paper = Image.new("RGB", (width, height), black if dark else white)
    px = paper.load()
    span = max(1, height - 1)
    noise = position_noise
    for y in range(height):
        t = y / span
        if dark:
            # Warm at the head, settling toward black at the foot. The white
            # trace uses the opposite end of the noise range so the two specks
            # never coincide.
            red_cut = (0.06 - 0.035 * t) * 256
            white_cut = 256 - (0.012 - 0.008 * t) * 256
            for x in range(width):
                n = noise(x, y)
                if n < red_cut:
                    px[x, y] = red
                elif n >= white_cut:
                    px[x, y] = white
        else:
            # Cream that warms toward the foot.
            cut = (0.03 + 0.06 * t) * 256
            for x in range(width):
                if noise(x, y) < cut:
                    px[x, y] = yellow
    _BETWEENUS_PAPER_CACHE[key] = paper
    while len(_BETWEENUS_PAPER_CACHE) > _BETWEENUS_PAPER_CACHE_MAX:
        _BETWEENUS_PAPER_CACHE.popitem(last=False)
    return paper.copy()


def _betweenus_clamp_rect(rect, width: int, height: int):
    x0, y0, x1, y1 = rect
    x0 = max(0, int(x0))
    y0 = max(0, int(y0))
    x1 = min(width - 1, int(x1))
    y1 = min(height - 1, int(y1))
    if x1 <= x0 or y1 <= y0:
        return None
    return (x0, y0, x1, y1)


def _betweenus_post_pass(image: Image.Image, bbox, sentinel, recipe) -> None:
    """Replace every ``sentinel`` pixel inside ``bbox`` with the two-ink
    ``recipe`` on the 8x8 Bayer tile (a 50% share is exactly a checkerboard)."""
    rect = _betweenus_clamp_rect(bbox, *image.size)
    if rect is None:
        return
    x0, y0, x1, y1 = rect
    ink_a = SPECTRA6[recipe[0]]
    ink_b = SPECTRA6[recipe[1]] if recipe[1] else None
    cut = round(recipe[2] * 64)
    px = image.load()
    for y in range(y0, y1 + 1):
        row = BAYER_8x8[y & 7]
        for x in range(x0, x1 + 1):
            if px[x, y] == sentinel:
                px[x, y] = ink_b if (ink_b is not None and row[x & 7] < cut) else ink_a


def _betweenus_line_outline(image: Image.Image, draw, rect, radius: int, dark: bool) -> None:
    """A 1 px rounded outline in the app's ``line`` token: R+G parity sepia on
    the light paper; on black the red half of that vanishes and the line
    reads as green, so dark uses a 3/8 white hairline — the faint warm-grey
    edge the app's dark ``line`` (#453C31) is."""
    draw.rounded_rectangle(rect, radius=radius, outline=_BETWEENUS_SENTINEL_LINE, width=1)
    recipe = ("black", "white", 0.375) if dark else ("red", "green", 0.5)
    _betweenus_post_pass(image, rect, _BETWEENUS_SENTINEL_LINE, recipe)


def _betweenus_paint_shadow(image: Image.Image, rect, dark: bool) -> None:
    """The card's soft drop shadow: a blurred, offset silhouette read back as a
    Bayer density. Light paints black at that density onto the paper; dark
    clears the paper's warm specks at it, so the halo of clean black *is* the
    shadow. Pixels the card will cover are skipped — the fill lands on top."""
    width, height = image.size
    x0, y0, x1, y1 = rect
    ox, oy = _BETWEENUS_SHADOW_OFFSET
    reach = _BETWEENUS_SHADOW_BLUR * 2 + max(ox, oy) + 2
    band = _betweenus_clamp_rect((x0 - reach, y0 - reach, x1 + reach, y1 + reach), width, height)
    if band is None:
        return
    bx0, by0, bx1, by1 = band
    mw, mh = bx1 - bx0 + 1, by1 - by0 + 1
    mask = Image.new("L", (mw, mh), 0)
    ImageDraw.Draw(mask).rounded_rectangle(
        (x0 + ox - bx0, y0 + oy - by0, x1 + ox - bx0, y1 + oy - by0),
        radius=_BETWEENUS_CARD_RADIUS,
        fill=255,
    )
    mask = mask.filter(ImageFilter.GaussianBlur(_BETWEENUS_SHADOW_BLUR))
    mp = mask.load()
    px = image.load()
    black = SPECTRA6["black"]
    r = _BETWEENUS_CARD_RADIUS
    for y in range(by0, by1 + 1):
        row = BAYER_8x8[y & 7]
        mid_row = y0 + r <= y <= y1 - r
        for x in range(bx0, bx1 + 1):
            # Fully under the card (its rectangle minus the corner cut-outs).
            if x0 <= x <= x1 and (mid_row or (x0 + r <= x <= x1 - r and y0 <= y <= y1)):
                continue
            s = mp[x - bx0, y - by0] / 255.0
            if not s:
                continue
            if dark:
                # Clear the warm specks outright where the silhouette is at
                # least half-strong, then ramp the clearing out through the
                # blur's tail.
                if px[x, y] != black and (s >= 0.5 or row[x & 7] < s * 2 * 64):
                    px[x, y] = black
            elif row[x & 7] < s * _BETWEENUS_SHADOW_PEAK * 64:
                px[x, y] = black


def _betweenus_paint_card(image: Image.Image, draw, colors: dict, rect, dark: bool) -> None:
    """Knock the body region out to a clean rounded card with the app's line
    edge, floated on the shadow."""
    _betweenus_paint_shadow(image, rect, dark)
    draw.rounded_rectangle(rect, radius=_BETWEENUS_CARD_RADIUS, fill=colors["page_bg"])
    _betweenus_line_outline(image, draw, rect, _BETWEENUS_CARD_RADIUS, dark)


def _betweenus_daypart_label(time_str: str | None) -> str | None:
    if not time_str:
        return None
    try:
        hour = int(time_str.split(":")[0])
    except (ValueError, IndexError):
        return None
    return _BETWEENUS_DAYPART_LABELS.get(daypart_for_hour(hour) or "")


def _betweenus_day_fraction(time_str: str | None) -> float:
    """Fraction of the day elapsed at ``time_str`` (0 at midnight), or 0."""
    if not time_str:
        return 0.0
    try:
        hour_text, minute_text = time_str.split(":")[:2]
        minutes = int(hour_text) * 60 + int(minute_text)
    except ValueError:
        return 0.0
    return max(0.0, min(1.0, minutes / 1440.0))


def _betweenus_paint_brand_row(image: Image.Image, draw, colors: dict, dark: bool, label: str | None) -> None:
    """"Between *Us*" top-left; the daypart capsule top-right."""
    width, _ = image.size
    ink = colors["text"]
    baseline = _BETWEENUS_BRAND_BASELINE
    word_font = load_font([(FRAUNCES_VARIABLE, "SemiBold"), *QUOTE_FONT_BOLD_CANDIDATES], size=21)
    us_font = load_font([(FRAUNCES_ITALIC_VARIABLE, "Italic"), *QUOTE_FONT_SEMIBOLD_CANDIDATES], size=21)
    x = _BETWEENUS_MARGIN
    draw.text((x, baseline), "Between ", font=word_font, fill=ink, anchor="ls")
    x += draw.textlength("Between ", font=word_font)
    draw.text((x, baseline), "Us", font=us_font, fill=ink, anchor="ls")
    if not label:
        return
    pill_font = load_font([(INTER_VARIABLE, "Medium"), *META_FONT_CANDIDATES], size=13)
    text_w = draw.textlength(label, font=pill_font)
    pill_h = 24
    pill_w = int(text_w) + 26
    px1 = width - _BETWEENUS_MARGIN
    px0 = px1 - pill_w
    py0 = baseline - 20
    py1 = py0 + pill_h
    if px0 <= x + 12 or py1 <= py0:
        return
    draw.rounded_rectangle((px0, py0, px1, py1), radius=pill_h // 2, fill=colors["page_bg"])
    _betweenus_line_outline(image, draw, (px0, py0, px1, py1), pill_h // 2, dark)
    draw.text(((px0 + px1) / 2, (py0 + py1) / 2 + 1), label, font=pill_font, fill=ink, anchor="mm")


def _betweenus_paint_progress(image: Image.Image, draw, dark: bool, fraction: float) -> None:
    """The app's progress track under the brand row, filled to the fraction of
    the day elapsed with the ``curious → want`` gradient (gold → tangerine)."""
    width, height = image.size
    x0 = _BETWEENUS_MARGIN
    x1 = width - _BETWEENUS_MARGIN
    y0 = _BETWEENUS_BAR_TOP
    y1 = y0 + _BETWEENUS_BAR_HEIGHT - 1
    if x1 - x0 < 12 or y1 >= height:
        return
    draw.rounded_rectangle((x0, y0, x1, y1), radius=2, fill=_BETWEENUS_SENTINEL_TRACK)
    # Track: a faint grey — 25% black on the light paper, 12.5% white on dark.
    _betweenus_post_pass(
        image, (x0, y0, x1, y1), _BETWEENUS_SENTINEL_TRACK,
        ("black", "white", 0.125) if dark else ("white", "black", 0.25),
    )
    if fraction <= 0:
        return
    fx1 = max(x0 + 5, x0 + round((x1 - x0) * fraction))
    draw.rounded_rectangle((x0, y0, fx1, y1), radius=2, fill=_BETWEENUS_SENTINEL_FILL)
    px = image.load()
    red = SPECTRA6["red"]
    yellow = SPECTRA6["yellow"]
    # Yellow share falls along the fill: Y-major gold at the left end, R-major
    # tangerine at the leading edge. Dark lifts both ends toward apricot.
    left_share, right_share = (0.62, 0.48) if dark else (0.55, 0.30)
    span = max(1, fx1 - x0)
    for y in range(y0, y1 + 1):
        row = BAYER_8x8[y & 7]
        for x in range(x0, fx1 + 1):
            if px[x, y] != _BETWEENUS_SENTINEL_FILL:
                continue
            share = left_share + (right_share - left_share) * ((x - x0) / span)
            px[x, y] = yellow if row[x & 7] < share * 64 else red


def _betweenus_paint_legend(image: Image.Image, draw, colors: dict, dark: bool) -> None:
    """The five answer tiers along the foot, dot + label each."""
    width, height = image.size
    font = load_font([(INTER_VARIABLE, "SemiBold"), *META_FONT_BOLD_CANDIDATES], size=13)
    radius = 4
    dot_gap = 7
    item_gap = 22
    items = []
    for label, light_recipe, dark_recipe in _BETWEENUS_LEGEND:
        items.append((label, dark_recipe if dark else light_recipe, draw.textlength(label, font=font)))
    total = sum(2 * radius + dot_gap + w for _, _, w in items) + item_gap * (len(items) - 1)
    if total > width - 2 * _BETWEENUS_MARGIN:
        return
    cy = height - _BETWEENUS_LEGEND_RISE
    if cy - radius < 0:
        return
    x = (width - total) / 2
    for index, (label, recipe, text_w) in enumerate(items):
        sentinel = _BETWEENUS_SENTINEL_DOTS[index]
        dot = (x, cy - radius, x + 2 * radius, cy + radius)
        draw.ellipse(dot, fill=sentinel)
        _betweenus_post_pass(image, dot, sentinel, recipe)
        draw.text((x + 2 * radius + dot_gap, cy), label, font=font, fill=colors["text"], anchor="lm")
        x += 2 * radius + dot_gap + text_w + item_gap


def draw_betweenus_border(image: Image.Image, colors: dict, clear_rect=None, time_str: str | None = None) -> None:
    """Paint the Between Us page: paper, card, brand row, progress, legend.

    Repaints the whole canvas from the cached paper first, so the two calls
    ``render`` makes (registry, then by name with ``clear_rect`` and
    ``time_str``) compose identically. ``time_str`` is optional for the same
    reason as in ``draw_synoptic_border``.
    """
    width, height = image.size
    dark = _betweenus_is_dark(colors)
    image.paste(_betweenus_paper(width, height, dark))
    draw = ImageDraw.Draw(image)
    card = _betweenus_clamp_rect(clear_rect, width, height) if clear_rect is not None else None
    if card is not None and card[2] - card[0] > 2 * _BETWEENUS_CARD_RADIUS and card[3] - card[1] > 2 * _BETWEENUS_CARD_RADIUS:
        _betweenus_paint_card(image, draw, colors, card, dark)
    _betweenus_paint_brand_row(image, draw, colors, dark, _betweenus_daypart_label(time_str))
    _betweenus_paint_progress(image, draw, dark, _betweenus_day_fraction(time_str))
    _betweenus_paint_legend(image, draw, colors, dark)


