# Themes whose matched-phrase face has a silhouette that breaks if its
# inter-word gaps are inflated by justification: these keep the
# matched-phrase spaces *rigid* (the bold face's natural width) and only the
# body's gaps absorb slack. Stretched, Eagle Lake's ``grimoire`` phrase reads
# as disconnected syllables and ``gothic``'s blackletter as separate clauses.
_THEMES_RIGID_MATCH_SPACING: frozenset[str] = frozenset({"grimoire", "gothic"})

# Themes whose body text is set ragged-right instead of justified. A
# typewriter, a terminal and a hand never justified a line: a monospace
# face stretched across elastic spaces reads as a column-alignment bug,
# matched phrase, quote marks and attribution are unaffected -- only the
# slack distribution on non-last body lines.
_THEMES_RAGGED_RIGHT: frozenset[str] = frozenset({
    "nightvision",   # Space Mono terminal readout
    "circuit",       # Space Mono silkscreen
    "dispatch",      # Special Elite typewriter
    "marker",        # Permanent Marker hand lettering
    "chalkboard",    # Playwrite cursive on slate
    "placard",       # Patrick Hand SC hand-printed sign
    "kanagawa",      # Yuji Boku sumi brush
})

# Full justification only when it will not open rivers: the line must be at
# least 75% full, carry at least ``_JUSTIFY_MIN_GAPS`` gaps, and stretch each
# gap by under ``_JUSTIFY_MAX_STRETCH_EM`` of the body size. The 75% rule
# alone bounds the slack but not how few gaps it lands on (a three-word hero
# line could take 75 px per gap).
_JUSTIFY_MIN_GAPS = 3
_JUSTIFY_MAX_STRETCH_EM = 0.45


def justify_flags(theme: str, metrics: list[tuple[int, int]], wrap_width: int, font_size: int) -> list[bool]:
    """Decide, per wrapped body line, whether it is fully justified.

    ``metrics`` holds ``(ink_width, gap_count)`` for every line in order;
    ``wrap_width`` is the measure the lines were wrapped to and
    ``font_size`` the body size in pixels. The last line is never
    justified, nor is any line in a ``_THEMES_RAGGED_RIGHT`` theme, nor a
    line less than 75% full (that line alone stays ragged). The remaining
    lines are decided **as a block**: if any one has fewer than
    ``_JUSTIFY_MIN_GAPS`` gaps or would stretch each gap past
    ``_JUSTIFY_MAX_STRETCH_EM`` of the body size, the whole block is ragged,
    since a half-justified paragraph reads as a mistake.
    """
    flags = [False] * len(metrics)
    if theme in _THEMES_RAGGED_RIGHT or len(metrics) < 2:
        return flags
    eligible: list[int] = []
    for index, (ink_width, gap_count) in enumerate(metrics[:-1]):
        slack = wrap_width - ink_width
        if not (0 < slack <= wrap_width * 0.25):
            continue
        if gap_count < _JUSTIFY_MIN_GAPS or slack / gap_count > font_size * _JUSTIFY_MAX_STRETCH_EM:
            return flags
        eligible.append(index)
    for index in eligible:
        flags[index] = True
    return flags


# Per-theme synthesised "faux bold" for the matched phrase: Pillow's
# ``stroke_width=N`` thickens each glyph by ~N px per side, for faces that
# ship a single weight. ``glacier``: Iceland ships only Regular, and its teal
# accent is too close in hue to the blue body to carry the difference alone.
#
# The value must be threaded through measurement (``wrap_styled_text`` /
# ``render``'s width loops) and drawing (``_draw_text_body``) in lock-step, or
# lines overrun ``max_width`` / gaps don't match the painted silhouette.
_BOLD_STROKE_BY_THEME: dict[str, int] = {"glacier": 1}


def _bold_stroke_for_theme(theme: str) -> int:
    """Return the per-theme matched-phrase faux-bold stroke width."""
    return _BOLD_STROKE_BY_THEME.get(theme, 0)


def _justify_distribution(space_is_bold: list[bool], slack: int, rigid_match: bool) -> list[int]:
    """Return the per-space slack contribution for a justified line.

    ``space_is_bold`` lists the line's inter-word spaces in visual order,
    each flagged if it sits inside the matched phrase; ``slack`` is the pixel
    width to redistribute. With ``rigid_match``, matched-phrase spaces get 0
    and the slack splits across the body gaps only; otherwise every space is
    equally elastic. The result is parallel to ``space_is_bold``.

    Returns an empty list when no space is elastic; the caller then falls
    through to ragged-right.
    """
    elastic_count = sum(1 for is_bold in space_is_bold if not (rigid_match and is_bold))
    if elastic_count == 0:
        return []
    base = slack // elastic_count
    remainder = slack - base * elastic_count
    distribute: list[int] = []
    elastic_seen = 0
    for is_bold in space_is_bold:
        if rigid_match and is_bold:
            distribute.append(0)
        else:
            distribute.append(base + (1 if elastic_seen < remainder else 0))
            elastic_seen += 1
    return distribute


def snap_image_to_palette(image: Image.Image, palette: list[tuple[int, int, int]]) -> Image.Image:
    snapped = Image.new("RGB", image.size)
    src = image.load()
    dst = snapped.load()
    # Frames carry only a handful of distinct colours, so memoise the
    # nearest-colour lookup per source pixel. Byte-identical output.
    cache: dict = {}
    for y in range(image.height):
        for x in range(image.width):
            pixel = src[x, y]
            nearest = cache.get(pixel)
            if nearest is None:
                nearest = min(
                    palette,
                    key=lambda c: (pixel[0] - c[0]) ** 2 + (pixel[1] - c[1]) ** 2 + (pixel[2] - c[2]) ** 2,
                )
                cache[pixel] = nearest
            dst[x, y] = nearest
    return snapped


# ---------------------------------------------------------------------------
# Render-time image dithering to the Spectra-6 palette.
#
# A committed continuous-tone PNG dithered down to the inks at render time,
# for photographic tonal fidelity. Any theme can drop a plate into
# ``assets/`` and route it through ``dither_image_to_palette``.
ANNA_ATKINS_PLATE = BASE_DIR / "assets" / "anna_atkins_cyanotype.png"
# The cyanotype dithers against only white, black and blue: error diffusion
# over all six inks scatters stray red/green specks into the deep blues. A
# strict subset of SPECTRA6, so the final ``snap_image_to_palette`` is a no-op.
_CYANOTYPE_PALETTE = [SPECTRA6["white"], SPECTRA6["black"], SPECTRA6["blue"]]

# Grimdark's gunmetal plate is greyscale, so it dithers to white+black only,
# keeping chroma out of the void.
GRIMDARK_PLATE = BASE_DIR / "assets" / "grimdark_gunmetal.png"
# control: board-formed concrete for the plinth, dithered to white+black at
# render time (scripts/generate_control_plate.py). 800x88, the plinth band.
CONTROL_PLATE = BASE_DIR / "assets" / "control_concrete.png"
_GUNMETAL_PALETTE = [SPECTRA6["white"], SPECTRA6["black"]]
# The concrete plate dithers to the same K+W pair as the gunmetal: one constant,
# so the two achromatic plates cannot drift apart.
_CONCRETE_PALETTE = _GUNMETAL_PALETTE

# The letter plate dithers to white/yellow/red/green (W+Y cream, R+G foxing).
# Black is excluded so error diffusion can't fleck clean paper (the creases
# and seal supply their own), and blue so foxing can't drift cool.
LETTER_PLATE = BASE_DIR / "assets" / "letter_aged_paper.png"
_AGED_PAPER_PALETTE = [SPECTRA6["white"], SPECTRA6["yellow"], SPECTRA6["red"], SPECTRA6["green"]]
# The daguerreotype landscape (scripts/generate_daguerreotype_plate.py) dithers
# against white+black ONLY, with Atkinson diffusion — the plate is the silver
# image itself, and any chroma belongs to the case (brass mat, sepia tarnish),
# painted as primitives on top.
DAGUERREOTYPE_PLATE = BASE_DIR / "assets" / "daguerreotype_plate.png"
_SILVER_PALETTE = [SPECTRA6["white"], SPECTRA6["black"]]

# The autochrome garden is dithered against the FULL six-ink palette — the
# chroma is the ground, standing in for the process's dyed starch grains (see
# the ``autochrome`` section). The default palette would do the same; the
# constant makes it read as a decision rather than an omission.
AUTOCHROME_PLATE = BASE_DIR / "assets" / "autochrome_garden.png"
_AUTOCHROME_PALETTE = SPECTRA6_PALETTE

# Separated Tarot de Marseille trumps (Jean Dodal, Lyon, 1701-1715), one
# 220x290 tile per hour on a 3x4 sheet (scripts/ingest_tarot_plates.py). Unlike
# the plates above this is NOT dithered at render time: a woodcut is line and
# flat colour, so the ingest separates it to white/black/red once. Absent, the
# polygon painters still draw every hour.
TAROT_PLATES = BASE_DIR / "assets" / "tarot_plates.png"
_TAROT_PLATE_COLS, _TAROT_PLATE_ROWS = 3, 4
_TAROT_PLATE_CACHE: dict = {}

# Dithered results are deterministic per (source, size, method) and re-used
# across the 144-frame contact sheet and the golden suite, so memoise them.
_DITHER_CACHE: dict = {}


def dither_image_to_palette(
    image: Image.Image,
    palette: list[tuple[int, int, int]],
    method: str = "floyd-steinberg",
) -> Image.Image:
    """Quantise a continuous-tone RGB image to ``palette`` with dithering,
    so gradients survive as a stipple the eye averages back into the tone.

    ``method``:

    * ``"floyd-steinberg"`` (default) — Pillow's C-speed ``Image.quantize``
      error diffusion: the soft organic stipple photographic plates want.
    * ``"ordered"`` — a deterministic 4×4 Bayer dither: a stable, tileable
      cross-hatch instead of content-dependent noise.
    * ``"atkinson"`` — Atkinson diffusion, which passes on only 6/8 of the
      error and *discards* the rest, so highlights blow toward paper and
      shadows crush toward ink: the high-key look of a daguerreotype (and
      what that theme's mechanism test measures). Pure Python, so reserve it
      for plates memoised through ``_load_dithered_plate``.

    Output is pure on-palette RGB, so a later ``snap_image_to_palette`` is a
    no-op on these pixels.
    """
    if not palette:
        raise ValueError("palette must contain at least one colour")
    src = image.convert("RGB")
    if method == "floyd-steinberg":
        pal_img = Image.new("P", (1, 1))
        flat: list[int] = []
        for colour in palette:
            flat.extend(colour)
        # Pad the 256-entry palette with the first ink, so quantize only maps
        # to colours in ``palette`` (0,0,0 padding would inject black).
        while len(flat) < 768:
            flat.extend(palette[0])
        pal_img.putpalette(flat[:768])
        quantised = src.quantize(palette=pal_img, dither=Image.Dither.FLOYDSTEINBERG)
        return quantised.convert("RGB")
    if method == "ordered":
        out = Image.new("RGB", src.size)
        sp = src.load()
        op = out.load()
        # Bayer cell values 0..15 → a signed bias in roughly [-0.5, +0.5] of an
        # ink step, scaled to 8-bit. ``amp`` controls the dither strength.
        amp = 64
        cache: dict = {}
        w, h = src.size
        for y in range(h):
            brow = BAYER_4x4[y & 3]
            for x in range(w):
                bias = (brow[x & 3] / 15.0 - 0.5) * amp
                r, g, b = sp[x, y]
                key = (int(r + bias), int(g + bias), int(b + bias))
                nearest = cache.get(key)
                if nearest is None:
                    pr, pg, pb = key
                    nearest = min(
                        palette,
                        key=lambda c, pr=pr, pg=pg, pb=pb: (pr - c[0]) ** 2 + (pg - c[1]) ** 2 + (pb - c[2]) ** 2,
                    )
                    cache[key] = nearest
                op[x, y] = nearest
        return out
    if method == "atkinson":
        out = Image.new("RGB", src.size)
        sp = src.load()
        op = out.load()
        w, h = src.size
        # Three rolling error rows (y, y+1, y+2) — Atkinson's kernel reaches
        # two rows down, one further than Floyd-Steinberg's.
        cur = [[0.0, 0.0, 0.0] for _ in range(w)]
        nxt = [[0.0, 0.0, 0.0] for _ in range(w)]
        after = [[0.0, 0.0, 0.0] for _ in range(w)]
        for y in range(h):
            for x in range(w):
                r, g, b = sp[x, y]
                err = cur[x]
                vr, vg, vb = r + err[0], g + err[1], b + err[2]
                nearest = min(
                    palette,
                    key=lambda c: (vr - c[0]) ** 2 + (vg - c[1]) ** 2 + (vb - c[2]) ** 2,
                )
                op[x, y] = nearest
                # An eighth to each of six neighbours; the remaining quarter is
                # dropped on purpose — that loss IS the Atkinson look.
                er = (vr - nearest[0]) / 8.0
                eg = (vg - nearest[1]) / 8.0
                eb = (vb - nearest[2]) / 8.0
                for tx, row in ((x + 1, cur), (x + 2, cur), (x - 1, nxt),
                                (x, nxt), (x + 1, nxt), (x, after)):
                    if 0 <= tx < w:
                        cell = row[tx]
                        cell[0] += er
                        cell[1] += eg
                        cell[2] += eb
            cur, nxt, after = nxt, after, cur
            for cell in after:
                cell[0] = cell[1] = cell[2] = 0.0
        return out
    raise ValueError(f"unknown dither method: {method!r}")


def _load_dithered_plate(path: Path, width: int, height: int, method: str = "floyd-steinberg",
                         palette: list[tuple[int, int, int]] | None = None) -> Image.Image | None:
    """Open a committed plate PNG, resize it, and dither it to ``palette``
    (default the full Spectra-6 set), memoised. Returns ``None`` if the asset
    is missing or unreadable, so a stripped install degrades to a plain
    ground."""
    pal = palette if palette is not None else SPECTRA6_PALETTE
    key = (str(path), width, height, method, tuple(pal))
    cached = _DITHER_CACHE.get(key)
    if cached is not None:
        return cached
    try:
        with Image.open(path) as raw:
            resized = raw.convert("RGB").resize((width, height), Image.LANCZOS)
    except (OSError, ValueError):
        return None
    dithered = dither_image_to_palette(resized, pal, method=method)
    _DITHER_CACHE[key] = dithered
    return dithered


def debug_quote_id(quote_row: dict) -> str | None:
    source_id = quote_row.get("source_id")
    source_path = quote_row.get("source_path") or ""
    line_number = quote_row.get("line_number")

    parts = []
    if source_id:
        parts.append(str(source_id))
    elif source_path:
        parts.append(Path(source_path).stem)

    if line_number is not None:
        parts.append(f"L{line_number}")

    if not parts and source_path:
        return Path(source_path).name
    return ":".join(parts) if parts else None


def fallback_title(quote_row: dict) -> str | None:
    source_id = quote_row.get("source_id")
    if source_id:
        return f"Project Gutenberg #{source_id}"
    source_path = quote_row.get("source_path")
    if source_path:
        return Path(source_path).stem
    return None


def render_source_card(quote_row: dict, width: int, height: int, theme: str = "default") -> Image.Image:
    """Render a centered metadata card for the current quote.

    Shown for a few seconds by the Inky button-C handler, then the loop
    repaints the frame. Reuses the theme palette and fonts.
    """
    colors = THEMES[theme]
    image = Image.new("RGB", (width, height), color=colors["page_bg"])
    _paint_theme_border(image, theme, colors)
    draw = ImageDraw.Draw(image)

    title_text = (quote_row.get("title") or fallback_title(quote_row) or "Unknown source").strip()
    author_text = (quote_row.get("author") or "").strip()
    source_id = quote_row.get("source_id")
    source_id_text = f"Project Gutenberg #{source_id}" if source_id else ""
    matched_text = (quote_row.get("matched_text") or "").strip()
    matched_text = normalize_dashes(strip_underscore_emphasis(matched_text))

    label_font = load_font(META_FONT_CANDIDATES, size=18)
    # ``card_quote_bold`` falls through to ``quote_bold`` unless a theme
    # overrides it: a seam for a theme whose bold face is ASCII-only to route
    # the card's title and phrase through a unicode-safe face.
    title_font = load_font(theme_font_candidates(theme, "card_quote_bold"), size=44)
    author_font = load_font(theme_font_candidates(theme, "quote_regular"), size=28)
    id_font = load_font(META_FONT_CANDIDATES, size=18)
    phrase_font = load_font(theme_font_candidates(theme, "card_quote_bold"), size=28)

    max_text_width = width - 2 * SIDE_MARGIN - 40
    title_lines = wrap_text(draw, title_text, title_font, max_text_width)[:3]
    author_lines = wrap_text(draw, f"by {author_text}", author_font, max_text_width)[:1] if author_text else []
    phrase_lines = wrap_text(draw, f"\u201c{matched_text}\u201d", phrase_font, max_text_width)[:2] if matched_text else []

    label_text = "Now showing"
    label_bbox = draw.textbbox((0, 0), label_text, font=label_font)
    label_h = label_bbox[3] - label_bbox[1]

    title_h = sum((draw.textbbox((0, 0), line, font=title_font)[3] - draw.textbbox((0, 0), line, font=title_font)[1]) + 6 for line in title_lines)
    author_h = sum((draw.textbbox((0, 0), line, font=author_font)[3] - draw.textbbox((0, 0), line, font=author_font)[1]) + 4 for line in author_lines)
    phrase_h = sum((draw.textbbox((0, 0), line, font=phrase_font)[3] - draw.textbbox((0, 0), line, font=phrase_font)[1]) + 4 for line in phrase_lines)
    id_bbox = draw.textbbox((0, 0), source_id_text, font=id_font) if source_id_text else (0, 0, 0, 0)
    id_h = (id_bbox[3] - id_bbox[1]) if source_id_text else 0

    block_h = label_h + 18 + title_h + (12 + author_h if author_lines else 0) + (24 + phrase_h if phrase_lines else 0) + (20 + id_h if source_id_text else 0)
    y = max(40, (height - block_h) // 2)

    def _draw_centered(text: str, font, fill):
        nonlocal y
        bbox = draw.textbbox((0, 0), text, font=font)
        w = bbox[2] - bbox[0]
        h = bbox[3] - bbox[1]
        _draw_text_body(image, draw, ((width - w) // 2, y), text, font=font, fill=fill, theme=theme)
        y += h

    _draw_centered(label_text, label_font, colors["accent"])
    y += 18
    for line in title_lines:
        _draw_centered(line, title_font, colors["text"])
        y += 6
    if author_lines:
        y += 6
        for line in author_lines:
            _draw_centered(line, author_font, colors["text"])
            y += 4
    if phrase_lines:
        y += 18
        for line in phrase_lines:
            _draw_centered(line, phrase_font, colors["accent"])
            y += 4
    if source_id_text:
        y += 14
        _draw_centered(source_id_text, id_font, colors["source"])

    return snap_image_to_palette(image, SPECTRA6_PALETTE)


def render_static_message(message: str, width: int, height: int, theme: str = "default") -> Image.Image:
    """Render a centered headline message in the active theme.

    The opt-in ``--mode goodnight --message TEXT`` path (the ``auto`` sleep
    and startup frames use :func:`render_sleep_frame`). Reuses the theme
    palette, border and fonts but never a custom frame, so a custom-frame
    theme contributes only its ``THEMES`` palette.
    """
    colors = THEMES[theme]
    image = Image.new("RGB", (width, height), color=colors["page_bg"])
    _paint_theme_border(image, theme, colors)
    draw = ImageDraw.Draw(image)

    max_text_width = width - 2 * SIDE_MARGIN - 40
    headline_candidates = theme_font_candidates(theme, "quote_bold")
    line_gap = 12
    for size in range(96, 35, -4):
        font = load_font(headline_candidates, size=size)
        lines = wrap_text(draw, message, font, max_text_width)
        line_heights = [
            draw.textbbox((0, 0), line, font=font)[3] - draw.textbbox((0, 0), line, font=font)[1]
            for line in lines
        ]
        block_h = sum(line_heights) + max(0, len(lines) - 1) * line_gap
        if block_h <= height - 80:
            break

    y = max(40, (height - block_h) // 2)
    for line, h in zip(lines, line_heights):
        bbox = draw.textbbox((0, 0), line, font=font)
        w = bbox[2] - bbox[0]
        _draw_text_body(image, draw, ((width - w) // 2, y), line, font=font, fill=colors["text"], theme=theme)
        y += h + line_gap

    return snap_image_to_palette(image, SPECTRA6_PALETTE)


# The quote the panel sleeps under, shaped as a corpus row so it goes through
# the entire literary layout — every border painter, custom frame and the
# accent-coloured matched phrase — in whichever theme is active.
#
# ``matched_text`` need not be a time phrase: ``resolve_display_match`` tries
# a literal search first, so "sleep" is bolded in the accent like a real hour.
# In ``dark`` this reproduces the bundled ``assets/goodnight.png``.
#
# Deliberately no ``source_id`` / ``line_number``: this row never enters the
# picker or the anti-repeat ledger and must not be confusable with a corpus
# row by anything keyed on that pair.
SLEEP_QUOTE_ROW: dict[str, str] = {
    "display_quote": "To sleep, perchance to dream.",
    "matched_text": "sleep",
    "author": "William Shakespeare",
    "title": "Hamlet",
}


def render_sleep_frame(
    time_str: str | None, width: int, height: int, theme: str = "default"
) -> Image.Image:
    """Render :data:`SLEEP_QUOTE_ROW` through the normal literary layout.

    The themed replacement for the static ``assets/goodnight.png``. Always
    ``mode="production"``.

    ``time_str`` is the moment quiet hours began, passed through because many
    themes surface the hour in their furniture (``tarot``'s numeral,
    ``lieder``'s time signature, ``abyssal``'s depth gauge …) and the entry
    time is the honest value there. ``None`` falls back to the wall clock so a
    bare ``render_quote.py --mode goodnight`` still renders.
    """
    if time_str is None:
        time_str = datetime.datetime.now().strftime("%H:%M")
    # Hand out a copy: this module-level row is shared across every render
    # in a process (contact sheet, ``/api/preview``), so a painter that ever
    # mutated its row would corrupt later renders.
    return render(time_str, dict(SLEEP_QUOTE_ROW), width, height, mode="production", theme=theme)


