def _diags_system_info() -> dict[str, str]:
    """Return host / IP / uptime strings for the diagnostic frame.

    Each lookup is wrapped so a misconfigured environment (no network,
    non-Linux host, restricted /proc) still renders; a missing field shows
    ``"—"``.

    The IP comes from a UDP "connect" to a public address, which sends no
    packet but pins the kernel's chosen source address — the primary
    outbound IP — with ``socket.gethostbyname`` as the fallback.
    """
    import socket

    info: dict[str, str] = {"host": "—", "ip": "—", "uptime": "—"}
    try:
        host = socket.gethostname()
        if host:
            info["host"] = host
    except Exception:
        pass
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            sock.connect(("8.8.8.8", 53))
            info["ip"] = sock.getsockname()[0]
        finally:
            sock.close()
    except Exception:
        try:
            ip = socket.gethostbyname(socket.gethostname())
            if ip and ip != "127.0.0.1":
                info["ip"] = ip
        except Exception:
            pass
    try:
        with open("/proc/uptime", "r") as fh:
            seconds = int(float(fh.read().split()[0]))
        days, rem = divmod(seconds, 86400)
        hours, rem = divmod(rem, 3600)
        minutes = rem // 60
        if days:
            info["uptime"] = f"{days}d {hours}h {minutes}m"
        elif hours:
            info["uptime"] = f"{hours}h {minutes}m"
        else:
            info["uptime"] = f"{minutes}m"
    except Exception:
        pass
    return info


def _fill_swatch_stipple(
    image: Image.Image,
    rect: tuple[int, int, int, int],
    dark: tuple[int, int, int],
    light: tuple[int, int, int],
    light_density: float,
) -> None:
    """Paint a rectangle with the Bayer stipple ``draw_text_dithered``
    applies to glyph masks; the three density branches mirror that function
    so the swatch shows the recipe a theme would actually paint.
    """
    x0, y0, x1, y1 = rect
    # Clip to image bounds: ``PixelAccess`` raises on out-of-range writes,
    # and a rect may sit partly or fully off-canvas (the diags swatch band in
    # a web-preview thumbnail).
    w, h = image.size
    x0 = max(0, x0)
    y0 = max(0, y0)
    x1 = min(w, x1)
    y1 = min(h, y1)
    if x1 <= x0 or y1 <= y0:
        return
    px = image.load()
    if light_density <= 0.25:
        for y in range(y0, y1):
            for x in range(x0, x1):
                px[x, y] = light if (x % 2 == 0 and y % 2 == 0) else dark
    elif light_density >= 0.5:
        for y in range(y0, y1):
            for x in range(x0, x1):
                px[x, y] = dark if (x + y) % 2 == 0 else light
    else:
        threshold = round(light_density * 16)
        for y in range(y0, y1):
            for x in range(x0, x1):
                px[x, y] = light if BAYER_4x4[y % 4][x % 4] < threshold else dark


def _fill_swatch_stipple_3way(
    image: Image.Image,
    rect: tuple[int, int, int, int],
    ink_a: tuple[int, int, int],
    ink_b: tuple[int, int, int],
    ink_c: tuple[int, int, int],
    density_a: float,
    density_b: float,
) -> None:
    """Paint a rectangular region with a 3-ink Bayer stipple.

    Partitions the 4×4 Bayer tile by two thresholds: cells below
    ``round(density_a * 16)`` get ``ink_a``, below
    ``round((density_a + density_b) * 16)`` get ``ink_b``, the rest ``ink_c``.
    See the "Three-ink recipes" section of ``spectra6_color_recipes.md``.
    Clips to image bounds like ``_fill_swatch_stipple``.
    """
    x0, y0, x1, y1 = rect
    w, h = image.size
    x0 = max(0, x0)
    y0 = max(0, y0)
    x1 = min(w, x1)
    y1 = min(h, y1)
    if x1 <= x0 or y1 <= y0:
        return
    threshold_a = round(density_a * 16)
    threshold_b = round((density_a + density_b) * 16)
    px = image.load()
    for y in range(y0, y1):
        for x in range(x0, x1):
            cell = BAYER_4x4[y % 4][x % 4]
            if cell < threshold_a:
                px[x, y] = ink_a
            elif cell < threshold_b:
                px[x, y] = ink_b
            else:
                px[x, y] = ink_c


# ---------------------------------------------------------------------------
# Shared painter helpers
#
# Small primitives that several themes reached for independently and that
# had been copy-pasted under theme-prefixed names (issue #336). One body
# each, so a fix lands everywhere and a new theme finds them by name.
# ---------------------------------------------------------------------------


def _clock_hour12(time_str) -> int:
    """The 12-hour clock hour, 1..12, parsed defensively from ``HH:MM``.

    Hour-only time surfaces (a numeral, a camera, a moon phase, a bearing)
    all want the same thing: 00:10 and 12:10 are 12, 13:00 is 1. Preview and
    source-card renders can reach a painter with an odd string or ``None``,
    so a bad parse falls back to 12 rather than raising.
    """
    try:
        hour = int(str(time_str).split(":", 1)[0])
    except ValueError:
        return 12
    return hour % 12 or 12


def _white_noise(width: int, height: int, seed: int) -> Image.Image:
    """A deterministic ``L`` field of uniform noise, one byte per pixel.

    For an *aperiodic* scatter: a small Bayer gate paints diagonal
    pinstripes that read as corduroy on the panel inks (invisible in an RGB
    preview). :func:`position_noise` has the right character but is a
    Python call per pixel, far too slow for a whole canvas. ``Random.randbytes``
    is the same white noise from a seeded C generator, so the frame stays
    byte-identical across processes (``hash()`` would not: it is
    PYTHONHASHSEED-salted), and compositing uses C-speed ``point`` LUTs and
    ``paste`` masks.
    """
    return Image.frombytes("L", (width, height), random.Random(seed).randbytes(width * height))


def _smooth_noise(size, cells, seed: int) -> Image.Image:
    """Seeded value noise: a coarse grid of white noise, bicubic-upsampled.
    ``cells`` is the grid's (columns, rows), so an unequal pair stretches the
    noise into streaks."""
    return _white_noise(cells[0], cells[1], seed).resize(size, Image.Resampling.BICUBIC)


def _bayer_threshold_field(size) -> Image.Image:
    """``BAYER_8x8`` tiled across ``size`` as an ``"L"`` image of rank
    thresholds (``rank * 4 + 2``), so a density map can be stippled with one
    C-speed compare: ``ImageChops.subtract(density, field)`` is non-zero
    exactly where the density beats the cell's rank."""
    width, height = size
    rows = [bytes(BAYER_8x8[r][x % 8] * 4 + 2 for x in range(width)) for r in range(8)]
    return Image.frombytes("L", size, b"".join(rows[y % 8] for y in range(height)))


def _lerp_stops(stops, y: float):
    """The colour at ``y`` on a ``[(y, rgb), ...]`` gradient sorted on ``y``,
    linearly interpolated; before the first stop it holds the first colour,
    past the last it holds the last."""
    for (y0, c0), (y1, c1) in zip(stops, stops[1:]):
        if y <= y1:
            t = 0.0 if y1 == y0 else max(0.0, (y - y0) / (y1 - y0))
            return tuple(round(a + (b - a) * t) for a, b in zip(c0, c1))
    return stops[-1][1]


def _halo_paste(image: Image.Image, mask: Image.Image, fill, halo: int = 5) -> None:
    """Paste ``fill`` through ``mask`` over a black halo grown from it, so
    text floats on a busy scene without a panel hiding it. ``fill=None``
    lays the halo alone (for a mask whose ink is painted separately)."""
    hard = mask.point(lambda v: 255 if v > 110 else 0)
    image.paste(SPECTRA6["black"], (0, 0), hard.filter(ImageFilter.MaxFilter(halo)))
    if fill is not None:
        image.paste(fill, (0, 0), hard)


def _soft_ellipse_mask(size, box, blur: int) -> Image.Image:
    """An ``L`` mask of the ellipse ``box``, Gaussian-feathered by ``blur``:
    a pool of light or shadow to composite through."""
    mask = Image.new("L", size, 0)
    ImageDraw.Draw(mask).ellipse(box, fill=255)
    return mask.filter(ImageFilter.GaussianBlur(blur))

# The panel's measured inks — CLAUDE.md's calibration table. A scene painted
# in this space and quantised by ``_dither_calibrated`` is re-labelled with the
# nominal ``SPECTRA6`` values afterwards, so the dither decides in the space the
# eye actually sees. Shared by expedition, hades, beksinski, goya, lumon, dsky,
# oblivion and yorha.
_PANEL_INKS = {
    "white": (185, 199, 201),
    "black": (31, 34, 38),
    "red": (98, 32, 30),
    "yellow": (193, 187, 30),
    "blue": (35, 63, 142),
    "green": (53, 86, 58),
}


def _dither_calibrated(scene: Image.Image, inks) -> Image.Image:
    """Floyd–Steinberg ``scene`` against the *calibrated* colours of ``inks``,
    then re-label the chosen indices with the nominal inks.

    ``quantize(palette=…)`` maps every pixel to an index into the palette
    image it is handed; replacing that image's palette with the nominal
    values afterwards is a pure re-labelling, so the dither's decisions are
    made in the measured space and its output is on-palette RGB.
    """
    measured: list[int] = []
    nominal: list[int] = []
    for name in inks:
        measured.extend(_PANEL_INKS[name])
        nominal.extend(SPECTRA6[name])
    while len(measured) < 768:
        measured.extend(_PANEL_INKS[inks[0]])
        nominal.extend(SPECTRA6[inks[0]])
    palette = Image.new("P", (1, 1))
    palette.putpalette(measured[:768])
    quantised = scene.convert("RGB").quantize(palette=palette, dither=Image.Dither.FLOYDSTEINBERG)
    quantised.putpalette(nominal[:768])
    return quantised.convert("RGB")


def _shift_no_wrap(img: Image.Image, dx: int, dy: int) -> Image.Image:
    """Translate without wrap-around (``ImageChops.offset`` wraps)."""
    out = Image.new(img.mode, img.size, 0)
    out.paste(img, (dx, dy))
    return out


def _shade_silhouette(mask: Image.Image, base, light, dark, *, offset: int = 10, blur: int = 7) -> Image.Image:
    """Model a silhouette under an upper-left light.

    Where the shape meets its own down-right shift it has an exposed upper-left
    edge — the lit rim; where it meets its up-left shift, the lower-right core
    shadow. Both are blurred so the modelling rolls round the form."""
    m = mask.filter(ImageFilter.GaussianBlur(1))
    lit = ImageChops.subtract(m, _shift_no_wrap(m, offset, offset)).filter(ImageFilter.GaussianBlur(blur))
    shadow = ImageChops.subtract(m, _shift_no_wrap(m, -offset, -offset)).filter(ImageFilter.GaussianBlur(blur))
    img = Image.new("RGB", mask.size, base)
    img = Image.composite(Image.new("RGB", mask.size, light), img, lit)
    return Image.composite(Image.new("RGB", mask.size, dark), img, shadow)


def _catmull_rom(points, closed: bool = True, samples: int = 10) -> list:
    """Catmull-Rom through ``points`` — organic silhouettes rather than the
    hard polygon corners a figure made of ``ImageDraw`` primitives gets."""
    pts = list(points)
    n = len(pts)
    out = []
    for i in (range(n) if closed else range(n - 1)):
        p0 = pts[(i - 1) % n] if closed else pts[max(i - 1, 0)]
        p1, p2 = pts[i], pts[(i + 1) % n]
        p3 = pts[(i + 2) % n] if closed else pts[min(i + 2, n - 1)]
        for k in range(samples):
            t = k / samples
            t2, t3 = t * t, t * t * t
            out.append(tuple(
                0.5 * (2 * p1[j] + (p2[j] - p0[j]) * t
                       + (2 * p0[j] - 5 * p1[j] + 4 * p2[j] - p3[j]) * t2
                       + (3 * p1[j] - p0[j] - 3 * p2[j] + p3[j]) * t3)
                for j in (0, 1)
            ))
    if not closed:
        out.append(tuple(pts[-1]))
    return out



# Three-ink stipple recipes from ``spectra6_color_recipes.md`` ("Three-ink
# recipes"), as (display name, ink_a, ink_b, ink_c, density_a, density_b,
# short label); the third density is implicit. Shown in two rows of 6 below
# the two-ink band, to check on the panel whether each reads as its pastel.
_DIAGS_TRIPLE_SWATCHES: list[
    tuple[str, tuple[int, int, int], tuple[int, int, int], tuple[int, int, int], float, float, str]
] = [
    # Pastels (3rd ink = white)
    ("light orange", SPECTRA6["red"],    SPECTRA6["yellow"], SPECTRA6["white"], 0.40,    0.40,    "R+Y+W 40/40/20"),
    ("salmon",       SPECTRA6["red"],    SPECTRA6["yellow"], SPECTRA6["white"], 1 / 3,   1 / 3,   "R+Y+W 1:1:1"),
    ("peach",        SPECTRA6["red"],    SPECTRA6["yellow"], SPECTRA6["white"], 0.30,    0.50,    "R+Y+W 30/50/20"),
    ("lavender",     SPECTRA6["red"],    SPECTRA6["blue"],   SPECTRA6["white"], 1 / 3,   1 / 3,   "R+B+W 1:1:1"),
    ("lilac",        SPECTRA6["red"],    SPECTRA6["blue"],   SPECTRA6["white"], 0.25,    0.25,    "R+B+W 25/25/50"),
    ("seafoam",      SPECTRA6["green"],  SPECTRA6["blue"],   SPECTRA6["white"], 0.40,    0.30,    "G+B+W 40/30/30"),
    # Pastels continued + deep tones (3rd ink = white or black) + chromatic (no W/K)
    ("khaki",        SPECTRA6["yellow"], SPECTRA6["green"],  SPECTRA6["white"], 0.40,    0.30,    "Y+G+W 40/30/30"),
    ("beige",        SPECTRA6["red"],    SPECTRA6["yellow"], SPECTRA6["white"], 0.25,    0.25,    "R+Y+W 25/25/50"),
    ("plum",         SPECTRA6["red"],    SPECTRA6["blue"],   SPECTRA6["black"], 1 / 3,   1 / 3,   "R+B+K 1:1:1"),
    ("print sepia",  SPECTRA6["red"],    SPECTRA6["yellow"], SPECTRA6["black"], 0.40,    0.40,    "R+Y+K 40/40/20"),
    ("burnt orange", SPECTRA6["red"],    SPECTRA6["yellow"], SPECTRA6["green"], 0.50,    0.40,    "R+Y+G 50/40/10"),
    ("forest-teal",  SPECTRA6["green"],  SPECTRA6["blue"],   SPECTRA6["yellow"], 0.40,   0.40,    "G+B+Y 40/40/20"),
]

_DIAGS_TRIPLE_ROW1_COUNT = 6


def render_diags_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Render the diagnostic frame for the ``diags`` theme.

    Replaces the literary layout with a status panel: a large clock, picker
    metrics (bucket / layout / quality / ID / matched phrase), the native
    palette, and the two- and three-ink stipple recipes. For on-panel
    calibration and for confirming the picker chose what you'd expect.
    """
    colors = THEMES["diags"]
    image = Image.new("RGB", (width, height), color=colors["page_bg"])
    draw = ImageDraw.Draw(image)

    INSET = 12
    PAD_X = 22

    # Outer frame
    draw.rectangle((INSET, INSET, width - INSET - 1, height - INSET - 1), outline=colors["text"], width=1)

    # Header bar
    header_font = load_font(META_FONT_BOLD_CANDIDATES, size=14)
    header = "IDLE HOURS · DIAGS"
    draw.text((PAD_X, INSET + 8), header, font=header_font, fill=colors["accent"])
    rule_y = INSET + 32
    draw.line((PAD_X, rule_y, width - PAD_X, rule_y), fill=colors["text"])

    # ----- Top section: big clock + status grid -----
    clock_font = load_font(theme_font_candidates("diags", "quote_bold"), size=88)
    clock_bbox = draw.textbbox((0, 0), time_str, font=clock_font)
    clock_w = clock_bbox[2] - clock_bbox[0]
    clock_x = PAD_X
    clock_y = rule_y + 10
    draw.text((clock_x - clock_bbox[0], clock_y - clock_bbox[1]), time_str, font=clock_font, fill=colors["text"])

    # Status table — right of the clock
    field_key_font = load_font(META_FONT_BOLD_CANDIDATES, size=12)
    field_val_font = load_font(META_FONT_CANDIDATES, size=12)
    fields_x = clock_x + clock_w + 36
    key_col_w = 92
    f_y = clock_y + 6
    LINE_H = 17

    layout_name = choose_layout(quote_row.get("display_quote") or "")
    bucket = quote_row.get("bucket") or "—"
    resolved = quote_row.get("resolved_bucket") or bucket
    quality = quote_row.get("quality_score")
    source_id = quote_row.get("source_id")
    line_number = quote_row.get("line_number")
    matched = (quote_row.get("matched_text") or "—").replace("\n", " ").strip()
    fallback = quote_row.get("used_fallback")

    if resolved and bucket and resolved != bucket and fallback:
        bucket_display = f"{bucket} → {resolved}"
    else:
        bucket_display = resolved or bucket

    if source_id and line_number is not None:
        id_display = f"{source_id}:{line_number}"
    elif source_id:
        id_display = str(source_id)
    else:
        id_display = "—"

    fields = [
        ("BUCKET", bucket_display),
        ("LAYOUT", layout_name),
        ("QUALITY", "—" if quality is None else str(quality)),
        ("FALLBACK", "yes" if fallback else "no"),
        ("ID", id_display),
        ("MATCHED", matched if len(matched) <= 36 else matched[:34] + "…"),
    ]
    for key, val in fields:
        draw.text((fields_x, f_y), key, font=field_key_font, fill=colors["accent"])
        draw.text((fields_x + key_col_w, f_y), val, font=field_val_font, fill=colors["text"])
        f_y += LINE_H

    # ----- System info strip (host / ip / uptime) -----
    # Sits between the status table (ends ~y=162) and the palette swatches
    # (start y=192).
    sys_info = _diags_system_info()
    sys_label_font = load_font(META_FONT_BOLD_CANDIDATES, size=11)
    sys_val_font = load_font(META_FONT_CANDIDATES, size=11)
    sys_y = 170
    sys_entries = [
        ("HOST", sys_info["host"]),
        ("IP", sys_info["ip"]),
        ("UPTIME", sys_info["uptime"]),
    ]
    # Distribute the three entries evenly across the inner width.
    avail_strip_w = width - 2 * PAD_X
    slot_w = avail_strip_w // len(sys_entries)
    for i, (key, val) in enumerate(sys_entries):
        slot_x = PAD_X + i * slot_w
        draw.text((slot_x, sys_y), key, font=sys_label_font, fill=colors["accent"])
        key_bb = draw.textbbox((0, 0), key, font=sys_label_font)
        key_w = key_bb[2] - key_bb[0]
        draw.text((slot_x + key_w + 8, sys_y), val, font=sys_val_font, fill=colors["text"])

    # ----- Middle section: Spectra 6 swatches -----
    section_font = load_font(META_FONT_BOLD_CANDIDATES, size=12)
    label_bold = load_font(META_FONT_BOLD_CANDIDATES, size=10)
    label_reg = load_font(META_FONT_CANDIDATES, size=10)

    s1_y = 186
    draw.text((PAD_X, s1_y), "SPECTRA 6 NATIVE PALETTE", font=section_font, fill=colors["accent"])

    sw_top = s1_y + 14
    sw_h = 36
    sw_gap = 6
    sw_count = len(_DIAGS_SPECTRA6_SWATCHES)
    avail_w = width - 2 * PAD_X
    sw_w = (avail_w - (sw_count - 1) * sw_gap) // sw_count
    for i, (name, rgb, hex_code) in enumerate(_DIAGS_SPECTRA6_SWATCHES):
        x0 = PAD_X + i * (sw_w + sw_gap)
        x1 = x0 + sw_w
        y1 = sw_top + sw_h
        draw.rectangle((x0, sw_top, x1, y1), fill=rgb, outline=colors["text"], width=1)
        # Contrasting label: white on black / blue / red, black otherwise.
        is_dark_fill = rgb in (SPECTRA6["black"], SPECTRA6["blue"], SPECTRA6["red"])
        label_fill = SPECTRA6["white"] if is_dark_fill else SPECTRA6["black"]
        draw.text((x0 + 5, sw_top + 4), name.upper(), font=label_bold, fill=label_fill)
        draw.text((x0 + 5, sw_top + 18), hex_code, font=label_reg, fill=label_fill)

    # ----- Synth bands -----
    # Two-ink: 18 recipes in 2 rows (8 + 10). Three-ink: 12 recipes in 2 rows
    # (6 + 6). All four rows share the per-swatch geometry; only the column
    # count and the painter change. Labels are a bold name plus a faded
    # recipe, two 9 pt lines.
    label_bold_9 = load_font(META_FONT_BOLD_CANDIDATES, size=9)
    label_reg_9 = load_font(META_FONT_CANDIDATES, size=9)
    sw2_color_h = 22
    sw2_label_h = 22
    sw2_row_h = sw2_color_h + sw2_label_h
    sw2_row_gap = 3
    sw2_gap = 5

    def _paint_synth_row(row_top: int, entries: list, painter) -> None:
        n = len(entries)
        row_w = (avail_w - (n - 1) * sw2_gap) // n
        if row_w <= 0:
            # Canvas too narrow for the swatch grid (small /api/preview
            # thumbnail) — skip rather than feed PIL an inverted rectangle.
            return
        for col_idx, entry in enumerate(entries):
            x0 = PAD_X + col_idx * (row_w + sw2_gap)
            x1 = x0 + row_w
            color_y1 = row_top + sw2_color_h
            # Paint the stipple inset by 1 so the outline stays visible.
            painter(entry, (x0 + 1, row_top + 1, x1, color_y1))
            draw.rectangle((x0, row_top, x1, color_y1), outline=colors["text"], width=1)
            name = entry[0]
            recipe = entry[-1]
            draw.text((x0, color_y1 + 2), name, font=label_bold_9, fill=colors["text"])
            draw.text((x0, color_y1 + 12), recipe, font=label_reg_9, fill=colors["subtle"])

    def _two_ink_painter(entry, rect):
        _name, dark, light, density, _recipe = entry
        _fill_swatch_stipple(image, rect, dark, light, density)

    def _three_ink_painter(entry, rect):
        _name, ink_a, ink_b, ink_c, density_a, density_b, _recipe = entry
        _fill_swatch_stipple_3way(image, rect, ink_a, ink_b, ink_c, density_a, density_b)

    # ----- Two-ink synth band -----
    s2_y = sw_top + sw_h + 8
    draw.text((PAD_X, s2_y), "SYNTHESISED (2-INK STIPPLE)", font=section_font, fill=colors["accent"])
    sw2_top = s2_y + 14
    sw2_row1 = _DIAGS_SYNTH_SWATCHES[:_DIAGS_SYNTH_ROW1_COUNT]
    sw2_row2 = _DIAGS_SYNTH_SWATCHES[_DIAGS_SYNTH_ROW1_COUNT:]
    _paint_synth_row(sw2_top, sw2_row1, _two_ink_painter)
    _paint_synth_row(sw2_top + sw2_row_h + sw2_row_gap, sw2_row2, _two_ink_painter)

    # ----- Three-ink synth band -----
    sw2_band_end = sw2_top + 2 * sw2_row_h + sw2_row_gap
    s3_y = sw2_band_end + 6
    draw.text((PAD_X, s3_y), "SYNTHESISED (3-INK STIPPLE)", font=section_font, fill=colors["accent"])
    sw3_top = s3_y + 14
    sw3_row1 = _DIAGS_TRIPLE_SWATCHES[:_DIAGS_TRIPLE_ROW1_COUNT]
    sw3_row2 = _DIAGS_TRIPLE_SWATCHES[_DIAGS_TRIPLE_ROW1_COUNT:]
    _paint_synth_row(sw3_top, sw3_row1, _three_ink_painter)
    _paint_synth_row(sw3_top + sw2_row_h + sw2_row_gap, sw3_row2, _three_ink_painter)

    return snap_image_to_palette(image, SPECTRA6_PALETTE)


# ---------------------------------------------------------------------------
# Astrarium frame
# ---------------------------------------------------------------------------
# The astrarium theme has its own render path (like ``diags``): an
# astronomical-clock dial on the left, the quote on the right, a datum strip
# along the bottom. The coloured ring quadrants are documented two-ink
# stipples (R+Y tangerine, R+G sepia, G+B teal), so ``snap_image_to_palette``
# is a no-op.


def _astrarium_paint_cream_wash(image: Image.Image) -> None:
    """Sparse 1-in-8 yellow Bayer wash over the white page background.

    Same Layer 0 recipe as ``dispatch`` / ``illuminated`` / ``herbarium`` /
    ``mucha``: ``BAYER_4x4 < 2`` flips ~12.5% of white to yellow so the page
    reads as faintly cream paper.
    """
    px = image.load()
    w, h = image.size
    for y in range(h):
        row = BAYER_4x4[y % 4]
        for x in range(w):
            if row[x % 4] < 2 and px[x, y] == SPECTRA6["white"]:
                px[x, y] = SPECTRA6["yellow"]


def _astrarium_paint_ring_quadrant(
    image: Image.Image,
    cx: int,
    cy: int,
    r_outer: int,
    r_inner: int,
    angle_start_deg: float,
    angle_end_deg: float,
    dark: tuple[int, int, int],
    light: tuple[int, int, int],
    light_density: float,
) -> None:
    """Fill an annular pie-slice with a two-ink Bayer stipple.

    The dial's quadrants: R+Y tangerine top-right, R+G sepia bottom-right,
    G+B teal bottom-left, solid black top-left (with a constellation
    speckle painted separately). The density branches mirror
    ``draw_text_dithered`` so the ring reads as the same hue a body-text
    recipe would.
    """
    px = image.load()
    w, h = image.size
    r_outer_sq = r_outer * r_outer
    r_inner_sq = r_inner * r_inner
    a0 = math.radians(angle_start_deg)
    a1 = math.radians(angle_end_deg)
    threshold = round(light_density * 16)
    y0 = max(0, cy - r_outer - 1)
    y1 = min(h, cy + r_outer + 2)
    x0 = max(0, cx - r_outer - 1)
    x1 = min(w, cx + r_outer + 2)
    for y in range(y0, y1):
        dy = y - cy
        for x in range(x0, x1):
            dx = x - cx
            d_sq = dx * dx + dy * dy
            if d_sq < r_inner_sq or d_sq > r_outer_sq:
                continue
            # Clock-face angle: 0° up, increasing clockwise, normalised to
            # [0, 2π) so the span check works when the start crosses 0.
            angle = math.atan2(dx, -dy)  # -π..π, 0 at top
            if angle < 0:
                angle += 2 * math.pi
            if not (a0 <= angle < a1):
                continue
            if light_density <= 0.25:
                px[x, y] = light if (x % 2 == 0 and y % 2 == 0) else dark
            elif light_density >= 0.5:
                px[x, y] = dark if (x + y) % 2 == 0 else light
            else:
                px[x, y] = light if BAYER_4x4[y % 4][x % 4] < threshold else dark


def _astrarium_paint_constellation_field(
    image: Image.Image,
    cx: int,
    cy: int,
    r_outer: int,
    r_inner: int,
    angle_start_deg: float,
    angle_end_deg: float,
    seed: int,
) -> None:
    """Paint a sparse white star speckle inside an annular sector (the
    dial's black top-left quadrant). Seeded, so the speckle is stable
    across renders."""
    rng = random.Random(seed)
    px = image.load()
    w, h = image.size
    a0 = math.radians(angle_start_deg)
    a1 = math.radians(angle_end_deg)
    n_stars = 22
    for _ in range(n_stars):
        # Sample uniformly inside the annular sector by inverse CDF on r².
        r = math.sqrt(rng.uniform(r_inner * r_inner, r_outer * r_outer))
        angle = rng.uniform(a0, a1)
        # Convert back to screen-space cartesian (0° = up, clockwise).
        sx = cx + int(r * math.sin(angle))
        sy = cy - int(r * math.cos(angle))
        if 0 <= sx < w and 0 <= sy < h:
            px[sx, sy] = SPECTRA6["white"]
            # A 4-pointed micro-star for ~35% of them.
            if rng.random() < 0.35:
                for ox, oy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    nx, ny = sx + ox, sy + oy
                    if 0 <= nx < w and 0 <= ny < h:
                        px[nx, ny] = SPECTRA6["white"]


def _astrarium_paint_dial(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    cx: int,
    cy: int,
    time_str: str,
    now: datetime.datetime,
) -> None:
    """Paint the astronomical-clock dial centred at (cx, cy).

    Layered outside-in:
    1. Outer minute-tick ring (60 ticks, long every 5)
    2. Halftone quadrant ring (tangerine / sepia / teal / black with a
       constellation speckle)
    3. Minute numerals ("60" / "15" / "30" / "45")
    4. Inner rule
    5. Centre disc with the wall-clock date and weekday — the panel only
       repaints on a bucket change, so an HH:MM readout would be stale most
       of the time; the date isn't.
    """
    BLACK = SPECTRA6["black"]
    WHITE = SPECTRA6["white"]
    RED = SPECTRA6["red"]
    YELLOW = SPECTRA6["yellow"]
    BLUE = SPECTRA6["blue"]
    GREEN = SPECTRA6["green"]

    r_outer = 168
    r_ring_outer = 150
    r_ring_inner = 128
    r_inner_rule = 108

    # Layer 1: outer hairline circle + 60 minute ticks.
    draw.ellipse((cx - r_outer, cy - r_outer, cx + r_outer, cy + r_outer), outline=BLACK, width=1)
    for tick in range(60):
        angle = math.radians(tick * 6)
        is_major = tick % 5 == 0
        tick_len = 8 if is_major else 4
        x_inner = cx + int((r_outer - tick_len) * math.sin(angle))
        y_inner = cy - int((r_outer - tick_len) * math.cos(angle))
        x_outer = cx + int(r_outer * math.sin(angle))
        y_outer = cy - int(r_outer * math.cos(angle))
        draw.line((x_inner, y_inner, x_outer, y_outer), fill=BLACK, width=1 if is_major else 1)

    # Layer 2: four halftone ring quadrants (0° = up, clockwise, so 0–90°
    # is top-right).
    _astrarium_paint_ring_quadrant(
        image, cx, cy, r_ring_outer, r_ring_inner, 0, 90,
        dark=RED, light=YELLOW, light_density=0.375,  # tangerine TR
    )
    _astrarium_paint_ring_quadrant(
        image, cx, cy, r_ring_outer, r_ring_inner, 90, 180,
        dark=RED, light=GREEN, light_density=0.5,  # sepia/brown BR (R+G)
    )
    _astrarium_paint_ring_quadrant(
        image, cx, cy, r_ring_outer, r_ring_inner, 180, 270,
        dark=GREEN, light=BLUE, light_density=0.5,  # teal BL (G+B → cyan)
    )
    # TL solid black + constellation speckle on top.
    _astrarium_paint_ring_quadrant(
        image, cx, cy, r_ring_outer, r_ring_inner, 270, 360,
        dark=BLACK, light=BLACK, light_density=0.5,
    )
    _astrarium_paint_constellation_field(
        image, cx, cy, r_ring_outer - 2, r_ring_inner + 2, 270, 360, seed=2026
    )

    # Crisp up the ring edges the per-pixel painters leave slightly jagged.
    draw.ellipse((cx - r_ring_outer, cy - r_ring_outer, cx + r_ring_outer, cy + r_ring_outer), outline=BLACK, width=1)
    draw.ellipse((cx - r_ring_inner, cy - r_ring_inner, cx + r_ring_inner, cy + r_ring_inner), outline=BLACK, width=1)
    # Quadrant separator lines (faint).
    for deg in (0, 90, 180, 270):
        angle = math.radians(deg)
        x0 = cx + int(r_ring_inner * math.sin(angle))
        y0 = cy - int(r_ring_inner * math.cos(angle))
        x1 = cx + int(r_ring_outer * math.sin(angle))
        y1 = cy - int(r_ring_outer * math.cos(angle))
        draw.line((x0, y0, x1, y1), fill=BLACK, width=1)

    # Layer 3: minute numerals at the 60 / 15 / 30 / 45 positions.
    numeral_font = load_font(META_FONT_BOLD_CANDIDATES, size=11)
    for label, deg in (("60", 0), ("15", 90), ("30", 180), ("45", 270)):
        angle = math.radians(deg)
        r_label = r_outer - 18
        nx = cx + int(r_label * math.sin(angle))
        ny = cy - int(r_label * math.cos(angle))
        bbox = draw.textbbox((0, 0), label, font=numeral_font)
        w_lbl = bbox[2] - bbox[0]
        h_lbl = bbox[3] - bbox[1]
        # Erase a small disc so the ticks don't run through the digits.
        bg_pad = 3
        draw.ellipse(
            (nx - w_lbl // 2 - bg_pad, ny - h_lbl // 2 - bg_pad,
             nx + w_lbl // 2 + bg_pad, ny + h_lbl // 2 + bg_pad),
            fill=WHITE,
        )
        draw.text((nx - w_lbl // 2 - bbox[0], ny - h_lbl // 2 - bbox[1]), label, font=numeral_font, fill=BLACK)

    # Layer 4: inner rule.
    draw.ellipse((cx - r_inner_rule, cy - r_inner_rule, cx + r_inner_rule, cy + r_inner_rule), outline=BLACK, width=1)

    # Layer 5: centre disc, filled explicitly because the constellation
    # speckle can spill into the inner area.
    draw.ellipse((cx - r_inner_rule + 2, cy - r_inner_rule + 2, cx + r_inner_rule - 2, cy + r_inner_rule - 2), fill=WHITE)

    # Text is centred with anchor="mm" rather than bbox maths, because bbox
    # centring drifts vertically between dates with and without descenders.
    #
    # The disc shows the wall-clock date, not ``time_str`` (see the
    # docstring). ``now`` is captured once per frame and shared with the
    # header and datum strip, so a render straddling midnight can't disagree
    # with itself.
    date_text = now.strftime("%b %d")
    weekday_text = now.strftime("%A").upper()

    header_font = load_font(META_FONT_CANDIDATES, size=10)
    draw.text((cx, cy - 50), "TODAY", font=header_font, fill=BLACK, anchor="mm")

    # Big date (e.g. "May 19"), centred on the dial axis.
    date_font = load_font(theme_font_candidates("astrarium", "quote_bold"), size=54)
    draw.text((cx, cy), date_text, font=date_font, fill=BLACK, anchor="mm")

    # Day of week beneath the date, at cy+46 so the 54 pt date's descenders
    # ("Sep", "Aug") clear it.
    weekday_font = load_font(META_FONT_CANDIDATES, size=12)
    draw.text((cx, cy + 46), weekday_text, font=weekday_font, fill=BLACK, anchor="mm")
    del time_str  # kept for signature symmetry; the disc reads the shared ``now``

    # Tiny sun glyph below "TODAY", above the date: red sentinel, then the
    # bbox post-pass below flips Bayer ranks >= 6 (10/16) to yellow.
    sun_cx = cx
    sun_cy = cy - 38
    sun_r = 4
    draw.ellipse((sun_cx - sun_r, sun_cy - sun_r, sun_cx + sun_r, sun_cy + sun_r), fill=RED)
    for ang_deg in range(0, 360, 45):
        ang = math.radians(ang_deg)
        x0 = sun_cx + int((sun_r + 2) * math.sin(ang))
        y0 = sun_cy - int((sun_r + 2) * math.cos(ang))
        x1 = sun_cx + int((sun_r + 6) * math.sin(ang))
        y1 = sun_cy - int((sun_r + 6) * math.cos(ang))
        draw.line((x0, y0, x1, y1), fill=RED, width=1)
    # Post-pass the sun's bbox to tangerine.
    px = image.load()
    bb_x0 = sun_cx - sun_r - 8
    bb_y0 = sun_cy - sun_r - 8
    bb_x1 = sun_cx + sun_r + 8
    bb_y1 = sun_cy + sun_r + 8
    for y in range(max(0, bb_y0), min(image.height, bb_y1)):
        for x in range(max(0, bb_x0), min(image.width, bb_x1)):
            if px[x, y] == RED and BAYER_4x4[y % 4][x % 4] >= 6:
                px[x, y] = YELLOW


def _astrarium_paint_header(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    width: int,
    time_str: str,
    now: datetime.datetime,
) -> None:
    """Top-strip dashboard chrome — brand on the left, date stack on the
    right, dotted rule beneath. ``now`` is shared with the dial so the two
    dates can't disagree across midnight."""
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]

    brand_bold = load_font(META_FONT_BOLD_CANDIDATES, size=14)
    brand_regular = load_font(META_FONT_CANDIDATES, size=14)
    chrome_bold = load_font(META_FONT_BOLD_CANDIDATES, size=10)

    # Brand line: "IDLE HOURS // ASTRARIUM"
    x = 24
    y = 22
    draw.text((x, y), "IDLE HOURS", font=brand_bold, fill=BLACK)
    bbox = draw.textbbox((0, 0), "IDLE HOURS", font=brand_bold)
    x += bbox[2] - bbox[0] + 10
    draw.text((x, y), "//", font=brand_regular, fill=BLACK)
    bbox = draw.textbbox((0, 0), "//", font=brand_regular)
    x += bbox[2] - bbox[0] + 8
    draw.text((x, y), "ASTRARIUM", font=brand_bold, fill=RED)

    # Right-side date stack — bold SOL/year line on top, red day label
    # beneath. Anchored directly to the right margin.
    day_label = now.strftime("%a · %b %d").upper()
    sol = f"SOL {now.timetuple().tm_yday} · YR {now.year}"

    date_right = width - 24
    sol_bbox = draw.textbbox((0, 0), sol, font=chrome_bold)
    day_bbox = draw.textbbox((0, 0), day_label, font=chrome_bold)
    draw.text((date_right - (sol_bbox[2] - sol_bbox[0]) - sol_bbox[0], 16 - sol_bbox[1]), sol, font=chrome_bold, fill=BLACK)
    draw.text((date_right - (day_bbox[2] - day_bbox[0]) - day_bbox[0], 32 - day_bbox[1]), day_label, font=chrome_bold, fill=RED)

    # Hairline dashed rule under the header — dotted every 4px.
    rule_y = 50
    for x in range(24, width - 24, 4):
        draw.point((x, rule_y), fill=BLACK)
    del time_str  # kept for signature symmetry; the strip reads the shared ``now``


def _astrarium_paint_quote_panel(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    quote_row: dict,
    panel_left: int,
    panel_right: int,
    panel_top: int,
    panel_bottom: int,
) -> None:
    """Lay the quote, matched-phrase tangerine accent, and attribution
    into the right column."""
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    YELLOW = SPECTRA6["yellow"]

    panel_width = panel_right - panel_left
    max_text_width = panel_width - 16

    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    matched = quote_row.get("matched_text") or ""

    # Small four-pointed star ornament above the body, green post-passed
    # to G+B teal.
    star_cx = panel_left + panel_width // 2
    star_cy = panel_top + 18
    star_r = 12
    draw.line((star_cx - star_r, star_cy, star_cx + star_r, star_cy), fill=SPECTRA6["green"], width=1)
    draw.line((star_cx, star_cy - star_r, star_cx, star_cy + star_r), fill=SPECTRA6["green"], width=1)
    for s in range(-star_r // 2, star_r // 2 + 1):
        if -star_r // 2 <= s <= star_r // 2:
            draw.point((star_cx + s, star_cy + s), fill=SPECTRA6["green"])
            draw.point((star_cx + s, star_cy - s), fill=SPECTRA6["green"])
    draw.ellipse((star_cx - 2, star_cy - 2, star_cx + 2, star_cy + 2), fill=SPECTRA6["green"])
    px = image.load()
    for y in range(max(0, star_cy - star_r - 2), min(image.height, star_cy + star_r + 2)):
        for x in range(max(0, star_cx - star_r - 2), min(image.width, star_cx + star_r + 2)):
            if px[x, y] == SPECTRA6["green"] and (x + y) & 1:
                px[x, y] = SPECTRA6["blue"]

    # Body block: the panel is narrower than the standard layout, hence the
    # smaller font range. +36 / −38 reserve room for the star ornament
    # above and the closing mark + attribution below.
    body_top = panel_top + 36
    body_bottom = panel_bottom - 38
    body_height = body_bottom - body_top
    quote_font, quote_font_bold, wrapped_quote, line_height, chosen_size = fit_quote(
        draw,
        display_quote,
        matched,
        max_text_width,
        body_height,
        font_max=38,
        font_min=18,
        line_height_mult=1.14,
        theme="astrarium",
    )
    quote_block_height = len(wrapped_quote) * line_height

    # Vertically centre the wrapped quote inside its panel.
    block_top = body_top + max(0, (body_height - quote_block_height) // 2)
    y = block_top

    # Oversized opening quotation mark in tangerine, anchored above the
    # first body line near the left edge of the panel.
    mark_size = max(48, int(chosen_size * 1.6))
    mark_font = load_font(theme_font_candidates("astrarium", "ornament"), size=mark_size)
    open_mark = "“"
    open_bbox = draw.textbbox((0, 0), open_mark, font=mark_font)
    open_h = open_bbox[3] - open_bbox[1]
    open_x = panel_left + 4
    open_y = block_top - open_h // 4
    draw_text_dithered(
        image,
        (open_x - open_bbox[0], open_y - open_bbox[1]),
        open_mark,
        font=mark_font,
        dark=RED,
        light=YELLOW,
        light_density=0.375,
    )

    for line in wrapped_quote:
        # Trim leading/trailing whitespace tokens (as ``render`` does).
        start = 0
        while start < len(line) and line[start][0].strip() == "":
            start += 1
        end = len(line)
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        drawable = line[start:end]
        x = panel_left + 8
        body_ascent = _font_ascent(quote_font)
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            chunk_y = y + (body_ascent - _font_ascent(font))
            if is_bold:
                # Tangerine matched phrase (R+Y 5/8:3/8, as ``deco``).
                draw_text_dithered(
                    image,
                    (x, chunk_y),
                    chunk,
                    font=font,
                    dark=RED,
                    light=YELLOW,
                    light_density=0.375,
                )
            else:
                draw.text((x, chunk_y), chunk, font=font, fill=BLACK)
            bbox = draw.textbbox((0, 0), chunk, font=font)
            x += bbox[2] - bbox[0]
        y += line_height

    # Closing quotation mark, mirrored to the bottom-right of the panel.
    close_mark = "”"
    close_bbox = draw.textbbox((0, 0), close_mark, font=mark_font)
    close_w = close_bbox[2] - close_bbox[0]
    close_h = close_bbox[3] - close_bbox[1]
    close_x = panel_right - close_w - 4
    close_y = y - close_h // 3
    if close_y + close_h > panel_bottom:
        close_y = panel_bottom - close_h - 2
    draw_text_dithered(
        image,
        (close_x - close_bbox[0], close_y - close_bbox[1]),
        close_mark,
        font=mark_font,
        dark=RED,
        light=YELLOW,
        light_density=0.375,
        pattern_offset=(1, 0),
    )

    # Attribution in the dashboard's sans, not the body's Cormorant: its
    # hairline serifs break up after palette snapping at byline sizes.
    author = quote_row.get("author") or None
    title = quote_row.get("title") or fallback_title(quote_row)
    author_font = load_font(META_FONT_BOLD_CANDIDATES, size=13)
    title_font = load_font(META_FONT_CANDIDATES, size=12)
    attrib_y = max(y + 6, close_y + close_h - 18)
    attrib_y = min(attrib_y, panel_bottom - 32)
    if author:
        draw.text((panel_left + 8, attrib_y), author, font=author_font, fill=BLACK)
        attrib_y += 15
    if title:
        title_lines = wrap_text(draw, title, title_font, max_text_width)[:1]
        if title_lines:
            draw.text((panel_left + 8, attrib_y), title_lines[0], font=title_font, fill=BLACK)


def _astrarium_paint_datum_strip(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    width: int,
    height: int,
    time_str: str,
    now: datetime.datetime,
) -> None:
    """Paint the bottom datum strip: two cells (solar elevation, lunar
    phase) under the left-half dial, derived from the clock rather than
    pretending to be sensor readings. The right half, under the quote, is
    deliberately left open."""
    BLACK = SPECTRA6["black"]

    strip_top = height - 44
    strip_bottom = height - 8
    # Top dotted rule across the full inner width, separating the quote
    # panel from the strip even where the right half has no cells.
    inner_left = 24
    inner_right = width // 2
    for x in range(24, width - 24, 4):
        draw.point((x, strip_top), fill=BLACK)

    label_font = load_font(META_FONT_BOLD_CANDIDATES, size=9)
    value_font = load_font(META_FONT_BOLD_CANDIDATES, size=14)
    unit_font = load_font(META_FONT_CANDIDATES, size=9)

    try:
        hh, mm = time_str.split(":")
        hour24 = int(hh)
        minute = int(mm)
    except (ValueError, AttributeError):
        hour24, minute = 0, 0
    # Toy solar-elevation model (peaks at noon), not real astronomy — the
    # furniture only needs to vary with the time of day.
    minute_of_day = hour24 * 60 + minute
    solar_norm = math.sin(math.pi * minute_of_day / (24 * 60))
    solar_elevation = max(0.0, solar_norm) * 75.0

    # Lunar phase: day-of-year modulo 30, from the shared ``now``.
    doy = now.timetuple().tm_yday
    moon_phase_pct = (doy % 30) / 30.0 * 100

    panels: list[tuple[str, str, str, tuple[int, int, int]]] = [
        ("SOLAR ELEVATION", f"{solar_elevation:.1f}", "°", BLACK),
        ("LUNAR PHASE", f"{int(moon_phase_pct)}", "%", BLACK),
    ]

    inner_width = inner_right - inner_left
    panel_w = inner_width // len(panels)
    for i, (label, value, unit, value_color) in enumerate(panels):
        px0 = inner_left + i * panel_w
        # Vertical separator between panels.
        if i > 0:
            for y in range(strip_top + 4, strip_bottom, 2):
                draw.point((px0, y), fill=BLACK)
        # Label on top.
        lbl_y = strip_top + 4
        draw.text((px0 + 4, lbl_y), label, font=label_font, fill=BLACK)
        # Value + unit on a tight baseline to fit the 36 px band.
        val_bbox = draw.textbbox((0, 0), value, font=value_font)
        val_y = strip_top + 18
        draw.text((px0 + 4 - val_bbox[0], val_y - val_bbox[1]), value, font=value_font, fill=value_color)
        val_w = val_bbox[2] - val_bbox[0]
        unit_bbox = draw.textbbox((0, 0), unit, font=unit_font)
        draw.text(
            (px0 + 4 + val_w + 4 - unit_bbox[0], val_y + (val_bbox[3] - val_bbox[1]) - (unit_bbox[3] - unit_bbox[1]) - unit_bbox[1]),
            unit, font=unit_font, fill=BLACK,
        )

    # Closing vertical rule, in line with the dial/quote divider drawn in
    # render (``div_x = int(width * 0.5)``).
    for y in range(strip_top + 4, strip_bottom, 2):
        draw.point((inner_right, y), fill=BLACK)


def render_astrarium_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Render the astrarium-theme dashboard frame.

    Composition (designed at the canonical 800×480; other sizes use the
    same layout proportions so contact-sheet and curator-preview renders
    still produce a recognisable thumbnail):

      ┌────────────────────────────────────────────────────────────────┐
      │ IDLE HOURS // ASTRARIUM         SAT · MAY 19  | S6 │ 800×480   │
      │ ─────────────────────────────────────────────────────────────  │
      │                                                                │
      │         ╭──────────╮                  ★                        │
      │       60│   ┌──┐   │15                                          │
      │         │   │  │   │     “It was at  ten o'clock                │
      │         │   └──┘   │      today that the first                  │
      │       45│  May 19  │30    of all Time Machines                  │
      │         │ TUESDAY  │      began its career.                     │
      │         ╰──────────╯                                             │
      │                                                                │
      │ ─────────────────────────────────────────────────────────────  │
      │ SOLAR ELEVATION │ LUNAR PHASE │                                │
      │      53.2°      │     18%     │                                │
      └────────────────────────────────────────────────────────────────┘

    Fully on-palette: the ring quadrants are two-ink Bayer stipples
    (tangerine / sepia / teal) or solid black, so the closing
    ``snap_image_to_palette`` is a no-op on the painted regions.
    """
    image = Image.new("RGB", (width, height), color=SPECTRA6["white"])
    # Layer 0: cream wash background.
    _astrarium_paint_cream_wash(image)
    draw = ImageDraw.Draw(image)

    # Capture the wall clock once and share it across the header / dial /
    # datum strip, so a render straddling midnight can't show two dates
    # (which would persist until the next bucket change).
    now = datetime.datetime.now()

    # Top-strip dashboard chrome.
    _astrarium_paint_header(image, draw, width, time_str, now)
    # Dial centred in the left half, positioned proportionally so
    # thumbnails still work. The 50 px reserve covers the datum strip.
    # strip (height − 44, plus a small breathing gap).
    dial_zone_w = int(width * 0.5)
    dial_cx = dial_zone_w // 2 + 8
    dial_cy = 64 + (height - 64 - 50) // 2
    _astrarium_paint_dial(image, draw, dial_cx, dial_cy, time_str, now)
    # Quote panel in the right half: 12 px right of the divider (plus the
    # panel's own 4–8 px padding), between the header rule (y=50) and the
    # datum strip (y=height−44).
    # two horizontal rules without crowding either of them.
    panel_left = int(width * 0.5) + 12
    panel_right = width - 24
    panel_top = 54
    panel_bottom = height - 46
    _astrarium_paint_quote_panel(image, draw, quote_row, panel_left, panel_right, panel_top, panel_bottom)
    # Dotted vertical divider between the dial and the quote panel.
    # (a faint dotted line, similar to the dashed header rule).
    div_x = int(width * 0.5)
    for y in range(64, height - 48, 4):
        draw.point((div_x, y), fill=SPECTRA6["black"])

    # Bottom datum strip.
    _astrarium_paint_datum_strip(image, draw, width, height, time_str, now)

    return snap_image_to_palette(image, SPECTRA6_PALETTE)


# ─── marquee (1930s movie-palace facade) ─────────────────────────────────────
# A black theatre facade at night: a yellow/red bulb-light border, the book
# title at the top as the chunky Bungee Shade "feature title", the quote below
# as the feature copy in white Cardo Italic with a red matched-phrase accent,
# and WRITTEN BY credit chrome along the bottom. (A Solari split-flap board
# was tried for this slot; its wayfinding register fought the literary
# content.)

_MARQUEE_BULB_INSET = 16
_MARQUEE_BULB_RADIUS = 5
_MARQUEE_BULB_SPACING = 32


def _marquee_paint_facade(image: Image.Image) -> None:
    """Solid black ground — the theater facade at night."""
    image.paste(SPECTRA6["black"], (0, 0, image.width, image.height))


def _marquee_paint_bulb_border(image: Image.Image, draw: ImageDraw.ImageDraw, width: int, height: int) -> None:
    """Yellow + red bulb-light border around the entire perimeter.

    Bulbs alternate yellow and red around the perimeter (a vintage
    coloured-bulb marquee rather than a uniform lamp row), each with a
    small white highlight so it reads as lit glass.
    """
    YELLOW = SPECTRA6["yellow"]
    RED = SPECTRA6["red"]
    WHITE = SPECTRA6["white"]
    r = _MARQUEE_BULB_RADIUS
    inset = _MARQUEE_BULB_INSET
    spacing = _MARQUEE_BULB_SPACING
    # Walk the perimeter and emit a bulb at each step.
    bulbs: list[tuple[int, int]] = []
    # Top edge: left → right.
    for x in range(inset, width - inset + 1, spacing):
        bulbs.append((x, inset))
    # Right edge: top → bottom (skip first to avoid double-tap of corner).
    for y in range(inset + spacing, height - inset + 1, spacing):
        bulbs.append((width - inset, y))
    # Bottom edge: right → left.
    for x in range(width - inset - spacing, inset - 1, -spacing):
        bulbs.append((x, height - inset))
    # Left edge: bottom → top.
    for y in range(height - inset - spacing, inset, -spacing):
        bulbs.append((inset, y))
    for i, (cx, cy) in enumerate(bulbs):
        bulb_colour = YELLOW if i % 2 == 0 else RED
        draw.ellipse((cx - r, cy - r, cx + r, cy + r), fill=bulb_colour)
        # White highlight near the bulb's top-left.
        draw.ellipse((cx - 1, cy - 2, cx + 1, cy), fill=WHITE)


def _marquee_paint_label_band(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    width: int,
    y_top: int,
    text: str,
    *,
    size: int = 14,
    colour: tuple[int, int, int] | None = None,
) -> None:
    """Centred chrome label (Antonio Bold) — the NOW SHOWING / ONE NIGHT ONLY taglines."""
    if colour is None:
        colour = SPECTRA6["yellow"]
    # Antonio Bold rather than Bungee Shade: the 3D-blocked Bungee Shade
    # muddies into noise at small label sizes.
    font = load_font([(ANTONIO_VARIABLE, "Bold"), *META_FONT_BOLD_CANDIDATES], size=size)
    bbox = draw.textbbox((0, 0), text, font=font)
    tw = bbox[2] - bbox[0]
    cx = width // 2
    draw.text((cx - tw // 2 - bbox[0], y_top - bbox[1]), text, font=font, fill=colour)


def _marquee_paint_feature_title(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    width: int,
    quote_row: dict,
    cy: int,
) -> None:
    """The book title as big white Bungee Shade "feature title" chrome.

    Centred on ``width`` and ``cy``, uppercased (the marquee convention) and
    shrunk to fit from 72pt down to 32pt; if it still overflows it wraps at
    the space nearest the midpoint and a fresh size sweep fits both lines.

    Falls back to the author, then the literal ``"IDLE HOURS"`` — never the
    wall-clock HH:MM, since the matched phrase is the time signal.
    """
    WHITE = SPECTRA6["white"]
    title = (quote_row.get("title") or fallback_title(quote_row) or "").strip()
    author = (quote_row.get("author") or "").strip()
    text = title.upper() or author.upper() or "IDLE HOURS"
    if not text:
        return
    max_text_width = width - 100  # 50 px inset each side

    # Try single-line fit first, biggest size down.
    chain = theme_font_candidates("marquee", "ornament")
    for size in (72, 64, 56, 50, 44, 38, 32):
        font = load_font(chain, size=size)
        bbox = draw.textbbox((0, 0), text, font=font)
        tw = bbox[2] - bbox[0]
        if tw <= max_text_width:
            th = bbox[3] - bbox[1]
            draw.text(
                (width // 2 - tw // 2 - bbox[0], cy - th // 2 - bbox[1]),
                text, font=font, fill=WHITE,
            )
            return

    # Wrap to two lines at the space nearest the midpoint.
    mid = len(text) // 2
    left_break = text.rfind(" ", 0, mid + 4)
    right_break = text.find(" ", mid)
    candidates = [b for b in (left_break, right_break) if b > 0]
    if not candidates:
        # No space at all — render at the smallest size and let it overflow.
        font = load_font(chain, size=28)
        bbox = draw.textbbox((0, 0), text, font=font)
        tw = bbox[2] - bbox[0]
        th = bbox[3] - bbox[1]
        draw.text(
            (width // 2 - tw // 2 - bbox[0], cy - th // 2 - bbox[1]),
            text, font=font, fill=WHITE,
        )
        return
    split_at = min(candidates, key=lambda b: abs(b - mid))
    line1, line2 = text[:split_at].strip(), text[split_at + 1:].strip()

    for size in (54, 48, 42, 36, 32, 28, 24):
        font = load_font(chain, size=size)
        bbox1 = draw.textbbox((0, 0), line1, font=font)
        bbox2 = draw.textbbox((0, 0), line2, font=font)
        tw1 = bbox1[2] - bbox1[0]
        tw2 = bbox2[2] - bbox2[0]
        if tw1 <= max_text_width and tw2 <= max_text_width:
            break

    th = bbox1[3] - bbox1[1]
    line_gap = 10
    block_h = th * 2 + line_gap
    top_y = cy - block_h // 2
    # Line 1.
    draw.text(
        (width // 2 - (bbox1[2] - bbox1[0]) // 2 - bbox1[0], top_y - bbox1[1]),
        line1, font=font, fill=WHITE,
    )
    # Line 2.
    draw.text(
        (width // 2 - (bbox2[2] - bbox2[0]) // 2 - bbox2[0],
         top_y + th + line_gap - bbox2[1]),
        line2, font=font, fill=WHITE,
    )


def _marquee_paint_divider(image: Image.Image, draw: ImageDraw.ImageDraw, width: int, cy: int) -> None:
    """Decorative double rule between the title and the quote body.

    A thicker yellow upper rule and a thin red lower rule with a small red
    diamond between them, like a proscenium / poster divider.
    """
    YELLOW = SPECTRA6["yellow"]
    RED = SPECTRA6["red"]
    x_left = 80
    x_right = width - 80
    draw.line((x_left, cy - 4, x_right, cy - 4), fill=YELLOW, width=2)
    draw.line((x_left, cy + 4, x_right, cy + 4), fill=RED, width=1)
    # Centred red diamond between the rules.
    cx = width // 2
    draw.polygon([(cx, cy - 5), (cx + 5, cy), (cx, cy + 5), (cx - 5, cy)], fill=RED)


def _marquee_paint_body(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    quote_row: dict,
    rect: tuple[int, int, int, int],
) -> None:
    """Quote body in white Cardo Italic with a red matched-phrase accent.

    Centred line-by-line within ``rect``; ``fit_quote`` shrinks a dense
    quote to fit.
    """
    WHITE = SPECTRA6["white"]
    RED = SPECTRA6["red"]
    x0, y0, x1, y1 = rect
    width = x1 - x0
    height = y1 - y0
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    matched = quote_row.get("matched_text") or ""

    quote_font, quote_font_bold, wrapped_quote, line_height, _ = fit_quote(
        draw,
        display_quote,
        matched,
        width,
        height,
        font_max=30,
        font_min=18,
        line_height_mult=1.22,
        theme="marquee",
    )
    quote_block_height = len(wrapped_quote) * line_height
    block_top = y0 + max(0, (height - quote_block_height) // 2)
    body_ascent = _font_ascent(quote_font)
    y = block_top
    for line in wrapped_quote:
        start = 0
        while start < len(line) and line[start][0].strip() == "":
            start += 1
        end = len(line)
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        drawable = line[start:end]
        line_w = 0
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            bbox = draw.textbbox((0, 0), chunk, font=font)
            line_w += bbox[2] - bbox[0]
        x = x0 + max(0, (width - line_w) // 2)
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            chunk_y = y + (body_ascent - _font_ascent(font))
            fill = RED if is_bold else WHITE
            draw.text((x, chunk_y), chunk, font=font, fill=fill)
            bbox = draw.textbbox((0, 0), chunk, font=font)
            x += bbox[2] - bbox[0]
        y += line_height


def _marquee_paint_credits(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    quote_row: dict,
    width: int,
    y_top: int,
) -> None:
    """WRITTEN BY [AUTHOR] credit chrome.

    Yellow Antonio Bold "WRITTEN BY" plus the author in white Cardo Italic,
    centred. Not the movie-poster ``STARRING``: the author wrote the book
    rather than performing in it, so the credit line is where the literary
    register wins.
    """
    YELLOW = SPECTRA6["yellow"]
    WHITE = SPECTRA6["white"]
    author = (quote_row.get("author") or "").strip()
    if not author:
        return
    cx = width // 2
    label_font = load_font([(ANTONIO_VARIABLE, "Bold"), *META_FONT_BOLD_CANDIDATES], size=14)
    name_font = load_font(theme_font_candidates("marquee", "quote_regular"), size=20)
    label = "WRITTEN BY"
    label_bbox = draw.textbbox((0, 0), label, font=label_font)
    label_w = label_bbox[2] - label_bbox[0]
    name_bbox = draw.textbbox((0, 0), author, font=name_font)
    name_w = name_bbox[2] - name_bbox[0]
    gap = 14
    total_w = label_w + gap + name_w
    line_x = cx - total_w // 2
    draw.text((line_x - label_bbox[0], y_top - label_bbox[1]), label, font=label_font, fill=YELLOW)
    draw.text(
        (line_x + label_w + gap - name_bbox[0], y_top - name_bbox[1] - 2),
        author, font=name_font, fill=WHITE,
    )


def render_marquee_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """1930s movie-palace marquee.

    Black ground; alternating yellow/red bulb border; a "NOW SHOWING"
    tagline; the book title as Bungee Shade feature-title chrome (wrapped to
    two lines when long); the quote in white Cardo Italic with a red matched
    phrase; WRITTEN BY [AUTHOR] credits; "ONE NIGHT ONLY" above the bottom
    bulbs.

    ``time_str`` is never rendered — the matched phrase carries the time. It
    stays on the signature shared by the custom-frame painters.
    """
    del time_str  # see docstring; deliberately unused.
    image = Image.new("RGB", (width, height), color=SPECTRA6["black"])
    _marquee_paint_facade(image)
    draw = ImageDraw.Draw(image)
    _marquee_paint_bulb_border(image, draw, width, height)

    # Top "NOW SHOWING" tagline, just below the top bulb row.
    _marquee_paint_label_band(image, draw, width, y_top=40, text="—  NOW SHOWING  —", size=14)

    # Big chrome — the book title as the feature display.
    _marquee_paint_feature_title(image, draw, width, quote_row, cy=112)

    # Decorative double-rule dividing the title from the quote body.
    _marquee_paint_divider(image, draw, width, cy=180)

    # Literary quote body — centred between the divider and the credits.
    body_rect = (60, 200, width - 60, 360)
    _marquee_paint_body(image, draw, quote_row, body_rect)

    # Credits chrome — WRITTEN BY [AUTHOR] only (the title is at the top).
    _marquee_paint_credits(image, draw, quote_row, width, y_top=384)

    # "ONE NIGHT ONLY" tagline just above the bottom bulb row.
    _marquee_paint_label_band(image, draw, width, y_top=448, text="—  ONE NIGHT ONLY  —", size=12)

    return snap_image_to_palette(image, SPECTRA6_PALETTE)


# ─── tarot (major-arcana card) ───────────────────────────────────────────────

# Vellum ground densities: mostly cream, with sparse foxing.
_TAROT_CREAM_DENSITY = 0.12
_TAROT_FOXING_DENSITY = 0.035
# Independent streams for the two layers: sampling one stream twice would
# correlate them (as ``cardcatalog``'s shared-period lattices cancelled).
_TAROT_CREAM_SEED = 0x7A6017
_TAROT_FOXING_SEED = 0x7A6018


def _tarot_paint_vellum(image: Image.Image) -> None:
    """Sparse R+G sepia foxing over a warm Y+W cream ground.

    1. Cream Y+W base at ``_TAROT_CREAM_DENSITY``.
    2. Sparse R+G foxing at ``_TAROT_FOXING_DENSITY``, split red/green by
       the low bit of the draw, so adjacent dots blend to rust-brown sepia.

    Foxing is pasted first and cream over it, so a pixel both layers claim
    comes out cream. Paints the whole canvas unconditionally, so it must be
    the first thing laid on the frame.
    """
    width, height = image.size
    cream_cut = round(_TAROT_CREAM_DENSITY * 255)
    fox_cut = round(_TAROT_FOXING_DENSITY * 255)
    foxing = _white_noise(width, height, _TAROT_FOXING_SEED)
    image.paste(SPECTRA6["red"], (0, 0), foxing.point(lambda v: 255 if v < fox_cut and v & 1 else 0))
    image.paste(SPECTRA6["green"], (0, 0), foxing.point(lambda v: 255 if v < fox_cut and not v & 1 else 0))
    cream = _white_noise(width, height, _TAROT_CREAM_SEED)
    image.paste(SPECTRA6["yellow"], (0, 0), cream.point(lambda v: 255 if v < cream_cut else 0))


_TAROT_ROMAN_NUMERALS = {
    1: "I", 2: "II", 3: "III", 4: "IV", 5: "V", 6: "VI",
    7: "VII", 8: "VIII", 9: "IX", 10: "X", 11: "XI", 12: "XII",
}


# The trump's name, carried along the card's foot (not the time phrase,
# which the reading beside it already states).
#
# TWO tables because the two emblem sources number the deck differently and
# the name must match the figure drawn: the Dodal plates (Marseille) number
# Justice VIII and La Force XI and stop at Le Pendu; the polygon painters
# follow Waite, which swaps those two, and draw the World at XII. Names are
# in English to match the reading; the ingest crops the plate's own printed
# title band.
_TAROT_TRUMP_NAMES = {
    1: "The Magician",
    2: "The High Priestess",
    3: "The Empress",
    4: "The Emperor",
    5: "The Hierophant",
    6: "The Lovers",
    7: "The Chariot",
    8: "Justice",
    9: "The Hermit",
    10: "The Wheel of Fortune",
    11: "Strength",
    12: "The Hanged Man",
}
# Where the polygon painters disagree with the plates (see above).
_TAROT_PAINTER_TRUMP_NAMES = {
    **_TAROT_TRUMP_NAMES,
    8: "Strength",
    11: "Justice",
    12: "The World",
}


# Card and reading-column geometry: a portrait card (a real tarot card's
# ratio is 0.58) laid on the cloth at the left, the interpretation written
# beside it — the left-object / right-text composition of ``vinyl`` and
# ``astrarium``. The emblem gets a tall panel, the quote a full column, and
# the vellum shows on every side of the card.
_TAROT_CARD_RECT = (34, 24, 294, 456)  # 260 x 432 — ratio 0.602
_TAROT_CARD_SHADOW = 4
_TAROT_READING_RECT = (324, 54, 768, 426)


def _tarot_paint_doubled_border(
    image: Image.Image, draw: ImageDraw.ImageDraw, rect: tuple[int, int, int, int],
) -> None:
    """Outer 3-px red rule + 2-px gap + inner 1-px black rule."""
    RED = SPECTRA6["red"]
    BLACK = SPECTRA6["black"]
    x0, y0, x1, y1 = rect
    # Outer red rule (3 px thick).
    for offset in range(3):
        draw.rectangle((x0 + offset, y0 + offset, x1 - offset, y1 - offset), outline=RED)
    # Inner black rule, 5 px inset (3 px outer + 2 px gap).
    draw.rectangle((x0 + 5, y0 + 5, x1 - 5, y1 - 5), outline=BLACK)


def _tarot_paint_corner_pips(
    draw: ImageDraw.ImageDraw, rect: tuple[int, int, int, int],
) -> None:
    """Small rubricated lozenges in the card's four inner corners.
    A red lozenge keeps the corners from reading as empty. Not the hour as
    corner indices: rotated Roman numerals misread (``XI`` becomes ``IX``),
    and Marseille / Rider-Waite trumps carry no indices — the numeral sits
    at the head and the name at the foot.
    """
    RED = SPECTRA6["red"]
    x0, y0, x1, y1 = rect
    inset = 17
    r = 4
    for px_x in (x0 + inset, x1 - inset):
        for px_y in (y0 + inset, y1 - inset):
            draw.polygon(
                [(px_x, px_y - r), (px_x + r, px_y), (px_x, px_y + r), (px_x - r, px_y)],
                fill=RED,
            )


def _tarot_paint_pentagram(
    draw: ImageDraw.ImageDraw, cx: float, cy: float, r: float, color: tuple,
) -> None:
    """Single five-point star as a 10-vertex polygon (alternating r_out/r_in)."""
    points: list[tuple[float, float]] = []
    for i in range(10):
        # Start at the top point (270°), alternate outer/inner radius.
        angle = -math.pi / 2 + i * math.pi / 5
        radius = r if i % 2 == 0 else r * 0.4
        points.append((cx + radius * math.cos(angle), cy + radius * math.sin(angle)))
    draw.polygon(points, fill=color)


def _tarot_paint_roman_numeral(
    image: Image.Image, draw: ImageDraw.ImageDraw, hour_int: int, cx: int, y_top: int,
) -> None:
    """Roman numeral hour in Cinzel Decorative Black 36, solid black."""
    BLACK = SPECTRA6["black"]
    font = load_font(theme_font_candidates("tarot", "ornament"), size=36)
    numeral = _TAROT_ROMAN_NUMERALS.get(hour_int, "—")
    bbox = draw.textbbox((0, 0), numeral, font=font)
    w = bbox[2] - bbox[0]
    draw.text((cx - w // 2 - bbox[0], y_top - bbox[1]), numeral, font=font, fill=BLACK)


# The name band's size is fitted to the card: the names span "Justice" to
# "The Wheel of Fortune" (~300 px at 22pt on a 260 px card). A real trump
# likewise sets a long title smaller.
_TAROT_NAME_SIZE_MAX = 22
_TAROT_NAME_SIZE_MIN = 12
# Inset from the card's outer edge. The inner black rule sits at 5 px;
# this leaves a further 7 px of breathing room either side.
_TAROT_NAME_INSET = 12


def _tarot_paint_card_name(
    image: Image.Image, draw: ImageDraw.ImageDraw, name: str, rect: tuple[int, int, int, int], y_top: int,
) -> None:
    """The trump's name in Tyrian purple, Cinzel Decorative Bold, along the foot.

    Stepped down from ``_TAROT_NAME_SIZE_MAX`` until it fits the card's inner
    width. Below the floor the name is drawn anyway rather than truncated:
    every committed name fits well above it, so a spill means an unmeasured
    new entry, which is a louder signal than a silent cut.
    """
    RED = SPECTRA6["red"]
    BLUE = SPECTRA6["blue"]
    text = (name or "").upper().strip()
    if not text:
        return
    x0, _, x1, _ = rect
    cx = (x0 + x1) // 2
    budget = (x1 - x0) - 2 * _TAROT_NAME_INSET
    for size in range(_TAROT_NAME_SIZE_MAX, _TAROT_NAME_SIZE_MIN - 1, -1):
        font = load_font(theme_font_candidates("tarot", "quote_bold"), size=size)
        bbox = draw.textbbox((0, 0), text, font=font)
        if bbox[2] - bbox[0] <= budget:
            break
    w = bbox[2] - bbox[0]
    # Re-anchor so left edge of the bbox lands at the intended start.
    draw_text_dithered(
        image,
        (cx - w // 2 - bbox[0], y_top - bbox[1]),
        text,
        font=font,
        dark=RED,
        light=BLUE,
        light_density=0.5,
    )


# The emblems that read on the panel all resolve into a *figure* — a
# trapezoid robe under a head, with the trump's attribute held beside it;
# attributes with no figure give the eye nothing to assemble them onto. Most
# emblems are therefore drawn on the shared ``_tarot_robed_figure`` skeleton.
#
# Native coordinates stay inside ±70 horizontally and ±88 vertically: the
# illustration panel is 216 x 274 and _TAROT_EMBLEM_SCALE enlarges by 1.5,
# so anything beyond that is clipped at the keyline.


def _tarot_face(
    draw: ImageDraw.ImageDraw,
    cx: int,
    cy: int,
    r: int,
    *,
    hair: str = "none",
    gaze: int = 0,
) -> None:
    """Brows, eyes, nose and mouth inside a head circle.

    Two eyes and a mouth turn a circle over a trapezoid into a person, so
    the trump's attribute reads as *held*. Kept to five strokes because the
    head is only ~30 px across: brows as well as eyes, since a lone dot
    reads as a blemish. ``gaze`` shifts both pupils sideways so the figure
    can look at its attribute. ``hair`` is a coarse silhouette cue so the
    twelve heads aren't identical.
    """
    BLACK = SPECTRA6["black"]
    eye_dx = max(2, round(r * 0.36))
    eye_r = max(1, r // 7)
    eye_y = cy - max(1, r // 8)
    if hair == "long":
        # Two narrow falls either side of the face, drawn before the
        # features. Strokes, not filled polygons, which read as a helmet.
        for side in (-1, 1):
            draw.line(
                [
                    (cx + side * (r - 2), cy - r // 2),
                    (cx + side * (r + 2), cy + r // 2),
                    (cx + side * (r - 1), cy + r + 4),
                ],
                fill=BLACK, width=3, joint="curve",
            )
    if hair in ("long", "veil", "short"):
        # A shallow cap across the brow. The 215-325 arc leaves a forehead;
        # a wider chord (190-350) fills the top half solid — a helmet.
        draw.chord((cx - r, cy - r, cx + r, cy + r), 215, 325, fill=BLACK)
    for side in (-1, 1):
        ex = cx + side * eye_dx
        draw.line((ex - eye_r - 1, eye_y - eye_r - 2, ex + eye_r + 1, eye_y - eye_r - 2), fill=BLACK, width=1)
        draw.ellipse(
            (ex - eye_r + gaze, eye_y - eye_r, ex + eye_r + gaze, eye_y + eye_r),
            fill=BLACK,
        )
    draw.line((cx, eye_y + eye_r, cx, cy + r // 3), fill=BLACK, width=1)
    draw.line((cx - r // 3, cy + r // 2, cx + r // 3, cy + r // 2), fill=BLACK, width=1)
    if hair == "beard":
        # Outline plus two interior strokes: a solid wedge would swallow
        # the mouth.
        draw.polygon(
            [
                (cx - r + 3, cy + r // 2),
                (cx + r - 3, cy + r // 2),
                (cx + r // 3, cy + r + 8),
                (cx - r // 3, cy + r + 8),
            ],
            outline=BLACK, width=2,
        )
        for side in (-1, 1):
            draw.line(
                (cx + side * r // 3, cy + r // 2 + 2, cx + side * r // 5, cy + r + 5),
                fill=BLACK, width=1,
            )


def _tarot_drapery(
    draw: ImageDraw.ImageDraw,
    cx: int,
    shoulder_y: int,
    hem_y: int,
    half_top: int,
    half_bot: int,
    folds: int = 4,
) -> None:
    """Fold lines down the inside of a robe, at one third the outline weight.

    The folds are hairlines against the outline's 3 px, so the eye reads a
    hierarchy — contour, then interior detail — which separates a drawing
    from clip art. Each fold fans from near the neck to its own place on
    the hem, since parallel verticals read as stripes.
    """
    BLACK = SPECTRA6["black"]
    # Fixed offsets rather than an RNG (the frame must stay byte-
    # deterministic): evenly spaced folds read as accordion pleats.
    jitter = (0.0, 0.13, -0.09, 0.06, -0.15)
    for i in range(1, folds + 1):
        t = i / (folds + 1) + jitter[i % len(jitter)] * 0.5
        x_top = cx + round((t - 0.5) * 2 * half_top * 0.55)
        x_bot = cx + round((t - 0.5) * 2 * half_bot * 0.88)
        mid_y = shoulder_y + (hem_y - shoulder_y) * (0.5 + jitter[i % len(jitter)])
        mid_x = x_top + (x_bot - x_top) * 0.45
        draw.line(
            [(x_top, shoulder_y + 4), (mid_x, mid_y), (x_bot, hem_y - 2)],
            fill=BLACK, width=1, joint="curve",
        )


def _tarot_hand(draw: ImageDraw.ImageDraw, x: float, y: float, r: int = 4) -> None:
    """A small filled disc terminating an arm.

    Crude on purpose — at this scale a modelled hand is ambiguous pixels.
    The arm must *end* in something so the attribute reads as gripped.
    """
    draw.ellipse((x - r, y - r, x + r, y + r), fill=SPECTRA6["black"])


def _tarot_arm(
    draw: ImageDraw.ImageDraw,
    x0: float, y0: float, x1: float, y1: float,
    *, elbow: float = 0.35, hand: bool = True,
) -> tuple[float, float]:
    """A two-segment arm from shoulder to hand. Returns the hand's centre.

    One bend reads as a limb where a straight line reads as a stick.
    ``elbow`` displaces the joint perpendicular to the shoulder-to-hand
    line, so the bend follows the reach.
    """
    BLACK = SPECTRA6["black"]
    mx, my = (x0 + x1) / 2, (y0 + y1) / 2
    dx, dy = x1 - x0, y1 - y0
    span = math.hypot(dx, dy) or 1
    ex, ey = mx - dy / span * span * elbow * 0.35, my + dx / span * span * elbow * 0.35
    draw.line([(x0, y0), (ex, ey), (x1, y1)], fill=BLACK, width=3, joint="curve")
    if hand:
        _tarot_hand(draw, x1, y1)
    return x1, y1


def _tarot_robed_figure(
    draw: ImageDraw.ImageDraw,
    cx: int,
    cy: int,
    top: int,
    bottom: int,
    half_w: int,
    *,
    hair: str = "none",
    gaze: int = 0,
    folds: int = 4,
) -> tuple[int, int]:
    """Head over a trapezoid robe, with a face and drapery. Returns (cx, cy) of the head.

    ``top`` is the crown of the head and ``bottom`` the hem, both relative
    to the emblem centre; the head is sized from the gap so a short figure
    is not all head. Shared by most emblems so the set reads as one hand.
    """
    BLACK = SPECTRA6["black"]
    head_r = max(9, (bottom - top) // 7)
    head_cy = cy + top + head_r
    draw.ellipse(
        (cx - head_r, head_cy - head_r, cx + head_r, head_cy + head_r),
        outline=BLACK, width=3,
    )
    _tarot_face(draw, cx, head_cy, head_r, hair=hair, gaze=gaze)
    shoulder = head_cy + head_r + 4
    half_top = head_r + 6
    draw.polygon(
        [
            (cx - half_top, shoulder),
            (cx + half_top, shoulder),
            (cx + half_w, cy + bottom),
            (cx - half_w, cy + bottom),
        ],
        outline=BLACK, width=3,
    )
    _tarot_drapery(draw, cx, shoulder, cy + bottom, half_top, half_w, folds=folds)
    return cx, head_cy


def _tarot_crown(draw: ImageDraw.ImageDraw, cx: int, base_y: int, half_w: int) -> None:
    """Three-spike crown sitting on a band — the head's, not free-floating."""
    BLACK = SPECTRA6["black"]
    draw.rectangle((cx - half_w, base_y - 5, cx + half_w, base_y), fill=BLACK)
    step = half_w
    for tip_x in (cx - step, cx, cx + step):
        draw.polygon(
            [(tip_x - 5, base_y - 5), (tip_x, base_y - 17), (tip_x + 5, base_y - 5)],
            fill=BLACK,
        )


def _tarot_emblem_magician(draw: ImageDraw.ImageDraw, cx: int, cy: int) -> None:
    """Magician (I): one arm raised to the wand, one pointing down.

    "As above, so below" is the gesture of this trump, and it needs two
    arms and a body; the lemniscate and the four tools annotate it.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    _, head_cy = _tarot_robed_figure(draw, cx, cy, top=-46, bottom=44, half_w=34)
    # Lemniscate hovering above the head.
    draw.arc((cx - 30, cy - 76, cx - 2, cy - 58), 0, 360, fill=BLACK, width=3)
    draw.arc((cx + 2, cy - 76, cx + 30, cy - 58), 0, 360, fill=BLACK, width=3)
    # Raised arm to the wand held aloft on the right.
    draw.line((cx + 12, cy - 12, cx + 44, cy - 34), fill=BLACK, width=3)
    draw.line((cx + 44, cy - 34, cx + 52, cy - 84), fill=BLACK, width=4)
    draw.ellipse((cx + 44, cy - 94, cx + 60, cy - 78), fill=RED)
    # Lowered arm pointing at the earth on the left.
    draw.line((cx - 12, cy - 12, cx - 44, cy + 16), fill=BLACK, width=3)
    draw.line((cx - 44, cy + 16, cx - 52, cy + 34), fill=BLACK, width=3)
    # Altar of the four suit tools across the foot.
    altar_y = cy + 62
    draw.rectangle((cx - 62, altar_y, cx + 62, altar_y + 6), fill=BLACK)
    sx = cx - 46  # cup
    draw.arc((sx - 10, altar_y - 20, sx + 10, altar_y), 0, 180, fill=RED, width=3)
    draw.line((sx - 10, altar_y - 10, sx - 10, altar_y - 20), fill=RED, width=3)
    draw.line((sx + 10, altar_y - 10, sx + 10, altar_y - 20), fill=RED, width=3)
    sx = cx - 16  # wand
    draw.line((sx, altar_y - 22, sx, altar_y - 2), fill=BLACK, width=3)
    draw.ellipse((sx - 5, altar_y - 28, sx + 5, altar_y - 18), fill=RED)
    sx = cx + 16  # sword
    draw.line((sx, altar_y - 24, sx, altar_y - 2), fill=BLACK, width=3)
    draw.line((sx - 8, altar_y - 16, sx + 8, altar_y - 16), fill=BLACK, width=3)
    _tarot_paint_pentagram(draw, cx + 46, altar_y - 12, 11, RED)  # pentacle


def _tarot_emblem_hermit(draw: ImageDraw.ImageDraw, cx: int, cy: int) -> None:
    """Hermit (IX): hooded silhouette with a raised lantern (a red star
    flame inside) and a diagonal staff.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    # Hooded silhouette: a triangle robe with a smaller triangle hood.
    robe = [
        (cx - 32, cy + 80),  # left foot
        (cx - 16, cy + 8),   # left shoulder
        (cx - 10, cy - 20),  # neck (left side of hood)
        (cx + 14, cy - 20),  # neck (right side of hood)
        (cx + 20, cy + 8),   # right shoulder
        (cx + 36, cy + 80),  # right foot
    ]
    draw.polygon(robe, fill=BLACK)
    # Hood: pointed peak above the head.
    hood = [
        (cx - 14, cy - 18),
        (cx + 2, cy - 50),
        (cx + 18, cy - 18),
    ]
    draw.polygon(hood, fill=BLACK)
    # Diagonal staff from the right shoulder to the ground.
    draw.line((cx + 18, cy + 4, cx + 60, cy + 90), fill=BLACK, width=4)
    # Raised lantern above the left shoulder.
    lx0, ly0, lx1, ly1 = cx - 60, cy - 50, cx - 28, cy - 14
    draw.rectangle((lx0, ly0, lx1, ly1), outline=BLACK, width=3)
    # Lantern panes — two vertical bars dividing the front face into 3.
    third = (lx1 - lx0) // 3
    draw.line((lx0 + third, ly0 + 2, lx0 + third, ly1 - 2), fill=BLACK, width=1)
    draw.line((lx0 + 2 * third, ly0 + 2, lx0 + 2 * third, ly1 - 2), fill=BLACK, width=1)
    # Lantern bail (handle).
    bail_cx = (lx0 + lx1) // 2
    draw.line((bail_cx, ly0, bail_cx, ly0 - 10), fill=BLACK, width=2)
    draw.arc((lx0 + 2, ly0 - 14, lx1 - 2, ly0 - 4), 0, 180, fill=BLACK, width=2)
    # Holding-arm line from lantern bail up to figure's hand.
    draw.line((bail_cx, ly0 - 10, cx - 10, cy - 14), fill=BLACK, width=2)
    # Flame inside the lantern — a red 12-point star.
    fx, fy = bail_cx, (ly0 + ly1) // 2
    flame_pts: list[tuple[float, float]] = []
    for i in range(24):
        angle = -math.pi / 2 + i * math.pi / 12
        r = 12 if i % 2 == 0 else 5
        flame_pts.append((fx + r * math.cos(angle), fy + r * math.sin(angle)))
    draw.polygon(flame_pts, fill=RED)


def _tarot_emblem_wheel(draw: ImageDraw.ImageDraw, cx: int, cy: int) -> None:
    """Wheel of Fortune (X): concentric rims with spokes, a red hub, and
    four letters (T A R O) at the cardinal points of the rim band.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    r_outer = 88
    r_mid = 70
    r_inner = 40
    r_hub = 16
    # Outer rim.
    draw.ellipse((cx - r_outer, cy - r_outer, cx + r_outer, cy + r_outer), outline=BLACK, width=4)
    # Mid rim (inscribed band).
    draw.ellipse((cx - r_mid, cy - r_mid, cx + r_mid, cy + r_mid), outline=BLACK, width=2)
    # Inner rim.
    draw.ellipse((cx - r_inner, cy - r_inner, cx + r_inner, cy + r_inner), outline=BLACK, width=2)
    # Eight spokes from inner rim to mid rim — the wheel's structural axles.
    for i in range(8):
        angle = i * math.pi / 4
        x1 = cx + r_inner * math.cos(angle)
        y1 = cy + r_inner * math.sin(angle)
        x2 = cx + r_mid * math.cos(angle)
        y2 = cy + r_mid * math.sin(angle)
        draw.line((x1, y1, x2, y2), fill=BLACK, width=2)
    # Red filled hub at the centre.
    draw.ellipse((cx - r_hub, cy - r_hub, cx + r_hub, cy + r_hub), fill=RED)
    # Cardinal letters in the band between the mid and outer rims.
    sigil_r = (r_outer + r_mid) // 2
    sigil_font = load_font(theme_font_candidates("tarot", "ornament"), size=14)
    for angle_deg, glyph in ((-90, "T"), (0, "A"), (90, "R"), (180, "O")):
        angle = math.radians(angle_deg)
        sx = cx + sigil_r * math.cos(angle)
        sy = cy + sigil_r * math.sin(angle)
        bbox = draw.textbbox((0, 0), glyph, font=sigil_font)
        gw = bbox[2] - bbox[0]
        gh = bbox[3] - bbox[1]
        draw.text((sx - gw // 2 - bbox[0], sy - gh // 2 - bbox[1]), glyph, font=sigil_font, fill=BLACK)
    # Engraver's divisions on the outer rim every 30°.
    for i in range(12):
        angle = i * math.pi / 6
        x1 = cx + (r_outer - 6) * math.cos(angle)
        y1 = cy + (r_outer - 6) * math.sin(angle)
        x2 = cx + r_outer * math.cos(angle)
        y2 = cy + r_outer * math.sin(angle)
        draw.line((x1, y1, x2, y2), fill=BLACK, width=1)


def _tarot_emblem_default(draw: ImageDraw.ImageDraw, cx: int, cy: int) -> None:
    """Generic red pentagram in a double circle with twelve radial ticks —
    the fallback for hours without a dedicated emblem.
    """
    RED = SPECTRA6["red"]
    BLACK = SPECTRA6["black"]
    # Inscribed circle behind the star.
    draw.ellipse((cx - 90, cy - 90, cx + 90, cy + 90), outline=BLACK, width=2)
    draw.ellipse((cx - 72, cy - 72, cx + 72, cy + 72), outline=BLACK, width=1)
    # Big pentagram.
    _tarot_paint_pentagram(draw, cx, cy, 70, RED)
    # Twelve radial dashes around the outer ring — clock-face ticks.
    for i in range(12):
        angle = i * math.pi / 6
        x1 = cx + 96 * math.cos(angle)
        y1 = cy + 96 * math.sin(angle)
        x2 = cx + 104 * math.cos(angle)
        y2 = cy + 104 * math.sin(angle)
        draw.line((x1, y1, x2, y2), fill=BLACK, width=1)


def _tarot_emblem_priestess(draw: ImageDraw.ImageDraw, cx: int, cy: int) -> None:
    """High Priestess (II): two pillars (B / J) flanking a crescent moon.

    The Rider-Waite Priestess sits between the pillars Boaz (left) and
    Jachin (right) with a crescent moon; a smaller moon rests at her feet.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    # Two pillars, left+right, height ~140.
    draw.rectangle((cx - 70, cy - 70, cx - 50, cy + 70), outline=BLACK, width=3)
    draw.rectangle((cx + 50, cy - 70, cx + 70, cy + 70), outline=BLACK, width=3)
    # Pillar capitals (cap blocks at the top of each).
    draw.rectangle((cx - 76, cy - 80, cx - 44, cy - 70), fill=BLACK)
    draw.rectangle((cx + 44, cy - 80, cx + 76, cy - 70), fill=BLACK)
    # "B" / "J" letters carved on the pillars.
    pillar_font = load_font(theme_font_candidates("tarot", "ornament"), size=18)
    for label, anchor_cx in (("B", cx - 60), ("J", cx + 60)):
        bbox = draw.textbbox((0, 0), label, font=pillar_font)
        gw = bbox[2] - bbox[0]
        gh = bbox[3] - bbox[1]
        draw.text(
            (anchor_cx - gw // 2 - bbox[0], cy - gh // 2 - bbox[1]),
            label, font=pillar_font, fill=BLACK,
        )
    # Crescent moon between the pillars: a disc with an offset knockout.
    moon_cx, moon_cy, moon_r = cx, cy - 50, 18
    draw.ellipse((moon_cx - moon_r, moon_cy - moon_r, moon_cx + moon_r, moon_cy + moon_r), fill=BLACK)
    # Knock out the right portion to create the crescent.
    knock_cx = moon_cx + 8
    draw.ellipse((knock_cx - moon_r, moon_cy - moon_r, knock_cx + moon_r, moon_cy + moon_r), fill=SPECTRA6["white"])
    # Scroll / TORA tablet at the priestess's lap (centred between pillars).
    scroll_cx, scroll_cy = cx, cy + 8
    draw.rectangle((scroll_cx - 16, scroll_cy - 12, scroll_cx + 16, scroll_cy + 12), outline=BLACK, width=2)
    # Three horizontal "text" hairlines on the scroll.
    for dy in (-5, 0, 5):
        draw.line((scroll_cx - 12, scroll_cy + dy, scroll_cx + 12, scroll_cy + dy), fill=BLACK, width=1)
    # Small red lunar dot at her feet — the moon she stands on.
    draw.ellipse((cx - 6, cy + 60, cx + 6, cy + 72), fill=RED)


def _tarot_emblem_empress(draw: ImageDraw.ImageDraw, cx: int, cy: int) -> None:
    """Empress (III): enthroned figure, twelve-star crown, wheat at her feet.

    The throne is a back behind the seated figure; drawn as the figure
    itself it read as a shield.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    # Throne back rising behind her.
    draw.polygon(
        [(cx - 58, cy + 76), (cx - 46, cy - 34), (cx + 46, cy - 34), (cx + 58, cy + 76)],
        outline=BLACK, width=3,
    )
    _, head_cy = _tarot_robed_figure(draw, cx, cy, top=-30, bottom=76, half_w=44, hair="long")
    # Corona stellarum duodecim — the twelve-star crown of Revelation 12.
    for i in range(12):
        angle = math.radians(200 + i * (140 / 11))
        sx = cx + 34 * math.cos(angle)
        sy = head_cy + 34 * math.sin(angle)
        draw.ellipse((sx - 2, sy - 2, sx + 2, sy + 2), fill=RED)
    # Heart shield resting against the robe.
    hy = cy + 18
    draw.polygon([
        (cx, hy + 14), (cx - 11, hy), (cx - 7, hy - 9),
        (cx, hy - 3), (cx + 7, hy - 9), (cx + 11, hy),
    ], fill=RED)
    # Wheat sheaf at her feet.
    for i in range(7):
        angle = math.radians(250 + i * 10)
        x2 = cx + 24 * math.cos(angle)
        y2 = cy + 86 + 24 * math.sin(angle)
        draw.line((cx, cy + 86, x2, y2), fill=BLACK, width=2)
        draw.ellipse((x2 - 2, y2 - 2, x2 + 2, y2 + 2), fill=BLACK)


def _tarot_emblem_emperor(draw: ImageDraw.ImageDraw, cx: int, cy: int) -> None:
    """Emperor (IV): seated crowned figure, ram finials, ankh and orb.

    The throne is two posts behind the seated figure (an empty rectangle
    read as a goalpost).
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    # Throne back: two posts flanking the figure, ram spirals on top.
    for post_x in (cx - 62, cx + 62):
        draw.line((post_x, cy - 44, post_x, cy + 76), fill=BLACK, width=5)
        draw.arc((post_x - 14, cy - 62, post_x + 14, cy - 34), 0, 360, fill=BLACK, width=3)
        draw.arc((post_x - 7, cy - 55, post_x + 7, cy - 41), 0, 360, fill=BLACK, width=2)
    draw.line((cx - 62, cy - 44, cx + 62, cy - 44), fill=BLACK, width=4)
    _, head_cy = _tarot_robed_figure(draw, cx, cy, top=-26, bottom=76, half_w=44)
    _tarot_crown(draw, cx, head_cy - 13, 11)
    # Ankh scepter (right hand) and orb of dominion (left).
    ax, ay = cx + 36, cy + 14
    draw.ellipse((ax - 8, ay - 18, ax + 8, ay - 2), outline=RED, width=3)
    draw.line((ax, ay - 2, ax, ay + 26), fill=RED, width=3)
    draw.line((ax - 11, ay + 8, ax + 11, ay + 8), fill=RED, width=3)
    draw.ellipse((cx - 44, cy + 8, cx - 26, cy + 26), fill=RED)


def _tarot_emblem_hierophant(draw: ImageDraw.ImageDraw, cx: int, cy: int) -> None:
    """Hierophant (V): bearded figure under the triregnum, hand raised in blessing.

    He holds the keys, and the tiara sits on a head with a face.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    _, head_cy = _tarot_robed_figure(draw, cx, cy, top=-24, bottom=74, half_w=42, hair="beard")
    # Triple tiara: three outlined tiers with air between them. Stacked
    # flush they merge into one solid trapezoid (a dunce cap); the bands
    # between the crowns are what make it read as three.
    base = head_cy - 14
    for top_w, bot_w, depth in ((32, 40, 0), (24, 32, 17), (17, 24, 34)):
        bot_y = base - depth
        top_y = bot_y - 12
        draw.polygon([
            (cx - bot_w // 2, bot_y), (cx - top_w // 2, top_y),
            (cx + top_w // 2, top_y), (cx + bot_w // 2, bot_y),
        ], outline=BLACK, width=2)
        draw.rectangle((cx - bot_w // 2, bot_y - 3, cx + bot_w // 2, bot_y), fill=BLACK)
    draw.line((cx, base - 46, cx, base - 58), fill=BLACK, width=2)
    draw.line((cx - 4, base - 54, cx + 4, base - 54), fill=BLACK, width=2)
    # Right hand raised in benediction, left holding the crossed keys.
    _tarot_arm(draw, cx + 16, cy + 6, cx + 44, cy - 22)
    _tarot_arm(draw, cx - 16, cy + 6, cx - 44, cy + 26)
    for sign in (-1, 1):
        draw.line((cx - 52, cy + 56 - sign * 12, cx - 22, cy + 26 + sign * 12), fill=RED, width=3)
    draw.ellipse((cx - 58, cy + 38, cx - 44, cy + 52), outline=RED, width=2)
    draw.ellipse((cx - 58, cy + 56, cx - 44, cy + 70), outline=RED, width=2)


def _tarot_emblem_lovers(draw: ImageDraw.ImageDraw, cx: int, cy: int) -> None:
    """Lovers (VI): two figures beneath the sun, a tree behind each.

    The figures are kept well apart and given bodies: overlapping discs
    merged into a single blot at panel distance.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    # Sun overhead with rays.
    draw.ellipse((cx - 15, cy - 88, cx + 15, cy - 58), fill=RED)
    for i in range(12):
        a = i * math.pi / 6
        draw.line(
            (cx + 19 * math.cos(a), cy - 73 + 19 * math.sin(a),
             cx + 29 * math.cos(a), cy - 73 + 29 * math.sin(a)),
            fill=RED, width=2,
        )
    # The two figures, well clear of each other.
    for fx in (cx - 38, cx + 38):
        _tarot_robed_figure(draw, fx, cy, top=-34, bottom=52, half_w=24)
    # A tree behind each at the outer margin. The canopy sits well above
    # the heads and larger than one, or it reads as a second face.
    for tx in (cx - 68, cx + 68):
        draw.line((tx, cy - 18, tx, cy + 52), fill=BLACK, width=3)
        draw.ellipse((tx - 18, cy - 54, tx + 18, cy - 18), outline=BLACK, width=3)
    # Joined hands between them — the union the trump is about.
    draw.line((cx - 20, cy + 6, cx + 20, cy + 6), fill=BLACK, width=3)
    draw.polygon(
        [(cx, cy - 2), (cx + 9, cy + 6), (cx, cy + 16), (cx - 9, cy + 6)],
        fill=RED,
    )


def _tarot_emblem_chariot(draw: ImageDraw.ImageDraw, cx: int, cy: int) -> None:
    """Chariot (VII): crowned charioteer riding a canopied car.

    The charioteer stands in the car as a full figure; a small head over
    the cab rim read as an unmanned cart.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    # Canopy roof and its four columns, behind the rider.
    draw.line((cx - 58, cy - 62, cx + 58, cy - 62), fill=BLACK, width=3)
    for col_x in (cx - 50, cx + 50):
        draw.line((col_x, cy - 62, col_x, cy + 26), fill=BLACK, width=2)
    _tarot_paint_pentagram(draw, cx, cy - 76, 11, RED)
    # The charioteer, hem hidden behind the car's front panel.
    _tarot_robed_figure(draw, cx, cy, top=-50, bottom=30, half_w=30, folds=3)
    # Car: front panel drawn after the figure so he stands *in* it.
    draw.rectangle((cx - 58, cy + 26, cx + 58, cy + 62), fill=SPECTRA6["white"], outline=BLACK, width=3)
    draw.line((cx - 58, cy + 34, cx + 58, cy + 34), fill=BLACK, width=1)
    for wheel_cx in (cx - 44, cx + 44):
        draw.ellipse((wheel_cx - 17, cy + 56, wheel_cx + 17, cy + 88), outline=BLACK, width=3)
        draw.line((wheel_cx, cy + 56, wheel_cx, cy + 88), fill=BLACK, width=2)
        draw.line((wheel_cx - 17, cy + 72, wheel_cx + 17, cy + 72), fill=BLACK, width=2)
        draw.ellipse((wheel_cx - 4, cy + 68, wheel_cx + 4, cy + 76), fill=RED)


def _tarot_emblem_strength(draw: ImageDraw.ImageDraw, cx: int, cy: int) -> None:
    """Strength (VIII): lion's head crowned by an infinity lemniscate.

    Distils the Rider-Waite card (a woman closing a lion's jaws under the
    lemniscate) to the maned lion's head and the lemniscate above it.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    # Infinity lemniscate at the top — two overlapping circles.
    draw.arc((cx - 44, cy - 100, cx, cy - 70), 0, 360, fill=BLACK, width=3)
    draw.arc((cx, cy - 100, cx + 44, cy - 70), 0, 360, fill=BLACK, width=3)
    # Lion's mane — many short black lines radiating outward from the head.
    head_cx, head_cy, head_r = cx, cy + 10, 36
    for i in range(28):
        angle = 2 * math.pi * i / 28
        # Vary the mane length slightly so it looks furry.
        r_out = head_r + (14 if i % 2 == 0 else 22)
        x1 = head_cx + head_r * math.cos(angle)
        y1 = head_cy + head_r * math.sin(angle)
        x2 = head_cx + r_out * math.cos(angle)
        y2 = head_cy + r_out * math.sin(angle)
        draw.line((x1, y1, x2, y2), fill=BLACK, width=2)
    # Lion's face — filled black circle with red eye dots and a stylised mouth.
    draw.ellipse((head_cx - head_r, head_cy - head_r, head_cx + head_r, head_cy + head_r), fill=BLACK)
    # Eyes.
    draw.ellipse((head_cx - 14, head_cy - 8, head_cx - 6, head_cy), fill=RED)
    draw.ellipse((head_cx + 6, head_cy - 8, head_cx + 14, head_cy), fill=RED)
    # Mouth — small red curve.
    draw.arc((head_cx - 10, head_cy + 4, head_cx + 10, head_cy + 20), 0, 180, fill=RED, width=2)
    # Two small fang triangles in the mouth.
    draw.polygon([(head_cx - 4, head_cy + 14), (head_cx - 2, head_cy + 20), (head_cx, head_cy + 14)], fill=SPECTRA6["white"])
    draw.polygon([(head_cx, head_cy + 14), (head_cx + 2, head_cy + 20), (head_cx + 4, head_cy + 14)], fill=SPECTRA6["white"])


def _tarot_emblem_justice(draw: ImageDraw.ImageDraw, cx: int, cy: int) -> None:
    """Justice (XI): crowned figure, sword raised right, scales held left.

    The sword in one hand and the scales in the other (the Rider-Waite
    composition) is what makes each attribute legible as itself.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    _, head_cy = _tarot_robed_figure(draw, cx, cy, top=-40, bottom=68, half_w=38)
    _tarot_crown(draw, cx, head_cy - 12, 10)
    # Sword raised in the right hand: blade up, crossguard, red pommel.
    sx = cx + 44
    draw.line((sx, cy - 66, sx, cy + 26), fill=BLACK, width=5)
    draw.line((sx - 14, cy + 12, sx + 14, cy + 12), fill=BLACK, width=4)
    draw.ellipse((sx - 6, cy + 26, sx + 6, cy + 38), fill=RED)
    draw.line((cx + 16, cy + 2, sx, cy + 18), fill=BLACK, width=3)
    # Scales held out in the left hand.
    # Held out clear of the robe: at half_w=38 the hem reaches cx-38, and
    # an inboard pan landed on top of it.
    hx, hy = cx - 52, cy - 22
    draw.line((cx - 16, cy - 4, hx, hy + 4), fill=BLACK, width=3)
    draw.line((hx, hy, hx, hy + 14), fill=BLACK, width=3)
    beam_y = hy + 14
    draw.line((hx - 18, beam_y, hx + 18, beam_y), fill=BLACK, width=3)
    for pan_x in (hx - 16, hx + 16):
        draw.line((pan_x, beam_y, pan_x, beam_y + 16), fill=BLACK, width=2)
        draw.polygon(
            [
                (pan_x - 13, beam_y + 16), (pan_x + 13, beam_y + 16),
                (pan_x + 9, beam_y + 26), (pan_x - 9, beam_y + 26),
            ],
            fill=BLACK,
        )
    draw.polygon(
        [(hx, beam_y - 5), (hx + 5, beam_y), (hx, beam_y + 5), (hx - 5, beam_y)],
        fill=RED,
    )


def _tarot_emblem_world(draw: ImageDraw.ImageDraw, cx: int, cy: int) -> None:
    """World (XII): dancing figure within a laurel wreath, four corner creatures.

    Distils the Rider-Waite card — the dancer in an oval laurel wreath with
    the four creatures at the corners — to the wreath, the figure and four
    small corner marks.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    # Laurel wreath — oval of small leaf shapes around a central oval.
    wreath_a, wreath_b = 60, 80  # semi-major / semi-minor axes
    n_leaves = 24
    for i in range(n_leaves):
        angle = 2 * math.pi * i / n_leaves
        ox = cx + wreath_a * math.cos(angle)
        oy = cy + wreath_b * math.sin(angle)
        # Leaf: small ellipse oriented tangent to the wreath.
        leaf_a, leaf_b = 8, 4
        # Polygon-approximated rotated ellipse (PIL has no rotate-ellipse).
        leaf_pts = []
        for j in range(8):
            la = 2 * math.pi * j / 8
            lx = leaf_a * math.cos(la)
            ly = leaf_b * math.sin(la)
            # Rotate by the wreath-tangent angle (perpendicular to radial).
            tangent = angle + math.pi / 2
            rx = lx * math.cos(tangent) - ly * math.sin(tangent)
            ry = lx * math.sin(tangent) + ly * math.cos(tangent)
            leaf_pts.append((ox + rx, oy + ry))
        draw.polygon(leaf_pts, fill=BLACK)
    # Dancing figure inside the wreath: the one unrobed trump (the dancer
    # is conventionally bare with a floating scarf), but with the same face.
    head_r = 11
    head_cy = cy - 30
    draw.ellipse(
        (cx - head_r, head_cy - head_r, cx + head_r, head_cy + head_r),
        outline=BLACK, width=3,
    )
    _tarot_face(draw, cx, head_cy, head_r, hair="short")
    draw.line((cx, head_cy + head_r, cx, cy + 12), fill=BLACK, width=4)
    _tarot_arm(draw, cx, cy - 12, cx - 26, cy - 30, elbow=-0.4)
    _tarot_arm(draw, cx, cy - 12, cx + 26, cy + 4, elbow=0.4)
    # Legs, one straight and one bent — the crossed-leg dancing pose.
    draw.line([(cx, cy + 12), (cx - 12, cy + 30), (cx - 18, cy + 48)], fill=BLACK, width=3, joint="curve")
    draw.line([(cx, cy + 12), (cx + 15, cy + 28), (cx + 5, cy + 46)], fill=BLACK, width=3, joint="curve")
    # The floating scarf, in the rubric red the rest of the card uses.
    draw.line(
        [(cx - 30, cy - 16), (cx - 8, cy - 4), (cx + 14, cy - 14), (cx + 32, cy - 2)],
        fill=RED, width=3, joint="curve",
    )
    # Wreath ribbons — two red bow-knots at top and bottom where the wreath ties.
    draw.ellipse((cx - 6, cy - 86, cx + 6, cy - 74), fill=RED)
    draw.ellipse((cx - 6, cy + 74, cx + 6, cy + 86), fill=RED)
    # The four creatures as small red pentagrams. Kept within ±62 x: at
    # ±90 the illustration panel clipped them away entirely.
    for corner_cx in (cx - 62, cx + 62):
        for corner_cy in (cy - 66, cy + 66):
            _tarot_paint_pentagram(draw, corner_cx, corner_cy, 7, RED)


_TAROT_EMBLEMS = {
    1: _tarot_emblem_magician,
    2: _tarot_emblem_priestess,
    3: _tarot_emblem_empress,
    4: _tarot_emblem_emperor,
    5: _tarot_emblem_hierophant,
    6: _tarot_emblem_lovers,
    7: _tarot_emblem_chariot,
    8: _tarot_emblem_strength,
    9: _tarot_emblem_hermit,
    10: _tarot_emblem_wheel,
    11: _tarot_emblem_justice,
    12: _tarot_emblem_world,
}


# The emblems are drawn at native size and the tile enlarged, rather than
# re-scaling twelve hand-tuned coordinate sets; the enlargement also
# thickens every stroke (2 px → 3 px), giving the line figures a woodcut's
# weight.
_TAROT_EMBLEM_SCALE = 1.5
# Native half-extent of the largest emblem (the Magician's staff reaches
# ~100 px above centre); the tile must hold the whole figure.
_TAROT_EMBLEM_TILE = 240
# The emblems paint in black and red plus a few white knockouts (the
# Priestess's moon, Strength's fangs, the Chariot's front panel). Enlarging
# is done in RGB rather than per-ink masks because masks lose the draw
# order, and a knockout only works stamped after its black ground.
_TAROT_EMBLEM_INKS = [SPECTRA6["white"], SPECTRA6["black"], SPECTRA6["red"]]


def _tarot_plate_tile(hour_int: int) -> Image.Image | None:
    """One trump cropped from the committed sprite sheet, or ``None``.

    The sheet is decoded once per process and memoised, so a render pays a
    crop rather than a decode (it matters for the 144-frame contact sheet).

    Hour maps to trump number directly, keeping the plate's Marseille
    numbering in step with the Roman hour painted above it.
    """
    if not TAROT_PLATES.exists():
        return None
    sheet = _TAROT_PLATE_CACHE.get("sheet")
    if sheet is None:
        try:
            with Image.open(TAROT_PLATES) as raw:
                sheet = raw.convert("RGB")
        except (OSError, ValueError):
            return None
        _TAROT_PLATE_CACHE["sheet"] = sheet
    tw = sheet.width // _TAROT_PLATE_COLS
    th = sheet.height // _TAROT_PLATE_ROWS
    i = (hour_int - 1) % (_TAROT_PLATE_COLS * _TAROT_PLATE_ROWS)
    col, row = i % _TAROT_PLATE_COLS, i // _TAROT_PLATE_COLS
    return sheet.crop((col * tw, row * th, (col + 1) * tw, (row + 1) * th))


def _tarot_stamp_tile(
    image: Image.Image,
    tile: Image.Image,
    cx: int,
    cy: int,
    clip: tuple[int, int, int, int] | None,
) -> None:
    """Stamp a tile centred on (cx, cy), skipping white and honouring ``clip``.

    White is skipped so the card's cream wash shows through the figure's
    negative space. The plate tile is exactly panel-sized, so ``clip`` is a
    no-op for it; the oversized polygon tile relies on it.
    """
    px = image.load()
    src = tile.load()
    w, h = image.size
    ox = cx - tile.width // 2
    oy = cy - tile.height // 2
    lo_x, lo_y, hi_x, hi_y = (0, 0, w, h) if clip is None else clip
    # Inset by one so the stamp never lands on the keyline itself.
    lo_x, lo_y = max(0, lo_x + 1), max(0, lo_y + 1)
    hi_x, hi_y = min(w, hi_x), min(h, hi_y)
    WHITE = SPECTRA6["white"]
    for ty in range(tile.height):
        y = oy + ty
        if not lo_y <= y < hi_y:
            continue
        for tx in range(tile.width):
            x = ox + tx
            if not lo_x <= x < hi_x:
                continue
            ink = src[tx, ty]
            if ink != WHITE:
                px[x, y] = ink


def _tarot_paint_emblem(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    hour_int: int,
    cx: int,
    cy: int,
    clip: tuple[int, int, int, int] | None = None,
) -> str:
    """Stamp the hour's trump: the committed Dodal plate, else the painter.

    The painter's figure is drawn at native size onto a white tile, scaled
    by ``_TAROT_EMBLEM_SCALE``, snapped back to its three inks, and stamped
    with white skipped.

    ``clip`` bounds the stamp to the illustration panel: the widest
    emblems reach past the keyline once enlarged, and a figure crossing its
    frame reads as a layout fault. Clipping rather than shrinking keeps the
    stroke weight.

    Returns the drawn trump's name, so the card is titled by the same call
    that chose the figure — the two sources number three of the twelve
    hours differently (see ``_TAROT_TRUMP_NAMES``).
    """
    tile = _tarot_plate_tile(hour_int)
    if tile is not None:
        _tarot_stamp_tile(image, tile, cx, cy, clip)
        return _TAROT_TRUMP_NAMES.get(hour_int, "")

    painter = _TAROT_EMBLEMS.get(hour_int, _tarot_emblem_default)
    size = _TAROT_EMBLEM_TILE
    half = size // 2
    tile = Image.new("RGB", (size, size), SPECTRA6["white"])
    painter(ImageDraw.Draw(tile), half, half)
    scaled = size * _TAROT_EMBLEM_SCALE
    tile = tile.resize((round(scaled), round(scaled)), Image.LANCZOS)
    tile = snap_image_to_palette(tile, _TAROT_EMBLEM_INKS)
    _tarot_stamp_tile(image, tile, cx, cy, clip)
    return _TAROT_PAINTER_TRUMP_NAMES.get(hour_int, "")


def _tarot_paint_body_panel(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    rect: tuple[int, int, int, int],
) -> None:
    """Knock out a clean cream "interpretation panel" beneath the emblem.

    The card-stock foxing breaks up EB Garamond's hairlines and muddles the
    purple matched-phrase dither, so the body region is overpainted with a
    clean cream wash (Y+W at 1-in-8, no R+G dots) and framed with a thin red
    rule, so the knockout reads as a deliberate cartouche.
    """
    WHITE = SPECTRA6["white"]
    YELLOW = SPECTRA6["yellow"]
    RED = SPECTRA6["red"]
    x0, y0, x1, y1 = rect
    # Step 1: solid white wipe — clears any foxing dots within the panel.
    draw.rectangle((x0, y0, x1, y1), fill=WHITE)
    # Step 2: a fresh cream wash so the panel still matches the vellum.
    px = image.load()
    # Clip the PixelAccess writes: the fixed 800x480 coordinates overrun
    # smaller canvases.
    w, h = image.size
    for y in range(max(0, y0), min(h, y1)):
        row = BAYER_4x4[y % 4]
        for x in range(max(0, x0), min(w, x1)):
            if row[x % 4] < 2:
                px[x, y] = YELLOW
    # Step 3: thin red rule framing the panel.
    draw.rectangle((x0, y0, x1, y1), outline=RED, width=1)


def _tarot_paint_body(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    quote_row: dict,
    rect: tuple[int, int, int, int],
) -> None:
    """Quote body fitted into ``rect`` with matched-phrase Tyrian purple.

    Expects ``_tarot_paint_body_panel`` to have knocked out a clean panel
    under ``rect`` first.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    BLUE = SPECTRA6["blue"]
    x0, y0, x1, y1 = rect
    width = x1 - x0
    height = y1 - y0
    # Inset slightly from the panel edge so glyphs don't kiss the red rule.
    pad = 8
    width -= 2 * pad
    height -= 2 * pad
    x0 += pad
    y0 += pad
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    matched = quote_row.get("matched_text") or ""

    quote_font, quote_font_bold, wrapped_quote, line_height, _ = fit_quote(
        draw,
        display_quote,
        matched,
        width,
        height,
        font_max=26,
        font_min=15,
        line_height_mult=1.24,
        theme="tarot",
    )
    quote_block_height = len(wrapped_quote) * line_height
    block_top = y0 + max(0, (height - quote_block_height) // 2)
    body_ascent = _font_ascent(quote_font)
    y = block_top
    for line in wrapped_quote:
        # Trim leading/trailing whitespace tokens.
        start = 0
        while start < len(line) and line[start][0].strip() == "":
            start += 1
        end = len(line)
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        drawable = line[start:end]
        # Centre the line horizontally.
        line_width = 0
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            bbox = draw.textbbox((0, 0), chunk, font=font)
            line_width += bbox[2] - bbox[0]
        x = x0 + max(0, (width - line_width) // 2)
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            chunk_y = y + (body_ascent - _font_ascent(font))
            if is_bold:
                draw_text_dithered(
                    image, (x, chunk_y), chunk, font=font,
                    dark=RED, light=BLUE, light_density=0.5,
                )
            else:
                draw.text((x, chunk_y), chunk, font=font, fill=BLACK)
            bbox = draw.textbbox((0, 0), chunk, font=font)
            x += bbox[2] - bbox[0]
        y += line_height


def _tarot_paint_attribution(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    quote_row: dict,
    cx: int,
    y_top: int,
    max_w: int,
) -> None:
    """Author · title in Cinzel Decorative Regular 12, solid black, centred.

    ``max_w`` is passed by the caller (the reading panel's inner width), so
    the byline can never cross the cartouche's rule.
    """
    BLACK = SPECTRA6["black"]
    font = load_font(theme_font_candidates("tarot", "ornament"), size=12)
    fitted = _fit_dotted_byline(draw, quote_row, font, max_w)
    if fitted is None:
        return
    text, bbox = fitted
    w = bbox[2] - bbox[0]
    draw.text((cx - w // 2 - bbox[0], y_top - bbox[1]), text, font=font, fill=BLACK)


def _tarot_paint_card_stock(
    image: Image.Image, draw: ImageDraw.ImageDraw, rect: tuple[int, int, int, int],
) -> None:
    """Lay the card onto the cloth: drop shadow, then a cleaner stock.

    The card and the cloth share a recipe, so without a tonal split the
    card's border reads as a rule drawn *on* the cloth. The interior is
    re-washed at a lower cream density with no foxing, and lifted by a black
    shadow ledge on the lower-right (as ``kanagawa`` / ``pride`` do).
    """
    WHITE = SPECTRA6["white"]
    YELLOW = SPECTRA6["yellow"]
    BLACK = SPECTRA6["black"]
    x0, y0, x1, y1 = rect
    off = _TAROT_CARD_SHADOW
    draw.rectangle((x0 + off, y0 + off, x1 + off, y1 + off), fill=BLACK)
    draw.rectangle((x0, y0, x1, y1), fill=WHITE)
    card_w = max(0, min(image.width, x1 + 1) - max(0, x0))
    card_h = max(0, min(image.height, y1 + 1) - max(0, y0))
    if not card_w or not card_h:
        return
    cut = round(_TAROT_CREAM_DENSITY * 0.75 * 255)
    stock = _white_noise(card_w, card_h, _TAROT_CREAM_SEED)
    image.paste(YELLOW, (max(0, x0), max(0, y0)), stock.point(lambda v: 255 if v < cut else 0))


def _tarot_paint_emblem_panel(
    draw: ImageDraw.ImageDraw, rect: tuple[int, int, int, int],
) -> None:
    """Thin keyline around the trump illustration.

    Historical trumps set the figure inside a ruled panel; without it the
    compact line emblems read as clip art floating on the stock.
    """
    draw.rectangle(rect, outline=SPECTRA6["black"], width=1)


def render_tarot_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A single trump laid on a reading cloth, interpretation beside it.

    Left: a portrait card on foxed vellum — doubled red+black rule, corner
    lozenges, the Roman-numeral hour above a ruled illustration panel, and
    the trump's name along the foot (the layout every historical trump
    uses). The time itself stays in the quote's matched phrase.

    Right: the reading — a clean cream cartouche carrying the quote in EB
    Garamond with a Tyrian-purple matched phrase, attribution at its foot.
    """
    # Composed at the canonical 800x480 and NEAREST-downsampled otherwise
    # (the ``metro`` convention): every rectangle is an absolute panel
    # coordinate, and a direct small render would put the reading panel
    # off-canvas.
    image = Image.new("RGB", (800, 480), color=SPECTRA6["white"])
    _tarot_paint_vellum(image)
    draw = ImageDraw.Draw(image)

    hour_int = _clock_hour12(time_str)

    # ── the card ──────────────────────────────────────────────────────
    card_rect = _TAROT_CARD_RECT
    x0, y0, x1, y1 = card_rect
    card_cx = (x0 + x1) // 2
    _tarot_paint_card_stock(image, draw, card_rect)
    _tarot_paint_doubled_border(image, draw, card_rect)
    _tarot_paint_corner_pips(draw, card_rect)
    _tarot_paint_roman_numeral(image, draw, hour_int, card_cx, y0 + 20)

    # Illustration panel: the numeral and name bands are carved out of the
    # card's height first, and the emblem gets what is left.
    panel = (x0 + 20, y0 + 68, x1 - 20, y1 - 74)
    _tarot_paint_emblem_panel(draw, panel)
    trump = _tarot_paint_emblem(image, draw, hour_int, card_cx, (panel[1] + panel[3]) // 2, clip=panel)

    # The trump's name along the foot, titled by the emblem call itself.
    _tarot_paint_card_name(image, draw, trump, card_rect, y1 - 60)

    # ── the reading ───────────────────────────────────────────────────
    rx0, ry0, rx1, ry1 = _TAROT_READING_RECT
    _tarot_paint_body_panel(image, draw, (rx0, ry0, rx1, ry1))
    attribution_band = 30
    _tarot_paint_body(image, draw, quote_row, (rx0, ry0, rx1, ry1 - attribution_band))
    # The byline shares the body's inset from the panel rule, so it can
    # never be wider than the text it attributes.
    _tarot_paint_attribution(image, draw, quote_row, (rx0 + rx1) // 2, ry1 - 22, (rx1 - rx0) - 16)

    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ─── vinyl (turntable + record label) ────────────────────────────────────────

# Disc geometry. The platter must not fill the plinth: the disc is kept
# small enough that the tonearm pivot sits far enough from the spindle for
# a sane stylus position.
_VINYL_DISK_CX = 178
_VINYL_DISK_CY = 246
_VINYL_DISK_R = 168
_VINYL_LABEL_R = 76


def _vinyl_paint_wear_speckle(image: Image.Image, seed: int) -> None:
    """Sparse 1-in-32 black speckle on the sleeve, daily-seeded for variation.

    Only flips white or yellow (cream-wash) pixels, so the disc and other
    graphics are untouched.
    """
    BLACK = SPECTRA6["black"]
    WHITE = SPECTRA6["white"]
    YELLOW = SPECTRA6["yellow"]
    rng = random.Random(seed)
    px = image.load()
    w, h = image.size
    # Only on the right half (sleeve region — x >= 400).
    for y in range(0, h, 2):
        for x in range(400, w, 2):
            if rng.random() < 1 / 32 and px[x, y] in (WHITE, YELLOW):
                px[x, y] = BLACK


# Programme-band sheen. Peak density stays low because a record is black:
# a satin hint of reflection, not a silver ring. The light jitter only
# dissolves the residual tile lattice (bakelite's ordered-plus-jitter
# recipe; hash alone at this density reads as sandpaper).
_VINYL_SHEEN_BANDS = 6
_VINYL_SHEEN_PEAK = 0.20
_VINYL_SHEEN_JITTER = 0.20


def _vinyl_paint_disk(
    image: Image.Image, draw: ImageDraw.ImageDraw, cx: int, cy: int, r_outer: int, r_label: int,
) -> None:
    """Solid black disk + densely-packed groove band + dead-wax + label + spindle.

    Three concentric pressing zones, after a real 12-inch LP:

    1. Dead wax (``r_label`` → ``r_label + 12``): left smooth black.
    2. Programme band (``r_label + 12`` → ``r_outer - 10``): a smooth radial
       **sheen**, painted per pixel — a cosine density ramp peaking on each
       reflection band, dithered on ``BAYER_8x8`` with a light
       :func:`position_noise` jitter.

       Deliberately not hairline grooves: groove pitch is unresolvable at
       viewing distance, packed 1-px rasterised rings beat into radial
       moiré, and many white rings turn the disc grey. A smooth per-pixel
       ramp has no rasterisation phase and gives the dither nothing
       periodic to alias against.
    3. Lead-in groove near the rim: a single 2-px white ring.
    """
    BLACK = SPECTRA6["black"]
    WHITE = SPECTRA6["white"]
    # Outer disk.
    draw.ellipse((cx - r_outer, cy - r_outer, cx + r_outer, cy + r_outer), fill=BLACK)

    # Programme band — a smooth radial *sheen*, painted per pixel.
    px = image.load()
    w, h = image.size
    lo, hi = r_label + 12, r_outer - 10
    span = max(1, hi - lo)
    x0, y0 = max(0, cx - r_outer), max(0, cy - r_outer)
    x1, y1 = min(w, cx + r_outer + 1), min(h, cy + r_outer + 1)
    for y in range(y0, y1):
        dy = y - cy
        for x in range(x0, x1):
            dx = x - cx
            radius = math.hypot(dx, dy)
            if not (lo <= radius <= hi):
                continue
            # Smooth cosine banding, with no hard periodic edge for the
            # dither tile to beat against.
            phase = (radius - lo) / span * _VINYL_SHEEN_BANDS * 2 * math.pi
            amp = ((math.cos(phase) + 1) / 2) ** 1.6
            rank = BAYER_8x8[y % 8][x % 8] + (position_noise(x, y) / 255 - 0.5) * 64 * _VINYL_SHEEN_JITTER
            if rank < amp * _VINYL_SHEEN_PEAK * 64:
                px[x, y] = WHITE

    # Lead-in groove — an isolated drawn ring is fine; packed ones beat.
    lead_in_r = r_outer - 4
    draw.ellipse(
        (cx - lead_in_r, cy - lead_in_r, cx + lead_in_r, cy + lead_in_r),
        outline=WHITE, width=2,
    )
    # The label fill and spindle are painted by ``_vinyl_paint_label``, after
    # the tonearm, so the label covers any part of the arm crossing it.


def _vinyl_paint_label(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    cx: int,
    cy: int,
    r_label: int,
    matched_text: str,
    bucket: str,
) -> None:
    """White-on-red label for a literary-audiobook LP.

    A music-LP label with the chrome reframed for the spoken-word labels
    (Caedmon, Spoken Arts, Listening Library) that pressed literary
    readings to vinyl.

    Composition top to bottom:

    * Black ring border, 2 px, inset 4 px from the label edge.
    * "SPOKEN WORD" format mark (the music LP's "STEREO").
    * The matched phrase, truncated to 18 chars, as the passage title.
    * A white hairline divider.
    * "IDLE HOURS" in Cormorant Bold 14pt.
    * "READ ALOUD" subtitle (a music LP's volume / side line).
    * Catalog number in Space Mono Bold ("IH-H11-15" etc).
    * The current year, small, at the bottom.

    Only the most iconic elements, so the label still reads at its ~76 px
    radius.
    """
    WHITE = SPECTRA6["white"]
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    # Label fill painted here, after the tonearm, so it covers the arm.
    draw.ellipse((cx - r_label, cy - r_label, cx + r_label, cy + r_label), fill=RED)
    # Outer black ring border — 2 px thick, inset 4 px from the label edge.
    ring_r = r_label - 4
    draw.ellipse((cx - ring_r, cy - ring_r, cx + ring_r, cy + ring_r), outline=BLACK, width=2)
    # SPOKEN WORD mark at the top of the label.
    format_font = load_font([(ANTONIO_VARIABLE, "Bold"), *META_FONT_BOLD_CANDIDATES], size=9)
    format_text = "· SPOKEN WORD ·"
    bbox = draw.textbbox((0, 0), format_text, font=format_font)
    w = bbox[2] - bbox[0]
    draw.text((cx - w // 2 - bbox[0], cy - 60 - bbox[1]), format_text, font=format_font, fill=WHITE)
    # Matched phrase (truncated) — the "track title".
    matched_font = load_font(theme_font_candidates("vinyl", "quote_bold"), size=11)
    snippet = (matched_text or "").strip()
    if len(snippet) > 18:
        snippet = snippet[:17] + "…"
    if snippet:
        bbox = draw.textbbox((0, 0), snippet, font=matched_font)
        w = bbox[2] - bbox[0]
        draw.text((cx - w // 2 - bbox[0], cy - 38 - bbox[1]), snippet, font=matched_font, fill=WHITE)
    # Hairline under matched phrase.
    draw.line((cx - r_label + 18, cy - 22, cx + r_label - 18, cy - 22), fill=WHITE, width=1)
    # IDLE HOURS line.
    title_font = load_font(theme_font_candidates("vinyl", "quote_bold"), size=14)
    title_text = "IDLE HOURS"
    bbox = draw.textbbox((0, 0), title_text, font=title_font)
    w = bbox[2] - bbox[0]
    draw.text((cx - w // 2 - bbox[0], cy - 18 - bbox[1]), title_text, font=title_font, fill=WHITE)
    # READ ALOUD subtitle.
    sub_font = load_font(theme_font_candidates("vinyl", "quote_regular"), size=11)
    sub_text = "READ ALOUD"
    bbox = draw.textbbox((0, 0), sub_text, font=sub_font)
    w = bbox[2] - bbox[0]
    draw.text((cx - w // 2 - bbox[0], cy + 8 - bbox[1]), sub_text, font=sub_font, fill=WHITE)
    # Catalog number (mono).
    cat_font = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=9)
    cat_text = _vinyl_catalog_number(bucket)
    bbox = draw.textbbox((0, 0), cat_text, font=cat_font)
    w = bbox[2] - bbox[0]
    draw.text((cx - w // 2 - bbox[0], cy + 28 - bbox[1]), cat_text, font=cat_font, fill=WHITE)
    # Current year at the bottom arc of the label.
    year_font = load_font([(ANTONIO_VARIABLE, "Bold"), *META_FONT_BOLD_CANDIDATES], size=9)
    year_text = f"© {datetime.date.today().year}"
    bbox = draw.textbbox((0, 0), year_text, font=year_font)
    w = bbox[2] - bbox[0]
    draw.text((cx - w // 2 - bbox[0], cy + 50 - bbox[1]), year_text, font=year_font, fill=WHITE)
    # Spindle hole, painted last so it sits on top of anything near centre.
    draw.ellipse((cx - 4, cy - 4, cx + 4, cy + 4), fill=WHITE)


# Tonearm mount, derived from the disc so the two cannot drift apart. The
# pivot sits 1.46x the record radius from the spindle (a real deck's 222 mm
# on a 152 mm record radius), behind and right of the platter.
_VINYL_PIVOT_DISTANCE_RATIO = 1.46
_VINYL_PIVOT_ANGLE_DEG = -40.0


def _vinyl_tonearm_pivot(cx: int, cy: int, r_outer: int) -> tuple[float, float]:
    """Where the arm's bearing sits, in panel coordinates."""
    d = r_outer * _VINYL_PIVOT_DISTANCE_RATIO
    ang = math.radians(_VINYL_PIVOT_ANGLE_DEG)
    return cx + d * math.cos(ang), cy + d * math.sin(ang)


# Tonearm geometry: 1.51x the disc radius is a 9-inch arm on a 12-inch
# record (230 mm effective length, 152 mm record radius), long enough for
# the stylus to reach outer edge to run-out within a narrow arc.
_VINYL_ARM_LENGTH_RATIO = 1.51
# Where the stylus stops at minute 59: just clear of the 76 px label, as a
# real run-out groove clears it by a few millimetres.
_VINYL_RUNOUT_RATIO = 0.55
_VINYL_COUNTERWEIGHT_OFFSET = 34


def _vinyl_paint_tonearm(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    cx: int,
    cy: int,
    r_outer: int,
    minute: int,
) -> None:
    """Pivoted tonearm whose stylus tracks *inward* across the hour.

    **The minute drives the stylus radius, not a rim angle.** A record
    plays outside-in, so minute 0 puts the stylus at the outer edge of the
    programme band and minute 59 near the run-out. The arm's angle falls out
    of the geometry: with the pivot a fixed distance ``d`` from the centre
    and arm length ``L``, the stylus is an intersection of the circle of
    radius ``r`` about the centre with the circle of radius ``L`` about the
    pivot (the two-circle solve below). This yields a ~23° sweep across the
    hour — visibly moving, never leaving the playing side.
    """
    BLACK = SPECTRA6["black"]
    WHITE = SPECTRA6["white"]
    RED = SPECTRA6["red"]
    pivot_x, pivot_y = _vinyl_tonearm_pivot(cx, cy, r_outer)
    arm_len = r_outer * _VINYL_ARM_LENGTH_RATIO

    # Stylus radius: outer edge of the programme band at minute 0,
    # creeping toward the run-out by minute 59.
    r_start = r_outer - 8
    r_end = r_outer * _VINYL_RUNOUT_RATIO
    frac = min(max(minute, 0), 59) / 59.0
    r_stylus = r_start + (r_end - r_start) * frac

    d = math.hypot(pivot_x - cx, pivot_y - cy)
    if d < 1:
        return
    # Two-circle intersection: |S - C| = r_stylus, |S - P| = arm_len.
    a = (r_stylus * r_stylus - arm_len * arm_len + d * d) / (2 * d)
    h_sq = r_stylus * r_stylus - a * a
    if h_sq < 0:
        # Unreachable geometry (the disc shrunk past what the pivot and
        # arm can span): draw no arm rather than a nonsense one.
        return
    h = math.sqrt(h_sq)
    ux, uy = (pivot_x - cx) / d, (pivot_y - cy) / d
    # Perpendicular; the negative sign takes the intersection on the near
    # face of the disc below the pivot, where a rear-right arm rests.
    px_, py_ = -uy, ux
    tip_x = cx + a * ux + h * px_
    tip_y = cy + a * uy + h * py_

    # Unit vector from stylus back to pivot — the arm axis.
    dx, dy = pivot_x - tip_x, pivot_y - tip_y
    axis = math.hypot(dx, dy)
    if axis < 1:
        return
    ax, ay = dx / axis, dy / axis
    perp_x, perp_y = -ay, ax

    # Counterweight sits behind the pivot, balancing the cartridge end.
    cw_x = pivot_x + ax * _VINYL_COUNTERWEIGHT_OFFSET
    cw_y = pivot_y + ay * _VINYL_COUNTERWEIGHT_OFFSET

    # Arm tube: one stroke through the pivot so it reads as rigid, cased as
    # a dark outline with a white core — a plain black tube would vanish
    # over the black disc (the ``metro`` route-line trick).
    ends = (tip_x + ax * 6, tip_y + ay * 6, cw_x, cw_y)
    draw.line(ends, fill=BLACK, width=5)
    draw.line(ends, fill=WHITE, width=2)
    # Pivot mount on the plate.
    draw.ellipse((pivot_x - 8, pivot_y - 8, pivot_x + 8, pivot_y + 8), fill=BLACK)
    draw.ellipse((pivot_x - 3, pivot_y - 3, pivot_x + 3, pivot_y + 3), fill=RED)
    # Counterweight cylinder.
    cw_r = 8
    draw.ellipse((cw_x - cw_r, cw_y - cw_r, cw_x + cw_r, cw_y + cw_r), fill=BLACK)
    draw.ellipse((cw_x - cw_r, cw_y - cw_r, cw_x + cw_r, cw_y + cw_r), outline=RED, width=1)
    # Cartridge headshell — a 4-point polygon along the arm axis.
    head_long, head_wide = 13, 8
    body_cx = tip_x + ax * (head_long * 0.45)
    body_cy = tip_y + ay * (head_long * 0.45)
    draw.polygon(
        [
            (body_cx + ax * head_long / 2 + perp_x * head_wide / 2,
             body_cy + ay * head_long / 2 + perp_y * head_wide / 2),
            (body_cx + ax * head_long / 2 - perp_x * head_wide / 2,
             body_cy + ay * head_long / 2 - perp_y * head_wide / 2),
            (body_cx - ax * head_long / 2 - perp_x * head_wide / 2,
             body_cy - ay * head_long / 2 - perp_y * head_wide / 2),
            (body_cx - ax * head_long / 2 + perp_x * head_wide / 2,
             body_cy - ay * head_long / 2 + perp_y * head_wide / 2),
        ],
        fill=BLACK,
        outline=WHITE,
    )
    # Stylus contact point.
    draw.ellipse((tip_x - 2, tip_y - 2, tip_x + 2, tip_y + 2), fill=RED)


def _vinyl_paint_33rpm_badge(
    image: Image.Image, draw: ImageDraw.ImageDraw, x_right: int, y_top: int,
) -> None:
    """Small red rect with white '33 RPM' Space Mono Bold, top-right corner.

    ASCII "33 RPM", not "33⅓": Space Mono Bold has no U+2153 and would tofu.
    """
    RED = SPECTRA6["red"]
    WHITE = SPECTRA6["white"]
    rect = (x_right - 64, y_top, x_right, y_top + 24)
    draw.rectangle(rect, fill=RED)
    font = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=12)
    text = "33 RPM"
    bbox = draw.textbbox((0, 0), text, font=font)
    w = bbox[2] - bbox[0]
    h = bbox[3] - bbox[1]
    rect_cx = (rect[0] + rect[2]) // 2
    rect_cy = (rect[1] + rect[3]) // 2
    draw.text((rect_cx - w // 2 - bbox[0], rect_cy - h // 2 - bbox[1]), text, font=font, fill=WHITE)


def _vinyl_paint_track_heading(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    x_left: int,
    y_top: int,
) -> None:
    """Small red "READING" heading above the quote body.

    Spoken-word LP backs (Caedmon) introduced each selection with
    "READING" / "PASSAGE" / "EXCERPT", the music LP's "TRACK ONE".
    """
    RED = SPECTRA6["red"]
    font = load_font([(ANTONIO_VARIABLE, "Bold"), *META_FONT_BOLD_CANDIDATES], size=13)
    text = "—  READING  —"
    draw.text((x_left, y_top), text, font=font, fill=RED)


def _vinyl_paint_spec_line(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    bucket: str,
    x_left: int,
    x_right: int,
    y_top: int,
) -> None:
    """Liner-note spec strip just under the READING heading.

    Spoken-word LP backs ran a technical line under each selection heading
    — side, speed, channel, running time. Space Mono, with a hairline above
    echoing the catalog bar's rule so the two strips bracket the quote. The
    running time is synthesised from the bucket, like the catalog number,
    so a given quote always renders the same strip.
    """
    BLACK = SPECTRA6["black"]
    font = load_font([SPACEMONO_BOLD, *META_FONT_CANDIDATES], size=10)
    # Deterministic "running time" 1:00–8:59 from the bucket. Never
    # ``hash()``: it is PYTHONHASHSEED-salted and would break the byte-exact
    # golden / dedup contract.
    h = sum(ord(c) for c in bucket)
    mins = 1 + (h % 8)
    secs = (h * 7) % 60
    # ASCII "33 RPM": Space Mono has no U+2153 (⅓) glyph.
    left_text = "SIDE ONE  ·  33 RPM  ·  MONO"
    right_text = f"RUNNING TIME {mins}:{secs:02d}"
    rule_y = y_top - 4
    draw.line((x_left, rule_y, x_right, rule_y), fill=BLACK, width=1)
    draw.text((x_left, y_top), left_text, font=font, fill=BLACK)
    bbox = draw.textbbox((0, 0), right_text, font=font)
    w = bbox[2] - bbox[0]
    draw.text((x_right - w - bbox[0], y_top - bbox[1]), right_text, font=font, fill=BLACK)


# Catalog-bar typography. The imprint shortens before the size steps down,
# and the size has a floor: below ~8 pt Cardo Italic shreds after palette
# snapping.
_VINYL_CATALOG_SIZE = 11
_VINYL_CATALOG_MIN_SIZE = 8
_VINYL_CATALOG_GAP = 14
_VINYL_IMPRINTS = (
    "IDLE HOURS LITERARY RECORDINGS",
    "IDLE HOURS RECORDINGS",
    "IDLE HOURS",
)


def _vinyl_paint_catalog_bar(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    bucket: str,
    x_left: int,
    x_right: int,
    y_top: int,
) -> None:
    """Bottom-of-sleeve catalog info bar: brand · catalog · year.

    Small italic Cardo — the register of an LP jacket's legal / catalog
    band. The catalog number repeats the label's, as real records do.
    """
    BLACK = SPECTRA6["black"]
    year = datetime.date.today().year
    cat = _vinyl_catalog_number(bucket)
    right_text = f"CAT NO. {cat}  ·  © {year}"
    # The catalog number carries the information, so the brand gives way:
    # try each shorter imprint, then step the size down. The halves must
    # never overlap.
    for size in range(_VINYL_CATALOG_SIZE, _VINYL_CATALOG_MIN_SIZE - 1, -1):
        font = load_font([CARDO_ITALIC, *META_FONT_CANDIDATES], size=size)
        right_w = draw.textlength(right_text, font=font)
        for left_text in _VINYL_IMPRINTS:
            left_w = draw.textlength(left_text, font=font)
            if left_w + right_w + _VINYL_CATALOG_GAP <= x_right - x_left:
                break
        else:
            continue
        break
    # Both halves share one baseline.
    baseline = y_top + size
    draw.text((x_left, baseline), left_text, font=font, fill=BLACK, anchor="ls")
    draw.text((x_right, baseline), right_text, font=font, fill=BLACK, anchor="rs")
    # Thin rule just above the catalog text.
    rule_y = y_top - 6
    draw.line((x_left, rule_y, x_right, rule_y), fill=BLACK, width=1)


def _vinyl_paint_quote_body(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    quote_row: dict,
    rect: tuple[int, int, int, int],
) -> None:
    """Quote body on the sleeve with tangerine matched-phrase substitution."""
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    YELLOW = SPECTRA6["yellow"]
    x0, y0, x1, y1 = rect
    width = x1 - x0
    height = y1 - y0
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    matched = quote_row.get("matched_text") or ""

    quote_font, quote_font_bold, wrapped_quote, line_height, _ = fit_quote(
        draw,
        display_quote,
        matched,
        width,
        height,
        font_max=32,
        font_min=18,
        line_height_mult=1.22,
        theme="vinyl",
    )
    quote_block_height = len(wrapped_quote) * line_height
    block_top = y0 + max(0, (height - quote_block_height) // 2)
    body_ascent = _font_ascent(quote_font)
    y = block_top
    for line in wrapped_quote:
        start = 0
        while start < len(line) and line[start][0].strip() == "":
            start += 1
        end = len(line)
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        drawable = line[start:end]
        x = x0
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            chunk_y = y + (body_ascent - _font_ascent(font))
            if is_bold:
                # Tangerine R+Y 5/8:3/8, same recipe astrarium uses.
                draw_text_dithered(
                    image, (x, chunk_y), chunk, font=font,
                    dark=RED, light=YELLOW, light_density=0.375,
                )
            else:
                draw.text((x, chunk_y), chunk, font=font, fill=BLACK)
            bbox = draw.textbbox((0, 0), chunk, font=font)
            x += bbox[2] - bbox[0]
        y += line_height


def _vinyl_paint_attribution(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    quote_row: dict,
    x_right: int,
    y_top: int,
) -> None:
    """Right-aligned author + ' · ' + title at the bottom of the sleeve."""
    BLACK = SPECTRA6["black"]
    font = load_font([EBGARAMOND_BOLD, *META_FONT_BOLD_CANDIDATES], size=12)
    # Truncate if too wide for the sleeve column (~360 px).
    max_w = 360
    fitted = _fit_dotted_byline(draw, quote_row, font, max_w)
    if fitted is None:
        return
    text, bbox = fitted
    w = bbox[2] - bbox[0]
    draw.text((x_right - w - bbox[0], y_top - bbox[1]), text, font=font, fill=BLACK)


def _vinyl_catalog_number(bucket: str) -> str:
    """Derive an album-style catalog number from a fuzzy bucket.

    e.g. ``"h2_half_past"`` → ``"IH-H2-30"``. Falls back to ``"IH-?"`` for
    malformed inputs so callers never raise.
    """
    if not bucket or "_" not in bucket:
        return "IH-?"
    hour_part, _, state = bucket.partition("_")
    minute = DEFAULT_BUCKET_MINUTES.get(state)
    if minute is None:
        return f"IH-{hour_part.upper()}-?"
    return f"IH-{hour_part.upper()}-{minute:02d}"


def render_vinyl_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Turntable + literary-audiobook LP back-cover (Caedmon / Spoken Arts register).

    Left half: a black LP (radius 200, centred at (200, 240)) with grooves,
    a lead-in groove, a dead-wax ring, a red label (SPOKEN WORD mark,
    matched-phrase title, brand stack, catalog number, © year) and a
    tonearm whose headshell sits at the current-minute rim position.

    Right half: cream liner-notes panel — "— READING —" heading, spec
    strip, the quote with a tangerine matched phrase, the attribution,
    a catalog bar, and the 33 RPM badge top-right. See docs/themes.md
    (``vinyl``).
    """
    # Composed at the canonical 800x480 and NEAREST-downsampled for other
    # sizes (``metro`` convention): the disc, label and tonearm pivot are
    # absolute panel coordinates.
    image = Image.new("RGB", (800, 480), color=SPECTRA6["white"])
    # Sleeve cream wash full-canvas — the disk will overpaint the left half.
    _astrarium_paint_cream_wash(image)
    # Daily-seeded wear marks on the sleeve (right half only).
    today = datetime.date.today()
    speckle_seed = int(today.strftime("%Y%m%d"))
    _vinyl_paint_wear_speckle(image, speckle_seed)

    draw = ImageDraw.Draw(image)

    # Render order: disk body (grooves only) → tonearm → label, so the
    # label paints over the arm and the arm never cuts through its text.
    _vinyl_paint_disk(image, draw, _VINYL_DISK_CX, _VINYL_DISK_CY, _VINYL_DISK_R, _VINYL_LABEL_R)
    bucket = quote_row.get("fuzzy_bucket") or bucket_for_time(time_str)
    matched = quote_row.get("matched_text") or ""
    try:
        minute = int(time_str.split(":", 1)[1])
    except (ValueError, IndexError):
        minute = 0
    _vinyl_paint_tonearm(image, draw, _VINYL_DISK_CX, _VINYL_DISK_CY, _VINYL_DISK_R, minute)
    _vinyl_paint_label(image, draw, _VINYL_DISK_CX, _VINYL_DISK_CY, _VINYL_LABEL_R, matched, bucket)

    # Right-half liner-notes chrome.
    sleeve_x_left, sleeve_x_right = 420, 800 - 20
    # 33 RPM badge in the sleeve's top-right.
    _vinyl_paint_33rpm_badge(image, draw, x_right=sleeve_x_right, y_top=20)
    # TRACK ONE heading at the top of the liner-notes column.
    _vinyl_paint_track_heading(image, draw, x_left=sleeve_x_left, y_top=24)
    # Liner-note spec strip (side · speed · channel · running time) just
    # below the heading — fills the dead cream between heading and quote.
    _vinyl_paint_spec_line(image, draw, bucket, x_left=sleeve_x_left,
                           x_right=sleeve_x_right, y_top=48)
    # Quote body on the sleeve (top nudged down to clear the spec strip).
    body_rect = (sleeve_x_left, 74, sleeve_x_right, 390)
    _vinyl_paint_quote_body(image, draw, quote_row, body_rect)
    # Author + title attribution (right-aligned).
    _vinyl_paint_attribution(image, draw, quote_row, x_right=sleeve_x_right, y_top=412)
    # Bottom catalog bar — the LP back-cover small-print band.
    _vinyl_paint_catalog_bar(image, draw, bucket, x_left=sleeve_x_left,
                             x_right=sleeve_x_right, y_top=450)

    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ─── vitrail (Gothic stained-glass cathedral window) ─────────────────────────

# Geometry below is the 800×480 reference; render_vitrail_frame scales the
# rose / arch / cartouche positions by (width/800, height/480) so the frame
# composes at any resolution and reproduces these exact values at native size.
_VITRAIL_SURROUND = 16        # black stone masonry inset from the canvas edge
_VITRAIL_CAME_W = 5           # lead-came line thickness
_VITRAIL_ROSE_CY = 96         # rose-window medallion centre y (cx is always width//2)
_VITRAIL_ROSE_R = 74          # rose-window medallion radius
_VITRAIL_ARCH_SPRING_Y = 150  # where the pointed-arch spandrels meet the sides
_VITRAIL_GRID_COLS = 6
_VITRAIL_GRID_ROWS = 5
_VITRAIL_CAME_INNER = 3       # black core thickness of the came between glass shapes
_VITRAIL_CAME_BEVEL = 2       # highlight/shadow offset that fakes the rounded raised-lead 3D profile
# Irregular-tessellation controls. A fixed seed keeps every render of the
# window byte-identical (golden / dedup determinism); the jitter nudges the
# interior lattice vertices off the grid and the split probability decides how
# many cells break into two triangular shards — together they turn the regular
# grid into a hand-leaded mosaic of varied quadrilaterals and triangles.
_VITRAIL_SEED = 0x711A55
_VITRAIL_JITTER = 0.30
# Per-row split probability ramp: the top row sits behind the rose window, so
# keeping it calm (few shards) avoids slivers crowding the medallion; the
# bottom rows split heavily to break up otherwise-oversized flat panes.
_VITRAIL_SPLIT_PROB_TOP = 0.18
_VITRAIL_SPLIT_PROB_BOTTOM = 0.82
# Clear white-glass cartouche the literary quote is knocked out onto so the
# dark body text stays legible over the busy colored field. Fixed for the
# 800×480 panel, like the other custom-render frames' coordinates.
_VITRAIL_CARTOUCHE = (150, 200, 650, 392)
# Pointed-gable rise above the cartouche's top edge, echoing the lancet arch
# so the quote panel reads as a light set into the tracery. Kept shallow: the
# cartouche paints after the rose window, so a taller gable would erase the
# rose's lower petals.
_VITRAIL_CARTOUCHE_ARCH = 20

# Deterministic jewel-tone cycle for the leaded glass panes, covering the
# native inks plus the 2-/3-ink stipple recipes from spectra6_color_recipes.md.
# Each entry is a fill spec consumed by _vitrail_pane_ink / _vitrail_fill_polygon:
#   ("solid", ink)                  → a native Spectra-6 ink
#   ("2", dark, light, density)     → 2-ink stipple (mirrors _fill_swatch_stipple)
#   ("3", a, b, c, dens_a, dens_b)  → 3-ink Bayer partition (mirrors
#                                     _fill_swatch_stipple_3way)
_VITRAIL_GLASS: list[tuple] = [
    ("solid", SPECTRA6["red"]),                                  # ruby
    ("solid", SPECTRA6["blue"]),                                 # sapphire
    ("2", SPECTRA6["red"], SPECTRA6["yellow"], 0.375),           # amber / gold
    ("solid", SPECTRA6["green"]),                                # emerald
    ("2", SPECTRA6["red"], SPECTRA6["blue"], 0.5),               # royal purple
    ("solid", SPECTRA6["yellow"]),                               # solid gold
    ("2", SPECTRA6["green"], SPECTRA6["blue"], 0.375),           # teal
    ("3", SPECTRA6["red"], SPECTRA6["blue"], SPECTRA6["black"], 0.34, 0.33),   # plum
    ("2", SPECTRA6["red"], SPECTRA6["white"], 0.5),              # rose / coral
    ("2", SPECTRA6["blue"], SPECTRA6["black"], 0.5),             # navy
    ("2", SPECTRA6["yellow"], SPECTRA6["green"], 0.5),           # olive
    ("3", SPECTRA6["red"], SPECTRA6["blue"], SPECTRA6["white"], 0.34, 0.33),   # lavender
    ("2", SPECTRA6["blue"], SPECTRA6["white"], 0.5),             # sky blue
    ("2", SPECTRA6["green"], SPECTRA6["black"], 0.5),            # forest
    ("2", SPECTRA6["green"], SPECTRA6["white"], 0.5),            # mint
]


def _vitrail_pane_ink(x: int, y: int, spec: tuple) -> tuple[int, int, int]:
    """Return the on-palette ink for pixel (x, y) within a pane, per the fill
    spec — solid, 2-ink stipple, or 3-ink Bayer partition. The stipple maths
    mirror _fill_swatch_stipple / _fill_swatch_stipple_3way exactly (absolute
    x/y so the Bayer phase stays continuous across adjacent panes), so the
    irregular polygon panes carry the same documented recipes the rectangular
    swatch fills do."""
    kind = spec[0]
    if kind == "solid":
        return spec[1]
    if kind == "2":
        _, dark, light, density = spec
        if density <= 0.25:
            return light if (x % 2 == 0 and y % 2 == 0) else dark
        if density >= 0.5:
            return dark if (x + y) % 2 == 0 else light
        return light if BAYER_4x4[y % 4][x % 4] < round(density * 16) else dark
    # "3" — 3-ink Bayer partition.
    _, ink_a, ink_b, ink_c, density_a, density_b = spec
    cell = BAYER_4x4[y % 4][x % 4]
    if cell < round(density_a * 16):
        return ink_a
    if cell < round((density_a + density_b) * 16):
        return ink_b
    return ink_c


def _vitrail_fill_polygon(image: Image.Image, polygon: list, spec: tuple) -> None:
    """Fill an arbitrary (irregular quadrilateral or triangular) glass shape
    with its jewel tone, clipped to the polygon via a 1-bit mask so the stipple
    only lands inside the leaded shape and never bleeds into a neighbour."""
    xs = [int(p[0]) for p in polygon]
    ys = [int(p[1]) for p in polygon]
    w, h = image.size
    x0 = max(0, min(xs))
    y0 = max(0, min(ys))
    x1 = min(w, max(xs) + 1)
    y1 = min(h, max(ys) + 1)
    if x1 <= x0 or y1 <= y0:
        return
    mask = Image.new("1", (x1 - x0, y1 - y0), 0)
    ImageDraw.Draw(mask).polygon([(int(px) - x0, int(py) - y0) for px, py in polygon], fill=1)
    mpx = mask.load()
    ipx = image.load()
    for yy in range(y1 - y0):
        ay = y0 + yy
        for xx in range(x1 - x0):
            if mpx[xx, yy]:
                ipx[x0 + xx, ay] = _vitrail_pane_ink(x0 + xx, ay, spec)


def _vitrail_build_panes(
    field: tuple[int, int, int, int], rose: tuple[float, float, float],
) -> list[tuple[list, tuple]]:
    """Deterministically tessellate the window opening into irregular leaded
    glass shapes.

    A jittered lattice (border vertices pinned, interior vertices nudged by a
    seeded RNG) yields irregular quads; some cells split along a diagonal into
    two triangular shards of different tones. The per-row +2 palette shear
    keeps vertically adjacent shapes from sharing a hue. Fixed seed, so the
    window is byte-identical on every render. Splitting ramps from calm at the
    top to busy at the bottom, and cells under the rose disc never split, so
    the medallion sits on calm glass."""
    x0, y0, x1, y1 = field
    cols, rows = _VITRAIL_GRID_COLS, _VITRAIL_GRID_ROWS
    rng = random.Random(_VITRAIL_SEED)
    cw = (x1 - x0) / cols
    ch = (y1 - y0) / rows
    jx = cw * _VITRAIL_JITTER
    jy = ch * _VITRAIL_JITTER
    rose_cx, rose_cy, rose_r = rose
    rose_keep_out = (rose_r + ch) ** 2
    pts: dict[tuple[int, int], tuple[float, float]] = {}
    for r in range(rows + 1):
        for c in range(cols + 1):
            px = x0 + c * cw
            py = y0 + r * ch
            if 0 < c < cols:
                px += rng.uniform(-jx, jx)
            if 0 < r < rows:
                py += rng.uniform(-jy, jy)
            pts[(r, c)] = (px, py)
    n = len(_VITRAIL_GLASS)
    panes: list[tuple[list, tuple]] = []
    for r in range(rows):
        row_frac = r / (rows - 1) if rows > 1 else 0.0
        split_prob = _VITRAIL_SPLIT_PROB_TOP + (_VITRAIL_SPLIT_PROB_BOTTOM - _VITRAIL_SPLIT_PROB_TOP) * row_frac
        for c in range(cols):
            tl = pts[(r, c)]
            tr = pts[(r, c + 1)]
            br = pts[(r + 1, c + 1)]
            bl = pts[(r + 1, c)]
            idx = (r * cols + c + r * 2) % n
            cell_cx = (tl[0] + tr[0] + br[0] + bl[0]) / 4
            cell_cy = (tl[1] + tr[1] + br[1] + bl[1]) / 4
            under_rose = (cell_cx - rose_cx) ** 2 + (cell_cy - rose_cy) ** 2 < rose_keep_out
            if not under_rose and rng.random() < split_prob:
                # Split into two triangular shards on one of the two diagonals.
                alt = _VITRAIL_GLASS[(idx + 7) % n]
                if rng.random() < 0.5:
                    panes.append(([tl, tr, br], _VITRAIL_GLASS[idx]))
                    panes.append(([tl, br, bl], alt))
                else:
                    panes.append(([tl, tr, bl], _VITRAIL_GLASS[idx]))
                    panes.append(([tr, br, bl], alt))
            else:
                panes.append(([tl, tr, br, bl], _VITRAIL_GLASS[idx]))
    return panes


def _vitrail_paint_glass_panes(image: Image.Image, panes: list) -> None:
    """Fill every leaded glass shape with its jewel tone."""
    for polygon, spec in panes:
        _vitrail_fill_polygon(image, polygon, spec)


# Diagonal specular "sheen" bands swept across the glass so the panes read as a
# glossy reflective surface catching light, not flat colour fields. Each entry
# is (centre_fraction, half_width_px, peak_density) in the t = x − y diagonal
# coordinate (lines of constant x − y run top-left → bottom-right, the classic
# glass-glint direction with light from the upper-left). White is stippled into
# the glass with density tapering linearly to zero at each band's edge.
_VITRAIL_SHIMMER = [(0.37, 120, 0.62), (0.63, 66, 0.40)]


def _vitrail_paint_shimmer(
    image: Image.Image,
    field: tuple[int, int, int, int],
    region: tuple[int, int, int, int] | None = None,
    clip: tuple[int, int, int] | None = None,
) -> None:
    """Sweep diagonal specular sheen bands across the filled glass.

    White is Bayer-stippled in at a density peaking on each band's centreline.
    Only glass-coloured pixels are touched (black and white are skipped); runs
    before the came / cartouche. A pure function of pixel position.

    Band positions always derive from ``field`` so a streak lands on the same
    diagonal everywhere. ``region`` restricts the pixels visited (to re-apply
    the same streaks to the rose glass); ``clip`` = ``(cx, cy, r)`` limits the
    pass to a disc."""
    WHITE = SPECTRA6["white"]
    BLACK = SPECTRA6["black"]
    fx0, fy0, fx1, fy1 = field
    t_min = fx0 - fy1
    span = (fx1 - fy0) - t_min
    if span <= 0:
        return
    bands = [(t_min + frac * span, hw, peak) for frac, hw, peak in _VITRAIL_SHIMMER]
    rx0, ry0, rx1, ry1 = region if region is not None else field
    rx0 = max(0, rx0)
    ry0 = max(0, ry0)
    rx1 = min(image.size[0], rx1)
    ry1 = min(image.size[1], ry1)
    cx = cy = cr2 = None
    if clip is not None:
        cx, cy, cr = clip
        cr2 = cr * cr
    px = image.load()
    for y in range(ry0, ry1):
        brow = BAYER_4x4[y % 4]
        for x in range(rx0, rx1):
            cur = px[x, y]
            if cur == BLACK or cur == WHITE:
                continue
            if cr2 is not None and (x - cx) * (x - cx) + (y - cy) * (y - cy) > cr2:
                continue
            t = x - y
            best = 0.0
            for centre, hw, peak in bands:
                d = abs(t - centre)
                if d < hw:
                    dens = peak * (1.0 - d / hw)
                    if dens > best:
                        best = dens
            if best > 0.0 and brow[x % 4] < round(best * 16):
                px[x, y] = WHITE


def _vitrail_paint_arch_spandrels(
    image: Image.Image, draw: ImageDraw.ImageDraw, field: tuple[int, int, int, int], spring_y: int,
) -> None:
    """Carve a pointed (lancet) arch into the top of the colored field by
    filling the two top-corner spandrel triangles with black stone, so the
    glass reads as a Gothic arch rather than a plain rectangle."""
    BLACK = SPECTRA6["black"]
    x0, y0, x1, _ = field
    apex = ((x0 + x1) // 2, y0)
    draw.polygon([(x0, y0), apex, (x0, spring_y)], fill=BLACK)
    draw.polygon([apex, (x1, y0), (x1, spring_y)], fill=BLACK)


def _vitrail_paint_lead_came(
    draw: ImageDraw.ImageDraw, panes: list, field: tuple[int, int, int, int],
) -> None:
    """Trace lead came along every glass-shape boundary as a *beveled* raised
    bar, then lay the heavy outer window frame on top.

    Each seam is drawn in three passes, light from the upper-left: a white
    highlight offset up-left, a black drop shadow offset down-right, then the
    black core on the true path. Shared edges are painted twice, harmlessly."""
    BLACK = SPECTRA6["black"]
    WHITE = SPECTRA6["white"]
    core = _VITRAIL_CAME_INNER
    b = _VITRAIL_CAME_BEVEL
    for polygon, _ in panes:
        closed = [*polygon, polygon[0]]
        hi = [(x - b, y - b) for x, y in closed]
        sh = [(x + b, y + b) for x, y in closed]
        draw.line(hi, fill=WHITE, width=core, joint="curve")
        draw.line(sh, fill=BLACK, width=core, joint="curve")
        draw.line(closed, fill=BLACK, width=core, joint="curve")
    _vitrail_paint_outer_frame(draw, field)


def _vitrail_paint_outer_frame(draw: ImageDraw.ImageDraw, field: tuple[int, int, int, int]) -> None:
    """Heavy beveled stone surround around the whole window: the opening's
    top-left lip is lit white, the bottom-right stays black, so the masonry
    reads as raised stone with the glass recessed behind it."""
    BLACK = SPECTRA6["black"]
    WHITE = SPECTRA6["white"]
    came = _VITRAIL_CAME_W
    x0, y0, x1, y1 = field
    for o in range(came):
        draw.rectangle((x0 + o, y0 + o, x1 - o, y1 - o), outline=BLACK)
    # Lit top + left lip of the opening.
    ix0, iy0, ix1, iy1 = x0 + came, y0 + came, x1 - came, y1 - came
    draw.line((ix0, iy0, ix1, iy0), fill=WHITE, width=1)
    draw.line((ix0, iy0, ix0, iy1), fill=WHITE, width=1)


def _vitrail_paint_rose_window(
    image: Image.Image, draw: ImageDraw.ImageDraw, hour_int: int,
    cx: int, cy: int, R: int, came: int,
) -> None:
    """Top-centre rose-window medallion: a stone-ringed glass disc divided
    into twelve jewel-tone petal wedges by radial came, ringed by a band of
    small clear-glass foil roundels (the tracery a real rose window carries),
    with the Roman-numeral hour set in the ecclesiastical ornament face at the
    hub."""
    BLACK = SPECTRA6["black"]
    WHITE = SPECTRA6["white"]
    # Stone ring + clear glass disc base.
    draw.ellipse((cx - R - came, cy - R - came, cx + R + came, cy + R + came), fill=BLACK)
    draw.ellipse((cx - R, cy - R, cx + R, cy + R), fill=WHITE)
    # Twelve petal wedges cycling the four saturated inks.
    petals = 12
    wedge_inks = [SPECTRA6["red"], SPECTRA6["blue"], SPECTRA6["yellow"], SPECTRA6["green"]]
    for k in range(petals):
        start = k * 360 / petals
        end = (k + 1) * 360 / petals
        draw.pieslice((cx - R, cy - R, cx + R, cy + R), start, end, fill=wedge_inks[k % len(wedge_inks)])
    # Radial came between petals + a concentric rim ring.
    for k in range(petals):
        ang = math.radians(k * 360 / petals)
        ex = cx + R * math.cos(ang)
        ey = cy + R * math.sin(ang)
        draw.line((cx, cy, ex, ey), fill=BLACK, width=came - 2)
    draw.ellipse((cx - R, cy - R, cx + R, cy + R), outline=BLACK, width=came - 2)
    # Tracery: a concentric came ring splits the petals into two tiers, and
    # twelve clear-glass foil roundels (one per outer petal) keep the
    # medallion from reading as a flat pie chart.
    ring_r = R * 0.60
    draw.ellipse((cx - ring_r, cy - ring_r, cx + ring_r, cy + ring_r), outline=BLACK, width=came - 2)
    foil_band = R * 0.80
    foil_r = max(3, round(R * 0.10))
    for k in range(petals):
        ang = math.radians((k + 0.5) * 360 / petals)
        fx = cx + foil_band * math.cos(ang)
        fy = cy + foil_band * math.sin(ang)
        draw.ellipse((fx - foil_r - 1, fy - foil_r - 1, fx + foil_r + 1, fy + foil_r + 1), fill=BLACK)
        draw.ellipse((fx - foil_r, fy - foil_r, fx + foil_r, fy + foil_r), fill=WHITE)
    # Central hub carrying the numeral, knocked out clear.
    hub = max(10, round(R * 0.38))
    draw.ellipse((cx - hub - 2, cy - hub - 2, cx + hub + 2, cy + hub + 2), fill=BLACK)
    draw.ellipse((cx - hub, cy - hub, cx + hub, cy + hub), fill=WHITE)
    numeral = _TAROT_ROMAN_NUMERALS.get(hour_int, "—")
    # Shrink from 30pt until the numeral fits the hub — wide numerals
    # ("VIII", "XII") overflow it at a fixed size. ~3px margin off the came.
    fit = hub - 3
    font_candidates = theme_font_candidates("vitrail", "ornament")
    font = load_font(font_candidates, size=30)
    for size in range(30, 11, -2):
        font = load_font(font_candidates, size=size)
        left, top, right, bottom = draw.textbbox((0, 0), numeral, font=font)
        if (right - left) <= fit * 2 and (bottom - top) <= fit * 2:
            break
    draw.text((cx, cy), numeral, font=font, fill=BLACK, anchor="mm")


def _vitrail_cartouche_top_points(x0: int, y0: int, x1: int, rise: int) -> list[tuple[int, int]]:
    """Polyline tracing the cartouche's pointed-arch top from the left top
    corner (x0, y0) up to the central apex (xc, y0 − rise) and down to the
    right top corner (x1, y0).

    The rise must stay shallow (the rose window sits just above), and a
    straight gable that shallow reads flat; easing each half by ``u ** p``
    (p > 1) concentrates the rise into a sharp central spire."""
    xc = (x0 + x1) / 2.0
    half = xc - x0
    p = 1.8
    n = 24
    pts: list[tuple[float, float]] = []
    for i in range(n + 1):                       # left half: x0 → apex
        u = i / n
        pts.append((x0 + u * half, y0 - rise * (u ** p)))
    for i in range(1, n + 1):                    # right half: apex → x1
        u = i / n
        pts.append((xc + u * half, y0 - rise * ((1.0 - u) ** p)))
    return [(int(round(px)), int(round(py))) for px, py in pts]


def _vitrail_paint_quote_cartouche(
    image: Image.Image, draw: ImageDraw.ImageDraw, rect: tuple[int, int, int, int], arch_rise: int,
) -> None:
    """Knock out a clear white-glass panel for the quote and frame it in came.

    A solid white wipe clears every stipple under the body so the text sits on
    legible ground. The panel has a pointed-arch top (apex at y0 − arch rise);
    its came frame follows that outline and is beveled like the panes (white
    lip top-left, black lip bottom-right). Just inside the came, adjacent red
    and blue 1px rules average to violet at panel distance, so the panel reads
    as set into coloured glass."""
    BLACK = SPECTRA6["black"]
    WHITE = SPECTRA6["white"]
    RED = SPECTRA6["red"]
    BLUE = SPECTRA6["blue"]
    x0, y0, x1, y1 = rect
    came = _VITRAIL_CAME_W
    top = _vitrail_cartouche_top_points(x0, y0, x1, arch_rise)
    # White knockout: arched top + rectangular body, as one polygon.
    draw.polygon(top + [(x1, y1), (x0, y1)], fill=WHITE)
    # Came frame along the full arched outline; curved joins keep the apex clean.
    outline = [(x0, y1)] + top + [(x1, y1), (x0, y1)]
    draw.line(outline, fill=BLACK, width=came, joint="curve")
    # Bevel: lit white lip along the lit top-left edges (left wall + left half of
    # the arch up to the apex), shadowed black lip along the bottom-right.
    apex_idx = len(top) // 2
    draw.line([(x0, y1), (x0, y0)] + top[: apex_idx + 1], fill=WHITE, width=1)
    draw.line(top[apex_idx:] + [(x1, y1), (x0, y1)], fill=BLACK, width=1)
    # Violet inner rule: concentric red then blue 1px outlines just inside the came.
    for inset, ink in ((3, RED), (4, BLUE)):
        itop = _vitrail_cartouche_top_points(x0 + inset, y0 + inset, x1 - inset, max(0, arch_rise - inset))
        draw.line(itop + [(x1 - inset, y1 - inset), (x0 + inset, y1 - inset), (x0 + inset, y0 + inset)],
                  fill=ink, width=1, joint="curve")


def _vitrail_paint_quote_body(
    image: Image.Image, draw: ImageDraw.ImageDraw,
    quote_row: dict, rect: tuple[int, int, int, int],
) -> None:
    """Quote body fitted into the cartouche, matched phrase in violet glass.

    Mirrors _tarot_paint_body: centred block, per-line horizontal centring,
    regular chunks in solid black, the matched time phrase stippled in R+B
    purple (the canonical violet-glass tone) via draw_text_dithered."""
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    BLUE = SPECTRA6["blue"]
    x0, y0, x1, y1 = rect
    pad = 14
    x0 += pad
    y0 += pad
    width = (x1 - pad) - x0
    height = (y1 - pad) - y0
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    matched = quote_row.get("matched_text") or ""
    quote_font, quote_font_bold, wrapped_quote, line_height, _ = fit_quote(
        draw, display_quote, matched, width, height,
        font_max=30, font_min=15, line_height_mult=1.22, theme="vitrail",
    )
    quote_block_height = len(wrapped_quote) * line_height
    block_top = y0 + max(0, (height - quote_block_height) // 2)
    body_ascent = _font_ascent(quote_font)
    y = block_top
    for line in wrapped_quote:
        start = 0
        while start < len(line) and line[start][0].strip() == "":
            start += 1
        end = len(line)
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        drawable = line[start:end]
        line_width = 0
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            bbox = draw.textbbox((0, 0), chunk, font=font)
            line_width += bbox[2] - bbox[0]
        x = x0 + max(0, (width - line_width) // 2)
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            chunk_y = y + (body_ascent - _font_ascent(font))
            if is_bold:
                draw_text_dithered(
                    image, (x, chunk_y), chunk, font=font,
                    dark=RED, light=BLUE, light_density=0.5,
                )
            else:
                draw.text((x, chunk_y), chunk, font=font, fill=BLACK)
            bbox = draw.textbbox((0, 0), chunk, font=font)
            x += bbox[2] - bbox[0]
        y += line_height


def _vitrail_paint_attribution(
    image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict, cx: int, y_top: int,
) -> None:
    """Author · title in the Liberation Serif body face, solid black, centred.

    Not the Uncial Antiqua ornament face: its open letterforms shatter at
    byline sizes after palette snapping."""
    BLACK = SPECTRA6["black"]
    font = load_font(theme_font_candidates("vitrail", "quote_regular"), size=15)
    max_w = 460
    fitted = _fit_dotted_byline(draw, quote_row, font, max_w)
    if fitted is None:
        return
    text, bbox = fitted
    w = bbox[2] - bbox[0]
    draw.text((cx - w // 2 - bbox[0], y_top - bbox[1]), text, font=font, fill=BLACK)


def render_vitrail_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Gothic stained-glass cathedral window.

    A tall lancet window whose black lead-came tracery divides the canvas into
    jewel-toned glass panes spanning the full synthesised Spectra-6 palette, a
    rose-window medallion carrying the Roman-numeral hour, and the literary
    quote glowing in a clear white-glass central cartouche (matched time phrase
    in violet glass). The matched phrase and the rose-window numeral carry the
    time; HH:MM digits are never shown.
    """
    image = Image.new("RGB", (width, height), color=SPECTRA6["black"])
    draw = ImageDraw.Draw(image)
    field = (_VITRAIL_SURROUND, _VITRAIL_SURROUND, width - _VITRAIL_SURROUND, height - _VITRAIL_SURROUND)
    # Scale the 800×480 reference geometry to the canvas so the frame composes
    # at any size; at native size it reproduces the constants exactly.
    sx, sy = width / 800.0, height / 480.0
    rose_cx = width // 2
    rose_cy = round(_VITRAIL_ROSE_CY * sy)
    rose_r = round(_VITRAIL_ROSE_R * sy)
    came = _VITRAIL_CAME_W
    spring_y = round(_VITRAIL_ARCH_SPRING_Y * sy)
    cx0, cy0, cx1, cy1 = _VITRAIL_CARTOUCHE
    cart = (round(cx0 * sx), round(cy0 * sy), round(cx1 * sx), round(cy1 * sy))
    arch_rise = round(_VITRAIL_CARTOUCHE_ARCH * sy)
    # Paint order: fill glass shapes → lead came along every seam → arch
    # spandrels (black stone over the top corners) → rose (on top of the top
    # shapes) → cartouche white knockout (erases any came/glass crossing it) →
    # cartouche frame + quote body + attribution.
    panes = _vitrail_build_panes(field, (rose_cx, rose_cy, rose_r))
    _vitrail_paint_glass_panes(image, panes)
    _vitrail_paint_shimmer(image, field)
    _vitrail_paint_lead_came(draw, panes, field)
    _vitrail_paint_arch_spandrels(image, draw, field, spring_y)
    hour_int = _clock_hour12(time_str)
    _vitrail_paint_rose_window(image, draw, hour_int, rose_cx, rose_cy, rose_r, came)
    # Re-apply the same sheen to the rose glass (painted after the field-wide
    # pass) so it stays continuous with the panes; clipped to the disc.
    _vitrail_paint_shimmer(
        image, field,
        region=(rose_cx - rose_r, rose_cy - rose_r, rose_cx + rose_r, rose_cy + rose_r),
        clip=(rose_cx, rose_cy, rose_r),
    )
    _vitrail_paint_quote_cartouche(image, draw, cart, arch_rise)
    _vitrail_paint_quote_body(image, draw, quote_row, (cart[0], cart[1], cart[2], cart[3] - round(24 * sy)))
    _vitrail_paint_attribution(image, draw, quote_row, (cart[0] + cart[2]) // 2, cart[3] - round(20 * sy))
    return snap_image_to_palette(image, SPECTRA6_PALETTE)


# ─── questline (pixel RPG dialogue) ──────────────────────────────────────────
#
# An 8/16-bit JRPG presents the quote as NPC dialogue: dithered sky over green
# hills, a hero sprite, sun and clouds, and a bordered dialogue box. The author
# is the speaker on the nameplate, the matched phrase glows yellow, a static ▼
# arrow sits in the corner, and the title runs along the bottom. HH:MM is never
# shown — the matched phrase carries the time.

# 8-wide × 10-tall pixel hero: red cap, white face, blue tunic, black boots.
# Painted as scale×scale blocks; '.' is transparent.
_QUESTLINE_HERO = (
    "..KKKK..",
    ".KRRRRK.",
    ".KWWWWK.",
    ".KWKKWK.",
    ".KWWWWK.",
    ".WBBBBW.",
    ".WBBBBW.",
    ".KBBBBK.",
    ".KB..BK.",
    ".KK..KK.",
)
_QUESTLINE_SPRITE_PALETTE = {
    "K": SPECTRA6["black"],
    "W": SPECTRA6["white"],
    "R": SPECTRA6["red"],
    "B": SPECTRA6["blue"],
    "G": SPECTRA6["green"],
    "Y": SPECTRA6["yellow"],
}

# Vertical bands of the scene (y, 800×480 canvas). The sky/hills are kept
# compact up top so the dialogue box can own the taller lower ~50% — more room
# for a larger, more legible font.
_QUESTLINE_SKY_BOTTOM = 168
_QUESTLINE_HILL_BOTTOM = 224
_QUESTLINE_BOX = (22, 230, 778, 470)  # x0, y0, x1, y1


def _questline_paint_sky(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """Sky-blue (B+W) wash over green hills, with a yellow sun + white clouds.

    The B+W checkerboard reads as a soft daytime sky where solid blue would be
    flat and saturated; the hills carry a forest-green (G+K) lower lip.
    """
    width = image.size[0]
    WHITE = SPECTRA6["white"]
    YELLOW = SPECTRA6["yellow"]
    GREEN = SPECTRA6["green"]
    BLACK = SPECTRA6["black"]
    BLUE = SPECTRA6["blue"]
    # Sky: sky-blue B+W checkerboard.
    _fill_swatch_stipple(image, (0, 0, width, _QUESTLINE_SKY_BOTTOM), dark=BLUE, light=WHITE, light_density=0.5)
    # Hills: solid green, with a forest-green (G+K) lower strip for depth.
    draw.rectangle((0, _QUESTLINE_SKY_BOTTOM, width, _QUESTLINE_HILL_BOTTOM), fill=GREEN)
    _fill_swatch_stipple(
        image, (0, _QUESTLINE_HILL_BOTTOM - 10, width, _QUESTLINE_HILL_BOTTOM),
        dark=GREEN, light=BLACK, light_density=0.5,
    )
    # Sun: yellow disc top-right with eight short rays.
    sun_cx, sun_cy, sun_r = 690, 72, 34
    for k in range(8):
        ang = math.radians(k * 45)
        x0 = sun_cx + int(math.cos(ang) * (sun_r + 6))
        y0 = sun_cy + int(math.sin(ang) * (sun_r + 6))
        x1 = sun_cx + int(math.cos(ang) * (sun_r + 18))
        y1 = sun_cy + int(math.sin(ang) * (sun_r + 18))
        draw.line((x0, y0, x1, y1), fill=YELLOW, width=4)
    draw.ellipse((sun_cx - sun_r, sun_cy - sun_r, sun_cx + sun_r, sun_cy + sun_r), fill=YELLOW)
    # Two white pixel clouds (clusters of overlapping discs).
    for (cx, cy, s) in ((150, 60, 1.0), (340, 110, 0.8)):
        for (dx, dy, r) in ((-28, 6, 16), (-8, -6, 22), (16, 2, 18), (34, 8, 14)):
            draw.ellipse(
                (cx + int(dx * s) - int(r * s), cy + int(dy * s) - int(r * s),
                 cx + int(dx * s) + int(r * s), cy + int(dy * s) + int(r * s)),
                fill=WHITE,
            )


def _questline_paint_sprite(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """The hero sprite standing on the hills, right of the dialogue nameplate."""
    scale = 7
    sprite_h = len(_QUESTLINE_HERO) * scale
    x0 = 656
    y0 = _QUESTLINE_HILL_BOTTOM - sprite_h  # feet rest on the hill line
    for ry, row in enumerate(_QUESTLINE_HERO):
        for rx, ch in enumerate(row):
            color = _QUESTLINE_SPRITE_PALETTE.get(ch)
            if color is None:
                continue
            px = x0 + rx * scale
            py = y0 + ry * scale
            draw.rectangle((px, py, px + scale - 1, py + scale - 1), fill=color)


def _questline_paint_box(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """Navy dialogue box with a white double pixel frame (square corners)."""
    x0, y0, x1, y1 = _QUESTLINE_BOX
    WHITE = SPECTRA6["white"]
    BLUE = SPECTRA6["blue"]
    BLACK = SPECTRA6["black"]
    # Navy fill (blue + black checkerboard) — deep dialogue-box blue.
    _fill_swatch_stipple(image, (x0, y0, x1 + 1, y1 + 1), dark=BLUE, light=BLACK, light_density=0.5)
    # White outer frame, 4 px thick.
    for i in range(4):
        draw.rectangle((x0 + i, y0 + i, x1 - i, y1 - i), outline=WHITE)
    # White inner rule, inset to leave a navy gap → classic double border.
    draw.rectangle((x0 + 10, y0 + 10, x1 - 10, y1 - 10), outline=WHITE)
    draw.rectangle((x0 + 11, y0 + 10, x1 - 11, y1 - 10), outline=WHITE)


def _questline_paint_nameplate(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """Speaker nameplate tab straddling the box top-left: the author's name.

    Falls back to "NARRATOR" when the row has no author, and truncates long
    names so the tab stays clear of the hero sprite.
    """
    WHITE = SPECTRA6["white"]
    YELLOW = SPECTRA6["yellow"]
    BLUE = SPECTRA6["blue"]
    BLACK = SPECTRA6["black"]
    author = (quote_row.get("author") or "").strip()
    name = (author or "NARRATOR").upper()
    if len(name) > 22:
        name = name[:21] + "…"
    font = load_font(theme_font_candidates("questline", "quote_bold"), size=11)
    bbox = draw.textbbox((0, 0), name, font=font)
    text_w = bbox[2] - bbox[0]
    pad_x, pad_y = 12, 7
    box_x0, box_y0 = _QUESTLINE_BOX[0] + 18, _QUESTLINE_BOX[1] - 26
    plate = (box_x0, box_y0, box_x0 + text_w + pad_x * 2, box_y0 + (bbox[3] - bbox[1]) + pad_y * 2)
    _fill_swatch_stipple(image, (plate[0], plate[1], plate[2] + 1, plate[3] + 1), dark=BLUE, light=BLACK, light_density=0.5)
    for i in range(3):
        draw.rectangle((plate[0] + i, plate[1] + i, plate[2] - i, plate[3] - i), outline=WHITE)
    draw.text((plate[0] + pad_x - bbox[0], plate[1] + pad_y - bbox[1]), name, font=font, fill=YELLOW)


def _questline_paint_dialogue(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict, rect: tuple[int, int, int, int]) -> None:
    """The quote as left-aligned NPC speech: white body, yellow matched phrase.

    Uses the shared ``fit_quote`` / ``wrap_styled_text`` pipeline so a dense
    quote shrinks to fit the box. Left-aligned (not centred) so it reads as
    dialogue. Press Start 2P reports descent 0, so a generous line-height
    multiplier supplies the inter-line gap the bitmap cell omits.
    """
    WHITE = SPECTRA6["white"]
    YELLOW = SPECTRA6["yellow"]
    x0, y0, x1, y1 = rect
    box_w = x1 - x0
    box_h = y1 - y0
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    matched = quote_row.get("matched_text") or ""
    quote_font, quote_font_bold, wrapped_quote, line_height, _ = fit_quote(
        draw, display_quote, matched, box_w, box_h,
        font_max=40, font_min=10, line_height_mult=1.6, theme="questline",
    )
    body_ascent = _font_ascent(quote_font)
    y = y0
    for line in wrapped_quote:
        start = 0
        while start < len(line) and line[start][0].strip() == "":
            start += 1
        end = len(line)
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        x = x0
        for chunk, is_bold in line[start:end]:
            font = quote_font_bold if is_bold else quote_font
            chunk_y = y + (body_ascent - _font_ascent(font))
            draw.text((x, chunk_y), chunk, font=font, fill=YELLOW if is_bold else WHITE)
            bbox = draw.textbbox((0, 0), chunk, font=font)
            x += bbox[2] - bbox[0]
        y += line_height


def _questline_paint_arrow(draw: ImageDraw.ImageDraw) -> None:
    """Static ▼ 'press to continue' arrow in the box's bottom-right corner."""
    WHITE = SPECTRA6["white"]
    x1, y1 = _QUESTLINE_BOX[2], _QUESTLINE_BOX[3]
    cx, cy = x1 - 30, y1 - 26
    draw.polygon([(cx - 9, cy - 6), (cx + 9, cy - 6), (cx, cy + 8)], fill=WHITE)


def _questline_paint_footer(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """'— from {Title} —' along the box's bottom inner margin, centred."""
    WHITE = SPECTRA6["white"]
    font = load_font(theme_font_candidates("questline", "quote_regular"), size=8)
    # Keep the footer clear of the continue arrow on the right.
    text = _fit_from_title(draw, quote_row, font, (_QUESTLINE_BOX[2] - _QUESTLINE_BOX[0]) - 120)
    if text is None:
        return
    bbox = draw.textbbox((0, 0), text, font=font)
    cx = (_QUESTLINE_BOX[0] + _QUESTLINE_BOX[2]) // 2
    fx = cx - (bbox[2] - bbox[0]) // 2 - bbox[0]
    fy = _QUESTLINE_BOX[3] - 22 - bbox[1]
    draw.text((fx, fy), text, font=font, fill=WHITE)


def render_questline_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Pixel RPG dialogue scene (see the module section comment above).

    ``time_str`` is unused (the matched phrase carries the time); kept for
    dispatch-signature uniformity.
    """
    del time_str  # see docstring; deliberately unused.
    image = Image.new("RGB", (width, height), color=SPECTRA6["black"])
    draw = ImageDraw.Draw(image)
    _questline_paint_sky(image, draw)
    _questline_paint_sprite(image, draw)
    _questline_paint_box(image, draw)
    _questline_paint_nameplate(image, draw, quote_row)
    # Body text rect: inside the double frame, clear of the nameplate (top) and
    # the footer / continue arrow (bottom).
    bx0, by0, bx1, by1 = _QUESTLINE_BOX
    _questline_paint_dialogue(image, draw, quote_row, (bx0 + 34, by0 + 28, bx1 - 34, by1 - 40))
    _questline_paint_arrow(draw)
    _questline_paint_footer(image, draw, quote_row)
    return snap_image_to_palette(image, SPECTRA6_PALETTE)


# ─── chrono (16-bit SNES JRPG dialogue) ──────────────────────────────────────
#
# The 16-bit counterpart to questline's 8-bit scene (Final Fantasy VI /
# Chrono Trigger era): a gradient twilight sky, the translucent-blue gradient
# dialogue window with a rounded border, and a portrait sub-window. Pixelify
# Sans gives the matched phrase a real Bold weight on top of the yellow
# accent. HH:MM is never shown — the matched phrase carries the time.

# Portrait motif — an ornate hourglass (a drawn face reads as crude on six
# inks). Each material carries a multi-tone shading ramp so brass, glass and
# sand read as lit volumes. Sculpted at a low logical resolution into a
# tone-indexed 'L' image (`_chrono_build_hourglass`), then upscaled and
# dither-mapped to Spectra-6 tones.
#
# Tone index → fill rule. "solid" = one ink; "mix2"/"mix3" = ordered-Bayer
# dithers (the recipes in spectra6_color_recipes.md): cream/gold/bronze brass
# (Y+W / Y / R+Y), amber sand (R+Y at varying density), sky-tint glass (B+W).
_CHRONO_ART_TONES = {
    1: ("solid", SPECTRA6["black"]),                          # outline
    2: ("mix2", SPECTRA6["yellow"], SPECTRA6["white"], 0.55),  # brass highlight (cream)
    3: ("solid", SPECTRA6["yellow"]),                         # brass mid (gold)
    4: ("mix2", SPECTRA6["red"], SPECTRA6["yellow"], 0.25),    # brass shadow (bronze)
    5: ("mix2", SPECTRA6["yellow"], SPECTRA6["white"], 0.6),   # sand highlight (pale)
    6: ("mix2", SPECTRA6["red"], SPECTRA6["yellow"], 0.38),    # sand mid (amber)
    7: ("mix2", SPECTRA6["red"], SPECTRA6["yellow"], 0.20),    # sand shadow (deep amber)
    8: ("mix2", SPECTRA6["blue"], SPECTRA6["white"], 0.55),    # glass tint (sky)
    9: ("solid", SPECTRA6["white"]),                          # specular highlight
}
_CHRONO_ART_SIZE = (56, 72)  # logical pixels before upscale
_CHRONO_ART_SCALE = 2        # → 112×144 px on the panel

_CHRONO_SKY_BOTTOM = 256
_CHRONO_WINDOW = (28, 256, 772, 458)
_CHRONO_PORTRAIT = (32, 222, 180, 394)


def _chrono_tone_color(idx: int, x: int, y: int):
    """Resolve an art tone index to its Spectra-6 (possibly dithered) colour."""
    rule = _CHRONO_ART_TONES[idx]
    kind = rule[0]
    if kind == "solid":
        return rule[1]
    if kind == "mix2":
        _, dark, light, density = rule
        return light if BAYER_4x4[y % 4][x % 4] < round(density * 16) else dark
    _, ink_a, ink_b, ink_c, da, db = rule
    cell = BAYER_4x4[y % 4][x % 4]
    return ink_a if cell < round(da * 16) else (ink_b if cell < round((da + db) * 16) else ink_c)


def _chrono_build_hourglass() -> Image.Image:
    """Sculpt an ornate hourglass as a tone-indexed ('L') logical image.

    A brass frame (capped top/bottom with finials + two shaded side posts), two
    sky-tinted glass bulbs with specular streaks, and amber sand — draining from
    a dished surface in the upper bulb, through the neck as a thin stream, onto a
    mound in the lower bulb. Light from the upper-left (cream highlights up-left,
    bronze / deep-amber shadows down-right). The caller upscales + dither-maps.
    """
    lw, lh = _CHRONO_ART_SIZE
    img = Image.new("L", (lw, lh), 0)
    d = ImageDraw.Draw(img)
    K = 1
    top_bulb = [(14, 9), (42, 9), (31, 37), (25, 37)]
    bot_bulb = [(25, 37), (31, 37), (42, 63), (14, 63)]
    # Glass bulbs (sky tint).
    d.polygon(top_bulb, fill=8)
    d.polygon(bot_bulb, fill=8)
    # Sand: dished surface in the upper bulb, a mound in the lower, a thin stream.
    d.polygon([(20, 22), (36, 22), (31, 37), (25, 37)], fill=6)
    d.line((20, 22, 28, 25), fill=7, width=1)
    d.line((36, 22, 28, 25), fill=7, width=1)
    d.line((22, 23, 34, 23), fill=5, width=1)
    d.polygon([(14, 63), (42, 63), (28, 48)], fill=6)
    d.line((28, 48, 15, 62), fill=5, width=1)
    d.line((29, 49, 41, 62), fill=7, width=1)
    d.line((28, 37, 28, 48), fill=6, width=1)
    d.point((28, 41), fill=5)
    d.point((28, 45), fill=5)
    # Glass specular streaks (upper-left of each bulb).
    d.line((19, 13, 23, 21), fill=9, width=1)
    d.point((20, 23), fill=9)
    d.line((20, 41, 22, 46), fill=9, width=1)
    # Glass outline.
    d.polygon(top_bulb, outline=K)
    d.polygon(bot_bulb, outline=K)
    # Brass side posts (cream highlight left, bronze shadow right).
    for px0, px1 in ((8, 12), (44, 48)):
        d.rectangle((px0, 8, px1, 64), fill=3, outline=K)
        d.line((px0 + 1, 9, px0 + 1, 63), fill=2, width=1)
        d.line((px1 - 1, 9, px1 - 1, 63), fill=4, width=1)
    # Brass caps (cream highlight top, bronze shadow bottom) + finials.
    for cy0, cy1 in ((3, 9), (63, 69)):
        d.rectangle((4, cy0, 52, cy1), fill=3, outline=K)
        d.line((5, cy0 + 1, 51, cy0 + 1), fill=2, width=1)
        d.line((5, cy1 - 1, 51, cy1 - 1), fill=4, width=1)
    d.rectangle((25, 0, 31, 3), fill=3, outline=K)
    d.rectangle((25, 69, 31, 71), fill=3, outline=K)
    return img


def _chrono_paint_hourglass(image: Image.Image, ox: int, oy: int) -> None:
    """Upscale the logical hourglass and paint it at (ox, oy), dither-mapping tones.

    The dither is sampled at absolute panel coordinates so the synthesised
    brass / sand / glass tones share a continuous Bayer phase with the frame.
    """
    big = _chrono_build_hourglass().resize(
        (_CHRONO_ART_SIZE[0] * _CHRONO_ART_SCALE, _CHRONO_ART_SIZE[1] * _CHRONO_ART_SCALE),
        Image.NEAREST,
    )
    bw, bh = big.size
    src = big.load()
    dst = image.load()
    width, height = image.size
    for y in range(bh):
        gy = oy + y
        if gy < 0 or gy >= height:
            continue
        for x in range(bw):
            idx = src[x, y]
            if not idx:
                continue
            gx = ox + x
            if 0 <= gx < width:
                dst[gx, gy] = _chrono_tone_color(idx, gx, gy)
_CHRONO_STAR_SEED = 0xC470


def _chrono_fill_poly(image: Image.Image, points, dark, light, density: float) -> None:
    """Fill a polygon with a Bayer two-ink stipple (for navy mountain silhouettes)."""
    w, h = image.size
    mask = Image.new("L", (w, h), 0)
    ImageDraw.Draw(mask).polygon(points, fill=255)
    bbox = mask.getbbox()
    if bbox is None:
        return
    x0, y0, x1, y1 = bbox
    px = image.load()
    mx = mask.load()
    threshold = round(density * 16)
    for y in range(y0, y1):
        for x in range(x0, x1):
            if mx[x, y]:
                px[x, y] = light if BAYER_4x4[y % 4][x % 4] < threshold else dark


def _chrono_paint_sky(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """Gradient twilight sky: deep navy at the zenith fading to a hazy horizon,
    with deterministic stars, a pale moon, and a two-range mountain silhouette.

    A per-row Bayer density ramp: black density falls from the zenith to
    mid-sky, then white density rises toward the horizon (haze).
    """
    width = image.size[0]
    BLUE = SPECTRA6["blue"]
    BLACK = SPECTRA6["black"]
    WHITE = SPECTRA6["white"]
    px = image.load()
    bottom = _CHRONO_SKY_BOTTOM
    # Clip the PixelAccess writes to the image height: `bottom` anchors the
    # ramp, but /api/preview renders canvases as short as ~60 px.
    for y in range(min(bottom, image.size[1])):
        if y < 130:
            # Zenith → mid: navy fading to pure blue (black density 0.42 → 0).
            d = 0.42 * (1 - y / 130)
            light, dark = BLACK, BLUE
        else:
            # Mid → horizon: pure blue gaining a haze of white (0 → 0.38).
            d = 0.38 * ((y - 130) / (bottom - 130))
            light, dark = WHITE, BLUE
        threshold = round(d * 16)
        row = BAYER_4x4[y % 4]
        for x in range(width):
            px[x, y] = light if row[x % 4] < threshold else dark
    # Stars — deterministic white specks in the upper sky, clear of the moon.
    rng = random.Random(_CHRONO_STAR_SEED)
    moon_cx, moon_cy, moon_r = 648, 72, 30
    for _ in range(70):
        sx = rng.randint(6, width - 6)
        sy = rng.randint(8, 150)
        if (sx - moon_cx) ** 2 + (sy - moon_cy) ** 2 < (moon_r + 14) ** 2:
            continue
        draw.point((sx, sy), fill=WHITE)
        if rng.random() < 0.22:  # a few brighter 2×2 stars
            draw.rectangle((sx, sy, sx + 1, sy + 1), fill=WHITE)
    # Distant mountain ranges (back lighter, front navy) for parallax depth.
    # Peaks are offsets above ``bottom`` (the horizon) so they follow it if
    # the sky height changes.
    draw.polygon(
        [(0, bottom), (0, bottom - 86), (150, bottom - 46), (320, bottom - 100),
         (520, bottom - 52), (700, bottom - 96), (width, bottom - 58), (width, bottom)],
        fill=BLUE,
    )
    _chrono_fill_poly(
        image,
        [(0, bottom), (0, bottom - 34), (180, bottom - 72), (360, bottom - 26),
         (560, bottom - 70), (760, bottom - 28), (width, bottom - 56), (width, bottom)],
        dark=BLUE, light=BLACK, density=0.5,
    )
    # Pale moon with a couple of faint navy craters.
    draw.ellipse((moon_cx - moon_r, moon_cy - moon_r, moon_cx + moon_r, moon_cy + moon_r), fill=WHITE)
    for (cx, cy, cr) in ((moon_cx - 8, moon_cy - 6, 5), (moon_cx + 9, moon_cy + 7, 4), (moon_cx + 2, moon_cy - 11, 3)):
        _fill_swatch_stipple(image, (cx - cr, cy - cr, cx + cr, cy + cr), dark=WHITE, light=BLUE, light_density=0.5)


def _chrono_window_fill(image: Image.Image, rect: tuple[int, int, int, int], radius: int) -> None:
    """Translucent-blue gradient window fill, clipped to a rounded rectangle.

    Painted on a private tile (top navy → bottom blue with a faint sky-blue
    sheen) and pasted through a rounded-rectangle mask, so the corners read as
    the soft rounded FF-window silhouette rather than a hard rectangle.
    """
    x0, y0, x1, y1 = rect
    w, h = x1 - x0, y1 - y0
    BLUE = SPECTRA6["blue"]
    BLACK = SPECTRA6["black"]
    WHITE = SPECTRA6["white"]
    tile = Image.new("RGB", (w, h), BLUE)
    tpx = tile.load()
    for j in range(h):
        frac = j / max(1, h - 1)
        if frac < 0.5:
            d = 0.5 * (1 - frac / 0.5)  # navy top → blue mid
            light, dark = BLACK, BLUE
        else:
            d = 0.16 * ((frac - 0.5) / 0.5)  # faint sky-blue sheen toward the foot
            light, dark = WHITE, BLUE
        threshold = round(d * 16)
        row = BAYER_4x4[j % 4]
        for i in range(w):
            tpx[i, j] = light if row[i % 4] < threshold else dark
    mask = Image.new("L", (w, h), 0)
    ImageDraw.Draw(mask).rounded_rectangle((0, 0, w - 1, h - 1), radius=radius, fill=255)
    image.paste(tile, (x0, y0), mask)


def _chrono_window_border(draw: ImageDraw.ImageDraw, rect: tuple[int, int, int, int], radius: int) -> None:
    """White rounded double border with small yellow corner accents (FF window)."""
    WHITE = SPECTRA6["white"]
    YELLOW = SPECTRA6["yellow"]
    x0, y0, x1, y1 = rect
    draw.rounded_rectangle(rect, radius=radius, outline=WHITE, width=3)
    draw.rounded_rectangle((x0 + 6, y0 + 6, x1 - 6, y1 - 6), radius=max(2, radius - 4), outline=WHITE, width=1)
    # Small yellow accent ticks just inside each corner.
    for (cx, cy) in ((x0 + 12, y0 + 12), (x1 - 13, y0 + 12), (x0 + 12, y1 - 13), (x1 - 13, y1 - 13)):
        draw.rectangle((cx, cy, cx + 2, cy + 2), fill=YELLOW)


def _chrono_paint_portrait(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """Portrait sub-window (a smaller FF window) holding the shaded hourglass."""
    rect = _CHRONO_PORTRAIT
    _chrono_window_fill(image, rect, radius=14)
    _chrono_window_border(draw, rect, radius=14)
    art_w = _CHRONO_ART_SIZE[0] * _CHRONO_ART_SCALE
    art_h = _CHRONO_ART_SIZE[1] * _CHRONO_ART_SCALE
    cx = (rect[0] + rect[2]) // 2
    cy = (rect[1] + rect[3]) // 2
    _chrono_paint_hourglass(image, cx - art_w // 2, cy - art_h // 2)


def _chrono_paint_dialogue(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict, rect: tuple[int, int, int, int]) -> None:
    """Speaker-name header + the quote as left-aligned dialogue.

    Author name (uppercased, truncated) as a white Pixelify Sans Bold header
    line, then the quote body below with the matched time-phrase in yellow
    Pixelify Sans Bold — a real weight step, not just a recolour.
    """
    WHITE = SPECTRA6["white"]
    YELLOW = SPECTRA6["yellow"]
    x0, y0, x1, y1 = rect
    box_w = x1 - x0
    # Speaker-name header.
    author = (quote_row.get("author") or "").strip()
    name = (author or "NARRATOR").upper()
    name_font = load_font(theme_font_candidates("chrono", "quote_bold"), size=19)
    while name and draw.textlength(name, font=name_font) > box_w:
        name = name[:-1]
    nb = draw.textbbox((0, 0), name, font=name_font)
    draw.text((x0 - nb[0], y0 - nb[1]), name, font=name_font, fill=WHITE)
    body_top = y0 + (nb[3] - nb[1]) + 8

    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    matched = quote_row.get("matched_text") or ""
    quote_font, quote_font_bold, wrapped_quote, line_height, _ = fit_quote(
        draw, display_quote, matched, box_w, y1 - body_top,
        font_max=54, font_min=14, line_height_mult=1.32, theme="chrono",
    )
    body_ascent = _font_ascent(quote_font)
    y = body_top
    for line in wrapped_quote:
        start = 0
        while start < len(line) and line[start][0].strip() == "":
            start += 1
        end = len(line)
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        x = x0
        for chunk, is_bold in line[start:end]:
            font = quote_font_bold if is_bold else quote_font
            chunk_y = y + (body_ascent - _font_ascent(font))
            draw.text((x, chunk_y), chunk, font=font, fill=YELLOW if is_bold else WHITE)
            bbox = draw.textbbox((0, 0), chunk, font=font)
            x += bbox[2] - bbox[0]
        y += line_height


def _chrono_paint_arrow(draw: ImageDraw.ImageDraw) -> None:
    """Yellow ▼ continue arrow in the window's bottom-right."""
    YELLOW = SPECTRA6["yellow"]
    x1, y1 = _CHRONO_WINDOW[2], _CHRONO_WINDOW[3]
    cx, cy = x1 - 30, y1 - 24
    draw.polygon([(cx - 8, cy - 6), (cx + 8, cy - 6), (cx, cy + 7)], fill=YELLOW)


def _chrono_paint_footer(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """'— from {Title} —' in white along the window's bottom inner margin."""
    font = load_font(theme_font_candidates("chrono", "quote_regular"), size=12)
    text = _fit_from_title(draw, quote_row, font, (_CHRONO_WINDOW[2] - _CHRONO_WINDOW[0]) - 140)
    if text is None:
        return
    bbox = draw.textbbox((0, 0), text, font=font)
    cx = (_CHRONO_WINDOW[0] + _CHRONO_WINDOW[2]) // 2 + 50  # nudge clear of the portrait
    fx = cx - (bbox[2] - bbox[0]) // 2 - bbox[0]
    fy = _CHRONO_WINDOW[3] - 18 - bbox[1]
    # Solid white: a sky-blue B+W dither averages too close to the blue window
    # fill to stay legible at this size.
    draw.text((fx, fy), text, font=font, fill=SPECTRA6["white"])


def render_chrono_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """16-bit SNES JRPG dialogue scene (see the module section comment above).

    ``time_str`` is unused (the matched phrase carries the time); kept for
    dispatch-signature uniformity.
    """
    del time_str  # see docstring; deliberately unused.
    image = Image.new("RGB", (width, height), color=SPECTRA6["blue"])
    draw = ImageDraw.Draw(image)
    _chrono_paint_sky(image, draw)
    _chrono_window_fill(image, _CHRONO_WINDOW, radius=18)
    _chrono_window_border(draw, _CHRONO_WINDOW, radius=18)
    _chrono_paint_portrait(image, draw)
    # Dialogue text sits right of the portrait, inside the window.
    px1 = _CHRONO_PORTRAIT[2]
    _chrono_paint_dialogue(image, draw, quote_row, (px1 + 16, _CHRONO_WINDOW[1] + 14, _CHRONO_WINDOW[2] - 24, _CHRONO_WINDOW[3] - 30))
    _chrono_paint_arrow(draw)
    _chrono_paint_footer(image, draw, quote_row)
    return snap_image_to_palette(image, SPECTRA6_PALETTE)


# ── outrun (synthwave) ──────────────────────────────────────────────────────
# Reference geometry is the 800×480 panel. All raw PixelAccess writes are
# bounds-clipped (/api/preview renders down to ~60 px tall), so a shorter
# canvas just crops the lower composition.
_OUTRUN_HORIZON = 300                  # sky/grid divide
_OUTRUN_SUN_CENTER = (400, 332)        # disc centre sits below the horizon …
_OUTRUN_SUN_RADIUS = 132               # … so only the upper cap shows as a half-sun
_OUTRUN_QUOTE_RECT = (60, 38, 740, 150)  # x0, y0, x1, y1 — quote block in the dark sky
_OUTRUN_STAR_SEED = 0x07A50


def _outrun_line_points(x0: int, y0: int, x1: int, y1: int):
    """Integer Bresenham point list — PIL has no per-pixel line colour, and the
    neon grid lines alternate two inks per pixel to synthesise magenta / cyan."""
    points = []
    dx = abs(x1 - x0)
    dy = -abs(y1 - y0)
    sx = 1 if x0 < x1 else -1
    sy = 1 if y0 < y1 else -1
    err = dx + dy
    while True:
        points.append((x0, y0))
        if x0 == x1 and y0 == y1:
            break
        e2 = 2 * err
        if e2 >= dy:
            err += dy
            x0 += sx
        if e2 <= dx:
            err += dx
            y0 += sy
    return points


def _outrun_paint_sky(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """Vertical Bayer-gradient twilight sky + deterministic stars.

    Two stacked density ramps: indigo navy (blue + black) at the zenith fading
    to pure blue, then blue gaining red toward a purple horizon. The ink pair
    swaps where the black density reaches 0, so there is no visible seam. Warm
    colour is reserved for the sun, keeping the white quote high-contrast.
    """
    width, height = image.size
    BLUE = SPECTRA6["blue"]
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    WHITE = SPECTRA6["white"]
    horizon = _OUTRUN_HORIZON
    px = image.load()
    for y in range(min(horizon, height)):
        frac = y / horizon
        if frac < 0.42:
            # Zenith indigo navy → pure blue (black wash 0.55 → 0).
            d = 0.55 * (1 - frac / 0.42)
            dark, light = BLUE, BLACK
        else:
            # Blue → purple at the horizon. Red density peaks at 0.36 (not
            # 50/50): red out-luminates blue, so an even mix reads hot.
            d = 0.36 * ((frac - 0.42) / 0.58)
            dark, light = BLUE, RED
        threshold = round(d * 16)
        row = BAYER_4x4[y % 4]
        for x in range(width):
            px[x, y] = light if row[x % 4] < threshold else dark
    # Stars — deterministic white specks in the upper sky, above the sun cap.
    rng = random.Random(_OUTRUN_STAR_SEED)
    star_ceiling = min(_OUTRUN_SUN_CENTER[1] - _OUTRUN_SUN_RADIUS - 4, height - 1)
    for _ in range(70):
        sx = rng.randint(4, width - 4)
        sy = rng.randint(6, max(7, star_ceiling))
        if 0 <= sx < width and 0 <= sy < height:
            px[sx, sy] = WHITE
            if rng.random() < 0.18 and sx + 1 < width and sy + 1 < height:
                px[sx + 1, sy] = WHITE
                px[sx, sy + 1] = WHITE


def _outrun_paint_grid(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """Dark ground + neon perspective grid + a bright horizon line.

    Magenta verticals (red/blue per-pixel alternation) fan out from a central
    vanishing point; cyan horizontals (green/blue alternation) are spaced
    densest near the horizon. The alternation reads as solid neon at distance.
    """
    width, height = image.size
    BLUE = SPECTRA6["blue"]
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    GREEN = SPECTRA6["green"]
    WHITE = SPECTRA6["white"]
    horizon = _OUTRUN_HORIZON
    if horizon >= height:
        return
    px = image.load()
    # Dark near-black ground with a faint blue tint so the neon grid pops.
    for y in range(horizon, height):
        row = BAYER_4x4[y % 4]
        for x in range(width):
            px[x, y] = BLUE if row[x % 4] < 2 else BLACK
    # Vertical magenta lines fanning from the vanishing point to the foot.
    vp_x = width // 2
    for k in range(-9, 10):
        bx = vp_x + k * 96
        for (x, y) in _outrun_line_points(vp_x, horizon, bx, height - 1):
            if 0 <= x < width and horizon <= y < height:
                px[x, y] = RED if (x + y) & 1 else BLUE
    # Horizontal cyan lines, perspective-spaced (t² → tight near the horizon).
    rows = 9
    span = height - horizon
    for i in range(1, rows + 1):
        t = i / rows
        yy = horizon + int(span * (t * t))
        if yy >= height:
            yy = height - 1
        for x in range(width):
            px[x, yy] = GREEN if (x + yy) & 1 else BLUE
    # Bright horizon line with a cyan under-glow.
    for x in range(width):
        for hy in (horizon - 1, horizon):
            if 0 <= hy < height:
                px[x, hy] = WHITE
        gy = horizon + 1
        if gy < height:
            px[x, gy] = GREEN if x & 1 else BLUE


def _outrun_paint_sun(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """The retrowave half-sun: a warm gradient disc cap sliced by widening slits.

    Only the cap above the horizon is painted (the centre sits below it). The
    cap carries a golden → tangerine → magenta gradient across its *visible*
    height, and unpainted slits, widening toward the horizon, let the sky show
    through.
    """
    width, height = image.size
    BLUE = SPECTRA6["blue"]
    RED = SPECTRA6["red"]
    YELLOW = SPECTRA6["yellow"]
    cx, cy = _OUTRUN_SUN_CENTER
    R = _OUTRUN_SUN_RADIUS
    horizon = _OUTRUN_HORIZON
    top_vis = cy - R
    if top_vis >= horizon or top_vis >= height:
        return
    # Slit bands: y-intervals (left unpainted) widening toward the horizon.
    slits = []
    pos = horizon
    i = 0
    while pos > top_vis + 34:
        gap = max(2, 14 - i * 3)
        slits.append((pos - gap, pos))
        pos -= gap + 7
        i += 1

    def in_slit(yy: int) -> bool:
        for lo, hi in slits:
            if lo <= yy < hi:
                return True
        return False

    visible_h = horizon - top_vis
    px = image.load()
    y_lo = max(0, top_vis)
    y_hi = min(horizon, height)
    for y in range(y_lo, y_hi):
        if in_slit(y):
            continue
        # Vertical position across the *visible* cap (0 top → 1 at horizon).
        tv = (y - top_vis) / visible_h
        if tv < 0.34:
            dark, light, d = RED, YELLOW, 0.60      # warm golden crown
        elif tv < 0.66:
            dark, light, d = RED, YELLOW, 0.375     # tangerine body
        else:
            dark, light, d = RED, BLUE, 0.42        # magenta foot melting into the sky
        threshold = round(d * 16)
        row = BAYER_4x4[y % 4]
        # Horizontal span of the disc at this row.
        half = int((R * R - (y - cy) ** 2) ** 0.5)
        x_lo = max(0, cx - half)
        x_hi = min(width, cx + half)
        for x in range(x_lo, x_hi):
            px[x, y] = light if (d > 0 and row[x % 4] < threshold) else dark


def _outrun_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The literary quote in white Oxanium, matched phrase in synthesised magenta.

    Centred line-by-line in the dark upper sky; the body is solid white. The
    matched phrase is a 5/8:3/8 red+blue stipple: red-biased because a 50/50
    mix's blue half melts into the blue sky behind it and reads dim.
    """
    width = image.size[0]
    WHITE = SPECTRA6["white"]
    BLUE = SPECTRA6["blue"]
    RED = SPECTRA6["red"]
    x0, y0, x1, y1 = _OUTRUN_QUOTE_RECT
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    matched = quote_row.get("matched_text") or ""
    quote_font, quote_font_bold, wrapped, line_height, _ = fit_quote(
        draw, display_quote, matched, x1 - x0, y1 - y0,
        font_max=36, font_min=15, line_height_mult=1.18, theme="outrun",
    )
    block_h = len(wrapped) * line_height
    y = y0 + max(0, ((y1 - y0) - block_h) // 2)
    ascent = _font_ascent(quote_font)
    for line in wrapped:
        start = 0
        while start < len(line) and line[start][0].strip() == "":
            start += 1
        end = len(line)
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        drawable = line[start:end]
        line_w = 0
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            bbox = draw.textbbox((0, 0), chunk, font=font)
            line_w += bbox[2] - bbox[0]
        x = (width - line_w) // 2
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            chunk_y = y + (ascent - _font_ascent(font))
            if is_bold and chunk.strip():
                draw_text_dithered(image, (x, chunk_y), chunk, font, dark=RED, light=BLUE, light_density=0.375)
            else:
                draw.text((x, chunk_y), chunk, font=font, fill=WHITE)
            bbox = draw.textbbox((0, 0), chunk, font=font)
            x += bbox[2] - bbox[0]
        y += line_height


def _outrun_paint_credits(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """Author (white) + title (magenta) credit line below the quote, in Antonio.

    Sits between the quote block and the sun cap. The title uses the matched
    phrase's red-biased magenta stipple so it holds against the blue sky.
    """
    width = image.size[0]
    WHITE = SPECTRA6["white"]
    BLUE = SPECTRA6["blue"]
    RED = SPECTRA6["red"]
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "")
    y = _OUTRUN_QUOTE_RECT[3] + 8
    max_w = width - 120
    if author:
        font = load_font([(ANTONIO_VARIABLE, "Bold"), *META_FONT_BOLD_CANDIDATES], size=15)
        text = author.upper()
        while text and draw.textlength(text, font=font) > max_w:
            text = text[:-1]
        bbox = draw.textbbox((0, 0), text, font=font)
        fx = (width - (bbox[2] - bbox[0])) // 2 - bbox[0]
        draw.text((fx, y - bbox[1]), text, font=font, fill=WHITE)
        y += (bbox[3] - bbox[1]) + 5
    if title:
        font = load_font([(ANTONIO_VARIABLE, "Regular"), *META_FONT_CANDIDATES], size=13)
        text = title
        while text and draw.textlength(f"— {text} —", font=font) > max_w:
            text = text[:-1]
        label = f"— {text} —"
        bbox = draw.textbbox((0, 0), label, font=font)
        fx = (width - (bbox[2] - bbox[0])) // 2 - bbox[0]
        draw_text_dithered(image, (fx, y - bbox[1]), label, font, dark=RED, light=BLUE, light_density=0.375)


def render_outrun_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """1980s synthwave / Outrun sunset (see the module section comment above).

    ``time_str`` is unused (the matched phrase carries the time); kept for
    dispatch-signature uniformity.
    """
    del time_str  # see docstring; deliberately unused.
    image = Image.new("RGB", (width, height), color=SPECTRA6["black"])
    draw = ImageDraw.Draw(image)
    _outrun_paint_sky(image, draw)
    _outrun_paint_grid(image, draw)
    _outrun_paint_sun(image, draw)
    _outrun_paint_quote(image, draw, quote_row)
    _outrun_paint_credits(image, draw, quote_row)
    return snap_image_to_palette(image, SPECTRA6_PALETTE)


# ── sampler: counted cross-stitch embroidery ──────────────────────────────────
# Every glyph is cross-stitch "X" marks: text is drawn to a small Silkscreen
# pixel-font mask and each set pixel is stamped as one stitch cell on an Aida
# ground. A stitched floral border and sampler motifs fill the margins. Body
# floss is black, the matched phrase red; HH:MM is never shown. No RNG, so
# re-renders are byte-identical.

# Floss palette — every stitch is one Spectra-6 ink.
_SAMPLER_FLOSS = {
    "K": SPECTRA6["black"],
    "R": SPECTRA6["red"],
    "G": SPECTRA6["green"],
    "B": SPECTRA6["blue"],
    "Y": SPECTRA6["yellow"],
    "W": SPECTRA6["white"],
}
# Stitch-cell sizes tried largest-first by the body fit loop.
_SAMPLER_STITCH_SIZES = (6, 5, 4, 3)
# Quote area, in panel px — clear of the border frame, the alphabet row above,
# and the credits / motif band below. Body layout is computed in mask-pixel
# units (panel px // stitch size) and scaled up at stitch time.
_SAMPLER_BODY_RECT = (96, 90, 704, 300)
# Blank mask rows above the Silkscreen cap line, trimmed from the layout so the
# stitched block isn't top-heavy with empty fabric.
_SAMPLER_TOP_SKIP = 3
# Mask rows allotted per text line (Silkscreen cap height ~5 + descender + gap).
_SAMPLER_LINE_ROWS = 8
_SAMPLER_WEAVE_PITCH = 4  # Aida-cloth thread-crossing grid pitch, in panel px.

# Small motif grids — one character per stitch cell, space = skip. Tiled / placed
# by _sampler_paint_border / _sampler_paint_motifs. Colours are _SAMPLER_FLOSS keys.
_SAMPLER_FLOWER_B = (" B ", "BYB", " B ")          # blue petals, yellow centre
_SAMPLER_FLOWER_Y = (" Y ", "YBY", " Y ")          # yellow petals, blue centre
_SAMPLER_HOUSE = (
    "   R   ",
    "  RRR  ",
    " RRRRR ",
    "RRRRRRR",
    "GYYBYYG",
    "GYYBYYG",
)
_SAMPLER_HEART = ("RR RR", "RRRRR", "RRRRR", " RRR ", "  R  ")
_SAMPLER_BIRD = ("  B  ", " BBBB", "BBBBB", " B B ")
_SAMPLER_TREE = ("  G  ", " GGG ", "GGGGG", " GGG ", "  K  ")


def _sampler_stitch_x(px, cx: int, cy: int, color, width: int, height: int, size: int) -> None:
    """Stamp one cross-stitch ``X`` into a ``size``×``size`` cell at (cx, cy).

    Every ``px[x, y]`` write is bounds-guarded: ``PixelAccess`` raises
    ``IndexError`` out of range, and ``/api/preview`` renders smaller canvases.
    """
    n = size - 1

    def put(x: int, y: int) -> None:
        if 0 <= x < width and 0 <= y < height:
            px[x, y] = color

    # Corner-to-corner diagonals: an inset, 1-px X washes out at small cell
    # sizes. Adjacent cells' arms meet at the corners, as real stitching does.
    for i in range(n + 1):
        put(cx + i, cy + i)
        put(cx + i, cy + (n - i))
    # Thicken each arm by one pixel on cells big enough to carry it.
    if size >= 4:
        for i in range(n):
            put(cx + i + 1, cy + i)
            put(cx + i, cy + (n - i - 1))


def _sampler_stamp_motif(px, motif, ox: int, oy: int, size: int, width: int, height: int) -> None:
    """Stamp a character-grid motif as stitches, top-left at (ox, oy)."""
    for row, line in enumerate(motif):
        for col, ch in enumerate(line):
            color = _SAMPLER_FLOSS.get(ch)
            if color is None:
                continue
            _sampler_stitch_x(px, ox + col * size, oy + row * size, color, width, height, size)


def _sampler_paint_aida(image: Image.Image) -> None:
    """Aida-cloth ground: white with a yellow fleck on a regular weave grid.

    One fleck per ``_SAMPLER_WEAVE_PITCH`` cell (~6% yellow at pitch 4). A
    sparse *regular* grid reads as thread crossings where a Bayer wash would
    read as tint, and keeps the black floss high-contrast.
    """
    width, height = image.size
    px = image.load()
    white, yellow = SPECTRA6["white"], SPECTRA6["yellow"]
    for y in range(height):
        for x in range(width):
            px[x, y] = white
    for y in range(0, height, _SAMPLER_WEAVE_PITCH):
        for x in range(0, width, _SAMPLER_WEAVE_PITCH):
            px[x, y] = yellow


def _sampler_paint_border(image: Image.Image) -> None:
    """A stitched cross-stitch border: an alternating green-leaf / red-bud vine
    frame with blue + yellow flower motifs at the corners and mid-edges.

    Built entirely from the stitch primitive; deterministic.
    """
    width, height = image.size
    px = image.load()
    size = 6
    inset = 30
    x0, y0 = inset, inset
    x1, y1 = width - inset - size, height - inset - size
    red, green = SPECTRA6["red"], SPECTRA6["green"]

    def vine(x: int, y: int, i: int) -> None:
        # Pairs of green leaf stitches alternate with pairs of red buds.
        _sampler_stitch_x(px, x, y, green if (i // 2) % 2 == 0 else red, width, height, size)

    i = 0
    for x in range(x0, x1 + 1, size):
        vine(x, y0, i)
        vine(x, y1, i)
        i += 1
    i = 0
    for y in range(y0, y1 + 1, size):
        vine(x0, y, i)
        vine(x1, y, i)
        i += 1

    # Corner + mid-edge flowers (blue / yellow), centred on the frame line.
    mid_x = (x0 + x1) // 2 - size
    mid_y = (y0 + y1) // 2 - size
    fb, fy = _SAMPLER_FLOWER_B, _SAMPLER_FLOWER_Y
    _sampler_stamp_motif(px, fb, x0 - size, y0 - size, size, width, height)
    _sampler_stamp_motif(px, fy, x1 - size, y0 - size, size, width, height)
    _sampler_stamp_motif(px, fy, x0 - size, y1 - size, size, width, height)
    _sampler_stamp_motif(px, fb, x1 - size, y1 - size, size, width, height)
    _sampler_stamp_motif(px, fy, mid_x, y0 - size, size, width, height)
    _sampler_stamp_motif(px, fy, mid_x, y1 - size, size, width, height)
    _sampler_stamp_motif(px, fb, x0 - size, mid_y, size, width, height)
    _sampler_stamp_motif(px, fb, x1 - size, mid_y, size, width, height)


def _sampler_paint_motifs(image: Image.Image) -> None:
    """Classic sampler furniture stitched in the lower margin: a house centred
    with a heart, a bird, and a tree flanking it. Sits below the credits band
    and above the bottom border, clear of the body rect. Deterministic.
    """
    width, height = image.size
    px = image.load()
    size = 6
    band_y = height - 30 - size - 6 * size  # top of the 6-row motif band
    cx = width // 2
    _sampler_stamp_motif(px, _SAMPLER_HOUSE, cx - (len(_SAMPLER_HOUSE[0]) * size) // 2, band_y, size, width, height)
    _sampler_stamp_motif(px, _SAMPLER_HEART, cx - 150, band_y + size, size, width, height)
    _sampler_stamp_motif(px, _SAMPLER_BIRD, cx + 110, band_y + size, size, width, height)
    _sampler_stamp_motif(px, _SAMPLER_TREE, cx - 230, band_y, size, width, height)
    _sampler_stamp_motif(px, _SAMPLER_TREE, cx + 190, band_y, size, width, height)


def _sampler_stitch_chunk(image, draw, px, chunk, font, x_px, origin_y, size, color, width, height) -> int:
    """Stitch one text chunk in ``color``; return the panel-px advance.

    The chunk is rendered to an ``L`` mask in the pixel font and every set mask
    pixel becomes a stitch cell. The mask keeps the font's full row coordinates
    (no per-chunk vertical crop) so regular and bold chunks share a baseline.
    """
    advance = int(round(draw.textlength(chunk, font=font)))
    if not chunk.strip():  # whitespace: no stitches, just advance the cursor
        return advance * size
    bbox = draw.textbbox((0, 0), chunk, font=font)
    cw = max(advance, bbox[2]) + 1
    ch = bbox[3] + 1
    mask = Image.new("L", (cw, ch), 0)
    ImageDraw.Draw(mask).text((0, 0), chunk, font=font, fill=255)
    mpx = mask.load()
    for my in range(ch):
        ty = my - _SAMPLER_TOP_SKIP
        if ty < 0:
            continue
        cell_y = origin_y + ty * size
        for mx in range(cw):
            if mpx[mx, my] >= 128:
                _sampler_stitch_x(px, x_px + mx * size, cell_y, color, width, height, size)
    return advance * size


def _sampler_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> int:
    """Stitch the literary quote, centred in the body rect, body floss in black
    with the matched time-phrase in red floss. Returns the bottom y of the
    stitched block so the credits can sit beneath it.
    """
    width, height = image.size
    bx0, by0, bx1, by1 = _SAMPLER_BODY_RECT
    body_w = bx1 - bx0
    body_h = by1 - by0
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    matched = quote_row.get("matched_text") or ""
    segments = tokenize_quote(display_quote, matched)
    body_color, accent_color = SPECTRA6["black"], SPECTRA6["red"]

    # Fit: pick the largest stitch size whose wrapped block fits the rect.
    chosen_size = _SAMPLER_STITCH_SIZES[-1]
    chosen_lines: list = []
    for size in _SAMPLER_STITCH_SIZES:
        mask_font = load_font(theme_font_candidates("sampler", "quote_regular"), 8)
        mask_bold = load_font(theme_font_candidates("sampler", "quote_bold"), 8)
        max_cols = max(1, body_w // size)
        lines = wrap_styled_text(draw, segments, mask_font, mask_bold, max_cols)
        block_h = len(lines) * _SAMPLER_LINE_ROWS * size
        chosen_size, chosen_lines = size, lines
        if block_h <= body_h:
            break

    mask_font = load_font(theme_font_candidates("sampler", "quote_regular"), 8)
    mask_bold = load_font(theme_font_candidates("sampler", "quote_bold"), 8)
    px = image.load()
    line_h = _SAMPLER_LINE_ROWS * chosen_size
    block_h = len(chosen_lines) * line_h
    y = by0 + max(0, (body_h - block_h) // 2)
    for line in chosen_lines:
        start = 0
        while start < len(line) and line[start][0].strip() == "":
            start += 1
        end = len(line)
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        drawable = line[start:end]
        line_w = 0
        for chunk, is_bold in drawable:
            font = mask_bold if is_bold else mask_font
            line_w += int(round(draw.textlength(chunk, font=font))) * chosen_size
        x = bx0 + max(0, (body_w - line_w) // 2)
        for chunk, is_bold in drawable:
            font = mask_bold if is_bold else mask_font
            color = accent_color if is_bold else body_color
            x += _sampler_stitch_chunk(image, draw, px, chunk, font, x, y, chosen_size, color, width, height)
        y += line_h
    return y


def _sampler_paint_credits(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict, block_bottom: int) -> None:
    """Stitch the attribution below the quote: author in blue floss, title in
    green. Small fixed stitch size; single truncated lines.
    """
    width, height = image.size
    px = image.load()
    size = 3
    font = load_font(theme_font_candidates("sampler", "quote_regular"), 8)
    blue, green = SPECTRA6["blue"], SPECTRA6["green"]
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "")
    bx0, _, bx1, _ = _SAMPLER_BODY_RECT
    body_w = bx1 - bx0
    max_cols = max(1, body_w // size)

    def stitch_centred(text: str, y: int, color) -> None:
        while text and int(round(draw.textlength(text, font=font))) > max_cols:
            text = text[:-1]
        if not text:
            return
        line_w = int(round(draw.textlength(text, font=font))) * size
        x = bx0 + max(0, (body_w - line_w) // 2)
        _sampler_stitch_chunk(image, draw, px, text, font, x, y, size, color, width, height)

    y = min(block_bottom + 10, _SAMPLER_BODY_RECT[3] + 12)
    if author:
        stitch_centred(author, y, blue)
        y += _SAMPLER_LINE_ROWS * size + 2
    if title:
        stitch_centred(f"- {title} -", y, green)


def render_sampler_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Counted cross-stitch embroidery sampler (see the module section comment).

    ``time_str`` is unused (the matched phrase carries the time); kept for
    dispatch-signature uniformity.
    """
    del time_str  # see docstring; deliberately unused.
    image = Image.new("RGB", (width, height), color=SPECTRA6["white"])
    draw = ImageDraw.Draw(image)
    _sampler_paint_aida(image)
    _sampler_paint_border(image)
    _sampler_paint_motifs(image)
    block_bottom = _sampler_paint_quote(image, draw, quote_row)
    _sampler_paint_credits(image, draw, quote_row, block_bottom)
    return snap_image_to_palette(image, SPECTRA6_PALETTE)


# ─── lieder (engraved art-song manuscript) ───────────────────────────────────
#
# The quote as the vocal line of a Lied, engraved as lyrics beneath a stave,
# one note per syllable. The clock is carried by the score's furniture:
#
#   * the TIME SIGNATURE is the hour over 4 (7 o'clock → 7/4), so the hour also
#     decides where the barlines fall.
#   * the TEMPO MARK is the minute: an Italian tempo word plus ``♩ = 60 +
#     minute``, which stays musically plausible at every minute.
#
# HH:MM is never printed; the matched phrase, sung in red under its own slur,
# carries the readable time. ``time_str`` IS used here, for that chrome.
#
# Ink discipline is typographic before chromatic:
#   roman black  — the plate: staves, clef, notes, barlines, lyrics, title.
#   italic black — the editorial apparatus: tempo, expression, composer. A
#                  synthesised two-ink tone shatters Alegreya's italic
#                  hairlines at 13px after palette snapping.
#   red          — the sung phrase alone: its lyric, noteheads and slur.
#
# Layer 0 is the shared cream wash (``_astrarium_paint_cream_wash``).
#
# Music glyphs come from the bundled Noto Music face (a treble clef's spiral
# renders as mush from polygons). Its staff is one em tall (draw at ``size = 4 *
# gap``) and its baseline sits on the BOTTOM staff line, so the clef is drawn
# with ``anchor="ls"`` onto that line; noteheads are ink-bbox-centred on their
# pitch instead.

_LIEDER_STAVE_GAP = 7            # px between adjacent staff lines (staff = 4×)
_LIEDER_MARGIN_L = 46
_LIEDER_MARGIN_R = 754
_LIEDER_MAX_SYSTEMS = 3
_LIEDER_BAND = (100, 446)        # vertical band the systems are laid out within
_LIEDER_HEADROOM = 4.0           # staff spaces reserved above a staff (stems/slur)
_LIEDER_LYRIC_OFFSET = 5.0       # staff spaces from staff bottom to lyric baseline
                                 # (clears a down-stem, which hangs 3.4 spaces below a
                                 #  middle-line notehead, by ~7px at the largest lyric)
_LIEDER_STEM_LEN = 3.4           # staff spaces
_LIEDER_PITCH_MIN = -2           # one ledger line below the staff
_LIEDER_PITCH_MAX = 10           # one ledger line above the staff
_LIEDER_FONT_MAX = 26
_LIEDER_FONT_MIN = 13
_LIEDER_SYSTEM_GAP = 6           # px between one system's lyric and the next staff's headroom
# Melodic steps in staff positions (1 = the next line-or-space up), weighted
# toward stepwise motion — a uniform choice reads as noise, not melody.
_LIEDER_MELODY_STEPS = (-4, -3, -2, -2, -1, -1, -1, 0, 1, 1, 1, 2, 2, 3, 4)
# Italian tempo words, one per 12-minute band; paired with ♩ = 60 + minute so
# the word and the metronome figure always agree.
_LIEDER_TEMPO_WORDS = ("Larghetto", "Andante", "Moderato", "Allegretto", "Allegro")
# Expression marks for the second system, chosen by the per-quote seed.
_LIEDER_EXPRESSION = ("dolce", "espressivo", "cantabile", "sotto voce", "teneramente", "con moto")
_MUSIC_G_CLEF = "\U0001D11E"
_MUSIC_NOTEHEAD = "\U0001D158"
_MUSIC_NOTEHEAD_VOID = "\U0001D157"   # half / dotted half
# Rests, longest first — the greedy set used to pad an incomplete final bar.
_MUSIC_RESTS = ((4.0, "\U0001D13B"), (2.0, "\U0001D13C"), (1.0, "\U0001D13D"), (0.5, "\U0001D13E"))
_MUSIC_QUARTER_NOTE = "♩"


def _row_digest(quote_row: dict) -> int:
    """Stable 32-bit FNV-1a digest of a corpus row's identity.

    The single seam for "seed something from the quote". Never use ``hash()``:
    it is PYTHONHASHSEED-salted, so seeds would differ between processes and
    break the golden fixtures and run_clock's unchanged-quote dedup.

    Walks the UTF-8 bytes (the FNV-1a definition), not ``ord()`` code points.
    """
    basis = f"{quote_row.get('source_id')}:{quote_row.get('line_number')}:{quote_row.get('display_quote')}"
    digest = 0x811C9DC5
    for byte in basis.encode("utf-8", "replace"):
        digest = ((digest ^ byte) * 0x01000193) & 0xFFFFFFFF
    return digest


def _lieder_clock(time_str: str) -> tuple[int, int]:
    """``(hour 1..12, minute 0..59)`` parsed defensively from ``HH:MM``.

    Preview and source-card renders can reach this with an odd string; a bad
    parse falls back to 12/00 rather than raising into the render path.
    """
    try:
        hh, mm = time_str.split(":")[:2]
        hour = int(hh) % 12 or 12
        minute = max(0, min(59, int(mm)))
    except (AttributeError, ValueError):
        return 12, 0
    return hour, minute


# Words the syllabifier below gets wrong (TeX's ``\hyphenation{}`` list).
# Keep it small and evidence-driven: only words actually frequent in
# ``quote_database.jsonl`` belong here.
_LIEDER_SYLLABLE_EXCEPTIONS = {
    "another": ("an", "oth", "er"),
    "business": ("busi", "ness"),
    "curious": ("cu", "ri", "ous"),
    "eleven": ("e", "lev", "en"),
    "entirely": ("en", "tire", "ly"),
    "exactly": ("ex", "act", "ly"),
    "precisely": ("pre", "cise", "ly"),
    "quiet": ("qui", "et"),
    "quietly": ("qui", "et", "ly"),
    "serious": ("se", "ri", "ous"),
    "something": ("some", "thing"),
    "sometimes": ("some", "times"),
    "somewhere": ("some", "where"),
    "therefore": ("there", "fore"),
    "various": ("va", "ri", "ous"),
}
# Consonant pairs that are one sound and must never be split across syllables.
_LIEDER_DIGRAPHS = ("th", "sh", "ch", "wh", "ph", "gh", "ck", "ng", "qu")
_LIEDER_VOWELS = frozenset("aeiouy")
# Unstressed function words — set to a weak, short note.
_LIEDER_FUNCTION_WORDS = frozenset(
    "a an the of and to in is was were it its that this these those his her their they them "
    "he she we you i be been am are had has have do did for with on at as by but or from not "
    "no so then than there which who what when all one up out into upon own who's".split()
)
# Prefixes that carry no stress, so the stress falls on the SECOND syllable
# (a-bout, be-fore, re-turn).
_LIEDER_WEAK_PREFIXES = ("a", "be", "re", "de", "con", "ex", "in", "un", "for", "to", "per", "pro")
_LIEDER_PHRASE_END = ".,;:!?—"


def _lieder_syllables(word: str) -> list[str]:
    """Split one word into display syllables.

    A heuristic, deliberately: what matters musically is the syllable *count*
    (how many notes the word gets), not the exact split point. The exception
    table covers frequent words the rules miss.

    Rules, in the order they matter: ``qu`` is a consonant (so ``quiet`` has
    one vowel run, not two); a final silent ``e`` is not a syllable (``time``)
    unless it is the ``-le`` of ``ta-ble``; ``-ed`` is silent except after t/d
    (``slipped`` is one syllable, ``wanted`` two); ``-es`` is silent except
    after a sibilant; a consonant pair that is a digraph never splits; a
    doubled consonant always splits between the pair; and a consonant+``le``
    ending takes the consonant with it.
    """
    core = "".join(ch for ch in word if ch.isalpha() or ch == "'")
    if len(core) <= 3:
        return [word]
    low = core.lower()
    if low in _LIEDER_SYLLABLE_EXCEPTIONS:
        lengths = [len(p) for p in _LIEDER_SYLLABLE_EXCEPTIONS[low]]
        cuts, run = [], 0
        for length in lengths[:-1]:
            run += length
            cuts.append(run)
        return _lieder_apply_cuts(word, cuts)

    groups, i = [], 0
    while i < len(low):
        if low[i] in _LIEDER_VOWELS:
            if low[i] == "u" and i and low[i - 1] == "q":   # "qu" is a consonant
                i += 1
                continue
            j = i
            while j < len(low) and low[j] in _LIEDER_VOWELS:
                if low[j] == "u" and low[j - 1] == "q":
                    break
                j += 1
            groups.append((i, j))
            i = j
        else:
            i += 1
    if len(groups) < 2:
        return [word]

    le_ending = len(low) > 3 and low.endswith("le") and low[-3] not in _LIEDER_VOWELS
    if not le_ending and low.endswith("e") and groups[-1] == (len(low) - 1, len(low)):
        groups.pop()
    if len(groups) > 1 and low.endswith("ed") and low[-3:-2] not in ("t", "d"):
        if groups[-1][0] == len(low) - 2:
            groups.pop()
    if len(groups) > 1 and low.endswith("es") and low[-3:-2] not in ("s", "z", "x", "h", "c", "i"):
        if groups[-1][0] == len(low) - 2:
            groups.pop()
    if len(groups) < 2:
        return [word]

    cuts = []
    for (_, end_a), (start_b, _) in zip(groups, groups[1:]):
        run = low[end_a:start_b]
        n = len(run)
        if le_ending and start_b == len(low) - 1 and n >= 2:
            cut = start_b - 2                       # ta-ble, lit-tle, pos-si-ble
        elif n <= 1:
            cut = end_a                             # o-ver
        elif n == 2:
            cut = end_a if run in _LIEDER_DIGRAPHS else end_a + 1   # an-oth-er / af-ter
        elif run[0] == run[1]:
            cut = end_a + 2                         # still-ness
        elif run[1:3] in _LIEDER_DIGRAPHS:
            cut = end_a + 1
        elif run[:2] in _LIEDER_DIGRAPHS:
            cut = end_a + 2
        else:
            cut = end_a + 1
        cuts.append(cut)
    kept, prev = [], 0
    for cut in cuts:
        # Never strand a fragment of under two letters — it is not a syllable
        # and it looks like a typo under a notehead.
        if cut - prev >= 2 and len(low) - cut >= 2:
            kept.append(cut)
            prev = cut
    return _lieder_apply_cuts(word, kept) if kept else [word]


def _lieder_apply_cuts(word: str, cuts: list[int]) -> list[str]:
    """Slice ``word`` at cut positions expressed in *letters-only* coordinates.

    The cuts are computed against the alphabetic core, but the displayed word
    still carries its punctuation ("o'clock,"), so the indices are mapped back
    onto the original string before slicing.
    """
    if not cuts:
        return [word]
    positions, seen = [], 0
    for index, ch in enumerate(word):
        if seen in cuts and ch.isalpha():
            positions.append(index)
            cuts = [c for c in cuts if c != seen]
        if ch.isalpha() or ch == "'":
            seen += 1
    pieces, start = [], 0
    for pos in positions:
        if pos > start:
            pieces.append(word[start:pos])
            start = pos
    pieces.append(word[start:])
    return [p for p in pieces if p] or [word]


def _lieder_notes(quote_row: dict) -> list[dict]:
    """Build the per-syllable note list: one dict per note, in singing order.

    Each carries what the later passes need — ``matched`` (inside the sung time
    phrase), ``hyphen`` (another syllable of the same word follows, so a lyric
    hyphen is drawn), ``breath`` (a phrase boundary follows) and ``stress``
    (2 phrase-final, 1 stressed, 0 weak), which is what the rhythm pass turns
    into note durations.
    """
    text = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    notes: list[dict] = []
    word_index = 0
    for chunk, matched in tokenize_quote(text, quote_row.get("matched_text") or ""):
        for word in chunk.split():
            bare = word.strip(_LIEDER_PHRASE_END + "\"'”“’")
            low = "".join(ch for ch in bare if ch.isalpha()).lower()
            pieces = _lieder_syllables(word)
            ends_phrase = any(word.endswith(ch) for ch in _LIEDER_PHRASE_END)
            weak_word = low in _LIEDER_FUNCTION_WORDS
            # Stress lands on the second syllable when the word opens with an
            # unstressed prefix (a-BOUT, be-FORE, re-TURN).
            accent = 0
            if len(pieces) > 1 and any(low.startswith(p) for p in _LIEDER_WEAK_PREFIXES):
                accent = 1
            for position, piece in enumerate(pieces):
                last = position == len(pieces) - 1
                if weak_word:
                    stress = 0
                elif position == accent:
                    stress = 1
                else:
                    stress = 0
                if last and ends_phrase:
                    stress = 2
                notes.append({
                    "text": piece,
                    "matched": matched,
                    "hyphen": not last,
                    "breath": last and ends_phrase,
                    "stress": stress,
                    "word": word_index,
                })
            word_index += 1
    if notes:
        notes[-1]["stress"] = 2
        notes[-1]["breath"] = False
    return notes


def _lieder_is_dotted(beats: float) -> bool:
    """A dot adds half again, so 1.5 (dotted quarter) and 3.0 (dotted half)."""
    return abs(beats - 1.5) < 1e-9 or abs(beats - 3.0) < 1e-9


def _lieder_rhythm(notes: list[dict], numerator: int) -> None:
    """Assign each note a duration in beats and mark where barlines fall.

    Durations come from stress: a phrase-final syllable is held (a dotted half
    at the very end), a stressed syllable takes a quarter, a weak one an
    eighth.

    Bars are filled to *exactly* ``numerator`` beats. A note is shortened
    rather than allowed to overflow, since a note straddling a barline would
    need a tie.
    """
    remaining = float(numerator)
    for index, note in enumerate(notes):
        if remaining <= 1e-9:
            remaining = float(numerator)
            note["bar"] = index > 0
        else:
            note["bar"] = False
        if note["stress"] >= 2:
            want = 3.0 if index == len(notes) - 1 else 2.0
        elif note["stress"] == 1:
            want = 1.0
        else:
            want = 0.5
        options = [d for d in (3.0, 2.0, 1.0, 0.5) if d <= remaining + 1e-9]
        beats = next((d for d in options if d <= want), options[-1] if options else 0.5)
        note["beats"] = beats
        note["dotted"] = _lieder_is_dotted(beats)
        remaining -= beats
    # Fill the last bar exactly: first grow the last note (a notehead can only
    # express a few durations), then pad whatever remains with rests.
    if notes and remaining > 1e-9:
        last = notes[-1]
        for grown in (3.0, 2.0, 1.5, 1.0):
            if grown > last["beats"] and grown <= last["beats"] + remaining + 1e-9:
                remaining -= grown - last["beats"]
                last["beats"] = grown
                last["dotted"] = _lieder_is_dotted(grown)
                break
        while remaining > 1e-9:
            value = next((v for v, _ in _MUSIC_RESTS if v <= remaining + 1e-9), None)
            if value is None:
                break
            notes.append({
                "text": "", "matched": False, "hyphen": False, "breath": False,
                "stress": 0, "word": last["word"], "beats": value, "dotted": False,
                "bar": False, "rest": True, "pitch": 4,
            })
            remaining -= value


def _lieder_chord_tone(pitch: int) -> int:
    """Nudge a pitch onto the nearest tonic-triad degree (C, E or G).

    In this key (no key signature, so C major) every staff position is a
    diatonic degree, and the triad sits on degrees 0/2/4 of the seven. Any
    pitch is at most one step from one of them, so this never leaps.
    """
    for delta in (0, -1, 1, -2, 2):
        candidate = pitch + delta
        if _LIEDER_PITCH_MIN <= candidate <= _LIEDER_PITCH_MAX and (candidate + 2) % 7 in (0, 2, 4):
            return candidate
    return pitch


def _lieder_contour(seed: int, notes: list[dict]) -> None:
    """Give the line a singable shape, and make it end like a piece of music.

    A weighted random walk, shaped by four rules:

    * **Downbeat gravity** — the first note of each bar is pulled onto a tonic
      triad degree.
    * **Leap resolution** — after a leap of three degrees or more the next move
      is a step in the opposite direction.
    * **Phrase resolution** — a phrase-final syllable settles onto a chord tone.
    * **Cadence** — the final note lands on the tonic, approached by step.

    The matched phrase keeps an upward bias so the sung phrase peaks; the
    range edges pull back toward the middle.
    """
    rng = random.Random(seed)
    pitch = _lieder_chord_tone(4)
    previous_step = 0
    # Trailing rests carry no pitch, and the cadence must land on the last sung
    # syllable rather than on a rest. Mutating these dicts still updates `notes`.
    sung = [n for n in notes if not n.get("rest")]
    total = len(sung)
    for index, note in enumerate(sung):
        if index == 0 or note.get("bar"):
            pitch = _lieder_chord_tone(pitch)
        note["pitch"] = pitch
        if index == total - 1:
            break
        if abs(previous_step) >= 3:
            step = -1 if previous_step > 0 else 1
        elif note["breath"]:
            step = _lieder_chord_tone(pitch) - pitch or rng.choice((-1, 1))
        else:
            step = rng.choice(_LIEDER_MELODY_STEPS)
            if note["matched"] and step < 0 and pitch < 7:
                step = -step
        if pitch >= 8 and step > 0:
            step = -step
        elif pitch <= 0 and step < 0:
            step = -step
        previous_step = step
        pitch = max(_LIEDER_PITCH_MIN, min(_LIEDER_PITCH_MAX, pitch + step))
    if total >= 2:
        tonic = min((-2, 5), key=lambda t: abs(t - sung[-1]["pitch"]))
        sung[-1]["pitch"] = tonic
        approach = sung[-2]["pitch"]
        if abs(approach - tonic) != 1:
            sung[-2]["pitch"] = max(_LIEDER_PITCH_MIN, min(_LIEDER_PITCH_MAX,
                                                           tonic + (1 if approach >= tonic else -1)))


def _lieder_slot(note: dict, min_gap: int, base: float) -> float:
    """Horizontal space one note owns.

    The larger of the syllable's text plus breathing room and a duration
    share. The 0.6 exponent compresses duration spacing as engravers do: a
    half note gets more room than an eighth, nowhere near four times more.
    """
    if note.get("rest"):
        return base * (note["beats"] ** 0.6)
    return max(note["width"] + min_gap * 0.75, base * (note["beats"] ** 0.6))


def _lieder_wrap(notes: list[dict], widths: list[int], min_gap: int, base: float) -> list[list[dict]]:
    """Break the notes into systems, never splitting a word across two staves.

    Keeping words whole avoids the continuation hyphen a split would need at
    the next line head, at the cost of a little justification slack.
    """
    lines: list[list[dict]] = []
    current: list[dict] = []
    current_w = 0.0
    index = 0
    while index < len(notes):
        word = notes[index]["word"]
        group = []
        while index < len(notes) and notes[index]["word"] == word:
            group.append(notes[index])
            index += 1
        group_w = sum(_lieder_slot(n, min_gap, base) for n in group)
        avail = widths[min(len(lines), len(widths) - 1)]
        if current and current_w + group_w > avail:
            lines.append(current)
            current, current_w = [], 0.0
        current.extend(group)
        current_w += group_w
    if current:
        lines.append(current)
    return lines


def _lieder_system_core(size: int, gap: int) -> int:
    """Vertical extent of one system: headroom + staff + lyric descent."""
    return int((_LIEDER_HEADROOM + 4 + _LIEDER_LYRIC_OFFSET) * gap) + size


def _lieder_fit(draw, notes: list[dict], widths: list[int], gap: int) -> tuple:
    """Shrink the lyric font until the syllables fit the page as engraved systems.

    Per size, the notes must wrap into at most ``_LIEDER_MAX_SYSTEMS`` staves
    and those systems (headroom + staff + lyric) must fit the vertical band.

    The size range is deliberately narrow: lyric size tracks staff size, so
    quote length is absorbed by the number of systems instead.
    """
    regular_chain = theme_font_candidates("lieder", "quote_regular")
    bold_chain = theme_font_candidates("lieder", "quote_bold")
    band_height = _LIEDER_BAND[1] - _LIEDER_BAND[0]
    lines: list = []
    size = _LIEDER_FONT_MIN
    regular = load_font(regular_chain, size=size)
    bold = load_font(bold_chain, size=size)
    min_gap = 0
    for size in range(_LIEDER_FONT_MAX, _LIEDER_FONT_MIN - 1, -1):
        regular = load_font(regular_chain, size=size)
        bold = load_font(bold_chain, size=size)
        min_gap = max(7, int(size * 0.38))
        base = min_gap * 2.1
        for note in notes:
            note["width"] = int(draw.textlength(note["text"], font=bold if note["matched"] else regular))
        lines = _lieder_wrap(notes, widths, min_gap, base)
        if len(lines) > _LIEDER_MAX_SYSTEMS:
            continue
        block = len(lines) * _lieder_system_core(size, gap) + (len(lines) - 1) * _LIEDER_SYSTEM_GAP
        if block <= band_height:
            return regular, bold, lines, size, min_gap, base
    if len(lines) > _LIEDER_MAX_SYSTEMS:
        lines = lines[:_LIEDER_MAX_SYSTEMS]
        if lines and lines[-1]:
            tail = lines[-1][-1]
            tail["text"] = tail["text"].rstrip(".,;:!?") + "…"
            tail["hyphen"] = False
            tail["width"] = int(draw.textlength(tail["text"], font=bold if tail["matched"] else regular))
    return regular, bold, lines, size, min_gap, max(7, int(size * 0.38)) * 2.1


def _lieder_pitch_y(staff_top: float, pitch: int, gap: int) -> float:
    """Staff position → y. Position 0 is the bottom line, 8 the top line."""
    return staff_top + 4 * gap - pitch * (gap / 2.0)


def _lieder_draw_glyph(draw, ch: str, font, cx: float, cy: float, fill) -> None:
    """Draw a music glyph with its ink bbox centred on ``(cx, cy)``."""
    x0, y0, x1, y1 = font.getbbox(ch, anchor="ls")
    draw.text((cx - (x0 + x1) / 2.0, cy - (y0 + y1) / 2.0), ch, font=font, fill=fill, anchor="ls")



def _lieder_paint_header(draw, quote_row: dict, time_str: str) -> None:
    """Title (centred), composer credit and tempo mark — the head of a song.

    Title centred at the top, composer flush right below it, tempo mark flush
    left at the same height.
    """
    BLACK = SPECTRA6["black"]
    width = 800  # header is laid out against the canonical canvas; see render_lieder_frame
    _, minute = _lieder_clock(time_str)
    title = (quote_row.get("title") or fallback_title(quote_row) or "").strip()
    author = (quote_row.get("author") or "").strip()

    if title:
        font = load_font(theme_font_candidates("lieder", "card_quote_bold"), size=24)
        text = title if len(title) <= 46 else title[:45].rstrip(" ,;:") + "…"
        draw.text((width / 2, 44), text, font=font, fill=BLACK, anchor="ms")

    italic = load_font(theme_font_candidates("lieder", "ornament"), size=16)
    if author:
        name = author if len(author) <= 34 else author[:33].rstrip(" ,;:") + "…"
        draw.text((_LIEDER_MARGIN_R, 82), name, font=italic, fill=BLACK, anchor="rs")

    # Tempo: Italian word + a real quarter-note glyph + the metronome figure.
    word = _LIEDER_TEMPO_WORDS[min(len(_LIEDER_TEMPO_WORDS) - 1, minute // 12)]
    x = _LIEDER_MARGIN_L
    draw.text((x, 82), word, font=italic, fill=BLACK, anchor="ls")
    x += draw.textlength(word, font=italic) + 12
    note_font = load_font([NOTOMUSIC_REGULAR], size=24)
    _lieder_draw_glyph(draw, _MUSIC_QUARTER_NOTE, note_font, x, 76, BLACK)
    draw.text((x + 10, 82), f"= {60 + minute}", font=italic, fill=BLACK, anchor="ls")


def _lieder_paint_clef_and_meter(draw, x: float, staff_top: float, gap: int, numerator: int, first: bool) -> float:
    """Draw the G clef (and, on the first system, the time signature).

    Returns the x at which the notes may begin. The clef's baseline goes on
    the bottom staff line (Noto Music's metric), so no hand-tuned offset.
    """
    BLACK = SPECTRA6["black"]
    staff_bottom = staff_top + 4 * gap
    clef_font = load_font([NOTOMUSIC_REGULAR], size=gap * 4)
    cx0, _, cx1, _ = clef_font.getbbox(_MUSIC_G_CLEF, anchor="ls")
    draw.text((x, staff_bottom), _MUSIC_G_CLEF, font=clef_font, fill=BLACK, anchor="ls")
    x += (cx1 - cx0) + gap

    if first:
        # Numerator centred between the top and middle lines, denominator
        # between the middle and bottom lines — the standard placement.
        meter_font = load_font(theme_font_candidates("lieder", "card_quote_bold"), size=int(gap * 3.0))
        widest = max(draw.textlength(str(numerator), font=meter_font), draw.textlength("4", font=meter_font))
        for text, cy in ((str(numerator), staff_top + gap), ("4", staff_top + 3 * gap)):
            draw.text((x + widest / 2.0, cy), text, font=meter_font, fill=BLACK, anchor="mm")
        x += widest + gap * 1.6
    return x


def _lieder_beam_groups(line: list[dict]) -> list[list[int]]:
    """Index runs of consecutive eighths that should share a beam.

    Eighths are beamed across syllables (modern vocal style; a row of single
    flags reads as noise at a 7 px staff gap). Runs break at a barline and are
    capped at four so they still group by beat.
    """
    groups: list[list[int]] = []
    run: list[int] = []
    for index, note in enumerate(line):
        is_eighth = abs(note["beats"] - 0.5) < 1e-9 and not note.get("rest")
        if run and (not is_eighth or (index > 0 and note.get("bar")) or len(run) >= 4):
            if len(run) >= 2:
                groups.append(run)
            run = []
        if is_eighth:
            run.append(index)
    if len(run) >= 2:
        groups.append(run)
    return groups


def _lieder_paint_head(draw, cx: float, note_y: float, gap: int, note: dict, fill) -> float:
    """Notehead, ledger line and augmentation dot. Returns the notehead width.

    Void notehead for a half or dotted half, filled otherwise.
    """
    note_font = load_font([NOTOMUSIC_REGULAR], size=gap * 4)
    glyph = _MUSIC_NOTEHEAD_VOID if note["beats"] >= 2.0 else _MUSIC_NOTEHEAD
    nx0, _, nx1, _ = note_font.getbbox(glyph, anchor="ls")
    head_w = max(4.0, float(nx1 - nx0))
    _lieder_draw_glyph(draw, glyph, note_font, cx, note_y, fill)

    if note["pitch"] <= _LIEDER_PITCH_MIN or note["pitch"] >= _LIEDER_PITCH_MAX:
        half = head_w / 2.0 + 3
        draw.line((cx - half, note_y, cx + half, note_y), fill=fill, width=1)

    if note["dotted"]:
        # The dot always sits in a space, so a note on a line pushes it up one.
        dot_y = note_y if note["pitch"] % 2 else note_y - gap / 2.0
        dot_x = cx + head_w / 2.0 + 3
        draw.ellipse((dot_x - 1.5, dot_y - 1.5, dot_x + 1.5, dot_y + 1.5), fill=fill)
    return head_w


def _lieder_paint_stem(draw, cx: float, note_y: float, gap: int, head_w: float,
                       down: bool, tip_y: float, flag: bool, fill) -> None:
    """Stem from the notehead to ``tip_y``, with a flag when it stands alone.

    Stems attach left of the head going down, right going up. A flag always
    hangs to the *right* of the stem, whatever the stem direction.
    """
    sx = cx - head_w / 2.0 + 1 if down else cx + head_w / 2.0 - 1
    draw.line((sx, note_y, sx, tip_y), fill=fill, width=1)
    if not flag:
        return
    direction = -1.0 if down else 1.0
    draw.polygon(
        [(sx, tip_y),
         (sx + gap * 0.85, tip_y + direction * gap * 0.55),
         (sx + gap * 0.75, tip_y + direction * gap * 1.45),
         (sx + gap * 0.15, tip_y + direction * gap * 0.8)],
        fill=fill,
    )


def _lieder_paint_rest(draw, cx: float, staff_top: float, gap: int, beats: float, fill) -> None:
    """Draw the rest glyph for ``beats``, at its conventional staff position.

    A whole rest hangs *below* the fourth line, a half rest sits *on* the
    middle line, and quarter / eighth rests centre on the middle line.
    """
    glyph = next((g for value, g in _MUSIC_RESTS if abs(value - beats) < 1e-9), None)
    if glyph is None:
        return
    font = load_font([NOTOMUSIC_REGULAR], size=gap * 4)
    x0, _, x1, y1 = font.getbbox(glyph, anchor="ls")
    if beats >= 2.0:
        # Ink bottom rests on the fourth line (whole) or the middle line (half).
        line = 6 if beats >= 4.0 else 4
        pen_y = _lieder_pitch_y(staff_top, line, gap) - y1
        draw.text((cx - (x0 + x1) / 2.0, pen_y), glyph, font=font, fill=fill, anchor="ls")
    else:
        _lieder_draw_glyph(draw, glyph, font, cx, _lieder_pitch_y(staff_top, 4, gap), fill)


def _lieder_paint_breath(draw, x: float, staff_top: float, gap: int, fill) -> None:
    """Breath mark: the comma above the staff that tells a singer to breathe."""
    top = staff_top - gap * 1.3
    draw.line((x, top, x - gap * 0.35, top + gap * 0.75), fill=fill, width=1)
    draw.line((x, top, x + gap * 0.2, top + gap * 0.3), fill=fill, width=1)


def _lieder_paint_slur(draw, xs: list[float], ys: list[float], gap: int) -> None:
    """Phrase slur arcing over the matched-phrase noteheads.

    A single-syllable phrase gets none. The arc box is validated first —
    ``draw.arc`` raises on an inverted box, which a thumbnail can produce.
    """
    if len(xs) < 2:
        return
    x0, x1 = min(xs), max(xs)
    if x1 - x0 < 4:
        return
    rise = max(4, int(gap * 0.9))
    top = min(ys) - gap * 2.2
    box = (x0, top - rise, x1, top + rise)
    if box[2] <= box[0] or box[3] <= box[1]:
        return
    draw.arc(box, start=180, end=360, fill=SPECTRA6["red"], width=2)


def _lieder_paint_system(draw, ctx: dict, index: int, line: list[dict]) -> None:
    """Engrave one staff: lines, clef/meter, barlines, notes, lyrics, slur.

    Geometry is resolved for the whole system first, because beaming needs to
    know where every stem in a group lands before any of them can be drawn.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    gap = ctx["gap"]
    staff_top = ctx["staff_tops"][index]
    staff_bottom = staff_top + 4 * gap
    last_system = index == len(ctx["staff_tops"]) - 1

    for i in range(5):
        y = staff_top + i * gap
        draw.line((_LIEDER_MARGIN_L, y, _LIEDER_MARGIN_R, y), fill=BLACK, width=1)

    x = _lieder_paint_clef_and_meter(draw, _LIEDER_MARGIN_L + 5, staff_top, gap, ctx["numerator"], index == 0)

    # Justify: hand the leftover width back to the notes in proportion to the
    # space each already claims, so a held note keeps its extra room.
    slots = [_lieder_slot(n, ctx["min_gap"], ctx["base"]) for n in line]
    avail = _LIEDER_MARGIN_R - x - gap * 2
    natural = sum(slots)
    if natural > 0 and avail > natural:
        stretch = min(avail / natural, 2.4 if last_system else 6.0)
        slots = [s * stretch for s in slots]

    # Pass 1: where every note sits.
    xs: list[float] = []
    ys: list[float] = []
    cursor = x
    for note, slot in zip(line, slots):
        xs.append(cursor + slot / 2.0)
        ys.append(_lieder_pitch_y(staff_top, note["pitch"], gap))
        cursor += slot

    # Pass 2: beam groups. A whole group shares one stem direction (majority
    # side of the middle line) and one horizontal beam clear of every head in it.
    stem_h = _LIEDER_STEM_LEN * gap
    beamed: dict[int, tuple[bool, float]] = {}
    beams: list[tuple[float, float, float, bool]] = []
    for run in _lieder_beam_groups(line):
        down = sum(1 for i in run if line[i]["pitch"] >= 4) * 2 >= len(run)
        beam_y = (max(ys[i] for i in run) + stem_h) if down else (min(ys[i] for i in run) - stem_h)
        for i in run:
            beamed[i] = (down, beam_y)
        beams.append((xs[run[0]], xs[run[-1]], beam_y, down))

    lyric_baseline = staff_bottom + _LIEDER_LYRIC_OFFSET * gap
    matched_xs: list[float] = []
    matched_ys: list[float] = []
    cursor = x
    for position, (note, slot) in enumerate(zip(line, slots)):
        cx, note_y = xs[position], ys[position]

        if note.get("bar"):
            bar_x = cursor - ctx["min_gap"] * 0.35 if position > 0 else x - gap * 0.8
            if _LIEDER_MARGIN_L < bar_x < _LIEDER_MARGIN_R:
                draw.line((bar_x, staff_top, bar_x, staff_bottom), fill=BLACK, width=1)

        ink = RED if note["matched"] else BLACK
        if note.get("rest"):
            _lieder_paint_rest(draw, cx, staff_top, gap, note["beats"], BLACK)
            cursor += slot
            continue
        head_w = _lieder_paint_head(draw, cx, note_y, gap, note, ink)
        if position in beamed:
            down, beam_y = beamed[position]
            _lieder_paint_stem(draw, cx, note_y, gap, head_w, down, beam_y, False, ink)
        else:
            down = note["pitch"] >= 4
            tip = note_y + stem_h if down else note_y - stem_h
            _lieder_paint_stem(draw, cx, note_y, gap, head_w, down,
                               tip, abs(note["beats"] - 0.5) < 1e-9, ink)
        if note["matched"]:
            matched_xs.append(cx)
            matched_ys.append(note_y)

        font = ctx["bold"] if note["matched"] else ctx["regular"]
        draw.text((cx, lyric_baseline), note["text"], font=font, fill=ink, anchor="ms")

        # Lyric hyphen, centred in the gap to the next syllable of the same word.
        if note["hyphen"] and position + 1 < len(line):
            left = cx + note["width"] / 2.0
            right = xs[position + 1] - line[position + 1]["width"] / 2.0
            if right - left > 4:
                mid = (left + right) / 2.0
                hy = lyric_baseline - ctx["size"] * 0.28
                draw.line((mid - 2, hy, mid + 2, hy), fill=ink, width=1)

        if note["breath"]:
            _lieder_paint_breath(draw, cursor + slot, staff_top, gap, BLACK)
        cursor += slot

    # Beams last, so they sit over the stems they cap.
    thickness = max(2, int(gap * 0.5))
    for bx0, bx1, by, down in beams:
        top = by - thickness if down else by
        draw.rectangle((bx0 - 1, top, bx1 + 1, top + thickness), fill=BLACK)

    _lieder_paint_slur(draw, matched_xs, matched_ys, gap)

    if last_system:
        draw.line((_LIEDER_MARGIN_R - 6, staff_top, _LIEDER_MARGIN_R - 6, staff_bottom), fill=BLACK, width=1)
        draw.rectangle((_LIEDER_MARGIN_R - 3, staff_top, _LIEDER_MARGIN_R, staff_bottom), fill=BLACK)
    if index == 1:
        italic = load_font(theme_font_candidates("lieder", "ornament"), size=14)
        draw.text((_LIEDER_MARGIN_L + 4, staff_top - gap * 1.4), ctx["expression"], font=italic, fill=BLACK, anchor="ls")


def _lieder_paint_plate_line(draw, quote_row: dict, width: int, height: int) -> None:
    """Engraver's plate number, centred at the foot — real scores carry one."""
    source_id = str(quote_row.get("source_id") or "").strip()
    text = f"Idle Hours Edition · Pl. {source_id}" if source_id else "Idle Hours Edition"
    font = load_font(theme_font_candidates("lieder", "ornament"), size=13)
    draw.text((width / 2, height - 22), text, font=font, fill=SPECTRA6["black"], anchor="ms")


def render_lieder_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Engraved art-song manuscript (see the module section comment above).

    Five passes, in dependency order: split the text into sung syllables, give
    them durations and barlines, give them pitches (which needs the barlines,
    since downbeats pull toward the chord), fit and wrap them, then engrave.

    Laid out against the canonical 800×480; smaller canvases (``/api/preview``
    thumbnails) crop rather than reflow. Every primitive is an ``ImageDraw``
    call, which clips silently, so no per-call bounds checks are needed.
    """
    image = Image.new("RGB", (width, height), color=SPECTRA6["white"])
    _astrarium_paint_cream_wash(image)
    draw = ImageDraw.Draw(image)

    hour, _ = _lieder_clock(time_str)
    seed = _row_digest(quote_row)
    notes = _lieder_notes(quote_row)
    if not notes:
        notes = [{"text": "—", "matched": False, "hyphen": False, "breath": False, "stress": 2, "word": 0}]

    gap = _LIEDER_STAVE_GAP
    clef_font = load_font([NOTOMUSIC_REGULAR], size=gap * 4)
    cx0, _, cx1, _ = clef_font.getbbox(_MUSIC_G_CLEF, anchor="ls")
    clef_w = (cx1 - cx0) + gap + 5
    meter_w = gap * 4.6  # the first system also carries the time signature
    span = _LIEDER_MARGIN_R - _LIEDER_MARGIN_L - gap * 2
    widths = [int(span - clef_w - meter_w), int(span - clef_w)]

    _lieder_rhythm(notes, hour)
    _lieder_contour(seed, notes)
    regular, bold, lines, size, min_gap, base = _lieder_fit(draw, notes, widths, gap)

    core = _lieder_system_core(size, gap)
    band_top, band_bottom = _LIEDER_BAND
    block = len(lines) * core + (len(lines) - 1) * _LIEDER_SYSTEM_GAP
    # Slack goes 1/3 above, 2/3 below: engraved music hangs from the top of its
    # type area, and a centred one-system song floats stranded mid-page.
    top = band_top + max(0, (band_bottom - band_top - block) // 3)
    staff_tops = [top + int(_LIEDER_HEADROOM * gap) + i * (core + _LIEDER_SYSTEM_GAP) for i in range(len(lines))]

    ctx = {
        "gap": gap, "regular": regular, "bold": bold, "min_gap": min_gap, "base": base,
        "size": size, "numerator": hour, "staff_tops": staff_tops,
        "expression": _LIEDER_EXPRESSION[seed % len(_LIEDER_EXPRESSION)],
    }
    _lieder_paint_header(draw, quote_row, time_str)
    for index, line in enumerate(lines):
        _lieder_paint_system(draw, ctx, index, line)
    _lieder_paint_plate_line(draw, quote_row, width, height)
    return snap_image_to_palette(image, SPECTRA6_PALETTE)


# ─── izakaya (neon alley at night) ───────────────────────────────────────────
#
# A Kabukichō / Golden Gai back alley after rain: vertical shop signs glowing
# down both margins, paper lanterns above, the quote as neon tube lettering,
# and wet asphalt throwing every sign back as a vertical smear. Every glow goes
# through ``paint_neon_mask`` (one ink at a falling density).
#
# Ink use:
#   black       the alley itself.
#   blue        the night haze above the roofline, and the body text's bloom.
#   white       the neon tube cores (the glass is the brightest thing in a sign).
#   yellow      the matched phrase's tube core.
#   red         the matched phrase's bloom, the paper lanterns, and two signs.
#   green       two more sign columns.
#
# The hour rides the main lantern as a kanji numeral (一 … 十二), so
# ``time_str`` is used; the matched phrase still carries the readable time.
# Sign words are ordinary alley signage set in Yuji Boku. Deliberately
# kanji-only: katakana would want ー rotated in vertical setting.

_IZAKAYA_SIGN_W = 58
_IZAKAYA_SIGN_COLUMNS = (10, 732)     # left / right sign-board x origins
_IZAKAYA_SIGN_TOP = 34
_IZAKAYA_SIGN_H = 92
_IZAKAYA_SIGN_GAP = 18
_IZAKAYA_STREET_Y = 360               # wet asphalt begins here (below a kerb gap);
                                      # deep so reflections read as smears, not bars
_IZAKAYA_QUOTE_RECT = (108, 146, 692, 316)
_IZAKAYA_HAZE_BOTTOM = 210            # night-haze wash fades out by this row
# (word, glow ink). Six boards, three per side, cycling the chroma inks.
_IZAKAYA_SIGNS = (
    ("居酒屋", "red"),
    ("焼鳥", "green"),
    ("酒", "yellow"),
    ("横丁", "blue"),
    ("喫茶", "green"),
    ("営業中", "red"),
)
_IZAKAYA_HOUR_KANJI = {
    1: "一", 2: "二", 3: "三", 4: "四", 5: "五", 6: "六",
    7: "七", 8: "八", 9: "九", 10: "十", 11: "十一", 12: "十二",
}
_IZAKAYA_LANTERNS = ((168, 74, 26, 34), (632, 80, 24, 31))  # (cx, cy, rx, ry) side pair
_IZAKAYA_MAIN_LANTERN = (400, 84, 33, 45)


def _izakaya_ground() -> frozenset:
    """Pixels a bloom is allowed to overwrite: the night ground and its haze.

    Passed as ``paint_neon_mask(ground=...)`` so a later glow cannot eat the
    cores, frames and ribs an earlier pass painted.
    """
    return frozenset({SPECTRA6["black"], SPECTRA6["blue"]})


def _izakaya_paint_night(image: Image.Image) -> None:
    """Black alley under a blue night haze that thins toward the roofline.

    A gradient Bayer wash, densest at the top and gone by
    ``_IZAKAYA_HAZE_BOTTOM``. Kept faint (peak ~2.2/16 ≈ 14%) so the sky never
    outshines the neon. The threshold stays a float: rounding it to an int
    bands the ramp into visible steps.
    """
    px = image.load()
    width, height = image.size
    span = max(1, _IZAKAYA_HAZE_BOTTOM)
    for y in range(min(height, _IZAKAYA_HAZE_BOTTOM)):
        threshold = 2.2 * (1.0 - y / span)
        if threshold <= 0:
            continue
        row = BAYER_4x4[y % 4]
        for x in range(width):
            if row[x % 4] < threshold:
                px[x, y] = SPECTRA6["blue"]


def _izakaya_sign_boxes() -> list[tuple[int, int, int, int, str, str]]:
    """``(x0, y0, x1, y1, word, ink)`` for all six boards, left column first."""
    boxes = []
    for index, (word, ink) in enumerate(_IZAKAYA_SIGNS):
        column = _IZAKAYA_SIGN_COLUMNS[index // 3]
        slot = index % 3
        y0 = _IZAKAYA_SIGN_TOP + slot * (_IZAKAYA_SIGN_H + _IZAKAYA_SIGN_GAP)
        boxes.append((column, y0, column + _IZAKAYA_SIGN_W, y0 + _IZAKAYA_SIGN_H, word, ink))
    return boxes


def _izakaya_paint_signs(image: Image.Image, draw: ImageDraw.ImageDraw, boxes) -> None:
    """Vertical shop boards: a glowing frame with kanji set down the middle.

    One mask per board (frame plus characters) so outline and lettering share
    one bloom; blooming them separately double-exposes where the halos meet.
    """
    ground = _izakaya_ground()
    for x0, y0, x1, y1, word, ink in boxes:
        glow = SPECTRA6[ink]
        mask = Image.new("L", image.size, 0)
        mdraw = ImageDraw.Draw(mask)
        mdraw.rectangle((x0, y0, x1, y1), outline=255, width=2)
        size = 30 if len(word) <= 2 else 24
        font = load_font([YUJI_BOKU_REGULAR, *ORNAMENT_FONT_CANDIDATES], size=size)
        step = size + 4
        cy = (y0 + y1) // 2 - (len(word) - 1) * step // 2
        for i, char in enumerate(word):
            mdraw.text(((x0 + x1) // 2, cy + i * step), char, font=font, fill=255, anchor="mm")
        # The board interior is the shop's own light box: the tube core paints
        # the frame and glyphs white, the gas colour blooms outward from both.
        paint_neon_mask(image, mask, SPECTRA6["white"], glow, radius=5, gamma=2.0, cap=0.62, ground=ground)
        del mdraw
    del draw


def _izakaya_paint_lantern(
    image: Image.Image,
    draw: ImageDraw.ImageDraw,
    cx: int,
    cy: int,
    rx: int,
    ry: int,
    text: str | None = None,
) -> None:
    """A red paper lantern (提灯) on a cord, optionally carrying a character.

    Three passes: the silhouette blooms (``core=None``), then the red body with
    black cap, base and ribs (horizontal chords clipped to the ellipse), then
    the character.
    """
    BLACK = SPECTRA6["black"]
    RED = SPECTRA6["red"]
    WHITE = SPECTRA6["white"]

    draw.line((cx, 0, cx, cy - ry - 5), fill=WHITE, width=1)

    silhouette = Image.new("L", image.size, 0)
    ImageDraw.Draw(silhouette).ellipse((cx - rx, cy - ry, cx + rx, cy + ry), fill=255)
    paint_neon_mask(image, silhouette, None, RED, radius=6, gamma=2.0, cap=0.6, ground=_izakaya_ground())

    draw.ellipse((cx - rx, cy - ry, cx + rx, cy + ry), fill=RED)
    for ry_off in range(-ry + 4, ry - 2, 6):
        half = int(rx * math.sqrt(max(0.0, 1.0 - (ry_off / float(ry)) ** 2)))
        if half > 1:
            draw.line((cx - half, cy + ry_off, cx + half, cy + ry_off), fill=BLACK, width=1)
    cap_w = int(rx * 0.55)
    draw.rectangle((cx - cap_w, cy - ry - 4, cx + cap_w, cy - ry + 1), fill=BLACK)
    draw.rectangle((cx - cap_w, cy + ry - 1, cx + cap_w, cy + ry + 4), fill=BLACK)

    if text:
        font = load_font([YUJI_BOKU_REGULAR, *ORNAMENT_FONT_CANDIDATES], size=max(12, int(ry * 0.62)))
        step = int(ry * 0.72)
        top = cy - (len(text) - 1) * step // 2
        for i, char in enumerate(text):
            draw.text((cx, top + i * step), char, font=font, fill=BLACK, anchor="mm")


def _izakaya_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> int:
    """The quote as bent neon tube. Returns the block's bottom y for the credits.

    Two masks from ``wrap_quote_into_masks``: cool white/blue for the prose,
    hot yellow/red for the matched phrase. The hot pass runs last and may
    overwrite the cool halo, so the phrase reads as nearer.
    """
    cool, hot, bottom = wrap_quote_into_masks(
        draw, image.size, quote_row, _IZAKAYA_QUOTE_RECT,
        theme="izakaya", line_height_mult=1.42,
    )
    ground = _izakaya_ground()
    paint_neon_mask(image, cool, SPECTRA6["white"], SPECTRA6["blue"], radius=6, gamma=2.0, cap=0.68, ground=ground)
    paint_neon_mask(image, hot, SPECTRA6["yellow"], SPECTRA6["red"], radius=6, gamma=1.9, cap=0.72,
                    ground=ground | {SPECTRA6["blue"]})
    return bottom


def _izakaya_paint_credits(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict, top: int) -> None:
    """author · title beneath the quote, unlit — a printed card, not a sign."""
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or fallback_title(quote_row) or "").strip()
    parts = [p for p in (author, title) if p]
    if not parts:
        return
    text = "  ·  ".join(parts)
    font = load_font(theme_font_candidates("izakaya", "quote_regular"), size=14)
    width = image.size[0]
    # Floor the budget and guard on length, not emptiness: ``text[:-2] + "…"``
    # is a fixed point at the ellipsis, which hangs a thumbnail render.
    max_w = max(40, width - 240)
    while len(text) > 1 and draw.textlength(text, font=font) > max_w:
        text = text[:-2].rstrip(" ·") + "…"
    y = min(max(top + 12, _IZAKAYA_QUOTE_RECT[3] - 4), _IZAKAYA_STREET_Y - 20)
    draw.text((width // 2, y), text, font=font, fill=SPECTRA6["white"], anchor="ma")


def _izakaya_paint_street(image: Image.Image, boxes) -> None:
    """Wet asphalt: each sign column smeared back as a rippled vertical streak.

    Each reflection inherits its board's ink and x-range, fades with depth,
    wobbles horizontally on a sine, and thins where a second sine crests. Both
    sines are phased **per column**: a shared phase breaks every column on the
    same rows, painting horizontal bands. Lanterns reflect at a lower weight.
    """
    px = image.load()
    width, height = image.size
    street = _IZAKAYA_STREET_Y
    if street >= height:
        return
    depth = max(1, height - street)

    columns = [(x0, x1, SPECTRA6[ink], 1.0) for x0, _, x1, _, _, ink in boxes]
    columns += [(cx - rx, cx + rx, SPECTRA6["red"], 0.45) for cx, _, rx, _ in _IZAKAYA_LANTERNS]
    columns.append((_IZAKAYA_MAIN_LANTERN[0] - _IZAKAYA_MAIN_LANTERN[2],
                    _IZAKAYA_MAIN_LANTERN[0] + _IZAKAYA_MAIN_LANTERN[2], SPECTRA6["red"], 0.55))

    # Faint blue sheen first, so the coloured streaks paint over it.
    for y in range(street, height):
        fade = max(0.0, (1.0 - (y - street) / depth) ** 1.6)
        sheen = 1.6 * fade
        if sheen <= 0:
            continue
        row = BAYER_4x4[y % 4]
        for x in range(width):
            if row[x % 4] < sheen and px[x, y] == SPECTRA6["black"]:
                px[x, y] = SPECTRA6["blue"]

    for index, (x0, x1, ink, weight) in enumerate(columns):
        phase = index * 1.7
        for y in range(street, height):
            fade = max(0.0, (1.0 - (y - street) / depth) ** 0.8)
            # Ripple by modulating density, not skipping rows — skipped rows
            # read as stacked horizontal bricks.
            ripple = 0.55 + 0.45 * math.sin(y * 0.42 + phase)
            threshold = 5.5 * fade * weight * ripple
            if threshold <= 0:
                continue
            # Distortion grows with depth: the near water is the most broken up.
            swing = 1.0 + 2.2 * ((y - street) / depth)
            wobble = int(round(swing * (4.0 * math.sin(y * 0.23 + phase) + 2.0 * math.sin(y * 0.61 + phase))))
            row = BAYER_4x4[y % 4]
            for x in range(max(0, x0 + wobble), min(width, x1 + wobble)):
                if row[x % 4] < threshold:
                    px[x, y] = ink


def render_izakaya_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Neon alley at night (see the module section comment above).

    Laid out against the canonical 800×480; smaller canvases (``/api/preview``
    thumbnails) crop rather than reflow. Raw pixel writes are bounds-clipped.
    """
    image = Image.new("RGB", (width, height), color=SPECTRA6["black"])
    _izakaya_paint_night(image)
    draw = ImageDraw.Draw(image)

    boxes = _izakaya_sign_boxes()
    _izakaya_paint_signs(image, draw, boxes)

    for cx, cy, rx, ry in _IZAKAYA_LANTERNS:
        _izakaya_paint_lantern(image, draw, cx, cy, rx, ry)
    mcx, mcy, mrx, mry = _IZAKAYA_MAIN_LANTERN
    _izakaya_paint_lantern(image, draw, mcx, mcy, mrx, mry, text=_IZAKAYA_HOUR_KANJI[_clock_hour12(time_str)])

    block_bottom = _izakaya_paint_quote(image, draw, quote_row)
    _izakaya_paint_credits(image, draw, quote_row, block_bottom)
    _izakaya_paint_street(image, boxes)
    return snap_image_to_palette(image, SPECTRA6_PALETTE)


# ---------------------------------------------------------------------------
# pride — the Progress Pride flag, flying.
#
# Eleven bands, all on-palette: native red / yellow / green / blue / white /
# black, plus documented two-ink recipes for orange (R+Y 5/8:3/8), violet
# (R+B 1:1), pink (R+W), light blue (B+W 1:1) and brown (R+G 1:1).
#
# The cloth is *lit*: a low-density white overlay on faces turned toward the
# light and a black one on faces turned away, riding the wave that displaces
# the stripes. Two constraints:
#
#   1. **Displacement and shading are 90 degrees apart.** The stripes displace
#      by the height field ``h``; the light sees the tilt ``dh/dx``. Shading the
#      crest instead of the slope reads as a corrugated roof, which is why
#      ``_pride_wave`` returns both from one pass.
#   2. **One sine reads as corrugation.** Two incommensurate frequencies
#      billow; the phases drift with ``y`` so the folds lean.
#
# The stripe lookup is clamped, so the frame reads as a crop of a larger flag.
# The chevron is resolved against the same wave-displaced row, so it rides the
# cloth rather than sitting on it like a decal.
#
# The quote sits in a white cartouche with a black drop-shadow ledge, in the
# rainbow field RIGHT of the chevron's point (a centred card would swallow the
# arrow). Body type is Jost; the matched phrase is in the flag's own violet.
# HH:MM is never shown.
#
# Deliberately *not* done: nothing encodes the hour in the bands. Their count
# and order carry meaning that is not a designer's to spend on a clock gimmick.
# ---------------------------------------------------------------------------
_PRIDE_STRIPES = 6
# (dark ink, light ink, light density) per stripe, top to bottom: red, orange,
# yellow, green, blue, violet. A ``None`` light ink means the stripe is a native
# Spectra 6 ink and paints solid.
_PRIDE_STRIPE_INKS: tuple[tuple[str, str | None, float], ...] = (
    ("red", None, 0.0),
    ("red", "yellow", 0.375),   # tangerine — the documented R+Y 5/8:3/8 recipe
    ("yellow", None, 0.0),
    ("green", None, 0.0),
    ("blue", None, 0.0),
    ("red", "blue", 0.5),       # violet — the documented R+B 1:1 recipe
)
# The Progress chevron, in the same (dark, light, light density) form, ordered
# from the innermost band outward. The order was measured off a reference image
# (published descriptions disagree); don't reorder it from memory.
#
# Brown is the R+G 1:1 sepia, which reads as true dark brown on the panel's
# muted inks (olive only in an RGB preview). It is not darkened with black:
# it sits against the black band and must stay distinguishable from it.
_PRIDE_CHEVRON_INKS: tuple[tuple[str, str | None, float], ...] = (
    ("white", None, 0.0),
    ("white", "red", 0.375),    # pink — R+W, white-dominant for the pale rose
    ("white", "blue", 0.5),     # light blue — the documented B+W 1:1 sky blue
    ("red", "green", 0.5),      # brown — the documented R+G 1:1 sepia
    ("black", None, 0.0),
)
# Depth of each chevron band's vertex as a fraction of canvas width, measured
# off the reference flag (band boundaries at 0.148 / 0.223 / 0.303 / 0.383 /
# 0.465 of the flag's width). The innermost white is a filled arrow rather than
# a band, which is why its depth is not simply one fifth.
_PRIDE_CHEVRON_DEPTHS: tuple[float, ...] = (0.148, 0.223, 0.303, 0.383, 0.465)
# The size of the flag those depths were measured from. The depths are
# fractions of WIDTH while an arm's travel is vertical, so the vertical term is
# scaled by the aspect ratio (``_pride_arm_slope``); a literal 45-degree arm at
# 800x480 would put the top-left corner in light blue instead of brown.
_PRIDE_REFERENCE_SIZE = (1008, 658)
# Clear space between the chevron's point and the quote card.
_PRIDE_FIELD_GAP = 18
# Wave terms as (amplitude px, angular frequency per px, y-lean, phase). Two
# incommensurate frequencies so the cloth billows instead of corrugating.
_PRIDE_WAVE: tuple[tuple[float, float, float, float], ...] = (
    (17.0, 0.0182, 0.0016, 0.7),
    (8.0, 0.0331, -0.0027, 2.4),
)
# Peak overlay densities for the lit and shadowed faces: well below 0.5 so the
# overlay models light on a colour rather than mixing a new one, but above ~0.2,
# below which the folds vanish at viewing distance.
_PRIDE_LIGHT_PEAK = 0.22
_PRIDE_SHADE_PEAK = 0.20
# The lighting is a *partition* of the Bayer tile, not an overlay painted over
# the stripe stipple. Any two reads of one Bayer tile are perfectly correlated,
# so pick-ink-then-overwrite skews the stripe's mix on each face of a fold (a
# hue shift masquerading as shading). Instead one read of ``BAYER_8x8`` ranks
# each pixel: the lowest ``round(density * 64)`` cells take the lighting ink and
# the rest split between the stripe's inks in its own ratio. 8x8 rather than 4x4
# because 17 levels band the folds into hard contours. A solid stripe is the
# degenerate case. ``TestPrideStripeInkRatios`` fences this.
# The card is sized to its contents, bounded by ``_PRIDE_TEXT_MAX`` and
# ``_PRIDE_CARD_MIN`` (a card much smaller than its own corner radius stops
# reading as a card). It lives right of the chevron's point, which is why the
# text maximum is narrow; the fit loop absorbs that by wrapping and shrinking.
_PRIDE_TEXT_MAX = (322, 316)
_PRIDE_CARD_MIN = (220, 120)
_PRIDE_PAD_X = 30
_PRIDE_PAD_TOP = 24
_PRIDE_PAD_BOTTOM = 20
_PRIDE_CREDIT_GAP = 16
_PRIDE_CARTOUCHE_RADIUS = 10
_PRIDE_SHADOW_OFFSET = 4
# Smallest byline the panel renders as readable text rather than a smudge.
_PRIDE_CREDIT_MIN_SIZE = 7


def _pride_wave(x: float, y: float) -> tuple[float, float]:
    """Return ``(displacement_px, tilt)`` for the cloth at ``(x, y)``.

    ``displacement`` shifts the stripe boundaries; ``tilt`` is the derivative of
    the same height field and drives the lighting, so light lands on the slopes
    of each fold, not its crest.
    """
    displacement = 0.0
    tilt = 0.0
    for amp, freq, lean, phase in _PRIDE_WAVE:
        angle = freq * x + lean * y + phase
        displacement += amp * math.sin(angle)
        tilt += amp * freq * math.cos(angle)
    return displacement, tilt


def _pride_metrics(width: int, height: int) -> dict:
    """Card geometry and type sizes for this canvas.

    The constants are native-panel (800x480) values scaled by the smaller axis
    ratio, capped at 1, so the native render is unaffected and thumbnails get a
    proportionally smaller card and type.
    """
    scale = min(1.0, width / 800.0, height / 480.0)

    def down(value: float, floor: int) -> int:
        return max(floor, round(value * scale))

    pad_x, pad_top, pad_bottom = down(_PRIDE_PAD_X, 4), down(_PRIDE_PAD_TOP, 3), down(_PRIDE_PAD_BOTTOM, 3)
    shadow = down(_PRIDE_SHADOW_OFFSET, 1)
    margin = shadow + down(4, 1)
    max_card_w = max(8, width - 2 * margin)
    max_card_h = max(8, height - 2 * margin)
    # Prefer the clear rainbow field right of the chevron; fall back to the full
    # canvas when the field is too narrow to hold a card at all.
    field_left = _pride_chevron_tip(width) + down(_PRIDE_FIELD_GAP, 2)
    card_min_w = min(down(_PRIDE_CARD_MIN[0], 40), max_card_w)
    field_w = width - margin - field_left
    if field_w >= card_min_w:
        max_card_w = min(max_card_w, field_w)
    return {
        "scale": scale,
        "pad_x": pad_x, "pad_top": pad_top, "pad_bottom": pad_bottom,
        "gap": down(_PRIDE_CREDIT_GAP, 2),
        "shadow": shadow, "radius": down(_PRIDE_CARTOUCHE_RADIUS, 0), "margin": margin,
        "field_left": field_left,
        "max_card": (max_card_w, max_card_h),
        "card_min": (card_min_w, min(down(_PRIDE_CARD_MIN[1], 30), max_card_h)),
        "text_max": (
            max(16, min(down(_PRIDE_TEXT_MAX[0], 16), max_card_w - 2 * pad_x)),
            max(16, min(down(_PRIDE_TEXT_MAX[1], 16), max_card_h - pad_top - pad_bottom)),
        ),
        "font": (max(8, down(34, 8)), max(6, down(14, 6))),
        "credits": (max(5, down(14, 5)), max(5, down(13, 5))),
        # Below this the byline is a smudge, so small thumbnails drop the
        # credits and give the quote the room.
        "show_credits": down(14, 5) >= _PRIDE_CREDIT_MIN_SIZE,
    }


def _pride_arm_slope(width: int, height: int) -> float:
    """Vertical-distance multiplier that keeps the chevron aspect-correct."""
    ref_w, ref_h = _PRIDE_REFERENCE_SIZE
    return (width / max(1, height)) * (ref_h / ref_w)


def _pride_chevron_tip(width: int) -> int:
    """x of the chevron's point — the left edge of the clear rainbow field."""
    return int(_PRIDE_CHEVRON_DEPTHS[-1] * width)


def _pride_paint_flag(image: Image.Image) -> None:
    """Paint the full-bleed waving flag: chevron over rainbow.

    Walks the canvas once, resolving each pixel to a band (via the wave-
    displaced row) and then to an ink through the three-way Bayer partition.
    The stripe index is clamped, so the frame is a crop of a larger flag.
    """
    width, height = image.size
    px = image.load()
    white = SPECTRA6["white"]
    black = SPECTRA6["black"]
    # A solid band is the degenerate partition: its "light" ink is its own ink
    # and its share is zero, so the same three-way branch below covers both.
    def _resolve(table):
        out = []
        for dark, light, density in table:
            dark_ink = SPECTRA6[dark]
            out.append((dark_ink, SPECTRA6[light] if light else dark_ink, density))
        return out

    inks = _resolve(_PRIDE_STRIPE_INKS)
    chevron = _resolve(_PRIDE_CHEVRON_INKS)
    depths = [d * width for d in _PRIDE_CHEVRON_DEPTHS]
    bands = len(depths)
    stripe_h = height / _PRIDE_STRIPES
    centre = height / 2.0
    arm_slope = _pride_arm_slope(width, height)
    # Normalise the tilt so the steepest fold reaches the configured peak
    # density rather than whatever the amplitude/frequency product happens to be.
    max_tilt = sum(amp * freq for amp, freq, _, _ in _PRIDE_WAVE) or 1.0
    tile = len(BAYER_8x8)
    scale = tile * tile
    for y in range(height):
        row = BAYER_8x8[y % tile]
        for x in range(width):
            displacement, tilt = _pride_wave(x, y)
            # The chevron is resolved against the wave-displaced row too. The
            # arms are straight, so one distance term places a pixel in the
            # whole nest of Vs; the slope carries the aspect correction.
            shifted = y - displacement
            reach = x + abs(shifted - centre) * arm_slope
            band = bisect.bisect_left(depths, reach)
            if band < bands:
                dark, light, light_density = chevron[band]
            else:
                index = int(shifted / stripe_h)
                dark, light, light_density = inks[max(0, min(_PRIDE_STRIPES - 1, index))]
            level = tilt / max_tilt
            if level >= 0.0:
                lighting, cells = white, round(level * _PRIDE_LIGHT_PEAK * scale)
            else:
                lighting, cells = black, round(-level * _PRIDE_SHADE_PEAK * scale)
            cell = row[x % tile]
            if cell < cells:
                px[x, y] = lighting
                continue
            px[x, y] = light if cell < cells + round(light_density * (scale - cells)) else dark


def _pride_layout(draw: ImageDraw.ImageDraw, quote_row: dict, width: int, height: int) -> dict:
    """Measure the quote and credits before anything is painted.

    Measured against the largest text area the card may occupy; the card is
    then cut to fit. Returns the fonts, the wrapped lines, the measured block
    size, and the rendered credit lines.
    """
    metrics = _pride_metrics(width, height)
    max_w, max_h = metrics["text_max"]
    font_max, font_min = metrics["font"]

    # Credits are measured first and the quote gets the remaining vertical
    # budget; fitting the quote first pushes the byline off a thumbnail.
    credits = []
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "")
    for text, key, size in ((author.upper(), "quote_bold", metrics["credits"][0]),
                            (title, "quote_regular", metrics["credits"][1])):
        if not text or not metrics["show_credits"]:
            continue
        font = load_font(theme_font_candidates("pride", key), size=size)
        while len(text) > 1 and draw.textlength(text, font=font) > max_w:
            text = text[:-1]
        credits.append((text, font, draw.textbbox((0, 0), text, font=font)))
    credits_h = sum(bbox[3] - bbox[1] + 5 for _, _, bbox in credits) - 5 if credits else 0

    quote_budget = max(16, max_h - (credits_h + metrics["gap"] if credits else 0))
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    matched = quote_row.get("matched_text") or ""
    quote_font, quote_font_bold, wrapped, line_height, _ = fit_quote(
        draw, display_quote, matched, max_w, quote_budget,
        font_max=font_max, font_min=font_min, line_height_mult=1.24, theme="pride",
    )
    lines = []
    block_w = 0
    for line in wrapped:
        start = 0
        while start < len(line) and line[start][0].strip() == "":
            start += 1
        end = len(line)
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        drawable = line[start:end]
        widths = []
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            bbox = draw.textbbox((0, 0), chunk, font=font)
            widths.append(bbox[2] - bbox[0])
        block_w = max(block_w, sum(widths))
        lines.append((drawable, widths, sum(widths)))

    for _, _, bbox in credits:
        block_w = max(block_w, bbox[2] - bbox[0])

    return {
        "metrics": metrics,
        "quote_font": quote_font,
        "quote_font_bold": quote_font_bold,
        "lines": lines,
        "line_height": line_height,
        "quote_h": len(lines) * line_height,
        "credits": credits,
        "credits_h": credits_h,
        "block_w": block_w,
    }


def _pride_card_rect(layout: dict, width: int, height: int) -> tuple[int, int, int, int]:
    """Cut the card to fit the measured block, centred and clamped to canvas."""
    m = layout["metrics"]
    content_h = layout["quote_h"] + (m["gap"] + layout["credits_h"] if layout["credits"] else 0)
    card_w = max(m["card_min"][0], layout["block_w"] + 2 * m["pad_x"])
    card_h = max(m["card_min"][1], content_h + m["pad_top"] + m["pad_bottom"])
    # Backstop: the measured block can exceed its budget when even the minimum
    # font overflows.
    card_w = min(card_w, m["max_card"][0])
    card_h = min(card_h, m["max_card"][1])
    # Centre it in the rainbow field right of the chevron's point. On a canvas
    # too narrow for that the clamp wins and the card overlaps the chevron.
    right_limit = width - m["margin"] - card_w
    x0 = max(m["margin"], min(m["field_left"] + max(0, (right_limit - m["field_left"]) // 2), right_limit))
    x0 = max(0, x0)
    y0 = max(0, (height - card_h) // 2)
    return x0, y0, x0 + card_w, y0 + card_h


def _pride_paint_cartouche(draw: ImageDraw.ImageDraw, rect: tuple[int, int, int, int], metrics: dict) -> None:
    """Knock a white card out of the cloth, lifted off it by a shadow ledge.

    The shadow is a black rounded rectangle offset down and right; without it
    the card reads as a hole cut in the flag.
    """
    x0, y0, x1, y1 = rect
    radius = max(0, min(metrics["radius"], (x1 - x0) // 2, (y1 - y0) // 2))
    offset = metrics["shadow"]
    draw.rounded_rectangle((x0 + offset, y0 + offset, x1 + offset, y1 + offset), radius=radius, fill=SPECTRA6["black"])
    draw.rounded_rectangle(rect, radius=radius, fill=SPECTRA6["white"], outline=SPECTRA6["black"], width=1)


def _pride_paint_text(image: Image.Image, draw: ImageDraw.ImageDraw, layout: dict, rect) -> None:
    """Quote then credits on the card, the matched phrase in the flag's violet.

    The time phrase is the R+B 1:1 stipple of the flag's sixth stripe; on the
    white card an even mix holds (no blue ground to melt into).
    """
    black = SPECTRA6["black"]
    red = SPECTRA6["red"]
    blue = SPECTRA6["blue"]
    m = layout["metrics"]
    x0, y0, x1, y1 = rect
    inner_w = x1 - x0
    content_h = layout["quote_h"] + (m["gap"] + layout["credits_h"] if layout["credits"] else 0)
    y = y0 + max(m["pad_top"], ((y1 - y0) - content_h) // 2)
    ascent = _font_ascent(layout["quote_font"])
    for drawable, widths, line_w in layout["lines"]:
        x = x0 + (inner_w - line_w) // 2
        for (chunk, is_bold), chunk_w in zip(drawable, widths):
            font = layout["quote_font_bold"] if is_bold else layout["quote_font"]
            chunk_y = y + (ascent - _font_ascent(font))
            if is_bold and chunk.strip():
                draw_text_dithered(image, (x, chunk_y), chunk, font, dark=red, light=blue)
            else:
                draw.text((x, chunk_y), chunk, font=font, fill=black)
            x += chunk_w
        y += layout["line_height"]
    if not layout["credits"]:
        return
    y += m["gap"]
    for text, font, bbox in layout["credits"]:
        x = x0 + (inner_w - (bbox[2] - bbox[0])) // 2 - bbox[0]
        draw.text((x, y - bbox[1]), text, font=font, fill=black)
        y += (bbox[3] - bbox[1]) + 5


def render_pride_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """The Progress Pride flag, flying (see the module section comment above).

    ``time_str`` is unused (the matched phrase carries the time); kept for
    dispatch-signature uniformity.
    """
    del time_str
    image = Image.new("RGB", (width, height), color=SPECTRA6["white"])
    _pride_paint_flag(image)
    draw = ImageDraw.Draw(image)
    layout = _pride_layout(draw, quote_row, width, height)
    rect = _pride_card_rect(layout, width, height)
    _pride_paint_cartouche(draw, rect, layout["metrics"])
    pad_x = layout["metrics"]["pad_x"]
    inner = (rect[0] + pad_x, rect[1], rect[2] - pad_x, rect[3])
    _pride_paint_text(image, draw, layout, inner)
    return snap_image_to_palette(image, SPECTRA6_PALETTE)



# ─── abyssal (deep sea) ──────────────────────────────────────────────────────
#
# A quote read through deep water: a vertical gradient from a seafoam surface
# to near-black, a caustic light net fading out below it, marine snow, and
# bioluminescent jellyfish.
#
# The surface band is the catalogue's **seafoam (G+B+W @ 40/30/30)**, a 3-way
# Bayer partition whose weights fall with depth (turquoise → pure blue).
# Bioluminescence goes through ``paint_neon_mask``: a blue bloom for the prose
# so it sits *in* the water, a mint-green bloom for the matched phrase.
#
# **The hour is a depth.** At 500 m per hour the sounding gauge down the left
# margin runs 500 m at one o'clock to 6000 m at twelve — the floor of the
# abyssal zone. ``time_str`` is therefore used.

_ABYSSAL_SURFACE_BOTTOM = 96     # seafoam band fades to plain blue by here
_ABYSSAL_CAUSTIC_BOTTOM = 172    # the light net dies out by here
_ABYSSAL_DEEP_TOP = 208          # below this the water darkens toward black
_ABYSSAL_QUOTE_RECT = (128, 150, 688, 330)
_ABYSSAL_GAUGE_X = 54
_ABYSSAL_GAUGE_TOP = 62
_ABYSSAL_GAUGE_BOTTOM = 428
_ABYSSAL_METRES_PER_HOUR = 500
# (cx, cy, bell radius) — kept clear of the quote rect and the gauge column.
_ABYSSAL_JELLYFISH = ((252, 392, 25), (566, 374, 19), (712, 236, 14))
_ABYSSAL_SNOW_SEED = 0xA1B255
_ABYSSAL_SNOW_COUNT = 260


def _abyssal_water_ground() -> frozenset:
    """Inks a bloom may overwrite: the water itself, not what is lit in it.

    Excludes white and green so a later halo cannot repaint the caustics, the
    snow or an already-painted jellyfish.
    """
    return frozenset({SPECTRA6["blue"], SPECTRA6["black"]})


def _abyssal_paint_water(image: Image.Image) -> None:
    """The depth gradient: seafoam surface → blue → navy → near-black.

    The surface is a 3-way Bayer partition (white / green / blue) whose white
    and green weights fall linearly with depth; the middle is plain blue; the
    deep band flips blue to black on a rising ramp capped short of solid, since
    a fully black floor reads as a border rather than water.
    """
    px = image.load()
    width, height = image.size
    blue, white, green, black = (SPECTRA6["blue"], SPECTRA6["white"],
                                 SPECTRA6["green"], SPECTRA6["black"])
    deep_span = max(1, height - _ABYSSAL_DEEP_TOP)
    for y in range(height):
        row = BAYER_4x4[y % 4]
        if y < _ABYSSAL_SURFACE_BOTTOM:
            frac = 1.0 - y / _ABYSSAL_SURFACE_BOTTOM
            # Seafoam G+B+W @ 40/30/30 in 16 Bayer cells: 6 green / 5 blue /
            # 5 white at the surface. Both weights scale with `frac`, so the
            # ratio holds as the band fades into plain blue.
            white_cells = 5.0 * frac
            green_cells = white_cells + 6.0 * frac
            for x in range(width):
                cell = row[x % 4]
                px[x, y] = white if cell < white_cells else (green if cell < green_cells else blue)
        elif y >= _ABYSSAL_DEEP_TOP:
            frac = (y - _ABYSSAL_DEEP_TOP) / deep_span
            black_cells = min(14.0, 16.0 * (frac ** 0.85))
            for x in range(width):
                px[x, y] = black if row[x % 4] < black_cells else blue
        else:
            for x in range(width):
                px[x, y] = blue


def _abyssal_paint_caustics(image: Image.Image) -> None:
    """The rippling net of surface light, thinning with depth.

    A caustic net is a **contour** of the interference field: a thin band
    around the zero crossing (``abs(f) < eps``) is a connected net, where
    thresholding the peaks gives confetti. Two sines alone form a regular
    lattice; the third, incommensurate term warps it into irregular cells.
    Density falls with depth so the band has no visible lower edge.
    """
    px = image.load()
    width = image.size[0]
    white, blue = SPECTRA6["white"], SPECTRA6["blue"]
    for y in range(min(image.size[1], _ABYSSAL_CAUSTIC_BOTTOM)):
        fade = (1.0 - y / _ABYSSAL_CAUSTIC_BOTTOM) ** 1.2
        density = 6.5 * fade
        if density <= 0:
            continue
        row = BAYER_4x4[y % 4]
        for x in range(width):
            field = (math.sin(x * 0.038 + y * 0.021)
                     + math.sin(x * 0.026 - y * 0.033)
                     + 0.8 * math.sin(x * 0.014 + y * 0.047))
            if abs(field) < 0.13 and row[x % 4] < density and px[x, y] == blue:
                px[x, y] = white


def _abyssal_paint_snow(image: Image.Image) -> None:
    """Marine snow — the constant drift of detritus that makes water read as deep.

    Seeded, so a given frame is byte-identical on re-render. Skips the surface
    band, where it would be lost in the caustics anyway.
    """
    rng = random.Random(_ABYSSAL_SNOW_SEED)
    px = image.load()
    width, height = image.size
    white = SPECTRA6["white"]
    ground = _abyssal_water_ground()
    # Clamp the start to the canvas: on a short /api/preview thumbnail the band
    # start can sit below the image, and randrange raises on an empty range.
    y_min = min(_ABYSSAL_CAUSTIC_BOTTOM // 2, max(0, height - 1))
    for _ in range(_ABYSSAL_SNOW_COUNT):
        x = rng.randrange(width)
        y = rng.randrange(y_min, height)
        if px[x, y] not in ground:
            continue
        px[x, y] = white
        if rng.random() < 0.22 and x + 1 < width and y + 1 < height:
            if px[x + 1, y] in ground:
                px[x + 1, y] = white


def _abyssal_paint_jellyfish(image: Image.Image, cx: int, cy: int, radius: int) -> None:
    """One bioluminescent jellyfish: a domed bell over trailing tentacles.

    One mask, so bell and tentacles share one bloom (separate blooms
    double-expose where the halos meet). White core, green halo.
    """
    mask = Image.new("L", image.size, 0)
    mdraw = ImageDraw.Draw(mask)
    # Bell: a hollow arc, not a filled dome, so the water shows through and it
    # reads as translucent.
    mdraw.arc((cx - radius, cy - radius, cx + radius, cy + radius), 180, 360, fill=255, width=2)
    mdraw.line((cx - radius, cy, cx + radius, cy), fill=255, width=2)
    # A couple of radial ribs inside the bell, the way a real medusa is veined.
    for rib in (-0.5, 0.0, 0.5):
        rx = cx + int(radius * rib * 0.8)
        mdraw.line((rx, cy - int(radius * (0.82 - abs(rib) * 0.5)), rx, cy), fill=255, width=1)
    # Tentacles: wavy lines trailing below, each with its own phase.
    for index in range(5):
        offset = cx + int((index - 2) * radius * 0.42)
        phase = index * 1.1
        length = int(radius * (2.6 + 0.5 * math.sin(phase)))
        prev = (offset, cy)
        for step in range(1, length, 3):
            sway = int(round(radius * 0.28 * math.sin(step * 0.16 + phase)))
            point = (offset + sway, cy + step)
            mdraw.line((prev[0], prev[1], point[0], point[1]), fill=255, width=1)
            prev = point
    paint_neon_mask(image, mask, SPECTRA6["white"], SPECTRA6["green"],
                    radius=max(3, radius // 3), gamma=2.0, cap=0.62,
                    ground=_abyssal_water_ground())


def _abyssal_paint_gauge(image: Image.Image, draw: ImageDraw.ImageDraw, hour: int) -> None:
    """Sounding gauge down the left margin — the hour, read as a depth.

    Twelve graduations at 500 m each (bottoming out at 6000 m). The current
    hour gets a filled marker and a label; every third graduation is long and
    numbered.
    """
    white, green = SPECTRA6["white"], SPECTRA6["green"]
    top, bottom = _ABYSSAL_GAUGE_TOP, _ABYSSAL_GAUGE_BOTTOM
    x = _ABYSSAL_GAUGE_X
    draw.line((x, top, x, bottom), fill=white, width=1)
    step = (bottom - top) / 12.0
    label_font = load_font(META_FONT_CANDIDATES, size=11)
    for mark in range(1, 13):
        y = top + step * mark
        long_mark = mark % 3 == 0
        draw.line((x, y, x + (13 if long_mark else 7), y), fill=white, width=1)
        # Skip the graduation numeral on the hour's own mark — the green marker
        # label lands in the same place and the two overprint into mush (most
        # visibly at 12 o'clock, where both read "6000").
        if long_mark and mark != hour:
            draw.text((x + 17, y), f"{mark * _ABYSSAL_METRES_PER_HOUR}", font=label_font,
                      fill=white, anchor="lm")
    # The hour: a filled marker, drawn last so it sits over its graduation.
    marker_y = top + step * hour
    draw.polygon([(x - 9, marker_y - 5), (x - 1, marker_y), (x - 9, marker_y + 5)], fill=green)
    depth_font = load_font(META_FONT_BOLD_CANDIDATES, size=12)
    draw.text((x + 17, marker_y), f"{hour * _ABYSSAL_METRES_PER_HOUR} m", font=depth_font,
              fill=green, anchor="lm")


def _abyssal_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> int:
    """The quote, lit like everything else down here. Returns the block bottom.

    Two masks, as in izakaya: white cores throughout, a blue bloom on the body
    and a mint-green bloom on the matched phrase.
    """
    cool, hot, bottom = wrap_quote_into_masks(
        draw, image.size, quote_row, _ABYSSAL_QUOTE_RECT,
        theme="abyssal", line_height_mult=1.38,
    )
    ground = _abyssal_water_ground()
    paint_neon_mask(image, cool, SPECTRA6["white"], SPECTRA6["blue"],
                    radius=6, gamma=2.1, cap=0.55, ground=ground)
    paint_neon_mask(image, hot, SPECTRA6["white"], SPECTRA6["green"],
                    radius=6, gamma=1.9, cap=0.7, ground=ground)
    return bottom


def _abyssal_paint_credits(image: Image.Image, draw: ImageDraw.ImageDraw,
                           quote_row: dict, top: int) -> None:
    """author · title below the quote, unlit — a label, not a light source."""
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or fallback_title(quote_row) or "").strip()
    parts = [p for p in (author, title) if p]
    if not parts:
        return
    text = "  ·  ".join(parts)
    font = load_font(theme_font_candidates("abyssal", "ornament"), size=14)
    width = image.size[0]
    max_w = max(40, width - 260)
    while len(text) > 1 and draw.textlength(text, font=font) > max_w:
        text = text[:-2].rstrip(" ·") + "…"
    y = min(max(top + 14, _ABYSSAL_QUOTE_RECT[3] - 2), image.size[1] - 40)
    draw.text((width // 2, y), text, font=font, fill=SPECTRA6["white"], anchor="ma")


def render_abyssal_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Deep sea (see the module section comment above).

    Laid out against the canonical 800×480; smaller canvases (``/api/preview``
    thumbnails) crop rather than reflow. Raw pixel writes clamp to
    ``image.size``; the gauge and credits use ``ImageDraw``, which clips.
    """
    image = Image.new("RGB", (width, height), color=SPECTRA6["blue"])
    _abyssal_paint_water(image)
    _abyssal_paint_caustics(image)
    _abyssal_paint_snow(image)
    for cx, cy, radius in _ABYSSAL_JELLYFISH:
        _abyssal_paint_jellyfish(image, cx, cy, radius)
    draw = ImageDraw.Draw(image)
    _abyssal_paint_gauge(image, draw, _clock_hour12(time_str))
    block_bottom = _abyssal_paint_quote(image, draw, quote_row)
    _abyssal_paint_credits(image, draw, quote_row, block_bottom)
    return snap_image_to_palette(image, SPECTRA6_PALETTE)


# ---------------------------------------------------------------------------
# pulp — a 1940s lurid paperback front (issue #214).
#
# A *cover*, not a ``comic`` panel: masthead strip, huge title, corner banner,
# price flash and blurb on a saturated yellow ground.
#
# **Misregistration:** ``_pulp_misregistered_text`` paints a red plate at an
# offset under the black one, leaving a red fringe on heavy elements. It needs
# a *fat* face — on a hairline serif the fringe eats the letterform.
#
# The time rides the **issue line**, ``VOL. XII · NO. 30`` (hour as a Roman
# volume, minute as the issue number). It is the most direct time surface in
# the rotation, accepted because a volume/number line is required furniture on
# this object and reads as a serial. The quote still carries the time.
#
# Composition, top to bottom: red masthead (imprint + issue line); the book's
# title, uppercased and fitted; an all-caps byline; the quote as the blurb on
# a knocked-out white band (black on saturated yellow is illegible at
# distance); a starburst price flash; and an angled COMPLETE NOVEL banner.
# ---------------------------------------------------------------------------
_PULP_MASTHEAD_H = 46
_PULP_TITLE_TOP = 58
_PULP_TITLE_MAX = 132          # title block height before the byline
_PULP_BLURB_RECT = (54, 176, 746, 380)
_PULP_PLATE_OFFSET = (3, 2)    # how far the red plate missed the black one
_PULP_IMPRINT = "IDLE HOURS"
_PULP_BANNER_TEXT = "COMPLETE NOVEL"
_PULP_PRICE = "25¢"
# Centre of the diagonal corner flash: far enough in that the text stays on
# canvas, low enough to clear the blurb band.
_PULP_BANNER_CENTRE = (104, 420)
_PULP_BANNER_SIZE = (186, 30)


def _pulp_issue_line(time_str: str) -> str:
    """``VOL. <roman hour> · NO. <minute>`` — the cover's serial, and the clock."""
    try:
        hour, minute = (int(part) for part in time_str.split(":")[:2])
    except (ValueError, AttributeError):
        hour, minute = 12, 0
    roman = _TAROT_ROMAN_NUMERALS[(hour % 12) or 12]
    return f"VOL. {roman}  ·  NO. {minute:02d}"


def _pulp_misregistered_text(image, draw, xy, text, font, *, anchor=None, offset=None):
    """Paint ``text`` as a black plate with the red plate landing off-register.

    Red goes down first at an offset and black covers most of it, leaving a
    fringe on two edges. Red drawn *after* black would read as a drop shadow.
    """
    dx, dy = offset or _PULP_PLATE_OFFSET
    x, y = xy
    draw.text((x + dx, y + dy), text, font=font, fill=SPECTRA6["red"], anchor=anchor)
    draw.text((x, y), text, font=font, fill=SPECTRA6["black"], anchor=anchor)
    del image


def _pulp_paint_stock(image) -> None:
    """A coarse black screen over the yellow — cheap paper, cheaply printed.

    One dot per 4x4 tile (6.25%): reads as texture without shifting the hue.
    Not a red screen — red over yellow is the R+Y tangerine recipe and would
    change the ground colour rather than dirty it.
    """
    width, height = image.size
    px = image.load()
    yellow, black = SPECTRA6["yellow"], SPECTRA6["black"]
    for y in range(height):
        if y % 4 != 1:
            continue
        for x in range(1, width, 4):
            if px[x, y] == yellow:
                px[x, y] = black


def _pulp_paint_masthead(image, draw, width, time_str):
    """Red strip across the head: imprint on the left, issue line on the right."""
    red, black, yellow = SPECTRA6["red"], SPECTRA6["black"], SPECTRA6["yellow"]
    draw.rectangle((0, 0, width, _PULP_MASTHEAD_H), fill=red)
    draw.rectangle((0, _PULP_MASTHEAD_H - 4, width, _PULP_MASTHEAD_H), fill=black)
    imprint = load_font([(ALFA_SLAB_ONE, None), *QUOTE_FONT_BOLD_CANDIDATES], size=25)
    serial = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=15)
    draw.text((18, _PULP_MASTHEAD_H // 2 - 3), _PULP_IMPRINT, font=imprint, fill=yellow, anchor="lm")
    draw.text((width - 18, _PULP_MASTHEAD_H // 2 - 3), _pulp_issue_line(time_str),
              font=serial, fill=yellow, anchor="rm")


def _pulp_fit_title(draw, title, width):
    """Largest Alfa Slab One size whose uppercased title fits, wrapping to two.

    Shrunk aggressively before it may wrap, and never past two lines — more
    reads as a paragraph, not a cover title.
    """
    text = (title or "").strip().upper() or _PULP_IMPRINT
    budget = width - 72
    for size in range(64, 25, -3):
        font = load_font([(ALFA_SLAB_ONE, None), *QUOTE_FONT_BOLD_CANDIDATES], size=size)
        if draw.textlength(text, font=font) <= budget:
            return font, [text]
    # Still too wide at the floor: break at the space nearest the midpoint.
    words = text.split()
    if len(words) > 1:
        best = min(range(1, len(words)), key=lambda i: abs(len(" ".join(words[:i])) - len(text) // 2))
        pair = [" ".join(words[:best]), " ".join(words[best:])]
        for size in range(48, 19, -3):
            font = load_font([(ALFA_SLAB_ONE, None), *QUOTE_FONT_BOLD_CANDIDATES], size=size)
            if max(draw.textlength(line, font=font) for line in pair) <= budget:
                return font, pair
        return load_font([(ALFA_SLAB_ONE, None), *QUOTE_FONT_BOLD_CANDIDATES], size=20), pair
    return load_font([(ALFA_SLAB_ONE, None), *QUOTE_FONT_BOLD_CANDIDATES], size=26), [text]


def _pulp_paint_title(image, draw, quote_row, width):
    """Cover title (the book) plus an all-caps byline. Returns the next free y."""
    title = (quote_row.get("title") or "").strip() or (quote_row.get("author") or "").strip()
    font, lines = _pulp_fit_title(draw, title, width)
    ascent = _font_ascent(font)
    y = _PULP_TITLE_TOP
    for line in lines:
        _pulp_misregistered_text(image, draw, (width // 2, y), line, font, anchor="ma")
        y += int(ascent * 1.02)
    author = (quote_row.get("author") or "").strip()
    if author:
        byline_font = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=16)
        text = f"BY {author.upper()}"
        while text and draw.textlength(text, font=byline_font) > width - 80:
            text = text[:-1]
        draw.text((width // 2, y + 6), text, font=byline_font, fill=SPECTRA6["black"], anchor="ma")
        y += 30
    return y


def _pulp_paint_blurb(image, draw, quote_row, rect):
    """The quote as the cover blurb, on a knocked-out white band.

    Black on saturated yellow is illegible at distance, so the band is wiped
    to white and given a heavy black rule.
    """
    x0, y0, x1, y1 = rect
    white, black, red = SPECTRA6["white"], SPECTRA6["black"], SPECTRA6["red"]
    draw.rectangle((x0, y0, x1, y1), fill=white, outline=black, width=3)
    inner = (x0 + 18, y0 + 14, x1 - 18, y1 - 14)
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    matched = quote_row.get("matched_text") or ""
    quote_font, quote_font_bold, wrapped, line_height, _ = fit_quote(
        draw, display_quote, matched, inner[2] - inner[0], inner[3] - inner[1],
        font_max=27, font_min=12, line_height_mult=1.16, theme="pulp",
    )
    block_h = len(wrapped) * line_height
    y = inner[1] + max(0, ((inner[3] - inner[1]) - block_h) // 2)
    ascent = _font_ascent(quote_font)
    for line in wrapped:
        start, end = 0, len(line)
        while start < end and line[start][0].strip() == "":
            start += 1
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        drawable = line[start:end]
        widths = []
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            box = draw.textbbox((0, 0), chunk, font=font)
            widths.append(box[2] - box[0])
        x = inner[0] + max(0, ((inner[2] - inner[0]) - sum(widths)) // 2)
        for (chunk, is_bold), chunk_w in zip(drawable, widths):
            font = quote_font_bold if is_bold else quote_font
            chunk_y = y + (ascent - _font_ascent(font))
            draw.text((x, chunk_y), chunk, font=font, fill=red if is_bold else black)
            x += chunk_w
        y += line_height


def _pulp_paint_price_flash(image, draw, width, height):
    """A starburst price badge — the coin-price flash every cover carried."""
    red, black, yellow = SPECTRA6["red"], SPECTRA6["black"], SPECTRA6["yellow"]
    cx, cy, r = width - 72, height - 56, 44
    points = []
    for i in range(24):
        angle = math.pi * 2 * i / 24
        radius = r if i % 2 == 0 else r * 0.72
        points.append((cx + radius * math.cos(angle), cy + radius * math.sin(angle)))
    draw.polygon(points, fill=red, outline=black)
    font = load_font([(ALFA_SLAB_ONE, None), *QUOTE_FONT_BOLD_CANDIDATES], size=20)
    draw.text((cx, cy), _PULP_PRICE, font=font, fill=yellow, anchor="mm")


def _pulp_paint_corner_banner(image, draw, width, height):
    """The angled flag across the bottom-left corner.

    Drawn on its own tile and rotated 45°, since PIL cannot set rotated text.
    """
    red, yellow, black = SPECTRA6["red"], SPECTRA6["yellow"], SPECTRA6["black"]
    band_w, band_h = _PULP_BANNER_SIZE
    # Built RGBA and pasted through its own alpha so the rotation's corner fill
    # stays transparent.
    tile = Image.new("RGBA", (band_w, band_h), red + (255,))
    tdraw = ImageDraw.Draw(tile)
    tdraw.rectangle((0, 0, band_w - 1, band_h - 1), outline=black + (255,), width=2)
    font = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=13)
    text = _PULP_BANNER_TEXT
    while len(text) > 1 and tdraw.textlength(text, font=font) > band_w - 14:
        text = text[:-1]
    tdraw.text((band_w // 2, band_h // 2), text, font=font, fill=yellow + (255,), anchor="mm")
    # BICUBIC, not NEAREST: NEAREST shreds 13 px glyph stems. The alpha is then
    # hard-thresholded so the band's edges stay crisp instead of leaving an
    # off-palette fringe against the yellow.
    rotated = tile.rotate(45, expand=True, resample=Image.BICUBIC, fillcolor=(0, 0, 0, 0))
    mask = rotated.split()[3].point(lambda v: 255 if v > 127 else 0)
    cx, cy = _PULP_BANNER_CENTRE
    cx = min(cx, max(0, width - 40))
    cy = min(cy, max(0, height - 40))
    image.paste(rotated.convert("RGB"), (cx - rotated.size[0] // 2, cy - rotated.size[1] // 2), mask)
    tile.close()
    rotated.close()


_METRO_ROUTES: tuple[tuple[tuple[int, int, int], tuple[tuple[int, int], ...]], ...] = (
    (SPECTRA6["red"], ((-20, 82), (122, 82), (210, 170), (590, 170), (686, 74), (820, 74))),
    (SPECTRA6["blue"], ((84, -20), (84, 118), (188, 222), (612, 222), (716, 326), (716, 500))),
    (SPECTRA6["green"], ((-20, 402), (132, 402), (238, 296), (560, 296), (662, 398), (820, 398))),
    (SPECTRA6["yellow"], ((238, -20), (238, 116), (318, 196), (482, 196), (562, 116), (562, -20))),
)


def _metro_paint_network(image: Image.Image) -> None:
    """Paint a schematic network with genuine 45-degree route geometry."""
    draw = ImageDraw.Draw(image)
    # Sparse coordinate dots give the white stock a printed-map texture
    # without turning it into graph paper or competing with the route lines.
    for y in range(64, 480, 32):
        for x in range(20, 800, 40):
            draw.point((x, y), fill=SPECTRA6["black"])
    # White gaps break the grid beneath each route, mimicking the casing used
    # on real diagram maps; the chromatic stroke then sits cleanly on top.
    for ink, points in _METRO_ROUTES:
        draw.line(points, fill=SPECTRA6["white"], width=15, joint="curve")
        draw.line(points, fill=ink, width=9, joint="curve")
        for x, y in points[1:-1]:
            draw.ellipse((x - 8, y - 8, x + 8, y + 8), fill=SPECTRA6["white"], outline=SPECTRA6["black"], width=2)

    # Four interchanges: a black outer ring and white centre are legible over
    # every route ink, and the paired nodes read as transfers rather than dots.
    for x, y in ((188, 222), (318, 196), (482, 196), (612, 222)):
        draw.ellipse((x - 12, y - 12, x + 12, y + 12), fill=SPECTRA6["white"], outline=SPECTRA6["black"], width=4)
        draw.ellipse((x - 3, y - 3, x + 3, y + 3), fill=SPECTRA6["black"])


def _metro_paint_chrome(image: Image.Image, time_str: str) -> None:
    draw = ImageDraw.Draw(image)
    draw.rectangle((0, 0, 800, 48), fill=SPECTRA6["black"])
    label_font = load_font(theme_font_candidates("metro", "ornament"), 19)
    small_font = load_font(theme_font_candidates("metro", "ornament"), 14)
    draw.text((26, 13), "IDLE HOURS METROPOLITAN", font=label_font, fill=SPECTRA6["white"])
    draw.text((625, 16), "LITERARY LINE", font=small_font, fill=SPECTRA6["yellow"])

    try:
        hour, minute = (int(part) for part in time_str.split(":")[:2])
    except (TypeError, ValueError):
        hour, minute = 0, 0
    hour = hour % 12 or 12
    # The clock becomes station furniture: hour is the line number and minute
    # is the stop. It is explicit, but read first as transit nomenclature.
    draw.ellipse((25, 398, 91, 464), fill=SPECTRA6["red"], outline=SPECTRA6["black"], width=4)
    code_font = load_font(theme_font_candidates("metro", "ornament"), 25)
    code = f"{hour:02d}"
    box = draw.textbbox((0, 0), code, font=code_font)
    draw.text((58 - (box[2] - box[0]) // 2, 411), code, font=code_font, fill=SPECTRA6["white"])
    draw.rectangle((98, 414, 202, 450), fill=SPECTRA6["black"])
    draw.text((110, 423), f"STOP {minute:02d}", font=small_font, fill=SPECTRA6["white"])

    # Route key along the bottom edge uses all four chromatic native inks.
    names = (("EXPRESS", SPECTRA6["red"]), ("NIGHT", SPECTRA6["blue"]), ("GARDEN", SPECTRA6["green"]), ("CIRCLE", SPECTRA6["yellow"]))
    x = 312
    for name, ink in names:
        draw.line((x, 448, x + 22, 448), fill=ink, width=7)
        draw.text((x + 29, 439), name, font=small_font, fill=SPECTRA6["black"])
        x += 119


def _metro_ellipsize(draw, text: str, font, max_width: int) -> str:
    """Trim text to a measured pixel budget, preserving an ellipsis."""
    text = str(text)
    if draw.textlength(text, font=font) <= max_width:
        return text
    ellipsis = "…"
    if draw.textlength(ellipsis, font=font) > max_width:
        return ""
    while text and draw.textlength(text.rstrip() + ellipsis, font=font) > max_width:
        text = text[:-1]
    return text.rstrip(" ,;:") + ellipsis


def _metro_fit_metadata(draw, author: str, title: str, author_font, title_font) -> tuple[str, str]:
    """Fit the two metadata labels into their shared 174..658 pixel row."""
    available = 658 - 174 - 12  # keep a visible gutter between the labels
    author_width = draw.textlength(author, font=author_font)
    title_width = draw.textlength(title, font=title_font)
    if author_width + title_width <= available:
        return author, title

    half = available // 2
    if author_width < half:
        author_budget = int(author_width)
        title_budget = available - author_budget
    elif title_width < half:
        title_budget = int(title_width)
        author_budget = available - title_budget
    else:
        author_budget = half
        title_budget = available - half
    return (
        _metro_ellipsize(draw, author, author_font, author_budget),
        _metro_ellipsize(draw, title, title_font, title_budget),
    )


def _metro_paint_quote_card(image: Image.Image, quote_row: dict) -> None:
    draw = ImageDraw.Draw(image)
    card = (116, 100, 684, 388)
    # Offset shadow + black keyline give the legend the physical hierarchy of
    # a pasted service notice, not a white hole accidentally left in the map.
    draw.rectangle((124, 108, 692, 396), fill=SPECTRA6["black"])
    draw.rectangle(card, fill=SPECTRA6["white"], outline=SPECTRA6["black"], width=4)
    draw.rectangle((116, 100, 684, 126), fill=SPECTRA6["black"])
    tab_font = load_font(theme_font_candidates("metro", "ornament"), 14)
    draw.text((132, 107), "CENTRAL INTERCHANGE  •  ALL STORIES CONNECT", font=tab_font, fill=SPECTRA6["white"])

    quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    regular, bold, lines, line_height, _ = fit_quote(
        draw, quote, quote_row.get("matched_text") or "", 500, 170, 34, 18, 1.16, theme="metro"
    )
    total_h = len(lines) * line_height
    y = 145 + max(0, (172 - total_h) // 2)
    for line in lines:
        widths = []
        for chunk, is_bold in line:
            font = bold if is_bold else regular
            box = draw.textbbox((0, 0), chunk, font=font)
            widths.append(box[2] - box[0])
        x = 400 - sum(widths) // 2
        body_ascent = _font_ascent(regular)
        for (chunk, is_bold), chunk_w in zip(line, widths):
            font = bold if is_bold else regular
            fill = SPECTRA6["red"] if is_bold else SPECTRA6["black"]
            draw.text((x, y + body_ascent - _font_ascent(font)), chunk, font=font, fill=fill)
            x += chunk_w
        y += line_height

    author = quote_row.get("author") or "UNKNOWN AUTHOR"
    title = quote_row.get("title") or fallback_title(quote_row)
    meta_font = load_font(theme_font_candidates("metro", "quote_regular"), 16)
    meta_bold = load_font(theme_font_candidates("metro", "quote_bold"), 16)
    draw.line((142, 338, 658, 338), fill=SPECTRA6["black"], width=2)
    draw.rectangle((142, 348, 164, 370), fill=SPECTRA6["blue"])
    author_text, title_text = _metro_fit_metadata(
        draw, str(author).upper(), str(title), meta_bold, meta_font
    )
    draw.text((174, 349), author_text, font=meta_bold, fill=SPECTRA6["black"])
    title_width = draw.textlength(title_text, font=meta_font)
    draw.text((658 - title_width, 350), title_text, font=meta_font, fill=SPECTRA6["black"])


def render_metro_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Render the literary clock as a full-palette metropolitan route map."""
    image = Image.new("RGB", (800, 480), color=SPECTRA6["white"])
    _metro_paint_network(image)
    _metro_paint_quote_card(image, quote_row)
    _metro_paint_chrome(image, time_str)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


def render_pulp_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A 1940s lurid paperback front (see the module section comment above)."""
    image = Image.new("RGB", (width, height), color=SPECTRA6["yellow"])
    _pulp_paint_stock(image)
    draw = ImageDraw.Draw(image)
    _pulp_paint_masthead(image, draw, width, time_str)
    _pulp_paint_title(image, draw, quote_row, width)
    blurb = (
        max(8, min(_PULP_BLURB_RECT[0], width - 24)),
        max(8, min(_PULP_BLURB_RECT[1], height - 24)),
        max(16, min(_PULP_BLURB_RECT[2], width - 8)),
        max(24, min(_PULP_BLURB_RECT[3], height - 8)),
    )
    if blurb[2] > blurb[0] + 20 and blurb[3] > blurb[1] + 20:
        _pulp_paint_blurb(image, draw, quote_row, blurb)
    _pulp_paint_corner_banner(image, draw, width, height)
    _pulp_paint_price_flash(image, draw, width, height)
    return snap_image_to_palette(image, SPECTRA6_PALETTE)


# ---------------------------------------------------------------------------
# vhs — a camcorder OSD over a degraded tape (issue #211).
#
# The identity is ``draw_text_chroma_shift``: red ghost left, blue ghost right,
# white core on top, so every glyph fringes like bled composite video.
#
# Four layers of wear, all deterministic:
#
#   * **Video noise**, denser toward the foot (the head sweep).
#   * **Tracking tears** — row bands shifted sideways. A real row-shift of the
#     painted pixels, applied AFTER the text, so whatever a tear crosses comes
#     apart with it.
#   * **Scanlines**, fainter than ``nightvision``'s (tape, not a terminal).
#   * **Dropout flecks** — sparse short white dashes; more read as snow.
#
# **The time carrier is a camcorder burn-in** — the one theme where HH:MM
# digits are authentic, since a camcorder OSD is a clock. Wall time, not a
# tape-position counter.
#
# The **date** stamp is NOT today's date (that would make the frame
# clock-dependent); it is derived from the quote via ``_row_digest`` — the
# date the tape was *recorded*.
# ---------------------------------------------------------------------------
_VHS_CHROMA_OFFSET = 2
_VHS_QUOTE_RECT = (86, 96, 714, 372)
_VHS_CREDIT_GAP = 20
_VHS_NOISE_SEED = 0x5648
_VHS_NOISE_COUNT = 2600
_VHS_TEAR_SEED = 0x7EA2
_VHS_TEARS = 3
# Tear magnitude is bounded well below the body cap height so a tear looks like
# the picture slipping, not the quote being deleted.
_VHS_TEAR_BAND = (2, 8)
_VHS_TEAR_SHIFT = (5, 17)
# Head-switching noise: the torn band of static across the last few scanlines,
# where the video heads swap mid-field. Always at the very bottom, so painted
# deterministically rather than left to the random tear pool.
_VHS_HEAD_SWITCH_H = 9
_VHS_DROPOUT_COUNT = 26
_VHS_SCANLINE_STEP = 4
# Tape-recorded date pool, indexed from the quote (see the section comment).
_VHS_TAPE_YEARS = (1984, 1987, 1989, 1991, 1993, 1996, 1998)


def _vhs_tape_date(quote_row: dict) -> str:
    """``JUN 14 1991`` — the date this tape was recorded, stable per quote."""
    months = ("JAN", "FEB", "MAR", "APR", "MAY", "JUN",
              "JUL", "AUG", "SEP", "OCT", "NOV", "DEC")
    seed = _row_digest(quote_row)
    year = _VHS_TAPE_YEARS[seed % len(_VHS_TAPE_YEARS)]
    month = months[(seed >> 4) % 12]
    day = 1 + (seed >> 8) % 28
    return f"{month} {day:02d} {year}"


def _vhs_paint_tape(image: Image.Image) -> None:
    """Near-black ground, scanlines, and noise rising toward the head sweep."""
    width, height = image.size
    px = image.load()
    black, blue, white = SPECTRA6["black"], SPECTRA6["blue"], SPECTRA6["white"]
    # Faint scanline modulation, softer than nightvision's.
    for y in range(0, height, _VHS_SCANLINE_STEP):
        for x in range(0, width, 2):
            px[x, y] = blue if (x + y) % 8 == 0 else black
    rng = random.Random(_VHS_NOISE_SEED)
    for _ in range(_VHS_NOISE_COUNT):
        # Bias toward the foot: two samples, keep the lower. Uniform noise
        # reads as a clean digital dither, not worn tape.
        y = max(rng.randrange(height), rng.randrange(height))
        x = rng.randrange(width)
        px[x, y] = white if rng.random() < 0.35 else blue


def _vhs_paint_dropouts(image: Image.Image) -> None:
    """Short white dashes where the oxide has shed off the tape."""
    width, height = image.size
    px = image.load()
    white = SPECTRA6["white"]
    rng = random.Random(_VHS_NOISE_SEED ^ 0xD0)
    for _ in range(_VHS_DROPOUT_COUNT):
        y = max(rng.randrange(height), rng.randrange(height))
        x = rng.randrange(max(1, width - 40))
        for dx in range(rng.randrange(6, 34)):
            if x + dx < width:
                px[x + dx, y] = white


def _vhs_apply_tears(image: Image.Image) -> None:
    """Shift bands of rows sideways — the tracking error the theme is named for.

    Applied *after* everything else, on the painted pixels, so a tear cuts
    through the quote and the OSD as well as the ground.
    """
    width, height = image.size
    px = image.load()
    black = SPECTRA6["black"]

    def shift_row(y: int, shift: int) -> None:
        row = [px[x, y] for x in range(width)]
        for x in range(width):
            src = x - shift
            px[x, y] = row[src] if 0 <= src < width else black

    rng = random.Random(_VHS_TEAR_SEED)
    for _ in range(_VHS_TEARS):
        top = rng.randrange(height)
        band = rng.randrange(*_VHS_TEAR_BAND)
        shift = rng.choice((-1, 1)) * rng.randrange(*_VHS_TEAR_SHIFT)
        for y in range(top, min(height, top + band)):
            shift_row(y, shift)

    # Head-switching noise: repaint the band as bright static first (shifting
    # the existing noise alone changes nothing visible), then tear each row by
    # a different amount.
    white, blue = SPECTRA6["white"], SPECTRA6["blue"]
    for index, y in enumerate(range(max(0, height - _VHS_HEAD_SWITCH_H), height)):
        for x in range(width):
            roll = rng.random()
            if roll < 0.34:
                px[x, y] = white
            elif roll < 0.6:
                px[x, y] = blue
            elif roll < 0.66:
                px[x, y] = black
        shift_row(y, rng.randrange(8, 30) * (1 if index % 2 else -1))


def _vhs_credit_lines(quote_row: dict) -> list[tuple[str, int]]:
    """Author + title, uppercased author first, at their chrome sizes."""
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "")
    return [(text, size) for text, size in ((author.upper(), 17), (title, 15)) if text]


def _vhs_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> int:
    """The quote as chroma-bled OSD text; returns the block's bottom edge.

    The matched phrase gets a wider chroma offset rather than a different
    colour — on tape, what stands out is what has degraded most.

    Quote and credits are centred *together* between the two OSD strips,
    which is why this returns a y rather than painting to a fixed rect.
    """
    x0, y0, x1, y1 = _VHS_QUOTE_RECT
    if x1 - x0 < 40 or y1 - y0 < 40:
        return y0
    white, red, blue = SPECTRA6["white"], SPECTRA6["red"], SPECTRA6["blue"]
    ground = frozenset({SPECTRA6["black"], blue, white, red})
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    matched = quote_row.get("matched_text") or ""

    credits = _vhs_credit_lines(quote_row)
    credit_h = sum(size + 6 for _, size in credits)
    budget = (y1 - y0) - (credit_h + _VHS_CREDIT_GAP if credits else 0)

    quote_font, quote_font_bold, wrapped, line_height, _ = fit_quote(
        draw, display_quote, matched, x1 - x0, budget,
        font_max=34, font_min=14, line_height_mult=1.26, theme="vhs",
    )
    block_h = len(wrapped) * line_height
    total = block_h + (credit_h + _VHS_CREDIT_GAP if credits else 0)
    y = y0 + max(0, ((y1 - y0) - total) // 2)
    ascent = _font_ascent(quote_font)
    for line in wrapped:
        start, end = 0, len(line)
        while start < end and line[start][0].strip() == "":
            start += 1
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        drawable = line[start:end]
        widths = []
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            box = draw.textbbox((0, 0), chunk, font=font)
            widths.append(box[2] - box[0])
        start_x = x0 + max(0, ((x1 - x0) - sum(widths)) // 2)
        # Two passes over the line: every ghost, then every core. Per-chunk
        # ghost-then-core lets the next chunk's left ghost land on the previous
        # chunk's core (from an offset of about 5), and the ``ground`` guard
        # cannot catch it since it lists the white core too.
        for pass_core in (False, True):
            x = start_x
            for (chunk, is_bold), chunk_w in zip(drawable, widths):
                font = quote_font_bold if is_bold else quote_font
                chunk_y = y + (ascent - _font_ascent(font))
                draw_text_chroma_shift(
                    image, (x, chunk_y), chunk, font,
                    core=white if pass_core else None,
                    left=None if pass_core else red,
                    right=None if pass_core else blue,
                    offset=_VHS_CHROMA_OFFSET + (1 if is_bold else 0),
                    ground=ground,
                )
                x += chunk_w
        y += line_height
    return y


def _vhs_paint_osd(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict,
                   width: int, height: int, time_str: str) -> None:
    """Camcorder chrome: REC indicator, tape date, and the time burn-in.

    Set in Pixelify Sans, a pixel face like a real OSD character generator.
    The burn-in is the theme's time carrier (a camcorder OSD is a clock).
    """
    if width < 200 or height < 120:
        return
    white, red = SPECTRA6["white"], SPECTRA6["red"]
    chrome = load_font([(PIXELIFYSANS_VARIABLE, "Bold"), *META_FONT_BOLD_CANDIDATES], size=17)
    small = load_font([(PIXELIFYSANS_VARIABLE, "Regular"), *META_FONT_CANDIDATES], size=15)
    # REC + a solid red dot, top-left.
    draw.text((30, 26), "REC", font=chrome, fill=white)
    dot = draw.textlength("REC", font=chrome)
    draw.ellipse((30 + dot + 8, 30, 30 + dot + 20, 42), fill=red)
    # SP is the standard-play tape speed every camcorder stamped in the corner.
    draw.text((width - 30, 26), "SP", font=chrome, fill=white, anchor="ra")
    draw.text((30, height - 52), _vhs_tape_date(quote_row), font=small, fill=white)
    burn = (time_str or "").strip() or "00:00"
    draw.text((width - 30, height - 54), f"{burn}:00", font=chrome, fill=white, anchor="ra")


def _vhs_paint_credits(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict,
                       width: int, top: int) -> None:
    """Author + title below the quote, bled like the body but at chrome size."""
    white, red, blue = SPECTRA6["white"], SPECTRA6["red"], SPECTRA6["blue"]
    ground = frozenset({SPECTRA6["black"], blue, white, red})
    y = top + _VHS_CREDIT_GAP
    for text, size in _vhs_credit_lines(quote_row):
        font = load_font([(ANTONIO_VARIABLE, "Bold"), *META_FONT_BOLD_CANDIDATES], size=size)
        while len(text) > 1 and draw.textlength(text, font=font) > width - 140:
            text = text[:-1]
        box = draw.textbbox((0, 0), text, font=font)
        draw_text_chroma_shift(
            image, ((width - (box[2] - box[0])) // 2 - box[0], y - box[1]), text, font,
            core=white, left=red, right=blue, offset=1, ground=ground,
        )
        y += size + 6


def render_vhs_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A camcorder OSD over a worn tape (see the module section comment above).

    Composed at the canonical 800x480 (fixed panel coordinates) and
    NEAREST-downsampled for other sizes (``metro`` convention); an
    interpolating filter would average the stipples into off-palette colours.
    """
    image = Image.new("RGB", (800, 480), color=SPECTRA6["black"])
    _vhs_paint_tape(image)
    draw = ImageDraw.Draw(image)
    block_bottom = _vhs_paint_quote(image, draw, quote_row)
    _vhs_paint_credits(image, draw, quote_row, 800, block_bottom)
    _vhs_paint_osd(image, draw, quote_row, 800, 480, time_str)
    _vhs_paint_dropouts(image)
    # Tears go last, over the finished picture — see _vhs_apply_tears.
    _vhs_apply_tears(image)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image



# ---------------------------------------------------------------------------
# control — the Astral Plane, after Remedy's *Control* (2019)
# ---------------------------------------------------------------------------
# The quote as one of the game's title cards, in three stacked registers: the
# Astral Plane (white void, floating stone blocks, the Board's inverted black
# pyramid), the Oldest House (a concrete plinth carrying a black wayfinding
# sign), and the Hiss (the matched phrase in red with a stippled halo).
#
# **Blocks are flat geometry**: three polygons each (white top, lit side,
# shadow side) with plain unjittered 8x8 K+W stipples — a jitter would only
# add noise to machined smoothness.
#
# **The plinth is jittered** (or the committed concrete plate): an ordered tile
# alone reads as a screen door, a hash alone as sandpaper. Formwork seams and
# tie-holes make it read as brutalist concrete.
#
# **The Hiss is a red bloom on white**, reading as a spreading stain rather
# than light. ``ground`` is pinned to white so the halo cannot eat the prose.
#
# **The Board speaks in pairs**: the sign reads ``AUTHOR/ORIGIN`` and
# ``WORK/VESSEL`` over the row's own author and title.
#
# **No time surface beyond the matched phrase**; pinned byte-identical across
# every time by ``TestControlFrame``.
#
# Composed at the canonical 800x480 and NEAREST-downsampled for other sizes
# (``metro`` convention): everything is absolute panel coordinates.
# ---------------------------------------------------------------------------
_CONTROL_QUOTE_RECT = (130, 100, 670, 372)
_CONTROL_PLINTH_Y = 392
_CONTROL_SIGN_RECT = (40, 418, 760, 462)
_CONTROL_SEAL_CENTRE = (74, 440)
_CONTROL_SEAL_RADIUS = 14
# The Board: an inverted pyramid hanging from the top edge, apex down.
_CONTROL_BOARD = ((338, 0), (462, 0), (400, 84))
# Floating blocks as (top_vertex_x, top_vertex_y, side, height), clear of the
# quote rect; the four small ones are distant blocks beside the pyramid.
_CONTROL_BLOCKS = (
    (70, 18, 36, 36),
    (24, 108, 16, 18),
    (736, 26, 40, 40),
    (700, 146, 14, 14),
    (58, 232, 28, 30),
    (748, 250, 24, 48),
    (94, 322, 30, 30),
    (712, 316, 34, 34),
    (200, 34, 8, 8),
    (590, 24, 10, 10),
    (296, 46, 9, 9),
    (516, 50, 9, 9),
)
_CONTROL_ISO = (0.866, 0.5)          # isometric axis: (cos 30°, sin 30°)
_CONTROL_LIT_FACE = 0.25             # black density on the face toward the light
_CONTROL_SHADE_FACE = 0.56           # black density on the face away from it
_CONTROL_BOARD_FACE = 0.68           # the Board's lit face: darker than any block
_CONTROL_CONCRETE = (0.30, 0.46)     # black density at the plinth's top / bottom
_CONTROL_CONCRETE_JITTER = 12        # ± ranks of positional jitter on the 8x8 tile
_CONTROL_TIE_HOLES_Y = 404
_CONTROL_SEAMS_X = (200, 400, 600)
_CONTROL_HISS_RADIUS = 6
_CONTROL_HISS_CAP = 0.62
_CONTROL_HISS_GAMMA = 1.6
_CONTROL_TRACKING = 2
_CONTROL_SIGN_GAP = 24          # clear space between the name run and the credit column
_CONTROL_CREDIT_SIZE = 12
_CONTROL_CREDIT_FLOOR = 10      # below this a credit is ellipsised rather than shrunk further
# Hiss resonance: thin bands of the phrase echoed sideways as a half-density
# red stipple — (band top as a fraction of the phrase height, band height px,
# shift px). Echoes only; the phrase itself stays whole and legible.
_CONTROL_RESONANCE = ((0.18, 3, 9), (0.47, 2, -7), (0.74, 3, 6))
_CONTROL_RESONANCE_DENSITY = 0.5


def _control_fill_polygon(image: Image.Image, polygon, density: float) -> None:
    """Fill a polygon with a K+W ordered stipple at ``density`` black.

    A 1-bit polygon mask clips the fill (the ``_vitrail_fill_polygon`` shape),
    and the rank is read off ``BAYER_8x8`` at absolute coordinates so adjacent
    faces share one phase. Unjittered on purpose — see the section comment.
    """
    xs = [int(p[0]) for p in polygon]
    ys = [int(p[1]) for p in polygon]
    w, h = image.size
    x0, y0 = max(0, min(xs)), max(0, min(ys))
    x1, y1 = min(w, max(xs) + 1), min(h, max(ys) + 1)
    if x1 <= x0 or y1 <= y0:
        return
    mask = Image.new("1", (x1 - x0, y1 - y0), 0)
    ImageDraw.Draw(mask).polygon([(int(px) - x0, int(py) - y0) for px, py in polygon], fill=1)
    mp = mask.load()
    px = image.load()
    black, white = SPECTRA6["black"], SPECTRA6["white"]
    cut = density * 64
    for yy in range(y1 - y0):
        ay = y0 + yy
        row = BAYER_8x8[ay % 8]
        for xx in range(x1 - x0):
            if mp[xx, yy]:
                ax = x0 + xx
                px[ax, ay] = black if row[ax % 8] < cut else white


def _control_block_faces(top_x: int, top_y: int, side: int, height: int):
    """The three visible faces of an isometric block whose highest vertex is
    ``(top_x, top_y)``: top rhombus, left (lit) face, right (shadow) face."""
    ux, uy = _CONTROL_ISO
    dx, dy = side * ux, side * uy
    top = (top_x, top_y)
    right = (top_x + dx, top_y + dy)
    left = (top_x - dx, top_y + dy)
    near = (top_x, top_y + 2 * dy)
    top_face = [top, right, near, left]
    left_face = [left, near, (near[0], near[1] + height), (left[0], left[1] + height)]
    right_face = [near, right, (right[0], right[1] + height), (near[0], near[1] + height)]
    return top_face, left_face, right_face


def _control_outline(draw: ImageDraw.ImageDraw, polygon, width: int = 2) -> None:
    pts = [(int(round(x)), int(round(y))) for x, y in polygon]
    draw.line(pts + [pts[0]], fill=SPECTRA6["black"], width=width, joint="curve")


def _control_paint_blocks(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """The Astral Plane's floating stone: isometric blocks in the margins.

    Each block is painted (white top, light and dark stipple sides) then
    outlined, so overlapping blocks stay distinct.
    """
    for top_x, top_y, side, height in _CONTROL_BLOCKS:
        top_face, left_face, right_face = _control_block_faces(top_x, top_y, side, height)
        draw.polygon([(int(round(x)), int(round(y))) for x, y in top_face], fill=SPECTRA6["white"])
        _control_fill_polygon(image, left_face, _CONTROL_LIT_FACE)
        _control_fill_polygon(image, right_face, _CONTROL_SHADE_FACE)
        stroke = 1 if side < 12 else 2
        for face in (top_face, left_face, right_face):
            _control_outline(draw, face, width=stroke)


def _control_paint_board(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """The Board: an inverted black pyramid hanging from the top of the void.

    Two faces meet on a vertical edge under the apex (lit face a dense
    stipple, shadow face solid black), so it reads as a solid.
    """
    (ax, ay), (bx, by), (cx, cy) = _CONTROL_BOARD
    _control_fill_polygon(image, [(ax, ay), (cx, ay), (cx, cy)], _CONTROL_BOARD_FACE)
    draw.polygon([(cx, ay), (bx, by), (cx, cy)], fill=SPECTRA6["black"])
    _control_outline(draw, [(ax, ay), (bx, by), (cx, cy)], width=2)
    draw.line([(cx, ay), (cx, cy)], fill=SPECTRA6["black"], width=2)


def _control_paint_concrete_stipple(image: Image.Image, top: int) -> None:
    """Fallback plinth texture when the concrete plate asset is missing.

    Hash-jittered ordered dither (the ``bakelite`` moulding recipe) at a
    density that deepens toward the bottom edge. Reads as cast stone at a
    glance; the committed plate carries the board grain this cannot.
    """
    width, height = image.size
    px = image.load()
    black = SPECTRA6["black"]
    span = max(1, height - top)
    d0, d1 = _CONTROL_CONCRETE
    jitter = _CONTROL_CONCRETE_JITTER
    for y in range(top, height):
        cut = (d0 + (d1 - d0) * (y - top) / span) * 64
        row = BAYER_8x8[y % 8]
        for x in range(width):
            rank = row[x % 8] + (position_noise(x, y) % (2 * jitter + 1)) - jitter
            if rank < cut:
                px[x, y] = black


def _control_paint_plinth(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """The Oldest House: a band of board-formed concrete across the foot.

    Prefers the committed continuous-tone plate (``CONTROL_PLATE``), dithered
    to white+black at render time; falls back to the jittered stipple when the
    asset is missing. Formwork seams and tie-holes go on top either way.
    """
    width, height = image.size
    black = SPECTRA6["black"]
    top = _CONTROL_PLINTH_Y
    if height > top:
        plate = _load_dithered_plate(CONTROL_PLATE, width, height - top, palette=_CONCRETE_PALETTE)
        if plate is not None:
            image.paste(plate, (0, top))
        else:
            _control_paint_concrete_stipple(image, top)
    draw.line([(0, top), (width, top)], fill=black, width=2)
    for sx in _CONTROL_SEAMS_X:
        draw.line([(sx, top), (sx, height)], fill=black, width=1)
    for hx in range(100, width, 200):
        draw.ellipse((hx - 3, _CONTROL_TIE_HOLES_Y - 3, hx + 3, _CONTROL_TIE_HOLES_Y + 3), fill=black)


def _control_paint_seal(draw: ImageDraw.ImageDraw) -> None:
    """The Bureau's device on the sign: a ring around an inverted triangle."""
    cx, cy = _CONTROL_SEAL_CENTRE
    r = _CONTROL_SEAL_RADIUS
    white = SPECTRA6["white"]
    draw.ellipse((cx - r, cy - r, cx + r, cy + r), outline=white, width=2)
    tri = [(cx - 8, cy - 6), (cx + 8, cy - 6), (cx, cy + 8)]
    draw.polygon(tri, outline=white, fill=None)
    draw.ellipse((cx - 2, cy - 2, cx + 2, cy + 2), fill=white)


def _control_board_lines(quote_row: dict) -> list[str]:
    """Attribution in the Board's paired diction — labels only; values are the row's."""
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "")
    lines = []
    if author:
        lines.append(f"AUTHOR/ORIGIN: {author.upper()}")
    if title:
        lines.append(f"WORK/VESSEL: {title.upper()}")
    return lines


def _control_paint_sign(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The black wayfinding sign on the plinth: Bureau device and name at the
    left, the Board's attribution pairs right-aligned."""
    x0, y0, x1, y1 = _CONTROL_SIGN_RECT
    white = SPECTRA6["white"]
    draw.rectangle((x0, y0, x1, y1), fill=SPECTRA6["black"])
    _control_paint_seal(draw)
    # The sign is UI: Archivo stands in for the game's Akzidenz-Grotesk cut.
    name_font = load_font([ARCHIVO_BOLD, (OSWALD_VARIABLE, "Bold"), *META_FONT_BOLD_CANDIDATES], size=16)
    # Bold at 10 px too: Archivo Regular's hairlines shred on the black sign.
    sub_font = load_font([ARCHIVO_BOLD, (OSWALD_VARIABLE, "Medium"), *META_FONT_BOLD_CANDIDATES], size=10)
    text_x = _CONTROL_SEAL_CENTRE[0] + _CONTROL_SEAL_RADIUS + 12
    name_w = draw_tracked(draw, (text_x, y0 + 5), "FEDERAL BUREAU OF CONTROL", name_font, white,
                          tracking=_CONTROL_TRACKING)
    draw_tracked(draw, (text_x, y0 + 29), "THE OLDEST HOUSE", sub_font, white, tracking=3)

    # Budget the credit column off the name run actually painted, not a
    # constant: a face change would otherwise let long titles overprint it.
    credit_candidates = [ARCHIVO_BOLD, (OSWALD_VARIABLE, "Medium"), *META_FONT_BOLD_CANDIDATES]
    right = x1 - 14
    limit = right - (text_x + name_w + _CONTROL_SIGN_GAP)
    lines = _control_board_lines(quote_row)
    y = y0 + 6 if len(lines) > 1 else y0 + 14
    for text in lines:
        font, text = fit_text_to_width(draw, text, credit_candidates, _CONTROL_CREDIT_SIZE, limit,
                                       floor=_CONTROL_CREDIT_FLOOR, tracking=1)
        draw_tracked(draw, (right, y), text, font, white, tracking=1, anchor_right=True)
        y += 17


def _control_paint_resonance(image: Image.Image, hot: Image.Image) -> None:
    """The Hiss's signal tearing: a few thin bands of the matched phrase echoed
    sideways as a half-density red stipple.

    An *echo*, not a tear: moving the band would cut the time phrase. Only
    white pixels are written, so the echo never overwrites prose, the phrase
    or its bloom.
    """
    bbox = hot.getbbox()
    if bbox is None:
        return
    x0, y0, x1, y1 = bbox
    span = y1 - y0
    width, height = image.size
    hp, px = hot.load(), image.load()
    red, white = SPECTRA6["red"], SPECTRA6["white"]
    cut = _CONTROL_RESONANCE_DENSITY * 64
    for frac, band_h, shift in _CONTROL_RESONANCE:
        by0 = y0 + int(frac * span)
        for y in range(by0, min(height, by0 + band_h)):
            row = BAYER_8x8[y % 8]
            for x in range(x0, x1):
                if hp[x, y] <= 128:
                    continue
                tx = x + shift
                if 0 <= tx < width and px[tx, y] == white and row[tx % 8] < cut:
                    px[tx, y] = red


def _control_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """Black prose in the void; the matched phrase in Hiss red with a coral
    bloom stippled into the white around it."""
    prose, hot, _ = wrap_quote_into_masks(
        draw, image.size, quote_row, _CONTROL_QUOTE_RECT, theme="control",
        font_max=40, font_min=16, line_height_mult=1.22,
    )
    # Threshold the prose mask: a mid-grey antialiased edge would snap to red.
    image.paste(SPECTRA6["black"], (0, 0), prose.point(lambda v: 255 if v > 128 else 0))
    paint_neon_mask(
        image, hot, SPECTRA6["red"], SPECTRA6["red"],
        radius=_CONTROL_HISS_RADIUS, gamma=_CONTROL_HISS_GAMMA, cap=_CONTROL_HISS_CAP,
        ground=frozenset({SPECTRA6["white"]}), tile=BAYER_8x8,
    )
    _control_paint_resonance(image, hot)
    prose.close()
    hot.close()


def render_control_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """The Astral Plane title card (see the module section comment above).

    ``time_str`` is unused by design: the matched phrase carries the time.
    """
    del time_str
    image = Image.new("RGB", (800, 480), color=SPECTRA6["white"])
    draw = ImageDraw.Draw(image)
    _control_paint_plinth(image, draw)
    _control_paint_board(image, draw)
    _control_paint_blocks(image, draw)
    _control_paint_quote(image, draw, quote_row)
    _control_paint_sign(image, draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# observation — S.A.M.'s camera feed, after No Code's *Observation* (2019)
# ---------------------------------------------------------------------------
# The quote as seen by S.A.M., the AI of the Observation station orbiting
# Saturn: one camera feed with the AI's interface laid over it.
#
# * **The feed.** Black space, a seeded star field, and Saturn — a banded
#   disc shaded by a terminator, its blue-grey north polar cap carrying the
#   hexagonal jet stream, and the rings cast as a tilted annulus that passes
#   *behind* the planet on the far side and *in front* of it on the near side.
#   Titan is a small tangerine disc. Faint blue sensor noise, and three
#   tracking tears shear bands of the feed sideways.
# * **The anomaly.** Nested glowing hexagons (white core, blue bloom) below
#   the rings, boxed by a yellow tracking reticle.
# * **The HUD.** Camera-frame corner brackets, the S.A.M. identifier, a red
#   REC tally and the camera's designation across the top; an uplink meter
#   and a station schematic along the foot, the current camera's module lit.
# * **The quote is an audio log.** An opaque terminal panel on the left with
#   an inverted header naming the author as the log's source, the quote set
#   ragged-right in white Plex Mono, the matched phrase yellow with a
#   tangerine halo, a playback waveform, and the title as the file name.
#
# **Saturn's shading** is a *single* ``BAYER_8x8`` read partitioned three
# ways: the lowest ranks take black for the terminator and the rest split
# between the band's two inks in its own ratio (``pride``'s rule — a second
# read would drift the hue across the terminator instead of darkening it).
#
# **The time is the camera number, hour only** (``CAM 07`` reads as a feed);
# the frame is pinned byte-identical across the minutes of an hour by
# ``TestObservationFrame``. The hour also picks the lit schematic module.
#
# The log number and the waveform are seeded from ``_row_digest``, never the
# clock.
#
# Composed at the canonical 800x480 and NEAREST-downsampled for other sizes
# (``metro`` convention).
# ---------------------------------------------------------------------------
_OBSERVATION_PANEL = (26, 50, 436, 424)
_OBSERVATION_HEADER_H = 24
_OBSERVATION_QUOTE_RECT = (44, 92, 420, 346)
_OBSERVATION_WAVE_RECT = (44, 362, 420, 390)
_OBSERVATION_FILE_Y = 398
_OBSERVATION_SATURN = (636, 206, 108)       # centre x, centre y, radius
_OBSERVATION_TILT = 0.22                    # ring-plane rotation, radians
_OBSERVATION_RING_K = 0.36                  # ring ellipse minor/major = sin(pole tilt)
_OBSERVATION_LIGHT = (-0.62, -0.42, 0.66)   # sun direction (screen x, y, toward viewer)
# Saturn's bands, north to south, as (lower sin-latitude bound, major ink,
# minor ink, minor share): a blue polar cap, then mostly cream zones broken by
# thin gold and tangerine belts (saturated orange stripes read as a beach ball).
_OBSERVATION_BANDS = (
    (0.80, "blue", "white", 0.50),
    (0.68, "white", "yellow", 0.45),
    (0.58, "red", "yellow", 0.45),
    (0.36, "yellow", "white", 0.45),
    (0.26, "red", "yellow", 0.50),
    (0.10, "yellow", "white", 0.38),
    (-0.08, "white", "yellow", 0.40),
    (-0.18, "yellow", "red", 0.30),
    (-2.00, "yellow", "white", 0.45),
)
_OBSERVATION_HEX_LAT = 0.975                # sin(78 deg N) — the real hexagon's latitude
# Rings as (inner, outer radius in planet radii, major ink, minor ink,
# minor share, fill density). The Cassini division and Encke gap are the
# spaces between entries.
_OBSERVATION_RINGS = (
    (1.24, 1.52, "yellow", "white", 0.50, 0.26),   # C ring: faint
    (1.52, 1.94, "white", "yellow", 0.40, 0.92),   # B ring: the bright one
    (2.02, 2.16, "yellow", "white", 0.35, 0.66),   # A ring, inside Encke
    (2.19, 2.26, "yellow", "red", 0.30, 0.55),     # A ring, outside Encke
    (2.33, 2.35, "white", "white", 0.00, 0.45),    # F ring: a thread
)
_OBSERVATION_TITAN = (474, 96, 7)
_OBSERVATION_STAR_SEED = 0x0B5E
_OBSERVATION_STAR_COUNT = 190
# Tracking tears, as (top y, height, horizontal shift). Applied to the feed
# only, before the HUD, so a tear can never cut the quote.
_OBSERVATION_TEARS = ((150, 3, 11), (238, 2, -9), (300, 4, 15))
_OBSERVATION_ANOMALY = (548, 380, 22)       # centre x, centre y, outer hexagon radius
_OBSERVATION_MAP_RECT = (604, 422, 776, 466)
# Two cameras per module; the hour picks the camera, the camera picks the module.
_OBSERVATION_MODULES = ("HAB", "SCIENCE", "COMMS", "ENGINEERING", "AIRLOCK", "OBSERVATION")


def _observation_module_index(camera: int) -> int:
    return (camera - 1) // 2 % len(_OBSERVATION_MODULES)


def _observation_mix(rank: int, black: float, major, minor, share: float):
    """One ``BAYER_8x8`` rank, partitioned three ways: shade, then band mix.

    The lowest ``round(black * 64)`` ranks take black; the remainder splits
    between the band's two inks in its own ratio. One read, never two.
    """
    nb = int(round(black * 64))
    if rank < nb:
        return SPECTRA6["black"]
    return minor if (rank - nb) < share * (64 - nb) else major


def _observation_paint_stars(image: Image.Image) -> None:
    rng = random.Random(_OBSERVATION_STAR_SEED)
    px = image.load()
    width, height = image.size
    white, yellow, blue = SPECTRA6["white"], SPECTRA6["yellow"], SPECTRA6["blue"]
    for _ in range(_OBSERVATION_STAR_COUNT):
        x, y = rng.randrange(width), rng.randrange(height)
        roll = rng.random()
        ink = yellow if roll < 0.06 else blue if roll < 0.12 else white
        px[x, y] = ink
        if rng.random() < 0.09 and x + 1 < width and y + 1 < height:
            px[x + 1, y] = px[x, y + 1] = px[x + 1, y + 1] = white


def _observation_ring_frame(dx: float, dy: float):
    """Screen offset from Saturn's centre → ring-plane coordinates (u, v)."""
    c, s = math.cos(_OBSERVATION_TILT), math.sin(_OBSERVATION_TILT)
    return dx * c + dy * s, -dx * s + dy * c


def _observation_from_ring_frame(u: float, v: float):
    c, s = math.cos(_OBSERVATION_TILT), math.sin(_OBSERVATION_TILT)
    return u * c - v * s, u * s + v * c


def _observation_paint_saturn(image: Image.Image) -> None:
    """The planet: latitude bands, a lit limb and a terminator, one read per pixel."""
    cx, cy, r = _OBSERVATION_SATURN
    width, height = image.size
    px = image.load()
    k = _OBSERVATION_RING_K
    cos_phi = math.sqrt(1 - k * k)
    lx, ly, lz = _OBSERVATION_LIGHT
    norm = math.sqrt(lx * lx + ly * ly + lz * lz)
    lx, ly, lz = lx / norm, ly / norm, lz / norm
    inks = {name: SPECTRA6[name] for name in ("white", "yellow", "red", "blue")}
    for y in range(max(0, cy - r), min(height, cy + r + 1)):
        row = BAYER_8x8[y % 8]
        dy = y - cy
        for x in range(max(0, cx - r), min(width, cx + r + 1)):
            dx = x - cx
            d2 = dx * dx + dy * dy
            if d2 > r * r:
                continue
            z = math.sqrt(r * r - d2)
            u, v = _observation_ring_frame(dx, dy)
            # sin(latitude): north is -v, and the pole leans toward us by k.
            lat = (-v * cos_phi + z * k) / r
            lat += 0.018 * math.sin(u * 0.11 + lat * 9.0)       # band turbulence
            for upper, major, minor, share in _OBSERVATION_BANDS:
                if lat >= upper:
                    break
            lit = (dx * lx + dy * ly + z * lz) / r
            limb = z / r
            shade = 0.08 + max(0.0, 0.55 - lit) * 1.5 + (1 - limb) ** 3 * 0.35
            shade = min(0.94, shade)
            px[x, y] = _observation_mix(row[x % 8], shade, inks[major], inks[minor], share)


def _observation_paint_hexagon(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """Saturn's north-polar hexagon, projected onto the visible pole."""
    cx, cy, r = _OBSERVATION_SATURN
    k = _OBSERVATION_RING_K
    cos_phi = math.sqrt(1 - k * k)
    sin_lat = _OBSERVATION_HEX_LAT
    cos_lat = math.sqrt(1 - sin_lat * sin_lat)
    pole = (0.0, -cos_phi, k)
    e2 = (0.0, k, cos_phi)
    pts = []
    for i in range(7):
        a = math.radians(60 * i + 15)
        u = r * (sin_lat * pole[0] + cos_lat * math.cos(a))
        v = r * (sin_lat * pole[1] + cos_lat * math.sin(a) * e2[1])
        dx, dy = _observation_from_ring_frame(u, v)
        pts.append((cx + dx, cy + dy))
    draw.line([(round(x), round(y)) for x, y in pts], fill=SPECTRA6["blue"], width=2, joint="curve")


def _observation_paint_rings(image: Image.Image) -> None:
    """The ring system: behind the planet on the far side, over it on the near."""
    cx, cy, r = _OBSERVATION_SATURN
    width, height = image.size
    px = image.load()
    k = _OBSERVATION_RING_K
    outer = _OBSERVATION_RINGS[-1][1] * r
    reach_x = int(outer) + 2
    reach_y = int(outer * max(abs(math.sin(_OBSERVATION_TILT)), k)) + int(outer * k) + 4
    inks = {name: SPECTRA6[name] for name in ("white", "yellow", "red")}
    black = SPECTRA6["black"]
    for y in range(max(0, cy - reach_y), min(height, cy + reach_y + 1)):
        row = BAYER_8x8[y % 8]
        dy = y - cy
        for x in range(max(0, cx - reach_x), min(width, cx + reach_x + 1)):
            dx = x - cx
            u, v = _observation_ring_frame(dx, dy)
            rho = math.sqrt(u * u + (v / k) ** 2) / r
            if rho < _OBSERVATION_RINGS[0][0] or rho > _OBSERVATION_RINGS[-1][1]:
                continue
            on_disc = dx * dx + dy * dy <= r * r
            if on_disc and v < 0:
                continue                                    # far side, hidden by the planet
            # Over the disc the rings are translucent: an unlit tile cell and
            # a gap both leave the planet showing, rather than punching black.
            for inner, outer_r, major, minor, share, density in _OBSERVATION_RINGS:
                if inner <= rho < outer_r:
                    rank = row[x % 8]
                    if rank < density * 64:
                        px[x, y] = _observation_mix(rank, 0.0, inks[major], inks[minor], share)
                    elif not on_disc:
                        px[x, y] = black
                    break
            else:
                if not on_disc:
                    px[x, y] = black                        # Cassini division / Encke gap


def _observation_paint_titan(draw: ImageDraw.ImageDraw, image: Image.Image) -> None:
    """Titan: a small tangerine disc with a lit crescent of white haze."""
    tx, ty, tr = _OBSERVATION_TITAN
    px = image.load()
    red, yellow, white = SPECTRA6["red"], SPECTRA6["yellow"], SPECTRA6["white"]
    for y in range(ty - tr, ty + tr + 1):
        row = BAYER_8x8[y % 8]
        for x in range(tx - tr, tx + tr + 1):
            d2 = (x - tx) ** 2 + (y - ty) ** 2
            if d2 > tr * tr:
                continue
            rank = row[x % 8]
            haze = (x - tx) + (y - ty) < -tr * 0.9 and d2 > (tr - 2) ** 2
            px[x, y] = white if haze else (yellow if rank < 24 else red)


def _observation_paint_noise(image: Image.Image) -> None:
    """Faint blue sensor noise on the black of the feed — every third row."""
    width, height = image.size
    px = image.load()
    black, blue = SPECTRA6["black"], SPECTRA6["blue"]
    for y in range(0, height, 3):
        for x in range(width):
            if px[x, y] == black and position_noise(x, y) % 16 == 0:
                px[x, y] = blue


def _observation_paint_tears(image: Image.Image) -> None:
    """Tracking tears: thin bands of the feed sheared sideways (feed only)."""
    width, height = image.size
    for top, band_h, shift in _OBSERVATION_TEARS:
        if top + band_h > height:
            continue
        band = image.crop((0, top, width, top + band_h))
        image.paste(SPECTRA6["black"], (0, top, width, top + band_h))
        image.paste(band, (shift, top))


def _observation_hex_points(cx: float, cy: float, radius: float, rot: float = 0.0):
    return [(cx + radius * math.cos(math.radians(60 * i + 30 + rot)),
             cy + radius * math.sin(math.radians(60 * i + 30 + rot))) for i in range(6)]


def _observation_paint_anomaly(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """The anomaly: nested hexagons, white-cored, blooming blue into space."""
    ax, ay, ar = _OBSERVATION_ANOMALY
    mask = Image.new("L", image.size, 0)
    md = ImageDraw.Draw(mask)
    for radius, rot, stroke in ((ar, 0, 3), (ar * 0.62, 30, 2), (ar * 0.3, 0, 2)):
        pts = [(round(x), round(y)) for x, y in _observation_hex_points(ax, ay, radius, rot)]
        md.line(pts + [pts[0]], fill=255, width=stroke, joint="curve")
    for x, y in _observation_hex_points(ax, ay, ar):
        md.line([(ax, ay), (round(x), round(y))], fill=255, width=1)
    paint_neon_mask(image, mask, SPECTRA6["white"], SPECTRA6["blue"],
                    radius=6, gamma=1.3, cap=0.78,
                    ground=frozenset({SPECTRA6["black"]}), tile=BAYER_8x8)
    mask.close()


def _observation_brackets(draw, box, length: int, fill, width: int) -> None:
    """Four L-shaped corner brackets — the camera-frame idiom."""
    x0, y0, x1, y1 = box
    for (x, y, sx, sy) in ((x0, y0, 1, 1), (x1, y0, -1, 1), (x0, y1, 1, -1), (x1, y1, -1, -1)):
        draw.line([(x, y + sy * length), (x, y), (x + sx * length, y)], fill=fill, width=width)


def _observation_paint_tracker(draw: ImageDraw.ImageDraw) -> None:
    """A yellow tracking reticle round the anomaly, with S.A.M.'s label."""
    ax, ay, ar = _OBSERVATION_ANOMALY
    yellow, white = SPECTRA6["yellow"], SPECTRA6["white"]
    pad = ar + 14
    _observation_brackets(draw, (ax - pad, ay - pad, ax + pad, ay + pad), 9, yellow, 2)
    for x0, x1 in ((ax - pad - 12, ax - pad - 3), (ax + pad + 3, ax + pad + 12)):
        draw.line([(x0, ay), (x1, ay)], fill=yellow, width=1)
    label = load_font([PLEXMONO_SEMIBOLD, SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=11)
    tx = ax + pad + 16
    draw.text((tx, ay - 20), "UNIDENTIFIED OBJECT", font=label, fill=white)
    draw.text((tx, ay - 5), "TRACKING", font=label, fill=yellow)
    draw.text((tx + draw.textlength("TRACKING ", font=label), ay - 5), "— NO DATA", font=label, fill=white)


def _observation_paint_chrome(image: Image.Image, draw: ImageDraw.ImageDraw, camera: int) -> None:
    """Camera brackets, the S.A.M. identifier, REC tally and camera designation."""
    width, height = image.size
    white, red, yellow = SPECTRA6["white"], SPECTRA6["red"], SPECTRA6["yellow"]
    _observation_brackets(draw, (10, 10, width - 11, height - 11), 24, white, 2)
    big = load_font([PLEXMONO_BOLD, SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=17)
    small = load_font([PLEXMONO_SEMIBOLD, SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=11)
    draw.text((42, 16), "S.A.M.", font=big, fill=white)
    draw.text((42 + draw.textlength("S.A.M. ", font=big), 21),
              "SYSTEMS ADMINISTRATION & MAINTENANCE", font=small, fill=white)
    module = _OBSERVATION_MODULES[_observation_module_index(camera)]
    cam = f"CAM {camera:02d} · {module}"
    right = width - 42
    cam_w = draw.textlength(cam, font=big)
    draw.text((right - cam_w, 16), cam, font=big, fill=yellow)
    rec_w = draw.textlength("REC", font=small)
    rx = right - cam_w - 18 - rec_w
    draw.text((rx, 21), "REC", font=small, fill=red)
    draw.ellipse((rx - 14, 22, rx - 5, 31), fill=red)


def _observation_paint_uplink(draw: ImageDraw.ImageDraw) -> None:
    """Foot-left: the uplink meter — three of five bars, and a red DEGRADED."""
    white, green, red = SPECTRA6["white"], SPECTRA6["green"], SPECTRA6["red"]
    small = load_font([PLEXMONO_SEMIBOLD, SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=11)
    x, base = 42, 460
    draw.text((x, base - 14), "UPLINK / EARTH", font=small, fill=white)
    bx = x + draw.textlength("UPLINK / EARTH ", font=small) + 4
    for i in range(5):
        h = 5 + i * 3
        box = (bx + i * 9, base - h, bx + i * 9 + 5, base)
        if i < 3:
            draw.rectangle(box, fill=green)
        else:
            draw.rectangle(box, outline=white, width=1)
    draw.text((bx + 5 * 9 + 10, base - 14), "DEGRADED", font=small, fill=red)


def _observation_paint_map(draw: ImageDraw.ImageDraw, camera: int) -> None:
    """Foot-right: the station schematic, the current camera's module lit."""
    x0, y0, x1, y1 = _OBSERVATION_MAP_RECT
    white, yellow, black = SPECTRA6["white"], SPECTRA6["yellow"], SPECTRA6["black"]
    tiny = load_font([PLEXMONO_SEMIBOLD, SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=9)
    draw.text((x0, y0 - 12), "STATION MAP", font=tiny, fill=white)
    spine_y = (y0 + y1) // 2 + 4
    draw.line([(x0 + 6, spine_y), (x1 - 6, spine_y)], fill=white, width=1)
    lit = _observation_module_index(camera)
    n = len(_OBSERVATION_MODULES)
    step = (x1 - x0 - 12) / (n - 1)
    for i in range(n):
        mx = round(x0 + 6 + i * step)
        above = i % 2 == 0
        top, bottom = (spine_y - 18, spine_y - 5) if above else (spine_y + 5, spine_y + 18)
        draw.line([(mx, spine_y), (mx, top if not above else bottom)], fill=white, width=1)
        box = (mx - 9, top, mx + 9, bottom)
        if i == lit:
            draw.rectangle(box, fill=yellow, outline=yellow)
        else:
            draw.rectangle(box, fill=black, outline=white, width=1)
    draw.ellipse((x1 - 6 - 2, spine_y - 2, x1 - 6 + 2, spine_y + 2), fill=white)


def _observation_log_header(quote_row: dict) -> str:
    author = (quote_row.get("author") or "").strip()
    return f"AUDIO LOG — {author.upper()}" if author else "AUDIO LOG — UNATTRIBUTED"


def _observation_paint_panel(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The audio-log terminal: header, transcript, waveform, file name."""
    x0, y0, x1, y1 = _OBSERVATION_PANEL
    white, black, yellow, red, green = (SPECTRA6[n] for n in ("white", "black", "yellow", "red", "green"))
    draw.rectangle((x0, y0, x1, y1), fill=black, outline=white, width=1)
    _observation_brackets(draw, (x0 - 3, y0 - 3, x1 + 3, y1 + 3), 14, white, 3)

    # Header: inverted strip, log source left, recording number right.
    hy1 = y0 + _OBSERVATION_HEADER_H
    draw.rectangle((x0, y0, x1, hy1), fill=white)
    digest = _row_digest(quote_row)
    log_no = f"#{digest % 10000:04d}"
    chrome = [PLEXMONO_BOLD, SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES]
    num_font = load_font(chrome, size=12)
    num_w = draw.textlength(log_no, font=num_font)
    draw.text((x1 - 10 - num_w, y0 + 5), log_no, font=num_font, fill=black)
    font, text = fit_text_to_width(draw, _observation_log_header(quote_row), chrome, 13,
                                   x1 - x0 - 34 - num_w, floor=10)
    draw.text((x0 + 10, y0 + 5), text, font=font, fill=black)

    # Transcript: white prose, the matched phrase yellow in a tangerine halo.
    prose, hot, _ = wrap_quote_into_masks(
        draw, image.size, quote_row, _OBSERVATION_QUOTE_RECT, theme="observation",
        font_max=36, font_min=13, line_height_mult=1.34, align="left",
    )
    image.paste(white, (0, 0), prose.point(lambda v: 255 if v > 128 else 0))
    paint_neon_mask(
        image, hot, yellow, red,
        radius=3, gamma=1.8, cap=0.5,
        ground=frozenset({black}), tile=BAYER_8x8,
        glow_minor=yellow, glow_minor_share=0.375,
    )
    prose.close()
    hot.close()

    # Playback waveform: green bars, a yellow playhead, played part solid.
    wx0, wy0, wx1, wy1 = _OBSERVATION_WAVE_RECT
    mid = (wy0 + wy1) // 2
    rng = random.Random(digest)
    head = wx0 + int((wx1 - wx0) * (0.35 + 0.5 * rng.random()))
    draw.line([(wx0, mid), (wx1, mid)], fill=green, width=1)
    for x in range(wx0, wx1, 4):
        env = 0.35 + 0.65 * abs(math.sin((x - wx0) * 0.045 + rng.random() * 0.6))
        amp = max(1, int((wy1 - wy0) / 2 * env * (0.4 + 0.6 * rng.random())))
        if x < head:
            draw.rectangle((x, mid - amp, x + 1, mid + amp), fill=green)
        else:
            draw.line([(x, mid - amp), (x, mid + amp)], fill=green, width=1)
    draw.line([(head, wy0 - 3), (head, wy1 + 3)], fill=yellow, width=2)

    # File line: the title as the recording's file name.
    title = (quote_row.get("title") or fallback_title(quote_row) or "").strip()
    meta = [PLEXMONO_MEDIUM, SPACEMONO_REGULAR, *META_FONT_CANDIDATES]
    label_font = load_font(chrome, size=11)
    draw.text((x0 + 18, _OBSERVATION_FILE_Y), "FILE", font=label_font, fill=yellow)
    fx = x0 + 18 + draw.textlength("FILE  ", font=label_font)
    if title:
        font, text = fit_text_to_width(draw, title.upper(), meta, 11, x1 - 14 - fx, floor=9)
        draw.text((fx, _OBSERVATION_FILE_Y), text, font=font, fill=white)


def render_observation_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """S.A.M.'s camera feed of Saturn (see the module section comment above)."""
    camera = _clock_hour12(time_str)
    image = Image.new("RGB", (800, 480), color=SPECTRA6["black"])
    draw = ImageDraw.Draw(image)
    _observation_paint_stars(image)
    _observation_paint_saturn(image)
    _observation_paint_hexagon(image, draw)
    _observation_paint_rings(image)
    _observation_paint_titan(draw, image)
    _observation_paint_noise(image)
    _observation_paint_tears(image)
    _observation_paint_anomaly(image, draw)
    _observation_paint_tracker(draw)
    _observation_paint_chrome(image, draw, camera)
    _observation_paint_uplink(draw)
    _observation_paint_map(draw, camera)
    _observation_paint_panel(image, draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# furies — Francis Bacon, *Three Studies for Figures at the Base of a
# Crucifixion* (1944)
# ---------------------------------------------------------------------------
# The triptych hung under glass in gilt frames on a dark gallery wall, with
# the quote beneath it as wall text:
#
# * **Left.** A hunched, draped figure on a table, its head bowed under a
#   hanging mass of dark hair.
# * **Centre.** A long-necked figure on a pedestal, eyes bound by a white
#   bandage, the lower face opened into a mouth of teeth.
# * **Right.** A body on stalk legs rooted in a tuft of grass, its neck
#   stretched horizontal to end in a screaming mouth.
#
# All three stand on flat cadmium orange with a few thin perspective lines.
#
# **The painting is built in memory as separate paint layers** (ground, lines,
# flesh, pedestal, grass), each with its own soft alpha, then:
#
# 1. **Dragged.** ``_furies_drag`` pulls each figure along a vector in fading,
#    striated steps (noise held constant *along* the drag, like bristles), so
#    the trail reads as a smear, not a motion blur; the core is carried at
#    partial strength so the form itself is smeared.
# 2. **Separated per layer against its own inks** (Floyd–Steinberg): ground
#    red/yellow, flesh white/black/red, grass green/yellow/black. One pass over
#    the flattened image would scatter green into grey flesh and white into
#    the orange.
# 3. **Composited through a dithered alpha** (``BAYER_8x8`` threshold, not a
#    50% cut), so smeared edges interpenetrate instead of reading as stickers.
#
# Flesh is modelled under an upper-left light (``_shade_silhouette``) and given
# brush marks before the drag so they smear with it. Mouths and the bandage are
# painted *after* the drag — the focal points stay sharp.
#
# Each panel sits in a bevelled gilt moulding, and one diagonal window
# reflection crosses all three panes as a sparse white stipple.
#
# **The matched phrase is the scream**: wall text in white Libre Franklin, the
# phrase in yellow-major orange (``_FURIES_PHRASE_RED_RANKS``) with a red smear
# dragged off it. The trail is written only onto the black wall, so it never
# cuts a prose glyph.
#
# ``time_str`` is ``del``-asserted (a painting carries no clock). The triptych
# is quote-independent and deterministic, so it is composed once and cached.
#
# Composed at the canonical 800x480 and NEAREST-downsampled for other sizes
# (``metro`` convention).
# ---------------------------------------------------------------------------
_FURIES_PANEL_W, _FURIES_PANEL_H = 212, 268
_FURIES_PANEL_Y = 24
_FURIES_PANEL_XS = (60, 294, 528)
_FURIES_FRAME = 8                          # gilt moulding width
_FURIES_QUOTE_RECT = (44, 318, 756, 440)
_FURIES_BYLINE_BASELINE = 464

_FURIES_ORANGE = (238, 116, 20)
_FURIES_FLESH = (170, 164, 166)
_FURIES_FLESH_LIGHT = (250, 246, 240)
_FURIES_FLESH_SHADOW = (48, 38, 42)
_FURIES_LINE = (104, 34, 14)               # the thin perspective lines, R+K
_FURIES_HAIR = (38, 28, 28)
_FURIES_MAW = (76, 12, 12)
_FURIES_THROAT = (18, 0, 0)
_FURIES_TOOTH = (252, 252, 250)

# The ground separates against red + yellow only: with black available, FS
# drops black specks into the deeper scumble and the orange goes olive. The
# perspective lines, which need black, are their own R+K layer.
_FURIES_GROUND_INKS = [SPECTRA6["red"], SPECTRA6["yellow"]]
_FURIES_LINE_INKS = [SPECTRA6["red"], SPECTRA6["black"]]
_FURIES_FLESH_INKS = [SPECTRA6["white"], SPECTRA6["black"], SPECTRA6["red"]]
_FURIES_GRASS_INKS = [SPECTRA6["green"], SPECTRA6["yellow"], SPECTRA6["black"]]

# The window reflection, as (intercept, half-width, peak density) of bands
# along y + slope * x = intercept — one shallow diagonal across all three panes.
_FURIES_GLARE_SLOPE = 0.28
_FURIES_GLARE = ((252, 9, 0.16), (290, 24, 0.07))

# The matched phrase's orange: ranks of 64 given to red (the rest yellow);
# 24/64 reads as cadmium on black where an even mix goes rust. Then the smear's
# density relative to its own alpha.
_FURIES_PHRASE_RED_RANKS = 24
_FURIES_SMEAR_STRENGTH = 0.7

_FURIES_TRIPTYCH_CACHE: dict = {}


def _furies_tube(draw: ImageDraw.ImageDraw, points, w0: float, w1: float, fill=255) -> None:
    """A neck or a limb: a spline swept at a width tapering ``w0`` → ``w1``."""
    path = _catmull_rom(points, closed=False, samples=8)
    left, right = [], []
    last = len(path) - 1
    for i, (x, y) in enumerate(path):
        ax, ay = path[max(i - 1, 0)]
        bx, by = path[min(i + 1, last)]
        length = math.hypot(bx - ax, by - ay) or 1.0
        nx, ny = (ay - by) / length, (bx - ax) / length
        half = (w0 + (w1 - w0) * i / last) / 2
        left.append((x + nx * half, y + ny * half))
        right.append((x - nx * half, y - ny * half))
    draw.polygon(left + right[::-1], fill=fill)


def _furies_dithered_alpha(alpha: Image.Image) -> Image.Image:
    """A soft alpha thresholded against the ordered tile: a smeared edge
    becomes a stippled interpenetration of the two layers, not a hard cut."""
    return ImageChops.subtract(alpha, _bayer_threshold_field(alpha.size)).point(lambda v: 255 if v else 0)


def _furies_noise(size, seed: int, scale: int, amp: float) -> Image.Image:
    """Low-frequency value noise centred on 128 — a tiny seeded grid upscaled
    BICUBIC, so the ground's scumble is C-speed and byte-deterministic."""
    rng = random.Random(seed)
    gw, gh = size[0] // scale + 2, size[1] // scale + 2
    small = Image.new("L", (gw, gh))
    small.putdata([int(128 + rng.uniform(-amp, amp)) for _ in range(gw * gh)])
    return small.resize(size, Image.BICUBIC)


def _furies_striations(size, angle: float, seed: int) -> Image.Image:
    """Bristle rows for a drag along ``angle``: noise held constant along the
    drag direction and stepping across it, like the hairs of a loaded brush."""
    rng = random.Random(seed)
    n = int(math.hypot(*size)) + 4
    values, v = [], rng.uniform(90, 255)
    for _ in range(n):
        if rng.random() < 0.35:
            v = rng.uniform(90, 255)
        values.append(int(v))
    column = Image.new("L", (1, n))
    column.putdata(values)
    square = column.resize((n, n), Image.NEAREST).rotate(-math.degrees(angle), resample=Image.NEAREST)
    left, top = (n - size[0]) // 2, (n - size[1]) // 2
    return square.crop((left, top, left + size[0], top + size[1]))


def _furies_drag(rgb: Image.Image, alpha: Image.Image, dx: int, dy: int, *, steps: int,
                 decay: float, seed: int, keep: float = 0.9) -> tuple[Image.Image, Image.Image]:
    """Drag wet paint along ``(dx, dy)``.

    Walks from the far end of the trail back to the figure, pasting shifted
    copies whose alpha fades by ``decay`` per step, modulated by the bristle
    striations. The figure goes down last at ``keep`` strength so the trail
    shows through it. Returns the new colour layer and alpha.
    """
    striations = _furies_striations(rgb.size, math.atan2(dy, dx), seed)
    out_rgb = Image.new("RGB", rgb.size, (0, 0, 0))
    out_alpha = Image.new("L", rgb.size, 0)
    for i in range(steps, 0, -1):
        weight = decay ** i
        sx, sy = round(dx * i / steps), round(dy * i / steps)
        step_alpha = ImageChops.multiply(
            _shift_no_wrap(alpha, sx, sy).point(lambda v, w=weight: int(v * w)), striations)
        out_rgb.paste(_shift_no_wrap(rgb, sx, sy), (0, 0), step_alpha)
        out_alpha = ImageChops.lighter(out_alpha, step_alpha)
    core = alpha.point(lambda v: int(v * keep))
    out_rgb.paste(rgb, (0, 0), core)
    return out_rgb, ImageChops.lighter(out_alpha, core)


def _furies_brushwork(rgb: Image.Image, mask: Image.Image, seed: int, *, count: int = 26,
                      direction: float = 0.0) -> None:
    """Curved brush marks inside a silhouette — light and dark greys and a
    few pink scumbles swept roughly along ``direction``. Painted before the
    drag so the marks smear with the flesh; the silhouette's alpha clips them."""
    box = mask.getbbox()
    if box is None:
        return
    rng = random.Random(seed)
    draw = ImageDraw.Draw(rgb)
    x0, y0, x1, y1 = box
    tones = ((236, 232, 228), (214, 208, 208), (128, 116, 120), (96, 84, 88), (206, 150, 150))
    for i in range(count):
        cx, cy = rng.uniform(x0, x1 - 1), rng.uniform(y0, y1 - 1)
        angle = direction + rng.uniform(-0.9, 0.9)
        length, bend = rng.uniform(14, 34), rng.uniform(-8, 8)
        width = rng.choice((2, 3, 4))
        if not mask.getpixel((int(cx), int(cy))):
            continue
        ux, uy = math.cos(angle) * length / 2, math.sin(angle) * length / 2
        stroke = [(cx - ux, cy - uy), (cx - math.sin(angle) * bend, cy + math.cos(angle) * bend),
                  (cx + ux, cy + uy)]
        draw.line(_catmull_rom(stroke, closed=False), fill=tones[i % len(tones)], width=width)


def _furies_ground(seed: int) -> Image.Image:
    """Cadmium orange on the rough side of the board: a scumble of warmer and
    deeper patches, and a vignette that browns toward the edges."""
    size = (_FURIES_PANEL_W, _FURIES_PANEL_H)
    img = Image.new("RGB", size, _FURIES_ORANGE)
    noise = _furies_noise(size, seed, 24, 24)
    img = Image.composite(Image.new("RGB", size, (246, 140, 28)), img,
                          noise.point(lambda v: max(0, v - 128) * 2))
    img = Image.composite(Image.new("RGB", size, (220, 88, 14)), img,
                          noise.point(lambda v: max(0, 128 - v) * 2))
    vignette = Image.new("L", size, 0)
    vd = ImageDraw.Draw(vignette)
    for i in range(36):
        vd.rectangle((i, i, size[0] - 1 - i, size[1] - 1 - i), outline=int(80 * (1 - i / 36) ** 2))
    img = Image.composite(Image.new("RGB", size, (180, 56, 12)), img, vignette)
    # Board grain: FS over a flat colour settles into vertical worms; a seeded
    # per-pixel jitter (``randbytes``; ``effect_noise`` is unseeded) breaks them.
    grain = _white_noise(size[0], size[1], seed * 7919)
    img = Image.composite(Image.new("RGB", size, (255, 160, 40)), img, grain.point(lambda v: max(0, v - 200)))
    return Image.composite(Image.new("RGB", size, (236, 84, 12)), img, grain.point(lambda v: max(0, 55 - v)))


def _furies_teeth(draw: ImageDraw.ImageDraw, x0: int, x1: int, y: int, step: int, down: bool) -> None:
    """A row of small triangular teeth hanging from (or rising to) ``y``."""
    depth = 5 if down else -4
    for tx in range(x0, x1, step):
        draw.polygon([(tx, y), (tx + step - 1, y), (tx + (step - 1) // 2, y + depth)], fill=_FURIES_TOOTH)


def _furies_ink(colour) -> Image.Image:
    """A flat continuous-tone colour at panel size — a layer's paint when its
    shape lives entirely in its alpha."""
    return Image.new("RGB", (_FURIES_PANEL_W, _FURIES_PANEL_H), colour)


def _furies_layer() -> Image.Image:
    return Image.new("L", (_FURIES_PANEL_W, _FURIES_PANEL_H), 0)


def _furies_left_panel() -> list:
    """The hunched, draped figure on a table, hair hanging over its face."""
    ground = _furies_ground(11)
    lines = _furies_layer()
    d = ImageDraw.Draw(lines)
    d.line((0, 206, _FURIES_PANEL_W, 198), fill=255, width=1)          # floor
    d.line((36, 176, 176, 176), fill=255, width=2)                      # table front
    d.line((56, 166, 194, 166), fill=255, width=1)                      # table back
    d.line((36, 176, 56, 166), fill=255, width=1)
    d.line((176, 176, 194, 166), fill=255, width=1)
    for x, top, bottom in ((44, 177, 250), (170, 177, 250), (190, 167, 236)):
        d.line((x, top, x, bottom), fill=255, width=2)
    mask = _furies_layer()
    md = ImageDraw.Draw(mask)
    md.polygon(_catmull_rom([(50, 176), (52, 140), (66, 108), (92, 86), (114, 90), (126, 78),
                               (150, 86), (166, 108), (170, 140), (176, 176)]), fill=255)
    md.polygon(_catmull_rom([(140, 112), (166, 104), (184, 124), (182, 150), (164, 160),
                               (144, 146)]), fill=255)
    _furies_tube(md, [(128, 128), (138, 152), (136, 176)], 14, 9)
    flesh = _shade_silhouette(mask, _FURIES_FLESH, _FURIES_FLESH_LIGHT, _FURIES_FLESH_SHADOW)
    _furies_brushwork(flesh, mask, 41, direction=-0.5)
    fd = ImageDraw.Draw(flesh)
    fd.polygon(_catmull_rom([(142, 110), (166, 102), (186, 122), (184, 160), (176, 176),
                               (168, 150), (160, 164), (156, 136), (146, 130)]), fill=_FURIES_HAIR)
    fd.line(_catmull_rom([(66, 150), (92, 118), (124, 104), (150, 108)], closed=False),
            fill=(118, 100, 104), width=2)
    fd.line(_catmull_rom([(110, 176), (116, 150), (134, 132)], closed=False), fill=(120, 104, 108), width=2)
    flesh, alpha = _furies_drag(flesh, mask, 10, 6, steps=8, decay=0.8, seed=21)
    return [(ground, None, _FURIES_GROUND_INKS), (_furies_ink(_FURIES_LINE), lines, _FURIES_LINE_INKS),
            (flesh, alpha, _FURIES_FLESH_INKS)]


def _furies_centre_panel() -> list:
    """The bandaged figure on its pedestal, the lower face opened into teeth."""
    ground = _furies_ground(12)
    lines = _furies_layer()
    d = ImageDraw.Draw(lines)
    d.line((0, 210, _FURIES_PANEL_W, 204), fill=255, width=1)
    d.line((0, 40, 60, 90), fill=255, width=1)
    d.line((_FURIES_PANEL_W, 36, 156, 88), fill=255, width=1)
    pedestal = _furies_layer()
    pd = ImageDraw.Draw(pedestal)
    pd.rectangle((84, 190, 132, 248), fill=255)
    pd.ellipse((84, 184, 132, 196), fill=255)
    pd.ellipse((84, 242, 132, 254), fill=255)
    stone = _shade_silhouette(pedestal, (70, 58, 56), (140, 120, 110), (20, 14, 14))
    mask = _furies_layer()
    md = ImageDraw.Draw(mask)
    md.polygon(_catmull_rom([(70, 190), (64, 160), (74, 128), (100, 118), (128, 128), (140, 158),
                               (134, 190)]), fill=255)
    _furies_tube(md, [(106, 132), (100, 104), (112, 80), (136, 74)], 30, 22)
    md.polygon(_catmull_rom([(122, 72), (148, 58), (176, 70), (180, 98), (168, 118), (140, 122),
                               (124, 104)]), fill=255)
    flesh = _shade_silhouette(mask, _FURIES_FLESH, _FURIES_FLESH_LIGHT, _FURIES_FLESH_SHADOW)
    _furies_brushwork(flesh, mask, 42, direction=1.2)
    fd = ImageDraw.Draw(flesh)
    fd.line(_catmull_rom([(78, 150), (96, 176), (126, 170)], closed=False), fill=(120, 104, 108), width=2)
    fd.line(_catmull_rom([(92, 126), (110, 140), (128, 136)], closed=False), fill=(130, 114, 118), width=1)
    flesh, alpha = _furies_drag(flesh, mask, -8, 10, steps=7, decay=0.8, seed=22)
    # The bandage and the mouth go down after the drag: the focal points.
    fd, ad = ImageDraw.Draw(flesh), ImageDraw.Draw(alpha)
    bandage = [(118, 70), (178, 76), (178, 90), (118, 86)]
    fd.polygon(bandage, fill=(248, 246, 244))
    ad.polygon(bandage, fill=255)
    fd.line((124, 78, 172, 83), fill=(170, 160, 160), width=1)
    fd.ellipse((132, 94, 170, 116), fill=_FURIES_MAW)
    fd.ellipse((140, 100, 162, 114), fill=_FURIES_THROAT)
    _furies_teeth(fd, 136, 168, 96, 4, down=True)
    _furies_teeth(fd, 140, 162, 115, 4, down=False)
    return [(ground, None, _FURIES_GROUND_INKS), (_furies_ink(_FURIES_LINE), lines, _FURIES_LINE_INKS),
            (stone, pedestal, _FURIES_FLESH_INKS),
            (flesh, alpha, _FURIES_FLESH_INKS)]


def _furies_right_panel() -> list:
    """The stalk-legged body in its tuft of grass, neck out, mouth screaming."""
    ground = _furies_ground(13)
    lines = _furies_layer()
    d = ImageDraw.Draw(lines)
    d.line((0, 196, _FURIES_PANEL_W, 206), fill=255, width=1)
    d.line((150, 0, 150, 60), fill=255, width=1)
    grass = _furies_layer()
    gd = ImageDraw.Draw(grass)
    blades = Image.new("RGB", grass.size, (40, 140, 40))
    bd = ImageDraw.Draw(blades)
    rng = random.Random(31)
    gd.ellipse((110, 214, 206, 244), fill=255)
    for _ in range(70):
        x, h, lean = rng.uniform(112, 204), rng.uniform(8, 26), rng.uniform(-6, 6)
        gd.line((x, 232, x + lean, 232 - h), fill=255, width=2)
        bd.line((x, 232, x + lean, 232 - h), fill=(90, 190, 40), width=1)
    mask = _furies_layer()
    md = ImageDraw.Draw(mask)
    md.polygon(_catmull_rom([(122, 128), (146, 104), (182, 106), (198, 136), (190, 170), (160, 180),
                               (130, 164)]), fill=255)
    _furies_tube(md, [(136, 140), (104, 128), (78, 122), (58, 118)], 30, 22)
    md.polygon(_catmull_rom([(18, 104), (40, 86), (68, 92), (76, 118), (66, 146), (34, 150),
                               (14, 132)]), fill=255)
    _furies_tube(md, [(146, 170), (142, 196), (146, 228)], 9, 4)
    _furies_tube(md, [(176, 172), (180, 200), (176, 228)], 9, 4)
    flesh = _shade_silhouette(mask, _FURIES_FLESH, _FURIES_FLESH_LIGHT, _FURIES_FLESH_SHADOW)
    _furies_brushwork(flesh, mask, 43, direction=0.2)
    flesh, alpha = _furies_drag(flesh, mask, 12, -4, steps=8, decay=0.8, seed=23)
    fd, ad = ImageDraw.Draw(flesh), ImageDraw.Draw(alpha)
    fd.ellipse((10, 104, 58, 144), fill=_FURIES_MAW)      # the scream opens the whole face
    ad.ellipse((10, 104, 58, 144), fill=255)
    fd.ellipse((18, 112, 50, 138), fill=_FURIES_THROAT)
    _furies_teeth(fd, 16, 52, 106, 5, down=True)
    _furies_teeth(fd, 20, 48, 142, 5, down=False)
    return [(ground, None, _FURIES_GROUND_INKS), (_furies_ink(_FURIES_LINE), lines, _FURIES_LINE_INKS),
            (blades, grass, _FURIES_GRASS_INKS),
            (flesh, alpha, _FURIES_FLESH_INKS)]


def _furies_compose_panel(layers: list) -> Image.Image:
    """Separate each paint layer against its own inks, then stack them through
    their dithered alphas. The first layer is the ground and has no alpha."""
    out = None
    for rgb, alpha, inks in layers:
        separated = dither_image_to_palette(rgb, inks)
        out = separated if alpha is None else Image.composite(separated, out, _furies_dithered_alpha(alpha))
    return out


def _furies_triptych() -> list:
    """The three separated panels, composed once per process."""
    cached = _FURIES_TRIPTYCH_CACHE.get("panels")
    if cached is None:
        cached = [_furies_compose_panel(build()) for build in
                  (_furies_left_panel, _furies_centre_panel, _furies_right_panel)]
        _FURIES_TRIPTYCH_CACHE["panels"] = cached
    return cached


def _furies_paint_triptych(image: Image.Image) -> None:
    for x, panel in zip(_FURIES_PANEL_XS, _furies_triptych()):
        image.paste(panel, (x, _FURIES_PANEL_Y))


def _furies_paint_frames(image: Image.Image) -> None:
    """Bevelled gilt mouldings: gold (Y-major Y+R) on the flat, a Y+W lit face
    on the top and left, an R+K shaded face on the bottom and right, and a
    black rebate where the moulding meets the board."""
    px = image.load()
    red, yellow, white, black = (SPECTRA6[k] for k in ("red", "yellow", "white", "black"))
    f = _FURIES_FRAME
    for x0 in _FURIES_PANEL_XS:
        y0 = _FURIES_PANEL_Y
        x1, y1 = x0 + _FURIES_PANEL_W, y0 + _FURIES_PANEL_H
        for y in range(y0 - f, y1 + f):
            row = BAYER_8x8[y & 7]
            for x in range(x0 - f, x1 + f):
                if x0 <= x < x1 and y0 <= y < y1:
                    continue
                inset = min(x - (x0 - f), y - (y0 - f), (x1 + f - 1) - x, (y1 + f - 1) - y)
                rank = row[x & 7]
                if inset == f - 1:
                    ink = black                                   # the rebate
                elif inset <= 1 and (x - (x0 - f) == inset or y - (y0 - f) == inset):
                    ink = white if rank < 28 else yellow          # lit face
                elif inset <= 1:
                    ink = black if rank < 28 else red             # shaded face
                else:
                    ink = red if rank < 12 else yellow            # gold flat
                px[x, y] = ink


def _furies_paint_glass(image: Image.Image) -> None:
    """The window reflection on the glazing: sparse white along diagonal bands,
    one reflection continuous across all three panes, on the paint only."""
    px = image.load()
    white = SPECTRA6["white"]
    y0, y1 = _FURIES_PANEL_Y, _FURIES_PANEL_Y + _FURIES_PANEL_H
    for x0 in _FURIES_PANEL_XS:
        for y in range(y0, y1):
            for x in range(x0, x0 + _FURIES_PANEL_W):
                u = y + _FURIES_GLARE_SLOPE * x
                for centre, half, peak in _FURIES_GLARE:
                    d = abs(u - centre)
                    if d < half and position_noise(x, y) < 255 * peak * (1 - d / half):
                        px[x, y] = white
                        break


def _furies_paint_quote(image: Image.Image, quote_row: dict) -> None:
    """Wall text in white, and the matched phrase in the painting's orange
    with a red smear dragged off it — written only onto the black wall."""
    draw = ImageDraw.Draw(image)
    prose, hot, _ = wrap_quote_into_masks(draw, image.size, quote_row, _FURIES_QUOTE_RECT,
                                          theme="furies", font_max=30, font_min=15,
                                          line_height_mult=1.3)
    black, red, yellow = SPECTRA6["black"], SPECTRA6["red"], SPECTRA6["yellow"]
    solid_prose = prose.point(lambda v: 255 if v >= 128 else 0)
    image.paste(SPECTRA6["white"], (0, 0), solid_prose)
    box = hot.getbbox()
    if box is None:
        return
    x0, y0, x1, y1 = box
    trail_box = (x0, y0, min(image.width, x1 + 11), min(image.height, y1 + 9))
    _, smear = _furies_drag(Image.new("RGB", image.size), hot, 9, 7, steps=9, decay=0.8,
                            seed=51, keep=0.0)
    # The smear keeps a two-pixel berth round every glyph of the phrase, so it
    # never fills a counter or bridges two letters.
    berth = hot.filter(ImageFilter.MaxFilter(5))
    smear_px, hot_px, berth_px, px = smear.load(), hot.load(), berth.load(), image.load()
    for y in range(trail_box[1], trail_box[3]):
        row = BAYER_8x8[y & 7]
        for x in range(trail_box[0], trail_box[2]):
            if hot_px[x, y] >= 128:
                # Cadmium orange, yellow-leaning so it holds on the black wall.
                px[x, y] = red if row[x & 7] < _FURIES_PHRASE_RED_RANKS else yellow
            elif (px[x, y] == black and berth_px[x, y] < 128
                  and smear_px[x, y] * _FURIES_SMEAR_STRENGTH > row[x & 7] * 4 + 2):
                px[x, y] = red


def _furies_paint_byline(image: Image.Image, quote_row: dict) -> None:
    draw = ImageDraw.Draw(image)
    font = load_font([(LIBREFRANKLIN_ITALIC_VARIABLE, "Medium Italic"), *META_FONT_CANDIDATES], size=14)
    draw_truncated_centred_byline(draw, quote_row, centre=image.width // 2,
                                  baseline=_FURIES_BYLINE_BASELINE, max_width=image.width - 96,
                                  font=font, fill=SPECTRA6["white"])


def render_furies_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Bacon's 1944 triptych under glass, the quote as wall text beneath it.

    ``time_str`` is unused by design: a painting carries no clock.
    """
    del time_str
    image = Image.new("RGB", (800, 480), color=SPECTRA6["black"])
    _furies_paint_triptych(image)
    _furies_paint_glass(image)
    _furies_paint_frames(image)
    _furies_paint_quote(image, quote_row)
    _furies_paint_byline(image, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image




# ---------------------------------------------------------------------------
# The Culture — shared machinery for ``culture`` and ``orbital``
# ---------------------------------------------------------------------------
# Two views of one object, after Iain M. Banks's Culture novels: ``culture`` is
# a Mind's signal with the Orbital it concerns beside it; ``orbital`` stands on
# that Orbital and looks up at the far side of the ring.
#
# **Both tell the time with the Orbital itself.** The ring spins once a day,
# so at any instant it carries every local time at once:
#
# * ``culture`` marks the plate whose local time is now; the marker travels
#   the full ring once per 24 hours (lit inner face by day, hull by night).
# * ``orbital`` paints the far side of the ring, which is twelve hours away:
#   at noon the zenith is dark, at midnight it blazes across a black sky. The
#   sky follows the hour too.
#
# Neither shows a digit; both use the full 24-hour clock to the minute.
#
# **Marain.** The glyphs are a generated *Marain-idiom* script on a 3x3 grid
# (``_marain_code``), not Banks's own table. ``culture`` writes the matched
# phrase out in it.
#
# **Ship names are invented**, not lifted from the novels.
# ---------------------------------------------------------------------------
_CULTURE_SHIP_NAMES = (
    "Punctuality Is A Lesser Virtue",
    "Late Again, As Foretold",
    "Nobody Checks The Minutes",
    "Tea Before Eschatology",
    "Quietly Keeping Count",
    "Still Reading, Do Not Disturb",
    "An Hour Is Mostly Interval",
    "Borrowed Time, Returned With Interest",
    "The Clock Is Only A Suggestion",
    "Patience Of A Minor Deity",
    "Footnote To A Longer Argument",
    "Ask Me Again After This Chapter",
    "Wrong Century, Right Intentions",
    "Well-Thumbed Margins",
    "Somewhat Overdue",
    "Terminally Bookish",
    "Reads Aloud To Strangers",
    "Dog-Eared But Unbowed",
    "Never Skips To The Last Page",
    "Idle Hours Well Spent",
)
_CULTURE_SHIP_CLASSES = ("GSV", "GCU", "LSV", "MSV", "VFP", "GOU")
_CULTURE_CHANNELS = ("tight point", "stuttered tight point", "broadcast", "swept beam", "compact point")
_CULTURE_MARAIN_LEVELS = ("M1", "M8", "M16", "M16.4", "M32")
_CULTURE_ORBITAL_NAMES = (
    "Masquerade Reach", "Tessellate", "Quillon", "Arvenhale", "Sorrowless", "Pelluc",
    "Hollin Sweep", "Vey Toussant",
)
_CULTURE_PLATE_NAMES = (
    "Lakeshore", "Hivel", "Orrent Downs", "Sallow", "Tarn Mile", "Cressing",
    "Undersky", "Fennet",
)


def _culture_clock(time_str: str) -> float:
    """Local time as a fraction of the day, 0.0 (midnight) .. <1.0.

    Hour *and* minute, since the frames place things along the ring by it. A
    malformed string reads as noon.
    """
    try:
        hh, mm = str(time_str).split(":", 1)
        hour, minute = int(hh) % 24, int(mm[:2]) % 60
    except ValueError:
        hour, minute = 12, 0
    return (hour * 60 + minute) / 1440.0


def _culture_signal(quote_row: dict) -> dict:
    """The signal's header furniture, derived from the row, never the clock.

    Seeded from ``_row_digest`` so the same quote is the same signal on every
    render. The two ships are always distinct.
    """
    digest = _row_digest(quote_row)
    n = len(_CULTURE_SHIP_NAMES)
    src = digest % n
    dst = (src + 1 + (digest >> 5) % (n - 1)) % n
    return {
        "from": f"{_CULTURE_SHIP_CLASSES[(digest >> 10) % len(_CULTURE_SHIP_CLASSES)]} "
                f"{_CULTURE_SHIP_NAMES[src]}",
        "to": f"{_CULTURE_SHIP_CLASSES[(digest >> 13) % len(_CULTURE_SHIP_CLASSES)]} "
              f"{_CULTURE_SHIP_NAMES[dst]}",
        "channel": _CULTURE_CHANNELS[(digest >> 16) % len(_CULTURE_CHANNELS)],
        "level": _CULTURE_MARAIN_LEVELS[(digest >> 19) % len(_CULTURE_MARAIN_LEVELS)],
        # The ``tra.`` stamp is the signal's send date, derived from the row.
        "stamp": f"n4.{28 + (digest >> 3) % 3}.{840 + (digest >> 7) % 60:03d}.{(digest >> 11) % 10000:04d}",
        "orbital": _CULTURE_ORBITAL_NAMES[(digest >> 22) % len(_CULTURE_ORBITAL_NAMES)],
        "plate": _CULTURE_PLATE_NAMES[(digest >> 25) % len(_CULTURE_PLATE_NAMES)],
    }


# -- Marain-idiom glyphs ------------------------------------------------------
_MARAIN_ALPHABET = "abcdefghijklmnopqrstuvwxyz0123456789"


def _marain_connected(code: int) -> bool:
    """True when the set cells of a 3x3 code form one orthogonally connected run."""
    cells = [i for i in range(9) if code >> i & 1]
    if not cells:
        return False
    seen, stack = {cells[0]}, [cells[0]]
    while stack:
        c = stack.pop()
        r, q = divmod(c, 3)
        for dr, dq in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, qq = r + dr, q + dq
            n = rr * 3 + qq
            if 0 <= rr < 3 and 0 <= qq < 3 and code >> n & 1 and n not in seen:
                seen.add(n)
                stack.append(n)
    return len(seen) == len(cells)


def _marain_table() -> dict[str, int]:
    """Assign every letter and digit a distinct, connected, 4-6 point pattern.

    A fixed affine step through the 512 codes scatters the assignment (so
    neighbouring letters don't get near-identical glyphs), filtered to single
    connected figures. Deterministic at import.
    """
    table: dict[str, int] = {}
    used: set[int] = set()
    code = 0
    for ch in _MARAIN_ALPHABET:
        while True:
            code = (code * 5 + 173) % 512
            if 4 <= bin(code).count("1") <= 6 and code not in used and _marain_connected(code):
                break
        used.add(code)
        table[ch] = code
    return table


_MARAIN_TABLE = _marain_table()


def _marain_code(ch: str) -> int | None:
    """The 9-bit pattern for one character, ``None`` for a word gap."""
    return _MARAIN_TABLE.get(ch.lower())


def _marain_draw_glyph(draw: ImageDraw.ImageDraw, x: int, y: int, code: int,
                       pitch: int, fill, *, stroke: int = 2, dot: int = 2) -> None:
    """One glyph with its top-left grid point at ``(x, y)``.

    Set points are joined to their set orthogonal neighbours, and every set
    point carries a dot, so a lone point still reads as part of the figure.
    """
    pts = {}
    for i in range(9):
        if code >> i & 1:
            r, q = divmod(i, 3)
            pts[i] = (x + q * pitch, y + r * pitch)
    for i, (px_, py_) in pts.items():
        if i % 3 < 2 and i + 1 in pts:
            draw.line([(px_, py_), pts[i + 1]], fill=fill, width=stroke)
        if i + 3 in pts:
            draw.line([(px_, py_), pts[i + 3]], fill=fill, width=stroke)
    for px_, py_ in pts.values():
        draw.ellipse((px_ - dot, py_ - dot, px_ + dot, py_ + dot), fill=fill)


def _marain_glyph_count(rows) -> int:
    return sum(code is not None for row in rows for code in row)


def _marain_layout(text: str, max_cols: int) -> list[list[int | None]]:
    """Break ``text`` into rows of glyph codes, wrapping only at word gaps.

    Hyphens count as word gaps: the script has no hyphen glyph, so
    "five-and-twenty" would otherwise fuse into one thirteen-letter word
    that no row can hold. A word still longer than a row is cut to it —
    callers that must not lose glyphs check with ``_marain_glyph_count``.
    """
    words = [[_marain_code(c) for c in w if _marain_code(c) is not None]
             for w in text.replace("-", " ").split()]
    words = [w for w in words if w]
    rows: list[list[int | None]] = []
    row: list[int | None] = []
    for word in words:
        need = len(word) + (1 if row else 0)
        if row and len(row) + need > max_cols:
            rows.append(row)
            row = []
        if row:
            row.append(None)
        row.extend(word[:max_cols])
    if row:
        rows.append(row)
    return rows


# -- culture: the Mind signal ---------------------------------------------------
# A custom frame. Left: the signal, set out the way Banks prints ship-to-ship
# traffic — a bracketed transmission line, then ``x`` (from) and ``o`` (to)
# ship names — and the quote as its body. The matched phrase glows like a
# drone's aura field. Right: the Orbital the signal concerns, a tilted ring
# whose visible inner face holds exactly the plates in daylight (their cities
# showing only where the face turns into dusk at its tips) and the hull,
# the current plate marked; and under it the matched phrase again, in Marain.
_CULTURE_TEXT_X = (34, 462)
_CULTURE_HEADER_Y = 28
_CULTURE_RULE_Y = 104
_CULTURE_QUOTE_RECT = (34, 120, 462, 396)
_CULTURE_FOOTER_Y = 424
_CULTURE_ORBITAL = (632, 168, 156)       # centre x, centre y, radius
_CULTURE_ORBITAL_K = 0.42                # minor/major axis = sin(view elevation)
_CULTURE_ORBITAL_TILT = -0.14            # screen rotation of the ring, radians
_CULTURE_ORBITAL_W = 24                  # band thickness on screen, px
# Ring angle of the plate at local noon: the middle of the far arc, so the
# visible inner face holds exactly the plates between 06:00 and 18:00.
_CULTURE_NOON = math.radians(-90)
_CULTURE_MARAIN_RECT = (494, 338, 780, 446)
_CULTURE_MARAIN_PITCH = 7
_CULTURE_MARAIN_MIN_PITCH = 3
_CULTURE_MARAIN_HEAD = 28               # label band above the glyphs, px
_CULTURE_STAR_SEED = 0xBA4C5
# Ships as (nose-left x, centreline y, length, half-girth): the GSV, then escorts.
_CULTURE_SHIPS = ((520, 34, 84, 4), (618, 52, 22, 2), (656, 30, 14, 1))
_CULTURE_STAR_COUNT = 260


def _culture_ground() -> frozenset:
    return frozenset({SPECTRA6["black"]})


def _culture_paint_stars(image: Image.Image) -> None:
    """A sparse seeded star field, kept off the text column."""
    rng = random.Random(_CULTURE_STAR_SEED)
    px = image.load()
    width, height = image.size
    white, yellow, blue = SPECTRA6["white"], SPECTRA6["yellow"], SPECTRA6["blue"]
    x0, _, x1, _ = _CULTURE_QUOTE_RECT
    for _ in range(_CULTURE_STAR_COUNT):
        x, y = rng.randrange(width), rng.randrange(height)
        roll = rng.random()
        if x0 - 6 <= x <= x1 + 6:
            continue
        px[x, y] = yellow if roll < 0.08 else blue if roll < 0.22 else white


def _culture_ring_uv(dx: float, dy: float) -> tuple[float, float]:
    c, s = math.cos(_CULTURE_ORBITAL_TILT), math.sin(_CULTURE_ORBITAL_TILT)
    return dx * c + dy * s, -dx * s + dy * c


def _culture_ring_xy(u: float, v: float) -> tuple[float, float]:
    c, s = math.cos(_CULTURE_ORBITAL_TILT), math.sin(_CULTURE_ORBITAL_TILT)
    cx, cy, _ = _CULTURE_ORBITAL
    return cx + u * c - v * s, cy + u * s + v * c


def _culture_ring_point(theta: float, across: float = 0.5) -> tuple[float, float]:
    """Screen position of ring angle ``theta`` at fraction ``across`` of the band."""
    _, _, radius = _CULTURE_ORBITAL
    u = radius * math.cos(theta)
    v = radius * _CULTURE_ORBITAL_K * math.sin(theta) - across * _CULTURE_ORBITAL_W
    return _culture_ring_xy(u, v)


def _culture_terrain(arc: float, across: float) -> tuple[float, float]:
    """``(land, cloud)`` fields over the ring's inner face.

    Sums of incommensurate sines on (arc length, fraction across the band) —
    smooth, continuous around the ring and byte-deterministic. Land above zero
    is continent, below is sea; the face ink treats cloud above 1.25 as weather.
    """
    land = (math.sin(arc * 0.071 + 1.7 * math.sin(arc * 0.019))
            + 0.55 * math.sin(arc * 0.043 + across * 4.1 + 0.6)
            + 0.35 * math.sin(across * 9.0 - arc * 0.013))
    cloud = (math.sin(arc * 0.17 + across * 7.0 + 2.0 * math.sin(arc * 0.037))
             + 0.7 * math.sin(arc * 0.29 - across * 5.0))
    return land, cloud


def _culture_face_ink(rank: int, x: int, y: int, arc: float, across: float, day: float):
    """Ink for one pixel of the inner (habitable) face.

    ``day`` is the cosine of the sun's angle from the plate's zenith: above
    zero the plate is in daylight. A single ``BAYER_8x8`` read decides both the
    shading and the surface mix (``pride``'s rule).
    """
    black, white, blue, green, yellow = (SPECTRA6[n] for n in ("black", "white", "blue", "green", "yellow"))
    land, cloud = _culture_terrain(arc, across)
    if day <= 0.0:
        # Night: dark plates, lit by their own cities.
        if land > 0.15 and position_noise(x, y) < 26:
            return yellow
        return black
    shade = max(0.0, 1.0 - day * 2.2)
    cut = shade * 64
    if rank < cut:
        return black
    share = (rank - cut) / max(1.0, 64 - cut)
    if cloud > 1.25:
        return white
    if land > 0.25:
        return yellow if share < 0.12 else green
    return white if share < 0.1 else blue


def _culture_paint_orbital(image: Image.Image) -> None:
    """The Orbital, per pixel: far arc shows the inner face, near arc the hull.

    For a screen pixel the ring coordinates follow in closed form. With the
    ring's centreline an ellipse of half-height ``h = R k sin`` at ``u`` and the
    band stacked ``W`` px above it, a pixel is on the far arc when ``v`` lies in
    ``[-h - W, -h]`` and on the near arc when it lies in ``[h - W, h]``. The near
    arc is tested first, so where the two overlap at the ends of the ellipse the
    hull correctly passes in front of the face.
    """
    cx, cy, radius = _CULTURE_ORBITAL
    k, band = _CULTURE_ORBITAL_K, _CULTURE_ORBITAL_W
    px = image.load()
    width, height = image.size
    black, white, blue = SPECTRA6["black"], SPECTRA6["white"], SPECTRA6["blue"]
    pad = band + 6
    for y in range(max(0, int(cy - radius * 0.5 - pad)), min(height, int(cy + radius * 0.5 + pad))):
        row = BAYER_8x8[y % 8]
        for x in range(max(0, cx - radius - pad), min(width, cx + radius + pad)):
            u, v = _culture_ring_uv(x - cx, y - cy)
            if abs(u) >= radius:
                continue
            s = math.sqrt(1.0 - (u / radius) ** 2)
            h = radius * k * s
            rank = row[x % 8]
            if h - band <= v <= h:
                # Near arc: the hull, lit where it faces the sun.
                theta = math.atan2(s, u / radius)
                across = (h - v) / band
                lit = -math.cos(theta - _CULTURE_NOON)
                edge = across < 0.09 or across > 0.91
                if edge:
                    px[x, y] = white if lit > 0.05 else blue
                    continue
                seam = int(theta * radius / 9.0) != int((theta * radius + 1.0) / 9.0)
                if lit > 0 and not seam and rank < lit * 0.42 * 64:
                    px[x, y] = white
                else:
                    px[x, y] = black
                continue
            if -h - band <= v <= -h:
                # Far arc: the inner face, the habitable surface looking back.
                theta = math.atan2(-s, u / radius)
                across = (-h - v) / band
                day = math.cos(theta - _CULTURE_NOON)
                if across < 0.07 or across > 0.93:
                    # The rim walls: lit bright on the day side, faint at night.
                    px[x, y] = white if day > 0 else blue
                    continue
                px[x, y] = _culture_face_ink(rank, x, y, theta * radius, across, day)


def _culture_plate_theta(clock: float) -> float:
    """Ring angle of the plate whose local time is ``clock`` (fraction of a day)."""
    return _CULTURE_NOON + (clock - 0.5) * 2.0 * math.pi


def _culture_paint_marker(image: Image.Image, draw: ImageDraw.ImageDraw,
                          clock: float, plate: str) -> tuple[int, int]:
    """Mark the plate whose local time is now, with a leader out to its name.

    Returns the marker's screen position (used by the tests). The leader runs
    radially away from the ring's centre so it never crosses the band.
    """
    cx, cy, _ = _CULTURE_ORBITAL
    theta = _culture_plate_theta(clock)
    mx, my = _culture_ring_point(theta)
    dx, dy = mx - cx, my - cy
    norm = math.hypot(dx, dy) or 1.0
    ux, uy = dx / norm, dy / norm
    if mx + ux * 30 < _CULTURE_TEXT_X[1] + 10:
        # Near the left end the radial leader would point into the quote, so
        # it drops straight down instead and the label hangs below the ring.
        ux, uy = 0.0, 1.0
    ex, ey = mx + ux * 30, my + uy * 30
    yellow, black = SPECTRA6["yellow"], SPECTRA6["black"]
    draw.line([(mx, my), (ex, ey)], fill=yellow, width=1)
    draw.ellipse((mx - 5, my - 5, mx + 5, my + 5), outline=black, width=3)
    draw.ellipse((mx - 4, my - 4, mx + 4, my + 4), outline=yellow, width=2)
    font = load_font([SHARETECHMONO_REGULAR, SPACEMONO_REGULAR, *META_FONT_CANDIDATES], size=12)
    label = plate.upper()
    tw = draw.textlength(label, font=font)
    lx = ex - tw / 2 if ux == 0.0 else (ex + 4 if dx >= 0 else ex - 4 - tw)
    # Never into the signal column: near the ring's left end the leader points
    # at the quote, so the label is held at the column's edge instead.
    lx = max(_CULTURE_TEXT_X[1] + 12, min(image.size[0] - 8 - tw, lx))
    ly = ey if ux == 0.0 else ey - 7
    draw.rectangle((lx - 2, ly, lx + tw + 2, ly + 14), fill=black)
    draw.text((lx, ly), label, font=font, fill=yellow)
    return round(mx), round(my)


def _culture_paint_ships(image: Image.Image) -> None:
    """A GSV and two escorts crossing the dark above the Orbital.

    Pale tapered hulls inside a blue field bloom; one mask, so hull and field
    share one halo.
    """
    mask = Image.new("L", image.size, 0)
    md = ImageDraw.Draw(mask)
    for (x0, y0, length, girth) in _CULTURE_SHIPS:
        md.polygon([(x0, y0), (x0 + girth * 2, y0 - girth), (x0 + length - girth * 3, y0 - girth),
                    (x0 + length, y0), (x0 + length - girth * 3, y0 + girth), (x0 + girth * 2, y0 + girth)],
                   fill=255)
    paint_neon_mask(image, mask, SPECTRA6["white"], SPECTRA6["blue"],
                    radius=3, gamma=1.5, cap=0.55, ground=_culture_ground())
    mask.close()


def _culture_marain_fit(phrase: str) -> tuple[int, int, int, list[list[int | None]]]:
    """``(pitch, step, row_step, rows)`` for the largest glyphs that hold the
    whole phrase in the Marain block.

    Steps the grid pitch down rather than dropping rows: the last row of a
    long phrase is usually the hour itself. Spacing scales with the pitch.
    Only a phrase too long even at the floor pitch is cut; no committed corpus
    row is (``TestCultureFrame`` sweeps them).
    """
    x0, y0, x1, y1 = _CULTURE_MARAIN_RECT
    avail_h = y1 - (y0 + _CULTURE_MARAIN_HEAD)
    want = _marain_glyph_count(_marain_layout(phrase, len(phrase) + 1))
    for pitch in range(_CULTURE_MARAIN_PITCH, _CULTURE_MARAIN_MIN_PITCH - 1, -1):
        glyph = pitch * 2
        step = glyph + round(pitch * 10 / 7)
        row_step = glyph + round(pitch * 16 / 7)
        cols = max(1, (x1 - x0 - glyph) // step + 1)
        rows = _marain_layout(phrase, cols)
        if (len(rows) * row_step - (row_step - glyph) <= avail_h
                and _marain_glyph_count(rows) == want):
            return pitch, step, row_step, rows
    max_rows = max(1, (avail_h - glyph) // row_step + 1)
    return pitch, step, row_step, rows[:max_rows]


def _culture_paint_marain(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The matched phrase written out again, in Marain, under the Orbital."""
    x0, y0, x1, y1 = _CULTURE_MARAIN_RECT
    white, blue = SPECTRA6["white"], SPECTRA6["blue"]
    small = load_font([SHARETECHMONO_REGULAR, SPACEMONO_REGULAR, *META_FONT_CANDIDATES], size=12)
    label = "THE HOUR, IN MARAIN"
    draw.text((x0, y0), label, font=small, fill=white)
    draw.line([(x0 + draw.textlength(label, font=small) + 8, y0 + 8), (x1, y0 + 8)], fill=blue, width=1)
    phrase = (quote_row.get("matched_text") or "").strip()
    if not phrase:
        return
    pitch, step, row_step, rows = _culture_marain_fit(phrase)
    glyph = pitch * 2
    top = y0 + _CULTURE_MARAIN_HEAD
    mask = Image.new("L", image.size, 0)
    md = ImageDraw.Draw(mask)
    block_h = len(rows) * row_step - (row_step - glyph)
    top += max(0, (y1 - top - block_h) // 2)
    stroke, dot = (3, 2) if pitch >= 6 else (2, 2) if pitch >= 5 else (2, 1)
    for r, codes in enumerate(rows):
        width_px = (len(codes) - 1) * step + glyph
        x = x0 + max(0, (x1 - x0 - width_px) // 2)
        for code in codes:
            if code is not None:
                _marain_draw_glyph(md, x, top + r * row_step, code, pitch, 255, stroke=stroke, dot=dot)
            x += step
    paint_neon_mask(image, mask, white, blue, radius=3, gamma=1.5, cap=0.6,
                    ground=_culture_ground())
    mask.close()


def _culture_paint_signal(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The signal header, the quote as its body, and the relay line.

    Chrome text is white or yellow, never blue: small type in panel blue on
    black disappears. Blue is kept for rules and blooms.
    """
    white, yellow, green, blue, black = (SPECTRA6[n] for n in ("white", "yellow", "green", "blue", "black"))
    sig = _culture_signal(quote_row)
    x0, x1 = _CULTURE_TEXT_X
    mono = [SHARETECHMONO_REGULAR, SPACEMONO_REGULAR, *META_FONT_CANDIDATES]
    y = _CULTURE_HEADER_Y
    font, text = fit_text_to_width(
        draw, f"[{sig['channel']}, {sig['level']}, tra. @{sig['stamp']}]", mono, 15, x1 - x0, floor=11)
    draw.text((x0, y), text, font=font, fill=white)
    y += 24
    for prefix, name, ink in (("x", sig["from"], yellow), ("o", sig["to"], white)):
        font, text = fit_text_to_width(draw, prefix + name, mono, 19, x1 - x0, floor=12)
        draw.text((x0, y), text, font=font, fill=ink)
        y += 25
    draw.line([(x0, _CULTURE_RULE_Y), (x0 + 64, _CULTURE_RULE_Y)], fill=blue, width=2)

    prose, hot, _ = wrap_quote_into_masks(
        draw, image.size, quote_row, _CULTURE_QUOTE_RECT, theme="culture",
        font_max=34, font_min=14, line_height_mult=1.3, align="left",
    )
    image.paste(white, (0, 0), prose.point(lambda v: 255 if v > 128 else 0))
    # The drone's aura: a yellow core wrapped in a green field. Only ever lands
    # on black, so the prose beside it is never eaten.
    paint_neon_mask(image, hot, yellow, green, radius=3, gamma=1.7, cap=0.55,
                    ground=frozenset({black}), tile=BAYER_8x8)
    prose.close()
    hot.close()

    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or fallback_title(quote_row) or "").strip()
    credit = " · ".join(p for p in (author, title) if p)
    draw.line([(x0, _CULTURE_FOOTER_Y - 8), (x0 + 64, _CULTURE_FOOTER_Y - 8)], fill=blue, width=2)
    small = load_font(mono, size=12)
    if not credit:
        draw.text((x0, _CULTURE_FOOTER_Y), "[signal ends]", font=small, fill=white)
        return
    draw.text((x0, _CULTURE_FOOTER_Y), "RELAYED FROM THE ARCHIVE", font=small, fill=yellow)
    body = [JURA_SEMIBOLD, *META_FONT_BOLD_CANDIDATES]
    font, text = fit_text_to_width(draw, credit, body, 17, x1 - x0, floor=11)
    draw.text((x0, _CULTURE_FOOTER_Y + 16), text, font=font, fill=white)


def _culture_paint_chrome(draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The Orbital's name, set under the ring."""
    sig = _culture_signal(quote_row)
    white, yellow = SPECTRA6["white"], SPECTRA6["yellow"]
    cx, cy, radius = _CULTURE_ORBITAL
    small = load_font([SHARETECHMONO_REGULAR, SPACEMONO_REGULAR, *META_FONT_CANDIDATES], size=12)
    name = load_font([JURA_BOLD, *META_FONT_BOLD_CANDIDATES], size=18)
    y = cy + int(radius * _CULTURE_ORBITAL_K) + 42
    draw.text((cx, y), f"{sig['orbital']} Orbital", font=name, fill=white, anchor="ma")
    draw.text((cx, y + 24), "ONE ROTATION PER DAY", font=small, fill=yellow, anchor="ma")


def render_culture_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A Mind's signal beside the Orbital it concerns (see the section comment)."""
    clock = _culture_clock(time_str)
    image = Image.new("RGB", (800, 480), color=SPECTRA6["black"])
    draw = ImageDraw.Draw(image)
    _culture_paint_stars(image)
    _culture_paint_ships(image)
    _culture_paint_orbital(image)
    _culture_paint_marker(image, draw, clock, _culture_signal(quote_row)["plate"])
    _culture_paint_chrome(draw, quote_row)
    _culture_paint_marain(image, draw, quote_row)
    _culture_paint_signal(image, draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# -- orbital: the Arch from the plate --------------------------------------------
# A custom frame, standing on one of the Orbital's plates and looking up. The
# rest of the ring rises from both horizons and meets overhead — the Arch — and
# the page is lit by where the sun is in this plate's day.
#
# **The Arch is the clock.** A point a fraction ``f`` of the way round the ring
# keeps a local time ``f`` of a day ahead of ours, so each pixel of the band is
# lit or dark by its own local time: at noon the Arch is lit at its feet and
# dark overhead, at midnight the zenith burns in daylight over a black sky
# (Banks's own image). The sky follows the hour: blue by day, a warm horizon
# band at dawn and dusk, stars at night.
#
# **The Arch narrows as it rises**, because it recedes: a point ``phi`` round
# the ring is ``2R sin(phi/2)`` away, so its apparent width falls as
# ``1 / sin(phi/2)``.
#
# The quote card is white with dark type by day and black with white type by
# night, so it is legible against either sky.
_ORBITAL_HORIZON = 318
_ORBITAL_ARCH = (400, 474, 300)            # centre x, semi-axis a, semi-axis b
_ORBITAL_ARCH_PHI0 = math.radians(44)      # ring angle where the Arch meets the ground
_ORBITAL_ARCH_T_APEX = 0.03                # band width at the zenith, in radius units
_ORBITAL_CARD = (120, 102, 680, 330)
_ORBITAL_QUOTE_PAD = (26, 34, 26, 40)       # left, top, right, bottom inside the card
_ORBITAL_STAR_SEED = 0x0B17A1
_ORBITAL_STAR_COUNT = 420


def _orbital_sun(clock: float) -> float:
    """Cosine of the sun's angle from the zenith: 1 at noon, -1 at midnight."""
    return math.cos(2.0 * math.pi * (clock - 0.5))


def _orbital_period(clock: float) -> str:
    """``"day"``, ``"twilight"`` or ``"night"`` for the plate's sky."""
    sun = _orbital_sun(clock)
    if sun > 0.2:
        return "day"
    if sun > -0.2:
        return "twilight"
    return "night"


def _orbital_ramp_mask(width: int, height: int, density, *, jitter: bool = True,
                       column=None) -> Image.Image:
    """An ``L`` mask, 255 where an ordered dither of ``density(y)`` is lit.

    Built from image operations (gradient minus tiled ``BAYER_8x8`` threshold)
    rather than a per-pixel loop, since a sky is ~250k pixels. ``jitter``
    perturbs the threshold: an unjittered ramp over a large field lattices.
    """
    grad = Image.new("L", (1, height))
    grad.putdata([max(0, min(255, round(density(y) * 256))) for y in range(height)])
    grad = grad.resize((width, height), Image.Resampling.NEAREST)
    if column is not None:
        # A separable horizontal weight, multiplied in at C speed.
        cols = Image.new("L", (width, 1))
        cols.putdata([max(0, min(255, round(column(x) * 255))) for x in range(width)])
        grad = ImageChops.multiply(grad, cols.resize((width, height), Image.Resampling.NEAREST))
    thresh = _orbital_threshold(width, height, jitter)
    return ImageChops.subtract(grad, thresh).point(lambda v: 255 if v > 0 else 0)


@functools.lru_cache(maxsize=4)
def _orbital_threshold(width: int, height: int, jitter: bool) -> Image.Image:
    """The tiled (optionally jittered) ``BAYER_8x8`` threshold image.

    Quote- and clock-independent, so cached per geometry. Callers must only
    read it.
    """
    tile = Image.new("L", (8, 8))
    tile.putdata([BAYER_8x8[y][x] * 4 + 2 for y in range(8) for x in range(8)])
    thresh = Image.new("L", (width, height))
    for ty in range(0, height, 8):
        for tx in range(0, width, 8):
            thresh.paste(tile, (tx, ty))
    if jitter:
        noise = _white_noise(width, height, _ORBITAL_STAR_SEED).point(lambda v: v // 8)
        thresh = ImageChops.add(thresh, noise, offset=-16)
    return thresh


def _orbital_paint_sky(image: Image.Image, clock: float) -> None:
    """Day blue, twilight glow, or night and stars, above the horizon."""
    width = image.size[0]
    horizon = _ORBITAL_HORIZON
    sky = image.crop((0, 0, width, horizon))
    period = _orbital_period(clock)
    white, blue, black, red, yellow = (SPECTRA6[n] for n in ("white", "blue", "black", "red", "yellow"))
    if period == "day":
        sky.paste(blue, (0, 0, width, horizon))
        # Paler toward the horizon, where the eye looks through more air.
        sky.paste(white, (0, 0), _orbital_ramp_mask(width, horizon, lambda y: 0.18 + 0.5 * (y / horizon) ** 1.6))
    else:
        sky.paste(black, (0, 0, width, horizon))
        rng = random.Random(_ORBITAL_STAR_SEED)
        spx = sky.load()
        for _ in range(_ORBITAL_STAR_COUNT if period == "night" else _ORBITAL_STAR_COUNT // 4):
            x, y = rng.randrange(width), rng.randrange(horizon)
            roll = rng.random()
            if y < horizon * (0.95 if period == "night" else 0.45):
                spx[x, y] = yellow if roll < 0.07 else blue if roll < 0.2 else white
        # A navy haze toward the horizon (deeper and higher at twilight).
        reach = 0.45 if period == "twilight" else 0.25
        sky.paste(blue, (0, 0), _orbital_ramp_mask(
            width, horizon, lambda y: max(0.0, (y / horizon - (1 - reach)) / reach) * 0.55))
        if period == "twilight":
            # The warm band, strongest over the sun's side of the sky: red
            # rising into a thinner gold edge at the horizon itself.
            east_west = math.sin(2.0 * math.pi * (clock - 0.5))
            sun_x = 400 + 380 * east_west
            near_sun = lambda x: max(0.25, 1.0 - abs(x - sun_x) / 620.0)  # noqa: E731
            sky.paste(red, (0, 0), _orbital_ramp_mask(
                width, horizon, lambda y: max(0.0, (y / horizon - 0.66) / 0.34) ** 1.3 * 0.85,
                column=near_sun))
            sky.paste(yellow, (0, 0), _orbital_ramp_mask(
                width, horizon, lambda y: max(0.0, (y / horizon - 0.84) / 0.16) ** 1.5 * 0.6,
                column=near_sun))
    image.paste(sky, (0, 0))


def _orbital_sun_xy(clock: float) -> tuple[int, int] | None:
    """Where the sun stands, or ``None`` when it is below the horizon.

    The path is wide and steep so a low sun stands clear of the quote card, and
    the noon sun sits below the Arch's apex (an Orbital is tilted so the far side
    does not eclipse noon).
    """
    sun = _orbital_sun(clock)
    if sun <= 0.02:
        return None
    east_west = math.sin(2.0 * math.pi * (clock - 0.5))
    x = 400 + 380 * east_west
    y = _ORBITAL_HORIZON - 255 * sun ** 0.25
    return round(x), round(y)


def _orbital_paint_sun(image: Image.Image, clock: float) -> None:
    pos = _orbital_sun_xy(clock)
    if pos is None:
        return
    x, y = pos
    mask = Image.new("L", image.size, 0)
    ImageDraw.Draw(mask).ellipse((x - 11, y - 11, x + 11, y + 11), fill=255)
    glow = SPECTRA6["yellow"] if _orbital_period(clock) == "day" else SPECTRA6["red"]
    paint_neon_mask(image, mask, SPECTRA6["white"], glow, radius=6, gamma=1.4, cap=0.7,
                    ground=frozenset({SPECTRA6["blue"], SPECTRA6["white"], SPECTRA6["black"]}))
    mask.close()


def _orbital_arch_phi(alpha: float) -> float:
    """Ring angle seen at elliptical angle ``alpha`` (``pi`` = left foot, 0 = right)."""
    return _ORBITAL_ARCH_PHI0 + (1.0 - alpha / math.pi) * (2.0 * math.pi - 2.0 * _ORBITAL_ARCH_PHI0)


def _orbital_arch_width(phi: float) -> float:
    """Band width in radius units: ``1 / sin(phi/2)`` perspective falloff."""
    return _ORBITAL_ARCH_T_APEX / max(0.05, math.sin(phi / 2.0))


def _orbital_arch_day(clock: float, phi: float) -> float:
    """Sun-angle cosine at the plate ``phi`` round the ring: its local noon is 1."""
    return math.cos(2.0 * math.pi * (clock + phi / (2.0 * math.pi) - 0.5))


def _orbital_paint_arch(image: Image.Image, clock: float) -> None:
    """The far side of the ring, each pixel lit by its own local time.

    Each row walks only the two x-intervals the band can occupy (closed form
    from the ellipse), so the cost is the band's area, not the sky's.
    """
    cx, a, b = _ORBITAL_ARCH
    horizon = _ORBITAL_HORIZON
    px = image.load()
    width = image.size[0]
    period = _orbital_period(clock)
    black, white, blue, green, yellow = (SPECTRA6[n] for n in ("black", "white", "blue", "green", "yellow"))
    t_max = _orbital_arch_width(_ORBITAL_ARCH_PHI0)
    for y in range(0, horizon):
        q = (horizon - y) / b
        if q >= 1.0:
            continue
        outer = a * math.sqrt(1.0 - q * q)
        inner_sq = (1.0 - t_max) ** 2 - q * q
        inner = a * math.sqrt(inner_sq) if inner_sq > 0 else 0.0
        row = BAYER_8x8[y % 8]
        spans = ((cx - outer, cx - inner), (cx + inner, cx + outer))
        for lo, hi in spans:
            for x in range(max(0, int(lo) - 1), min(width, int(hi) + 2)):
                ux = (x - cx) / a
                rho = math.hypot(ux, q)
                alpha = math.atan2(q, ux)
                phi = _orbital_arch_phi(alpha)
                t = _orbital_arch_width(phi)
                across = (1.0 - rho) / t
                if not 0.0 <= across <= 1.0:
                    continue
                day = _orbital_arch_day(clock, phi)
                rank = row[x % 8]
                # The rim walls, a fixed ~1.5 px at every width, so the Arch keeps
                # its outline even where its surface is in night.
                rim = 1.5 / (t * b)
                if across < rim or across > 1.0 - rim:
                    px[x, y] = white if (day > 0 or period != "night") else blue
                    continue
                if day > 0:
                    ink = _culture_face_ink(rank, x, y, phi * 180.0, across, day)
                    # Seen through our own air by day: the far side washes pale.
                    if period == "day" and ink != white and position_noise(x, y) < 40:
                        ink = white
                    px[x, y] = ink
                elif period == "day":
                    # The far side's night, seen through a lit sky: a band of
                    # navy a shade deeper than the blue around it.
                    px[x, y] = black if rank < 20 else blue
                else:
                    px[x, y] = yellow if position_noise(x, y) < 14 and rank < 40 else black


def _orbital_lights(x: int, y: int, below_crest: float) -> bool:
    """A lit window: rare in open country, gathered into a few settlements that
    sit along the hills' far slopes and thin out toward the viewer."""
    town = math.sin(x * 0.021 + 0.7) + math.sin(x * 0.0063 + 2.9)
    if town > 1.0 and below_crest < 46:
        return position_noise(x, y) < 30 * (1.0 - below_crest / 46)
    return position_noise(x, y) < 1


def _orbital_paint_land(image: Image.Image, clock: float) -> None:
    """The plate itself: a hazy far range and near forested hills.

    By day the hills are forest green shading toward the foreground; at
    twilight and night they are silhouettes, lit only by their settlements —
    which stay dark at twilight, when nobody has needed a lamp yet.
    """
    width, height = image.size
    horizon = _ORBITAL_HORIZON
    period = _orbital_period(clock)
    black, white, blue, green, yellow = (SPECTRA6[n] for n in ("black", "white", "blue", "green", "yellow"))
    px = image.load()
    for x in range(width):
        far = horizon - 14 - 16 * math.sin(x * 0.011 + 0.8) - 7 * math.sin(x * 0.037 + 2.1)
        near = horizon + 34 + 18 * math.sin(x * 0.0072 + 2.6) + 8 * math.sin(x * 0.029)
        for y in range(int(far), height):
            rank = BAYER_8x8[y % 8][x % 8]
            if y < near:
                # The far range: through haze by day, a navy silhouette by night.
                if period == "day":
                    px[x, y] = blue if rank < 44 else white
                else:
                    px[x, y] = blue if rank < 16 else black
                continue
            depth = (y - near) / max(1.0, height - near)
            if period == "day":
                # Sunlit crests fading to forest shade toward the viewer.
                crest = y - near < 5
                cut = 64 * (0.06 + 0.34 * depth)
                px[x, y] = black if rank < cut else (yellow if crest and rank > 40 else green)
            elif y - near < 1.5:
                # A cold rim on the crest so the silhouette still reads.
                px[x, y] = blue
            elif period == "night" and _orbital_lights(x, y, y - near):
                px[x, y] = yellow
            else:
                px[x, y] = black


def _orbital_paint_card(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict,
                        clock: float) -> None:
    """The quote on a card floating under the Arch, inked for the hour."""
    x0, y0, x1, y1 = _ORBITAL_CARD
    white, black, blue, yellow, green = (SPECTRA6[n] for n in ("white", "black", "blue", "yellow", "green"))
    night = _orbital_period(clock) != "day"
    face, ink, rule = (black, white, white) if night else (white, black, black)
    # Shadow ledge by day (the ``kanagawa`` / ``pride`` card), a blue field
    # bloom by night — a drone's field, not a sheet of paper.
    if night:
        mask = Image.new("L", image.size, 0)
        ImageDraw.Draw(mask).rounded_rectangle((x0, y0, x1, y1), radius=12, fill=255)
        paint_neon_mask(image, mask, None, blue, radius=5, gamma=1.3, cap=0.6)
        mask.close()
    else:
        draw.rounded_rectangle((x0 + 4, y0 + 4, x1 + 4, y1 + 4), radius=12, fill=black)
    draw.rounded_rectangle((x0, y0, x1, y1), radius=12, fill=face, outline=rule, width=1)

    sig = _culture_signal(quote_row)
    mono = [SHARETECHMONO_REGULAR, SPACEMONO_REGULAR, *META_FONT_CANDIDATES]
    small = load_font(mono, size=12)
    header = f"{sig['plate'].upper()} PLATE · {sig['orbital'].upper()} ORBITAL"
    draw.text((x0 + 20, y0 + 12), header, font=small, fill=ink)
    # The header's Marain: the plate's name, as its own signage would carry it.
    code_x = x1 - 20
    for ch in reversed(sig["plate"].lower()):
        code = _marain_code(ch)
        if code is None:
            continue
        code_x -= 12
        _marain_draw_glyph(draw, code_x, y0 + 12, code, 4, ink, stroke=1, dot=1)

    pl, pt, pr, pb = _ORBITAL_QUOTE_PAD
    rect = (x0 + pl, y0 + pt, x1 - pr, y1 - pb)
    prose, hot, _ = wrap_quote_into_masks(draw, image.size, quote_row, rect, theme="orbital",
                                          font_max=32, font_min=14, line_height_mult=1.28)
    image.paste(ink, (0, 0), prose.point(lambda v: 255 if v > 128 else 0))
    if night:
        paint_neon_mask(image, hot, yellow, green, radius=3, gamma=1.7, cap=0.55,
                        ground=frozenset({face}), tile=BAYER_8x8)
    else:
        image.paste(blue, (0, 0), hot.point(lambda v: 255 if v > 128 else 0))
    prose.close()
    hot.close()

    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or fallback_title(quote_row) or "").strip()
    credit = " · ".join(p for p in (author, title) if p)
    if credit:
        font, text = fit_text_to_width(draw, credit, [JURA_SEMIBOLD, *META_FONT_BOLD_CANDIDATES],
                                       15, x1 - x0 - 48, floor=11)
        draw.text(((x0 + x1) // 2, y1 - 26), text, font=font, fill=ink, anchor="ma")


def render_orbital_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """The Arch from the plate, lit by the hour (see the section comment)."""
    clock = _culture_clock(time_str)
    image = Image.new("RGB", (800, 480), color=SPECTRA6["black"])
    draw = ImageDraw.Draw(image)
    _orbital_paint_sky(image, clock)
    _orbital_paint_sun(image, clock)
    _orbital_paint_arch(image, clock)
    _orbital_paint_land(image, clock)
    _orbital_paint_card(image, draw, quote_row, clock)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image



# ---------------------------------------------------------------------------
# trisolaris — Liu Cixin's *The Three-Body Problem* (三体, 2008)
# ---------------------------------------------------------------------------
# The Trisolaran sky, computed rather than drawn: three suns and a planet are
# integrated under Newtonian gravity from fixed initial conditions, and the
# clock advances the simulation (each dial minute is a fixed slice of simulated
# time). Every render shows where the suns have got to, with the last hour of
# their paths trailing behind.
#
# **The novel's mechanics come from the physics.** The era is read off the
# integration: *stable* when one sun's pull on the planet exceeds the next
# strongest by ``_TRISOLARIS_STABLE_DOMINANCE``, *chaotic* otherwise. When the
# planet falls into a sun or is flung out, that civilization ends: the planet is
# reborn in a circular orbit about the most isolated sun and the header counter
# advances. The planet's trail is broken at every rebirth so a teleport never
# draws as a streak.
#
# **Byte-identical everywhere.** Only ``+ - * /`` and ``math.sqrt`` are used,
# all correctly rounded under IEEE 754. Don't use ``**`` in the force law
# (``r2 * sqrt(r2)``, not ``r2 ** 1.5``): ``pow`` goes through libm, which need
# not round correctly. Kick-drift-kick leapfrog at a fixed step; forces are
# Plummer-softened because an adaptive step would make the frame depend on
# floating-point comparisons in a step controller.
#
# **The initial conditions were searched offline** for a start whose suns stay
# inside the sky all day and whose planet sees a mix of stable and chaotic eras
# and a handful of lost civilizations (a generic three-body system ejects a sun
# within a few dozen crossing times). ``TestTrisolarisEphemeris`` fences those
# properties against the committed constants.
#
# **Composition.** The orrery owns the left; at its foot the Red Coast Base dish
# on Radar Peak aims at the barycentre with wavefronts leaving its feed. The
# quote sits on the right under a ``三体`` masthead, the matched phrase lit as
# sunlight (yellow core in the bakelite split-band tangerine bloom), the prose
# solid white. Along the foot: DO NOT ANSWER.
#
# **The time.** The clock drives the simulation and the era label; no digit of
# the time is printed (the civilization number is a count of deaths). Composed
# at 800x480 and NEAREST-downsampled (the ``metro`` convention).
# ---------------------------------------------------------------------------
_TRISOLARIS_MASSES = (1.0, 0.85, 1.15)
_TRISOLARIS_INITIAL_SUNS = (
    (-0.7790231091549272, -1.123740528588034),
    (-0.6284556317938058, 0.7024334277767176),
    (1.141922083634489, 0.4579757521546296),
)
_TRISOLARIS_INITIAL_VELOCITIES = (
    (-0.42512274278402506, 0.1819496698677228),
    (0.3824413054486465, -0.3228627894307456),
    (0.08699794187189179, 0.08042060969427037),
)
_TRISOLARIS_INITIAL_PLANET = (-1.0330201690484344, -1.4173172376938314)
_TRISOLARIS_INITIAL_PLANET_VELOCITY = (0.7886371665064716, -0.8681726280332862)
_TRISOLARIS_SOFTENING2 = 0.02          # sun-sun Plummer softening, squared
_TRISOLARIS_PLANET_SOFTENING2 = 0.006  # planet-sun softening, squared
_TRISOLARIS_DT = 0.004
_TRISOLARIS_STEPS_PER_SAMPLE = 5
_TRISOLARIS_SAMPLES_PER_MINUTE = 4
_TRISOLARIS_PREROLL_MINUTES = 90       # so 12:00 already has a trail behind it
_TRISOLARIS_DIAL_MINUTES = 720
_TRISOLARIS_TRAIL_MINUTES = 60
_TRISOLARIS_BURN_RADIUS2 = 0.0049      # planet within 0.07 of a sun: consumed
_TRISOLARIS_LOST_RADIUS2 = 10.24       # planet beyond 3.2 of the barycentre: lost
_TRISOLARIS_REBIRTH_RADIUS = 0.3
_TRISOLARIS_STABLE_DOMINANCE = 4.0
_TRISOLARIS_FIRST_CIVILIZATION = 183

_TRISOLARIS_SKY = (146, 24, 436, 314)  # where the suns' whole-day paths are fitted, clear of the dish
_TRISOLARIS_ORRERY_CLIP = (0, 0, 446, 420)
_TRISOLARIS_COLUMN = (456, 780)        # the quote column's x extent
_TRISOLARIS_QUOTE_RECT = (456, 118, 780, 372)
_TRISOLARIS_DISH_X = 72                # the dish pedestal; its y comes from the ridge
_TRISOLARIS_SUN_RADII = (6, 5, 7)
_TRISOLARIS_STAR_SEED = 0x3B0D1E5
_TRISOLARIS_WARNING = "DO NOT ANSWER!"
_TRISOLARIS_WARNING_Y = 422

_TRISOLARIS_EPHEMERIS: tuple | None = None
_TRISOLARIS_PROJECTION: tuple | None = None


def _trisolaris_sun_accel(pos):
    """Softened pairwise gravity between the three suns (G = 1)."""
    m = _TRISOLARIS_MASSES
    ax = [0.0, 0.0, 0.0]
    ay = [0.0, 0.0, 0.0]
    for i in range(3):
        for j in range(i + 1, 3):
            dx = pos[j][0] - pos[i][0]
            dy = pos[j][1] - pos[i][1]
            r2 = dx * dx + dy * dy + _TRISOLARIS_SOFTENING2
            inv = 1.0 / (r2 * math.sqrt(r2))
            ax[i] += m[j] * dx * inv
            ay[i] += m[j] * dy * inv
            ax[j] -= m[i] * dx * inv
            ay[j] -= m[i] * dy * inv
    return ax, ay


def _trisolaris_planet_accel(p, pos):
    """Acceleration on the (massless) planet, plus each sun's pull strength —
    the latter is what the era is read from."""
    ax = ay = 0.0
    pulls = []
    for i in range(3):
        dx = pos[i][0] - p[0]
        dy = pos[i][1] - p[1]
        r2 = dx * dx + dy * dy + _TRISOLARIS_PLANET_SOFTENING2
        g = _TRISOLARIS_MASSES[i] / (r2 * math.sqrt(r2))
        ax += g * dx
        ay += g * dy
        pulls.append(_TRISOLARIS_MASSES[i] / r2)
    return ax, ay, pulls


def _trisolaris_rebirth(pos, vel):
    """A new civilization: a circular orbit about the most isolated sun — the
    one whose nearest neighbour is furthest away, which is where a planet has
    its best chance of a long stable era."""
    best, home = -1.0, 0
    for i in range(3):
        nearest = min((pos[i][0] - pos[j][0]) * (pos[i][0] - pos[j][0])
                      + (pos[i][1] - pos[j][1]) * (pos[i][1] - pos[j][1])
                      for j in range(3) if j != i)
        if nearest > best:
            best, home = nearest, i
    # Circular speed under the *softened* force law the planet actually feels:
    # v^2 / r = m r / (r^2 + eps^2)^(3/2). The Keplerian sqrt(m / r) is ~5% too
    # fast at this radius and starts every civilization on an eccentric orbit.
    r = _TRISOLARIS_REBIRTH_RADIUS
    q = r * r + _TRISOLARIS_PLANET_SOFTENING2
    speed = r * math.sqrt(_TRISOLARIS_MASSES[home] / (q * math.sqrt(q)))
    return ([pos[home][0] + _TRISOLARIS_REBIRTH_RADIUS, pos[home][1]],
            [vel[home][0], vel[home][1] + speed])


def _trisolaris_ephemeris() -> tuple:
    """The whole day's integration, computed once per process.

    Returns one sample per quarter-minute from the start of the preroll:
    ``(suns, planet, dominance, civilization)`` where ``suns`` is three
    ``(x, y)`` pairs, ``dominance`` is the strongest sun's pull over the next
    strongest, and ``civilization`` counts the planet's deaths so far. About a
    tenth of a second on a desktop; memoised because a contact sheet renders
    144 frames in one process.
    """
    global _TRISOLARIS_EPHEMERIS
    if _TRISOLARIS_EPHEMERIS is not None:
        return _TRISOLARIS_EPHEMERIS
    pos = [list(s) for s in _TRISOLARIS_INITIAL_SUNS]
    vel = [list(v) for v in _TRISOLARIS_INITIAL_VELOCITIES]
    p = list(_TRISOLARIS_INITIAL_PLANET)
    pv = list(_TRISOLARIS_INITIAL_PLANET_VELOCITY)
    ax, ay = _trisolaris_sun_accel(pos)
    pax, pay, pulls = _trisolaris_planet_accel(p, pos)
    half = 0.5 * _TRISOLARIS_DT
    dt = _TRISOLARIS_DT
    civilization = 0
    samples = []
    total = (_TRISOLARIS_PREROLL_MINUTES + _TRISOLARIS_DIAL_MINUTES) * _TRISOLARIS_SAMPLES_PER_MINUTE
    for _ in range(total):
        ranked = sorted(pulls, reverse=True)
        samples.append((tuple((s[0], s[1]) for s in pos), (p[0], p[1]),
                        ranked[0] / ranked[1], civilization))
        for _ in range(_TRISOLARIS_STEPS_PER_SAMPLE):
            for i in range(3):
                vel[i][0] += half * ax[i]
                vel[i][1] += half * ay[i]
            pv[0] += half * pax
            pv[1] += half * pay
            for i in range(3):
                pos[i][0] += dt * vel[i][0]
                pos[i][1] += dt * vel[i][1]
            p[0] += dt * pv[0]
            p[1] += dt * pv[1]
            ax, ay = _trisolaris_sun_accel(pos)
            pax, pay, pulls = _trisolaris_planet_accel(p, pos)
            for i in range(3):
                vel[i][0] += half * ax[i]
                vel[i][1] += half * ay[i]
            pv[0] += half * pax
            pv[1] += half * pay
            # Checked every step, not every sample: a fast pass can dip inside
            # the burn radius and back out between two samples.
            burned = any((p[0] - s[0]) * (p[0] - s[0]) + (p[1] - s[1]) * (p[1] - s[1])
                         < _TRISOLARIS_BURN_RADIUS2 for s in pos)
            lost = p[0] * p[0] + p[1] * p[1] > _TRISOLARIS_LOST_RADIUS2
            if burned or lost:
                civilization += 1
                p, pv = _trisolaris_rebirth(pos, vel)
                pax, pay, pulls = _trisolaris_planet_accel(p, pos)
    _TRISOLARIS_EPHEMERIS = tuple(samples)
    return _TRISOLARIS_EPHEMERIS


def _trisolaris_index(time_str: str) -> int:
    """Ephemeris index for a wall-clock time on the twelve-hour dial.

    Noon and midnight both start the dial, so 00:30 and 12:30 see the same sky.
    """
    try:
        hour, minute = (int(part) for part in time_str.split(":")[:2])
    except (ValueError, AttributeError):
        hour, minute = 0, 0
    dial = (hour % 12) * 60 + minute % 60
    return (_TRISOLARIS_PREROLL_MINUTES + dial) * _TRISOLARIS_SAMPLES_PER_MINUTE


def _trisolaris_projection() -> tuple[float, float, float]:
    """``(scale, offset_x, offset_y)`` fitting the suns' whole-day paths into
    ``_TRISOLARIS_SKY`` at one fixed scale, aspect preserved.

    Derived from the ephemeris rather than hardcoded so the fit cannot drift
    from the constants it depends on. The planet is left out of the fit on
    purpose: a lost planet flies far outside the system, and fitting it would
    shrink the suns to a cluster in the middle of the panel.
    """
    global _TRISOLARIS_PROJECTION
    if _TRISOLARIS_PROJECTION is not None:
        return _TRISOLARIS_PROJECTION
    xs = [s[0] for sample in _trisolaris_ephemeris() for s in sample[0]]
    ys = [s[1] for sample in _trisolaris_ephemeris() for s in sample[0]]
    x0, y0, x1, y1 = _TRISOLARIS_SKY
    scale = min((x1 - x0) / (max(xs) - min(xs)), (y1 - y0) / (max(ys) - min(ys)))
    ox = (x0 + x1) / 2 - scale * (max(xs) + min(xs)) / 2
    oy = (y0 + y1) / 2 - scale * (max(ys) + min(ys)) / 2
    _TRISOLARIS_PROJECTION = (scale, ox, oy)
    return _TRISOLARIS_PROJECTION


def _trisolaris_project(point) -> tuple[float, float]:
    scale, ox, oy = _trisolaris_projection()
    return ox + scale * point[0], oy + scale * point[1]


def _trisolaris_era(time_str: str) -> tuple[bool, int]:
    """``(stable, civilization_number)`` at ``time_str``."""
    sample = _trisolaris_ephemeris()[_trisolaris_index(time_str)]
    return sample[2] > _TRISOLARIS_STABLE_DOMINANCE, _TRISOLARIS_FIRST_CIVILIZATION + sample[3]


def _trisolaris_ridge_y(x: float) -> int:
    """Radar Peak's skyline: high on the left where the dish stands, falling
    away under the quote column. Two incommensurate sines keep it from reading
    as a ruled curve."""
    fall = min(1.0, max(0.0, (x - 60) / 480))
    base = 392 + 62 * fall * fall * (3 - 2 * fall)
    peak = 16 * math.exp(-((x - _TRISOLARIS_DISH_X) / 70.0) ** 2)
    return int(base - peak + 6 * math.sin(x * 0.031) + 4 * math.sin(x * 0.087 + 1.3))


def _trisolaris_paint_sky(image: Image.Image) -> None:
    """Black space and a seeded star field, one star in five a blue one.

    Stars stay out of the whole text column (masthead, quote, byline and
    warning), where a stray white pixel beside a letterform reads as a stroke.
    """
    draw = ImageDraw.Draw(image)
    draw.rectangle((0, 0, 799, 479), fill=SPECTRA6["black"])
    px = image.load()
    rng = random.Random(_TRISOLARIS_STAR_SEED)
    column_x0 = _TRISOLARIS_COLUMN[0] - 10
    for _ in range(230):
        x = int(rng.random() * 800)
        y = int(rng.random() * 440)
        big = rng.random() < 0.1
        blue = rng.random() < 0.18
        if x >= column_x0 - 1:
            continue
        if y >= _trisolaris_ridge_y(x) - 4:
            continue
        ink = SPECTRA6["blue"] if blue else SPECTRA6["white"]
        if big:
            draw.rectangle((x, y, x + 1, y + 1), fill=ink)
        else:
            px[x, y] = ink


def _trisolaris_stipple_line(px, points, *, salt: int, keep: float = 1.0, width: int = 1,
                             ink=None, hot: float = 0.0, clip=(0, 0, 800, 480)) -> None:
    """Stipple a polyline: each pixel along it survives with probability
    ``keep`` (a position hash, so it is deterministic), clipped to ``clip``.

    ``ink=None`` paints tangerine — yellow with probability
    ``hot + (1 - hot) * 3/8``, red otherwise — so a warm line reads as warm
    even at ``hot=0``, where solid red would sit within a few luminance points
    of the panel's black. Every warm line on the frame (sun wakes, the ridge,
    the transmission) goes through here; ``hot`` is how a sun's wake starts
    yellow at the sun and cools toward the 3/8 floor as it ages.
    """
    cx0, cy0, cx1, cy1 = clip
    warm_share = hot + (1.0 - hot) * 0.375
    for (ax, ay), (bx, by) in zip(points, points[1:]):
        steps = int(max(abs(bx - ax), abs(by - ay))) + 1
        for k in range(steps + 1):
            t = k / steps
            x0 = int(ax + (bx - ax) * t)
            y0 = int(ay + (by - ay) * t)
            for dy in range(width):
                x, y = x0, y0 + dy
                if not (cx0 <= x < cx1 and cy0 <= y < cy1) or _flow_stroke_hash(x, y, salt) >= keep:
                    continue
                if ink is None:
                    warm = _flow_stroke_hash(x, y, salt + 100) < warm_share
                    px[x, y] = SPECTRA6["yellow"] if warm else SPECTRA6["red"]
                else:
                    px[x, y] = ink


def _trisolaris_paint_orbits(image: Image.Image, index: int) -> None:
    """The last hour of each body's path, cooling as it ages.

    A sun's trail starts yellow and cools to tangerine over its first 40%,
    thinning toward the oldest end. The planet's trail is sparse white and drawn
    only back to its most recent rebirth, so the jump to a new orbit never draws.
    """
    px = image.load()
    ephemeris = _trisolaris_ephemeris()
    span = _TRISOLARIS_TRAIL_MINUTES * _TRISOLARIS_SAMPLES_PER_MINUTE
    start = max(1, index - span)
    for k in range(start, index + 1):
        age = (index - k) / span
        keep = 0.85 - 0.7 * age
        before, after = ephemeris[k - 1], ephemeris[k]
        for i in range(3):
            segment = [_trisolaris_project(before[0][i]), _trisolaris_project(after[0][i])]
            _trisolaris_stipple_line(px, segment, salt=40 + i, keep=keep,
                                     hot=max(0.0, 1.0 - age * 2.5), clip=_TRISOLARIS_ORRERY_CLIP)
        if before[3] == ephemeris[index][3]:
            segment = [_trisolaris_project(before[1]), _trisolaris_project(after[1])]
            _trisolaris_stipple_line(px, segment, salt=47, keep=keep * 0.7,
                                     ink=SPECTRA6["white"], clip=_TRISOLARIS_ORRERY_CLIP)


def _trisolaris_paint_bodies(image: Image.Image, index: int) -> None:
    """Three suns as gold blooms, then the planet as a blue world with a white
    lit limb. The suns share one mask so two near each other merge into one
    glare rather than double-exposing. The halo is confined to empty sky, so
    it dims into the trails and the dish rather than painting over them."""
    sample = _trisolaris_ephemeris()[index]
    mask = Image.new("L", image.size, 0)
    mdraw = ImageDraw.Draw(mask)
    for (sx, sy), radius in zip((_trisolaris_project(s) for s in sample[0]), _TRISOLARIS_SUN_RADII):
        mdraw.ellipse((sx - radius, sy - radius, sx + radius, sy + radius), fill=255)
    paint_neon_mask(
        image, mask, SPECTRA6["yellow"], SPECTRA6["red"],
        radius=6, gamma=1.3, cap=0.75, tile=BAYER_8x8,
        glow_minor=SPECTRA6["yellow"], glow_minor_share=0.375,
        core_minor=SPECTRA6["white"], core_minor_share=0.25,
        # Only onto empty sky: a sun passing the lower-left of the sky box
        # would otherwise stipple its halo over the dish's wavefront arcs.
        ground=frozenset({SPECTRA6["black"], SPECTRA6["blue"]}),
    )
    x, y = _trisolaris_project(sample[1])
    cx0, cy0, cx1, cy1 = _TRISOLARIS_ORRERY_CLIP
    if cx0 + 4 <= x < cx1 - 4 and cy0 + 4 <= y < cy1 - 4:
        draw = ImageDraw.Draw(image)
        draw.ellipse((x - 4, y - 4, x + 4, y + 4), fill=SPECTRA6["blue"], outline=SPECTRA6["white"])


def _trisolaris_dish_geometry(ridge_top: int):
    """Pedestal polygon, dish polygon, feed tip and aim for the Red Coast
    antenna.

    The dish is a parabolic section in profile: the reflecting face curves
    toward the aim, and the back is thickest at the vertex and thins to the
    rim, so the silhouette reads as a bowl rather than a flat plate.
    """
    x = _TRISOLARIS_DISH_X
    pivot = (x, ridge_top - 46)
    pedestal = [(x - 20, ridge_top + 6), (x - 7, pivot[1] + 4), (x + 7, pivot[1] + 4),
                (x + 20, ridge_top + 6)]
    # Aimed at the system's barycentre — the origin of the integration's
    # coordinates, since the initial conditions carry zero total momentum —
    # so the transmission points where the three suns actually dance.
    tx, ty = _trisolaris_project((0.0, 0.0))
    aim = math.atan2(ty - pivot[1], tx - pivot[0])
    ux, uy = math.cos(aim), math.sin(aim)         # along the dish axis
    vx, vy = -uy, ux                              # across the aperture
    half, depth, back = 46, 21, 9
    face, rear = [], []
    for k in range(-12, 13):
        s = k / 12.0
        d = depth * s * s
        face.append((pivot[0] + half * s * vx + d * ux, pivot[1] + half * s * vy + d * uy))
        b = d - back * (1 - s * s)
        rear.append((pivot[0] + half * s * vx + b * ux, pivot[1] + half * s * vy + b * uy))
    feed = (pivot[0] + 40 * ux, pivot[1] + 40 * uy)
    return pedestal, face, rear, pivot, feed, (ux, uy)


def _trisolaris_paint_red_coast(image: Image.Image) -> None:
    """Radar Peak and the Red Coast dish, drawn as line-work.

    The ridge is a tangerine crest line with two fainter contours behind it,
    black below; the dish is white line-work (face, back, feed struts,
    pedestal). Don't make it a black silhouette on a dusk glow: the glow reads
    as a dune field and the dish vanishes. Line-work also matches the orrery.

    The transmission is a fan of wavefront arcs off the feed, thinning as they
    spread; a straight line to the suns reads as one more orbit trail.
    """
    draw = ImageDraw.Draw(image)
    skyline = [(x, _trisolaris_ridge_y(x)) for x in range(0, 801, 4)]
    draw.polygon(skyline + [(800, 480), (0, 480)], fill=SPECTRA6["black"])
    px = image.load()
    _trisolaris_stipple_line(px, skyline, salt=61, width=2)
    for step, keep in ((11, 0.55), (24, 0.3)):
        contour = [(x, _trisolaris_ridge_y(x) + step + int(3 * math.sin(x * 0.05 + step)))
                   for x in range(0, 801, 4)]
        _trisolaris_stipple_line(px, contour, salt=63 + step, keep=keep)

    ridge_top = _trisolaris_ridge_y(_TRISOLARIS_DISH_X)
    pedestal, face, rear, pivot, feed, (ux, uy) = _trisolaris_dish_geometry(ridge_top)
    white = SPECTRA6["white"]
    draw.polygon(pedestal, fill=SPECTRA6["black"], outline=white)
    draw.line([(pivot[0] - 4, pivot[1] + 4), (pedestal[0][0] + 6, ridge_top), (pedestal[3][0] - 6, pivot[1] + 12)],
              fill=white, width=1)
    outline = [(round(a), round(b)) for a, b in face + rear[::-1]]
    draw.polygon(outline, fill=SPECTRA6["black"])
    draw.line([(round(a), round(b)) for a, b in face], fill=white, width=2)
    draw.line([(round(a), round(b)) for a, b in rear], fill=white, width=1)
    for strut in (face[0], face[-1]):
        draw.line([strut, feed], fill=white, width=1)
    draw.ellipse((feed[0] - 2, feed[1] - 2, feed[0] + 2, feed[1] + 2), fill=SPECTRA6["yellow"])

    aim = math.atan2(uy, ux)
    for ring, radius in enumerate(range(16, 76, 12)):
        keep = 0.95 - 0.16 * ring
        spread = math.radians(16 + 4 * ring)
        steps = int(radius * spread * 2) + 1
        arc = [(feed[0] + radius * math.cos(aim - spread + 2 * spread * k / steps),
                feed[1] + radius * math.sin(aim - spread + 2 * spread * k / steps))
               for k in range(steps + 1)]
        _trisolaris_stipple_line(px, arc, salt=91 + ring, keep=keep)


def _trisolaris_paint_header(draw: ImageDraw.ImageDraw, time_str: str) -> None:
    """``三体`` masthead, the title, the civilization number and the era.

    The era carries its own glyph: three small discs for the three suns, one
    filled in a stable era (the planet has a sun of its own) and all three in
    a chaotic one.
    """
    stable, civilization = _trisolaris_era(time_str)
    col_x0, col_x1 = _TRISOLARIS_COLUMN
    han = load_font([YUJI_BOKU_REGULAR, *META_FONT_BOLD_CANDIDATES], 46)
    draw.text((col_x0, 22), "三体", font=han, fill=SPECTRA6["white"])
    han_w = draw.textlength("三体", font=han)
    chrome = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], 11)
    x = col_x0 + han_w + 14
    draw_tracked(draw, (x, 28), "THE THREE-BODY PROBLEM", chrome, SPECTRA6["white"], tracking=1)
    draw_tracked(draw, (x, 47), f"CIVILIZATION NO. {civilization}", chrome, SPECTRA6["yellow"], tracking=1)
    era = "STABLE ERA · REHYDRATE" if stable else "CHAOTIC ERA · DEHYDRATE"
    draw_tracked(draw, (x, 66), era, chrome, SPECTRA6["white"] if stable else SPECTRA6["yellow"], tracking=1)
    # A dotted rule closes the header, ending in the era glyph.
    glyph_x0 = col_x1 - 40
    for xx in range(col_x0, glyph_x0 - 6, 4):
        draw.point((xx, 100), fill=SPECTRA6["white"])
    for k in range(3):
        cx = glyph_x0 + 4 + k * 14
        filled = (not stable) or k == 0
        draw.ellipse((cx - 4, 96, cx + 4, 104), fill=SPECTRA6["yellow"] if filled else None,
                     outline=SPECTRA6["yellow"])


def _trisolaris_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> int:
    """The quote in the dark sky: solid white prose, the matched phrase lit as
    sunlight. Returns the block's bottom y.

    The prose is deliberately unlit: even a faint blue halo reads as an
    outline round every letter.
    """
    prose, hot, bottom = wrap_quote_into_masks(
        draw, image.size, quote_row, _TRISOLARIS_QUOTE_RECT, theme="trisolaris",
        font_max=30, font_min=14, line_height_mult=1.32,
    )
    image.paste(SPECTRA6["white"], (0, 0), prose.point(lambda v: 255 if v > 128 else 0))
    paint_neon_mask(
        image, hot, SPECTRA6["yellow"], SPECTRA6["red"],
        radius=4, gamma=1.5, cap=0.6, ground=frozenset({SPECTRA6["black"], SPECTRA6["blue"]}),
        tile=BAYER_8x8,
        glow_minor=SPECTRA6["yellow"], glow_minor_share=0.375,
    )
    return bottom


def _trisolaris_paint_credits(draw: ImageDraw.ImageDraw, quote_row: dict, top: int) -> None:
    col_x0, col_x1 = _TRISOLARIS_COLUMN
    font = load_font([TITILLIUM_ITALIC, *META_FONT_CANDIDATES], 15)
    draw_truncated_centred_byline(draw, quote_row, centre=(col_x0 + col_x1) // 2,
                                  baseline=min(412, top + 26), max_width=col_x1 - col_x0,
                                  font=font, fill=SPECTRA6["white"])


def _trisolaris_paint_warning(draw: ImageDraw.ImageDraw) -> None:
    """The pacifist's reply, three times along the foot.

    Solid yellow, not red: at 11px red barely clears the panel's black, and a
    two-ink tangerine shreds a letterform that small.
    """
    col_x0, col_x1 = _TRISOLARIS_COLUMN
    font = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], 11)
    for repeats in (3, 2, 1):
        text = "  ".join([_TRISOLARIS_WARNING] * repeats)
        width = draw.textlength(text, font=font)
        if width <= col_x1 - col_x0:
            break
    draw.text(((col_x0 + col_x1 - width) / 2, _TRISOLARIS_WARNING_Y), text, font=font, fill=SPECTRA6["yellow"])


def render_trisolaris_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """The Trisolaran sky (see the module section comment above)."""
    index = _trisolaris_index(time_str)
    image = Image.new("RGB", (800, 480), color=SPECTRA6["black"])
    _trisolaris_paint_sky(image)
    _trisolaris_paint_orbits(image, index)
    _trisolaris_paint_red_coast(image)
    _trisolaris_paint_bodies(image, index)
    draw = ImageDraw.Draw(image)
    _trisolaris_paint_header(draw, time_str)
    bottom = _trisolaris_paint_quote(image, draw, quote_row)
    _trisolaris_paint_credits(draw, quote_row, bottom)
    _trisolaris_paint_warning(draw)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# biomech — H. R. Giger's biomechanical wall round a Beksiński dusk
# ---------------------------------------------------------------------------
# A pointed arch cut through a Giger wall (airbrushed bone-and-chrome
# machinery: *surface*) and through it a Beksiński evening (burning dusk,
# ruined cathedral, leaning crosses: *distance*).
#
# **Two render-time "plates", neither committed.** Unlike the themes that ship
# a PNG, both plates are painted procedurally in continuous tone and dithered
# in-process:
#
# * **The wall is a lit height field** (``shade_height_field``). Blurred shapes
#   unioned with ``ImageChops.lighter`` give rounded profiles (a blurred line is
#   a tube, a blurred ellipse a dome); ``ImageChops.subtract`` carves sockets
#   and hose grooves. Shaded Blinn-Phong from the upper left, darkened by
#   height and a cavity term, then Floyd-Steinberg-dithered to **white + black
#   only**: a neutral grey is nearly equidistant from K, W *and* R in RGB, so a
#   four-ink dither would scatter red specks through the bone.
# * **The red is rim light, not pigment.** A second pass lights the wall from
#   the portal and stipples red where that light rakes a surface (``BAYER_8x8``
#   threshold), so the sky is reflected on the machinery and the two halves read
#   as one space.
# * **The dusk is painted, then dithered to K/R/Y/W**: a per-row gradient,
#   streaked cloud noise, a half-set sun, silhouettes in atmospheric
#   perspective and a low fog. Blue and green are left out so error diffusion
#   cannot cool the fire.
#
# Both plates are quote-independent, so the background is built once per
# process (``_BIOMECH_BACKGROUND``) and each render pastes text over a copy.
#
# **The quote** sits in the near-black upper sky: bone-white Spectral with a
# 2 px black halo (not a panel, so the arch keeps its view), the matched phrase
# an ember (yellow core, red bloom with ``ground`` pinned to black).
#
# **The time is the plate's title, hour only** (``BIOMECHANOID · XI`` on the
# sill's cartouche, after Giger's numbered series); pinned byte-identical
# across the minutes of an hour by ``TestBiomechFrame``.
#
# Composed at 800x480 and NEAREST-downsampled (the ``metro`` convention).
# ---------------------------------------------------------------------------
_BIOMECH_ARCH = (126, 674, 96, 12, 452)     # left x, right x, springline y, apex y, sill y
_BIOMECH_QUOTE_RECT = (172, 58, 628, 262)
_BIOMECH_HORIZON = 372
_BIOMECH_SUN = (402, 356, 42)               # centre x, centre y, radius
_BIOMECH_BYLINE_BASELINE = 440
_BIOMECH_PLATE = (306, 457, 494, 477)
_BIOMECH_SEED = 0xB10
_BIOMECH_SCENE_PALETTE = [SPECTRA6["black"], SPECTRA6["red"], SPECTRA6["yellow"], SPECTRA6["white"]]
_BIOMECH_WALL_PALETTE = [SPECTRA6["black"], SPECTRA6["white"]]
# The dusk, as (y, rgb) stops interpolated per row: a near-black zenith the
# quote can sit on, a blood-red middle sky, a molten band at the horizon, and
# a ground that falls back to black toward the sill.
_BIOMECH_SKY_STOPS = (
    (0, (0, 0, 0)), (168, (0, 0, 0)), (236, (52, 3, 2)), (292, (138, 14, 6)),
    (334, (206, 58, 12)), (360, (246, 140, 36)), (_BIOMECH_HORIZON, (255, 196, 92)),
)
_BIOMECH_GROUND_STOPS = ((_BIOMECH_HORIZON, (96, 16, 6)), (404, (34, 4, 2)), (480, (4, 0, 0)))
# The ruined cathedral's spires, as (centre x, half width, top y). The tallest
# stands in front of the sun so it reads against the brightest thing on the page.
_BIOMECH_SPIRES = (
    (344, 3, 328), (356, 5, 306), (368, 3, 320), (381, 6, 292), (402, 9, 268),
    (421, 5, 296), (434, 3, 318), (447, 5, 304), (459, 3, 330),
)
# Crosses on the horizon to the left, as (x, height, lean): stood against the
# brightest band of sky so a thin black stroke still reads.
_BIOMECH_CROSSES = ((172, 30, -3), (206, 24, 2), (236, 19, -2), (262, 15, 3), (284, 12, -1), (302, 9, 1))
_BIOMECH_BACKGROUND: dict = {}


def _biomech_arch_halfwidth(y: float) -> float:
    """Half the opening's width at row ``y``: straight piers below the
    springline, then a curve that closes to a point at the apex."""
    left, right, spring, apex, _ = _BIOMECH_ARCH
    half = (right - left) / 2
    if y >= spring:
        return half
    if y <= apex:
        return 0.0
    t = (spring - y) / (spring - apex)
    return half * (1 - t ** 1.7) ** 0.62


def _biomech_arch_outline(offset: float = 0.0) -> list[tuple[float, float]]:
    """The opening's edge from the left sill up over the apex to the right
    sill, pushed ``offset`` px outward (into the wall)."""
    left, right, spring, apex, sill = _BIOMECH_ARCH
    cx = (left + right) / 2
    ys = [sill - i for i in range(0, int(sill - apex) + 1, 4)] + [apex]
    side = [(cx - _biomech_arch_halfwidth(y) - offset, y) for y in ys]
    side[-1] = (cx, apex - offset)
    return side + [(2 * cx - x, y) for x, y in reversed(side[:-1])]


def _biomech_opening_mask(size) -> Image.Image:
    mask = Image.new("L", size, 0)
    ImageDraw.Draw(mask).polygon([(round(x), round(y)) for x, y in _biomech_arch_outline()], fill=255)
    return mask


def _biomech_haze(colour, amount: float):
    """Black pushed ``amount`` of the way toward ``colour`` — how far a
    silhouette has dissolved into the air in front of it."""
    return tuple(round(c * amount) for c in colour)


def _biomech_paint_sky(image: Image.Image) -> None:
    """The dusk and the ground: per-row gradient, streaked cloud, a half-set sun."""
    width, height = image.size
    column = Image.new("RGB", (1, height))
    for y in range(height):
        stops = _BIOMECH_SKY_STOPS if y <= _BIOMECH_HORIZON else _BIOMECH_GROUND_STOPS
        column.putpixel((0, y), _lerp_stops(stops, y))
    base = column.resize((width, height), Image.Resampling.NEAREST)

    # Cloud: long horizontal streaks, brightening and darkening the middle sky
    # only — the zenith stays black for the quote, the horizon stays molten.
    envelope = Image.new("L", (1, height))
    for y in range(height):
        e = 0.0
        if 170 < y < _BIOMECH_HORIZON:
            e = math.sin(math.pi * (y - 170) / (_BIOMECH_HORIZON - 170)) ** 1.4
        envelope.putpixel((0, y), round(255 * e))
    envelope = envelope.resize((width, height), Image.Resampling.NEAREST)
    streaks = _smooth_noise((width, height), (9, 38), _BIOMECH_SEED)
    light = ImageChops.multiply(streaks.point(lambda v: max(0, v - 132) * 3), envelope)
    dark = ImageChops.multiply(streaks.point(lambda v: max(0, 112 - v) * 3), envelope)
    bright = ImageEnhance.Brightness(base).enhance(1.9)
    image.paste(Image.composite(bright, base, light))
    image.paste(Image.composite(ImageEnhance.Brightness(image).enhance(0.35), image, dark))

    # Sun: a wide glow and a pale disc, half set behind the horizon.
    sx, sy, sr = _BIOMECH_SUN
    glow = Image.new("L", (width, height), 0)
    ImageDraw.Draw(glow).ellipse((sx - sr * 2.6, sy - sr * 2.2, sx + sr * 2.6, sy + sr * 2.2), fill=150)
    sky = Image.new("L", (width, height), 0)
    ImageDraw.Draw(sky).rectangle((0, 0, width, _BIOMECH_HORIZON), fill=255)
    glow = ImageChops.multiply(glow.filter(ImageFilter.GaussianBlur(sr)), sky)
    image.paste(Image.composite(Image.new("RGB", (width, height), (255, 214, 120)), image, glow))
    disc = Image.new("L", (width, height), 0)
    ImageDraw.Draw(disc).ellipse((sx - sr, sy - sr, sx + sr, sy + sr), fill=255)
    image.paste((255, 244, 206), (0, 0), ImageChops.multiply(disc.filter(ImageFilter.GaussianBlur(2)), sky))


def _biomech_paint_landscape(image: Image.Image) -> None:
    """Beksiński's distance: a far ridge, a cathedral of bone spires against
    the sun, a shrouded giant, leaning crosses, then a fog over the horizon."""
    width, height = image.size
    draw = ImageDraw.Draw(image)
    hz = _BIOMECH_HORIZON
    horizon_sky = _lerp_stops(_BIOMECH_SKY_STOPS, 330)
    rng = random.Random(_BIOMECH_SEED)

    # Far ridge: a low ragged line, most dissolved into the air.
    ridge = [(0, hz + 2)]
    for x in range(0, width + 12, 12):
        ridge.append((x, hz - 2 - rng.random() * 9 - (7 if 520 < x < 640 else 0)))
    ridge.append((width, hz + 2))
    draw.polygon([(round(x), round(y)) for x, y in ridge], fill=_biomech_haze(horizon_sky, 0.52))

    # The shrouded giant, right of centre: a hooded figure, half-hazed.
    gx, top = 574, 280
    giant = _biomech_haze(horizon_sky, 0.26)
    draw.ellipse((gx - 6, top, gx + 8, top + 16), fill=giant)             # hood
    shroud = [(gx - 5, top + 10), (gx + 9, top + 9), (gx + 13, top + 26), (gx + 12, top + 60),
              (gx + 19, hz)]
    for i in range(8):
        shroud.append((gx + 19 - i * 5, hz - (3 if i % 2 else 10)))
    shroud += [(gx - 21, hz - 5), (gx - 13, top + 58), (gx - 11, top + 26)]
    draw.polygon([(round(x), round(y)) for x, y in shroud], fill=giant)

    # The cathedral: organ-pipe spires of bone, eroded and thorned, a low
    # nave, lancets lit by the sun behind.
    near = (6, 1, 0)
    draw.polygon([(330, hz + 3), (336, 346), (350, 336), (452, 336), (468, 348), (474, hz + 3)], fill=near)
    for cx, hw, sy in _BIOMECH_SPIRES:
        jag = rng.random() * 4
        draw.polygon([(cx - hw, hz + 3), (cx - hw, sy + hw * 5), (cx - hw * 0.4, sy + hw * 2 + jag),
                      (cx, sy), (cx + hw * 0.5, sy + hw * 2), (cx + hw, sy + hw * 5 + jag),
                      (cx + hw, hz + 3)], fill=near)
        for k in range(4):                                          # thorns
            ty = sy + hw * 5 + 8 + k * 11
            if ty < 336:
                side = -1 if (k + cx) % 2 else 1
                draw.polygon([(cx + side * hw, ty), (cx + side * (hw + 4), ty - 7),
                              (cx + side * hw, ty + 3)], fill=near)
    for wx in (356, 381, 402, 421, 447):                            # lancets, lit from behind
        draw.polygon([(wx - 2, 362), (wx - 2, 350), (wx, 345), (wx + 2, 350), (wx + 2, 362)],
                     fill=(250, 170, 50))

    # Crosses on the horizon, leaning, receding.
    for cx, h, lean in _BIOMECH_CROSSES:
        w = 2 if h > 16 else 1
        draw.line([(cx, hz + 1), (cx + lean, hz - h)], fill=near, width=w)
        ay = hz - h * 0.72
        arm = h * 0.3
        draw.line([(cx + lean * 0.7 - arm, ay), (cx + lean * 0.7 + arm, ay - lean * 0.3)], fill=near, width=w)

    # Fog: a low band across the horizon, streaked, veiling every base.
    fog = Image.new("L", (1, height))
    for y in range(height):
        fog.putpixel((0, y), round(150 * math.exp(-((y - hz + 2) / 9.0) ** 2)))
    fog = ImageChops.multiply(fog.resize((width, height), Image.Resampling.NEAREST),
                              _smooth_noise((width, height), (14, 60), _BIOMECH_SEED + 1))
    fog = fog.point(lambda v: min(255, v * 2))
    image.paste(Image.composite(Image.new("RGB", (width, height), (168, 40, 14)), image, fog))


def _biomech_layer(size, paint, blur: float, peak: int) -> Image.Image:
    """One form of the wall: painted solid, blurred into a rounded profile,
    scaled to its height. ``paint`` receives an ``ImageDraw`` on an ``"L"`` layer."""
    layer = Image.new("L", size, 0)
    paint(ImageDraw.Draw(layer))
    layer = layer.filter(ImageFilter.GaussianBlur(blur))
    return layer if peak >= 255 else layer.point(lambda v: v * peak // 255)


def _biomech_resample(points, step: float):
    """Points every ``step`` px of arc length along a polyline, with the unit
    normal there — where a corrugated hose's grooves go."""
    out = []
    carry = 0.0
    for (x0, y0), (x1, y1) in zip(points, points[1:]):
        seg = math.hypot(x1 - x0, y1 - y0)
        if seg == 0:
            continue
        ux, uy = (x1 - x0) / seg, (y1 - y0) / seg
        d = carry
        while d < seg:
            out.append((x0 + ux * d, y0 + uy * d, -uy, ux))
            d += step
        carry = d - seg
    return out


def _biomech_hose(size, points, width: int, peak: int, pitch: float) -> Image.Image:
    """A corrugated hose: a blurred line for the tube, grooves carved across
    it every ``pitch`` px so the light picks out each rib."""
    pts = [(round(x), round(y)) for x, y in points]
    tube = _biomech_layer(size, lambda d: d.line(pts, fill=255, width=width, joint="curve"),
                          width * 0.26, peak)
    if pitch:
        half = width / 2 + 1
        grooves = _biomech_layer(size, lambda d: [
            d.line([(round(x - nx * half), round(y - ny * half)), (round(x + nx * half), round(y + ny * half))],
                   fill=255, width=2)
            for x, y, nx, ny in _biomech_resample(points, pitch)], 0.8, int(peak * 0.3))
        tube = ImageChops.subtract(tube, grooves)
    return tube


def _biomech_skull(size, cx: int, top: int) -> Image.Image:
    """An elongated skull crowning a pier: cranium dome, carved sockets, a
    nasal cavity and a row of teeth."""
    head = _biomech_layer(size, lambda d: (
        d.ellipse((cx - 32, top, cx + 32, top + 70), fill=255),
        d.ellipse((cx - 24, top + 46, cx + 24, top + 92), fill=255)), 5, 236)
    sockets = _biomech_layer(size, lambda d: (
        d.ellipse((cx - 23, top + 44, cx - 5, top + 62), fill=255),
        d.ellipse((cx + 5, top + 44, cx + 23, top + 62), fill=255),
        d.polygon([(cx - 4, top + 72), (cx + 4, top + 72), (cx, top + 64)], fill=255)), 2.2, 220)
    head = ImageChops.subtract(head, sockets)
    teeth = _biomech_layer(size, lambda d: [
        d.rounded_rectangle((cx - 15 + i * 6, top + 78, cx - 11 + i * 6, top + 89), radius=2, fill=255)
        for i in range(6)], 1.0, 250)
    return ImageChops.lighter(head, teeth)


def _biomech_vertebrae(size, cx: int, y0: int, y1: int, pitch: int) -> Image.Image:
    """A spinal column: stacked vertebral bodies, each with a spinous knob and
    two transverse processes swept downward."""
    def paint_bodies(d):
        for y in range(y0, y1, pitch):
            d.rounded_rectangle((cx - 23, y - 10, cx + 23, y + 10), radius=9, fill=255)

    def paint_processes(d):
        for y in range(y0, y1, pitch):
            for s in (-1, 1):
                d.line([(cx + s * 20, y), (cx + s * 40, y + 7), (cx + s * 46, y + 14)], fill=255, width=6,
                       joint="curve")

    def paint_knobs(d):
        for y in range(y0, y1, pitch):
            d.ellipse((cx - 7, y - 7, cx + 7, y + 7), fill=255)

    bodies = _biomech_layer(size, paint_bodies, 3.6, 214)
    processes = _biomech_layer(size, paint_processes, 2.0, 176)
    knobs = _biomech_layer(size, paint_knobs, 2.0, 250)
    return ImageChops.lighter(ImageChops.lighter(bodies, processes), knobs)


def _biomech_height_field(size, opening: Image.Image) -> Image.Image:
    """The Giger wall as heights: a textured ground plane, then piers of
    vertebrae and hoses crowned by skulls, a ribbed archivolt round the
    opening, tendrils in the spandrels and a hose along the sill."""
    width, height = size
    left, right, _, _, sill = _BIOMECH_ARCH
    wall = ImageOps.invert(opening)
    grain = _smooth_noise(size, (width // 3, height // 3), _BIOMECH_SEED + 2)
    flesh = _smooth_noise(size, (width // 26, height // 26), _BIOMECH_SEED + 3)
    ground = ImageChops.add(grain.point(lambda v: v * 34 // 255), flesh.point(lambda v: 40 + v * 60 // 255))
    field = ImageChops.multiply(ground, wall.filter(ImageFilter.GaussianBlur(2)))

    forms = []
    for cx in (left // 2, (right + width) // 2):
        forms.append(_biomech_skull(size, cx, 8))
        forms.append(_biomech_vertebrae(size, cx, 118, sill - 6, 27))
        for dx, phase in ((-47, 0.0), (47, 1.7)):
            pts = [(cx + dx + 4 * math.sin(y / 23 + phase), y) for y in range(96, sill + 4, 6)]
            forms.append(_biomech_hose(size, pts, 14, 224, 6))
    rim = _biomech_arch_outline(9)
    forms.append(_biomech_hose(size, rim, 15, 244, 13))
    forms.append(_biomech_hose(size, _biomech_arch_outline(31), 12, 214, 6))
    # Spandrel tendrils: hoses sweeping out of the top edge and down the arch.
    for sx, ex, drop in ((140, 262, 46), (178, 330, 22), (660, 538, 46), (622, 470, 22)):
        pts = [(sx + (ex - sx) * t, -8 + drop * t * t + 6 * math.sin(t * 6)) for t in [i / 20 for i in range(21)]]
        forms.append(_biomech_hose(size, pts, 12, 206, 5))
    forms.append(_biomech_hose(size, [(-10, sill + 16), (width + 10, sill + 16)], 20, 230, 6))
    for form in forms:
        field = ImageChops.lighter(field, form)
    # Nothing of the wall stands inside the opening, but the rim may overhang it.
    return ImageChops.multiply(field, ImageChops.lighter(wall, _biomech_rim_overhang(size)))


def _biomech_rim_overhang(size) -> Image.Image:
    """The archivolt's inner lip: a band just inside the opening where the
    rim is allowed to overhang the view."""
    band = Image.new("L", size, 0)
    ImageDraw.Draw(band).line([(round(x), round(y)) for x, y in _biomech_arch_outline(9)],
                              fill=255, width=26, joint="curve")
    return band


def _biomech_paint_wall(image: Image.Image, opening: Image.Image) -> None:
    """Shade the height field, dither it to K+W, stipple in the red rim light
    from the portal, and lay it over the scene outside the opening."""
    size = image.size
    width = size[0]
    field = _biomech_height_field(size, opening)
    tone = shade_height_field(field, relief=0.03, ambient=0.06, diffuse=0.9, specular=0.85, shininess=22)
    # Recesses fall to black: the ground plane sits low and dark, only the
    # forms stand up into the light.
    depth = field.point(lambda v: round(255 * min(1.0, max(0.0, v - 28) / 172) ** 1.25))
    cavity = ImageChops.subtract(field.filter(ImageFilter.GaussianBlur(5)), field)
    tone = ImageChops.multiply(tone, depth)
    tone = ImageChops.multiply(tone, cavity.point(lambda v: 255 - min(255, v * 5)))
    wall = dither_image_to_palette(tone.convert("RGB"), _BIOMECH_WALL_PALETTE)

    # Rim light from the fire: each pier lit from the portal side, low.
    rim_l = shade_height_field(field, light=(0.9, 0.25, 0.25), relief=0.03,
                               ambient=0.0, diffuse=1.0, specular=0.0, shininess=1)
    rim_r = shade_height_field(field, light=(-0.9, 0.25, 0.25), relief=0.03,
                               ambient=0.0, diffuse=1.0, specular=0.0, shininess=1)
    side = Image.new("L", size, 0)
    ImageDraw.Draw(side).rectangle((0, 0, width // 2, size[1]), fill=255)
    rim = Image.composite(rim_l, rim_r, side)
    near_portal = opening.filter(ImageFilter.GaussianBlur(28)).point(lambda v: min(255, v * 3))
    rim = ImageChops.multiply(rim.point(lambda v: max(0, v - 132) * 2), depth)
    rim = ImageChops.multiply(rim, near_portal)
    red = ImageChops.subtract(rim, _bayer_threshold_field(size)).point(lambda v: 255 if v else 0)
    wall.paste(SPECTRA6["red"], (0, 0), red)

    solid = ImageChops.lighter(ImageOps.invert(opening), field.point(lambda v: 255 if v > 150 else 0))
    image.paste(wall, (0, 0), solid)


def _biomech_background() -> Image.Image:
    """The quote-independent frame: dusk + wall, painted and dithered once.

    Keyed on the painter functions, looked up at call time, so a test that
    patches a painter gets a fresh frame rather than a stale cache (a plain
    "built yet?" flag would let the decoration fences measure the cache).
    """
    key = (_biomech_paint_sky, _biomech_paint_landscape, _biomech_paint_wall)
    cached = _BIOMECH_BACKGROUND.get("frame")
    if cached is not None and cached[0] == key:
        return cached[1]
    size = (800, 480)
    scene = Image.new("RGB", size, SPECTRA6["black"])
    _biomech_paint_sky(scene)
    _biomech_paint_landscape(scene)
    image = dither_image_to_palette(scene, _BIOMECH_SCENE_PALETTE)
    _biomech_paint_wall(image, _biomech_opening_mask(size))
    _BIOMECH_BACKGROUND["frame"] = (key, image)
    return image


def _biomech_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """Bone-white prose over a black halo; the matched phrase an ember."""
    prose, hot, _ = wrap_quote_into_masks(
        draw, image.size, quote_row, _BIOMECH_QUOTE_RECT, theme="biomech",
        font_max=42, font_min=14, line_height_mult=1.3,
    )
    _halo_paste(image, ImageChops.lighter(prose, hot), None)
    image.paste(SPECTRA6["white"], (0, 0), prose.point(lambda v: 255 if v > 110 else 0))
    paint_neon_mask(image, hot, SPECTRA6["yellow"], SPECTRA6["red"],
                    radius=3, gamma=1.5, cap=0.62,
                    ground=frozenset({SPECTRA6["black"]}), tile=BAYER_8x8)
    prose.close()
    hot.close()


def _biomech_paint_byline(image: Image.Image, quote_row: dict) -> None:
    """Author and title, small and bone-white, over the dark plain."""
    left, right, *_ = _BIOMECH_ARCH
    mask = Image.new("L", image.size, 0)
    font = load_font([SPECTRAL_MEDIUM_ITALIC, *META_FONT_CANDIDATES], size=15)
    draw_truncated_centred_byline(ImageDraw.Draw(mask), quote_row, centre=(left + right) // 2,
                                  baseline=_BIOMECH_BYLINE_BASELINE, max_width=right - left - 60,
                                  font=font, fill=255)
    _halo_paste(image, mask, SPECTRA6["white"])
    mask.close()


def _biomech_paint_plate(draw: ImageDraw.ImageDraw, hour: int) -> None:
    """The sill cartouche: the work's title, the hour its Roman number."""
    x0, y0, x1, y1 = _BIOMECH_PLATE
    # The numeral is yellow, not red: red on black is the lowest-contrast pair
    # the six inks offer.
    white, yellow, black = SPECTRA6["white"], SPECTRA6["yellow"], SPECTRA6["black"]
    draw.rounded_rectangle((x0, y0, x1, y1), radius=6, fill=black, outline=white, width=1)
    font = load_font([(GRENZE_GOTISCH_VARIABLE, "SemiBold"), *META_FONT_BOLD_CANDIDATES], size=15)
    title, numeral = "Biomechanoid · ", _TAROT_ROMAN_NUMERALS[hour]
    total = draw.textlength(title + numeral, font=font)
    x = (x0 + x1 - total) / 2
    base = y1 - 6
    draw.text((x, base), title, font=font, fill=white, anchor="ls")
    draw.text((x + draw.textlength(title, font=font), base), numeral, font=font, fill=yellow, anchor="ls")


def render_biomech_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Giger's wall round a Beksiński dusk (see the module section comment above)."""
    hour = _clock_hour12(time_str)
    image = _biomech_background().copy()
    draw = ImageDraw.Draw(image)
    _biomech_paint_quote(image, draw, quote_row)
    _biomech_paint_byline(image, quote_row)
    _biomech_paint_plate(draw, hour)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image



# ---------------------------------------------------------------------------
# codex — a page of the Codex Seraphinianus
# ---------------------------------------------------------------------------
# Luigi Serafini's imaginary encyclopedia (1981), laid out as a botanical
# entry: a chimerical plant plate on the left, columns of asemic script on the
# right, and the quote as the one *deciphered* passage, set in a pen hand
# between lines of untranslated script.
#
# **The script is generated, not typeset** (it is deliberately not an
# alphabet). ``_codex_script`` drives a pen along a prolate trochoid, which
# loops whenever the backward swing outruns the forward advance, like a cursive
# hand. Per-letter swing, height and direction come from an RNG seeded from
# ``_row_digest`` (never ``hash()``), so each quote gets its own byte-identical
# page.
#
# **The time is the page number**, written as the minute of the day in base 21
# (Serafini's own numeral base; three digits cover 0-1439) using twenty-one
# invented glyphs built from the bits of each value, so the same digit always
# looks the same. The readable time stays with the matched phrase.
#
# **Vibrancy is carried by the plate, not the ground.** The page stays a calm
# cream so the script reads; the plant uses every native ink plus two-ink
# recipes (tangerine R+Y, violet R+B, teal G+B, mint G+W, rose R+W, sepia R+G).
# Colour choices are seeded from the row, so each entry is a different specimen.
_CODEX_PLATE = (20, 40, 324, 452)            # the illustration's clear field
_CODEX_STEM_BASE = (128, 404)
_CODEX_STEM_TOP = (140, 118)
_CODEX_COLUMN = (344, 772)                   # text column x-range
_CODEX_QUOTE_RECT = (344, 146, 772, 392)
_CODEX_RAINBOW_CENTRE = (716, 76)
_CODEX_BANDS = (
    ("solid", SPECTRA6["red"]),
    ("2", SPECTRA6["red"], SPECTRA6["yellow"], 0.375),      # tangerine
    ("solid", SPECTRA6["yellow"]),
    ("solid", SPECTRA6["green"]),
    ("solid", SPECTRA6["blue"]),
    ("2", SPECTRA6["red"], SPECTRA6["blue"], 0.5),          # violet
)
_CODEX_LEAF_FILLS = (
    ("2", SPECTRA6["green"], SPECTRA6["blue"], 0.375),      # teal
    ("2", SPECTRA6["green"], SPECTRA6["white"], 0.5),       # mint
    ("solid", SPECTRA6["green"]),
)
_CODEX_PETAL_FILLS = (
    ("2", SPECTRA6["red"], SPECTRA6["white"], 0.5),         # rose
    ("2", SPECTRA6["red"], SPECTRA6["blue"], 0.5),          # violet
)
_CODEX_SEPIA = ("2", SPECTRA6["red"], SPECTRA6["green"], 0.5)
_CODEX_TANGERINE = ("2", SPECTRA6["red"], SPECTRA6["yellow"], 0.375)
_CODEX_CREAM_DENSITY = 14                    # of 256: sparse Y+W paper wash
_CODEX_NUMERAL_BASE = 21
_CODEX_WORD_OVERHEAD = 1.6                   # x-heights: lead-in + exit tail + loop overshoot
# How far a line of script can reach from its baseline, in x-heights. Every
# letter shape and diacritic is drawn inside these bounds, and every stacked
# pair of lines on the page is pitched at least ``BELOW·xh_upper +
# ABOVE·xh_lower`` apart, so an ascender can never cross the descender of the
# line above it (fenced by ``TestCodexFrame``).
_CODEX_REACH_ABOVE = 2.1
_CODEX_REACH_BELOW = 1.5
_CODEX_HEADING = (58, 8)                     # (baseline, x-height) of the red rubric
_CODEX_UPPER_LINES = (92, 112, 132)          # script paragraph above the quote
_CODEX_LOWER_LINES = (418, 438)              # script paragraph below it
_CODEX_CAPTION_BASE = 466                    # plate caption, clear below the roots
_CODEX_BODY_XH = 5
_CODEX_BYLINE_MIN = 12
_CODEX_BYLINE_MAX = 18


def _codex_paint_page(image: Image.Image) -> None:
    """Cream paper: a sparse aperiodic yellow scatter over white.

    A hash field rather than a Bayer rank (a sparse ordered tile lattices),
    using the C-speed ``_white_noise`` since it covers the whole canvas.
    """
    noise = _white_noise(image.width, image.height, 0xC0DE)
    mask = noise.point(lambda v: 255 if v < _CODEX_CREAM_DENSITY else 0)
    image.paste(SPECTRA6["yellow"], (0, 0), mask)
    noise.close()
    mask.close()


def _codex_letter_points(x0: float, base: float, xh: float, rng: random.Random) -> tuple[list, float, bool]:
    """One asemic letter as a pen path that starts and ends on the baseline.

    ``x = x0 + w·t + r·sin 2πt`` swings forward on the way up and back on the
    way down, crossing its own stroke (a loop) whenever ``r > w/4``. The vertical
    excursion is up for an ordinary letter, much taller for an ascender and
    below the line for a descender, so a line of these carries the rhythm of a
    cursive hand without being one. The third return value flags an ascender
    or descender, over which no diacritic is placed.
    """
    kind = rng.random()
    w = xh * rng.uniform(0.7, 1.25)
    above, below = _CODEX_REACH_ABOVE, _CODEX_REACH_BELOW
    if kind < 0.14:
        h, sign, r = xh * rng.uniform(above - 0.5, above), -1, w * rng.uniform(0.32, 0.45)   # ascender loop
    elif kind < 0.24:
        h, sign, r = xh * rng.uniform(below - 0.4, below), 1, w * rng.uniform(0.3, 0.42)    # descender loop
    elif kind < 0.62:
        h, sign, r = xh * rng.uniform(0.8, 1.1), -1, w * rng.uniform(0.28, 0.4)      # small loop
    else:
        h, sign, r = xh * rng.uniform(0.7, 1.0), -1, w * rng.uniform(0.0, 0.18)      # hump
    steps = 14
    pts = []
    for i in range(steps + 1):
        t = i / steps
        x = x0 + w * t + r * math.sin(2 * math.pi * t)
        y = base + sign * h * (1 - math.cos(2 * math.pi * t)) / 2
        pts.append((x, y))
    return pts, x0 + w, kind < 0.24


def _codex_script(draw: ImageDraw.ImageDraw, x: float, base: float, x_end: float, *,
                  xh: float, rng: random.Random, fill, width: int = 1,
                  max_words: int | None = None) -> float:
    """Write a line of asemic script from ``x`` to at most ``x_end``.

    Words of 2–7 letters joined in one continuous stroke, the pen lifted
    between words; an occasional diacritic dot or hook above a letter, the
    furniture every alphabet grows. Returns the x where the pen stopped.
    """
    words = 0
    while x < x_end:
        n = rng.randint(2, 7)
        # Never start a word that cannot finish inside the line. The budget is
        # the worst case (widest letter, 1.25 x-heights, plus lead-in, exit tail
        # and loop overshoot), so the ink provably stops at ``x_end``.
        if x + (n * 1.25 + _CODEX_WORD_OVERHEAD) * xh > x_end:
            n = int((x_end - x) / xh - _CODEX_WORD_OVERHEAD) * 4 // 5
            if n < 2:
                break
        pts = [(x, base)]
        lead = xh * 0.35
        pts.append((x + lead, base - xh * 0.25))
        cx = x + lead
        marks = []
        for _ in range(n):
            letter, cx, tall = _codex_letter_points(cx, base, xh, rng)
            pts.extend(letter[1:])
            # Diacritics sit over short letters only, where there is headroom
            # inside the reach bound; over an ascender they would collide
            # with it or climb out of the line.
            if not tall and rng.random() < 0.14:
                marks.append((letter[len(letter) // 2][0], base - xh * (_CODEX_REACH_ABOVE - 0.45)))
        pts.append((cx + xh * 0.4, base - xh * 0.2))
        draw.line(pts, fill=fill, width=width, joint="curve")
        for mx, my in marks:
            if rng.random() < 0.5:
                d = max(1, width)
                draw.ellipse((mx - d, my - d, mx + d, my + d), fill=fill)
            else:
                draw.arc((mx - xh * 0.5, my - xh * 0.4, mx + xh * 0.5, my + xh * 0.4),
                         200, 340, fill=fill, width=width)
        x = cx + xh * rng.uniform(1.2, 1.9)
        words += 1
        if max_words is not None and words >= max_words:
            break
    return x


def _codex_numeral_advance(digit: int, size: float) -> float:
    """Horizontal advance of one numeral: zero's bare ring is narrower."""
    return size * (0.85 if digit == 0 else 0.95)


def _codex_numeral(draw: ImageDraw.ImageDraw, x: float, base: float, digit: int, *,
                   size: float, fill, width: int = 2) -> float:
    """One of twenty-one invented digits, drawn from the bits of its value.

    Zero is a bare ring. Every other digit is a curved stem whose features are
    switched on by its five bits — a top loop, a foot hook, a crossbar, a dot, a
    tail curl — so the twenty glyphs are pairwise distinct and a given digit is
    always drawn the same way. Returns the advance.
    """
    s = size
    if digit == 0:
        draw.ellipse((x, base - s * 0.7, x + s * 0.6, base - s * 0.1), outline=fill, width=width)
        return _codex_numeral_advance(digit, s)
    stem = [(x + s * 0.15, base), (x + s * 0.35, base - s * 0.5), (x + s * 0.2, base - s)]
    draw.line(stem, fill=fill, width=width, joint="curve")
    if digit & 1:
        draw.arc((x + s * 0.1, base - s * 1.15, x + s * 0.55, base - s * 0.75), 90, 450, fill=fill, width=width)
    if digit & 2:
        draw.arc((x - s * 0.1, base - s * 0.3, x + s * 0.35, base + s * 0.1), 0, 180, fill=fill, width=width)
    if digit & 4:
        draw.line((x, base - s * 0.55, x + s * 0.6, base - s * 0.45), fill=fill, width=width)
    if digit & 8:
        d = width + 0.5
        cx, cy = x + s * 0.6, base - s * 0.85
        draw.ellipse((cx - d, cy - d, cx + d, cy + d), fill=fill)
    if digit & 16:
        draw.arc((x + s * 0.25, base - s * 0.35, x + s * 0.75, base + s * 0.05), 270, 90, fill=fill, width=width)
    return _codex_numeral_advance(digit, s)


def codex_page_digits(time_str: str) -> list[int]:
    """The minute of the day as base-21 digits, most significant first."""
    hh, mm = (int(p) for p in time_str.split(":"))
    value = hh * 60 + mm
    digits = []
    while True:
        digits.append(value % _CODEX_NUMERAL_BASE)
        value //= _CODEX_NUMERAL_BASE
        if not value:
            break
    return digits[::-1]


def _codex_ellipse_poly(cx: float, cy: float, a: float, b: float, angle: float, n: int = 28) -> list:
    """A rotated ellipse as a polygon (PIL's ``ellipse`` cannot rotate)."""
    ca, sa = math.cos(angle), math.sin(angle)
    return [
        (cx + a * math.cos(t) * ca - b * math.sin(t) * sa,
         cy + a * math.cos(t) * sa + b * math.sin(t) * ca)
        for t in (2 * math.pi * i / n for i in range(n))
    ]


def _codex_fill(image: Image.Image, polygon: list, spec: tuple, outline=SPECTRA6["black"], width: int = 1) -> None:
    """Fill with a documented recipe, then ink the contour — coloured pencil
    inside a pen line, the way every plate in the book is drawn."""
    _vitrail_fill_polygon(image, polygon, spec)
    if outline is not None:
        ImageDraw.Draw(image).line(list(polygon) + [polygon[0]], fill=outline, width=width, joint="curve")


def _codex_stem_point(t: float) -> tuple[float, float]:
    """The stem's centreline: a gentle quadratic S from root to crown."""
    (x0, y0), (x1, y1) = _CODEX_STEM_BASE, _CODEX_STEM_TOP
    cx = x0 + 34
    x = (1 - t) ** 2 * x0 + 2 * (1 - t) * t * cx + t * t * x1
    y = y0 + (y1 - y0) * t
    return x, y


def _codex_fill_mask(image: Image.Image, mask: Image.Image, spec: tuple) -> None:
    """Paint every set pixel of a ``1`` mask with a recipe, in place.

    Filling through a private mask gives the roots their R+G sepia without a
    red sentinel, whose bbox post-pass would also recolour any other red there.
    """
    bbox = mask.getbbox()
    if bbox is None:
        return
    mpx, ipx = mask.load(), image.load()
    for y in range(bbox[1], bbox[3]):
        for x in range(bbox[0], bbox[2]):
            if mpx[x, y]:
                ipx[x, y] = _vitrail_pane_ink(x, y, spec)


def _codex_paint_roots(image: Image.Image, draw: ImageDraw.ImageDraw, rng: random.Random):
    """Sepia roots below a green-hatched ground line, each curling into a
    spiral. Returns the roots' ink bbox, so the caption can be kept clear of it.
    """
    bx, by = _CODEX_STEM_BASE
    # Ground: short green hatching, the mound the specimen stands on.
    for i in range(-70, 72, 5):
        h = 3 + int(4 * math.cos(i / 70 * math.pi / 2))
        draw.line((bx + i, by + 2, bx + i + 3, by + 2 - h), fill=SPECTRA6["green"], width=1)
    draw.line((bx - 78, by + 3, bx + 80, by + 3), fill=SPECTRA6["black"], width=1)
    mask = Image.new("1", image.size, 0)
    mdraw = ImageDraw.Draw(mask)
    for k, dx in enumerate((-46, -20, 6, 30, 52)):
        pts = [(bx + dx * 0.2, by + 4)]
        x, y = bx + dx * 0.2, by + 4
        for _ in range(8):
            x += dx * 0.12 + rng.uniform(-2, 2)
            y += 4.2
            pts.append((x, y))
        # Spiral terminal: the root keeps curling the way it was heading. The
        # centre sits on the curl side, so the spiral starts at the root's tip
        # (angle pi from a centre to its right, 0 from one to its left) and
        # winds inward.
        curl = 1 if dx > 0 else -1
        r = 5 + k % 3
        ox, oy = x + curl * r, y
        start = math.pi if curl > 0 else 0.0
        for j in range(1, 16):
            a = start - curl * j * 0.55
            rr = r * (1 - j / 18)
            pts.append((ox + rr * math.cos(a), oy + rr * math.sin(a)))
        mdraw.line(pts, fill=1, width=3, joint="curve")
    bbox = mask.getbbox()
    _codex_fill_mask(image, mask, _CODEX_SEPIA)
    mask.close()
    return bbox


def _codex_paint_stem(image: Image.Image, draw: ImageDraw.ImageDraw, band_offset: int) -> None:
    """A tapering stem banded through the spectrum, inked on both flanks."""
    n = 22
    left, right = [], []
    samples = []
    for i in range(n + 1):
        t = i / n
        x, y = _codex_stem_point(t)
        hw = 9 - 5 * t
        samples.append((x, y, hw))
    for i in range(n):
        xa, ya, ha = samples[i]
        xb, yb, hb = samples[i + 1]
        band = (xa - ha, ya), (xa + ha, ya), (xb + hb, yb), (xb - hb, yb)
        _vitrail_fill_polygon(image, list(band), _CODEX_BANDS[(i + band_offset) % len(_CODEX_BANDS)])
        draw.line((xb - hb, yb, xb + hb, yb), fill=SPECTRA6["black"], width=1)
        left.append((xa - ha, ya))
        right.append((xa + ha, ya))
    left.append((samples[-1][0] - samples[-1][2], samples[-1][1]))
    right.append((samples[-1][0] + samples[-1][2], samples[-1][1]))
    draw.line(left, fill=SPECTRA6["black"], width=2, joint="curve")
    draw.line(right, fill=SPECTRA6["black"], width=2, joint="curve")


def _codex_paint_fish_leaf(image: Image.Image, draw: ImageDraw.ImageDraw, ax: float, ay: float,
                           side: int, spec: tuple, size: float) -> tuple[float, float]:
    """A leaf that is a fish: body, forked tail at the stem, scales, one eye.

    The tail is the petiole: the fish grows out of the stem nose-first.
    Returns the tip of the nose, for the plate's dotted leaders.
    """
    angle = -0.5 if side > 0 else math.pi + 0.5
    ca, sa = math.cos(angle), math.sin(angle)

    def rot(u: float, v: float) -> tuple[float, float]:
        return ax + u * ca - v * sa, ay + u * sa + v * ca

    a, b = size, size * 0.42
    tail_root = 10
    tail = [rot(tail_root + 2, 0), rot(0, -b * 0.8), rot(4, 0), rot(0, b * 0.8)]
    _codex_fill(image, tail, _CODEX_TANGERINE)
    cx = tail_root + a
    body = [rot(cx + a * math.cos(t), b * math.sin(t) * (0.75 + 0.25 * math.cos(t)))
            for t in (2 * math.pi * i / 30 for i in range(30))]
    _codex_fill(image, body, spec, width=2)
    # Scale arcs: rows of small blue crescents along the flank.
    for row in (-0.3, 0.2):
        for k in range(3):
            u = cx - a * 0.55 + k * a * 0.36
            sx, sy = rot(u, row * b)
            draw.arc((sx - 4, sy - 4, sx + 4, sy + 4), 0, 180, fill=SPECTRA6["blue"], width=1)
    # Gill line and eye near the nose.
    gx0, gy0 = rot(cx + a * 0.35, -b * 0.6)
    gx1, gy1 = rot(cx + a * 0.42, b * 0.6)
    draw.line((gx0, gy0, gx1, gy1), fill=SPECTRA6["black"], width=1)
    ex, ey = rot(cx + a * 0.62, -b * 0.15)
    draw.ellipse((ex - 3.5, ey - 3.5, ex + 3.5, ey + 3.5), fill=SPECTRA6["white"], outline=SPECTRA6["black"])
    draw.ellipse((ex - 1.5, ey - 1.5, ex + 1.5, ey + 1.5), fill=SPECTRA6["black"])
    # A dorsal fin, red, on the upper flank.
    fin = [rot(cx - a * 0.3, -b * 0.9), rot(cx - a * 0.05, -b * 1.55), rot(cx + a * 0.2, -b * 0.95)]
    _codex_fill(image, fin, ("solid", SPECTRA6["red"]))
    return rot(cx + a, 0)


def _codex_paint_blossom(image: Image.Image, draw: ImageDraw.ImageDraw, rng: random.Random) -> None:
    """A corolla of alternating rose and violet petals round an open eye."""
    cx, cy = _CODEX_STEM_TOP[0], _CODEX_STEM_TOP[1] - 36
    petals = rng.choice((8, 9, 10, 11))
    phase = rng.uniform(0, math.pi)
    for i in range(petals):
        a = phase + 2 * math.pi * i / petals
        px_, py_ = cx + 34 * math.cos(a), cy + 34 * math.sin(a)
        _codex_fill(image, _codex_ellipse_poly(px_, py_, 26, 11, a), _CODEX_PETAL_FILLS[i % 2], width=2)
    # Inner tangerine ring of sepals.
    for i in range(petals):
        a = phase + math.pi / petals + 2 * math.pi * i / petals
        px_, py_ = cx + 20 * math.cos(a), cy + 20 * math.sin(a)
        _codex_fill(image, _codex_ellipse_poly(px_, py_, 11, 5, a, 16), _CODEX_TANGERINE)
    # The eye: an almond of white sclera, a blue iris, a black pupil, a glint.
    almond = [(cx - 24 + 48 * t, cy - 14 * math.sin(math.pi * t)) for t in (i / 16 for i in range(17))]
    almond += [(cx + 24 - 48 * t, cy + 12 * math.sin(math.pi * t)) for t in (i / 16 for i in range(1, 16))]
    _codex_fill(image, almond, ("solid", SPECTRA6["white"]), width=2)
    draw.ellipse((cx - 10, cy - 10, cx + 10, cy + 10), fill=SPECTRA6["blue"], outline=SPECTRA6["black"])
    draw.ellipse((cx - 4, cy - 4, cx + 4, cy + 4), fill=SPECTRA6["black"])
    draw.rectangle((cx - 6, cy - 7, cx - 4, cy - 5), fill=SPECTRA6["white"])
    # Lashes along the upper lid.
    for t in (0.18, 0.34, 0.5, 0.66, 0.82):
        x = cx - 24 + 48 * t
        y = cy - 14 * math.sin(math.pi * t)
        dx = (t - 0.5) * 10
        draw.line((x, y, x + dx, y - 6), fill=SPECTRA6["black"], width=1)


def _codex_paint_seeds(image: Image.Image, draw: ImageDraw.ImageDraw, rng: random.Random) -> None:
    """Striped seeds drifting off the crown on thread parachutes."""
    cx, cy = _CODEX_STEM_TOP[0], _CODEX_STEM_TOP[1] - 36
    for k in range(3):
        sx = cx + 70 + k * 28 + rng.uniform(-6, 6)
        sy = cy - 40 + k * 26 + rng.uniform(-6, 6)
        seed = _codex_ellipse_poly(sx, sy, 7, 4, 1.1)
        _codex_fill(image, seed, _CODEX_BANDS[(k * 2 + 1) % len(_CODEX_BANDS)])
        top = (sx - 5, sy - 14)
        for spread in (-8, -3, 3, 8):
            draw.line((sx - 1, sy - 3, top[0] + spread, top[1]), fill=SPECTRA6["black"], width=1)
        draw.arc((top[0] - 10, top[1] - 6, top[0] + 10, top[1] + 6), 180, 360, fill=SPECTRA6["black"], width=1)


def _codex_paint_labels(draw: ImageDraw.ImageDraw, rng: random.Random, anchors: list) -> None:
    """Dotted leaders from the specimen's parts to asemic labels — the
    diagrammatic apparatus of an encyclopedia plate, captioned in a script
    nobody can read."""
    x_label = _CODEX_PLATE[2] - 58
    for ax, ay in anchors:
        y = ay
        x = ax + 5
        while x < x_label - 6:
            draw.point((x, y), fill=SPECTRA6["black"])
            x += 3
        _codex_script(draw, x_label, y + 3, _CODEX_PLATE[2], xh=4, rng=rng,
                      fill=SPECTRA6["black"], max_words=1)


def _codex_paint_plate(image: Image.Image, rng: random.Random) -> None:
    draw = ImageDraw.Draw(image)
    _codex_paint_roots(image, draw, rng)
    band_offset = rng.randrange(len(_CODEX_BANDS))
    _codex_paint_stem(image, draw, band_offset)
    leaf_ts = (0.18, 0.38, 0.58, 0.76)
    anchors = []
    for i, t in enumerate(leaf_ts):
        x, y = _codex_stem_point(t)
        side = 1 if i % 2 == 0 else -1
        spec = _CODEX_LEAF_FILLS[(i + band_offset) % len(_CODEX_LEAF_FILLS)]
        nose = _codex_paint_fish_leaf(image, draw, x + side * (8 - 5 * t), y, side, spec, 32 - 6 * t)
        if side > 0:
            anchors.append(nose)
    _codex_paint_blossom(image, draw, rng)
    _codex_paint_seeds(image, draw, rng)
    _codex_paint_labels(draw, rng, anchors)
    # Plate caption under the specimen, in the script.
    _codex_script(draw, _CODEX_PLATE[0] + 40, _CODEX_CAPTION_BASE, _CODEX_PLATE[2] - 40,
                  xh=_CODEX_BODY_XH, rng=rng, fill=SPECTRA6["black"])


def _codex_paint_rainbow(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """A small rainbow beside the rubric heading, one foot dripping its bands
    into a puddle — a Serafinian object, familiar and then not."""
    cx, cy = _CODEX_RAINBOW_CENTRE
    inks = (SPECTRA6["red"], SPECTRA6["yellow"], SPECTRA6["green"], SPECTRA6["blue"])
    r = 40
    for ink in inks:
        draw.arc((cx - r, cy - r, cx + r, cy + r), 180, 360, fill=ink, width=5)
        r -= 5
    draw.arc((cx - 41, cy - 41, cx + 41, cy + 41), 180, 360, fill=SPECTRA6["black"], width=1)
    draw.arc((cx - 20, cy - 20, cx + 20, cy + 20), 180, 360, fill=SPECTRA6["black"], width=1)
    # The right foot runs: each band drips straight down into a puddle.
    for k, ink in enumerate(inks):
        x = cx + 38 - k * 5
        drop = 10 + (k * 7) % 12
        draw.line((x, cy, x, cy + drop), fill=ink, width=4)
        draw.ellipse((x - 2, cy + drop - 1, x + 2, cy + drop + 4), fill=ink)
    puddle = _codex_ellipse_poly(cx + 30, cy + 30, 16, 4, 0.0, 20)
    _codex_fill(image, puddle, _CODEX_BANDS[5])
    # The left foot is a pinned tab of paper: the rainbow is tacked to the page.
    draw.ellipse((cx - 42, cy - 3, cx - 34, cy + 5), fill=SPECTRA6["red"], outline=SPECTRA6["black"])


def _codex_paint_column(image: Image.Image, draw: ImageDraw.ImageDraw, rng: random.Random) -> None:
    """The untranslated text: a red rubric heading and a paragraph of script
    above the quote, and a further paragraph below it."""
    x0, x1 = _CODEX_COLUMN
    heading_base, heading_xh = _CODEX_HEADING
    _codex_script(draw, x0 + 30, heading_base, x1 - 30, xh=heading_xh, rng=rng,
                  fill=SPECTRA6["red"], width=2, max_words=4)
    for i, base in enumerate(_CODEX_UPPER_LINES):
        # The first two lines stop short of the rainbow vignette.
        end = _CODEX_RAINBOW_CENTRE[0] - 58 if i < 2 else x0 + (x1 - x0) * rng.uniform(0.45, 0.8)
        _codex_script(draw, x0 + (18 if i == 0 else 0), base, end, xh=_CODEX_BODY_XH, rng=rng,
                      fill=SPECTRA6["black"])
    for i, base in enumerate(_CODEX_LOWER_LINES):
        end = x1 if i == 0 else x0 + (x1 - x0) * rng.uniform(0.4, 0.7)
        _codex_script(draw, x0, base, end, xh=_CODEX_BODY_XH, rng=rng, fill=SPECTRA6["black"])


def _codex_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The one deciphered passage, in a pen hand, bracketed by blue rules."""
    x0, y0, x1, y1 = _CODEX_QUOTE_RECT
    quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    regular, italic, lines, line_height, size = fit_quote(
        draw, quote, quote_row.get("matched_text") or "", x1 - x0 - 16, y1 - y0 - 38,
        38, 15, 1.2, theme="codex",
    )
    block = len(lines) * line_height
    top = y0 + max(0, (y1 - y0 - 30 - block) // 2)
    draw_centred_styled_lines(draw, lines, x0=x0, x1=x1, top=top, line_height=line_height,
                              regular=regular, bold=italic, fill=SPECTRA6["black"],
                              accent=SPECTRA6["red"], min_inset=8)
    rule_y = top + block + 8
    mid = (x0 + x1) // 2
    draw.line((mid - 60, rule_y, mid + 60, rule_y), fill=SPECTRA6["blue"], width=1)
    draw.polygon([(mid, rule_y - 4), (mid + 4, rule_y), (mid, rule_y + 4), (mid - 4, rule_y)],
                 fill=SPECTRA6["red"])
    # Scaled with the body and clamped, so the byline stays visibly smaller
    # than a dense quote fitted near the 15 pt floor.
    byline = load_font(theme_font_candidates("codex", "quote_bold"),
                       max(_CODEX_BYLINE_MIN, min(_CODEX_BYLINE_MAX, int(size * 0.55))))
    draw_truncated_centred_byline(draw, quote_row, centre=mid, baseline=rule_y + 22,
                                  max_width=x1 - x0 - 16, font=byline, fill=SPECTRA6["blue"])


def _codex_paint_folio(draw: ImageDraw.ImageDraw, time_str: str) -> float:
    """The page number, bottom outer corner, in base-21 Serafinian numerals
    between two small flourishes. Returns where the pen stopped after the last
    digit, which is the column's right edge whatever digits the time needs."""
    digits = codex_page_digits(time_str)
    size = 20
    total = sum(_codex_numeral_advance(d, size) for d in digits)
    x = _CODEX_COLUMN[1] - total
    base = 462
    draw.arc((x - 24, base - 10, x - 6, base + 2), 200, 360, fill=SPECTRA6["blue"], width=1)
    for d in digits:
        x += _codex_numeral(draw, x, base, d, size=size, fill=SPECTRA6["red"])
    draw.arc((x + 2, base - 10, x + 20, base + 2), 180, 340, fill=SPECTRA6["blue"], width=1)
    return x


def render_codex_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A page of the Codex Seraphinianus (see the module section comment above)."""
    image = Image.new("RGB", (800, 480), color=SPECTRA6["white"])
    _codex_paint_page(image)
    rng = random.Random(_row_digest(quote_row))
    _codex_paint_plate(image, rng)
    draw = ImageDraw.Draw(image)
    _codex_paint_column(image, draw, rng)
    _codex_paint_rainbow(image, draw)
    _codex_paint_quote(image, draw, quote_row)
    _codex_paint_folio(draw, time_str)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image



# ---------------------------------------------------------------------------
# bosch — Hieronymus Bosch, *The Garden of Earthly Delights* (c. 1490-1510)
# ---------------------------------------------------------------------------
# A custom frame: the triptych standing open. Paradise on the left wing
# (Fountain of Life, owl, dragon tree), the Garden across the centre (far lake
# and fountains, the giant fruit, the lovers' bubble) and Hell on the right
# (burning city, knife between two ears, Tree-Man, frozen lake). The quote is
# lettered on a **phylactery banderole** across the centre panel, in black
# textura with the matched phrase **rubricated**.
#
# **Craquelure** (``paint_craquelure``) is built as a graph, not a per-pixel
# field: a jittered lattice whose edges are wobbled polylines, some dropped, a
# few diagonals added. A crack net is a set of connected edges; thresholding
# noise gives disconnected specks. Cells are wider than tall because oak-panel
# cracks run across the vertical grain.
#
# **A crack changes polarity with the paint it crosses**: grime-filled and dark
# on a light passage, open to the white ground on a dark one. Hence the
# primitive's separate ``dark`` and ``light`` inks.
#
# **Cracks never cut a letter.** The banderole's text is drawn a second time
# into a dilated ``keep_out`` mask so a fissure stops short of every stroke.
# Fenced by ``TestBoschFrame``.
#
# **The wing tops are the centre arch, halved and mirrored**: closed, each wing
# covers half the centre, so opened its free edge (the arch's apex) ends up
# outermost. The wings are narrower than half the centre, so the half-arch is
# compressed, but the direction is the physical one.
#
# Colour mixes use a *single* jittered ``BAYER_8x8`` read per pixel,
# partitioned into as many inks as the passage needs (a second read is
# correlated with the first and slides the hue; unjittered, broad fields
# lattice). Flesh is light orange (W+R+Y) run white-major, ~68 : 16 : 16,
# because Bosch's nudes are a cool pallor, not a peach.
#
# **No clock surface beyond the phrase**: ``time_str`` is ``del``-asserted.
#
# Composed at 800x480 and NEAREST-downsampled (the ``metro`` convention).
# ---------------------------------------------------------------------------
_BOSCH_PANELS = (
    ("paradise", (14, 14, 172, 466)),
    ("garden", (182, 14, 618, 466)),
    ("hell", (628, 14, 786, 466)),
)
_BOSCH_ARCH_RISE = 30            # sagitta of the centre panel's segmental arch
_BOSCH_SCROLL_CENTRE = (400, 236)
_BOSCH_TEXT_MAX = (344, 214)     # widest / tallest the lettered block may grow
_BOSCH_SCROLL_PAD = (22, 16)
_BOSCH_SCROLL_MIN_W = 250
_BOSCH_SCROLL_WAVE = 3.0         # the banderole's flutter, px
_BOSCH_ROLL_W = 13               # rolled ends
_BOSCH_CREDIT_SIZE = 16
_BOSCH_CRACK_CELL = (30, 17)
_BOSCH_CRACK_SEED = 0xB05C
_BOSCH_JITTER = 9                # ± ranks of positional jitter on the 8x8 tile


_BOSCH_RANK_FIELD: tuple[bytes, ...] = ()


def _bosch_rank_field() -> tuple[bytes, ...]:
    """The 8x8 Bayer rank plus a seeded jitter, for the whole canvas, once.

    Ordered dither with its rank nudged by up to ``_BOSCH_JITTER``, the jitter
    from a seeded ``Random.randbytes`` field rather than a per-pixel
    ``position_noise`` call (the frame reads ~450k ranks per render). Seeded,
    so byte-identical across processes.

    **Clamped to 0..63**, so share 0 means no pixels and share 1 means all,
    which every ``_bosch_pick`` call assumes.

    Built into a local and published in one assignment, because curator-UI
    previews render on concurrent threads.
    """
    global _BOSCH_RANK_FIELD
    field = _BOSCH_RANK_FIELD
    if not field:
        noise = random.Random(_BOSCH_CRACK_SEED ^ 0x5A5A).randbytes(800 * 480)
        span, j = 2 * _BOSCH_JITTER + 1, _BOSCH_JITTER
        field = tuple(
            bytes(min(63, max(0, BAYER_8x8[y % 8][x % 8] + noise[y * 800 + x] % span - j)) for x in range(800))
            for y in range(480)
        )
        _BOSCH_RANK_FIELD = field
    return field


def _bosch_pick(rank: int, parts):
    """One rank, partitioned: ``parts`` is ``((ink, share), ...)`` low to high.

    The last part takes the remainder. One read per pixel, never two.
    """
    acc = 0.0
    for ink, share in parts[:-1]:
        acc += share * 64
        if rank < acc:
            return ink
    return parts[-1][0]


def _bosch_ink(name: str):
    return SPECTRA6[name]


def _bosch_paint(tile: Image.Image, mask: Image.Image, shade) -> None:
    """Fill ``mask``'s set pixels with ``shade(x, y, rank) -> ink`` (``None`` skips)."""
    bbox = mask.getbbox()
    if bbox is None:
        return
    px, mp = tile.load(), mask.load()
    ox, oy = getattr(tile, "_bosch_origin", (0, 0))
    field = _bosch_rank_field()
    for y in range(bbox[1], bbox[3]):
        ranks = field[(y + oy) % 480]
        for x in range(bbox[0], bbox[2]):
            if mp[x, y] > 127:
                ink = shade(x, y, ranks[(x + ox) % 800])
                if ink is not None:
                    px[x, y] = ink


def _bosch_shape(size, painter) -> Image.Image:
    """An ``"L"`` mask with ``painter(ImageDraw)`` drawn into it."""
    mask = Image.new("L", size, 0)
    painter(ImageDraw.Draw(mask))
    return mask


def _bosch_arch_tops(kind: str, width: int) -> list[float]:
    """Panel-local y of the painted top edge, per column.

    The centre is a segmental arch; each wing is half of it, mirrored so the
    apex sits at the wing's outer edge (see the section comment).
    """
    centre_w = _BOSCH_PANELS[1][1][2] - _BOSCH_PANELS[1][1][0]
    rise = _BOSCH_ARCH_RISE
    radius = (centre_w * centre_w / 4 + rise * rise) / (2 * rise)

    def arch(d: float) -> float:          # d = distance from the centre's left edge
        off = d - centre_w / 2
        return rise - (math.sqrt(max(0.0, radius * radius - off * off)) - (radius - rise))

    tops = []
    for x in range(width):
        c = x + 0.5
        if kind == "garden":
            tops.append(arch(c))
        elif kind == "paradise":          # hinge on the right
            tops.append(arch((width - c) / width * centre_w / 2))
        else:                             # hell: hinge on the left
            tops.append(arch(c / width * centre_w / 2))
    return tops


def _bosch_panel_mask(kind: str, size) -> Image.Image:
    width, height = size
    tops = _bosch_arch_tops(kind, width)
    pts = [(x, round(t)) for x, t in enumerate(tops)] + [(width - 1, height - 1), (0, height - 1)]
    return _bosch_shape(size, lambda d: d.polygon(pts, fill=255))


# ---- the frame -------------------------------------------------------------

def _bosch_paint_frame(image: Image.Image) -> None:
    """Dark oak frame with a grain, a gilt fillet round each panel, and hinges."""
    width, height = image.size
    draw = ImageDraw.Draw(image)
    red, yellow, black = (_bosch_ink(n) for n in ("red", "yellow", "black"))
    px = image.load()
    # The panels cover most of the frame; only the rails, the gaps and the
    # spandrels above the arches show, so the per-pixel passes skip the rest.
    covered = [any(x0 + 4 <= x < x1 - 4 for _, (x0, _, x1, _) in _BOSCH_PANELS) for x in range(width)]
    open_top, open_bottom = 14 + _BOSCH_ARCH_RISE + 4, 466 - 4

    def visible(x: int, y: int) -> bool:
        return not (covered[x] and open_top < y < open_bottom)

    for y in range(height):                           # wavy grain streaks
        for x in range(width):
            if not visible(x, y):
                continue
            g = math.sin(x * 0.9 + 6.0 * math.sin(y * 0.021 + x * 0.013))
            if g > 0.96 and position_noise(x, y) % 3 == 0:
                px[x, y] = red
    for kind, (x0, y0, x1, y1) in _BOSCH_PANELS:
        tops = _bosch_arch_tops(kind, x1 - x0)
        pts = [(x0 + x, y0 + round(t) - 3) for x, t in enumerate(tops)]
        pts = [(x0 - 3, pts[0][1])] + pts + [(x1 + 2, pts[-1][1]), (x1 + 2, y1 + 2), (x0 - 3, y1 + 2)]
        draw.polygon(pts, fill=yellow)
    for gap_x in (174, 620):                          # iron-and-gilt hinge straps
        for hy in (70, 238, 406):
            draw.rectangle((gap_x - 3, hy, gap_x + 10, hy + 14), fill=yellow)
            draw.rectangle((gap_x + 3, hy + 2, gap_x + 4, hy + 12), fill=black)
    for y in range(height):                           # gold: Y+R 5/8:3/8
        row = BAYER_8x8[y % 8]
        for x in range(width):
            if visible(x, y) and px[x, y] == yellow and row[x % 8] < 24:
                px[x, y] = red


# ---- Paradise --------------------------------------------------------------

def _bosch_sky(tile, horizon: int, top_white: float, low_white: float) -> None:
    w = tile.size[0]
    white, blue = _bosch_ink("white"), _bosch_ink("blue")
    mask = _bosch_shape(tile.size, lambda d: d.rectangle((0, 0, w, horizon), fill=255))

    def shade(x, y, rank):
        t = y / max(1, horizon)
        return _bosch_pick(rank, ((white, top_white + (low_white - top_white) * t), (blue, 1)))
    _bosch_paint(tile, mask, shade)


def _bosch_meadow(tile, top: int) -> None:
    """Pale spring green at the horizon deepening to a dark forest foot,
    rippled by a slow undulation so the turf does not read as a flat band.

    The frame's hot loop, so written out rather than routed through
    ``_bosch_paint``: the undulation is separable (angle-sum identity) into
    per-column tables and per-row values, and the four-way partition is
    inlined as cumulative thresholds. Same single rank read.
    """
    w, h = tile.size
    white, yellow, green, black = (_bosch_ink(n) for n in ("white", "yellow", "green", "black"))
    px = tile.load()
    ox, oy = getattr(tile, "_bosch_origin", (0, 0))
    field = _bosch_rank_field()
    sx = [math.sin(x * 0.05) for x in range(w)]
    cx = [math.cos(x * 0.05) for x in range(w)]
    span = max(1, h - top)
    for y in range(top, h):
        ranks = field[(y + oy) % 480]
        base = (y - top) / span
        amp = 0.12 * math.sin(y * 0.11)
        cy_, sy_ = math.cos(y * 0.03) * amp, math.sin(y * 0.03) * amp
        for x in range(w):
            t = base + sx[x] * cy_ + cx[x] * sy_
            t = 0.0 if t < 0.0 else 1.0 if t > 1.0 else t
            rank = ranks[(x + ox) % 800]
            c1 = 14.08 * (1 - t)                        # white  0.22 (1 - t)
            c2 = c1 + 21.76 * (1 - t) + 3.84            # yellow 0.34 (1 - t) + 0.06
            if rank < c1:
                px[x, y] = white
            elif rank < c2:
                px[x, y] = yellow
            elif rank < c2 + 21.76 * t:                 # black  0.34 t
                px[x, y] = black
            else:
                px[x, y] = green


def _bosch_hills(tile, horizon: int, peaks, seed: int) -> None:
    """Distant blue hills along the horizon, fading into the sky."""
    w = tile.size[0]
    rng = random.Random(seed)
    pts = [(0, horizon)]
    for x in range(0, w + 8, 8):
        y = horizon - 6 - 5 * math.sin(x * 0.045 + seed) - rng.randrange(4)
        for px_, height_, half in peaks:
            if abs(x - px_) < half:
                y = min(y, horizon - height_ * (1 - abs(x - px_) / half) ** 0.6)
        pts.append((x, y))
    pts.append((w, horizon + 1))
    mask = _bosch_shape(tile.size, lambda d: d.polygon(pts, fill=255))
    white, blue = _bosch_ink("white"), _bosch_ink("blue")
    _bosch_paint(tile, mask, lambda x, y, r: _bosch_pick(r, ((white, 0.38), (blue, 1))))


def _bosch_birds(draw, points, ink) -> None:
    for x, y, s in points:
        draw.line([(x - s, y - s // 2), (x, y), (x + s, y - s // 2)], fill=ink, width=1)


def _bosch_rose_tower(tile, cx: int, base: int, top: int, half: int, light: float = 0.36) -> None:
    """A slender pink Gothic spire: flared base, lancets, crockets, finial."""
    white, red, black = _bosch_ink("white"), _bosch_ink("red"), _bosch_ink("black")
    body = [(cx - half - 5, base), (cx - half, base - 12), (cx - half + 2, top + 26),
            (cx, top), (cx + half - 2, top + 26), (cx + half, base - 12), (cx + half + 5, base)]
    mask = _bosch_shape(tile.size, lambda d: d.polygon(body, fill=255))

    def shade(x, y, rank):
        side = (x - cx) / max(1, half)               # lit from the upper left
        r = light + 0.14 * max(0.0, side)
        k = 0.12 * max(0.0, side - 0.3)
        return _bosch_pick(rank, ((black, k), (red, r), (white, 1)))
    _bosch_paint(tile, mask, shade)
    draw = ImageDraw.Draw(tile)
    for i, y in enumerate(range(top + 34, base - 16, 22)):           # lancets
        draw.ellipse((cx - 2, y, cx + 2, y + 10), fill=black)
        for s in (-1, 1):                                              # crockets
            draw.polygon([(cx + s * (half - 1), y + 4), (cx + s * (half + 5), y - 2),
                          (cx + s * (half - 1), y + 9)], fill=red)
    draw.line([(cx, top - 10), (cx, top)], fill=red, width=1)
    draw.ellipse((cx - 2, top - 14, cx + 2, top - 10), fill=red)


def _bosch_paint_paradise(tile: Image.Image) -> None:
    w, h = tile.size
    white, blue, red, black, yellow, green = (_bosch_ink(n) for n in
                                              ("white", "blue", "red", "black", "yellow", "green"))
    horizon = 168
    _bosch_sky(tile, horizon, 0.30, 0.78)
    _bosch_hills(tile, horizon, ((24, 64, 14), (132, 44, 18)), seed=3)
    _bosch_meadow(tile, horizon)
    draw = ImageDraw.Draw(tile)
    _bosch_birds(draw, ((40, 58, 4), (56, 70, 3), (104, 50, 4), (118, 64, 3)), black)

    # The pool, and the Fountain of Life rising out of it.
    pool = _bosch_shape(tile.size, lambda d: d.ellipse((14, 262, 144, 338), fill=255))
    _bosch_paint(tile, pool, lambda x, y, r: _bosch_pick(
        r, ((white, 0.30 + 0.25 * ((y - 262) / 76)), (blue, 1))))
    for y in (286, 300, 316):
        draw.arc((30, y - 6, 128, y + 6), 200, 340, fill=white, width=1)
    cx = 79
    _bosch_rose_tower(tile, cx, 306, 150, 9)
    # The orb at the fountain's foot, and the owl in its dark hollow.
    orb = _bosch_shape(tile.size, lambda d: d.ellipse((cx - 17, 282, cx + 17, 316), fill=255))
    _bosch_paint(tile, orb, lambda x, y, r: _bosch_pick(
        r, ((black, 0.18 * max(0.0, (x - cx) / 17)), (red, 0.42), (white, 1))))
    draw.ellipse((cx - 9, 290, cx + 9, 308), fill=black)
    draw.ellipse((cx - 6, 295, cx - 2, 299), fill=yellow)
    draw.ellipse((cx + 2, 295, cx + 6, 299), fill=yellow)
    draw.point([(cx - 4, 297), (cx + 4, 297)], fill=black)
    draw.polygon([(cx - 1, 300), (cx + 1, 300), (cx, 303)], fill=yellow)

    # The dragon tree: a bare sepia trunk and a fan of dark spiky fronds.
    trunk = _bosch_shape(tile.size, lambda d: d.polygon(
        [(126, 356), (136, 356), (134, 236), (130, 236)], fill=255))
    _bosch_paint(tile, trunk, lambda x, y, r: red if (x + y) & 1 else green)
    for i in range(9):
        a = math.radians(200 + i * 17.5)
        ex, ey = 132 + 30 * math.cos(a), 236 + 24 * math.sin(a)
        draw.line([(132, 236), (round(ex), round(ey))], fill=black, width=3)
        draw.line([(132, 236), (round(ex), round(ey))], fill=green, width=1)

    # Small beasts, which at this scale read as dark flecks in the grass.
    for x, y in ((24, 372), (58, 398), (98, 384), (140, 410), (36, 430)):
        draw.ellipse((x - 3, y - 2, x + 3, y + 2), fill=black)
        draw.point((x - 4, y - 2), fill=black)
    for x, y in ((18, 204), (30, 196), (26, 214), (40, 206)):          # a rose bush in flower
        draw.ellipse((x - 9, y - 7, x + 9, y + 7), fill=black)
        draw.ellipse((x - 7, y - 6, x + 7, y + 5), fill=green)
    for x, y in ((16, 200), (30, 193), (40, 204), (24, 212), (34, 214)):
        draw.ellipse((x - 2, y - 2, x + 2, y + 2), fill=red)
        draw.point((x - 1, y - 1), fill=white)


# ---- the Garden ------------------------------------------------------------

def _bosch_blue_orb(tile, cx: int, cy: int, r: int) -> None:
    """A cracked blue globe of the far fountains, lit from the upper left."""
    white, blue, black = _bosch_ink("white"), _bosch_ink("blue"), _bosch_ink("black")
    mask = _bosch_shape(tile.size, lambda d: d.ellipse((cx - r, cy - r, cx + r, cy + r), fill=255))

    def shade(x, y, rank):
        lit = ((x - cx) + (y - cy)) / (2 * r)          # -1 lit .. +1 shadow
        return _bosch_pick(rank, ((white, max(0.0, 0.35 - 0.4 * lit)),
                                  (black, max(0.0, 0.3 * lit)), (blue, 1)))
    _bosch_paint(tile, mask, shade)
    draw = ImageDraw.Draw(tile)
    draw.line([(cx - r // 3, cy - r + 2), (cx, cy - r // 4), (cx - r // 5, cy + r // 3)], fill=black, width=1)


def _bosch_spikes(draw, cx: int, cy: int, r: int, ink, count: int = 5) -> None:
    for i in range(count):
        a = math.radians(-160 + i * 140 / max(1, count - 1))
        bx, by = cx + r * math.cos(a), cy + r * math.sin(a)
        tx, ty = cx + (r + 11) * math.cos(a), cy + (r + 11) * math.sin(a)
        nx, ny = -math.sin(a) * 2.5, math.cos(a) * 2.5
        draw.polygon([(bx - nx, by - ny), (tx, ty), (bx + nx, by + ny)], fill=ink)


def _bosch_strawberry(tile, cx: int, cy: int, r: int) -> None:
    """A giant strawberry: rounded shoulders tapering to a point, seeded, crowned."""
    white, red, yellow, green, black = (_bosch_ink(n) for n in ("white", "red", "yellow", "green", "black"))
    body = []
    for i in range(33):
        a = math.pi + math.pi * i / 32                 # the rounded shoulders, left to right
        body.append((cx + r * math.cos(a), cy - r * 0.55 + r * 0.5 * math.sin(a)))
    for i in range(1, 16):                             # the flanks, bellying out to the tip
        t = i / 16
        body.append((cx + r * math.cos(t * math.pi / 2) ** 0.7, cy - r * 0.55 + r * 1.6 * t))
    for i in range(15, 0, -1):
        t = i / 16
        body.append((cx - r * math.cos(t * math.pi / 2) ** 0.7, cy - r * 0.55 + r * 1.6 * t))
    body = [(round(x), round(y)) for x, y in body]
    mask = _bosch_shape(tile.size, lambda d: d.polygon(body, fill=255))

    def shade(x, y, rank):
        lit = ((x - cx) + (y - cy)) / (2 * r)
        return _bosch_pick(rank, ((white, max(0.0, 0.2 - 0.4 * lit)), (black, max(0.0, 0.4 * lit)), (red, 1)))
    _bosch_paint(tile, mask, shade)
    draw = ImageDraw.Draw(tile)
    mp = mask.load()
    for row, yy in enumerate(range(cy - round(r * 0.6), cy + r, 6)):   # seeds, staggered
        for xx in range(cx - r + (row % 2) * 3, cx + r, 6):
            if 0 <= xx < tile.size[0] and 0 <= yy + 2 < tile.size[1] and mp[xx, yy] and mp[xx, yy + 2]:
                draw.line([(xx, yy), (xx, yy + 1)], fill=yellow)
    top = cy - round(r * 0.55) - round(r * 0.5)
    for i in range(6):                                                 # calyx
        a = math.radians(-170 + i * 32)
        draw.polygon([(cx - 3, top + 3), (cx + round(r * 0.8 * math.cos(a)),
                       top + 4 + round(r * 0.35 * abs(math.sin(a)))), (cx + 3, top + 3)], fill=green)
    draw.line([(cx, top + 2), (cx + 4, top - 10)], fill=green, width=2)


def _bosch_cherry(tile, cx: int, cy: int, r: int, stem_to) -> None:
    white, red, black, green = (_bosch_ink(n) for n in ("white", "red", "black", "green"))
    mask = _bosch_shape(tile.size, lambda d: d.ellipse((cx - r, cy - r, cx + r, cy + r), fill=255))

    def shade(x, y, rank):
        lit = ((x - cx) + (y - cy)) / (2 * r)
        return _bosch_pick(rank, ((black, max(0.0, 0.45 * lit + 0.05)), (red, 1)))
    _bosch_paint(tile, mask, shade)
    draw = ImageDraw.Draw(tile)
    draw.ellipse((cx - r // 2 - 2, cy - r // 2 - 2, cx - r // 2 + 2, cy - r // 2 + 2), fill=white)
    draw.line([(cx, cy - r), stem_to], fill=green, width=2)


def _bosch_bubble(tile, cx: int, cy: int, r: int) -> None:
    """The lovers' glass bubble: the meadow seen through a pale blue skin."""
    white, blue = _bosch_ink("white"), _bosch_ink("blue")
    mask = _bosch_shape(tile.size, lambda d: d.ellipse((cx - r, cy - r, cx + r, cy + r), fill=255))

    def shade(x, y, rank):
        edge = math.hypot(x - cx, y - cy) / r
        if rank < 64 * (0.10 + 0.45 * edge ** 4):
            return blue if rank % 2 else white
        return None                                  # the meadow shows through
    _bosch_paint(tile, mask, shade)
    draw = ImageDraw.Draw(tile)
    draw.ellipse((cx - r, cy - r, cx + r, cy + r), outline=blue, width=2)
    draw.arc((cx - r + 6, cy - r + 6, cx + r - 6, cy + r - 6), 200, 250, fill=white, width=3)
    # Two tiny lovers inside — pale shapes, as they are in the painting.
    for dx in (-6, 5):
        draw.ellipse((cx + dx - 3, cy + 2, cx + dx + 3, cy + 14), fill=white)
        draw.ellipse((cx + dx - 2, cy - 4, cx + dx + 2, cy + 1), fill=white)


def _bosch_bird(tile, cx: int, cy: int, facing: int, inks) -> None:
    """One of the Garden's giant birds, perched: body, head, beak, a wing
    bar in its second colour, and a tail."""
    black = _bosch_ink("black")
    main, bar = inks
    draw = ImageDraw.Draw(tile)
    f = facing
    draw.polygon([(cx - f * 14, cy + 2), (cx - f * 28, cy + 12), (cx - f * 24, cy + 16), (cx - f * 10, cy + 8)],
                 fill=black)                                           # tail
    draw.ellipse((cx - 16, cy - 10, cx + 14, cy + 12), fill=main, outline=black)
    draw.ellipse((cx + f * 10 - 8, cy - 20, cx + f * 10 + 8, cy - 4), fill=main, outline=black)
    draw.polygon([(cx + f * 17, cy - 14), (cx + f * 27, cy - 11), (cx + f * 17, cy - 9)], fill=black)   # beak
    draw.ellipse((cx + f * 12 - 2, cy - 15, cx + f * 12 + 1, cy - 12), fill=black)                    # eye
    draw.chord((cx - 12, cy - 6, cx + 8, cy + 10), 0 if f > 0 else 180, 180 if f > 0 else 360, fill=bar)
    draw.line([(cx - 2, cy + 12), (cx - 4, cy + 20)], fill=black, width=1)                             # legs
    draw.line([(cx + 4, cy + 12), (cx + 6, cy + 20)], fill=black, width=1)


def _bosch_paint_garden(tile: Image.Image) -> None:
    w, h = tile.size
    white, blue, red, black, yellow, green = (_bosch_ink(n) for n in
                                              ("white", "blue", "red", "black", "yellow", "green"))
    horizon, lake_foot = 74, 124
    _bosch_sky(tile, horizon, 0.62, 0.84)
    lake = _bosch_shape(tile.size, lambda d: d.rectangle((0, horizon, w, lake_foot), fill=255))
    _bosch_paint(tile, lake, lambda x, y, r: _bosch_pick(
        r, ((white, 0.48 - 0.22 * (y - horizon) / (lake_foot - horizon)), (blue, 1))))
    _bosch_hills(tile, horizon, ((30, 22, 24), (410, 26, 22)), seed=11)
    _bosch_meadow(tile, lake_foot)
    draw = ImageDraw.Draw(tile)

    # The fountains of the far lake, alternating rose spires and blue globes.
    _bosch_rose_tower(tile, 218, 118, 40, 8)
    _bosch_blue_orb(tile, 218, 104, 13)
    _bosch_spikes(draw, 218, 104, 13, red, 5)
    for cx, kind in ((58, "orb"), (128, "tower"), (310, "tower"), (380, "orb")):
        if kind == "orb":
            _bosch_blue_orb(tile, cx, 106, 12)
            _bosch_spikes(draw, cx, 106, 12, red, 3)
        else:
            _bosch_rose_tower(tile, cx, 120, 70, 6, light=0.44)
    rng = random.Random(0xB05C)
    x = 4                                                              # a hedge of far trees
    while x < w:
        r = rng.randrange(4, 9)
        draw.ellipse((x - r, lake_foot - r - 2, x + r, lake_foot + r - 2), fill=black)
        draw.ellipse((x - r + 2, lake_foot - r - 1, x + r - 4, lake_foot + r - 6), fill=green)
        x += r + rng.randrange(6, 22)

    # The middle distance: the pool of bathers, ringed by the cavalcade of
    # riders circling it — the hub the whole centre panel turns around.
    pcx, pcy = w // 2, 176
    pool = _bosch_shape(tile.size, lambda d: d.ellipse((pcx - 104, pcy - 20, pcx + 104, pcy + 20), fill=255))
    _bosch_paint(tile, pool, lambda x, y, r: _bosch_pick(r, ((white, 0.34), (blue, 1))))
    for i in range(9):
        bx = pcx - 80 + i * 20 + (i % 2) * 4
        draw.ellipse((bx - 2, pcy - 6 + (i % 3) * 4, bx + 2, pcy - 2 + (i % 3) * 4), fill=white)
    for i in range(36):
        a = 2 * math.pi * i / 36
        rx, ry = pcx + 150 * math.cos(a), pcy + 36 * math.sin(a)
        ink = (red, white, black, yellow, blue, black)[i % 6]
        draw.ellipse((round(rx) - 4, round(ry) - 2, round(rx) + 4, round(ry) + 2), fill=ink)
        draw.ellipse((round(rx) - 1, round(ry) - 6, round(rx) + 1, round(ry) - 2), fill=white)

    _bosch_bird(tile, 98, 360, 1, (yellow, red))                         # a goldfinch
    _bosch_bird(tile, 338, 362, -1, (blue, white))                     # a kingfisher

    # The giant fruit of the foreground.
    _bosch_strawberry(tile, 60, 414, 26)
    _bosch_bubble(tile, 158, 408, 30)
    _bosch_cherry(tile, 262, 418, 14, (276, 386))
    _bosch_cherry(tile, 292, 424, 13, (276, 386))
    _bosch_strawberry(tile, 384, 412, 22)
    _bosch_birds(draw, ((316, 30, 4), (332, 22, 3), (96, 34, 3)), black)


# ---- Hell ------------------------------------------------------------------

def _bosch_flesh(rank: int, lit: float):
    """Bosch's pallid flesh: W-major, a little red and yellow, shading to black."""
    white, red, yellow, black = (_bosch_ink(n) for n in ("white", "red", "yellow", "black"))
    return _bosch_pick(rank, ((black, max(0.0, 0.35 * lit)), (red, 0.16), (yellow, 0.16), (white, 1)))


def _bosch_ear(tile, cx: int, top: int, w: int, h: int, facing: int) -> None:
    """One giant ear in profile: a broad rounded shell narrowing to a lobe,
    with the helix rolled along its rim and the dark bowl of the concha.

    ``facing`` is +1 for an ear whose opening faces right, -1 for left.
    """
    black = _bosch_ink("black")
    half = w / 2
    outline = []
    for i in range(25):                                # the rounded top and back
        a = math.pi + math.pi * 1.25 * i / 24
        outline.append((cx - facing * half * math.cos(a) * -1, top + half + half * math.sin(a)))
    outline.append((cx + facing * half * 0.35, top + h * 0.82))           # the lobe
    outline.append((cx - facing * half * 0.05, top + h))
    outline.append((cx - facing * half * 0.55, top + h * 0.84))
    outline = [(round(x), round(y)) for x, y in outline]
    mask = _bosch_shape(tile.size, lambda d: d.polygon(outline, fill=255))
    _bosch_paint(tile, mask, lambda x, y, r: _bosch_flesh(r, max(0.0, ((x - cx) * facing + (y - top - h / 2)) / h)))
    draw = ImageDraw.Draw(tile)
    draw.polygon(outline, outline=black)
    inner = (cx - half * 0.62, top + half * 0.38, cx + half * 0.62, top + half * 1.62)
    start, end = (150, 20) if facing > 0 else (160, 30)
    draw.arc([round(v) for v in inner], start, end, fill=black, width=1)  # the helix fold
    bowl = (cx - facing * 3 - 5, top + half - 4, cx - facing * 3 + 5, top + half + 9)
    draw.ellipse([round(v) for v in bowl], fill=black)                     # the concha


def _bosch_paint_hell(tile: Image.Image) -> None:
    w, h = tile.size
    white, blue, red, black, yellow, green = (_bosch_ink(n) for n in
                                              ("white", "blue", "red", "black", "yellow", "green"))
    draw = ImageDraw.Draw(tile)

    # A wall of fire behind the city: yellow-hot at the root, red only at the
    # tips, because red on black is the lowest-contrast pair the inks offer.
    def crest(x: float) -> float:
        return 30 + 16 * abs(math.sin(x * 0.11)) + 10 * math.sin(x * 0.047 + 1.3)

    fire_foot = 112
    blaze = [(0, fire_foot)] + [(x, crest(x)) for x in range(0, w + 3, 3)] + [(w, fire_foot)]
    fire = _bosch_shape(tile.size, lambda d: d.polygon(blaze, fill=255))

    def flame(x, y, rank):
        t = (y - crest(x)) / max(1.0, fire_foot - crest(x))   # 0 tip .. 1 root
        return _bosch_pick(rank, ((white, 0.4 * t * t), (red, 0.75 * (1 - t) ** 1.5), (yellow, 1)))
    _bosch_paint(tile, fire, flame)
    paint_neon_mask(tile, fire, None, red, radius=7, gamma=1.3, cap=0.55,
                    ground=frozenset({black}), tile=BAYER_8x8,
                    glow_minor=yellow, glow_minor_share=0.375)
    fire.close()
    draw.rectangle((0, fire_foot, w, 150), fill=black)   # the glow lights the sky, not the ground
    # The city burning: black gables and towers against the blaze.
    skyline = [(0, 114), (0, 84), (8, 84), (8, 70), (16, 60), (24, 70), (24, 90), (36, 90), (36, 54),
               (42, 42), (48, 54), (48, 86), (60, 86), (60, 76), (72, 64), (84, 76), (84, 92), (98, 92),
               (98, 50), (104, 36), (110, 50), (110, 82), (124, 82), (130, 72), (136, 82), (136, 94),
               (w, 94), (w, 114)]
    draw.polygon(skyline, fill=black)
    for x, y in ((40, 62), (102, 58), (102, 70), (76, 80), (16, 76), (128, 88)):
        draw.rectangle((x, y, x + 1, y + 3), fill=yellow)

    # The knife between two ears — the blade marked with its letter M.
    _bosch_ear(tile, 42, 122, 38, 54, -1)
    _bosch_ear(tile, 86, 122, 38, 54, 1)
    blade = [(58, 146), (144, 132), (152, 138), (60, 160)]
    draw.polygon(blade, fill=white, outline=black)
    draw.line([(62, 153), (146, 136)], fill=blue, width=1)              # the bevel's cold edge
    draw.text((96, 139), "M", font=load_font([(GRENZE_GOTISCH_VARIABLE, "Black"), *META_FONT_BOLD_CANDIDATES],
                                            size=11), fill=black)
    draw.line([(8, 170), (140, 162)], fill=black, width=3)             # the arrow through them
    draw.line([(8, 170), (140, 162)], fill=white, width=1)
    draw.polygon([(146, 161), (134, 156), (136, 168)], fill=white, outline=black)
    for fx in (8, 14):
        draw.line([(fx, 164), (fx + 4, 176)], fill=red, width=2)

    # The Tree-Man: a broken egg-shell body on rotten trunk legs, turning
    # his head back toward us from under a disc hat carrying a bagpipe.
    for leg in ([(70, 292), (80, 292), (62, 372), (50, 372)], [(96, 292), (106, 292), (114, 372), (102, 372)]):
        m = _bosch_shape(tile.size, lambda d, leg=leg: d.polygon(leg, fill=255))
        _bosch_paint(tile, m, lambda x, y, r: black if r < 16 else (red if (x + y) & 1 else green))
        draw.polygon(leg, outline=black)
    draw.line([(68, 324), (54, 314)], fill=black, width=2)             # snapped branches
    draw.line([(106, 336), (120, 326)], fill=black, width=2)
    shell = (50, 226, 126, 300)
    body = _bosch_shape(tile.size, lambda d: d.ellipse(shell, fill=255))
    _bosch_paint(tile, body, lambda x, y, r: _bosch_flesh(r, max(0.0, ((x - 88) + (y - 263)) / 64)))
    draw.ellipse(shell, outline=black, width=1)
    draw.polygon([(104, 240), (126, 256), (126, 284), (110, 296), (100, 276), (108, 262)], fill=black)
    draw.rectangle((112, 270, 114, 275), fill=yellow)                  # the tavern inside him
    head_box = (34, 212, 62, 242)
    head = _bosch_shape(tile.size, lambda d: d.ellipse(head_box, fill=255))
    _bosch_paint(tile, head, lambda x, y, r: _bosch_flesh(r, max(0.0, (x - 48) / 14) * 0.5))
    draw.ellipse(head_box, outline=black, width=1)
    draw.ellipse((40, 222, 43, 225), fill=black)
    draw.ellipse((50, 222, 53, 225), fill=black)
    draw.arc((41, 226, 53, 236), 20, 160, fill=black, width=1)
    hat_box = (20, 202, 120, 216)                                      # the grey disc hat
    hat = _bosch_shape(tile.size, lambda d: d.ellipse(hat_box, fill=255))
    _bosch_paint(tile, hat, lambda x, y, r: black if r < 22 + (y - 209) * 3 else white)
    draw.ellipse(hat_box, outline=black, width=1)
    bag = _bosch_shape(tile.size, lambda d: d.ellipse((50, 186, 84, 208), fill=255))
    _bosch_paint(tile, bag, lambda x, y, r: _bosch_pick(r, ((black, max(0.0, (x - 67) / 60)), (red, 0.45), (white, 1))))
    draw.ellipse((50, 186, 84, 208), outline=black, width=1)
    draw.line([(80, 192), (102, 180)], fill=black, width=3)             # the chanter
    draw.line([(62, 188), (70, 172)], fill=black, width=2)              # the drone

    # The frozen lake: boats locked in the ice, a hole broken through it.
    ice = _bosch_shape(tile.size, lambda d: d.rectangle((0, 366, w, h), fill=255))
    _bosch_paint(tile, ice, lambda x, y, r: _bosch_pick(r, ((white, 0.56), (blue, 1))))
    for boat_x in (48, 110):
        draw.polygon([(boat_x - 18, 368), (boat_x + 18, 368), (boat_x + 11, 380), (boat_x - 11, 380)], fill=black)
    draw.ellipse((18, 412, 66, 430), fill=black)
    draw.line([(80, 396), (104, 410), (140, 404)], fill=white, width=1)
    draw.line([(10, 446), (40, 436), (72, 444)], fill=blue, width=1)
    for x, y in ((118, 428), (134, 438), (92, 440)):                   # skaters
        draw.rectangle((x, y - 6, x + 2, y), fill=black)
        draw.point((x + 1, y - 8), fill=black)


# ---- the banderole ---------------------------------------------------------

def _bosch_scroll_layout(draw, quote_row: dict):
    """Fit the quote and size the banderole to it (the ``pride`` card rule)."""
    text = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    max_w, max_h = _BOSCH_TEXT_MAX
    credit_h = _BOSCH_CREDIT_SIZE + 10
    regular, bold, wrapped, line_height, _ = fit_quote(
        draw, text, quote_row.get("matched_text") or "", max_w, max_h - credit_h,
        font_max=30, font_min=14, line_height_mult=1.2, theme="bosch",
    )
    widest = 0
    for line in wrapped:
        segment = [c for c in line]
        while segment and segment[0][0].strip() == "":
            segment.pop(0)
        while segment and segment[-1][0].strip() == "":
            segment.pop()
        widest = max(widest, sum(draw.textbbox((0, 0), c, font=bold if b else regular)[2] for c, b in segment))
    pad_x, pad_y = _BOSCH_SCROLL_PAD
    body_w = max(_BOSCH_SCROLL_MIN_W, min(max_w, widest) + 2 * pad_x)
    body_h = len(wrapped) * line_height + credit_h + 2 * pad_y
    cx, cy = _BOSCH_SCROLL_CENTRE
    rect = (cx - body_w // 2, cy - body_h // 2, cx + body_w // 2, cy + body_h // 2)
    return regular, bold, wrapped, line_height, rect


def _bosch_scroll_edge(x: float, rect, side: int) -> float:
    """y of the banderole's top (side=-1) or bottom (+1) edge — a flutter."""
    x0, y0, x1, y1 = rect
    wave = _BOSCH_SCROLL_WAVE * math.sin((x - x0) / (x1 - x0) * math.pi * 2.0 + 0.6)
    return (y0 if side < 0 else y1) + wave


def _bosch_scroll_mask(size, rect) -> Image.Image:
    x0, y0, x1, y1 = rect
    top = [(x, _bosch_scroll_edge(x, rect, -1)) for x in range(x0, x1 + 1, 4)]
    bottom = [(x, _bosch_scroll_edge(x, rect, 1)) for x in range(x1, x0 - 1, -4)]
    return _bosch_shape(size, lambda d: d.polygon(top + bottom, fill=255))


def _bosch_paint_scroll(image: Image.Image, rect) -> None:
    """Parchment banderole with a cast shadow and two rolled ends."""
    x0, y0, x1, y1 = rect
    white, yellow, black, red = (_bosch_ink(n) for n in ("white", "yellow", "black", "red"))
    shadow = _bosch_scroll_mask(image.size, (x0 + 6, y0 + 7, x1 + 6, y1 + 7))
    _bosch_paint(image, shadow, lambda x, y, r: black if r < 30 else None)
    body = _bosch_scroll_mask(image.size, rect)
    # Parchment: sparse cream, a touch darker toward the fluttering edges.
    cy = (y0 + y1) / 2

    def parchment(x, y, rank):
        edge = abs(y - cy) / ((y1 - y0) / 2)
        if rank < 64 * (0.13 + 0.10 * edge ** 3):
            return yellow
        if rank > 64 - 64 * 0.05 * edge ** 6:
            return red
        return white
    _bosch_paint(image, body, parchment)
    draw = ImageDraw.Draw(image)
    top = [(x, round(_bosch_scroll_edge(x, rect, -1))) for x in range(x0, x1 + 1, 2)]
    bottom = [(x, round(_bosch_scroll_edge(x, rect, 1))) for x in range(x0, x1 + 1, 2)]
    draw.line(top, fill=black, width=1)
    draw.line(bottom, fill=black, width=1)
    # Rolled ends: cylinders taller than the body, lit left, shaded right.
    rw = _BOSCH_ROLL_W
    for side, ex in ((-1, x0), (1, x1)):
        et, eb = _bosch_scroll_edge(ex, rect, -1), _bosch_scroll_edge(ex, rect, 1)
        rx0 = ex - rw if side < 0 else ex
        box = (rx0, round(et) - 5, rx0 + rw, round(eb) + 5)
        roll = _bosch_shape(image.size, lambda d, box=box: d.rounded_rectangle(box, radius=rw // 2, fill=255))

        def shade(x, y, rank, rx0=rx0):
            t = (x - rx0) / rw                          # 0 lit edge .. 1 shadow edge
            return _bosch_pick(rank, ((black, max(0.0, 0.55 * (t - 0.35))), (yellow, 0.3), (white, 1)))
        _bosch_paint(image, roll, shade)
        draw.rounded_rectangle(box, radius=rw // 2, outline=black, width=1)
        cx_ = rx0 + rw // 2
        draw.arc((cx_ - 4, box[1] + 2, cx_ + 4, box[1] + 8), 0, 300, fill=black, width=1)  # the spiral


def _bosch_draw_lettering(draw, regular, bold, wrapped, line_height, rect, quote_row: dict,
                          ink, accent) -> None:
    x0, y0, x1, y1 = rect
    pad_x, pad_y = _BOSCH_SCROLL_PAD
    credit_y = draw_centred_styled_lines(
        draw, wrapped, x0=x0, x1=x1, top=y0 + pad_y, line_height=line_height,
        regular=regular, bold=bold, fill=ink, accent=accent, min_inset=pad_x,
    )
    credit_font = load_font(theme_font_candidates("bosch", "quote_regular"), size=_BOSCH_CREDIT_SIZE)
    draw_truncated_centred_byline(
        draw, quote_row, centre=(x0 + x1) // 2, baseline=credit_y + _BOSCH_CREDIT_SIZE + 2,
        max_width=x1 - x0 - 2 * pad_x, font=credit_font, fill=ink,
    )


# ---- craquelure --------------------------------------------------------------

def paint_craquelure(
    image: Image.Image,
    region: Image.Image,
    *,
    seed: int,
    cell=(21, 13),
    jitter: float = 0.36,
    drop: float = 0.2,
    diagonal: float = 0.14,
    continuity: int = 5,
    dark=None,
    light=None,
    light_share: float = 0.15,
    keep_out: Image.Image | None = None,
    keep_out_pad: int = 2,
) -> Image.Image:
    """Craze a painted surface with an aged-varnish crack network.

    The net is a *graph* (connected by construction, unlike a thresholded noise
    field): a lattice of ``cell``-spaced vertices, each nudged by up to
    ``jitter`` of a cell, whose right and down edges are polylines bowed at the
    midpoint. ``drop`` of the edges are left out so islands merge into larger
    blocks; ``diagonal`` of the cells gain a corner-to-corner split so the net
    does not read as a grid.

    Along the net, ``continuity`` of every 8 pixels are painted (positional
    hash), so fissures read as fine and broken. A crack pixel takes ``dark`` on
    light paint and ``light`` where the paint is already ``dark``, but only
    ``light_share`` of those open, since full strength would read as a white
    net laid over the black.

    ``region`` (``"L"``) confines the net to the painted surface; ``keep_out``
    (``"L"``) is dilated by ``keep_out_pad`` and never cracked. Returns the
    crack mask. Deterministic for a given ``seed``.
    """
    dark = SPECTRA6["black"] if dark is None else dark
    light = SPECTRA6["white"] if light is None else light
    width, height = image.size
    rng = random.Random(seed)
    cw, ch = cell
    cols, rows = width // cw + 2, height // ch + 2
    verts = {}
    for j in range(rows):
        for i in range(cols):
            verts[i, j] = (i * cw + rng.uniform(-jitter, jitter) * cw,
                           j * ch + rng.uniform(-jitter, jitter) * ch)
    net = Image.new("L", image.size, 0)
    nd = ImageDraw.Draw(net)

    def crack(p, q, bow: float) -> None:
        mx, my = (p[0] + q[0]) / 2, (p[1] + q[1]) / 2
        dx, dy = q[0] - p[0], q[1] - p[1]
        mx, my = mx - dy * bow, my + dx * bow
        nd.line([(round(p[0]), round(p[1])), (round(mx), round(my)), (round(q[0]), round(q[1]))],
                fill=255, width=1)

    for j in range(rows):
        for i in range(cols):
            p = verts[i, j]
            # Draw every random number whether or not the edge is kept, so one
            # edge's fate never shifts the stream for the rest of the net.
            for di, dj in ((1, 0), (0, 1)):
                keep, bow = rng.random() >= drop, rng.uniform(-0.16, 0.16)
                q = verts.get((i + di, j + dj))
                if keep and q is not None:
                    crack(p, q, bow)
            split, flip, bow = rng.random() < diagonal, rng.random() < 0.5, rng.uniform(-0.1, 0.1)
            if split and (i + 1, j + 1) in verts:
                a, b = ((i, j), (i + 1, j + 1)) if flip else ((i + 1, j), (i, j + 1))
                crack(verts[a], verts[b], bow)

    guard = None
    if keep_out is not None:
        guard = keep_out.filter(ImageFilter.MaxFilter(2 * keep_out_pad + 1)).load()
    painted = Image.new("L", image.size, 0)
    px, rp, np_, pp = image.load(), region.load(), net.load(), painted.load()
    bbox = net.getbbox()
    if bbox is None:
        return painted
    for y in range(bbox[1], bbox[3]):
        for x in range(bbox[0], bbox[2]):
            if not np_[x, y] or not rp[x, y] or (guard is not None and guard[x, y]):
                continue
            h = position_noise(x, y)
            if h % 8 >= continuity:
                continue
            if px[x, y] == dark:
                if (h >> 3) % 64 < light_share * 64:
                    px[x, y] = light
                    pp[x, y] = 255
            else:
                px[x, y] = dark
                pp[x, y] = 255
    net.close()
    return painted


# ---- assembly ----------------------------------------------------------------

_BOSCH_PAINTERS = {
    "paradise": _bosch_paint_paradise,
    "garden": _bosch_paint_garden,
    "hell": _bosch_paint_hell,
}


def _bosch_panel_region(size) -> Image.Image:
    """The union of the three arched panel shapes, where craquelure may craze
    (never the frame). Pure geometry, so it does not depend on what was drawn."""
    region = Image.new("L", size, 0)
    for kind, (x0, y0, x1, y1) in _BOSCH_PANELS:
        mask = _bosch_panel_mask(kind, (x1 - x0, y1 - y0))
        region.paste(mask, (x0, y0), mask)
    return region


def _bosch_paint_panels(image: Image.Image) -> None:
    """Paint each wing onto its own tile and set it into the frame."""
    for kind, (x0, y0, x1, y1) in _BOSCH_PANELS:
        size = (x1 - x0, y1 - y0)
        ground = SPECTRA6["black"] if kind == "hell" else SPECTRA6["white"]
        tile = Image.new("RGB", size, ground)
        tile._bosch_origin = (x0, y0)
        _BOSCH_PAINTERS[kind](tile)
        image.paste(tile, (x0, y0), _bosch_panel_mask(kind, size))
        tile.close()


def render_bosch_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """*The Garden of Earthly Delights*, open (see the section comment above)."""
    del time_str  # an altarpiece carries no hour; the matched phrase is the clock.
    image = Image.new("RGB", (800, 480), color=SPECTRA6["black"])
    _bosch_paint_frame(image)
    _bosch_paint_panels(image)
    region = _bosch_panel_region(image.size)
    draw = ImageDraw.Draw(image)
    regular, bold, wrapped, line_height, rect = _bosch_scroll_layout(draw, quote_row)
    _bosch_paint_scroll(image, rect)
    _bosch_draw_lettering(draw, regular, bold, wrapped, line_height, rect, quote_row,
                          SPECTRA6["black"], SPECTRA6["red"])
    lettering = Image.new("L", image.size, 0)
    _bosch_draw_lettering(ImageDraw.Draw(lettering), regular, bold, wrapped, line_height, rect,
                          quote_row, 255, 255)
    paint_craquelure(image, region, seed=_BOSCH_CRACK_SEED, cell=_BOSCH_CRACK_CELL, keep_out=lettering)
    lettering.close()
    region.close()
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# semiotic — Ron Cobb's Semiotic Standard, the Nostromo signage from *Alien*
# ---------------------------------------------------------------------------
# A custom frame: a black bulkhead between yellow/black hazard stripes, one
# large sign for the hour with three smaller companions, and the quote on a
# crew-notice placard framed the way Cobb framed his signs — white edge, red
# band, white panel, the band broken at the rules.
#
# **The signs are the real set, not redrawn.** ``SEMIOTIC_SIGNS`` is a sprite
# sheet built by ``scripts/ingest_semiotic_signs.py`` from LouH's CC BY 4.0
# vector adaptation (attribution in ``assets/semiotic/README.md``). Its seven
# flat colours each map to one native ink, except the "system" grey, which is
# the K+W 50/50 stipple, so the signs need classification, not dithering.
#
# **Classify after resizing, never before.** Each antialiased tile is resized
# to its painted size, composited onto the black ground, and only then snapped
# by ``quantize`` to the seven source values; snapping first and resizing
# blends inks off-palette. The grey's stipple is phased on absolute canvas
# coordinates so adjacent grey fields share one checkerboard.
#
# **The hour is the section**: the featured sign is the hour's
# (``_SEMIOTIC_HOUR_SIGNS``) and the header reads ``SECTION 07``. Hour only, so
# every minute of an hour renders byte-identically. The three companions and
# the notice's reference number come from ``_row_digest``.
#
# If the sheet is missing the signs degrade to blank red-framed panels.
SEMIOTIC_SIGNS = BASE_DIR / "assets" / "semiotic_signs.png"
_SEMIOTIC_SHEET_COLS = 6
_SEMIOTIC_TILE = (250, 262)
_SEMIOTIC_SHEET_CACHE: dict = {}

# Legend order — must match ``scripts/ingest_semiotic_signs.py``'s ``SIGNS``.
_SEMIOTIC_SIGNS: tuple[tuple[str, str], ...] = (
    ("001", "PRESSURISED AREA"),
    ("002", "PRESSURISED WITH ARTIFICIAL GRAVITY"),
    ("003", "ARTIFICIAL GRAVITY ABSENT"),
    ("004", "CRYOGENIC VAULT"),
    ("005", "AIRLOCK"),
    ("006", "BULKHEAD DOOR"),
    ("007", "NON-PRESSURISED AREA BEYOND"),
    ("008", "PRESSURE SUIT LOCKER"),
    ("009", "PHOTONIC SYSTEM (FIBRE OPTICS)"),
    ("010", "LASER"),
    ("011", "ASTRONIC SYSTEM (ELECTRONICS)"),
    ("012", "HAZARD WARNING"),
    ("013", "ARTIFICIAL GRAVITY AREA, NON-PRESSURISED SUIT REQUIRED"),
    ("014", "NO PRESSURE, GRAVITY SUIT REQUIRED"),
    ("015", "EXHAUST"),
    ("016", "AREA SHIELDED FROM RADIATION"),
    ("017", "RADIATION HAZARD"),
    ("018", "HIGH RADIOACTIVITY"),
    ("019", "REFRIGERATION"),
    ("020", "DIRECTION"),
    ("020A", "DIRECTION"),
    ("020B", "DIRECTION"),
    ("020C", "DIRECTION"),
    ("021", "LIFE SUPPORT SYSTEM"),
    ("022", "GALLEY"),
    ("023", "COFFEE"),
    ("024", "BRIDGE"),
    ("025", "AUTODOC"),
    ("026", "MAINTENANCE"),
    ("027", "LADDERWAY"),
    ("028", "INTERCOM"),
    ("029", "STORAGE, NON-ORGANIC"),
    ("029A", "STORAGE, ORGANIC (FOODSTUFFS)"),
    ("030", "COMPUTER TERMINAL"),
)
_SEMIOTIC_INDEX = {code: i for i, (code, _) in enumerate(_SEMIOTIC_SIGNS)}
_SEMIOTIC_NAMES = dict(_SEMIOTIC_SIGNS)

# One sign per hour, chosen for silhouette variety across the day.
_SEMIOTIC_HOUR_SIGNS = {
    1: "005", 2: "006", 3: "003", 4: "004", 5: "008", 6: "010",
    7: "012", 8: "014", 9: "015", 10: "018", 11: "030", 12: "024",
}
# Companions: every sign except the blank-panel "pressurised area" and the
# four direction chevrons, which read as decoration rather than as places.
_SEMIOTIC_COMPANION_POOL = tuple(
    code for code, _ in _SEMIOTIC_SIGNS if code != "001" and not code.startswith("020")
)

# The adaptation's seven flat values and the ink each lands on (None = the
# K+W stipple). Measured off the upstream PNGs; amber appears as both
# (255, 176, 0) and (255, 170, 0), which one entry covers.
_SEMIOTIC_SOURCE_INKS: tuple[tuple[tuple[int, int, int], tuple[int, int, int] | None], ...] = (
    ((255, 255, 255), SPECTRA6["white"]),
    ((0, 0, 0), SPECTRA6["black"]),
    ((160, 0, 0), SPECTRA6["red"]),
    ((255, 176, 0), SPECTRA6["yellow"]),
    ((10, 10, 112), SPECTRA6["blue"]),
    ((0, 68, 17), SPECTRA6["green"]),
    ((96, 96, 96), None),
)

_SEMIOTIC_FEATURE_BOX = (24, 60, 220, 231)          # x, y, w, h — the 1000:1050 aspect
_SEMIOTIC_COMPANION_Y = 373
_SEMIOTIC_COMPANION_SIZE = (68, 71)
_SEMIOTIC_COMPANION_XS = (24, 100, 176)
_SEMIOTIC_PLACARD = (264, 60, 776, 444)
_SEMIOTIC_HAZARD_BANDS = ((0, 16), (458, 480))
_SEMIOTIC_STRIPE = 14                                  # hazard stripe width, px
_SEMIOTIC_HEADER_RULE_Y = 120
_SEMIOTIC_FOOTER_RULE_Y = 384
_SEMIOTIC_QUOTE_RECT = (306, 132, 734, 374)
_SEMIOTIC_LAMPS = ("blue", "green", "yellow", "red")


def _semiotic_font(weight: str, size: int):
    """Barlow Condensed at a named weight, falling back like the theme chains."""
    path = {"Medium": BARLOWCOND_MEDIUM, "SemiBold": BARLOWCOND_SEMIBOLD, "Bold": BARLOWCOND_BOLD}[weight]
    return load_font([path, (OSWALD_VARIABLE, weight), *META_FONT_BOLD_CANDIDATES], size=size)


def _semiotic_companions(quote_row: dict, featured: str) -> tuple[str, str, str]:
    """Three distinct companion signs for this quote, never the featured one."""
    pool = [code for code in _SEMIOTIC_COMPANION_POOL if code != featured]
    rng = random.Random(_row_digest(quote_row))
    return tuple(rng.sample(pool, 3))


def _semiotic_sheet() -> Image.Image | None:
    """The decoded sprite sheet, memoised per process; ``None`` if missing."""
    key = str(SEMIOTIC_SIGNS)
    if key not in _SEMIOTIC_SHEET_CACHE:
        try:
            with Image.open(SEMIOTIC_SIGNS) as sheet:
                _SEMIOTIC_SHEET_CACHE[key] = sheet.convert("RGBA")
        except (OSError, ValueError):
            _SEMIOTIC_SHEET_CACHE[key] = None
    return _SEMIOTIC_SHEET_CACHE[key]


def _semiotic_palette_image(values) -> Image.Image:
    """A ``P`` image carrying ``values`` (a subset of the source values), for
    ``quantize``.

    Unused slots repeat the first entry; ``_semiotic_classify`` maps indices by
    their palette colour, not their position, so a duplicate can never pick a
    different ink.
    """
    flat = [c for v in values for c in v]
    flat += list(values[0]) * (256 - len(values))
    pal = Image.new("P", (1, 1))
    pal.putpalette(flat)
    return pal


_SEMIOTIC_VALUES_CACHE: dict = {}


def _semiotic_sign_values(code: str, master: Image.Image) -> tuple:
    """The source values this sign actually uses, in ``_SEMIOTIC_SOURCE_INKS`` order.

    Against all seven, an antialiased seam can land on a colour the sign lacks
    (a black/white edge averages close to the dark green). Restricting each
    sign to values covering at least 0.5% of its opaque master keeps edges on
    the inks that meet there. Black is always allowed (the ground).
    """
    if code not in _SEMIOTIC_VALUES_CACHE:
        all_values = [v for v, _ in _SEMIOTIC_SOURCE_INKS]
        opaque = Image.new("RGBA", master.size, SPECTRA6["black"] + (255,))
        opaque.alpha_composite(master)
        indexed = opaque.convert("RGB").quantize(palette=_semiotic_palette_image(all_values),
                                                 dither=Image.Dither.NONE)
        counts = indexed.histogram()
        floor = 0.005 * master.width * master.height
        keep = {all_values[i] for i in range(len(all_values)) if counts[i] >= floor}
        keep.add((0, 0, 0))
        _SEMIOTIC_VALUES_CACHE[code] = tuple(v for v in all_values if v in keep)
    return _SEMIOTIC_VALUES_CACHE[code]


def _semiotic_classify(tile: Image.Image, origin: tuple[int, int], values) -> Image.Image:
    """Snap an RGB tile onto the inks: nearest of ``values``, then grey → the
    K+W checkerboard phased on absolute canvas coordinates."""
    indexed = tile.quantize(palette=_semiotic_palette_image(values), dither=Image.Dither.NONE)
    table = indexed.getpalette()[: 3 * 256]
    lookup = {v: ink for v, ink in _SEMIOTIC_SOURCE_INKS}
    grey_index = []
    inks = []
    for i in range(256):
        value = tuple(table[3 * i:3 * i + 3]) if 3 * i + 2 < len(table) else (255, 255, 255)
        ink = lookup.get(value, SPECTRA6["white"])
        grey_index.append(255 if value in lookup and ink is None else 0)
        inks.extend(ink if ink is not None else SPECTRA6["white"])
    base = indexed.copy()
    base.putpalette(inks)
    base = base.convert("RGB")
    idx = Image.frombytes("L", indexed.size, indexed.tobytes())
    grey = idx.point(grey_index)
    if grey.getbbox() is not None:
        w, h = tile.size
        ox, oy = origin
        even = bytes(255 if (x + ox) & 1 else 0 for x in range(w + 1))
        rows = b"".join(even[(p := (y + oy) & 1):p + w] for y in range(h))
        checker = Image.frombytes("L", (w, h), rows)
        base.paste(SPECTRA6["black"], (0, 0), ImageChops.multiply(grey, checker))
    return base


def _semiotic_paint_sign(image: Image.Image, code: str, box: tuple[int, int, int, int]) -> None:
    """Paint one Standard sign at ``box`` (x, y, w, h) onto the black ground."""
    x0, y0, w, h = box
    sheet = _semiotic_sheet()
    if sheet is None:
        draw = ImageDraw.Draw(image)
        r = max(4, w // 7)
        draw.rounded_rectangle((x0, y0, x0 + w - 1, y0 + h - 1), radius=r, fill=SPECTRA6["white"])
        inset = max(2, w // 40)
        draw.rounded_rectangle((x0 + inset, y0 + inset, x0 + w - 1 - inset, y0 + h - 1 - inset),
                               radius=r - inset, fill=SPECTRA6["red"])
        band = max(4, w // 10)
        draw.rounded_rectangle((x0 + band, y0 + band, x0 + w - 1 - band, y0 + h - 1 - band),
                               radius=max(2, r - band), fill=SPECTRA6["white"])
        return
    i = _SEMIOTIC_INDEX[code]
    tw, th = _SEMIOTIC_TILE
    sx, sy = (i % _SEMIOTIC_SHEET_COLS) * tw, (i // _SEMIOTIC_SHEET_COLS) * th
    full = sheet.crop((sx, sy, sx + tw, sy + th))
    values = _semiotic_sign_values(code, full)
    master = full.resize((w, h), Image.Resampling.LANCZOS)
    ground = Image.new("RGBA", (w, h), SPECTRA6["black"] + (255,))
    ground.alpha_composite(master)
    inked = _semiotic_classify(ground.convert("RGB"), (x0, y0), values)
    mask = master.getchannel("A").point(lambda a: 255 if a > 127 else 0)
    image.paste(inked, (x0, y0), mask)


def _semiotic_paint_hazard(image: Image.Image) -> None:
    """Yellow/black 45-degree hazard stripes across the head and foot."""
    width = image.width
    s = _SEMIOTIC_STRIPE
    for y0, y1 in _SEMIOTIC_HAZARD_BANDS:
        h = y1 - y0
        band = Image.new("RGB", (width, h), SPECTRA6["black"])
        draw = ImageDraw.Draw(band)
        for k in range(-h, width + h, 2 * s):
            draw.polygon([(k, h), (k + s, h), (k + s + h, 0), (k + h, 0)], fill=SPECTRA6["yellow"])
        image.paste(band, (0, y0))


def _semiotic_paint_header(image: Image.Image, draw: ImageDraw.ImageDraw, hour: int) -> None:
    """Standard name left; status lamps and the hour's section right."""
    white, yellow = SPECTRA6["white"], SPECTRA6["yellow"]
    font = _semiotic_font("SemiBold", 17)
    draw_tracked(draw, (24, 25), "SEMIOTIC STANDARD", font, white, tracking=3)
    right = image.width - 24
    draw_tracked(draw, (right, 25), f"{hour:02d}", _semiotic_font("Bold", 17), yellow, tracking=2, anchor_right=True)
    num_w = tracked_width(draw, f"{hour:02d}", _semiotic_font("Bold", 17), tracking=2)
    label_w = draw_tracked(draw, (right - num_w - 8, 25), "SECTION", font, white, tracking=3, anchor_right=True)
    x = right - num_w - 8 - label_w - 22
    for name in reversed(_SEMIOTIC_LAMPS):
        draw.ellipse((x - 5, 31, x + 5, 41), fill=SPECTRA6[name], outline=white)
        x -= 18


def _semiotic_wrap_name(draw, name: str, max_w: int) -> tuple[list[str], object]:
    """The featured sign's name in at most two lines, shrinking to fit."""
    for size in (19, 17, 15, 13):
        font = _semiotic_font("Bold", size)
        lines, line = [], ""
        for word in name.split():
            trial = f"{line} {word}".strip()
            if line and tracked_width(draw, trial, font, tracking=1) > max_w:
                lines.append(line)
                line = word
            else:
                line = trial
        lines.append(line)
        if len(lines) <= 2 and all(tracked_width(draw, ln, font, tracking=1) <= max_w for ln in lines):
            return lines, font
    return lines[:2], font


def _semiotic_paint_signs(image: Image.Image, draw: ImageDraw.ImageDraw, hour: int, quote_row: dict) -> None:
    """The hour's sign, its number and name, and three companions below."""
    featured = _SEMIOTIC_HOUR_SIGNS[hour]
    x, y, w, h = _SEMIOTIC_FEATURE_BOX
    _semiotic_paint_sign(image, featured, (x, y, w, h))
    label_y = y + h + 8
    draw_tracked(draw, (x, label_y), f"NO. {featured}", _semiotic_font("SemiBold", 14), SPECTRA6["yellow"], tracking=2)
    lines, font = _semiotic_wrap_name(draw, _SEMIOTIC_NAMES[featured], w)
    ly = label_y + 19
    for line in lines:
        draw_tracked(draw, (x, ly), line, font, SPECTRA6["white"], tracking=1)
        ly += font.size + 2
    cw, ch = _SEMIOTIC_COMPANION_SIZE
    for cx, code in zip(_SEMIOTIC_COMPANION_XS, _semiotic_companions(quote_row, featured)):
        _semiotic_paint_sign(image, code, (cx, _SEMIOTIC_COMPANION_Y, cw, ch))


def _semiotic_paint_placard(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The crew notice, framed as Cobb framed a sign: white edge, red band
    broken where the header and footer rules cross it, white panel."""
    x0, y0, x1, y1 = _SEMIOTIC_PLACARD
    white, red, black = SPECTRA6["white"], SPECTRA6["red"], SPECTRA6["black"]
    draw.rounded_rectangle((x0, y0, x1, y1), radius=24, fill=white)
    draw.rounded_rectangle((x0 + 6, y0 + 6, x1 - 6, y1 - 6), radius=19, fill=red)
    draw.rounded_rectangle((x0 + 19, y0 + 19, x1 - 19, y1 - 19), radius=8, fill=white)
    for ry in (_SEMIOTIC_HEADER_RULE_Y, _SEMIOTIC_FOOTER_RULE_Y):
        draw.rectangle((x0 + 6, ry - 4, x0 + 19, ry + 4), fill=white)
        draw.rectangle((x1 - 19, ry - 4, x1 - 6, ry + 4), fill=white)
        draw.rectangle((x0 + 19, ry - 1, x1 - 19, ry + 1), fill=black)

    head = _semiotic_font("Bold", 22)
    draw_tracked(draw, (x0 + 34, 86), "CREW NOTICE", head, black, tracking=3)
    ref = f"REF {_row_digest(quote_row) % 10000:04d}-{_row_digest(quote_row) // 10000 % 100:02d}"
    draw_tracked(draw, (x1 - 34, 91), ref, _semiotic_font("SemiBold", 15), black, tracking=2, anchor_right=True)

    prose, hot, _ = wrap_quote_into_masks(
        draw, image.size, quote_row, _SEMIOTIC_QUOTE_RECT, theme="semiotic",
        font_max=40, font_min=16, line_height_mult=1.16,
    )
    image.paste(black, (0, 0), prose.point(lambda v: 255 if v > 128 else 0))
    image.paste(red, (0, 0), hot.point(lambda v: 255 if v > 128 else 0))
    prose.close()
    hot.close()

    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "")
    byline = " · ".join(part.upper() for part in (author, title) if part)
    if byline:
        candidates = [BARLOWCOND_SEMIBOLD, (OSWALD_VARIABLE, "Medium"), *META_FONT_BOLD_CANDIDATES]
        max_w = (x1 - x0) - 2 * 40
        font, text = fit_text_to_width(draw, byline, candidates, 17, max_w, floor=12, tracking=1)
        text_w = tracked_width(draw, text, font, tracking=1)
        draw_tracked(draw, ((x0 + x1 - text_w) / 2, _SEMIOTIC_FOOTER_RULE_Y + 12), text, font, black, tracking=1)


def render_semiotic_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Cobb's Semiotic Standard on a Nostromo bulkhead (see the section comment)."""
    hour = _clock_hour12(time_str)
    image = Image.new("RGB", (800, 480), color=SPECTRA6["black"])
    draw = ImageDraw.Draw(image)
    _semiotic_paint_hazard(image)
    _semiotic_paint_header(image, draw, hour)
    _semiotic_paint_signs(image, draw, hour, quote_row)
    _semiotic_paint_placard(image, draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image



# ---------------------------------------------------------------------------
# saros — Housemarque's *Saros* (2026): the eclipse over Carcosa
# ---------------------------------------------------------------------------
# The colony of Carcosa under the eclipse that never ends: a black sun over a
# dead colony, spores drifting through a red-and-black sky, the quote in the
# one dark stretch of sky.
#
# **The corona is painted in continuous tone and dithered, not stippled**: a
# chromospheric rim decaying over a few pixels, a mid corona over half a
# radius, an outer haze over one and a half, and *streamers* (angular Gaussian
# lobes brightening the mid and outer terms). The profile is sampled every
# ``_SAROS_SKY_STEP`` px (a glow has no finer detail) and bicubic-upsampled;
# the photosphere and moon are then painted sharp at full resolution, because
# the exposed sliver is the one hard edge in the sky. The field is
# Floyd-Steinberg-dithered to K/R/Y/W plus blue (``_SAROS_SKY_PALETTE``). Blue
# is only for the horizon haze away from the sun; its channel is zero
# elsewhere so error diffusion cannot scatter blue into the fire. No green.
#
# **The time is the eclipse's phase.** At twelve the moon is centred and the
# eclipse total. At other hours the moon is offset ``_SAROS_HOUR_OFFSET`` radii
# *away* from the hour's clock-face position, so the diamond ring sits where
# the hour hand would point (the wordmark's O carries the same bead). Hour
# only: every minute of an hour renders byte-identically. The status line's
# occlusion figure comes from the same geometry.
#
# **The ground is silhouette plus rim light.** Spires, towers and a bone arch
# are one black mask; the rim is the shape minus itself shifted two pixels
# away from the sun, weighted by the sky's falloff and stippled yellow where
# strong, red where weak. Everything lit on the frame is lit by the sun. The
# sky is quote-independent and cached per hour (``_SAROS_SKY_CACHE``, keyed on
# the painter so the decoration fence measures a painter, not a cache).
#
# **The quote** is Saira (ragged-left, a transmission rather than a verse)
# pasted white over a black halo grown from its own mask, so no dithered
# corona speck lands between strokes; the matched phrase is a yellow core in a
# tangerine split-band bloom, ``ground`` pinned to black. Spore motes are
# seeded from ``_row_digest``.
#
# Composed at 800x480 and NEAREST-downsampled (the ``metro`` convention).
# ---------------------------------------------------------------------------
_SAROS_SUN = (556, 186)                   # the sun's centre
_SAROS_RADIUS = 108                       # the photosphere's radius, px
_SAROS_MOON_SCALE = 1.03                  # the moon is a shade larger: totality is total
_SAROS_HOUR_OFFSET = 0.10                 # moon offset in sun radii at every hour but twelve
_SAROS_SKY_STEP = 4                       # the corona is sampled every N px, then upsampled
_SAROS_SKY_REACH = 3.6                    # beyond this many radii the sky is black
_SAROS_HORIZON = 390
_SAROS_QUOTE_RECT = (48, 104, 376, 348)
_SAROS_SEED = 0x5A205
_SAROS_SKY_PALETTE = [SPECTRA6["black"], SPECTRA6["red"], SPECTRA6["yellow"], SPECTRA6["white"],
                      SPECTRA6["blue"]]
# Coronal streamers as (angle in degrees — screen axes, 0 = right, 90 = down —
# half-width in degrees, reach in radii, weight). Asymmetric on purpose: a
# corona at solar minimum is a few long equatorial plumes and short polar
# brushes, not a halo.
_SAROS_STREAMERS = (
    (-74, 6, 3.1, 1.00), (-31, 9, 2.5, 0.80), (16, 5, 3.4, 1.10), (58, 8, 2.2, 0.70),
    (121, 7, 2.9, 0.90), (165, 10, 2.0, 0.60), (-133, 8, 2.6, 0.85), (-108, 4, 1.8, 0.50),
)
# Distant spires on the left ridge as (x, half width, height, lean): the
# colony's alien skyline, receding toward the arch.
_SAROS_SPIRES = (
    (46, 4, 74, 3), (68, 3, 52, -2), (104, 6, 96, 2), (131, 3, 60, -3), (166, 5, 118, 1),
    (191, 3, 70, 3), (228, 7, 142, -2), (258, 4, 88, 2), (296, 3, 58, -1), (322, 5, 104, 2),
)
_SAROS_SKY_CACHE: dict = {}


def _saros_hour_vector(hour: int) -> tuple[float, float]:
    """Unit vector from the sun's centre toward the hour's place on a clock
    face, in screen coordinates (12 straight up, 3 to the right)."""
    angle = math.radians(hour * 30.0)
    return math.sin(angle), -math.cos(angle)


def _saros_moon_centre(hour: int) -> tuple[float, float]:
    """The moon sits opposite the hour, so the exposed sliver is on the hour."""
    cx, cy = _SAROS_SUN
    if hour == 12:
        return float(cx), float(cy)
    ux, uy = _saros_hour_vector(hour)
    return cx - ux * _SAROS_HOUR_OFFSET * _SAROS_RADIUS, cy - uy * _SAROS_HOUR_OFFSET * _SAROS_RADIUS


def _saros_bead(hour: int) -> tuple[float, float]:
    """Where the diamond ring sits: on the photosphere's limb, at the hour."""
    cx, cy = _SAROS_SUN
    ux, uy = _saros_hour_vector(hour)
    return cx + ux * _SAROS_RADIUS, cy + uy * _SAROS_RADIUS


def _saros_occlusion(hour: int) -> int:
    """Percentage of the photosphere the moon covers, for the status line.

    Two discs' overlap by the lens formula; 100 at twelve, where the slightly
    larger moon covers all of it.
    """
    if hour == 12:
        return 100
    r = float(_SAROS_RADIUS)
    rm = r * _SAROS_MOON_SCALE
    d = _SAROS_HOUR_OFFSET * r
    a = r * r * math.acos((d * d + r * r - rm * rm) / (2 * d * r))
    b = rm * rm * math.acos((d * d + rm * rm - r * r) / (2 * d * rm))
    c = 0.5 * math.sqrt((-d + r + rm) * (d + r - rm) * (d - r + rm) * (d + r + rm))
    return int(round(100 * (a + b - c) / (math.pi * r * r)))


def _saros_streamer_gain(theta_deg: float, d: float) -> float:
    """How much the streamers brighten the corona at polar coordinate
    ``(theta, d)``: a sum of angular Gaussian lobes, each fading past its reach."""
    gain = 0.0
    for angle, sigma, reach, weight in _SAROS_STREAMERS:
        da = ((theta_deg - angle + 180.0) % 360.0) - 180.0
        gain += weight * math.exp(-(da * da) / (2.0 * sigma * sigma)) * math.exp(-max(0.0, d - reach) / 0.35)
    return min(1.3, gain)


def _saros_corona_field(size) -> tuple[Image.Image, Image.Image]:
    """The continuous-tone sky and its lighting falloff, both at full size.

    Returns ``(sky, falloff)``: ``sky`` is RGB, black beyond the corona's
    reach; ``falloff`` is an ``"L"`` map of how strongly the sun lights a
    point — what the ground's rim light is weighted by.
    """
    width, height = size
    step = _SAROS_SKY_STEP
    cols, rows = -(-width // step), -(-height // step)
    cx, cy = _SAROS_SUN
    radius = float(_SAROS_RADIUS)
    pixels = []
    light = []
    for j in range(rows):
        y = j * step + step / 2 - cy
        for i in range(cols):
            x = i * step + step / 2 - cx
            d = math.hypot(x, y) / radius
            # The sunset that rings the horizon under a total eclipse: a red
            # band fading up from the ground, strongest under the sun.
            dusk = _saros_dusk(i * step, j * step)
            r, g, b = int(150 * dusk), int(36 * dusk), _saros_haze(i * step, j * step)
            lit = 0.0
            if d < _SAROS_SKY_REACH:
                e = max(0.0, d - 1.0)
                gain = _saros_streamer_gain(math.degrees(math.atan2(y, x)), d)
                rim = math.exp(-e / 0.06)
                mid = math.exp(-e / 0.36) * (0.35 + 0.65 * gain)
                outer = math.exp(-e / 1.1) * 0.22 * (0.3 + 0.7 * gain)
                # No blue in the fire, not even on the white-hot rim: error
                # diffusion would pay it out as blue specks in the corona.
                r += int(255 * rim + 255 * mid + 150 * outer)
                g += int(210 * rim + 112 * mid + 18 * outer)
                lit = 0.55 * rim + 0.6 * mid + 0.9 * outer
            pixels.append((min(255, r), min(255, g), min(255, b)))
            light.append(min(255, int(255 * lit)))
    sky = Image.new("RGB", (cols, rows))
    sky.putdata(pixels)
    falloff = Image.new("L", (cols, rows))
    falloff.putdata(light)
    full = (cols * step, rows * step)
    sky = sky.resize(full, Image.Resampling.BICUBIC).crop((0, 0, width, height))
    falloff = falloff.resize(full, Image.Resampling.BICUBIC).crop((0, 0, width, height))
    return sky, falloff


def _saros_dusk(x: float, y: float) -> float:
    """The horizon glow, 0..1: an exponential band up from the ground line,
    strongest beneath the sun and never more than a third as bright at the
    far edges — enough to cut every silhouette out of the sky."""
    if y > _SAROS_HORIZON + 8:
        return 0.0
    band = math.exp(-max(0.0, _SAROS_HORIZON - y) / 58.0)
    lateral = 0.3 + 0.7 * math.exp(-abs(x - _SAROS_SUN[0]) / 360.0)
    return band * lateral


def _saros_haze(x: float, y: float) -> int:
    """The cold blue haze on the horizon, left of the sun, as a blue channel
    value 0..24: a Gaussian band about the horizon fading out to the right."""
    if x > 340 or y > _SAROS_HORIZON + 6:
        return 0
    band = math.exp(-((y - _SAROS_HORIZON) / 44.0) ** 2)
    lateral = max(0.0, 1.0 - x / 340.0) ** 0.8
    return int(24 * band * lateral)


def _saros_paint_sky(image: Image.Image, hour: int) -> Image.Image:
    """Paint the dithered eclipse sky onto ``image`` and return the falloff map."""
    size = image.size
    sky, falloff = _saros_corona_field(size)
    draw = ImageDraw.Draw(sky)
    cx, cy = _SAROS_SUN
    r = _SAROS_RADIUS
    draw.ellipse((cx - r, cy - r, cx + r, cy + r), fill=(255, 248, 222))
    mx, my = _saros_moon_centre(hour)
    rm = r * _SAROS_MOON_SCALE
    draw.ellipse((mx - rm, my - rm, mx + rm, my + rm), fill=(0, 0, 0))
    image.paste(dither_image_to_palette(sky, _SAROS_SKY_PALETTE))
    sky.close()
    return falloff


def _saros_sky(hour: int) -> tuple[Image.Image, Image.Image]:
    """The quote-independent sky for ``hour``, dithered once per process.

    Keyed on the painter so a test that neuters ``_saros_paint_sky`` is not
    handed a sky painted before the patch (the ``biomech`` cache rule).
    """
    key = (hour, _saros_paint_sky, _saros_corona_field)
    cached = _SAROS_SKY_CACHE.get(hour)
    if cached is not None and cached[0] == key:
        return cached[1], cached[2]
    image = Image.new("RGB", (800, 480), SPECTRA6["black"])
    falloff = _saros_paint_sky(image, hour)
    if falloff is None:
        falloff = Image.new("L", image.size, 0)
    _SAROS_SKY_CACHE[hour] = (key, image, falloff)
    return image, falloff


def _saros_paint_bead(image: Image.Image, hour: int) -> None:
    """The diamond ring: a white bead with a yellow bloom on the exposed
    limb, and a horizontal lens spike. Nothing at totality."""
    if hour == 12:
        return
    bx, by = _saros_bead(hour)
    bead = Image.new("L", image.size, 0)
    ImageDraw.Draw(bead).ellipse((bx - 5, by - 5, bx + 5, by + 5), fill=255)
    paint_neon_mask(image, bead, SPECTRA6["white"], SPECTRA6["yellow"],
                    radius=9, gamma=1.5, cap=0.7, tile=BAYER_8x8)
    spike = Image.new("L", image.size, 0)
    ImageDraw.Draw(spike).line([(bx - 54, by), (bx + 54, by)], fill=255, width=1)
    paint_neon_mask(image, spike, None, SPECTRA6["white"], radius=3, gamma=1.8, cap=0.5,
                    ground=frozenset({SPECTRA6["black"], SPECTRA6["red"]}), tile=BAYER_8x8)
    bead.close()
    spike.close()


def _saros_ground_y(x: float) -> float:
    """The horizon line: a gentle swell, lower toward the right."""
    return _SAROS_HORIZON + 5 * math.sin(x / 97.0) + 3 * math.sin(x / 41.0 + 1.0) + x * 0.012


def _saros_silhouette(size) -> Image.Image:
    """Everything that stands black against the sky, in one ``"L"`` mask."""
    width, height = size
    mask = Image.new("L", size, 0)
    draw = ImageDraw.Draw(mask)
    # The ground.
    line = [(x, _saros_ground_y(x)) for x in range(0, width + 8, 8)]
    draw.polygon([(0, height), *line, (width, height)], fill=255)
    # The spires of the left ridge.
    for x, half, tall, lean in _SAROS_SPIRES:
        base = _saros_ground_y(x) + 2
        draw.polygon([(x - half, base), (x + lean, base - tall), (x + half, base)], fill=255)
    # A bone arch over the middle distance, thick at the feet, thin at the crown.
    for k in range(40):
        t0, t1 = k / 40, (k + 1) / 40
        pts = []
        for t in (t0, t1):
            x = 300 + (452 - 300) * t
            y = _saros_ground_y(x) + 2 - 128 * math.sin(math.pi * t) ** 0.9
            pts.append((x, y))
        w = max(5, int(14 * (1 - math.sin(math.pi * (t0 + t1) / 2)) + 5))
        draw.line(pts, fill=255, width=w)
    # Colony towers to the right: broken blocks with a mast.
    for x0, x1, top in ((664, 700, 318), (708, 722, 346), (742, 790, 304)):
        base = _saros_ground_y((x0 + x1) / 2) + 2
        draw.polygon([(x0, base), (x0, top + 6), (x0 + 8, top), ((x0 + x1) // 2, top + 9),
                      (x1 - 6, top + 2), (x1, top + 10), (x1, base)], fill=255)
    draw.line([(765, 304), (765, 236)], fill=255, width=2)
    draw.line([(758, 250), (772, 250)], fill=255, width=1)
    return mask


def _saros_paint_ground(image: Image.Image, falloff: Image.Image) -> None:
    """Lay the silhouettes over the sky, then light their sun-facing edges."""
    size = image.size
    shape = _saros_silhouette(size)
    image.paste(SPECTRA6["black"], (0, 0), shape)
    # The rim: the shape minus itself shifted away from the sun, so only the
    # edge that faces the light survives. Left of the sun the light comes
    # from the upper right, right of it from the upper left.
    from_right = ImageChops.subtract(shape, ImageChops.offset(shape, -2, 2))
    from_left = ImageChops.subtract(shape, ImageChops.offset(shape, 2, 2))
    half = Image.new("L", size, 0)
    ImageDraw.Draw(half).rectangle((0, 0, _SAROS_SUN[0], size[1]), fill=255)
    rim = Image.composite(from_right, from_left, half)
    rim = ImageChops.multiply(rim, falloff.point(lambda v: min(255, int(v * 1.7))))
    bayer = _bayer_threshold_field(size)
    strong = ImageChops.subtract(rim, bayer.point(lambda v: min(255, v + 120))).point(lambda v: 255 if v else 0)
    weak = ImageChops.subtract(rim.point(lambda v: min(255, int(v * 1.5))), bayer).point(lambda v: 255 if v else 0)
    image.paste(SPECTRA6["red"], (0, 0), weak)
    image.paste(SPECTRA6["yellow"], (0, 0), strong)
    for layer in (shape, from_right, from_left, half, rim, bayer, strong, weak):
        layer.close()


def _saros_paint_motes(image: Image.Image, quote_row: dict) -> None:
    """Spores drifting up through the sky, seeded from the quote."""
    rng = random.Random(_row_digest(quote_row) ^ _SAROS_SEED)
    mx, my = _SAROS_SUN
    keep = (_SAROS_RADIUS * _SAROS_MOON_SCALE + 6) ** 2
    motes = Image.new("L", image.size, 0)
    draw = ImageDraw.Draw(motes)
    for _ in range(72):
        x = rng.uniform(8, 792)
        y = rng.uniform(40, _SAROS_HORIZON - 4) if rng.random() < 0.6 else rng.uniform(220, _SAROS_HORIZON - 4)
        if (x - mx) ** 2 + (y - my) ** 2 < keep:
            continue
        size = 1 if rng.random() < 0.7 else 2
        draw.ellipse((x - size, y - size, x + size, y + size), fill=255)
    paint_neon_mask(image, motes, SPECTRA6["white"], SPECTRA6["yellow"], radius=2, gamma=1.4, cap=0.5,
                    ground=frozenset({SPECTRA6["black"]}))
    motes.close()


def _saros_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> int:
    """White Saira prose over a black halo; the matched phrase an ember.
    Returns the block's bottom y."""
    prose, hot, bottom = wrap_quote_into_masks(
        draw, image.size, quote_row, _SAROS_QUOTE_RECT, theme="saros",
        font_max=34, font_min=14, line_height_mult=1.34, align="left",
    )
    _halo_paste(image, ImageChops.lighter(prose, hot), None, halo=7)
    image.paste(SPECTRA6["white"], (0, 0), prose.point(lambda v: 255 if v > 110 else 0))
    paint_neon_mask(image, hot, SPECTRA6["yellow"], SPECTRA6["red"],
                    radius=4, gamma=1.5, cap=0.6, ground=frozenset({SPECTRA6["black"]}),
                    tile=BAYER_8x8, glow_minor=SPECTRA6["yellow"], glow_minor_share=0.375)
    prose.close()
    hot.close()
    return bottom


def _saros_paint_byline(image: Image.Image, quote_row: dict, top: int) -> None:
    """Author and title, flush left under the quote, ellipsised to the column."""
    x0, _, x1, _ = _SAROS_QUOTE_RECT
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or fallback_title(quote_row) or "").strip()
    text = " — ".join(p for p in (author, title) if p)
    if not text:
        return
    font = load_font([(SAIRA_ITALIC_VARIABLE, "Italic"), (EXO2_ITALIC_VARIABLE, "Italic"), *META_FONT_CANDIDATES], 15)
    mask = Image.new("L", image.size, 0)
    draw = ImageDraw.Draw(mask)
    while draw.textlength(text, font=font) > x1 - x0 and len(text) > 8:
        text = text[:-2].rstrip(" ,.;:") + "…"
    draw.text((x0, min(_SAROS_HORIZON - 16, top + 24)), text, font=font, fill=255, anchor="ls")
    _halo_paste(image, mask, SPECTRA6["white"], halo=5)
    mask.close()


def _saros_paint_chrome(image: Image.Image, draw: ImageDraw.ImageDraw, hour: int) -> None:
    """The wordmark, with the O as a small eclipse carrying the hour's bead,
    the colony line beneath it and the eclipse status at the right."""
    white, yellow, black = SPECTRA6["white"], SPECTRA6["yellow"], SPECTRA6["black"]
    x0 = _SAROS_QUOTE_RECT[0]
    # Orbitron for the wordmark — the nearest open face to Arame, the game's
    # main display face; Michroma, the Korataki stand-in, keeps the small chrome.
    wordmark = load_font([(ORBITRON_VARIABLE, "Bold"), MICHROMA_REGULAR, *META_FONT_BOLD_CANDIDATES], 22)
    tracking = 6
    y = 30
    x = draw_tracked(draw, (x0, y), "SAR", wordmark, white, tracking=tracking) + x0
    cap = draw.textbbox((0, 0), "S", font=wordmark)
    cap_h = cap[3] - cap[1]
    r = cap_h / 2 + 1
    # The O sits one tracking step after the R and one before the S, like a
    # glyph in the run; ``draw_tracked`` returns the run's width *without* a
    # trailing step, so the step is added here.
    cx, cy = x + tracking + r + 1, y + cap[1] + cap_h / 2
    draw.ellipse((cx - r, cy - r, cx + r, cy + r), fill=black, outline=white, width=2)
    if hour != 12:
        ux, uy = _saros_hour_vector(hour)
        bx, by = cx + ux * (r - 1), cy + uy * (r - 1)
        draw.ellipse((bx - 2, by - 2, bx + 2, by + 2), fill=yellow)
    x = cx + r + 1 + tracking
    draw_tracked(draw, (x, y), "S", wordmark, white, tracking=tracking)
    small = load_font([MICHROMA_REGULAR, *META_FONT_CANDIDATES], 10)
    draw_tracked(draw, (x0, y + 34), "CARCOSA COLONY", small, white, tracking=3)
    status = "TOTALITY" if hour == 12 else "DIAMOND RING"
    occlusion = f"OCCLUSION {_saros_occlusion(hour)}%"
    draw_tracked(draw, (748, 30), status, small, white, tracking=3, anchor_right=True)
    draw_tracked(draw, (748, 47), occlusion, small, white, tracking=3, anchor_right=True)
    draw.ellipse((756, 31, 766, 41), fill=yellow if hour != 12 else black, outline=yellow, width=2)
    del image


def render_saros_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """The eclipse over Carcosa (see the section comment above)."""
    hour = _clock_hour12(time_str)
    sky, falloff = _saros_sky(hour)
    image = sky.copy()
    _saros_paint_bead(image, hour)
    _saros_paint_ground(image, falloff)
    _saros_paint_motes(image, quote_row)
    draw = ImageDraw.Draw(image)
    _saros_paint_chrome(image, draw, hour)
    bottom = _saros_paint_quote(image, draw, quote_row)
    _saros_paint_byline(image, quote_row, bottom)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# atropos — Housemarque's *Returnal* (2021): night in the Overgrown Ruins
# ---------------------------------------------------------------------------
# One night in the rain-soaked ruins: teal fog over a black plain, rain, the
# Sentient statues, the wreck of the *Helios*, black tendrils glowing where
# alive, bullet-hell orbs, and a HUD over it all. The quote is a **xenoglyph
# cipher** the scout has just translated.
#
# **Cold scene, hot layer — two passes, two palettes.** The night is painted
# in continuous tone and Floyd–Steinberg-dithered to **black / blue / green /
# white only**, so error diffusion can never warm it; the teal is a B+G mix
# whose density falls with the fog, hence dithered rather than stippled.
# Everything that glows is laid on top through ``paint_neon_mask`` with
# ``ground`` pinned to the three cold inks: ember nodules, hot orbs and the
# matched phrase in a yellow core with a tangerine halo (red with yellow at
# 3/8), violet orbs in a white core with a blue + red halo at 1/2.
#
# **The scene is quote-independent and cached** (``_ATROPOS_BACKGROUND``,
# keyed on the painters, the ``biomech`` pattern). Orbs, cipher and HUD
# readings are seeded from ``_row_digest``, never ``hash()`` or the clock.
#
# **The cipher is the quote in alien script.** ``_atropos_glyph`` builds a
# 26-letter alphabet once from a fixed seed (three to five strokes on a 3x4
# lattice plus an optional dot); the slab carries the matched phrase and then
# the quote, so the same letter is always the same glyph. 1 px strokes are a
# single white ink so they survive the snap.
#
# **The time is the cycle counter, hour only** (``CYCLE 07`` top-right),
# pinned byte-identical across the minutes of an hour by ``TestAtroposFrame``.
# Custom frames never draw the debug banner, so no ``_DEBUG_LABEL_RIGHT_INSET``.
#
# **Saira** for the translation, **Michroma** for the HUD: the nearest open
# faces to Returnal's Erbaum and Kellion (see ``docs/themes.md``).
#
# Composed at 800x480 and NEAREST-downsampled (the ``metro`` convention).
# ---------------------------------------------------------------------------
_ATROPOS_SEED = 0xA7C0
_ATROPOS_HORIZON = 334
_ATROPOS_QUOTE_RECT = (166, 72, 666, 256)
_ATROPOS_BYLINE_BASELINE = 288
_ATROPOS_SLAB = (704, 60, 768, 406)         # the cipher monolith
_ATROPOS_STATUE = (104, 118)                # centre x, crown y of the near Sentient
_ATROPOS_GATE = (418, 302, 112)             # centre x, centre y, radius of the ring gate
_ATROPOS_HELIOS = (476, 212, 652, 332)      # bounding box of the wreck
_ATROPOS_HELIOS_BEACON = (598, 236)
_ATROPOS_CYCLE_RIGHT = 766
_ATROPOS_SCENE_PALETTE = [SPECTRA6["black"], SPECTRA6["blue"], SPECTRA6["green"], SPECTRA6["white"]]
_ATROPOS_COLD_GROUND = frozenset({SPECTRA6["black"], SPECTRA6["blue"], SPECTRA6["green"]})
_ATROPOS_SKY_STOPS = (
    (0, (0, 0, 0)), (140, (1, 4, 5)), (230, (4, 18, 20)), (284, (14, 56, 62)),
    (_ATROPOS_HORIZON, (42, 124, 128)),
)
_ATROPOS_GROUND_STOPS = ((_ATROPOS_HORIZON, (26, 84, 88)), (400, (9, 32, 34)), (480, (2, 8, 9)))
# Pools of lit fog, as (centre x, centre y, radius, strength): behind the near
# Sentient, so the figure reads as a silhouette in mist, and round the wreck,
# whose beacon lights the fog from inside.
_ATROPOS_FOG_LIGHTS = ((104, 236, 130, 0.62), (590, 262, 120, 0.5))
_ATROPOS_DARK = (3, 9, 10)                  # the silhouettes' own black, a hair off pure
_ATROPOS_RIM = (96, 178, 182)               # teal rim light the fog throws on an edge
_ATROPOS_BACKGROUND: dict = {}
_ATROPOS_PATHS: dict = {}
_ATROPOS_GLYPHS: dict = {}


def _atropos_font(size: int):
    """Michroma, falling back through the techno sans before the system faces."""
    return load_font([MICHROMA_REGULAR, (OXANIUM_VARIABLE, "Medium"), *META_FONT_BOLD_CANDIDATES], size=size)


def _atropos_haze(colour, amount: float):
    """``_ATROPOS_DARK`` pushed ``amount`` of the way toward ``colour`` — how far
    a silhouette has dissolved into the fog in front of it."""
    return tuple(round(d + (c - d) * amount) for d, c in zip(_ATROPOS_DARK, colour))


def _atropos_paint_sky(image: Image.Image) -> None:
    """The night: a black zenith falling to teal fog at the horizon, the fog
    banked by stretched noise, spores drifting in the air, a wet plain below."""
    width, height = image.size
    hz = _ATROPOS_HORIZON
    column = Image.new("RGB", (1, height))
    for y in range(height):
        stops = _ATROPOS_SKY_STOPS if y <= hz else _ATROPOS_GROUND_STOPS
        column.putpixel((0, y), _lerp_stops(stops, y))
    image.paste(column.resize((width, height), Image.Resampling.NEAREST))

    # Fog banks: long horizontal streaks, densest just above the horizon.
    envelope = Image.new("L", (1, height))
    for y in range(height):
        e = math.exp(-((y - hz + 14) / 58.0) ** 2) if y <= hz + 20 else 0.0
        envelope.putpixel((0, y), round(255 * e))
    envelope = envelope.resize((width, height), Image.Resampling.NEAREST)
    streaks = _smooth_noise((width, height), (8, 44), _ATROPOS_SEED)
    light = ImageChops.multiply(streaks.point(lambda v: max(0, v - 120) * 3), envelope)
    bright = ImageEnhance.Brightness(image).enhance(1.75)
    image.paste(Image.composite(bright, image, light))

    # Lit pools in the fog, where something stands in it or burns inside it.
    pools = Image.new("L", (width, height), 0)
    pd = ImageDraw.Draw(pools)
    for px, py, pr, strength in _ATROPOS_FOG_LIGHTS:
        pd.ellipse((px - pr, py - pr * 0.8, px + pr, py + pr * 0.8), fill=round(255 * strength))
    pools = pools.filter(ImageFilter.GaussianBlur(44))
    lit = Image.composite(Image.new("RGB", (width, height), (52, 136, 140)), image, pools)
    image.paste(Image.blend(image, lit, 0.85))

    # Spores: a sparse scatter of pale teal motes hanging in the air.
    motes = _white_noise(width, height, _ATROPOS_SEED + 1).point(lambda v: 255 if v > 252 else 0)
    air = Image.new("L", (width, height), 0)
    ImageDraw.Draw(air).rectangle((0, 40, width, hz + 60), fill=255)
    motes = ImageChops.multiply(motes, air.filter(ImageFilter.GaussianBlur(30)))
    image.paste((96, 170, 172), (0, 0), motes)


def _atropos_paint_rain(image: Image.Image) -> None:
    """Rain: hundreds of short slanted streaks, brighter where the fog lights them."""
    width, height = image.size
    draw = ImageDraw.Draw(image)
    rng = random.Random(_ATROPOS_SEED + 2)
    for _ in range(380):
        x = rng.uniform(-20, width + 20)
        y = rng.uniform(-30, height)
        length = rng.uniform(9, 30)
        near = rng.random()
        tone = 0.25 + 0.75 * near * (0.45 + 0.55 * min(1.0, y / _ATROPOS_HORIZON))
        colour = tuple(round(c * tone) for c in (62, 138, 142))
        draw.line([(x, y), (x - length * 0.22, y + length)], fill=colour, width=1)


def _atropos_sentient(draw: ImageDraw.ImageDraw, cx: int, crown: int, scale: float, colour, rim=None) -> None:
    """A Sentient statue: the long crested skull swept back, a thin neck, sloped
    shoulders, a robe falling to the ground, arms hanging to elongated hands."""
    def pt(x, y):
        return (round(cx + x * scale), round(crown + y * scale))

    head = [pt(-11, 46), pt(-10, 24), pt(-2, 6), pt(18, -10), pt(48, -24), pt(56, -18), pt(44, -2),
            pt(26, 16), pt(16, 32), pt(11, 46), pt(5, 56), pt(-5, 56)]
    body = [pt(-5, 52), pt(5, 52), pt(7, 70), pt(28, 76), pt(36, 130), pt(44, 216), pt(-44, 216),
            pt(-36, 130), pt(-28, 76), pt(-7, 70)]
    arms = []
    for s in (-1, 1):
        arms.append([pt(s * 24, 80), pt(s * 36, 84), pt(s * 46, 150), pt(s * 48, 186), pt(s * 40, 188),
                     pt(s * 34, 152), pt(s * 26, 100)])
        for k in range(3):                                   # three long fingers
            fx = s * (38 + k * 5)
            arms.append([pt(fx - 1.5, 184), pt(fx + 1.5, 184), pt(fx + 2 + s * 2, 206 + k * 4), pt(fx - 1 + s * 2, 206 + k * 4)])
    if rim is not None:
        for poly in (head, body, *arms):
            draw.polygon([(x + 3, y - 1) for x, y in poly], fill=rim)
    for poly in (head, body, *arms):
        draw.polygon(poly, fill=colour)
    draw.polygon([pt(-3, 44), pt(3, 44), pt(3, 54), pt(-3, 54)], fill=colour)  # neck


def _atropos_paint_ruins(image: Image.Image) -> None:
    """Atropos at the horizon: a far skyline of broken monoliths, the ring
    gate, the layered pillars, the *Helios* on its nose, the Sentients, the
    cipher slab, then the plain's wet reflection of all of it."""
    width, height = image.size
    draw = ImageDraw.Draw(image)
    hz = _ATROPOS_HORIZON
    horizon_sky = _lerp_stops(_ATROPOS_SKY_STOPS, hz - 6)
    rng = random.Random(_ATROPOS_SEED + 3)

    # Far skyline: a broken row of monoliths, most dissolved into the fog.
    far = _atropos_haze(horizon_sky, 0.58)
    x = -10
    while x < width:
        w = rng.randint(8, 34)
        h = rng.randint(6, 54) + (30 if 560 < x < 700 else 0)
        lean = rng.randint(-4, 4)
        draw.polygon([(x, hz + 2), (x + lean, hz - h), (x + w + lean, hz - h + rng.randint(-8, 8)), (x + w, hz + 2)], fill=far)
        x += w + rng.randint(4, 40)

    # The ring gate, half sunk, with the fog brighter through it.
    gx, gy, gr = _ATROPOS_GATE
    through = Image.new("L", (width, height), 0)
    ImageDraw.Draw(through).ellipse((gx - gr + 10, gy - gr + 10, gx + gr - 10, gy + gr - 10), fill=120)
    sky = Image.new("L", (width, height), 0)
    ImageDraw.Draw(sky).rectangle((0, 0, width, hz), fill=255)
    through = ImageChops.multiply(through.filter(ImageFilter.GaussianBlur(26)), sky)
    image.paste(Image.composite(ImageEnhance.Brightness(image).enhance(1.9), image, through))
    gate = _atropos_haze(horizon_sky, 0.22)
    mask = Image.new("L", (width, height), 0)
    md = ImageDraw.Draw(mask)
    md.ellipse((gx - gr, gy - gr, gx + gr, gy + gr), fill=255)
    md.ellipse((gx - gr + 12, gy - gr + 12, gx + gr - 12, gy + gr - 12), fill=0)
    md.rectangle((0, hz, width, height), fill=0)
    for k in range(8):                                      # carved notches round the ring
        a = -math.pi / 2 + k * math.pi / 7
        nx, ny = gx + math.cos(a) * (gr - 6), gy + math.sin(a) * (gr - 6)
        md.ellipse((nx - 4, ny - 4, nx + 4, ny + 4), fill=0)
    image.paste(gate, (0, 0), mask)

    # Layered pillars to the right, in front of the skyline, behind the slab.
    near = _atropos_haze(horizon_sky, 0.08)
    for px, pw, top in ((596, 22, 206), (628, 30, 176), (666, 18, 228), (690, 26, 190), (736, 34, 150)):
        draw.rectangle((px, top, px + pw, hz + 4), fill=near)
        draw.polygon([(px, top), (px + pw, top), (px + pw + 3, top - 6 - pw // 6), (px - 2, top - 3)], fill=near)
        for ly in range(top + 10, hz, 14):                   # the strata's seams
            draw.line([(px + 1, ly), (px + pw - 1, ly)], fill=_atropos_haze(horizon_sky, 0.26), width=1)
    draw.polygon([(590, 182), (730, 150), (734, 160), (594, 194)], fill=near)   # a fallen lintel

    # The Helios: nose buried, tail in the air, the hull split.
    hx0, hy0, hx1, hy1 = _ATROPOS_HELIOS
    hull = _atropos_haze(horizon_sky, 0.03)
    draw.polygon([(hx0 + 10, hy1), (hx0 + 34, hy1 - 30), (hx0 + 86, hy0 + 44), (hx1 - 48, hy0 + 2),
                  (hx1 - 20, hy0), (hx1, hy0 + 16), (hx1 - 36, hy0 + 48), (hx0 + 110, hy1 - 36),
                  (hx0 + 70, hy1)], fill=hull)
    draw.polygon([(hx1 - 44, hy0 + 20), (hx1 - 2, hy0 - 22), (hx1 + 8, hy0 - 14), (hx1 - 30, hy0 + 34)], fill=hull)  # fin
    for k in range(4):                                      # the cabin windows, lit by the fog
        wx, wy = hx0 + 96 + k * 16, hy0 + 40 - k * 6
        draw.rectangle((wx, wy, wx + 5, wy + 3), fill=(44, 110, 114))
    draw.line([(hx0 + 60, hy1 - 18), (hx0 + 84, hy0 + 62)], fill=(30, 84, 88), width=1)  # the split

    # The Sentients: one near, one a long way off.
    sx, sy = _ATROPOS_STATUE
    _atropos_sentient(draw, 262, 226, 0.5, _atropos_haze(horizon_sky, 0.3))
    _atropos_sentient(draw, sx, sy, 1.0, _ATROPOS_DARK, rim=_ATROPOS_RIM)

    # The cipher slab: a bevelled monolith, lighter where the fog catches its edge.
    x0, y0, x1, y1 = _ATROPOS_SLAB
    draw.rectangle((x0 - 4, y0 - 4, x1 + 4, y1 + 4), fill=(40, 96, 100))
    draw.rectangle((x0, y0, x1, y1), fill=(5, 14, 16))
    draw.line([(x0 - 4, y0 - 4), (x0 - 12, y0 + 4), (x0 - 12, y1 + 12), (x0 - 4, y1 + 4)], fill=(24, 60, 64), width=3)

    # Fog over every base, then the wet plain: the horizon mirrored, streaked.
    fog = Image.new("L", (1, height))
    for y in range(height):
        fog.putpixel((0, y), round(130 * math.exp(-((y - hz + 4) / 11.0) ** 2)))
    fog = ImageChops.multiply(fog.resize((width, height), Image.Resampling.NEAREST),
                              _smooth_noise((width, height), (14, 60), _ATROPOS_SEED + 4)).point(lambda v: min(255, v * 2))
    image.paste(Image.composite(Image.new("RGB", (width, height), (36, 104, 108)), image, fog))
    band = image.crop((0, hz - 70, width, hz)).transpose(Image.Transpose.FLIP_TOP_BOTTOM)
    band = ImageEnhance.Brightness(band.resize((width, 110), Image.Resampling.BILINEAR)).enhance(0.55)
    wet = _smooth_noise((width, 110), (160, 3), _ATROPOS_SEED + 5).point(lambda v: max(0, v - 70) * 2)
    fade = Image.new("L", (1, 110))
    for y in range(110):
        fade.putpixel((0, y), round(255 * (1 - y / 110) ** 1.6))
    wet = ImageChops.multiply(wet, fade.resize((width, 110), Image.Resampling.NEAREST))
    image.paste(Image.composite(band, image.crop((0, hz, width, hz + 110)), wet), (0, hz))


def _atropos_tendril_paths() -> list:
    """The tendrils as ``(points, base_width, nodules)`` — a seeded random walk
    per root, pulled toward a target, with ember nodules dropped along the
    stem. Memoised: the tendril painter and the ember painter both read it,
    and the embers must sit on the stems that were actually drawn."""
    cached = _ATROPOS_PATHS.get("paths")
    if cached is not None:
        return cached
    rng = random.Random(_ATROPOS_SEED + 6)
    roots = (
        ((-12, 468), (70, 160), 13, 46), ((36, 492), (150, 350), 9, 24), ((210, 492), (560, 402), 11, 44),
        ((612, 494), (560, 318), 8, 30), ((812, 466), (736, 150), 13, 44), ((760, 494), (690, 372), 8, 22),
        ((-8, 300), (120, 400), 6, 26),
    )
    paths = []
    for (x, y), (tx, ty), base, steps in roots:
        heading = math.atan2(ty - y, tx - x)
        points = [(x, y)]
        nodules = []
        for i in range(steps):
            want = math.atan2(ty - y, tx - x)
            heading += (want - heading) * 0.14 + rng.gauss(0, 0.34)
            x += math.cos(heading) * 9
            y += math.sin(heading) * 9
            points.append((x, y))
            # Nodules only where they can be seen: on the canvas, and clear
            # of the HUD readouts along the foot that paint over the growth.
            if i > steps * 0.2 and rng.random() < 0.1 and 8 <= x <= 792 and 8 <= y <= 428:
                nodules.append((x, y, rng.uniform(2.6, 4.6)))
        paths.append((points, base, nodules))
    _ATROPOS_PATHS["paths"] = paths
    return paths


def _atropos_paint_tendrils(image: Image.Image) -> None:
    """The black growth: tapering stems with a teal rim, side shoots, and a
    swelling where each nodule will glow."""
    draw = ImageDraw.Draw(image)
    rng = random.Random(_ATROPOS_SEED + 7)
    for points, base, nodules in _atropos_tendril_paths():
        n = len(points) - 1
        for pass_colour, extra in ((_ATROPOS_RIM, 2), (_ATROPOS_DARK, 0)):
            for i, ((x0, y0), (x1, y1)) in enumerate(zip(points, points[1:])):
                w = max(1, round(base * (1 - i / n) ** 0.8 + 1)) + extra
                draw.line([(x0, y0), (x1, y1)], fill=pass_colour, width=w)
                if extra == 0 and i % 6 == 3 and i < n - 4:              # a side shoot
                    a = math.atan2(y1 - y0, x1 - x0) + rng.choice((-1, 1)) * rng.uniform(0.7, 1.3)
                    length = rng.uniform(10, 26) * (1 - i / n)
                    draw.line([(x1, y1), (x1 + math.cos(a) * length, y1 + math.sin(a) * length)],
                              fill=_ATROPOS_DARK, width=max(1, w // 2))
        for x, y, r in nodules:
            draw.ellipse((x - r - 2, y - r - 2, x + r + 2, y + r + 2), fill=_ATROPOS_DARK)


def _atropos_background() -> Image.Image:
    """The quote-independent night, painted and dithered once per process."""
    key = (_atropos_paint_sky, _atropos_paint_rain, _atropos_paint_ruins, _atropos_paint_tendrils)
    cached = _ATROPOS_BACKGROUND.get("frame")
    if cached is not None and cached[0] == key:
        return cached[1]
    size = (800, 480)
    scene = Image.new("RGB", size, SPECTRA6["black"])
    _atropos_paint_sky(scene)
    _atropos_paint_rain(scene)
    _atropos_paint_ruins(scene)
    _atropos_paint_tendrils(scene)
    image = dither_image_to_palette(scene, _ATROPOS_SCENE_PALETTE)
    _ATROPOS_BACKGROUND["frame"] = (key, image)
    return image


def _atropos_glow_hot(image: Image.Image, mask: Image.Image, core, *, radius: int, gamma: float, cap: float,
                      ground=_ATROPOS_COLD_GROUND, yellow_share: float = 0.375) -> None:
    """A tangerine bloom: red with yellow at 3/8, the warning orange of the HUD.

    Scene lights pass ``yellow_share=0.5``: panel red is nearly black, so a
    5/8-red halo reads as shadow rather than light. The phrase keeps 3/8,
    since on pure black the hue is what matters.
    """
    paint_neon_mask(image, mask, core, SPECTRA6["red"], radius=radius, gamma=gamma, cap=cap,
                    ground=ground, tile=BAYER_8x8, glow_minor=SPECTRA6["yellow"], glow_minor_share=yellow_share)


def _atropos_paint_embers(image: Image.Image) -> None:
    """Where the growth is alive: each nodule a yellow core in a tangerine
    bloom; the *Helios* beacon the same, still blinking in the wreck."""
    mask = Image.new("L", image.size, 0)
    md = ImageDraw.Draw(mask)
    for _, _, nodules in _atropos_tendril_paths():
        for x, y, r in nodules:
            md.ellipse((x - r, y - r, x + r, y + r), fill=255)
    bx, by = _ATROPOS_HELIOS_BEACON
    md.ellipse((bx - 2, by - 2, bx + 2, by + 2), fill=255)
    # The Sentient's xenotech seams: thin lines of light along the crest and
    # down the chest, the one thing on the statue that is still awake.
    sx, sy = _ATROPOS_STATUE
    md.line([(sx + 4, sy + 8), (sx + 36, sy - 10)], fill=255, width=1)
    md.line([(sx, sy + 76), (sx, sy + 150)], fill=255, width=1)
    _atropos_glow_hot(image, mask, SPECTRA6["yellow"], radius=6, gamma=1.2, cap=0.8, yellow_share=0.5)
    mask.close()


def _atropos_paint_orbs(image: Image.Image, quote_row: dict) -> None:
    """The volley: glowing projectiles with fading trails, a different pattern
    per quote. Hot orbs are yellow in tangerine, violet ones white in R+B."""
    rng = random.Random(_row_digest(quote_row) ^ _ATROPOS_SEED)
    width, height = image.size
    # The volley stays clear of the translation frame (an orb beside a glyph
    # reads as a dot stuck to the phrase) and of the cipher slab.
    reach = 26                                                   # how far a bloom spills past its mask
    keepouts = (_atropos_quote_keepout(), _ATROPOS_SLAB)         # the text, and the glyphs it translates

    def clear(px, py):
        return not any(kx0 - reach < px < kx1 + reach and ky0 - reach < py < ky1 + reach
                       for kx0, ky0, kx1, ky1 in keepouts)

    for _ in range(6 + rng.randrange(4)):
        r = rng.uniform(4.5, 8.0)
        for _attempt in range(60):
            x, y = rng.uniform(40, width - 40), rng.uniform(52, _ATROPOS_HORIZON + 16)
            a = rng.uniform(0, 2 * math.pi)
            dots = [(x - math.cos(a) * k * r * 1.6, y - math.sin(a) * k * r * 1.6) for k in range(1, 8)]
            if clear(x, y) and all(clear(tx, ty) for tx, ty in dots):
                break
        else:                                                    # pragma: no cover - 60 draws never all collide
            continue
        hot = rng.random() < 0.7
        core = Image.new("L", image.size, 0)
        trail = Image.new("L", image.size, 0)
        ImageDraw.Draw(core).ellipse((x - r, y - r, x + r, y + r), fill=255)
        td = ImageDraw.Draw(trail)
        for k, (tx, ty) in enumerate(dots, start=1):
            tr = r * (1 - k / 8) * 0.9
            td.ellipse((tx - tr, ty - tr, tx + tr, ty + tr), fill=round(255 * (1 - k / 9)))
        if hot:
            _atropos_glow_hot(image, trail, None, radius=5, gamma=1.8, cap=0.55, yellow_share=0.5)
            _atropos_glow_hot(image, core, SPECTRA6["yellow"], radius=8, gamma=1.1, cap=0.85, yellow_share=0.5)
            ir = r * 0.42                                        # white-hot centre
            ImageDraw.Draw(image).ellipse((x - ir, y - ir, x + ir, y + ir), fill=SPECTRA6["white"])
        else:
            for m, c, rad, g, cp in ((trail, None, 5, 1.8, 0.5), (core, SPECTRA6["white"], 8, 1.1, 0.8)):
                paint_neon_mask(image, m, c, SPECTRA6["blue"], radius=rad, gamma=g, cap=cp,
                                ground=_ATROPOS_COLD_GROUND, tile=BAYER_8x8,
                                glow_minor=SPECTRA6["red"], glow_minor_share=0.5)
        core.close()
        trail.close()


def _atropos_quote_keepout() -> tuple[int, int, int, int]:
    """The translation frame, brackets and byline included, that no orb may
    sit inside."""
    x0, y0, x1, _ = _ATROPOS_QUOTE_RECT
    return (x0 - 18, y0 - 22, x1 + 18, _ATROPOS_BYLINE_BASELINE + 12)


def _atropos_glyph(letter: str) -> tuple:
    """The xenoglyph for ``letter``: strokes on a 3x4 lattice and an optional
    dot, built once per letter from a fixed seed so the alphabet is stable."""
    glyph = _ATROPOS_GLYPHS.get(letter)
    if glyph is None:
        rng = random.Random(_ATROPOS_SEED * 31 + ord(letter))
        lattice = [(c, r) for r in range(4) for c in range(3)]
        strokes = []
        start = rng.choice(lattice)
        for _ in range(rng.randint(3, 5)):
            end = rng.choice([p for p in lattice if p != start and (p[0] == start[0] or p[1] == start[1]
                                                                    or abs(p[0] - start[0]) == abs(p[1] - start[1]))])
            strokes.append((start, end))
            start = end if rng.random() < 0.7 else rng.choice(lattice)
        dot = rng.choice(lattice) if rng.random() < 0.45 else None
        glyph = _ATROPOS_GLYPHS[letter] = (tuple(strokes), dot)
    return glyph


def _atropos_cipher_text(quote_row: dict) -> str:
    """The letters the slab carries: the matched phrase, then the quote."""
    text = f"{quote_row.get('matched_text') or ''} {quote_row.get('display_quote') or ''}".lower()
    return "".join(ch if ch.isalpha() and ch.isascii() else " " for ch in text)


def _atropos_paint_cipher(image: Image.Image, quote_row: dict) -> None:
    """The xenoglyph wall: the quote in alien script down the slab, white
    strokes in a faint blue bloom, a space as an empty cell."""
    x0, y0, x1, y1 = _ATROPOS_SLAB
    cell_w, cell_h, pitch = 10, 14, 22
    columns = (x0 + 12, x0 + 38)
    rows = (y1 - y0 - 16) // pitch
    mask = Image.new("L", image.size, 0)
    md = ImageDraw.Draw(mask)
    letters = _atropos_cipher_text(quote_row)
    text = " ".join(letters.split())
    index = 0
    for row in range(rows):
        for cx in columns:
            if index >= len(text):
                break
            ch = text[index]
            index += 1
            if ch == " ":
                continue
            strokes, dot = _atropos_glyph(ch)
            top = y0 + 10 + row * pitch
            for (c0, r0), (c1, r1) in strokes:
                md.line([(cx + c0 * cell_w / 2, top + r0 * cell_h / 3), (cx + c1 * cell_w / 2, top + r1 * cell_h / 3)],
                        fill=255, width=1)
            if dot is not None:
                dx, dy = cx + dot[0] * cell_w / 2, top + dot[1] * cell_h / 3
                md.ellipse((dx - 1, dy - 1, dx + 1, dy + 1), fill=255)
    paint_neon_mask(image, mask, SPECTRA6["white"], SPECTRA6["blue"], radius=2, gamma=1.6, cap=0.4,
                    ground=_ATROPOS_COLD_GROUND, tile=BAYER_8x8)
    mask.close()


def _atropos_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The translation: white Saira over a black halo, the matched phrase
    a yellow core in the HUD's tangerine."""
    prose, hot, _ = wrap_quote_into_masks(
        draw, image.size, quote_row, _ATROPOS_QUOTE_RECT, theme="atropos",
        font_max=30, font_min=12, line_height_mult=1.42,
    )
    _halo_paste(image, ImageChops.lighter(prose, hot), None)
    image.paste(SPECTRA6["white"], (0, 0), prose.point(lambda v: 255 if v > 110 else 0))
    _atropos_glow_hot(image, hot, SPECTRA6["yellow"], radius=3, gamma=1.8, cap=0.5,
                      ground=frozenset({SPECTRA6["black"]}))
    prose.close()
    hot.close()


def _atropos_paint_byline(image: Image.Image, quote_row: dict) -> None:
    """Author and title as the cipher's source line, small capitals in white."""
    x0, _, x1, _ = _ATROPOS_QUOTE_RECT
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "")
    byline = "  ·  ".join(part.upper() for part in (author, title) if part)
    if not byline:
        return
    mask = Image.new("L", image.size, 0)
    md = ImageDraw.Draw(mask)
    candidates = [(SAIRA_VARIABLE, "Medium"), MICHROMA_REGULAR, *META_FONT_BOLD_CANDIDATES]
    font, text = fit_text_to_width(md, byline, candidates, 13, x1 - x0, floor=10, tracking=1)
    w = tracked_width(md, text, font, tracking=1)
    draw_tracked(md, ((x0 + x1 - w) / 2, _ATROPOS_BYLINE_BASELINE - 12), text, font, 255, tracking=1)
    _halo_paste(image, mask, SPECTRA6["white"], halo=3)
    mask.close()


def _atropos_brackets(draw: ImageDraw.ImageDraw, box, length: int, fill) -> None:
    x0, y0, x1, y1 = box
    for cx, sx in ((x0, 1), (x1, -1)):
        for cy, sy in ((y0, 1), (y1, -1)):
            draw.line([(cx, cy + sy * length), (cx, cy), (cx + sx * length, cy)], fill=fill, width=1)


def _atropos_paint_hud(image: Image.Image, draw: ImageDraw.ImageDraw, hour: int, quote_row: dict) -> None:
    """The scout's HUD: the biome title, the cycle counter, the translation
    frame and its label, the integrity bar and adrenaline pips, and the
    uplink that never answers."""
    white, black = SPECTRA6["white"], SPECTRA6["black"]
    digest = _row_digest(quote_row)
    width = image.size[0]

    # Biome title, top-left.
    draw_tracked(draw, (34, 16), "ATROPOS", _atropos_font(14), white, tracking=4)
    draw_tracked(draw, (34, 36), "OVERGROWN RUINS", _atropos_font(10), white, tracking=3)

    # Cycle counter, top-right, with a ring icon: the hour, nothing else.
    font = _atropos_font(15)
    label = f"CYCLE {hour:02d}"
    draw_tracked(draw, (_ATROPOS_CYCLE_RIGHT, 15), label, font, white, tracking=3, anchor_right=True)
    cx = _ATROPOS_CYCLE_RIGHT - tracked_width(draw, label, font, tracking=3) - 18
    draw.ellipse((cx - 8, 15, cx + 8, 31), outline=white, width=1)
    draw.ellipse((cx - 3, 20, cx + 3, 26), fill=white)

    # The translation frame: corner brackets round the quote, a label above.
    x0, y0, x1, y1 = _ATROPOS_QUOTE_RECT
    _atropos_brackets(draw, _atropos_quote_keepout(), 16, white)
    draw_tracked(draw, (x0 - 6, y0 - 19), "XENOGLYPH CIPHER", _atropos_font(10), white, tracking=3)
    draw_tracked(draw, (x1 + 6, y0 - 19), "TRANSLATED", _atropos_font(10), white, tracking=3, anchor_right=True)

    # Integrity and adrenaline, bottom-left: this run's readings.
    bx0, by, bx1 = 34, 452, 262
    draw.rectangle((bx0 - 3, by - 18, bx1 + 3, by + 11), fill=black)
    draw_tracked(draw, (bx0, by - 16), "INTEGRITY", _atropos_font(10), white, tracking=2)
    draw.rectangle((bx0, by, bx1, by + 7), outline=white, width=1)
    fill_to = bx0 + round((bx1 - bx0) * (0.34 + (digest % 61) / 100))
    draw.rectangle((bx0 + 2, by + 2, fill_to, by + 5), fill=white)
    for tx in range(bx0 + 38, bx1, 38):
        draw.line([(tx, by), (tx, by + 7)], fill=black, width=1)
    lit = 1 + digest // 61 % 5
    draw.rectangle((bx1 + 14, by - 18, bx1 + 136, by + 11), fill=black)
    draw_tracked(draw, (bx1 + 18, by - 16), "ADRENALINE", _atropos_font(10), white, tracking=2)
    for k in range(5):
        px, py = bx1 + 24 + k * 16, by + 4
        pts = [(px, py - 5), (px + 5, py), (px, py + 5), (px - 5, py)]
        if k < lit:
            draw.polygon(pts, fill=white)
        else:
            draw.polygon(pts, outline=white)

    # The uplink, bottom-right.
    draw.rectangle((width - 190, by - 18, width - 30, by + 11), fill=black)
    draw_tracked(draw, (width - 34, by - 16), "HELIOS UPLINK", _atropos_font(10), white, tracking=2, anchor_right=True)
    draw_tracked(draw, (width - 34, by - 2), "NO SIGNAL", _atropos_font(10), white, tracking=3, anchor_right=True)


def render_atropos_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Night in the Overgrown Ruins of Atropos (see the section comment above)."""
    hour = _clock_hour12(time_str)
    image = _atropos_background().copy()
    draw = ImageDraw.Draw(image)
    _atropos_paint_embers(image)
    _atropos_paint_orbs(image, quote_row)
    _atropos_paint_cipher(image, quote_row)
    _atropos_paint_quote(image, draw, quote_row)
    _atropos_paint_byline(image, quote_row)
    _atropos_paint_hud(image, draw, hour, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# expedition — Sandfall Interactive's *Clair Obscur: Expedition 33* (2025):
# the Monolith from the Lumière promenade
# ---------------------------------------------------------------------------
# The view from the Lumière promenade: stone balustrade and gas lamp in the
# foreground, the dusk sea, and on the far islet the Monolith with the
# Paintress beside it, brush raised. The number she has just painted is the
# **hour**. The quote is a page from an expedition journal.
#
# **Clair-obscur, literally**: black zenith and silhouettes against one warm
# light, the horizon glow behind the Monolith. The scene (dusk gradient,
# pooled glow, a vignette keeping the journal's corner dark, the sea with
# shimmer and broken reflection, silhouettes, a brush-stroke facture) is
# painted in continuous tone and Floyd–Steinberg-dithered.
#
# **Dithered against the calibrated inks, not the nominal ones.** Tones are
# specified in the panel's measured colour space and the quantiser is given
# the same measured inks, so diffusion weighs red as the near-black it is on
# the panel; indices are then re-labelled with the nominal inks
# (``_dither_calibrated``). Nominal-RGB design goes to mud on the panel. The
# sky is quantised without green (diffusion uses any ink it is given); the sea
# gets green back for the B+G teal of lit water.
#
# **The number is paint.** ``_expedition_numeral_mask`` sets the hour in Bebas
# Neue and roughs it into a brushed stroke (bristle gaps, swelling edges,
# drips, a flick). Painted as a yellow core with white at 1/4 in a red + yellow
# halo at 1/2 (a 5/8-red halo reads as shadow). The water carries its
# reflection as a density stipple (``_expedition_stipple_field``). The
# Paintress's brush tip reaches into the halo.
#
# **The petals are the Gommage**: a gust of rose petals along a cubic path from
# the promenade toward the number, each a teardrop in a red + white stipple
# (pink is the only way a petal reads against the night when panel red is so
# dark), rimmed white on the lit side. Sizes fall along the path. Seeded from
# ``_row_digest``; the gust keeps out of the journal, byline, wordmark, credo
# and number.
#
# **The chroma**: ``paint_flow_strokes`` sweeps the sky round the number
# through a swirl-plus-wind field, blue/white in the cold sky, red/yellow near
# the glow.
#
# **The game's own faces.** The journal is **IM Fell Double Pica**, roman body
# and (no bold exists) italic matched phrase, painted in the number's recipe.
# The number and every label are **Bebas Neue**; solid-yellow Bebas at 15 px
# survives the panel where a stippled serif would shred. The wordmark is
# spaced **Cinzel Decorative** with a gold hairline and diamond.
#
# **Time surfaces.** The number is hour-only, pinned byte-identical across the
# minutes of an hour by ``TestExpeditionFrame``. The scene is quote- and
# hour-independent and cached once per process (``_EXPEDITION_BACKGROUND``,
# keyed on the painters). Composed at 800x480 and NEAREST-downsampled (the
# ``metro`` convention).
# ---------------------------------------------------------------------------
_EXPEDITION_SEED = 0xE33
_EXPEDITION_HORIZON = 306
_EXPEDITION_RAIL_TOP = 430
_EXPEDITION_QUOTE_RECT = (126, 76, 548, 216)
_EXPEDITION_BYLINE_TOP = 226
_EXPEDITION_WORDMARK_BOX = (44, 12, 340, 70)
_EXPEDITION_CREDO_BOX = (470, 396, 770, 418)
_EXPEDITION_MONOLITH = ((596, 26), (720, 26), (724, 322), (592, 322))   # the slab, top to the islet
_EXPEDITION_NUMERAL_BOX = (606, 78, 710, 214)          # where the Paintress paints
_EXPEDITION_NUMERAL_CENTRE = (658, 146)
_EXPEDITION_PAINTRESS_BOX = (460, 156, 586, 322)
_EXPEDITION_BRUSH = ((506, 236), (618, 146))           # handle end, tip — into the number's halo
_EXPEDITION_LAMP_X = 66
_EXPEDITION_LAMP_GLASS = (56, 206, 76, 244)
_EXPEDITION_LAMP_BOX = (44, 184, 90, 262)
_EXPEDITION_SKY_INKS = ("black", "blue", "red", "yellow", "white")
_EXPEDITION_SEA_INKS = ("black", "blue", "green", "red", "yellow", "white")
# Dusk, top to horizon, in the calibrated space: blue-black zenith, deep
# blue, violet, rose, amber.
_EXPEDITION_SKY_STOPS = (
    (0, (31, 34, 40)), (104, (33, 50, 98)), (196, (60, 54, 98)),
    (258, (108, 72, 74)), (292, (158, 124, 72)), (_EXPEDITION_HORIZON, (178, 150, 92)),
)
_EXPEDITION_SEA_STOPS = (
    (_EXPEDITION_HORIZON, (62, 86, 120)), (338, (44, 64, 108)),
    (400, (36, 48, 82)), (480, (31, 36, 50)),
)
_EXPEDITION_SILHOUETTE = (24, 22, 28)               # a hair off the panel's black
_EXPEDITION_GLOW = (196, 162, 92)                   # the horizon pooled behind the Monolith
_EXPEDITION_BACKGROUND: dict = {}
_EXPEDITION_NUMERALS: dict = {}


def _expedition_label_font(size: int):
    """Bebas Neue — the game's numeral and label face — falling back through
    Antonio, the bundle's other condensed caps, before the system faces."""
    return load_font([BEBASNEUE_REGULAR, (ANTONIO_VARIABLE, "Bold"), *META_FONT_BOLD_CANDIDATES], size=size)


def _expedition_wordmark_font(size: int):
    """Cinzel Decorative Bold — the poster's lettering — for ``EXPEDITION 33``."""
    return load_font([CINZELDECORATIVE_BOLD, CINZELDECORATIVE_REGULAR, *META_FONT_BOLD_CANDIDATES], size=size)


def _expedition_paint_sky(scene: Image.Image) -> None:
    """The dusk: the gradient, the glow pooled behind the Monolith, the
    vignette over the journal's corner, and the brush facture."""
    width, height = scene.size
    hz = _EXPEDITION_HORIZON
    column = Image.new("RGB", (1, height))
    for y in range(height):
        column.putpixel((0, y), _lerp_stops(_EXPEDITION_SKY_STOPS, min(y, hz)))
    scene.paste(column.resize((width, height), Image.Resampling.NEAREST))

    # The light: an elliptical pool behind the Monolith, brightest at the
    # horizon, which is what the slab and the Paintress are silhouetted on.
    glow = Image.new("L", (width, height), 0)
    gp = glow.load()
    gx, gy = _EXPEDITION_NUMERAL_CENTRE[0], hz
    for y in range(hz + 1):
        dy = (y - gy) / 150.0
        for x in range(width):
            dx = (x - gx) / 300.0
            gp[x, y] = round(255 * min(1.0, 0.92 * math.exp(-(dx * dx + dy * dy))))
    lit = Image.new("RGB", (width, height), _EXPEDITION_GLOW)
    scene.paste(Image.composite(lit, scene, glow))

    # The vignette: the corner the journal page sits in stays black, so the
    # halo under the type has nothing to fight.
    shade = Image.new("L", (width, height), 0)
    sp = shade.load()
    for y in range(hz + 1):
        dy = (y - 128) / 160.0
        for x in range(width):
            dx = (x - 290) / 310.0
            sp[x, y] = round(255 * 0.7 * math.exp(-(dx * dx + dy * dy)))
    dark = Image.new("RGB", (width, height), (31, 34, 38))
    scene.paste(Image.composite(dark, scene, shade))

    # Facture: long horizontal strokes and a finer streak, multiplied in.
    broad = _smooth_noise((width, height), (10, 72), _EXPEDITION_SEED).point(lambda v: 196 + v * 0.46)
    fine = _smooth_noise((width, height), (26, 160), _EXPEDITION_SEED + 1).point(lambda v: 222 + v * 0.26)
    brushed = ImageChops.multiply(scene, ImageChops.multiply(broad, fine).convert("RGB"))
    brushed = ImageEnhance.Brightness(brushed).enhance(1.18)
    sky = Image.new("L", (width, height), 0)
    ImageDraw.Draw(sky).rectangle((0, 0, width, hz), fill=255)
    scene.paste(Image.composite(brushed, scene, sky))


def _expedition_paint_sea(scene: Image.Image) -> None:
    """The water: a depth gradient, shimmer streaks, and the glow's reflection
    under the Monolith, broken by the same streaks."""
    width, height = scene.size
    hz = _EXPEDITION_HORIZON
    column = Image.new("RGB", (1, height))
    for y in range(height):
        column.putpixel((0, y), _lerp_stops(_EXPEDITION_SEA_STOPS, max(y, hz)))
    water = column.resize((width, height), Image.Resampling.NEAREST)

    streaks = _smooth_noise((width, height), (14, 110), _EXPEDITION_SEED + 2)
    water = ImageChops.multiply(water, streaks.point(lambda v: 186 + v * 0.38).convert("RGB"))
    water = ImageEnhance.Brightness(water).enhance(1.12)

    reflect = Image.new("L", (width, height), 0)
    rp = reflect.load()
    sp = streaks.load()
    gx = _EXPEDITION_NUMERAL_CENTRE[0]
    for y in range(hz, height):
        fall = math.exp(-(y - hz) / 62.0)
        for x in range(width):
            dx = (x - gx) / 96.0
            rp[x, y] = round(255 * 0.8 * fall * math.exp(-dx * dx) * (0.35 + 0.65 * sp[x, y] / 255.0))
    lit = Image.new("RGB", (width, height), (176, 138, 80))
    water = Image.composite(lit, water, reflect)

    sea = Image.new("L", (width, height), 0)
    ImageDraw.Draw(sea).rectangle((0, hz, width, height), fill=255)
    scene.paste(Image.composite(water, scene, sea))


def _expedition_paint_continent(scene: Image.Image) -> None:
    """The Continent's coast, far off on the left horizon, hazed into the sky."""
    hz = _EXPEDITION_HORIZON
    draw = ImageDraw.Draw(scene)
    coast = [(0, hz + 1), (0, hz - 7), (40, hz - 9), (96, hz - 13), (150, hz - 10), (204, hz - 15),
             (250, hz - 11), (300, hz - 12), (344, hz - 8), (380, hz - 5), (402, hz + 1)]
    draw.polygon(coast, fill=(124, 104, 86))


def _expedition_paint_monolith(scene: Image.Image) -> None:
    """The slab on its islet: a stone face with a rim of the glow down each
    edge, and the rocks it rises from."""
    draw = ImageDraw.Draw(scene)
    (x0, y0), (x1, _), (x2, y2), (x3, _) = _EXPEDITION_MONOLITH
    face = Image.new("L", scene.size, 0)
    ImageDraw.Draw(face).polygon(list(_EXPEDITION_MONOLITH), fill=255)
    stone = Image.new("RGB", scene.size, (27, 26, 33))
    grain = _smooth_noise(scene.size, (20, 6), _EXPEDITION_SEED + 3).point(lambda v: 214 + v * 0.16)
    stone = ImageChops.multiply(stone, grain.convert("RGB"))
    scene.paste(Image.composite(stone, scene, face))
    # Rim light: the glow grazes both edges, strongest at the base.
    for y in range(y0, y2):
        t = (y - y0) / max(1, y2 - y0)
        lx = round(x3 + (x0 - x3) * (1 - t))
        rx = round(x2 + (x1 - x2) * (1 - t))
        amount = 0.15 + 0.85 * t * t
        rim = tuple(round(27 + (c - 27) * amount) for c in (168, 126, 70))
        draw.line([(lx, y), (lx + 1, y)], fill=rim)
        draw.line([(rx - 1, y), (rx, y)], fill=tuple(round(c * 0.7) for c in rim))
    # The islet: low jagged rock either side of the base, breaking the horizon.
    hz = _EXPEDITION_HORIZON
    rocks = [
        [(556, hz + 12), (570, hz - 2), (590, hz - 8), (612, hz - 4), (626, hz + 2), (640, hz + 14)],
        [(690, hz + 14), (704, hz - 3), (726, hz - 9), (748, hz - 5), (768, hz + 1), (784, hz + 14)],
        [(600, hz + 14), (640, hz + 2), (680, hz - 1), (730, hz + 4), (760, hz + 16)],
    ]
    for rock in rocks:
        draw.polygon(rock, fill=_EXPEDITION_SILHOUETTE)
    draw.rectangle((556, hz + 8, 784, hz + 18), fill=_EXPEDITION_SILHOUETTE)


def _expedition_paint_paintress(scene: Image.Image) -> None:
    """The Paintress, seated on the islet beside the Monolith, brush raised to
    the number — a silhouette against the one light in the picture."""
    draw = ImageDraw.Draw(scene)
    ink = _EXPEDITION_SILHOUETTE
    # Hair, first: a long mass down her back and over the rock behind her.
    draw.polygon([(502, 170), (520, 162), (536, 168), (540, 186), (534, 206), (522, 226), (508, 250),
                  (498, 276), (494, 302), (484, 318), (468, 318), (470, 294), (478, 262), (488, 228),
                  (494, 196)], fill=ink)
    # The seated body: hips and folded legs, the torso leaning to the slab, a raised knee.
    draw.polygon([(474, 318), (480, 292), (494, 270), (518, 262), (548, 268), (564, 286), (570, 304),
                  (572, 318)], fill=ink)
    draw.polygon([(496, 272), (500, 236), (510, 206), (530, 198), (542, 212), (544, 244), (540, 270)],
                 fill=ink)
    draw.polygon([(522, 268), (534, 246), (550, 240), (562, 256), (570, 290), (556, 300), (540, 282)],
                 fill=ink)                                                       # the knee
    draw.polygon([(514, 206), (520, 194), (530, 192), (534, 204)], fill=ink)     # neck
    draw.ellipse((532, 164, 562, 200), fill=ink)                                 # head
    # The arm, reaching for the Monolith, and the brush it holds.
    draw.line([(534, 220), (560, 196), (578, 178)], fill=ink, width=11)
    draw.ellipse((598, 170, 612, 184), fill=ink)                                 # hand
    (hx, hy), (tx, ty) = _EXPEDITION_BRUSH
    draw.line([(hx, hy), (tx, ty)], fill=ink, width=4)
    # The brush head: a tapered tuft at the tip, flared back along the handle.
    ang = math.atan2(ty - hy, tx - hx)
    nx, ny = -math.sin(ang), math.cos(ang)
    bx, by = tx - math.cos(ang) * 14, ty - math.sin(ang) * 14
    draw.polygon([(tx, ty), (bx + nx * 5, by + ny * 5), (bx - nx * 5, by - ny * 5)], fill=ink)


def _expedition_paint_promenade(scene: Image.Image) -> None:
    """Lumière's edge: the balustrade across the foot of the page, lit from
    the lamp, and the lamp itself — post, bracket, lantern — as silhouette.
    The lantern's glass is left pale for the bloom to take."""
    width, height = scene.size
    draw = ImageDraw.Draw(scene)
    ink = _EXPEDITION_SILHOUETTE
    top = _EXPEDITION_RAIL_TOP
    lamp_x = _EXPEDITION_LAMP_X

    def lit(x: int, base, amount: float):
        glow = math.exp(-((x - lamp_x) / 150.0) ** 2) * amount
        return tuple(round(b + (g - b) * glow) for b, g in zip(base, (132, 104, 58)))

    # Rail and plinth, lit toward the lamp.
    for x in range(width):
        draw.line([(x, top), (x, top + 9)], fill=lit(x, (36, 34, 40), 0.75))
        draw.line([(x, top + 10), (x, top + 11)], fill=lit(x, (20, 18, 24), 0.3))
        draw.line([(x, top + 42), (x, height)], fill=lit(x, (30, 28, 34), 0.5))
    # Balusters: a vase profile each, 36 px pitch, the sea showing between.
    for cx in range(26, width + 18, 36):
        tone = lit(cx, ink, 0.45)
        draw.rectangle((cx - 7, top + 12, cx + 7, top + 15), fill=tone)
        draw.polygon([(cx - 4, top + 16), (cx + 4, top + 16), (cx + 7, top + 24), (cx + 5, top + 32),
                      (cx + 6, top + 41), (cx - 6, top + 41), (cx - 5, top + 32), (cx - 7, top + 24)],
                     fill=tone)
    # The lamp post, with its base, bracket curls and the lantern cage.
    draw.rectangle((lamp_x - 4, 262, lamp_x + 3, height), fill=ink)
    draw.rectangle((lamp_x - 9, 418, lamp_x + 8, 430), fill=ink)
    draw.rectangle((lamp_x - 7, 400, lamp_x + 6, 418), fill=ink)
    draw.arc((lamp_x - 22, 256, lamp_x, 284), 180, 360, fill=ink, width=2)
    draw.arc((lamp_x - 1, 256, lamp_x + 21, 284), 180, 360, fill=ink, width=2)
    gx0, gy0, gx1, gy1 = _EXPEDITION_LAMP_GLASS
    draw.polygon([(gx0 - 4, gy1 + 2), (gx1 + 4, gy1 + 2), (gx1 + 1, gy1 + 16), (gx0 - 1, gy1 + 16)], fill=ink)
    draw.rectangle((gx0, gy0, gx1, gy1), fill=(168, 158, 100))                  # the glass
    draw.polygon([(gx0 - 6, gy0), (gx1 + 6, gy0), (lamp_x + 1, gy0 - 14), (lamp_x - 1, gy0 - 14)], fill=ink)
    draw.polygon([(lamp_x - 3, gy0 - 12), (lamp_x + 3, gy0 - 12), (lamp_x, gy0 - 22)], fill=ink)


def _expedition_paint_chroma(image: Image.Image) -> None:
    """The swirl the Paintress leaves in the sky: streamline strokes round the
    number, blue and white in the cold sky, red and yellow near the glow."""
    cx, cy = _EXPEDITION_NUMERAL_CENTRE
    qx0, qy0, qx1, qy1 = _expedition_quote_keepout()
    wx0, wy0, wx1, wy1 = _EXPEDITION_WORDMARK_BOX
    mx0 = _EXPEDITION_MONOLITH[0][0] - 6
    mx1 = _EXPEDITION_MONOLITH[1][0] + 6
    px0, py0, px1, py1 = _EXPEDITION_PAINTRESS_BOX
    black, blue, white = SPECTRA6["black"], SPECTRA6["blue"], SPECTRA6["white"]
    red, yellow = SPECTRA6["red"], SPECTRA6["yellow"]

    def direction(x: float, y: float) -> float:
        dx, dy = x - cx, y - cy
        r = math.hypot(dx, dy) or 1.0
        swirl = math.exp(-(r / 260.0) ** 2)
        tx, ty = -dy / r, dx / r                          # tangent, clockwise about the number
        wx, wy = math.cos(-0.18), math.sin(-0.18)         # the wind, a little upward
        return math.atan2(ty * swirl + wy * (1 - swirl), tx * swirl + wx * (1 - swirl))

    def ink_at(x: int, y: int, r: float):
        if y > _EXPEDITION_HORIZON - 30:
            return None
        if qx0 - 8 < x < qx1 + 8 and qy0 - 8 < y < qy1 + 8:
            return None
        if wx0 < x < wx1 and wy0 < y < wy1:
            return None
        if mx0 < x < mx1 or (px0 < x < px1 and py0 < y < py1):
            return None
        near = math.hypot(x - cx, y - cy)
        if near < 150:
            return red if r < 0.16 else yellow if r < 0.22 else None
        if r < 0.035 and near < 330:
            return white
        return blue if r < 0.44 else None

    paint_flow_strokes(image, (0, 0, image.size[0], _EXPEDITION_HORIZON), direction, ink_at,
                       cell=11, length=22, width=2, steps=4, ground=frozenset({black, blue, red}),
                       salt=_EXPEDITION_SEED)


def _expedition_paint_lamp(image: Image.Image) -> None:
    """The gas lamp lit: a yellow core with white in it, a yellow bloom with
    white at 3/10 — gaslight, not neon — and the cage bars back over it."""
    gx0, gy0, gx1, gy1 = _EXPEDITION_LAMP_GLASS
    mask = Image.new("L", image.size, 0)
    ImageDraw.Draw(mask).rectangle((gx0 + 1, gy0 + 1, gx1 - 1, gy1 - 1), fill=255)
    paint_neon_mask(image, mask, SPECTRA6["yellow"], SPECTRA6["yellow"], radius=9, gamma=1.4, cap=0.62,
                    tile=BAYER_8x8, glow_minor=SPECTRA6["white"], glow_minor_share=0.3,
                    core_minor=SPECTRA6["white"], core_minor_share=0.3)
    draw = ImageDraw.Draw(image)
    black = SPECTRA6["black"]
    mid = (gx0 + gx1) // 2
    draw.line([(mid, gy0), (mid, gy1)], fill=black, width=1)
    draw.line([(gx0, (gy0 + gy1) // 2), (gx1, (gy0 + gy1) // 2)], fill=black, width=1)
    draw.rectangle((gx0, gy0, gx1, gy1), outline=black, width=1)
    mask.close()


def _expedition_background() -> Image.Image:
    """The quote- and hour-independent view, painted and dithered once per process."""
    key = (_expedition_paint_sky, _expedition_paint_sea, _expedition_paint_continent,
           _expedition_paint_monolith, _expedition_paint_paintress, _expedition_paint_promenade,
           _expedition_paint_chroma, _expedition_paint_lamp)
    cached = _EXPEDITION_BACKGROUND.get("frame")
    if cached is not None and cached[0] == key:
        return cached[1]
    size = (800, 480)
    scene = Image.new("RGB", size, _PANEL_INKS["black"])
    _expedition_paint_sky(scene)
    _expedition_paint_sea(scene)
    _expedition_paint_continent(scene)
    _expedition_paint_monolith(scene)
    _expedition_paint_paintress(scene)
    _expedition_paint_promenade(scene)
    # Two quantisers: the sky without green, the water with it.
    image = _dither_calibrated(scene, _EXPEDITION_SKY_INKS)
    sea = _dither_calibrated(scene, _EXPEDITION_SEA_INKS)
    band = Image.new("L", size, 0)
    ImageDraw.Draw(band).rectangle((0, _EXPEDITION_HORIZON + 1, size[0], _EXPEDITION_RAIL_TOP - 1), fill=255)
    image = Image.composite(sea, image, band)
    _expedition_paint_chroma(image)
    _expedition_paint_lamp(image)
    _EXPEDITION_BACKGROUND["frame"] = (key, image)
    return image


def _expedition_quote_keepout() -> tuple[int, int, int, int]:
    x0, y0, x1, y1 = _EXPEDITION_QUOTE_RECT
    return (x0 - 8, y0 - 8, x1 + 8, _EXPEDITION_BYLINE_TOP + 22)


def _expedition_stipple_field(image: Image.Image, field: Image.Image, major, minor, *,
                              cap: float, minor_share: float, ground) -> None:
    """Paint an ``L`` density field as an ordered stipple of two inks on
    ``ground`` pixels — ``paint_neon_mask``'s halo rule applied to a field
    that is itself the light, with no solid core to grow it from."""
    bbox = field.getbbox()
    if bbox is None:
        return
    fp = field.load()
    px = image.load()
    levels = 64
    for y in range(bbox[1], bbox[3]):
        row = BAYER_8x8[y % 8]
        for x in range(bbox[0], bbox[2]):
            level = fp[x, y] / 255.0
            if level <= 0.02 or px[x, y] not in ground:
                continue
            rank = row[x % 8]
            lit = min(cap, level) * levels
            if rank < lit:
                px[x, y] = minor if rank < lit * minor_share else major


def _expedition_numeral_mask(hour: int) -> Image.Image:
    """The hour as the Paintress painted it: Bebas Neue brushed rough —
    bristle gaps, biting edges, drips from its lowest points, a flick."""
    cached = _EXPEDITION_NUMERALS.get(hour)
    if cached is not None:
        return cached
    size = (800, 480)
    x0, y0, x1, y1 = _EXPEDITION_NUMERAL_BOX
    box_w, box_h = x1 - x0, y1 - y0
    text = str(hour)
    candidates = [BEBASNEUE_REGULAR, (ANTONIO_VARIABLE, "Bold"), *QUOTE_FONT_BOLD_CANDIDATES]
    font_size = 196
    while font_size > 40:
        font = load_font(candidates, font_size)
        bbox = ImageDraw.Draw(Image.new("L", (1, 1))).textbbox((0, 0), text, font=font)
        if bbox[2] - bbox[0] <= box_w and bbox[3] - bbox[1] <= box_h:
            break
        font_size -= 4
    glyph = Image.new("L", size, 0)
    gd = ImageDraw.Draw(glyph)
    tx = x0 + (box_w - (bbox[2] - bbox[0])) // 2 - bbox[0]
    ty = y0 + (box_h - (bbox[3] - bbox[1])) // 2 - bbox[1]
    gd.text((tx, ty), text, font=font, fill=255)

    rng = random.Random(_EXPEDITION_SEED * 31 + hour)
    # Bristle gaps: vertical streaks carved out where a tall-celled noise dips.
    bristle = _smooth_noise(size, (120, 6), _EXPEDITION_SEED + 10 + hour).point(lambda v: 255 if v > 26 else 0)
    glyph = ImageChops.multiply(glyph, bristle)
    # Edges that swell and bite: grow where one noise is high, shrink where low.
    bite = _smooth_noise(size, (60, 36), _EXPEDITION_SEED + 20 + hour).point(lambda v: 255 if v > 150 else 0)
    glyph = Image.composite(glyph.filter(ImageFilter.MaxFilter(3)), glyph.filter(ImageFilter.MinFilter(3)), bite)
    # Drips, from the lowest painted pixel in three columns of the glyph.
    gp = glyph.load()
    gd = ImageDraw.Draw(glyph)
    columns = [x for x in range(x0, x1) if any(gp[x, y] for y in range(y0, y1 + 8))]
    if columns:
        for _ in range(2):
            x = rng.choice(columns)
            bottom = max(y for y in range(y0, y1 + 8) if gp[x, y])
            length = rng.randint(14, 40)
            gd.line([(x, bottom), (x, bottom + length)], fill=255, width=2)
            gd.ellipse((x - 2, bottom + length - 1, x + 2, bottom + length + 3), fill=255)
    # A flick of the brush beside the number, where the stroke left the slab.
    fx, fy = x0 + rng.randint(-6, 4), y1 + rng.randint(4, 12)
    gd.line([(fx, fy), (fx + 22, fy - 16)], fill=255, width=2)
    _EXPEDITION_NUMERALS[hour] = glyph
    return glyph


def _expedition_paint_numeral(image: Image.Image, hour: int) -> None:
    """The number, wet and lit: a yellow core with white at 1/4 in a red +
    yellow halo at 1/2, and its reflection broken on the water."""
    mask = _expedition_numeral_mask(hour)
    paint_neon_mask(image, mask, SPECTRA6["yellow"], SPECTRA6["red"], radius=10, gamma=1.25, cap=0.8,
                    tile=BAYER_8x8, glow_minor=SPECTRA6["yellow"], glow_minor_share=0.5,
                    core_minor=SPECTRA6["white"], core_minor_share=0.25)

    hz = _EXPEDITION_HORIZON
    x0, y0, x1, y1 = _EXPEDITION_NUMERAL_BOX
    reach = y1 - y0 + 48
    slab = mask.crop((x0 - 20, y0 - 4, x1 + 20, y1 + 44)).transpose(Image.Transpose.FLIP_TOP_BOTTOM)
    slab = slab.resize((slab.size[0], round(slab.size[1] * 1.25)), Image.Resampling.BILINEAR)
    field = Image.new("L", image.size, 0)
    field.paste(slab, (x0 - 20, hz + 4))
    field = field.filter(ImageFilter.GaussianBlur(2.5))
    fade = Image.new("L", image.size, 0)
    fp = fade.load()
    streaks = _smooth_noise(image.size, (14, 110), _EXPEDITION_SEED + 2).load()
    for y in range(hz, min(image.size[1], hz + 4 + round(reach * 1.25) + 8)):
        depth = math.exp(-(y - hz) / 90.0)
        for x in range(x0 - 20, x1 + 20):
            fp[x, y] = round(255 * depth * (0.3 + 0.7 * streaks[x, y] / 255.0))
    field = ImageChops.multiply(field, fade)
    _expedition_stipple_field(image, field, SPECTRA6["yellow"], SPECTRA6["red"], cap=0.7, minor_share=0.5,
                              ground=frozenset({SPECTRA6["blue"], SPECTRA6["black"], SPECTRA6["green"]}))
    field.close()
    fade.close()


def _expedition_petal_polygon(cx: float, cy: float, size: float, angle: float) -> list:
    """A rose petal: a teardrop, rounded at the base and narrowing to the tip."""
    pts = []
    ca, sa = math.cos(angle), math.sin(angle)
    for k in range(16):
        t = 2 * math.pi * k / 16
        x = math.cos(t) * size
        y = math.sin(t) * size * (0.5 - 0.3 * math.cos(t))
        pts.append((cx + x * ca - y * sa, cy + x * sa + y * ca))
    return pts


def _expedition_gust(quote_row: dict) -> list:
    """The petals, as ``(x, y, size, angle, white_density)``: a cubic path
    from the promenade, under the journal page, up past the Paintress to the
    number, plus a few strays loose in the sky. Seeded from the quote."""
    rng = random.Random(_row_digest(quote_row) ^ _EXPEDITION_SEED)
    p0, p1, p2, p3 = (26, 446), (250, 404), (470, 332), (628, 166)
    keepouts = (_expedition_quote_keepout(), _EXPEDITION_WORDMARK_BOX, _EXPEDITION_CREDO_BOX,
                (_EXPEDITION_NUMERAL_BOX[0] - 10, _EXPEDITION_NUMERAL_BOX[1] - 10,
                 _EXPEDITION_NUMERAL_BOX[2] + 10, _EXPEDITION_NUMERAL_BOX[3] + 30),
                _EXPEDITION_LAMP_BOX)

    def clear(x: float, y: float, size: float) -> bool:
        if not (size < x < 800 - size and size < y < _EXPEDITION_RAIL_TOP - size):
            return False
        return not any(kx0 - size < x < kx1 + size and ky0 - size < y < ky1 + size
                       for kx0, ky0, kx1, ky1 in keepouts)

    petals = []
    for _ in range(64):
        t = rng.random() ** 0.85
        u = 1 - t
        x = u ** 3 * p0[0] + 3 * u * u * t * p1[0] + 3 * u * t * t * p2[0] + t ** 3 * p3[0]
        y = u ** 3 * p0[1] + 3 * u * u * t * p1[1] + 3 * u * t * t * p2[1] + t ** 3 * p3[1]
        dx = 3 * u * u * (p1[0] - p0[0]) + 6 * u * t * (p2[0] - p1[0]) + 3 * t * t * (p3[0] - p2[0])
        dy = 3 * u * u * (p1[1] - p0[1]) + 6 * u * t * (p2[1] - p1[1]) + 3 * t * t * (p3[1] - p2[1])
        heading = math.atan2(dy, dx)
        spread = 16 + 44 * math.sin(math.pi * t)
        off = rng.gauss(0, spread)
        x += -math.sin(heading) * off
        y += math.cos(heading) * off
        size = 3.0 + 12.0 * u * u + rng.uniform(-1.0, 1.5)
        if size < 1.5 or not clear(x, y, size):
            continue
        angle = heading + rng.uniform(-0.9, 0.9)
        petals.append((x, y, size, angle, 0.34 + 0.26 * t))
    for _ in range(10):
        x, y = rng.uniform(20, 780), rng.uniform(20, _EXPEDITION_HORIZON - 20)
        size = rng.uniform(1.8, 4.5)
        if clear(x, y, size):
            petals.append((x, y, size, rng.uniform(0, math.pi), 0.5))
    return petals


def _expedition_paint_petals(image: Image.Image, quote_row: dict) -> None:
    """The gust: each petal a red + white stipple with a white rim toward the
    light and a red one away from it."""
    width, height = image.size
    px = image.load()
    red, white = SPECTRA6["red"], SPECTRA6["white"]
    lx, ly = _EXPEDITION_NUMERAL_CENTRE
    for x, y, size, angle, density in _expedition_gust(quote_row):
        if size < 2.6:
            ix, iy = round(x), round(y)
            for ox, oy, ink in ((0, 0, white), (1, 0, red), (0, 1, red), (1, 1, white)):
                if 0 <= ix + ox < width and 0 <= iy + oy < height:
                    px[ix + ox, iy + oy] = ink
            continue
        pts = _expedition_petal_polygon(x, y, size, angle)
        bx0 = max(0, int(min(p[0] for p in pts)) - 1)
        by0 = max(0, int(min(p[1] for p in pts)) - 1)
        bx1 = min(width - 1, int(max(p[0] for p in pts)) + 1)
        by1 = min(height - 1, int(max(p[1] for p in pts)) + 1)
        mask = Image.new("L", (bx1 - bx0 + 1, by1 - by0 + 1), 0)
        ImageDraw.Draw(mask).polygon([(p[0] - bx0, p[1] - by0) for p in pts], fill=255)
        edge = ImageChops.subtract(mask, mask.filter(ImageFilter.MinFilter(3)))
        mp, ep = mask.load(), edge.load()
        toward = math.atan2(ly - y, lx - x)
        tx, ty = math.cos(toward), math.sin(toward)
        for yy in range(mask.size[1]):
            row = BAYER_4x4[(by0 + yy) % 4]
            for xx in range(mask.size[0]):
                if not mp[xx, yy]:
                    continue
                ax, ay = bx0 + xx, by0 + yy
                if ep[xx, yy]:
                    px[ax, ay] = white if (ax - x) * tx + (ay - y) * ty > 0 else red
                else:
                    px[ax, ay] = white if row[ax % 4] < density * 16 else red


def _expedition_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The journal page: white Fell roman over a black halo, the matched
    phrase in Fell italic and the number's own paint."""
    prose, hot, _ = wrap_quote_into_masks(
        draw, image.size, quote_row, _EXPEDITION_QUOTE_RECT, theme="expedition",
        font_max=31, font_min=13, line_height_mult=1.36,
    )
    _halo_paste(image, ImageChops.lighter(prose, hot), None)
    image.paste(SPECTRA6["white"], (0, 0), prose.point(lambda v: 255 if v > 110 else 0))
    paint_neon_mask(image, hot, SPECTRA6["yellow"], SPECTRA6["red"], radius=3, gamma=1.8, cap=0.5,
                    ground=frozenset({SPECTRA6["black"]}), tile=BAYER_8x8,
                    glow_minor=SPECTRA6["yellow"], glow_minor_share=0.5)
    prose.close()
    hot.close()


def _expedition_paint_byline(image: Image.Image, quote_row: dict) -> None:
    """Author and title as the journal's signature, gold Bebas capitals."""
    x0, _, x1, _ = _EXPEDITION_QUOTE_RECT
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "")
    byline = "  ·  ".join(part.upper() for part in (author, title) if part)
    if not byline:
        return
    mask = Image.new("L", image.size, 0)
    md = ImageDraw.Draw(mask)
    candidates = [BEBASNEUE_REGULAR, (ANTONIO_VARIABLE, "Bold"), *META_FONT_BOLD_CANDIDATES]
    font, text = fit_text_to_width(md, byline, candidates, 17, x1 - x0, floor=13, tracking=3)
    w = tracked_width(md, text, font, tracking=3)
    draw_tracked(md, ((x0 + x1 - w) / 2, _EXPEDITION_BYLINE_TOP), text, font, 255, tracking=3)
    _halo_paste(image, mask, SPECTRA6["yellow"], halo=5)
    mask.close()


def _expedition_paint_chrome(image: Image.Image) -> None:
    """The wordmark and its gold rule, and the expedition's credo."""
    yellow, white = SPECTRA6["yellow"], SPECTRA6["white"]
    x0, y0, _, _ = _EXPEDITION_WORDMARK_BOX
    mask = Image.new("L", image.size, 0)
    md = ImageDraw.Draw(mask)
    draw_tracked(md, (x0 + 2, y0 + 2), "CLAIR OBSCUR", _expedition_label_font(15), 255, tracking=6)
    draw_tracked(md, (x0, y0 + 20), "EXPEDITION 33", _expedition_wordmark_font(25), 255, tracking=3)
    _halo_paste(image, mask, white, halo=5)
    mask.close()
    # The rule: a gold hairline with a diamond at its centre — the ornament
    # every panel of the game's interface is drawn with.
    draw = ImageDraw.Draw(image)
    ry = y0 + 56
    rx1 = x0 + 262
    draw.line([(x0, ry), (rx1, ry)], fill=yellow, width=1)
    mid = (x0 + rx1) // 2
    draw.polygon([(mid, ry - 4), (mid + 4, ry), (mid, ry + 4), (mid - 4, ry)], fill=yellow)
    draw.polygon([(x0, ry - 2), (x0 + 2, ry), (x0, ry + 2), (x0 - 2, ry)], fill=yellow)
    draw.polygon([(rx1, ry - 2), (rx1 + 2, ry), (rx1, ry + 2), (rx1 - 2, ry)], fill=yellow)

    cx0, cy0, cx1, _ = _EXPEDITION_CREDO_BOX
    mask = Image.new("L", image.size, 0)
    md = ImageDraw.Draw(mask)
    font = _expedition_label_font(16)
    draw_tracked(md, (cx1, cy0 + 2), "FOR THOSE WHO COME AFTER", font, 255, tracking=4, anchor_right=True)
    _halo_paste(image, mask, yellow, halo=5)
    mask.close()


def render_expedition_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """The Monolith from the Lumière promenade (see the section comment above)."""
    hour = _clock_hour12(time_str)
    image = _expedition_background().copy()
    draw = ImageDraw.Draw(image)
    _expedition_paint_numeral(image, hour)
    _expedition_paint_petals(image, quote_row)
    _expedition_paint_quote(image, draw, quote_row)
    _expedition_paint_byline(image, quote_row)
    _expedition_paint_chrome(image)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# witcher — CD Projekt Red's *The Witcher 3: Wild Hunt* (2015): a bestiary
# page under the meditation dial
# ---------------------------------------------------------------------------
# Geralt's journal: a parchment page in a leather binding, an entry title in
# condensed capitals over a red rule, the quote as its epigraph, and a
# "susceptible to" line of sign icons at the foot. The **meditation dial** is
# the time carrier, with three claw slashes at its hub.
#
# **The dial is hour-only**: two engraved rings, 48 ticks, and one marker on
# the hour's radius, a sun by day and a crescent by night (chosen by the
# 24-hour hour). Pinned byte-identical across the minutes of an hour by
# ``TestWitcherFrame``; nothing prints a digit.
#
# **The hub** carries three claw slashes after the III of the logotype (the
# Wolf School emblem is CD Projekt's mark, and Roman bars read only as a
# numeral): red blades outlined in black, the outer two scaled down and swung
# outward.
#
# **The page** is the ``tarot`` vellum recipe (Y+W cream under sparse R+G
# foxing) inside a deckled edge eaten by seeded noise. The binding is black
# with a sparse red fleck, six-ink dark brown.
#
# **Type**: Barlow Condensed for title, quote and matched phrase (R+Y
# tangerine stipple), Archivo Narrow for labels, attribution and the
# ``WILD HUNT`` mark (see the ``THEME_FONTS`` entry). Labels are solid ink:
# small text in a stipple shreds.
#
# **Susceptible to**: the five signs drawn as icons, the susceptible ones
# (from ``_row_digest``) filled in the sign's own colour. The entry number is
# the row's real Gutenberg ID.
#
# The page is quote- and hour-independent and cached once per process
# (``_WITCHER_PAGE``, keyed on the painters). Composed at 800x480 and
# NEAREST-downsampled (the ``metro`` convention).
# ---------------------------------------------------------------------------
_WITCHER_SEED = 0x3331
_WITCHER_PAGE_RECT = (30, 28, 770, 452)
_WITCHER_RULE_INSET = 12
_WITCHER_HEADER_Y = 48
_WITCHER_HEADER_RULE_Y = 106
_WITCHER_DIAL_CENTRE = (180, 254)
_WITCHER_DIAL_RADIUS = 108
_WITCHER_MEDALLION_RADIUS = 50
_WITCHER_QUOTE_RECT = (330, 124, 742, 362)
_WITCHER_ATTRIBUTION_TOP = 372
_WITCHER_FOOT_Y = 404
_WITCHER_SIGNS_RIGHT = 742
_WITCHER_CREAM_DENSITY = 0.14
_WITCHER_FOXING_DENSITY = 0.03
_WITCHER_PAGE: dict = {}
# The hub device in a 100-unit box: one blade, pointed at both ends, with the
# spike that trails it below the cut; the outer two are the same blade scaled
# down and swung outward about the hub.
_WITCHER_CLAW_BLADE = ((50, 2), (58, 14), (61, 32), (56, 56), (52, 64), (44, 58), (40, 32), (42, 14))
_WITCHER_CLAW_SPIKE = ((54, 68), (52, 84), (50, 98), (46, 80), (45, 64))
_WITCHER_CLAW_PIVOT = (50, 74)
_WITCHER_CLAWS = ((0.0, 1.0, 0), (-0.22, 0.88, -26), (0.22, 0.88, 26))   # (lean, scale, x offset)
_WITCHER_SIGNS = ("AARD", "IGNI", "YRDEN", "QUEN", "AXII")


def _witcher_hour(time_str: str) -> int:
    """The 24-hour hour, 0..23: the dial needs to know night from day."""
    try:
        return int(str(time_str).split(":", 1)[0]) % 24
    except ValueError:
        return 12


def _witcher_label_font(size: int, instance: str = "Bold"):
    """Archivo Narrow — the nearest open face to Bell Gothic — pinned by instance."""
    return load_font([(ARCHIVONARROW_VARIABLE, instance), ARCHIVO_BOLD, *META_FONT_BOLD_CANDIDATES], size=size)


def _witcher_page_mask(size) -> Image.Image:
    """The page's silhouette: the rect with a deckled, seeded edge."""
    mask = Image.new("L", size, 0)
    ImageDraw.Draw(mask).rectangle(_WITCHER_PAGE_RECT, fill=255)
    band = ImageChops.subtract(mask, mask.filter(ImageFilter.MinFilter(9)))
    tear = _smooth_noise(size, (size[0] // 3, size[1] // 3), _WITCHER_SEED)
    torn = ImageChops.multiply(band, tear.point(lambda v: 255 if v < 118 else 0))
    return ImageChops.subtract(mask, torn)


def _witcher_paint_binding(image: Image.Image) -> None:
    """The leather the page sits in: black with a sparse red fleck, which is
    how six inks spell dark brown, and a few yellow glints of the grain."""
    width, height = image.size
    grain = _white_noise(width, height, _WITCHER_SEED + 1)
    image.paste(SPECTRA6["red"], (0, 0), grain.point(lambda v: 255 if v < 18 else 0))
    image.paste(SPECTRA6["yellow"], (0, 0), grain.point(lambda v: 255 if 252 < v else 0))


def _witcher_paint_parchment(image: Image.Image) -> None:
    """The page: cream Y+W under a sparse R+G foxing, inside the deckled mask."""
    width, height = image.size
    page = Image.new("RGB", image.size, SPECTRA6["white"])
    foxing = _white_noise(width, height, _WITCHER_SEED + 2)
    fox_cut = round(_WITCHER_FOXING_DENSITY * 255)
    page.paste(SPECTRA6["red"], (0, 0), foxing.point(lambda v: 255 if v < fox_cut and v & 1 else 0))
    page.paste(SPECTRA6["green"], (0, 0), foxing.point(lambda v: 255 if v < fox_cut and not v & 1 else 0))
    cream = _white_noise(width, height, _WITCHER_SEED + 3)
    page.paste(SPECTRA6["yellow"], (0, 0), cream.point(lambda v: 255 if v < round(_WITCHER_CREAM_DENSITY * 255) else 0))
    image.paste(page, (0, 0), _witcher_page_mask(image.size))


def _witcher_paint_rules(image: Image.Image) -> None:
    """The game's thin-line chrome: an inset rule with notched corners, and the
    header rule with a diamond at each end."""
    draw = ImageDraw.Draw(image)
    black, red = SPECTRA6["black"], SPECTRA6["red"]
    x0, y0, x1, y1 = _WITCHER_PAGE_RECT
    inset = _WITCHER_RULE_INSET
    x0, y0, x1, y1 = x0 + inset, y0 + inset, x1 - inset, y1 - inset
    notch = 14
    for (cx, sx), (cy, sy) in (((x0, 1), (y0, 1)), ((x1, -1), (y0, 1)), ((x0, 1), (y1, -1)), ((x1, -1), (y1, -1))):
        draw.line([(cx + sx * notch, cy), (cx, cy), (cx, cy + sy * notch)], fill=black, width=2)
    draw.line([(x0 + notch + 6, y0), (x1 - notch - 6, y0)], fill=black, width=1)
    draw.line([(x0 + notch + 6, y1), (x1 - notch - 6, y1)], fill=black, width=1)
    draw.line([(x0, y0 + notch + 6), (x0, y1 - notch - 6)], fill=black, width=1)
    draw.line([(x1, y0 + notch + 6), (x1, y1 - notch - 6)], fill=black, width=1)
    ry = _WITCHER_HEADER_RULE_Y
    draw.line([(56, ry), (744, ry)], fill=red, width=2)
    for dx in (56, 744):
        draw.polygon([(dx, ry - 5), (dx + 5, ry), (dx, ry + 5), (dx - 5, ry)], fill=red)


def _witcher_paint_dial(image: Image.Image) -> None:
    """The meditation dial's engraving: two rings and the tick train. The
    hour marker is painted per render by ``_witcher_paint_marker``."""
    draw = ImageDraw.Draw(image)
    black = SPECTRA6["black"]
    cx, cy = _WITCHER_DIAL_CENTRE
    r = _WITCHER_DIAL_RADIUS
    draw.ellipse((cx - r, cy - r, cx + r, cy + r), outline=black, width=2)
    inner = r - 18
    draw.ellipse((cx - inner, cy - inner, cx + inner, cy + inner), outline=black, width=1)
    for k in range(48):
        ang = math.radians(k * 7.5 - 90)
        major = k % 4 == 0
        r0 = r - (13 if major else 7)
        r1 = r - 3
        draw.line([(cx + math.cos(ang) * r0, cy + math.sin(ang) * r0),
                   (cx + math.cos(ang) * r1, cy + math.sin(ang) * r1)], fill=black, width=2 if major else 1)
    # A hatched band between the rings' inner edge and the tick train, so the
    # dial reads as an engraved plate rather than a drawn circle.
    band = inner + 2
    paint_hatched_tone(image, (cx - r, cy - r, cx + r, cy + r),
                       lambda x, y: 0.42 if band < math.hypot(x - cx, y - cy) < r - 14 else 0.0,
                       52.0, 3.0, black, ground=frozenset({SPECTRA6["white"], SPECTRA6["yellow"]}))
    label = _witcher_label_font(13)
    draw_tracked(draw, (cx - tracked_width(draw, "MEDITATION", label, tracking=4) / 2, cy + r + 10),
                 "MEDITATION", label, black, tracking=4)


def _witcher_claw(lean: float, scale: float, dx: float):
    """One slash's polygons: the blade scaled and swung about the pivot, then
    shifted along the hub; returns the blade and its spike in box units."""
    px, py = _WITCHER_CLAW_PIVOT
    ca, sa = math.cos(lean), math.sin(lean)

    def swing(pts):
        return [(px + dx + ((x - px) * ca - (y - py) * sa) * scale, py + ((x - px) * sa + (y - py) * ca) * scale)
                for x, y in pts]

    return swing(_WITCHER_CLAW_BLADE), swing(_WITCHER_CLAW_SPIKE)


def _witcher_paint_medallion(image: Image.Image) -> None:
    """The hub: three claw slashes in red, outlined in black so they hold on
    the cream, after the III of the title."""
    draw = ImageDraw.Draw(image)
    black, red = SPECTRA6["black"], SPECTRA6["red"]
    cx, cy = _WITCHER_DIAL_CENTRE
    r = _WITCHER_MEDALLION_RADIUS
    scale = r * 2 / 100.0
    ox, oy = cx - 50 * scale, cy - 50 * scale

    def place(pts):
        return [(ox + x * scale, oy + y * scale) for x, y in pts]

    for lean, size, dx in _WITCHER_CLAWS:
        for piece in _witcher_claw(lean, size, dx):
            draw.polygon(place(piece), fill=red, outline=black)


def _witcher_page() -> Image.Image:
    """The entry page without its entry: binding, parchment, rules, dial, medallion."""
    key = (_witcher_paint_binding, _witcher_paint_parchment, _witcher_paint_rules,
           _witcher_paint_dial, _witcher_paint_medallion)
    cached = _WITCHER_PAGE.get("frame")
    if cached is not None and cached[0] == key:
        return cached[1]
    image = Image.new("RGB", (800, 480), SPECTRA6["black"])
    _witcher_paint_binding(image)
    _witcher_paint_parchment(image)
    _witcher_paint_rules(image)
    _witcher_paint_dial(image)
    _witcher_paint_medallion(image)
    _WITCHER_PAGE["frame"] = (key, image)
    return image


def _witcher_paint_marker(image: Image.Image, hour: int) -> None:
    """The hour on the dial: a sun by day, a crescent by night, on the hour's
    radius between the medallion and the inner ring, with a pointer on the
    tick train."""
    draw = ImageDraw.Draw(image)
    black, yellow, white = SPECTRA6["black"], SPECTRA6["yellow"], SPECTRA6["white"]
    cx, cy = _WITCHER_DIAL_CENTRE
    ang = math.radians((hour % 12) * 30 - 90)
    # The marker rides between the claws' reach and the inner ring, so the
    # sun's rays never cross a blade tip; the pointer sits on the ring itself.
    rr = _WITCHER_DIAL_RADIUS - 36
    mx, my = cx + math.cos(ang) * rr, cy + math.sin(ang) * rr
    tip = _WITCHER_DIAL_RADIUS - 11
    draw.polygon([(cx + math.cos(ang) * tip, cy + math.sin(ang) * tip),
                  (cx + math.cos(ang + 0.09) * (tip - 9), cy + math.sin(ang + 0.09) * (tip - 9)),
                  (cx + math.cos(ang - 0.09) * (tip - 9), cy + math.sin(ang - 0.09) * (tip - 9))], fill=black)
    if 6 <= hour < 18:
        for k in range(8):
            a = math.radians(k * 45)
            draw.line([(mx + math.cos(a) * 9, my + math.sin(a) * 9), (mx + math.cos(a) * 14, my + math.sin(a) * 14)],
                      fill=black, width=2)
        draw.ellipse((mx - 8, my - 8, mx + 8, my + 8), fill=yellow, outline=black, width=2)
    else:
        draw.polygon(_witcher_crescent(mx, my, 10, (4.5, -2.5), 8.5), fill=yellow, outline=black)
    del white


def _witcher_crescent(cx: float, cy: float, r: float, bite, br: float) -> list:
    """A crescent as one polygon (disc arc outside the bite, then bite arc
    inside the disc), so it can be filled and outlined in one call."""
    bx, by = cx + bite[0], cy + bite[1]
    outer = [(cx + math.cos(t) * r, cy + math.sin(t) * r) for t in (k * math.pi / 36 for k in range(72))]
    outer = [p for p in outer if math.hypot(p[0] - bx, p[1] - by) >= br]
    # Rotate the kept arc so it starts just after the bite.
    d = math.atan2(by - cy, bx - cx)
    outer.sort(key=lambda p: (math.atan2(p[1] - cy, p[0] - cx) - d) % (2 * math.pi))
    inner = [(bx + math.cos(t) * br, by + math.sin(t) * br) for t in (k * math.pi / 36 for k in range(72))]
    inner = [p for p in inner if math.hypot(p[0] - cx, p[1] - cy) <= r]
    inner.sort(key=lambda p: (math.atan2(p[1] - by, p[0] - bx) - d - math.pi) % (2 * math.pi))
    def area(pts):
        return abs(sum(x0 * y1 - x1 * y0 for (x0, y0), (x1, y1) in zip(pts, pts[1:] + pts[:1])))
    a, b = outer + inner, outer + inner[::-1]
    return a if area(a) >= area(b) else b


def _witcher_entry_title(quote_row: dict) -> str:
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "") or "Untitled Entry"
    return title.upper()


def _witcher_paint_header(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """``BESTIARY`` and the entry number over the title in condensed capitals."""
    black, red = SPECTRA6["black"], SPECTRA6["red"]
    x0, x1 = 56, 744
    small = _witcher_label_font(13)
    draw_tracked(draw, (x0, _WITCHER_HEADER_Y - 2), "BESTIARY", small, red, tracking=4)
    source_id = str(quote_row.get("source_id") or "").strip()
    if source_id:
        draw_tracked(draw, (x1, _WITCHER_HEADER_Y - 2), f"ENTRY No. {source_id}", small, black, tracking=3,
                     anchor_right=True)
    title_font, title = fit_text_to_width(draw, _witcher_entry_title(quote_row),
                                          [BARLOWCOND_BOLD, (ARCHIVONARROW_VARIABLE, "Bold"), *META_FONT_BOLD_CANDIDATES],
                                          34, x1 - x0, floor=22, tracking=1)
    draw_tracked(draw, (x0, _WITCHER_HEADER_Y + 16), title, title_font, black, tracking=1)


def _witcher_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The entry's epigraph: Barlow Condensed in black ink, ragged right, the
    matched phrase Bold in the interface's red-orange (R+Y tangerine)."""
    x0, y0, x1, y1 = _WITCHER_QUOTE_RECT
    black, red, yellow = SPECTRA6["black"], SPECTRA6["red"], SPECTRA6["yellow"]
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    quote_font, quote_font_bold, wrapped, line_height, _ = fit_quote(
        draw, display_quote, quote_row.get("matched_text") or "",
        x1 - x0, y1 - y0, font_max=32, font_min=14, line_height_mult=1.28, theme="witcher",
    )
    y = y0
    ascent = _font_ascent(quote_font)
    for line in wrapped:
        x = x0
        for chunk, is_bold in line:
            font = quote_font_bold if is_bold else quote_font
            chunk_y = y + (ascent - _font_ascent(font))
            if is_bold:
                draw_text_dithered(image, (x, chunk_y), chunk, font, red, yellow, light_density=0.375)
            else:
                draw.text((x, chunk_y), chunk, font=font, fill=black)
            x += int(round(draw.textlength(chunk, font=font)))
        y += line_height
    author = (quote_row.get("author") or "").strip()
    if author:
        attribution = _witcher_label_font(15, "Medium")
        draw_tracked(draw, (x0, min(y + 10, _WITCHER_ATTRIBUTION_TOP)), f"— {author.upper()}", attribution, black,
                     tracking=2)


# The signs' colours: Aard blue, Igni red, Yrden's violet as blue with red
# spokes (a two-ink stipple is too small at 16 px), Quen gold, Axii solid red.
_WITCHER_SIGN_INKS = {"AARD": "blue", "IGNI": "red", "YRDEN": "blue", "QUEN": "yellow", "AXII": "red"}


def _witcher_susceptible(quote_row: dict) -> set:
    """The signs this entry is susceptible to: one bit of the digest each,
    at least one always."""
    digest = _row_digest(quote_row)
    susceptible = {name for k, name in enumerate(_WITCHER_SIGNS) if (digest >> k) & 1}
    return susceptible or {_WITCHER_SIGNS[digest % 5]}


def _witcher_sign_icon(draw: ImageDraw.ImageDraw, name: str, cx: float, cy: float, filled: bool) -> None:
    """One of the five signs as a 16 px icon, in its own colour when the entry
    is susceptible to it and a black outline otherwise."""
    black, red = SPECTRA6["black"], SPECTRA6["red"]
    ink = SPECTRA6[_WITCHER_SIGN_INKS[name]] if filled else black
    if name == "AARD":                                          # a blast: three chevrons
        for k in range(3):
            x = cx - 7 + k * 5
            draw.line([(x, cy - 7), (x + 5, cy), (x, cy + 7)], fill=ink, width=2)
    elif name == "IGNI":                                        # a flame
        pts = [(cx, cy - 9), (cx + 6, cy - 1), (cx + 4, cy + 8), (cx - 4, cy + 8), (cx - 6, cy - 1)]
        if filled:
            draw.polygon(pts, fill=ink)
        else:
            draw.polygon(pts, outline=ink, width=2)
        draw.polygon([(cx, cy - 2), (cx + 2, cy + 4), (cx - 2, cy + 4)], fill=SPECTRA6["white"])
    elif name == "YRDEN":                                       # the trap: a circle with three spokes
        draw.ellipse((cx - 8, cy - 8, cx + 8, cy + 8), outline=ink, width=2, fill=ink if filled else None)
        for k in range(3):
            a = math.radians(k * 120 - 90)
            draw.line([(cx, cy), (cx + math.cos(a) * 7, cy + math.sin(a) * 7)], fill=red if filled else ink, width=2)
    elif name == "QUEN":                                        # the shield: a diamond in a diamond
        outer = [(cx, cy - 9), (cx + 8, cy), (cx, cy + 9), (cx - 8, cy)]
        if filled:
            draw.polygon(outer, fill=ink, outline=black)
            draw.polygon([(cx, cy - 4), (cx + 3, cy), (cx, cy + 4), (cx - 3, cy)], fill=black)
        else:
            draw.polygon(outer, outline=ink, width=2)
            draw.polygon([(cx, cy - 4), (cx + 3, cy), (cx, cy + 4), (cx - 3, cy)], outline=ink)
    else:                                                       # AXII: a spiral
        pts = [(cx + math.cos(t) * t * 1.35, cy + math.sin(t) * t * 1.35) for t in [k * 0.25 for k in range(1, 27)]]
        draw.line(pts, fill=ink, width=3 if filled else 2)


def _witcher_paint_foot(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The entry's foot: the ``WILD HUNT`` mark at the left, and the five signs
    at the right, the susceptible ones filled in their own colour."""
    black, red = SPECTRA6["black"], SPECTRA6["red"]
    y = _WITCHER_FOOT_Y
    mark = _witcher_label_font(15)
    draw_tracked(draw, (56, y + 2), "THE WITCHER", mark, black, tracking=3)
    w = tracked_width(draw, "THE WITCHER", mark, tracking=3)
    draw_tracked(draw, (56 + w + 12, y + 2), "WILD HUNT", mark, red, tracking=3)
    label = _witcher_label_font(12, "Medium")
    susceptible = _witcher_susceptible(quote_row)
    x = _WITCHER_SIGNS_RIGHT
    for name in reversed(_WITCHER_SIGNS):
        x -= 24
        _witcher_sign_icon(draw, name, x + 10, y + 10, name in susceptible)
    draw_tracked(draw, (x - 12, y + 4), "SUSCEPTIBLE TO", label, black, tracking=3, anchor_right=True)


def render_witcher_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A bestiary page under the meditation dial (see the section comment above)."""
    hour = _witcher_hour(time_str)
    image = _witcher_page().copy()
    draw = ImageDraw.Draw(image)
    _witcher_paint_marker(image, hour)
    _witcher_paint_header(image, draw, quote_row)
    _witcher_paint_quote(image, draw, quote_row)
    _witcher_paint_foot(image, draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# hades — Supergiant Games' *Hades II* (2025): a boon at the Crossroads under
# the moon
# ---------------------------------------------------------------------------
# The Crossroads at night, lit by the moon and Hecate's green witchfire, and a
# **boon** card: dark, gold-framed, a portrait medallion at the left, the god's
# name across the top and the description beneath. The author is the god, the
# quote is the boon, the matched phrase is lit in gold.
#
# **The moon is the hour**: full at twelve, new at six, first quarter at nine,
# last quarter at three. Hour-only, pinned byte-identical across the minutes
# of an hour by ``TestHadesFrame``. The terminator is the ellipse
# ``x = cos(2πp)·√(1-y²)``; the unlit limb keeps a thin blue rim so a new moon
# is still a moon.
#
# **The sky is painted in continuous tone and dithered** against the
# calibrated inks (the ``expedition`` posture; black, blue, green, white, no
# red). Stars, ridge and braziers go on after the dither so they stay crisp;
# the brazier flame is a white core in a green bloom.
#
# **The card** is black with a sparse blue fleck (six-ink midnight) in a double
# gold rule with bossed corners and a **Greek-key frieze** (one continuous line
# on a 3 px grid). The medallion holds Chronos's **hourglass**, the sand Y with
# a red lattice so it reads amber rather than lemon.
#
# **Type**: Caesar Dressing for the author (yellow with a 1 px red stroke so it
# reads as beaten gold), Spectral for the body and matched phrase, Spectral SC
# for the title, Lato for the rarity label, Hammersmith One (the open
# Johnston) for the chrome.
#
# **Rarity is a roll**: ``_row_digest`` picks Common .. Legendary at the
# game's rough odds; pips are filled in the rarity's colour.
#
# The scene is quote- and hour-independent and painted once per process
# (``_HADES_SCENE``, keyed on the painters). Composed at 800x480 and
# NEAREST-downsampled (the ``metro`` convention).
# ---------------------------------------------------------------------------
_HADES_SEED = 0x4D454C                 # MEL
_HADES_HORIZON = 176                   # the card's top edge; the sky ends here
_HADES_RIDGE_Y = 156
_HADES_MOON_CENTRE = (636, 84)
_HADES_MOON_RADIUS = 46
_HADES_PANEL_RECT = (34, 176, 766, 448)
_HADES_PANEL_INSET = 7
_HADES_FRIEZE_UNIT = 3
_HADES_FRIEZE_TOP = 188                # the head frieze's top row; the foot's mirrors it
_HADES_MEDALLION_CENTRE = (130, 310)
_HADES_MEDALLION_RADIUS = 66
_HADES_DIVIDER_X = 216
_HADES_TITLE_X = 238
_HADES_TITLE_RIGHT = 738
_HADES_TITLE_Y = 204
_HADES_RULE_Y = 250
_HADES_QUOTE_RECT = (238, 260, 738, 396)
_HADES_FOOT_Y = 404
_HADES_BRAZIERS = (84, 716)            # the torches on the ridge
_HADES_WORDMARK_XY = (36, 16)
_HADES_LABEL_XY = (37, 48)
# Two quantisers, the ``expedition`` posture: the upper sky without green
# (the grain otherwise tips the zenith's black-violet into green specks)
# and the horizon band with it, where the teal and the witchfire live.
_HADES_SKY_INKS = ("black", "blue", "white")
_HADES_HORIZON_INKS = ("black", "blue", "green", "white")
_HADES_HORIZON_BAND = 112              # green is admitted below this row
# Night, top to the card's edge, in the calibrated space: black-violet
# zenith, the panel's blue, a teal glow at the horizon.
_HADES_SKY_STOPS = (
    (0, (24, 26, 52)), (60, (30, 40, 88)), (120, (36, 56, 112)),
    (156, (40, 70, 110)), (_HADES_HORIZON, (44, 84, 96)),
)
_HADES_MOON_GLOW = (150, 168, 184)
_HADES_WITCH_GLOW = (66, 122, 92)
# (label, pips, pip fill, pip outline) at the game's rough odds; the roll is
# ``_row_digest`` mod 100 against ``_HADES_RARITY_FLOORS``.
_HADES_RARITIES = (
    ("COMMON", 1, "white", "white"),
    ("RARE", 2, "blue", "blue"),
    ("EPIC", 3, "blue", "red"),
    ("HEROIC", 4, "red", "red"),
    ("LEGENDARY", 5, "yellow", "yellow"),
)
_HADES_RARITY_FLOORS = (0, 50, 78, 92, 98)
_HADES_SCENE: dict = {}


def _hades_phase(hour: int) -> float:
    """Lunar phase for the hour, 0 new .. 0.5 full .. 1 new: full at twelve,
    new at six, first quarter at nine, last quarter at three."""
    return ((hour % 12) + 6) / 12.0 % 1.0


def _hades_title_font(size: int):
    """Caesar Dressing — the game's title-card face — before Cinzel Decorative."""
    return load_font([CAESARDRESSING_REGULAR, CINZELDECORATIVE_BOLD, *META_FONT_BOLD_CANDIDATES], size=size)


def _hades_chrome_font(size: int):
    """Hammersmith One — the open Johnston, for the game's P22 Underground chrome."""
    return load_font([HAMMERSMITHONE_REGULAR, (JOST_VARIABLE, "Medium"), *META_FONT_BOLD_CANDIDATES], size=size)


def _hades_label_font(size: int):
    """Lato Bold — the game's secondary face — for the rarity label."""
    return load_font([LATO_BOLD, *META_FONT_BOLD_CANDIDATES], size=size)


def _hades_paint_sky(scene: Image.Image) -> None:
    """The night in continuous tone: the gradient, the brush facture, the
    moon's halo and the witch-glow pooled under the braziers."""
    width, height = scene.size
    hz = _HADES_HORIZON
    column = Image.new("RGB", (1, hz))
    cp = column.load()
    for y in range(hz):
        cp[0, y] = _lerp_stops(_HADES_SKY_STOPS, y)
    scene.paste(column.resize((width, hz), Image.Resampling.NEAREST), (0, 0))
    scene.paste(Image.new("RGB", (width, height - hz), _HADES_SKY_STOPS[-1][1]), (0, hz))
    # Brush facture: a stretched noise, ±7 levels, so the dither lays grain
    # across the sky rather than a flat field.
    grain = _smooth_noise((width, height), (64, 24), _HADES_SEED + 1).point(lambda v: v // 18)
    tint = Image.merge("RGB", (grain, grain, grain))
    scene.paste(ImageChops.subtract(ImageChops.add(scene, tint), Image.new("RGB", scene.size, (7, 7, 7))))
    # The moon's halo.
    mx, my = _HADES_MOON_CENTRE
    reach = _HADES_MOON_RADIUS * 1.7
    halo = Image.new("L", scene.size, 0)
    ImageDraw.Draw(halo).ellipse((mx - reach, my - reach, mx + reach, my + reach), fill=255)
    halo = halo.filter(ImageFilter.GaussianBlur(36)).point(lambda v: int(v * 0.62))
    scene.paste(Image.new("RGB", scene.size, _HADES_MOON_GLOW), (0, 0), halo)
    # Witchfire pooled on the horizon under each brazier.
    fire = Image.new("L", scene.size, 0)
    fd = ImageDraw.Draw(fire)
    for bx in _HADES_BRAZIERS:
        fd.ellipse((bx - 80, _HADES_RIDGE_Y - 40, bx + 80, _HADES_RIDGE_Y + 44), fill=255)
    fire = fire.filter(ImageFilter.GaussianBlur(28)).point(lambda v: int(v * 0.55))
    scene.paste(Image.new("RGB", scene.size, _HADES_WITCH_GLOW), (0, 0), fire)


def _hades_paint_stars(image: Image.Image) -> None:
    """A seeded field of stars above the ridge, clear of the moon: most a
    single white pixel, some a 2x2, a few a four-point cross."""
    rng = random.Random(_HADES_SEED + 2)
    draw = ImageDraw.Draw(image)
    px = image.load()
    white = SPECTRA6["white"]
    mx, my = _HADES_MOON_CENTRE
    keep = _HADES_MOON_RADIUS + 28
    for _ in range(190):
        x, y = rng.randrange(4, image.size[0] - 4), rng.randrange(4, _HADES_RIDGE_Y - 24)
        roll = rng.random()
        if math.hypot(x - mx, y - my) < keep:
            continue
        if roll < 0.72:
            px[x, y] = white
        elif roll < 0.92:
            draw.rectangle((x, y, x + 1, y + 1), fill=white)
        else:
            draw.line([(x - 3, y), (x + 3, y)], fill=white, width=1)
            draw.line([(x, y - 3), (x, y + 3)], fill=white, width=1)


def _hades_paint_ridge(image: Image.Image) -> None:
    """The Crossroads' horizon in silhouette: a low ridge over black earth
    that runs to the foot of the frame, cypresses, and two broken columns
    with a blue fluting glint on the taller one."""
    draw = ImageDraw.Draw(image)
    black, blue = SPECTRA6["black"], SPECTRA6["blue"]
    rng = random.Random(_HADES_SEED + 3)
    width = image.size[0]
    height = image.size[1]
    ridge = [(0, height)]
    x, y = 0, _HADES_RIDGE_Y + 6
    while x <= width:
        ridge.append((x, y))
        x += rng.randint(30, 70)
        y = max(_HADES_RIDGE_Y - 6, min(_HADES_RIDGE_Y + 12, y + rng.randint(-6, 6)))
    ridge.extend([(width, y), (width, height)])
    draw.polygon(ridge, fill=black)
    earth = Image.new("L", image.size, 0)
    ImageDraw.Draw(earth).polygon(ridge, fill=255)
    fleck = _white_noise(width, height, _HADES_SEED + 8).point(lambda v: 255 if v < 6 else 0)
    image.paste(blue, (0, 0), ImageChops.multiply(earth, fleck))
    earth.close()
    base = _HADES_RIDGE_Y + 8
    for cx, h, w in ((188, 64, 12), (212, 88, 15), (236, 56, 11), (462, 70, 13), (484, 48, 10), (556, 94, 16)):
        draw.polygon([(cx, base - h), (cx + w * 0.34, base - h * 0.74), (cx + w * 0.5, base - h * 0.42),
                      (cx + w * 0.4, base), (cx - w * 0.4, base), (cx - w * 0.5, base - h * 0.42),
                      (cx - w * 0.34, base - h * 0.74)], fill=black)
    for cx, h, broken in ((330, 72, False), (372, 44, True)):
        draw.rectangle((cx - 7, base - h, cx + 7, base), fill=black)
        if broken:
            draw.polygon([(cx - 7, base - h), (cx - 3, base - h - 9), (cx + 2, base - h - 3),
                          (cx + 7, base - h - 11), (cx + 7, base - h)], fill=black)
        else:
            draw.rectangle((cx - 11, base - h - 6, cx + 11, base - h), fill=black)
            draw.line([(cx - 3, base - h + 4), (cx - 3, base - 2)], fill=blue, width=1)


def _hades_paint_braziers(image: Image.Image) -> None:
    """Hecate's torches on the ridge: a gold tripod and bowl, and a flame
    that is a white core in a green bloom — witchfire."""
    draw = ImageDraw.Draw(image)
    black, yellow = SPECTRA6["black"], SPECTRA6["yellow"]
    flame = Image.new("L", image.size, 0)
    fd = ImageDraw.Draw(flame)
    by = _HADES_RIDGE_Y
    for bx in _HADES_BRAZIERS:
        for dx in (-9, 0, 9):
            draw.line([(bx + dx * 1.7, by + 22), (bx + dx * 0.4, by + 4)], fill=yellow, width=2)
        draw.chord((bx - 16, by - 10, bx + 16, by + 12), 0, 180, fill=black, outline=yellow, width=2)
        draw.line([(bx - 17, by + 1), (bx + 17, by + 1)], fill=yellow, width=2)
        fd.polygon([(bx, by - 48), (bx + 7, by - 30), (bx + 11, by - 12), (bx + 6, by - 2), (bx - 6, by - 2),
                    (bx - 11, by - 14), (bx - 6, by - 32)], fill=255)
        fd.polygon([(bx + 8, by - 36), (bx + 15, by - 22), (bx + 9, by - 6)], fill=255)
        fd.polygon([(bx - 9, by - 32), (bx - 16, by - 20), (bx - 9, by - 6)], fill=255)
    paint_neon_mask(image, flame, SPECTRA6["white"], SPECTRA6["green"], radius=7, gamma=1.5, cap=0.62,
                    tile=BAYER_8x8, core_minor=SPECTRA6["green"], core_minor_share=0.45,
                    ground=frozenset({SPECTRA6["black"], SPECTRA6["blue"], SPECTRA6["green"]}))
    flame.close()


def _hades_meander(draw: ImageDraw.ImageDraw, x0: int, top: int, x1: int, ink, flip: bool = False) -> None:
    """A Greek key as one continuous line on a ``_HADES_FRIEZE_UNIT`` grid:
    a baseline with a square spiral rising from it every period. ``flip``
    hangs the spirals from the baseline instead, for the foot."""
    u = _HADES_FRIEZE_UNIT
    period = 4 * u
    n = int((x1 - x0) // period)

    def row(k: int) -> int:
        return top + (3 - k) * u if flip else top + k * u

    draw.line([(x0, row(3)), (x0 + n * period, row(3))], fill=ink, width=1)
    x = x0
    for _ in range(n):
        draw.line([(x, row(3)), (x, row(0)), (x + 3 * u, row(0)), (x + 3 * u, row(2)),
                   (x + u, row(2)), (x + u, row(1)), (x + 2 * u, row(1))], fill=ink, width=1)
        x += period


def _hades_paint_panel(image: Image.Image) -> None:
    """The boon card: a midnight ground (black with a blue fleck) in a double
    gold rule, a meander frieze at the head and foot, bossed corners, and the
    divider between the portrait and the text."""
    x0, y0, x1, y1 = _HADES_PANEL_RECT
    draw = ImageDraw.Draw(image)
    black, yellow, blue = SPECTRA6["black"], SPECTRA6["yellow"], SPECTRA6["blue"]
    draw.rectangle((x0, y0, x1, y1), fill=black)
    fleck = _white_noise(x1 - x0 + 1, y1 - y0 + 1, _HADES_SEED + 5).point(lambda v: 255 if v < 9 else 0)
    image.paste(blue, (x0, y0), fleck)
    draw.rectangle((x0, y0, x1, y1), outline=yellow, width=2)
    i = _HADES_PANEL_INSET
    draw.rectangle((x0 + i, y0 + i, x1 - i, y1 - i), outline=yellow, width=1)
    frieze_h = 3 * _HADES_FRIEZE_UNIT
    _hades_meander(draw, x0 + 30, _HADES_FRIEZE_TOP, x1 - 30, yellow)
    _hades_meander(draw, x0 + 30, y1 - (_HADES_FRIEZE_TOP - y0) - frieze_h, x1 - 30, yellow, flip=True)
    for cx, cy in ((x0 + 18, y0 + 18), (x1 - 18, y0 + 18), (x0 + 18, y1 - 18), (x1 - 18, y1 - 18)):
        draw.polygon([(cx, cy - 7), (cx + 7, cy), (cx, cy + 7), (cx - 7, cy)], fill=yellow)
        draw.polygon([(cx, cy - 2), (cx + 2, cy), (cx, cy + 2), (cx - 2, cy)], fill=black)
    dx = _HADES_DIVIDER_X
    draw.line([(dx, y0 + 34), (dx, y1 - 34)], fill=yellow, width=1)
    for fy in (y0 + 30, y1 - 30):
        draw.polygon([(dx, fy - 5), (dx + 4, fy), (dx, fy + 5), (dx - 4, fy)], fill=yellow)


def _hades_hourglass_masks(size, cx: int, cy: int, s: int, w: int) -> tuple[Image.Image, Image.Image, list, list]:
    """The two bulbs as ``L`` masks plus their outlines: wide at the frame
    bars, three pixels at the neck."""
    def bulb(sign: int) -> list:
        right = []
        for k in range(13):
            t = k / 12.0
            right.append((cx + w * (1 - t ** 2.2) + 3 * t ** 2.2, cy + sign * (s - t * (s - 2))))
        return right + [(2 * cx - x, y) for x, y in reversed(right)]

    upper, lower = bulb(-1), bulb(1)
    masks = []
    for pts in (upper, lower):
        mask = Image.new("L", size, 0)
        ImageDraw.Draw(mask).polygon(pts, fill=255)
        masks.append(mask)
    return masks[0], masks[1], upper, lower


def _hades_paint_medallion(image: Image.Image) -> None:
    """The portrait medallion: a blue bloom behind a black disc in gold
    rings, with Chronos's hourglass in it and his name beneath."""
    cx, cy = _HADES_MEDALLION_CENTRE
    r = _HADES_MEDALLION_RADIUS
    black, yellow, blue, red = SPECTRA6["black"], SPECTRA6["yellow"], SPECTRA6["blue"], SPECTRA6["red"]
    glow = Image.new("L", image.size, 0)
    ImageDraw.Draw(glow).ellipse((cx - r + 2, cy - r + 2, cx + r - 2, cy + r - 2), fill=255)
    paint_neon_mask(image, glow, None, blue, radius=16, gamma=1.3, cap=0.5, tile=BAYER_8x8,
                    ground=frozenset({black, blue}))
    glow.close()
    draw = ImageDraw.Draw(image)
    draw.ellipse((cx - r, cy - r, cx + r, cy + r), fill=black)
    disc = Image.new("L", image.size, 0)
    ImageDraw.Draw(disc).ellipse((cx - r + 8, cy - r + 8, cx + r - 8, cy + r - 8), fill=255)
    speck = _white_noise(image.size[0], image.size[1], _HADES_SEED + 6).point(lambda v: 255 if v < 30 else 0)
    image.paste(blue, (0, 0), ImageChops.multiply(disc, speck))
    disc.close()
    draw.ellipse((cx - r, cy - r, cx + r, cy + r), outline=yellow, width=3)
    draw.ellipse((cx - r + 7, cy - r + 7, cx + r - 7, cy + r - 7), outline=yellow, width=1)
    for k in range(8):
        a = math.radians(k * 45)
        tx, ty = cx + math.cos(a) * (r - 4), cy + math.sin(a) * (r - 4)
        draw.ellipse((tx - 2, ty - 2, tx + 2, ty + 2), fill=yellow)
    # The hourglass: frame bars and posts, the bulbs outlined, the sand.
    s, w = 38, 24
    draw.rectangle((cx - w - 5, cy - s - 5, cx + w + 5, cy - s), fill=yellow)
    draw.rectangle((cx - w - 5, cy + s, cx + w + 5, cy + s + 5), fill=yellow)
    for sx in (-1, 1):
        draw.line([(cx + sx * (w + 3), cy - s), (cx + sx * (w + 3), cy + s)], fill=yellow, width=2)
    upper_mask, lower_mask, upper, lower = _hades_hourglass_masks(image.size, cx, cy, s, w)
    sand = Image.new("L", image.size, 0)
    sd = ImageDraw.Draw(sand)
    sd.rectangle((cx - w, cy - s * 0.5, cx + w, cy), fill=255)
    sd.polygon([(cx - w * 0.85, cy + s), (cx, cy + s * 0.3), (cx + w * 0.85, cy + s)], fill=255)
    sand = ImageChops.multiply(sand, ImageChops.lighter(upper_mask, lower_mask))
    image.paste(yellow, (0, 0), sand)
    lattice = Image.new("L", image.size, 0)
    lp = lattice.load()
    bbox = sand.getbbox()
    if bbox:
        for y in range(bbox[1], bbox[3], 2):
            for x in range(bbox[0] + (y // 2) % 2, bbox[2], 2):
                lp[x, y] = 255
    image.paste(red, (0, 0), ImageChops.multiply(sand, lattice))
    for pts in (upper, lower):
        draw.line(pts + [pts[0]], fill=yellow, width=2, joint="curve")
    draw.line([(cx, cy - 1), (cx, cy + s - 8)], fill=yellow, width=1)
    for m in (upper_mask, lower_mask, sand, lattice):
        m.close()
    font = _hades_chrome_font(12)
    draw_tracked(draw, (cx - tracked_width(draw, "CHRONOS", font, tracking=4) / 2, cy + r + 10),
                 "CHRONOS", font, yellow, tracking=4)


def _hades_paint_label(image: Image.Image) -> None:
    """The title card at the top left: the wordmark in Caesar Dressing over
    the location in the open Johnston."""
    draw = ImageDraw.Draw(image)
    yellow, white = SPECTRA6["yellow"], SPECTRA6["white"]
    mark = _hades_title_font(24)
    x, y = _HADES_WORDMARK_XY
    for ch in "HADES II":
        draw.text((x, y), ch, font=mark, fill=yellow, stroke_width=1, stroke_fill=SPECTRA6["red"])
        x += draw.textlength(ch, font=mark) + 3
    label = _hades_chrome_font(12)
    w = draw_tracked(draw, _HADES_LABEL_XY, "THE CROSSROADS", label, white, tracking=5)
    lx, ly = _HADES_LABEL_XY
    draw.line([(lx, ly + 19), (lx + w, ly + 19)], fill=yellow, width=1)


def _hades_scene() -> Image.Image:
    """The card without its boon: sky, stars, ridge, braziers, card,
    medallion, title card. Painted once per process."""
    key = (_hades_paint_sky, _hades_paint_stars, _hades_paint_ridge, _hades_paint_braziers,
           _hades_paint_panel, _hades_paint_medallion, _hades_paint_label)
    cached = _HADES_SCENE.get("frame")
    if cached is not None and cached[0] == key:
        return cached[1]
    size = (800, 480)
    scene = Image.new("RGB", size, _PANEL_INKS["black"])
    _hades_paint_sky(scene)
    image = _dither_calibrated(scene, _HADES_SKY_INKS)
    horizon = _dither_calibrated(scene, _HADES_HORIZON_INKS)
    # Feathered over 40 rows, so the seam between the quantisers is a drift
    # of green into the blue rather than a rule across the sky.
    band = Image.new("L", size, 0)
    ImageDraw.Draw(band).rectangle((0, _HADES_HORIZON_BAND + 20, size[0], size[1]), fill=255)
    band = band.filter(ImageFilter.GaussianBlur(12))
    image = Image.composite(horizon, image, band.point(lambda v: 255 if v > 128 - (v % 7) * 18 else 0))
    _hades_paint_stars(image)
    _hades_paint_ridge(image)
    _hades_paint_braziers(image)
    _hades_paint_panel(image)
    _hades_paint_medallion(image)
    _hades_paint_label(image)
    _HADES_SCENE["frame"] = (key, image)
    return image


def _hades_paint_moon(image: Image.Image, hour: int) -> None:
    """The moon at the hour's phase: the lit disc white with a blue dapple
    of maria, the unlit disc black with a thin blue rim."""
    phase = _hades_phase(hour)
    cx, cy = _HADES_MOON_CENTRE
    r = _HADES_MOON_RADIUS
    white, black, blue = SPECTRA6["white"], SPECTRA6["black"], SPECTRA6["blue"]
    maria = _smooth_noise((2 * r + 1, 2 * r + 1), (26, 26), _HADES_SEED + 7)
    mp = maria.load()
    px = image.load()
    k = math.cos(2 * math.pi * phase)
    waxing = phase < 0.5
    for y in range(cy - r, cy + r + 1):
        v = (y - cy) / r
        half = math.sqrt(max(0.0, 1 - v * v))
        term = k * half
        for x in range(cx - r, cx + r + 1):
            u = (x - cx) / r
            rr = u * u + v * v
            if rr > 1:
                continue
            lit = (u > term) if waxing else (u < -term)
            if lit:
                px[x, y] = blue if mp[x - cx + r, y - cy + r] < 58 else white
            else:
                px[x, y] = blue if rr > 0.86 else black


def _hades_paint_title(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The boon's name — the author — in Caesar Dressing, gold with a red
    stroke, over a gold rule with a diamond."""
    yellow, red = SPECTRA6["yellow"], SPECTRA6["red"]
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "")
    name = (author or title or "The Crossroads").upper()
    font, text = fit_text_to_width(draw, name, [CAESARDRESSING_REGULAR, CINZELDECORATIVE_BOLD, *META_FONT_BOLD_CANDIDATES],
                                   36, _HADES_TITLE_RIGHT - _HADES_TITLE_X, floor=22, tracking=2)
    x = _HADES_TITLE_X
    for ch in text:
        draw.text((x, _HADES_TITLE_Y), ch, font=font, fill=yellow, stroke_width=1, stroke_fill=red)
        x += draw.textlength(ch, font=font) + 2
    ry = _HADES_RULE_Y
    draw.line([(_HADES_TITLE_X + 10, ry), (_HADES_TITLE_RIGHT, ry)], fill=yellow, width=1)
    draw.polygon([(_HADES_TITLE_X + 4, ry - 4), (_HADES_TITLE_X + 8, ry), (_HADES_TITLE_X + 4, ry + 4),
                  (_HADES_TITLE_X, ry)], fill=yellow)


def _hades_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The boon's text: white Spectral, ragged right, the matched phrase
    SemiBold in gold — the card's highlighted key words."""
    placed = _place_quote(draw, quote_row, _HADES_QUOTE_RECT, theme="hades",
                          font_max=30, font_min=14, line_height_mult=1.3)
    _paint_placed(draw, placed, SPECTRA6["white"], SPECTRA6["yellow"])


def _hades_rarity(quote_row: dict) -> int:
    """The boon's rarity, 0 Common .. 4 Legendary: a roll from the digest."""
    roll = _row_digest(quote_row) % 100
    return max(i for i, floor in enumerate(_HADES_RARITY_FLOORS) if roll >= floor)


def _hades_paint_foot(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The foot: the rarity pips and label at the left, the book's title in
    small caps at the right."""
    yellow, white = SPECTRA6["yellow"], SPECTRA6["white"]
    label, pips, fill, outline = _HADES_RARITIES[_hades_rarity(quote_row)]
    y = _HADES_FOOT_Y
    for k in range(5):
        cx, cy = _HADES_TITLE_X + 6 + k * 16, y + 9
        diamond = [(cx, cy - 6), (cx + 6, cy), (cx, cy + 6), (cx - 6, cy)]
        if k < pips:
            draw.polygon(diamond, fill=SPECTRA6[fill], outline=SPECTRA6[outline])
        else:
            draw.line(diamond + [diamond[0]], fill=yellow, width=1)
    draw_tracked(draw, (_HADES_TITLE_X + 5 * 16 + 8, y + 2), label, _hades_label_font(12), white, tracking=3)
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "").strip()
    if title:
        font, text = fit_text_to_width(draw, title, [SPECTRALSC_MEDIUM, SPECTRAL_MEDIUM, *META_FONT_CANDIDATES],
                                       15, _HADES_TITLE_RIGHT - _HADES_TITLE_X - 200, floor=12, tracking=1)
        draw_tracked(draw, (_HADES_TITLE_RIGHT, y + 1), text, font, white, tracking=1, anchor_right=True)


def render_hades_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A boon at the Crossroads under the moon (see the section comment above)."""
    hour = _clock_hour12(time_str)
    image = _hades_scene().copy()
    draw = ImageDraw.Draw(image)
    _hades_paint_moon(image, hour)
    _hades_paint_title(image, draw, quote_row)
    _hades_paint_quote(image, draw, quote_row)
    _hades_paint_foot(image, draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image

# ---------------------------------------------------------------------------
# beksinski — Zdzisław Beksiński's fantastic period (c. 1964–1983): a
# procession across a dead plain toward a cathedral of bone
# ---------------------------------------------------------------------------
# A plain under a dust-coloured haze with a dim sun, a cathedral of bone grown
# on the horizon (spires, pointed openings, tendons into the ground), and
# hooded figures walking toward it. The quote is set in the haze.
#
# **The procession is the hour**: one figure per hour, led from the
# cathedral's foot back along the road, so the file grows and the leader never
# moves. Hour-only, pinned byte-identical across the minutes of an hour by
# ``TestBeksinskiFrame``. Each black figure has a 1 px bone-white edge toward
# the cathedral, which with the pale road keeps it legible on the dark plain.
#
# **Sky and plain are painted in continuous tone and dithered** against the
# calibrated inks (the ``expedition`` posture): umber-to-ochre gradient,
# scraped-oil noise, the sun's glow behind the spires, a vignette. **No green
# and no blue**: with green admitted the umber quantises to red-and-green
# confetti. The plain is lighter at the horizon (atmospheric perspective).
#
# **The cathedral** is an ``L`` mask: a mound, six ragged spires with a bulge
# so they read as bone rather than cones, pinnacles, tendon buttresses, and
# windows and an oculus knocked through. It is painted before the dither as a
# grained near-black body with a rust **rim light** (mask minus itself offset
# down-right). A far ruin on the left horizon makes the plain wide. After the
# dither ``paint_craquelure`` crazes the plain and the bone (not the sky),
# keeping the byline clear.
#
# **Type**: Old Standard TT, the Didone of 20th-century Central European book
# printing (Beksiński set no type): Regular body, Bold matched phrase in solid
# red, bone-white byline.
#
# The scene is quote- and hour-independent and painted once per process
# (``_BEKSINSKI_SCENE``, keyed on the painters). Composed at 800x480 and
# NEAREST-downsampled (the ``metro`` convention).
# ---------------------------------------------------------------------------
_BEKSINSKI_SEED = 0x5A42               # ZB
_BEKSINSKI_HORIZON = 318
_BEKSINSKI_QUOTE_RECT = (46, 42, 490, 266)
_BEKSINSKI_BYLINE_XY = (46, 444)
_BEKSINSKI_BYLINE_WIDTH = 420
_BEKSINSKI_SUN = (584, 126, 34)        # centre x, centre y, radius
_BEKSINSKI_TOWER = (548, 762)          # the cathedral's footprint on the horizon
_BEKSINSKI_ROAD = ((112, 430), (496, 354))   # near end .. far end of the road
_BEKSINSKI_RUIN_X = (74, 108, 150)     # the far ruin's spires, on the left horizon
_BEKSINSKI_SKY_INKS = ("black", "red", "yellow", "white")
_BEKSINSKI_GROUND_INKS = ("black", "red", "yellow", "white")
# Haze, zenith to horizon, in the calibrated space: smoky umber to a
# bone-ochre glow. Then the plain, hazed at its far edge and falling to
# near-black at the foot.
_BEKSINSKI_SKY_STOPS = (
    (0, (112, 98, 80)), (110, (142, 128, 96)), (230, (168, 156, 112)),
    (_BEKSINSKI_HORIZON, (184, 172, 124)),
)
_BEKSINSKI_GROUND_STOPS = (
    (_BEKSINSKI_HORIZON, (132, 112, 84)), (_BEKSINSKI_HORIZON + 26, (82, 58, 42)),
    (390, (54, 38, 32)), (480, (30, 26, 24)),
)
_BEKSINSKI_SUN_GLOW = (214, 206, 166)
_BEKSINSKI_SUN_DISC = (206, 198, 154)
_BEKSINSKI_ROAD_TONE = (104, 88, 72)
_BEKSINSKI_RUIN_TONE = (128, 112, 88)
_BEKSINSKI_BODY = (38, 31, 29)
_BEKSINSKI_RIM = (128, 68, 36)
_BEKSINSKI_ROOT = (24, 20, 20)
# (centre x offset from the footprint's left edge, height, base width, lean)
_BEKSINSKI_SPIRES = (
    (22, 150, 40, -0.02), (58, 236, 52, -0.01), (100, 296, 60, 0.0),
    (142, 254, 54, 0.015), (180, 196, 44, 0.03), (206, 128, 34, 0.05),
)
_BEKSINSKI_SCENE: dict = {}


def _beksinski_spindle(rng: random.Random, cx: float, base: float, h: float, w: float,
                       lean: float = 0.0) -> list[tuple[float, float]]:
    """A tapering spire with ragged edges and a bulge along its length — a
    bone, not a cone — as a polygon."""
    left, right = [], []
    steps = max(6, int(h) // 14)
    for i in range(steps + 1):
        t = i / steps
        y = base - h * t
        half = (w * 0.5 * (1 - t) ** 0.72 + 1.5) * (1 + 0.12 * math.sin(t * math.pi * 3.1 + cx))
        x = cx + lean * h * t
        left.append((x - half + rng.uniform(-2.5, 2.5), y))
        right.append((x + half + rng.uniform(-2.5, 2.5), y))
    return left + right[::-1]


def _beksinski_arch(cx: float, y_bottom: float, w: float, h: float) -> list[tuple[float, float]]:
    """A pointed arch, apex up, as a polygon."""
    half = w / 2
    return [(cx - half, y_bottom), (cx - half, y_bottom - h + half), (cx, y_bottom - h),
            (cx + half, y_bottom - h + half), (cx + half, y_bottom)]


def _beksinski_tower_mask(size: tuple[int, int]) -> Image.Image:
    """The cathedral as an ``L`` mask: mound, spires, pinnacles, buttresses,
    with the windows and the oculus knocked through."""
    mask = Image.new("L", size, 0)
    md = ImageDraw.Draw(mask)
    rng = random.Random(_BEKSINSKI_SEED + 3)
    base = _BEKSINSKI_HORIZON + 4
    x0, x1 = _BEKSINSKI_TOWER
    md.polygon([(x0 - 30, base), (x0 - 10, base - 40), (x0 + 30, base - 70), ((x0 + x1) // 2, base - 92),
                (x1 - 40, base - 70), (x1 + 2, base - 36), (x1 + 24, base)], fill=255)
    spires = [(x0 + dx, h, w, lean) for dx, h, w, lean in _BEKSINSKI_SPIRES]
    for cx, h, w, lean in spires:
        md.polygon(_beksinski_spindle(rng, cx, base, h, w, lean), fill=255)
        for _ in range(rng.randint(2, 4)):
            dx = rng.uniform(-w * 0.55, w * 0.55)
            md.polygon(_beksinski_spindle(rng, cx + dx, base - h * rng.uniform(0.25, 0.55),
                                          h * rng.uniform(0.18, 0.34), w * 0.3), fill=255)
    # Buttresses: tendons from the body down into the plain on both flanks,
    # thickening as they land.
    for sx, sy, ex, ey, w in ((x0 + 10, base - 120, x0 - 56, base + 2, 9),
                              (x0 + 40, base - 200, x0 - 22, base + 2, 7),
                              (x1 - 20, base - 100, x1 + 44, base + 2, 8),
                              (x1 - 60, base - 170, x1 + 16, base + 2, 6)):
        pts = []
        for i in range(9):
            t = i / 8
            pts.append((sx + (ex - sx) * t * t, sy + (ey - sy) * (1 - (1 - t) ** 2), w * (0.5 + t)))
        for (ax, ay, aw), (bx, by, _) in zip(pts, pts[1:]):
            md.line([(ax, ay), (bx, by)], fill=255, width=int(aw))
    # Windows: pointed arches through each spire, the haze showing through.
    for cx, h, w, lean in spires:
        for k in range(max(1, int(h // 70))):
            y = base - 30 - k * (h * 0.26)
            ww = max(5, int(w * 0.22 * (1 - k * 0.18)))
            x = cx + lean * (base - y) + rng.uniform(-2, 2)
            md.polygon(_beksinski_arch(x, y, ww, int(ww * 2.6)), fill=0)
    cx = spires[2][0]
    oy = base - 150
    md.ellipse((cx - 13, oy - 13, cx + 13, oy + 13), fill=0)
    md.ellipse((cx - 5, oy - 5, cx + 5, oy + 5), fill=255)
    return mask


def _beksinski_paint_sky(scene: Image.Image) -> None:
    """The haze and the plain in continuous tone: the gradients, the scraped
    facture, the sun behind the haze, the road, the far ruin, the vignette."""
    width, height = scene.size
    hz = _BEKSINSKI_HORIZON
    column = Image.new("RGB", (1, height))
    cp = column.load()
    for y in range(height):
        cp[0, y] = _lerp_stops(_BEKSINSKI_SKY_STOPS if y < hz else _BEKSINSKI_GROUND_STOPS, y)
    scene.paste(column.resize((width, height), Image.Resampling.NEAREST), (0, 0))
    # Scraped-oil facture: a horizontal streak and a broad smudge, both
    # centred on zero so the gradient's stops stay where they were set.
    streak = _smooth_noise((width, height), (48, 18), _BEKSINSKI_SEED + 1).point(lambda v: v // 10)
    smudge = _smooth_noise((width, height), (7, 5), _BEKSINSKI_SEED + 2).point(lambda v: v // 12)
    grain = ImageChops.add(streak, smudge)
    tint = Image.merge("RGB", (grain, grain, grain))
    scene.paste(ImageChops.subtract(ImageChops.add(scene, tint), Image.new("RGB", scene.size, (23, 23, 23))))
    # The sun: a pale disc behind the haze, its glow pooled round it. It sits
    # behind the left spires, so the cathedral is seen against the light.
    sx, sy, sr = _BEKSINSKI_SUN
    halo = Image.new("L", scene.size, 0)
    ImageDraw.Draw(halo).ellipse((sx - sr * 2.4, sy - sr * 2.4, sx + sr * 2.4, sy + sr * 2.4), fill=255)
    halo = halo.filter(ImageFilter.GaussianBlur(34)).point(lambda v: int(v * 0.34))
    scene.paste(Image.new("RGB", scene.size, _BEKSINSKI_SUN_GLOW), (0, 0), halo)
    disc = Image.new("L", scene.size, 0)
    ImageDraw.Draw(disc).ellipse((sx - sr, sy - sr, sx + sr, sy + sr), fill=255)
    disc = disc.filter(ImageFilter.GaussianBlur(3)).point(lambda v: int(v * 0.7))
    scene.paste(Image.new("RGB", scene.size, _BEKSINSKI_SUN_DISC), (0, 0), disc)
    # A ruin far off on the left horizon, in the haze's own colour: three
    # spires of the same construction, which is what makes the plain wide.
    rng = random.Random(_BEKSINSKI_SEED + 9)
    ruin = Image.new("L", scene.size, 0)
    rd = ImageDraw.Draw(ruin)
    for rx, h, w in zip(_BEKSINSKI_RUIN_X, (34, 58, 42), (14, 20, 16)):
        rd.polygon(_beksinski_spindle(rng, rx, hz + 1, h, w), fill=255)
    scene.paste(Image.new("RGB", scene.size, _BEKSINSKI_RUIN_TONE), (0, 0), ruin)
    # The road: a pale ash track across the plain, wider as it nears.
    (nx, ny), (fx, fy) = _BEKSINSKI_ROAD
    road = Image.new("L", scene.size, 0)
    ImageDraw.Draw(road).polygon([(nx - 70, ny + 16), (fx - 10, fy - 4), (fx + 30, fy - 2),
                                  (nx + 90, ny + 30), (nx - 10, ny + 34)], fill=255)
    road = road.filter(ImageFilter.GaussianBlur(9)).point(lambda v: int(v * 0.75))
    scene.paste(Image.new("RGB", scene.size, _BEKSINSKI_ROAD_TONE), (0, 0), road)
    # A vignette: the edges fall into the dark, the way the oils do.
    vignette = Image.new("L", scene.size, 0)
    ImageDraw.Draw(vignette).ellipse((-120, -90, width + 120, height + 90), fill=255)
    vignette = vignette.filter(ImageFilter.GaussianBlur(70)).point(lambda v: 180 + v * 75 // 255)
    scene.paste(Image.composite(scene, Image.new("RGB", scene.size, (0, 0, 0)), vignette))


def _beksinski_paint_tower(scene: Image.Image, mask: Image.Image) -> None:
    """The cathedral in continuous tone: a dark grained body on ``mask``, a
    rust rim light on the faces toward the sun, roots into the plain."""
    body = Image.new("RGB", scene.size, _BEKSINSKI_BODY)
    grain = _smooth_noise(scene.size, (20, 40), _BEKSINSKI_SEED + 4).point(lambda v: v // 9)
    scene.paste(ImageChops.add(body, Image.merge("RGB", (grain, grain, grain))), (0, 0), mask)
    rim = ImageChops.subtract(mask, ImageChops.offset(mask, 3, 2)).filter(ImageFilter.GaussianBlur(1.2))
    rim = ImageChops.multiply(rim, mask).point(lambda v: min(255, v * 2))
    scene.paste(Image.new("RGB", scene.size, _BEKSINSKI_RIM), (0, 0), rim)
    draw = ImageDraw.Draw(scene)
    rng = random.Random(_BEKSINSKI_SEED + 5)
    x0, x1 = _BEKSINSKI_TOWER
    for _ in range(10):
        x = rng.uniform(x0 - 10, x1 + 20)
        length = rng.uniform(24, 84)
        pts = [(x, _BEKSINSKI_HORIZON)]
        for i in range(1, 6):
            x += rng.uniform(-9, 9)
            pts.append((x, _BEKSINSKI_HORIZON + length * i / 5))
        for (ax, ay), (bx, by) in zip(pts, pts[1:]):
            width = max(1, int(5 - 4 * (ay - _BEKSINSKI_HORIZON) / length))
            draw.line([(ax, ay), (bx, by)], fill=_BEKSINSKI_ROOT, width=width)


def _beksinski_scene() -> Image.Image:
    """The painting without its figures: haze, sun, ruin, cathedral, plain,
    craquelure. Painted once per process."""
    key = (_beksinski_paint_sky, _beksinski_paint_tower)
    cached = _BEKSINSKI_SCENE.get("frame")
    if cached is not None and cached[0] == key:
        return cached[1]
    size = (800, 480)
    scene = Image.new("RGB", size, _PANEL_INKS["black"])
    _beksinski_paint_sky(scene)
    tower = _beksinski_tower_mask(size)
    _beksinski_paint_tower(scene, tower)
    sky = _dither_calibrated(scene, _BEKSINSKI_SKY_INKS)
    ground = _dither_calibrated(scene, _BEKSINSKI_GROUND_INKS)
    # The plain and the bone are one surface for the craquelure; the sky is
    # not crazed, and the byline's footprint is kept out of the net.
    surface = Image.new("L", size, 0)
    ImageDraw.Draw(surface).rectangle((0, _BEKSINSKI_HORIZON, size[0], size[1]), fill=255)
    surface = ImageChops.lighter(surface, tower)
    image = Image.composite(ground, sky, surface)
    keep = Image.new("L", size, 0)
    bx, by = _BEKSINSKI_BYLINE_XY
    ImageDraw.Draw(keep).rectangle((bx - 4, by - 2, bx + _BEKSINSKI_BYLINE_WIDTH + 20, by + 24), fill=255)
    paint_craquelure(image, surface, seed=_BEKSINSKI_SEED + 6, cell=(26, 16), jitter=0.4, drop=0.25,
                     dark=SPECTRA6["black"], light=SPECTRA6["white"], light_share=0.16, keep_out=keep)
    _BEKSINSKI_SCENE["frame"] = (key, image)
    return image


def _beksinski_figure(cx: float, cy: float, h: float, lean: float) -> list[tuple[float, float]]:
    """A hooded, stooped walker standing on ``(cx, cy)``, ``h`` tall, leaning
    ``lean`` of its height toward the cathedral, with a ragged hem."""
    hw, sw, bw = h * 0.11, h * 0.16, h * 0.22
    top = cy - h
    lx = lean * h
    hem = [(cx + bw * (-1 + 2 * i / 6), cy - (3 if i % 2 else 0) * (h / 40)) for i in range(7)]
    return ([(cx + lx, top), (cx + lx + hw, top + h * 0.14), (cx + lx * 0.7 + sw, top + h * 0.36),
             (cx + lx * 0.3 + sw * 0.9, top + h * 0.62), (cx + bw, cy)]
            + hem[::-1][1:-1]
            + [(cx - bw, cy), (cx + lx * 0.3 - sw * 0.9, top + h * 0.62), (cx + lx * 0.7 - sw, top + h * 0.36),
               (cx + lx - hw, top + h * 0.14)])


def _beksinski_paint_figures(image: Image.Image, hour: int) -> None:
    """The procession: one figure per hour, led from the cathedral's foot
    back along the road, so the file grows through the day."""
    draw = ImageDraw.Draw(image)
    black, white = SPECTRA6["black"], SPECTRA6["white"]
    rng = random.Random(_BEKSINSKI_SEED + 7)
    (nx, ny), (fx, fy) = _BEKSINSKI_ROAD
    # Every figure's jitter is drawn whether or not it walks today, so the
    # ones that do stand where they always stand.
    walk = [(rng.uniform(-0.012, 0.012), rng.uniform(-5, 5), rng.uniform(0.02, 0.1), rng.uniform(0.8, 1.0))
            for _ in range(12)]
    for k in range(hour):
        jt, jy, lean, stoop = walk[k]
        t = 1 - k / 12 - 0.03 + jt
        cx = nx + (fx - nx) * t
        cy = ny + (fy - ny) * t + jy * (1 - t)
        h = (58 - 32 * t) * stoop
        body = _beksinski_figure(cx, cy, h, lean)
        draw.polygon(body, fill=black)
        if h > 30:
            draw.line([(cx + lean * h + h * 0.18, cy - h * 0.7), (cx + h * 0.21, cy + 2)], fill=black, width=1)
        # The glow catches the edge toward the cathedral: a bone-white line.
        draw.line(body[1:4], fill=white, width=1)


def _beksinski_paint_quote(draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The quote in the haze: black Old Standard, ragged right, the matched
    phrase Bold in solid red."""
    placed = _place_quote(draw, quote_row, _BEKSINSKI_QUOTE_RECT, theme="beksinski",
                          font_max=32, font_min=15, line_height_mult=1.3)
    _paint_placed(draw, placed, SPECTRA6["black"], SPECTRA6["red"])


def _beksinski_paint_byline(draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """Author and title in bone-white on the plain at the foot."""
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "")
    text = " — ".join(part for part in (author, title) if part)
    if not text:
        return
    font, text = fit_text_to_width(draw, text, [OLDSTANDARD_REGULAR, *META_FONT_CANDIDATES], 17,
                                   _BEKSINSKI_BYLINE_WIDTH, floor=13)
    draw.text(_BEKSINSKI_BYLINE_XY, text, font=font, fill=SPECTRA6["white"])


def render_beksinski_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A procession toward a cathedral of bone (see the section comment above)."""
    hour = _clock_hour12(time_str)
    image = _beksinski_scene().copy()
    draw = ImageDraw.Draw(image)
    _beksinski_paint_figures(image, hour)
    _beksinski_paint_quote(draw, quote_row)
    _beksinski_paint_byline(draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image



# ---------------------------------------------------------------------------
# expanse — *The Expanse* (2015–2022): the Rocinante's console
# ---------------------------------------------------------------------------
# One of the Rocinante's displays: dense modules on dark glass (a system plot
# with station column heads, arc gauges, status pills, a framed feed, a boxed
# contact list, waveform charts, and tiny ``//`` system text under each
# module). The quote is the feed: an incoming tightbeam.
#
# **The hour is a bearing.** The tracked contact sits on the plot's outer ring
# at the hour's clock-face position ("contact, two o'clock"), with a dashed
# blue flyby track and a dashed orange intercept from the Roci, and its list
# row reads the bearing in degrees (``BRG 060``). Hour-only, pinned
# byte-identical across the minutes of an hour by ``TestExpanseFrame``.
#
# **Colour.** MCRN orange is an R+Y 50/50 stipple (a red-biased tangerine goes
# dim on black) for the matched phrase, sender, header leads and lit pills;
# gauge sweeps and chart fills are a B+W checker (the console's cyan);
# hairlines are solid blue, since a hairline cannot carry a stipple, and never
# red, which is a shade off black on the panel. Pills and bars are green for
# nominal, red for armed or empty; running text is white.
#
# **Type**: Barlow (nearest open face to the show's modified DIN Pro) for the
# body, matched phrase and sender; Barlow Condensed for labels; Share Tech
# Mono for readouts, system text and the command line.
#
# **The ship's state is the quote's**: ``_row_digest`` deals the gauges,
# pills, waveform, signal bars and transmission ID. Nothing prints a digit the
# time could be read from.
#
# The chrome is quote- and hour-independent and painted once per process
# (``_EXPANSE_SCENE``, keyed on the painters). Composed at 800x480 and
# NEAREST-downsampled (the ``metro`` convention).
# ---------------------------------------------------------------------------
_EXPANSE_SEED = 0x524F4349            # ROCI
_EXPANSE_GRID_PITCH = 23              # coprime with the 4x4 / 8x8 Bayer tiles
_EXPANSE_TAG_RECT = (24, 8, 150, 54)
_EXPANSE_ORBIT_RECT = (164, 8, 776, 54)
_EXPANSE_ORBIT_STATIONS = ("LUNA", "MARS", "CERES", "TYCHO", "GANYMEDE", "SATURN")
_EXPANSE_PLOT_RECT = (24, 64, 232, 392)
_EXPANSE_PLOT_CENTRE = (128, 196)
_EXPANSE_PLOT_RINGS = (28, 56, 84)
_EXPANSE_CONTACT_RADIUS = 70
_EXPANSE_STATIC_CONTACTS = ((40, 215), (38, 318))   # (radius, bearing) of the unknowns
_EXPANSE_ARC_GAUGE_Y = 340
_EXPANSE_ARC_GAUGE_XS = (56, 104, 152, 200)
_EXPANSE_ARC_GAUGE_R = 15
_EXPANSE_ARC_GAUGES = ("RCS", "PWR", "O2", "TMP")
_EXPANSE_FEED_RECT = (244, 64, 652, 392)
_EXPANSE_HEADER_H = 24
_EXPANSE_SENDER_Y = 98
_EXPANSE_QUOTE_RECT = (268, 134, 628, 324)
_EXPANSE_FRAME_RECT = (258, 126, 638, 332)         # the feed's own thin frame round the quote
_EXPANSE_SOURCE_Y = 344
_EXPANSE_PROMPT_Y = 370
_EXPANSE_LIST_RECT = (664, 64, 776, 392)
_EXPANSE_LIST_ROW_Y = 96
_EXPANSE_LIST_ROW_H = 46
_EXPANSE_LIST_ROWS = ("ROCINANTE", "CONTACT", "UNK 01", "UNK 02")
_EXPANSE_SCATTER_RECT = (676, 290, 764, 360)
_EXPANSE_FOOT_RECT = (24, 402, 776, 472)
_EXPANSE_PILL_ROWS = ("PDC", "TORP", "RCS", "EPS")
_EXPANSE_CHART_RECT = (236, 414, 556, 462)
_EXPANSE_SYSTEXT_X = 574
_EXPANSE_CHAMFER = 12
_EXPANSE_SCENE: dict = {}


def _expanse_bearing(hour: int) -> int:
    """The contact's bearing in degrees clockwise from north: twelve is 000."""
    return (hour % 12) * 30


def _expanse_polar(radius: float, bearing_deg: float) -> tuple[float, float]:
    """A point on the plot at ``radius`` and a bearing clockwise from north."""
    cx, cy = _EXPANSE_PLOT_CENTRE
    a = math.radians(bearing_deg)
    return cx + radius * math.sin(a), cy - radius * math.cos(a)


def _expanse_label_font(size: int):
    """Barlow Condensed Medium — the tracked DIN-style labels."""
    return load_font([BARLOWCOND_MEDIUM, BARLOW_MEDIUM, *META_FONT_CANDIDATES], size=size)


def _expanse_label_bold_font(size: int):
    """Barlow Condensed SemiBold — the module headers."""
    return load_font([BARLOWCOND_SEMIBOLD, BARLOW_SEMIBOLD, *META_FONT_BOLD_CANDIDATES], size=size)


def _expanse_mono_font(size: int):
    """Share Tech Mono — the readouts, the system text and the command line."""
    return load_font([SHARETECHMONO_REGULAR, SPACEMONO_REGULAR, *META_FONT_CANDIDATES], size=size)


def _expanse_chamfered(rect, cut: int, corners=("tr", "bl")) -> list:
    """A rectangle's outline, clockwise from the top left, with the named
    corners cut at 45 degrees — the console's panel shape."""
    x0, y0, x1, y1 = rect
    pts: list = []
    pts += [(x0, y0 + cut), (x0 + cut, y0)] if "tl" in corners else [(x0, y0)]
    pts += [(x1 - cut, y0), (x1, y0 + cut)] if "tr" in corners else [(x1, y0)]
    pts += [(x1, y1 - cut), (x1 - cut, y1)] if "br" in corners else [(x1, y1)]
    pts += [(x0 + cut, y1), (x0, y1 - cut)] if "bl" in corners else [(x0, y1)]
    return pts


def _expanse_paint_bracket(draw: ImageDraw.ImageDraw, x: int, y: int, dx: int, dy: int, ink, length: int = 14,
                           width: int = 2) -> None:
    """An L-shaped corner bracket at ``(x, y)`` opening toward ``(dx, dy)``."""
    draw.line([(x, y), (x + dx * length, y)], fill=ink, width=width)
    draw.line([(x, y), (x, y + dy * length)], fill=ink, width=width)


def _expanse_paint_brackets(draw: ImageDraw.ImageDraw, rect, ink, length: int = 10, width: int = 1) -> None:
    """Brackets on all four corners of ``rect`` — the feed's frame."""
    x0, y0, x1, y1 = rect
    for cx, cy, dx, dy in ((x0, y0, 1, 1), (x1, y0, -1, 1), (x1, y1, -1, -1), (x0, y1, 1, -1)):
        _expanse_paint_bracket(draw, cx, cy, dx, dy, ink, length=length, width=width)


def _expanse_dashed(draw: ImageDraw.ImageDraw, points: list, ink, on: int = 6, off: int = 5, width: int = 1) -> None:
    """A polyline drawn as dashes, the dash phase carried across vertices."""
    run, lit = 0.0, True
    for (ax, ay), (bx, by) in zip(points, points[1:]):
        seg = math.hypot(bx - ax, by - ay)
        t = 0.0
        while t < seg:
            step = min(seg - t, (on if lit else off) - run)
            if lit:
                draw.line([(ax + (bx - ax) * t / seg, ay + (by - ay) * t / seg),
                           (ax + (bx - ax) * (t + step) / seg, ay + (by - ay) * (t + step) / seg)],
                          fill=ink, width=width)
            t += step
            run += step
            if run >= (on if lit else off) - 1e-6:
                run, lit = 0.0, not lit


def _expanse_dotted_rule(px, x0: int, x1: int, y: int, ink, pitch: int = 3) -> None:
    """A dotted horizontal leader — the baseline under every readout."""
    for x in range(x0, x1, pitch):
        px[x, y] = ink


def _expanse_paint_amber_rect(image: Image.Image, rect) -> None:
    """The MCRN orange as a block: red + yellow at 1/2 : 1/2."""
    _fill_swatch_stipple(image, rect, SPECTRA6["red"], SPECTRA6["yellow"], 0.5)


def _expanse_paint_cyan_rect(image: Image.Image, rect) -> None:
    """The console's cyan as a block: blue + white at 1/2 : 1/2."""
    _fill_swatch_stipple(image, rect, SPECTRA6["blue"], SPECTRA6["white"], 0.5)


def _expanse_paint_pill(image: Image.Image, draw: ImageDraw.ImageDraw, rect, ink: str) -> None:
    """A status pill: a small rounded cell filled solid (green / red /
    white), stippled amber, or left as a blue hairline when dark."""
    x0, y0, x1, y1 = rect
    if ink == "amber":
        draw.rounded_rectangle(rect, radius=2, fill=SPECTRA6["black"])
        _expanse_paint_amber_rect(image, (x0 + 1, y0 + 1, x1, y1))
    elif ink == "dark":
        draw.rounded_rectangle(rect, radius=2, outline=SPECTRA6["blue"], width=1)
    else:
        draw.rounded_rectangle(rect, radius=2, fill=SPECTRA6[ink])


def _expanse_paint_systext(draw: ImageDraw.ImageDraw, x: int, y: int, lines, ink=None, size: int = 9) -> int:
    """A few lines of the console's ``//`` system text in the mono — the
    under-the-hood register every module on the Roci carries. Returns the
    y below the block."""
    font = _expanse_mono_font(size)
    for line in lines:
        draw.text((x, y), line, font=font, fill=ink or SPECTRA6["white"])
        y += size + 3
    return y


def _expanse_paint_ground(image: Image.Image) -> None:
    """Black glass with a sparse blue dot grid, so the panels sit on a
    surface rather than in a void."""
    px = image.load()
    blue = SPECTRA6["blue"]
    w, h = image.size
    for y in range(6, h, _EXPANSE_GRID_PITCH):
        for x in range(6, w, _EXPANSE_GRID_PITCH):
            px[x, y] = blue


def _expanse_paint_tag(image: Image.Image) -> None:
    """The ship's tag at the top left: the service as an orange block, the
    name beneath it, the class under that."""
    draw = ImageDraw.Draw(image)
    black, white = SPECTRA6["black"], SPECTRA6["white"]
    x0, y0, x1, y1 = _EXPANSE_TAG_RECT
    draw.rectangle((x0, y0, x0 + 46, y0 + 16), fill=black)
    _expanse_paint_amber_rect(image, (x0, y0, x0 + 46, y0 + 16))
    tag = _expanse_label_bold_font(12)
    draw_tracked(draw, (x0 + (46 - tracked_width(draw, "MCRN", tag, tracking=2)) / 2, y0 + 2), "MCRN", tag, black, tracking=2)
    name = load_font([BARLOW_SEMIBOLD, BARLOWCOND_SEMIBOLD, *META_FONT_BOLD_CANDIDATES], size=15)
    draw_tracked(draw, (x0, y0 + 20), "ROCINANTE", name, white, tracking=2)
    draw_tracked(draw, (x0, y0 + 38), "CORVETTE-CLASS", _expanse_label_font(10), white, tracking=2)
    draw.line([(x1, y0), (x1, y1)], fill=SPECTRA6["blue"], width=1)


def _expanse_paint_orbit(image: Image.Image) -> None:
    """The system plot across the top: the stations as column heads over
    vertical rules, two trajectories curving through them, a banded gas
    giant, a ringed one and a moon."""
    draw = ImageDraw.Draw(image)
    px = image.load()
    white, blue, yellow, red = SPECTRA6["white"], SPECTRA6["blue"], SPECTRA6["yellow"], SPECTRA6["red"]
    x0, y0, x1, y1 = _EXPANSE_ORBIT_RECT
    draw.line([(x0, y1), (x1, y1)], fill=blue, width=1)
    _expanse_dotted_rule(px, x0, x1, y0, blue, pitch=2)
    n = len(_EXPANSE_ORBIT_STATIONS)
    pitch = (x1 - x0) / n
    font = _expanse_label_font(10)
    for k, station in enumerate(_EXPANSE_ORBIT_STATIONS):
        sx = int(x0 + k * pitch)
        draw.line([(sx, y0 + 2), (sx, y1 - 2)], fill=blue, width=1)
        draw_tracked(draw, (sx + 5, y0 + 2), station, font, white, tracking=1)

    def bezier(p0, p1, p2, steps: int = 60) -> list:
        return [((1 - t) ** 2 * p0[0] + 2 * (1 - t) * t * p1[0] + t * t * p2[0],
                 (1 - t) ** 2 * p0[1] + 2 * (1 - t) * t * p1[1] + t * t * p2[1])
                for t in (i / steps for i in range(steps + 1))]

    _expanse_dashed(draw, bezier((x0 + 6, y1 - 6), (x0 + 300, y0 + 2), (x1 - 8, y1 - 16)), blue, on=5, off=4)
    draw.line(bezier((x0 + 30, y0 + 10), (x0 + 330, y1 + 10), (x1 - 40, y0 + 12)), fill=yellow, width=1)
    # A banded gas giant at Ganymede's column, with the Roci's ship marker beside it.
    gx, gy, gr = int(x0 + 4.5 * pitch), y0 + 28, 11
    disc = Image.new("L", image.size, 0)
    ImageDraw.Draw(disc).ellipse((gx - gr, gy - gr, gx + gr, gy + gr), fill=255)
    _expanse_paint_stipple_masked(image, disc, SPECTRA6["red"], SPECTRA6["yellow"])
    disc.close()
    for band in (-6, -2, 3, 7):
        draw.line([(gx - gr + 2, gy + band), (gx + gr - 2, gy + band)], fill=red, width=1)
    draw.polygon([(gx + gr + 10, gy - 4), (gx + gr + 16, gy), (gx + gr + 10, gy + 4)], fill=white)
    # A ringed planet at Saturn's column.
    sx, sy, sr = int(x0 + 5.5 * pitch), y0 + 24, 6
    draw.ellipse((sx - sr, sy - sr, sx + sr, sy + sr), fill=white)
    draw.ellipse((sx - 13, sy - 4, sx + 13, sy + 4), outline=yellow, width=1)
    draw.ellipse((sx - sr, sy - sr, sx + sr, sy + sr), outline=white, width=1)
    # A moon at Mars's column, and Ceres as a fleck.
    mx, my = int(x0 + 1.5 * pitch), y1 - 14
    draw.ellipse((mx - 3, my - 3, mx + 3, my + 3), fill=white)
    draw.rectangle((int(x0 + 2.5 * pitch), y0 + 22, int(x0 + 2.5 * pitch) + 1, y0 + 23), fill=white)


def _expanse_paint_panel(image: Image.Image, rect, title: str, *, corners=("tr", "bl"), header: bool = True,
                         sub: str = "") -> None:
    """A console panel: black glass in a chamfered blue hairline, yellow
    brackets on the square corners, and a header strip with its title and
    an optional subtitle at the right."""
    draw = ImageDraw.Draw(image)
    black, blue, yellow, white = SPECTRA6["black"], SPECTRA6["blue"], SPECTRA6["yellow"], SPECTRA6["white"]
    x0, y0, x1, y1 = rect
    outline = _expanse_chamfered(rect, _EXPANSE_CHAMFER, corners)
    draw.polygon(outline, fill=black)
    draw.line(outline + [outline[0]], fill=blue, width=1)
    for cx, cy, dx, dy, name in ((x0, y0, 1, 1, "tl"), (x1, y0, -1, 1, "tr"), (x1, y1, -1, -1, "br"), (x0, y1, 1, -1, "bl")):
        if name not in corners:
            _expanse_paint_bracket(draw, cx, cy, dx, dy, yellow)
    if header:
        hy = y0 + _EXPANSE_HEADER_H
        draw.line([(x0, hy), (x1, hy)], fill=blue, width=1)
        font = _expanse_label_bold_font(13)
        _expanse_paint_amber_rect(image, (x0 + 1, y0 + 1, x0 + 8, hy - 1))
        draw_tracked(draw, (x0 + 16, y0 + 6), title, font, white, tracking=3)
        if sub:
            draw_tracked(draw, (x1 - 10, y0 + 7), sub, _expanse_label_font(11), white, tracking=2, anchor_right=True)


def _expanse_paint_plot(image: Image.Image) -> None:
    """The tactical plot: range rings as arcs gapped at the cardinals,
    bearing ticks, a gapped crosshair, the Roci as a white chevron at the
    centre, two unknowns as hollow blue triangles, a tick ruler down the
    panel's left edge, and the rings of the four arc gauges beneath."""
    draw = ImageDraw.Draw(image)
    px = image.load()
    blue, white = SPECTRA6["blue"], SPECTRA6["white"]
    cx, cy = _EXPANSE_PLOT_CENTRE
    for r in _EXPANSE_PLOT_RINGS:
        for quadrant in range(4):
            start = quadrant * 90 - 90 + 5
            draw.arc((cx - r, cy - r, cx + r, cy + r), start, start + 80, fill=blue, width=1)
    outer = _EXPANSE_PLOT_RINGS[-1]
    for k in range(36):
        length = 6 if k % 3 == 0 else 3
        (ax, ay), (bx, by) = _expanse_polar(outer + 2, k * 10), _expanse_polar(outer + 2 + length, k * 10)
        draw.line([(ax, ay), (bx, by)], fill=blue if k % 3 else white, width=1)
    font = _expanse_mono_font(10)
    for bearing, text in ((0, "000"), (90, "090"), (180, "180"), (270, "270")):
        tx, ty = _expanse_polar(outer + 15, bearing)
        draw.text((tx, ty), text, font=font, fill=white, anchor="mm")
    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        draw.line([(cx + dx * 8, cy + dy * 8), (cx + dx * (outer - 6), cy + dy * (outer - 6))], fill=blue, width=1)
    draw.polygon([(cx, cy - 6), (cx + 5, cy + 5), (cx, cy + 2), (cx - 5, cy + 5)], fill=white)
    for radius, bearing in _EXPANSE_STATIC_CONTACTS:
        px_, py_ = _expanse_polar(radius, bearing)
        draw.polygon([(px_, py_ - 5), (px_ + 5, py_ + 4), (px_ - 5, py_ + 4)], outline=blue, width=1)
    x0, y0, x1, y1 = _EXPANSE_PLOT_RECT
    # The ruler down the left edge, inside the frame.
    for y in range(y0 + _EXPANSE_HEADER_H + 8, _EXPANSE_ARC_GAUGE_Y - 30, 6):
        tick = 5 if (y - y0) % 30 == 2 else 2
        draw.line([(x0 + 3, y), (x0 + 3 + tick, y)], fill=blue if tick == 2 else white, width=1)
    # The arc gauges' outer rings and labels; the sweeps are the quote's.
    r = _EXPANSE_ARC_GAUGE_R
    _expanse_dotted_rule(px, x0 + 10, x1 - 10, _EXPANSE_ARC_GAUGE_Y - r - 10, blue)
    label = _expanse_label_font(9)
    for gx, name in zip(_EXPANSE_ARC_GAUGE_XS, _EXPANSE_ARC_GAUGES):
        gy = _EXPANSE_ARC_GAUGE_Y
        draw.arc((gx - r, gy - r, gx + r, gy + r), 135, 405, fill=blue, width=1)
        draw.arc((gx - r + 9, gy - r + 9, gx + r - 9, gy + r - 9), 135, 405, fill=blue, width=1)
        draw_tracked(draw, (gx - tracked_width(draw, name, label, tracking=1) / 2, gy + r + 3), name, label, white, tracking=1)


def _expanse_paint_list(image: Image.Image) -> None:
    """The contacts list: boxed rows with a silhouette and a name, and a
    drive scatter box beneath with its system text."""
    draw = ImageDraw.Draw(image)
    px = image.load()
    white, blue, yellow = SPECTRA6["white"], SPECTRA6["blue"], SPECTRA6["yellow"]
    x0, y0, x1, y1 = _EXPANSE_LIST_RECT
    font = _expanse_label_font(10)
    for k, name in enumerate(_EXPANSE_LIST_ROWS):
        ry = _EXPANSE_LIST_ROW_Y + k * _EXPANSE_LIST_ROW_H
        draw.rectangle((x0 + 8, ry, x1 - 8, ry + _EXPANSE_LIST_ROW_H - 8), outline=blue, width=1)
        sx, sy = x0 + 22, ry + 14
        if k == 0:       # the Roci: a corvette, nose right
            draw.polygon([(sx - 10, sy - 3), (sx + 4, sy - 3), (sx + 11, sy), (sx + 4, sy + 3), (sx - 10, sy + 3)], fill=white)
            draw.rectangle((sx - 8, sy - 6, sx - 4, sy + 6), fill=white)
        elif k == 1:     # the contact: a diamond, orange
            glyph = Image.new("L", image.size, 0)
            ImageDraw.Draw(glyph).polygon([(sx, sy - 7), (sx + 9, sy), (sx, sy + 7), (sx - 9, sy)], fill=255)
            _expanse_paint_stipple_masked(image, glyph, SPECTRA6["red"], SPECTRA6["yellow"])
            glyph.close()
        else:            # unknowns: hollow triangles
            draw.polygon([(sx, sy - 7), (sx + 7, sy + 5), (sx - 7, sy + 5)], outline=blue, width=1)
        draw_tracked(draw, (x0 + 40, ry + 6), name, font, white, tracking=1)
        _expanse_dotted_rule(px, x0 + 40, x1 - 14, ry + 21, blue)
    # The drive scatter box: a square with a crosshair and a seeded scatter.
    sx0, sy0, sx1, sy1 = _EXPANSE_SCATTER_RECT
    draw.rectangle(_EXPANSE_SCATTER_RECT, outline=blue, width=1)
    _expanse_paint_brackets(draw, (sx0 - 3, sy0 - 3, sx1 + 3, sy1 + 3), white, length=6)
    mx, my = (sx0 + sx1) // 2, (sy0 + sy1) // 2
    draw.line([(mx, sy0 + 4), (mx, sy1 - 4)], fill=blue, width=1)
    draw.line([(sx0 + 4, my), (sx1 - 4, my)], fill=blue, width=1)
    rng = random.Random(_EXPANSE_SEED + 4)
    for _ in range(26):
        dx, dy = rng.gauss(0, 12), rng.gauss(0, 9)
        x, y = int(mx + dx), int(my + dy)
        if sx0 + 3 < x < sx1 - 3 and sy0 + 3 < y < sy1 - 3:
            px[x, y] = white
            if rng.random() < 0.3:
                px[x + 1, y] = white
    draw.ellipse((mx - 3, my - 3, mx + 3, my + 3), outline=yellow, width=1)
    draw_tracked(draw, (x0 + 12, y1 - 24), "DRIVE 01", _expanse_label_bold_font(10), white, tracking=1)
    w = draw_tracked(draw, (x1 - 12, y1 - 23), "OPTIMAL", _expanse_label_font(9), white, tracking=1, anchor_right=True)
    draw.rounded_rectangle((x1 - 12 - w - 14, y1 - 22, x1 - 12 - w - 6, y1 - 16), radius=2, fill=SPECTRA6["green"])


def _expanse_paint_foot(image: Image.Image) -> None:
    """The readout strip's chrome: the pill-grid row labels, the chart's
    frame and dotted baseline, and the system text block."""
    _expanse_paint_panel(image, _EXPANSE_FOOT_RECT, "", corners=("tl", "br"), header=False)
    draw = ImageDraw.Draw(image)
    px = image.load()
    blue, white = SPECTRA6["blue"], SPECTRA6["white"]
    x0, y0, x1, y1 = _EXPANSE_FOOT_RECT
    label = _expanse_label_font(9)
    for k, name in enumerate(_EXPANSE_PILL_ROWS):
        draw_tracked(draw, (x0 + 34, y0 + 9 + k * 13), name, label, white, tracking=1)
    draw.line([(x0 + 200, y0 + 10), (x0 + 200, y1 - 10)], fill=blue, width=1)
    cx0, cy0, cx1, cy1 = _EXPANSE_CHART_RECT
    draw_tracked(draw, (cx0, cy0 - 2), "DSR", _expanse_label_bold_font(9), white, tracking=1)
    _expanse_dotted_rule(px, cx0 + 24, cx1, cy1 - 1, blue)
    _expanse_dotted_rule(px, cx0 + 24, cx1, cy0 + (cy1 - cy0) // 2, blue, pitch=5)
    for k in range(0, cx1 - cx0 - 24, 30):
        draw.line([(cx0 + 24 + k, cy1), (cx0 + 24 + k, cy1 + 3)], fill=blue, width=1)
    draw.line([(cx1 + 12, y0 + 10), (cx1 + 12, y1 - 10)], fill=blue, width=1)
    _expanse_paint_systext(draw, _EXPANSE_SYSTEXT_X, y0 + 8, (
        "// REX MASTER LOAD CONTROL",
        "PROG. GENERATOR <01> // PROC. RLF001",
        "// WAIT  RUN 03  MASTER LOADED <04>",
    ))


def _expanse_scene() -> Image.Image:
    """The console without its transmission: ground, tag, orbital strip,
    the three panels, the plot, the list and the readout strip. Painted
    once per process."""
    key = (_expanse_paint_ground, _expanse_paint_tag, _expanse_paint_orbit, _expanse_paint_panel,
           _expanse_paint_plot, _expanse_paint_list, _expanse_paint_foot)
    cached = _EXPANSE_SCENE.get("frame")
    if cached is not None and cached[0] == key:
        return cached[1]
    image = Image.new("RGB", (800, 480), SPECTRA6["black"])
    _expanse_paint_ground(image)
    _expanse_paint_tag(image)
    _expanse_paint_orbit(image)
    _expanse_paint_panel(image, _EXPANSE_PLOT_RECT, "TACTICAL", sub="RNG 500")
    _expanse_paint_plot(image)
    _expanse_paint_panel(image, _EXPANSE_FEED_RECT, "COMMS", sub="TIGHTBEAM · ENCRYPTED")
    _expanse_paint_panel(image, _EXPANSE_LIST_RECT, "CONTACTS")
    _expanse_paint_list(image)
    draw = ImageDraw.Draw(image)
    px = image.load()
    x0, y0, x1, _ = _EXPANSE_FEED_RECT
    draw_tracked(draw, (x0 + 84, y0 + 7), "FEED 01 · INCOMING", _expanse_label_font(11), SPECTRA6["white"], tracking=2)
    draw_tracked(draw, (x0 + 14, _EXPANSE_SENDER_Y + 7), "FROM", _expanse_label_font(10), SPECTRA6["white"], tracking=2)
    draw.rectangle(_EXPANSE_FRAME_RECT, outline=SPECTRA6["blue"], width=1)
    fx0, fy0, fx1, fy1 = _EXPANSE_FRAME_RECT
    _expanse_paint_brackets(draw, (fx0 - 3, fy0 - 3, fx1 + 3, fy1 + 3), SPECTRA6["white"], length=9)
    for k in range(fx0 + 20, fx1 - 10, 20):
        draw.line([(k, fy1 - 4), (k, fy1 - 1)], fill=SPECTRA6["blue"], width=1)
    draw_tracked(draw, (x0 + 14, _EXPANSE_SOURCE_Y + 2), "SRC", _expanse_label_font(10), SPECTRA6["white"], tracking=2)
    draw_tracked(draw, (x1 - 128, _EXPANSE_SOURCE_Y + 2), "SIG", _expanse_label_font(10), SPECTRA6["white"], tracking=2)
    _expanse_dotted_rule(px, x0 + 14, x1 - 14, _EXPANSE_SOURCE_Y + 16, SPECTRA6["blue"])
    _expanse_paint_foot(image)
    _EXPANSE_SCENE["frame"] = (key, image)
    return image


def _expanse_paint_contact(image: Image.Image, hour: int) -> None:
    """The tracked contact at the hour's bearing: its track arced through
    it in blue, the intercept dashed in orange from the Roci, an orange
    diamond in brackets with a white core and an amber bloom, and the
    bearing in the contact's row of the list."""
    draw = ImageDraw.Draw(image)
    black, white, blue, yellow, red = (SPECTRA6["black"], SPECTRA6["white"], SPECTRA6["blue"],
                                       SPECTRA6["yellow"], SPECTRA6["red"])
    bearing = _expanse_bearing(hour)
    r = _EXPANSE_CONTACT_RADIUS
    # A flyby: the track passes through the contact and bows outward at both ends.
    track = [_expanse_polar(r + 12 * ((a - bearing) / 48) ** 2, a) for a in range(bearing - 48, bearing + 49, 4)]
    _expanse_dashed(draw, track, blue, on=7, off=5)
    tx, ty = _expanse_polar(r, bearing)
    _expanse_dashed(draw, [_EXPANSE_PLOT_CENTRE, (tx, ty)], yellow, on=4, off=4)
    glow = Image.new("L", image.size, 0)
    ImageDraw.Draw(glow).polygon([(tx, ty - 6), (tx + 6, ty), (tx, ty + 6), (tx - 6, ty)], fill=255)
    paint_neon_mask(image, glow, yellow, yellow, radius=7, gamma=1.6, cap=0.55, tile=BAYER_8x8,
                    glow_minor=red, glow_minor_share=0.4, ground=frozenset({black, blue}))
    glow.close()
    draw.polygon([(tx, ty - 3), (tx + 3, ty), (tx, ty + 3), (tx - 3, ty)], fill=white)
    for sx, sy in ((-1, -1), (1, -1), (1, 1), (-1, 1)):
        _expanse_paint_bracket(draw, int(tx + sx * 11), int(ty + sy * 11), -sx, -sy, yellow, length=5, width=1)
    x0, _, x1, _ = _EXPANSE_LIST_RECT
    ry = _EXPANSE_LIST_ROW_Y + _EXPANSE_LIST_ROW_H
    draw.text((x0 + 40, ry + 24), f"BRG {bearing:03d}", font=_expanse_mono_font(11), fill=yellow)


def _expanse_paint_sender(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The sender — the author, or the book when there is none — in Barlow
    Bold capitals, the MCRN orange."""
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "")
    name = (author or title or "UNKNOWN STATION").upper()
    x0, _, x1, _ = _EXPANSE_FEED_RECT
    font, text = fit_text_to_width(draw, name, [BARLOW_BOLD, BARLOWCOND_BOLD, *META_FONT_BOLD_CANDIDATES],
                                   20, x1 - x0 - 90, floor=15, tracking=2)
    x = float(x0 + 52)
    for ch in text:
        draw_text_dithered(image, (int(round(x)), _EXPANSE_SENDER_Y), ch, font, SPECTRA6["red"], SPECTRA6["yellow"],
                           light_density=0.5)
        x += draw.textlength(ch, font=font) + 2


def _expanse_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The transmission: white Barlow, ragged right, the matched phrase
    SemiBold in the MCRN orange, centred in the feed's frame."""
    x0, y0, x1, y1 = _EXPANSE_QUOTE_RECT
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    quote_font, quote_font_bold, wrapped, line_height, _ = fit_quote(
        draw, display_quote, quote_row.get("matched_text") or "",
        x1 - x0, y1 - y0, font_max=36, font_min=14, line_height_mult=1.3, theme="expanse",
    )
    # A short transmission sits in the middle of the frame rather than
    # leaving the glass under it dark.
    y = y0 + max(0, (y1 - y0 - len(wrapped) * line_height) // 2)
    ascent = _font_ascent(quote_font)
    for line in wrapped:
        x = x0
        for chunk, is_bold in line:
            font = quote_font_bold if is_bold else quote_font
            chunk_y = y + (ascent - _font_ascent(font))
            if is_bold and chunk.strip():
                draw_text_dithered(image, (x, chunk_y), chunk, font, SPECTRA6["red"], SPECTRA6["yellow"], light_density=0.5)
            elif not is_bold:
                draw.text((x, chunk_y), chunk, font=font, fill=SPECTRA6["white"])
            x += int(round(draw.textlength(chunk, font=font)))
        y += line_height


def _expanse_gauges(quote_row: dict) -> tuple[int, ...]:
    """The four arc gauges' sweeps, 0..12 each, dealt from the row digest."""
    d = _row_digest(quote_row)
    return tuple((d >> (5 * k)) % 13 for k in range(len(_EXPANSE_ARC_GAUGES)))


def _expanse_pills(quote_row: dict) -> tuple[tuple[str, ...], ...]:
    """The pill grid, four rows of three: each pill green, amber, red or
    dark, dealt from the row digest two bits at a time."""
    d = _row_digest(quote_row) ^ 0x5A5A5A5A
    inks = ("green", "amber", "red", "dark")
    return tuple(tuple(inks[(d >> (2 * (3 * r + c))) & 3] for c in range(3)) for r in range(len(_EXPANSE_PILL_ROWS)))


def _expanse_signal(quote_row: dict) -> int:
    """Signal strength, 1..8 bars, from the row digest."""
    return 1 + (_row_digest(quote_row) >> 30) % 8


def _expanse_tx_id(quote_row: dict) -> str:
    """The transmission's ID: four hex digits of the row digest."""
    return f"TX-{_row_digest(quote_row) & 0xFFFF:04X}"


def _expanse_paint_segments(image: Image.Image, draw: ImageDraw.ImageDraw, x: int, y: int, filled: int, total: int,
                            *, cell: int = 6, gap: int = 3, height: int = 10) -> None:
    """A segmented bar: lit cells in cyan, the rest as blue hairline boxes."""
    for k in range(total):
        rect = (x + k * (cell + gap), y, x + k * (cell + gap) + cell - 1, y + height - 1)
        if k < filled:
            _expanse_paint_cyan_rect(image, (rect[0], rect[1], rect[2] + 1, rect[3] + 1))
        else:
            draw.rectangle(rect, outline=SPECTRA6["blue"], width=1)


def _expanse_paint_source(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The foot of the feed: the book as the source, the signal bars, and
    the command line with the transmission ID."""
    x0, _, x1, y1 = _EXPANSE_FEED_RECT
    white = SPECTRA6["white"]
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "").strip()
    if title:
        font, text = fit_text_to_width(draw, title.upper(), [BARLOWCOND_MEDIUM, BARLOW_MEDIUM, *META_FONT_CANDIDATES],
                                       13, x1 - x0 - 220, floor=11, tracking=1)
        draw_tracked(draw, (x0 + 44, _EXPANSE_SOURCE_Y + 1), text, font, white, tracking=1)
    _expanse_paint_segments(image, draw, x1 - 100, _EXPANSE_SOURCE_Y + 2, _expanse_signal(quote_row), 8, cell=7, gap=4)
    mono = _expanse_mono_font(12)
    prompt = f"> comms.rx tightbeam --decrypt ok  [{_expanse_tx_id(quote_row)}]"
    draw.text((x0 + 14, _EXPANSE_PROMPT_Y), prompt, font=mono, fill=white)
    cursor_x = int(x0 + 14 + draw.textlength(prompt + " ", font=mono))
    _expanse_paint_amber_rect(image, (cursor_x, _EXPANSE_PROMPT_Y + 2, cursor_x + 7, _EXPANSE_PROMPT_Y + 13))


def _expanse_paint_arc_gauges(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The four arc gauges' sweeps: a cyan arc over the outer ring and an
    orange arc on the inner, each sweeping the quote's value of 270°."""
    r = _EXPANSE_ARC_GAUGE_R
    for gx, sweep in zip(_EXPANSE_ARC_GAUGE_XS, _expanse_gauges(quote_row)):
        gy = _EXPANSE_ARC_GAUGE_Y
        end = 135 + 270 * sweep / 12
        mask = Image.new("L", image.size, 0)
        md = ImageDraw.Draw(mask)
        md.arc((gx - r + 2, gy - r + 2, gx + r - 2, gy + r - 2), 135, end, fill=255, width=4)
        _expanse_paint_stipple_masked(image, mask, SPECTRA6["blue"], SPECTRA6["white"])
        md.rectangle((0, 0, image.size[0], image.size[1]), fill=0)
        md.arc((gx - r + 9, gy - r + 9, gx + r - 9, gy + r - 9), 135, 135 + 270 * ((sweep * 7) % 13) / 12, fill=255, width=3)
        image.paste(SPECTRA6["black"], (0, 0), mask)
        _expanse_paint_stipple_masked(image, mask, SPECTRA6["red"], SPECTRA6["yellow"])
        mask.close()
        draw.ellipse((gx - 1, gy - 1, gx + 1, gy + 1), fill=SPECTRA6["white"])


def _expanse_paint_stipple_masked(image: Image.Image, mask: Image.Image, ink_a, ink_b) -> None:
    """A 50/50 ``ink_a``/``ink_b`` checker through an ``L`` mask: blue + white
    for the cyan, red + yellow for the MCRN orange."""
    bbox = mask.getbbox()
    if not bbox:
        return
    swatch = Image.new("RGB", image.size, SPECTRA6["black"])
    _fill_swatch_stipple(swatch, bbox, ink_a, ink_b, 0.5)
    image.paste(swatch, (0, 0), mask)
    swatch.close()


def _expanse_paint_readouts(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The foot's quote-dependent modules: the pill grid, the waveform
    chart and the boxed IDs under the system text."""
    x0, y0, x1, y1 = _EXPANSE_FOOT_RECT
    for r, row in enumerate(_expanse_pills(quote_row)):
        for c, ink in enumerate(row):
            px0 = x0 + 66 + c * 40
            py0 = y0 + 10 + r * 13
            _expanse_paint_pill(image, draw, (px0, py0, px0 + 32, py0 + 8), ink)
    # The waveform: a seeded walk filled to the baseline in cyan with a white crest.
    cx0, cy0, cx1, cy1 = _EXPANSE_CHART_RECT
    rng = random.Random(_row_digest(quote_row))
    base = cy1 - 2
    height = cy1 - cy0 - 6
    pts = []
    v = 0.4
    for x in range(cx0 + 24, cx1):
        v = min(1.0, max(0.05, v + rng.uniform(-0.09, 0.09) + (0.5 - v) * 0.04))
        pts.append((x, base - int(v * height)))
    area = Image.new("L", image.size, 0)
    ImageDraw.Draw(area).polygon([(cx0 + 24, base)] + pts + [(cx1 - 1, base)], fill=255)
    _expanse_paint_stipple_masked(image, area, SPECTRA6["blue"], SPECTRA6["white"])
    area.close()
    draw.line(pts, fill=SPECTRA6["white"], width=1)
    # Boxed IDs under the system text, as the modules carry.
    mono = _expanse_mono_font(10)
    d = _row_digest(quote_row)
    bx, by = _EXPANSE_SYSTEXT_X, y0 + 46
    for k, text in enumerate((f"{d % 10_000_000:07d}", f"SY{(d >> 8) % 100_000:05d}")):
        w = int(draw.textlength(text, font=mono)) + 10
        draw.rectangle((bx, by, bx + w, by + 15), outline=SPECTRA6["blue"], width=1)
        draw.text((bx + 5, by + 2), text, font=mono, fill=SPECTRA6["white"])
        bx += w + 8
    w = draw_tracked(draw, (x1 - 14, by + 3), "ARMED", _expanse_label_font(9), SPECTRA6["white"], tracking=1, anchor_right=True)
    draw.rectangle((x1 - 14 - w - 14, by + 2, x1 - 14 - w - 7, by + 13), fill=SPECTRA6["red"])


def render_expanse_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """The Rocinante's console with the quote as an incoming tightbeam (see
    the section comment above)."""
    hour = _clock_hour12(time_str)
    del time_str
    image = _expanse_scene().copy()
    draw = ImageDraw.Draw(image)
    _expanse_paint_contact(image, hour)
    _expanse_paint_sender(image, draw, quote_row)
    _expanse_paint_quote(image, draw, quote_row)
    _expanse_paint_source(image, draw, quote_row)
    _expanse_paint_arc_gauges(image, draw, quote_row)
    _expanse_paint_readouts(image, draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# goya — Francisco de Goya, the *Pinturas negras* (1819-1823): *El Perro*
# ---------------------------------------------------------------------------
# The dog's head looks up out of a dark slope into an ochre void; here it is
# looking at the time. Full design notes: docs/themes.md (``goya``).
#
# Palette: black, yellow, red and white only (the paintings' earth plus their
# one red), never blue or green. The void is painted in continuous tone and
# Floyd–Steinberg dithered against the calibrated inks (``_dither_calibrated``);
# the slope is a warm black in the same scene, so its edge is brushed rather
# than ruled. ``paint_craquelure`` crazes the cached scene (cells coarser than
# ``bosch``'s, as a mural's craze is) before the quote goes on, so the quote is
# never cracked through.
#
# ``_goya_gaze`` pitches the head toward the matched phrase's centroid. The
# body is black, not white: the void's luminance sits a third of the way from
# black to white, giving black text ~6:1 contrast and white ~2:1. The label's
# Prado-style inventory number comes from the Gutenberg id; it carries no date
# (the book's would be wrong, Goya's a lie about the author).
#
# No hour carrier and no wall clock: ``time_str`` is deleted at frame entry.
# Void, slope and craze are quote-independent and cached per process
# (``_GOYA_SCENE``). Composed at 800x480 and NEAREST-downsampled otherwise (the
# ``metro`` convention).
# ---------------------------------------------------------------------------
_GOYA_SEED = 0x474F5941              # GOYA
_GOYA_INKS = ("black", "red", "yellow", "white")
_GOYA_SLOPE_LEFT = 386               # the slope's top edge at x=0 …
_GOYA_SLOPE_RIGHT = 322              # … and at x=800: it rises to the right
_GOYA_DOG_PIVOT = (252, 308)         # the skull's centre; the neck runs down into the slope
_GOYA_GAZE_MIN = math.radians(14)    # a near-level look …
_GOYA_GAZE_MAX = math.radians(44)    # … to a nose well in the air
_GOYA_GAZE_DEFAULT = math.radians(28)  # the painting's own tilt
_GOYA_QUOTE_RECT = (84, 50, 716, 292)
_GOYA_LABEL_RECT = (540, 382, 780, 470)
_GOYA_CRACK_CELL = (30, 19)
# The void, top to foot, in the calibrated space: dark umber at the top, the
# pale ochre passage where the painting's light sits, a deeper ochre above
# the slope, umber again beneath it.
_GOYA_VOID_STOPS = (
    (0, (70, 58, 38)), (64, (108, 92, 50)), (150, (144, 128, 70)), (230, (140, 122, 64)),
    (320, (116, 96, 46)), (400, (82, 64, 38)), (480, (60, 48, 30)),
)
_GOYA_LIGHT = (172, 156, 94)         # the pale passage, pooled upper-centre-left
_GOYA_STAIN = (86, 68, 42)           # the cool stain dragged over the upper right
_GOYA_SLOPE = (42, 34, 28)           # the slope: a warm black
_GOYA_SLOPE_EDGE = (72, 54, 36)      # its brushed upper edge
_GOYA_DOG_BASE = (102, 74, 46)       # the dog: raw umber …
_GOYA_DOG_LIGHT = (118, 90, 58)      # … lit from the upper left …
_GOYA_DOG_DARK = (56, 42, 30)        # … and in shadow toward the slope
_GOYA_DOG_EAR = (62, 46, 32)         # the dropped ear, in the skull's shadow
# The head and neck in a local frame: +x toward the nose, +y down, origin at
# the skull's centre, muzzle level. Rotated about the origin by the gaze; the
# neck runs far enough down to meet the slope at any pitch in range.
_GOYA_HEAD = (
    (-34, -8), (-26, -30), (-8, -42), (16, -38), (30, -30), (40, -22), (56, -16), (72, -10),
    (80, -4), (78, 4), (66, 12), (50, 16), (36, 20), (22, 24), (8, 30), (-4, 40),
    (-10, 56), (-14, 90), (-58, 90), (-54, 56), (-48, 28), (-44, 8),
)
_GOYA_EAR = ((-30, -14), (-44, -2), (-50, 18), (-44, 32), (-32, 28), (-26, 10), (-24, -4))
_GOYA_EYE = (26, -16)
_GOYA_NOSTRIL = (74, -6)
_GOYA_SCENE: dict = {}


def _goya_slope_edge() -> list:
    """The slope's upper edge, x=0..800: a line rising to the right with a
    seeded brush wobble and a swell where the dog stands."""
    rng = random.Random(_GOYA_SEED + 1)
    points = []
    for x in range(0, 801, 25):
        t = x / 800.0
        y = _GOYA_SLOPE_LEFT + (_GOYA_SLOPE_RIGHT - _GOYA_SLOPE_LEFT) * t
        y -= 14 * math.exp(-((x - _GOYA_DOG_PIVOT[0]) / 90.0) ** 2)
        points.append((x, y + rng.uniform(-5, 5)))
    return _catmull_rom(points, closed=False, samples=6)


def _goya_slope_mask(size) -> Image.Image:
    mask = Image.new("L", size, 0)
    edge = _goya_slope_edge()
    ImageDraw.Draw(mask).polygon([(0, size[1])] + [(round(x), round(y)) for x, y in edge] + [(size[0], size[1])],
                                 fill=255)
    return mask


def _goya_paint_void(scene: Image.Image) -> None:
    """The void in continuous tone: the gradient, the pale passage, the
    stain, the dragged strokes and the grain, then the slope."""
    width, height = scene.size
    column = Image.new("RGB", (1, height))
    cp = column.load()
    for y in range(height):
        cp[0, y] = _lerp_stops(_GOYA_VOID_STOPS, y)
    scene.paste(column.resize((width, height), Image.Resampling.NEAREST), (0, 0))
    light = _soft_ellipse_mask(scene.size, (40, 70, 560, 290), 44).point(lambda v: int(v * 0.58))
    scene.paste(Image.new("RGB", scene.size, _GOYA_LIGHT), (0, 0), light)
    stain = _soft_ellipse_mask(scene.size, (520, -30, 800, 150), 34).point(lambda v: int(v * 0.66))
    scene.paste(Image.new("RGB", scene.size, _GOYA_STAIN), (0, 0), stain)
    # Facture: broad dragged strokes (a noise streaked eight to one) over a
    # finer grain, each centred so it moves the tone both ways.
    for cells, amp, salt in (((10, 44), 13, 2), ((48, 36), 7, 3), ((5, 3), 9, 4)):
        grain = _smooth_noise(scene.size, cells, _GOYA_SEED + salt).point(lambda v, a=amp: v * (2 * a) // 255)
        tint = Image.merge("RGB", (grain, grain, grain))
        scene.paste(ImageChops.subtract(ImageChops.add(scene, tint), Image.new("RGB", scene.size, (amp,) * 3)))
    # The slope: a warm black, its upper edge brushed lighter.
    slope = _goya_slope_mask(scene.size)
    edge = ImageChops.subtract(slope, slope.filter(ImageFilter.MinFilter(9))).filter(ImageFilter.GaussianBlur(3))
    scene.paste(Image.new("RGB", scene.size, _GOYA_SLOPE), (0, 0), slope)
    scene.paste(Image.new("RGB", scene.size, _GOYA_SLOPE_EDGE), (0, 0), edge.point(lambda v: int(v * 0.7)))


def _goya_scene() -> Image.Image:
    """The void and the slope, dithered and crazed. Painted once per process."""
    key = (_goya_paint_void, paint_craquelure)
    cached = _GOYA_SCENE.get("frame")
    if cached is not None and cached[0] == key:
        return cached[1]
    size = (800, 480)
    scene = Image.new("RGB", size, _PANEL_INKS["black"])
    _goya_paint_void(scene)
    image = _dither_calibrated(scene, _GOYA_INKS)
    paint_craquelure(image, Image.new("L", size, 255), seed=_GOYA_SEED + 5, cell=_GOYA_CRACK_CELL,
                     jitter=0.4, drop=0.24, diagonal=0.16, continuity=4,
                     dark=SPECTRA6["black"], light=SPECTRA6["yellow"], light_share=0.08)
    _GOYA_SCENE["frame"] = (key, image)
    return image


def _goya_layout(draw: ImageDraw.ImageDraw, quote_row: dict):
    """The quote's lines in the void, and the positioned bold chunks."""
    return _place_quote(draw, quote_row, _GOYA_QUOTE_RECT, theme="goya",
                        font_max=34, font_min=16, line_height_mult=1.32)


def _goya_gaze(placed) -> float:
    """The head's pitch above level, toward the matched phrase's centroid;
    the painting's own tilt when the quote carries no phrase."""
    bold = [(x + w / 2.0, y + lh / 2.0) for x, y, chunk, font, is_bold, w, lh in placed if is_bold and chunk.strip()]
    if not bold:
        return _GOYA_GAZE_DEFAULT
    cx = sum(p[0] for p in bold) / len(bold)
    cy = sum(p[1] for p in bold) / len(bold)
    px, py = _GOYA_DOG_PIVOT
    angle = math.atan2(py - cy, cx - px) if cx > px else _GOYA_GAZE_MAX
    return max(_GOYA_GAZE_MIN, min(_GOYA_GAZE_MAX, angle))


def _goya_turn(points, gaze: float) -> list:
    """Rotate local head points about the pivot: a positive gaze lifts the nose."""
    px, py = _GOYA_DOG_PIVOT
    c, s = math.cos(gaze), math.sin(gaze)
    return [(px + x * c + y * s, py - x * s + y * c) for x, y in points]


def _goya_paint_dog(image: Image.Image, gaze: float) -> None:
    """The dog: head and neck above the slope at the gaze's pitch, shaded,
    dithered in place against the four inks and crazed; the eye and nostril
    crisp on top."""
    size = image.size
    head = Image.new("L", size, 0)
    hd = ImageDraw.Draw(head)
    hd.polygon([(round(x), round(y)) for x, y in _catmull_rom(_goya_turn(_GOYA_HEAD, gaze), samples=6)], fill=255)
    ear = Image.new("L", size, 0)
    ImageDraw.Draw(ear).polygon([(round(x), round(y)) for x, y in _catmull_rom(_goya_turn(_GOYA_EAR, gaze), samples=6)],
                                fill=255)
    head = ImageChops.lighter(head, ear)
    # Only what stands above the slope is the dog; the rest is the slope.
    head = ImageChops.subtract(head, _goya_slope_mask(size))
    bbox = head.getbbox()
    if bbox is None:
        return
    pad = 6
    box = (max(0, bbox[0] - pad), max(0, bbox[1] - pad), min(size[0], bbox[2] + pad), min(size[1], bbox[3] + pad))
    shaded = _shade_silhouette(head, _GOYA_DOG_BASE, _GOYA_DOG_LIGHT, _GOYA_DOG_DARK, offset=6, blur=4)
    shaded.paste(Image.new("RGB", size, _GOYA_DOG_EAR), (0, 0), ear.filter(ImageFilter.GaussianBlur(1)))
    grain = _smooth_noise(size, (40, 24), _GOYA_SEED + 6).point(lambda v: v * 12 // 255)
    shaded = ImageChops.subtract(ImageChops.add(shaded, Image.merge("RGB", (grain, grain, grain))),
                                 Image.new("RGB", size, (6, 6, 6)))
    dithered = _dither_calibrated(shaded.crop(box), _GOYA_INKS)
    image.paste(dithered, box[:2], head.crop(box))
    crop = image.crop(box)
    paint_craquelure(crop, head.crop(box), seed=_GOYA_SEED + 7, cell=_GOYA_CRACK_CELL, jitter=0.4, drop=0.24,
                     diagonal=0.16, continuity=4, dark=SPECTRA6["black"], light=SPECTRA6["yellow"], light_share=0.08)
    image.paste(crop, box[:2])
    draw = ImageDraw.Draw(image)
    (ex, ey), (nx, ny) = _goya_turn((_GOYA_EYE, _GOYA_NOSTRIL), gaze)
    draw.ellipse((ex - 5, ey - 4, ex + 5, ey + 4), fill=SPECTRA6["black"])
    draw.rectangle((ex - 2, ey - 3, ex - 1, ey - 2), fill=SPECTRA6["white"])
    draw.ellipse((nx - 4, ny - 4, nx + 4, ny + 4), fill=SPECTRA6["black"])
    for m in (head, ear, shaded, dithered, crop):
        m.close()


def _goya_paint_quote(draw: ImageDraw.ImageDraw, placed) -> None:
    """The quote written into the void: black Libre Baskerville, ragged
    right, the matched phrase Bold in the Black Paintings' one red."""
    black, red = SPECTRA6["black"], SPECTRA6["red"]
    for x, y, chunk, font, is_bold, w, lh in placed:
        draw.text((x, y), chunk, font=font, fill=red if is_bold else black)


def _goya_label_font(size: int, instance: str = "Regular"):
    """Libre Baskerville, the named instance, for the gallery label."""
    file = LIBREBASKERVILLE_ITALIC_VARIABLE if instance == "Italic" else LIBREBASKERVILLE_VARIABLE
    return load_font([(file, instance), (LIBRECASLON_VARIABLE, "Regular"), *META_FONT_CANDIDATES], size=size)


def _goya_inventory(quote_row: dict) -> str:
    """The Prado's inventory form — ``P000767`` is *El Perro* — from the
    Gutenberg id, or the series' own number when the row has none."""
    source = str(quote_row.get("source_id") or "").strip()
    digits = "".join(ch for ch in source if ch.isdigit())
    return f"P{int(digits) % 1_000_000:06d}" if digits else "P000767"


def _goya_paint_label(draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The gallery label: a white card on the slope with the author on the
    artist's line, the title in italic, the medium and the series."""
    x0, y0, x1, y1 = _GOYA_LABEL_RECT
    black, white = SPECTRA6["black"], SPECTRA6["white"]
    draw.rectangle((x0, y0, x1, y1), fill=white)
    pad = 10
    measure = x1 - x0 - 2 * pad
    author = (quote_row.get("author") or "").strip() or "Anónimo"
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "").strip()
    font, text = fit_text_to_width(draw, author, [(LIBREBASKERVILLE_VARIABLE, "SemiBold"),
                                                  (LIBRECASLON_VARIABLE, "Bold"), *META_FONT_BOLD_CANDIDATES],
                                   16, measure, floor=12)
    draw.text((x0 + pad, y0 + 9), text, font=font, fill=black)
    if title:
        font, text = fit_text_to_width(draw, title, [(LIBREBASKERVILLE_ITALIC_VARIABLE, "Italic"),
                                                     (LIBRECASLON_VARIABLE, "Regular"), *META_FONT_CANDIDATES],
                                       14, measure, floor=11)
        draw.text((x0 + pad, y0 + 33), text, font=font, fill=black)
    small = _goya_label_font(11)
    draw.text((x0 + pad, y0 + 55), "Óleo sobre revoco trasladado a lienzo", font=small, fill=black)
    draw.text((x0 + pad, y0 + 70), "Pinturas negras", font=small, fill=black)
    inventory = _goya_inventory(quote_row)
    draw.text((x1 - pad - draw.textlength(inventory, font=small), y0 + 70), inventory, font=small, fill=black)


def render_goya_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """*El Perro*, with the quote in the void and the dog looking at the
    time (see the section comment above).

    ``time_str`` is unused by design: a painting carries no clock.
    """
    del time_str
    image = _goya_scene().copy()
    draw = ImageDraw.Draw(image)
    placed = _goya_layout(draw, quote_row)
    _goya_paint_dog(image, _goya_gaze(placed))
    draw = ImageDraw.Draw(image)
    _goya_paint_quote(draw, placed)
    _goya_paint_label(draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# hal — *2001: A Space Odyssey* (1968): the Discovery One's monitors, HAL 9000
# ---------------------------------------------------------------------------
# The Discovery's monitors are flat fields of one saturated colour captioned
# with a three-letter subsystem mnemonic — solid flats, which six inks render
# exactly. Full design notes: docs/themes.md (``hal``).
#
# Layout: the main monitor (blue field, the active mnemonic in Michroma,
# seeded readout bars, the quote in white Jost with the matched phrase Bold in
# yellow, a tracked byline); the twelve subsystem tiles along the foot; and the
# right column — nameplate, HAL's lens, the VEH wireframe and the HIB monitor's
# two life traces.
#
# The hour is which subsystem is up: the hour's tile is white and its mnemonic
# heads the main monitor. The order is fixed, so the frame is byte-identical
# across the minutes of an hour; nothing reads the wall clock. Every colour is
# a solid ink; the only stipples are the ``paint_neon_mask`` blooms, each with
# ``ground`` pinned so it cannot eat the bezel. Composed at 800x480 and
# NEAREST-downsampled otherwise (the ``metro`` convention).
# ---------------------------------------------------------------------------
_HAL_SEED = 0x48414C39                # HAL9
_HAL_MNEMONICS = ("COM", "NAV", "VEH", "ATM", "HIB", "GDE", "LIF", "MEM", "DMG", "FLX", "CNT", "NUC")
_HAL_TILE_INKS = ("red", "yellow", "green", "blue")
_HAL_HOUSING_RECT = (16, 16, 644, 392)   # the monitor's housing, a hairline on black
_HAL_MONITOR_RECT = (26, 26, 634, 382)   # the screen inside it
_HAL_SCREEN_RADIUS = 20
_HAL_HEADER_RULE_Y = 96
_HAL_QUOTE_RECT = (56, 110, 604, 338)
_HAL_BYLINE_Y = 352
_HAL_TILE_BAND = (24, 402, 636, 462)
_HAL_TILE_GAP = 6
_HAL_PLATE_RECT = (664, 24, 780, 92)
_HAL_EYE_CENTRE = (722, 196)
_HAL_EYE_RADIUS = 44
_HAL_SHIP_RECT = (664, 292, 780, 370)   # VEH: the Discovery in wireframe
_HAL_TRACE_RECT = (664, 378, 780, 462)  # HIB: the life traces
_HAL_SCANLINE_PERIOD = 4


def _crt_paint_scanlines(image: Image.Image, rect, ground, *, period: int = 4, phase: int = 0) -> None:
    """Raster lines over a CRT: every ``period``-th row inside ``rect`` goes
    black where it holds one of the ``ground`` inks, so glyphs and graphics
    painted over the phosphor stay solid and the type keeps its weight. One
    in four is the coarsest spacing that still reads as lines rather than
    stripes at the panel's pitch."""
    x0, y0, x1, y1 = rect
    width, height = image.size
    x0, y0, x1, y1 = max(0, x0), max(0, y0), min(width, x1), min(height, y1)
    if x1 <= x0 or y1 <= y0:
        return
    px = image.load()
    black = SPECTRA6["black"]
    ground = set(ground)
    for y in range(y0, y1):
        if (y - y0 + phase) % period:
            continue
        for x in range(x0, x1):
            if px[x, y] in ground:
                px[x, y] = black


def _hal_mnemonic(hour: int) -> str:
    return _HAL_MNEMONICS[(hour - 1) % 12]


def _hal_tile_rects() -> list:
    """The twelve foot tiles, left to right, one per hour."""
    x0, y0, x1, y1 = _HAL_TILE_BAND
    width = (x1 - x0 - 11 * _HAL_TILE_GAP) // 12
    used = 12 * width + 11 * _HAL_TILE_GAP
    start = x0 + (x1 - x0 - used) // 2
    return [(start + i * (width + _HAL_TILE_GAP), y0, start + i * (width + _HAL_TILE_GAP) + width, y1)
            for i in range(12)]


def _hal_chrome_font(size: int):
    """Michroma — the monitors' squared capitals — for every label."""
    return load_font([MICHROMA_REGULAR, (JOST_VARIABLE, "Bold"), *ORNAMENT_FONT_CANDIDATES], size=size)


def _hal_paint_monitor(image: Image.Image, hour: int, quote_row: dict) -> None:
    """The main monitor: the blue field, the active mnemonic, a row of
    readout bars seeded from the quote, and the rule under both."""
    draw = ImageDraw.Draw(image)
    x0, y0, x1, y1 = _HAL_MONITOR_RECT
    blue, white, black = SPECTRA6["blue"], SPECTRA6["white"], SPECTRA6["black"]
    # The housing: a hairline on the black, and the phosphor's light leaking
    # onto it from the glass.
    draw.rounded_rectangle(_HAL_HOUSING_RECT, radius=_HAL_SCREEN_RADIUS + 8, fill=black, outline=white, width=1)
    glass = Image.new("L", image.size, 0)
    ImageDraw.Draw(glass).rounded_rectangle((x0, y0, x1, y1), radius=_HAL_SCREEN_RADIUS, fill=255)
    paint_neon_mask(image, glass, None, blue, radius=7, gamma=1.6, cap=0.5, ground=(black,))
    glass.close()
    draw.rounded_rectangle((x0, y0, x1, y1), radius=_HAL_SCREEN_RADIUS, fill=blue)
    # The mnemonic in its title box, the way the film's screens caption
    # themselves, and a seeded bar chart beside it.
    font = _hal_chrome_font(36)
    name = _hal_mnemonic(hour)
    tw = draw.textlength(name, font=font)
    draw.rectangle((x0 + 28, y0 + 18, x0 + 28 + tw + 24, y0 + 72), outline=white, width=2)
    draw.text((x0 + 40, y0 + 24), name, font=font, fill=white)
    rng = random.Random(_HAL_SEED ^ _row_digest(quote_row))
    bar_x = x1 - 30 - 12 * 15
    for i in range(12):
        h = rng.randint(6, 44)
        bx = bar_x + i * 15
        draw.rectangle((bx, y0 + 70 - h, bx + 9, y0 + 70), fill=white)
    draw.rectangle((bar_x - 2, y0 + 71, x1 - 30, y0 + 72), fill=white)
    draw.rectangle((x0 + 28, _HAL_HEADER_RULE_Y, x1 - 30, _HAL_HEADER_RULE_Y + 2), fill=white)


def _hal_layout(draw: ImageDraw.ImageDraw, quote_row: dict):
    """The quote's lines on the monitor, with the bold chunks positioned."""
    return _place_quote(draw, quote_row, _HAL_QUOTE_RECT, theme="hal",
                        font_max=36, font_min=16, line_height_mult=1.28)


def _hal_paint_quote(draw: ImageDraw.ImageDraw, placed) -> None:
    """White Jost on the blue field; the matched phrase Bold in yellow."""
    _paint_placed(draw, placed, SPECTRA6["white"], SPECTRA6["yellow"])


def _hal_paint_byline(draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """Author and title as the monitor's tracked capitals along its foot."""
    x0 = _HAL_QUOTE_RECT[0]
    measure = _HAL_QUOTE_RECT[2] - x0
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "").strip()
    parts = [p.upper() for p in (author, title) if p]
    if not parts:
        return
    text = "   /   ".join(parts)
    font, text = fit_text_to_width(draw, text, [(JOST_VARIABLE, "Medium"), *META_FONT_CANDIDATES],
                                   16, measure, floor=13, tracking=2)
    draw_tracked(draw, (x0, _HAL_BYLINE_Y), text, font, SPECTRA6["white"], tracking=2)


def _hal_paint_tiles(image: Image.Image, hour: int, quote_row: dict) -> None:
    """The twelve subsystem tiles along the foot: the film's colours in
    rotation, the hour's tile white, each with a seeded mini-readout."""
    draw = ImageDraw.Draw(image)
    rng = random.Random(_HAL_SEED + 7 + _row_digest(quote_row))
    white, black = SPECTRA6["white"], SPECTRA6["black"]
    font = _hal_chrome_font(11)
    for i, (x0, y0, x1, y1) in enumerate(_hal_tile_rects()):
        active = (i + 1) == hour
        ink = "white" if active else _HAL_TILE_INKS[i % len(_HAL_TILE_INKS)]
        fill = SPECTRA6[ink]
        label = black if ink in ("white", "yellow") else white
        draw.rounded_rectangle((x0, y0, x1, y1), radius=5, fill=fill)
        name = _HAL_MNEMONICS[i]
        tw = draw.textlength(name, font=font)
        draw.text((x0 + (x1 - x0 - tw) / 2, y0 + 7), name, font=font, fill=label)
        for b in range(4):
            h = rng.randint(3, 18)
            bx = x0 + 6 + b * 9
            draw.rectangle((bx, y1 - 8 - h, bx + 5, y1 - 8), fill=label)
        _crt_paint_scanlines(image, (x0, y0, x1 + 1, y1 + 1), (fill,), period=_HAL_SCANLINE_PERIOD, phase=1)
        if active:
            draw.rectangle((x0, y0 - 8, x1, y0 - 6), fill=white)


def _hal_paint_plate(draw: ImageDraw.ImageDraw) -> None:
    """The nameplate above the lens: HAL over 9000 on the blue plate."""
    x0, y0, x1, y1 = _HAL_PLATE_RECT
    blue, white = SPECTRA6["blue"], SPECTRA6["white"]
    draw.rectangle((x0, y0, x1, y1), fill=blue)
    big, small = _hal_chrome_font(24), _hal_chrome_font(15)
    cx = (x0 + x1) / 2
    draw.text((cx - draw.textlength("HAL", font=big) / 2, y0 + 8), "HAL", font=big, fill=white)
    draw.text((cx - draw.textlength("9000", font=small) / 2, y0 + 42), "9000", font=small, fill=white)


def _hal_paint_eye(image: Image.Image) -> None:
    """The lens: a red disc in a white bezel, a yellow bloom at its centre
    with a white catchlight, and red light spilling into the black."""
    cx, cy = _HAL_EYE_CENTRE
    r = _HAL_EYE_RADIUS
    draw = ImageDraw.Draw(image)
    black, white, red, yellow = SPECTRA6["black"], SPECTRA6["white"], SPECTRA6["red"], SPECTRA6["yellow"]
    draw.ellipse((cx - r - 6, cy - r - 6, cx + r + 6, cy + r + 6), fill=black, outline=white, width=3)
    draw.ellipse((cx - r, cy - r, cx + r, cy + r), fill=red)
    glow = Image.new("L", image.size, 0)
    ImageDraw.Draw(glow).ellipse((cx - 13, cy - 13, cx + 13, cy + 13), fill=255)
    paint_neon_mask(image, glow, yellow, yellow, radius=9, gamma=1.8, cap=0.6, ground=(red,))
    draw.ellipse((cx - 19, cy - 19, cx - 9, cy - 9), fill=white)
    bloom = Image.new("L", image.size, 0)
    ImageDraw.Draw(bloom).ellipse((cx - r - 8, cy - r - 8, cx + r + 8, cy + r + 8), fill=255)
    paint_neon_mask(image, bloom, None, red, radius=12, gamma=2.0, cap=0.45, ground=(black,))
    glow.close()
    bloom.close()


def _hal_paint_ship(draw: ImageDraw.ImageDraw) -> None:
    """The vehicle monitor under the lens: the Discovery One in white
    wireframe — the command sphere, the spine of fuel tanks, the engine
    block — the kind of schematic the film's screens drew by hand."""
    x0, y0, x1, y1 = _HAL_SHIP_RECT
    white = SPECTRA6["white"]
    draw.rectangle((x0, y0, x1, y1), outline=white, width=1)
    draw.text((x0 + 8, y0 + 6), "VEH", font=_hal_chrome_font(11), fill=white)
    cy = y0 + 50
    sx = x0 + 10
    draw.ellipse((sx, cy - 11, sx + 22, cy + 11), outline=white, width=1)
    draw.ellipse((sx + 6, cy - 5, sx + 16, cy + 5), outline=white, width=1)
    draw.line((sx + 22, cy, x1 - 26, cy), fill=white, width=1)
    for i in range(5):
        bx = sx + 30 + i * 11
        draw.rectangle((bx, cy - 4, bx + 7, cy + 4), outline=white, width=1)
    draw.rectangle((x1 - 26, cy - 8, x1 - 10, cy + 8), outline=white, width=1)
    draw.line((x1 - 10, cy - 5, x1 - 6, cy - 5), fill=white, width=1)
    draw.line((x1 - 10, cy + 5, x1 - 6, cy + 5), fill=white, width=1)
    draw.line((sx + 24, cy - 18, sx + 24, cy + 18), fill=white, width=1)
    draw.line((sx + 18, cy - 18, sx + 30, cy - 18), fill=white, width=1)


def _hal_paint_traces(image: Image.Image, quote_row: dict) -> None:
    """The hibernation monitor under the ship: two life traces, seeded
    from the quote, in a white hairline frame."""
    draw = ImageDraw.Draw(image)
    x0, y0, x1, y1 = _HAL_TRACE_RECT
    white = SPECTRA6["white"]
    draw.rectangle((x0, y0, x1, y1), outline=white, width=1)
    draw.text((x0 + 8, y0 + 6), "HIB", font=_hal_chrome_font(11), fill=white)
    rng = random.Random(_HAL_SEED + 11 + _row_digest(quote_row))
    inner_top = y0 + 24
    lane = (y1 - inner_top) // 2
    for t in range(2):
        base = inner_top + t * lane + lane // 2 + 6
        amp = lane // 2 - 6
        phase = rng.uniform(0, math.tau)
        freq = rng.uniform(0.25, 0.55)
        spike = rng.randint(6, 14)
        points = []
        for x in range(x0 + 8, x1 - 8):
            v = math.sin((x - x0) * freq + phase) * amp * 0.45
            if (x - x0) % 34 < 3:
                v -= spike
            points.append((x, round(base + v)))
        draw.line(points, fill=white, width=1)


def render_hal_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """The Discovery's main monitor with the hour's subsystem up, HAL's eye
    beside it (see the section comment above)."""
    hour = _clock_hour12(time_str)
    image = Image.new("RGB", (800, 480), SPECTRA6["black"])
    _hal_paint_monitor(image, hour, quote_row)
    draw = ImageDraw.Draw(image)
    _hal_paint_quote(draw, _hal_layout(draw, quote_row))
    _hal_paint_byline(draw, quote_row)
    _crt_paint_scanlines(image, _HAL_MONITOR_RECT, (SPECTRA6["blue"],), period=_HAL_SCANLINE_PERIOD)
    _hal_paint_tiles(image, hour, quote_row)
    _hal_paint_plate(ImageDraw.Draw(image))
    _crt_paint_scanlines(image, _HAL_PLATE_RECT, (SPECTRA6["blue"],), period=_HAL_SCANLINE_PERIOD)
    _hal_paint_eye(image)
    draw = ImageDraw.Draw(image)
    _hal_paint_ship(draw)
    _hal_paint_traces(image, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# lumon — *Severance* (2022–): the Macrodata Refinement terminal
# ---------------------------------------------------------------------------
# Macrodata Refinement: a file named after a town as a field of white digits
# on a blue CRT; the refiner boxes the "scary" cluster and sweeps it into one
# of five bins. Full design notes: docs/themes.md (``lumon``).
#
# The screen is a vignetted blue field computed at quarter resolution,
# bicubic-upsampled and Floyd–Steinberg dithered to blue and black
# (``_dither_calibrated``) so the vignette is error-diffused, not latticed. It
# sits in a recessed black edge inside a beige (W+Y stipple) housing, cached
# per process (``_LUMON_SCENE``).
#
# The hour is the completion, ``N% Complete`` with ``N = hour / 12`` (noon and
# midnight are 100%), and also the column pair of the boxed scary cluster,
# which walks left to right across the twelve hours. Both are byte-identical
# across the minutes of an hour; the matched phrase carries the minute.
#
# Faces (the show's are custom, so each register takes the nearest open face):
# Montserrat (for Gotham) for the digits and the quote, with the matched phrase
# Bold in yellow inside a white hover box; Inter (for Forma DJR) for the file
# name, completion and byline; Michroma (for Manifold Extended) for the
# wordmark. Composed at 800x480 and NEAREST-downsampled otherwise (the
# ``metro`` convention).
# ---------------------------------------------------------------------------
_LUMON_SEED = 0x4C554D4F              # LUMO
_LUMON_FILES = ("Cold Harbor", "Siena", "Dranesville", "Tumwater", "Allentown", "Sunset Park",
                "Lexington", "Nanning", "Moonbeam", "Lucknow", "Billings", "Wellington")
_LUMON_INKS = ("blue", "black")
_LUMON_HOUSING = 10                   # the beige housing, a W+Y stipple
_LUMON_GAP = 6                        # the recessed black edge of the glass
_LUMON_BEZEL = _LUMON_HOUSING + _LUMON_GAP
_LUMON_BEZEL_RADIUS = 26
_LUMON_SCANLINE_PERIOD = 4
_LUMON_HEADER_Y = 28
_LUMON_RULE_Y = 82
_LUMON_GRID_RECT = (44, 94, 756, 198)
_LUMON_GRID_COLS = 24
_LUMON_GRID_ROWS = 4
_LUMON_QUOTE_RECT = (50, 214, 750, 386)
_LUMON_BYLINE_Y = 392
_LUMON_BINS_RECT = (44, 414, 756, 460)
_LUMON_BIN_GAP = 12
_LUMON_SCENE: dict = {}
_LUMON_BLUE = _PANEL_INKS["blue"]
_LUMON_BLACK = _PANEL_INKS["black"]


def _lumon_completion(hour: int) -> int:
    """The file's completion in percent: the hour over twelve."""
    return round(hour * 100 / 12)


def _lumon_file_name(quote_row: dict) -> str:
    """The file's town, chosen by the quote."""
    return _LUMON_FILES[_row_digest(quote_row) % len(_LUMON_FILES)]


def _lumon_scene() -> Image.Image:
    """The vignetted blue CRT inside its bezel, dithered. Painted once per
    process."""
    key = (_lumon_paint_screen,)
    cached = _LUMON_SCENE.get("frame")
    if cached is not None and cached[0] == key:
        return cached[1]
    size = (800, 480)
    image = Image.new("RGB", size, SPECTRA6["black"])
    _lumon_paint_screen(image)
    _LUMON_SCENE["frame"] = (key, image)
    return image


def _lumon_paint_screen(image: Image.Image) -> None:
    """The blue field falling to black at the corners, error-diffused to the
    two inks, in a recessed black edge inside a beige housing, with the
    phosphor's light leaking onto the edge."""
    width, height = image.size
    small = Image.new("RGB", (width // 4, height // 4))
    sp = small.load()
    cx, cy = small.size[0] / 2.0, small.size[1] / 2.0
    rmax = math.hypot(cx, cy)
    for y in range(small.size[1]):
        for x in range(small.size[0]):
            t = min(1.0, (math.hypot(x + 0.5 - cx, y + 0.5 - cy) / rmax) ** 2.8 * 0.85)
            sp[x, y] = tuple(round(b * (1 - t) + k * t) for b, k in zip(_LUMON_BLUE, _LUMON_BLACK))
    field = _dither_calibrated(small.resize((width, height), Image.Resampling.BICUBIC), _LUMON_INKS)
    # The housing: the beige of the show's terminals, white with a yellow
    # quarter, with the glass opening cut out of it.
    _fill_swatch_stipple(image, (0, 0, width, height), SPECTRA6["white"], SPECTRA6["yellow"], 0.25)
    h = _LUMON_HOUSING
    ImageDraw.Draw(image).rounded_rectangle((h, h, width - h, height - h), radius=_LUMON_BEZEL_RADIUS + _LUMON_GAP,
                                            fill=SPECTRA6["black"])
    b = _LUMON_BEZEL
    mask = Image.new("L", (width, height), 0)
    ImageDraw.Draw(mask).rounded_rectangle((b, b, width - b, height - b), radius=_LUMON_BEZEL_RADIUS, fill=255)
    paint_neon_mask(image, mask, None, SPECTRA6["blue"], radius=5, gamma=1.6, cap=0.5, ground=(SPECTRA6["black"],))
    image.paste(field, (0, 0), mask)
    small.close()
    field.close()
    mask.close()


def _lumon_paint_header(draw: ImageDraw.ImageDraw, hour: int, quote_row: dict) -> None:
    """The file name, the Lumon globe and wordmark, and the completion."""
    white = SPECTRA6["white"]
    x0, x1 = _LUMON_GRID_RECT[0], _LUMON_GRID_RECT[2]
    name_font = load_font([(INTER_VARIABLE, "Medium"), *META_FONT_BOLD_CANDIDATES], size=26)
    draw.text((x0, _LUMON_HEADER_Y), _lumon_file_name(quote_row), font=name_font, fill=white)
    # The globe: a circle with three latitude lines.
    gx, gy, gr = x1 - 18, _LUMON_HEADER_Y + 20, 16
    draw.ellipse((gx - gr, gy - gr, gx + gr, gy + gr), outline=white, width=2)
    for dy, half in ((-8, 13), (0, 16), (8, 13)):
        draw.line((gx - half, gy + dy, gx + half, gy + dy), fill=white, width=1)
    draw.line((gx, gy - gr, gx, gy + gr), fill=white, width=1)
    mark = load_font([MICHROMA_REGULAR, (JOST_VARIABLE, "Bold"), *ORNAMENT_FONT_CANDIDATES], size=14)
    right = gx - gr - 12
    draw.text((right - draw.textlength("LUMON", font=mark), _LUMON_HEADER_Y - 2), "LUMON", font=mark, fill=white)
    line = f"{_lumon_completion(hour)}% Complete"
    small = load_font([(INTER_VARIABLE, "Regular"), *META_FONT_CANDIDATES], size=15)
    draw.text((right - draw.textlength(line, font=small), _LUMON_HEADER_Y + 22), line, font=small, fill=white)
    draw.rectangle((x0, _LUMON_RULE_Y, x1, _LUMON_RULE_Y + 1), fill=white)


def _lumon_grid_cells():
    """The grid's cell boxes, row-major."""
    x0, y0, x1, y1 = _LUMON_GRID_RECT
    cw = (x1 - x0) / _LUMON_GRID_COLS
    ch = (y1 - y0) / _LUMON_GRID_ROWS
    return [[(x0 + c * cw, y0 + r * ch, x0 + (c + 1) * cw, y0 + (r + 1) * ch)
             for c in range(_LUMON_GRID_COLS)] for r in range(_LUMON_GRID_ROWS)]


def _lumon_cluster(hour: int) -> tuple[int, int]:
    """The scary cluster's top-left cell ``(row, col)``: the middle rows,
    the hour's column pair."""
    return 1, 2 * (hour - 1)


def _lumon_paint_grid(draw: ImageDraw.ImageDraw, hour: int, quote_row: dict) -> None:
    """The field of digits, seeded from the quote, with the hour's cluster
    boxed, a size larger and nudged off the grid."""
    white = SPECTRA6["white"]
    rng = random.Random(_LUMON_SEED ^ _row_digest(quote_row))
    cells = _lumon_grid_cells()
    plain = load_font([(MONTSERRAT_VARIABLE, "Medium"), *QUOTE_FONT_REGULAR_CANDIDATES], size=17)
    scary = load_font([(MONTSERRAT_VARIABLE, "Bold"), *QUOTE_FONT_BOLD_CANDIDATES], size=23)
    row0, col0 = _lumon_cluster(hour)
    for r, row in enumerate(cells):
        for c, (cx0, cy0, cx1, cy1) in enumerate(row):
            digit = str(rng.randint(0, 9))
            in_cluster = row0 <= r <= row0 + 1 and col0 <= c <= col0 + 1
            font = scary if in_cluster else plain
            dx = rng.randint(-2, 2) if in_cluster else 0
            dy = rng.randint(-2, 2) if in_cluster else 0
            tw = draw.textlength(digit, font=font)
            th = _font_ascent(font)
            draw.text((cx0 + (cx1 - cx0 - tw) / 2 + dx, cy0 + (cy1 - cy0 - th) / 2 - 2 + dy), digit, font=font,
                      fill=white)
    bx0, by0 = cells[row0][col0][0], cells[row0][col0][1]
    bx1, by1 = cells[row0 + 1][col0 + 1][2], cells[row0 + 1][col0 + 1][3]
    draw.rectangle((round(bx0) - 3, round(by0) - 3, round(bx1) + 3, round(by1) + 3), outline=white, width=1)


def _lumon_layout(draw: ImageDraw.ImageDraw, quote_row: dict):
    """The quote's lines on the terminal, with the bold chunks positioned."""
    return _place_quote(draw, quote_row, _LUMON_QUOTE_RECT, theme="lumon",
                        font_max=30, font_min=14, line_height_mult=1.32)


def _lumon_hover_boxes(draw: ImageDraw.ImageDraw, placed) -> list:
    """One box per run of bold chunks on a line — the phrase, not each
    word — trimmed to the run's inked extent."""
    boxes = []
    run = None
    for x, y, chunk, font, is_bold, w, lh in placed:
        if not is_bold or not chunk.strip():
            if run is not None and (not is_bold or run[1] != y):
                boxes.append(run)
                run = None
            if is_bold and run is not None:
                run = (run[0], run[1], x + w, run[3])
            continue
        lead = draw.textlength(chunk, font=font) - draw.textlength(chunk.lstrip(), font=font)
        trail = draw.textlength(chunk, font=font) - draw.textlength(chunk.rstrip(), font=font)
        x0, x1 = round(x + lead), round(x + w - trail)
        if run is not None and run[1] == y:
            run = (run[0], y, x1, lh)
        else:
            if run is not None:
                boxes.append(run)
            run = (x0, y, x1, lh)
    if run is not None:
        boxes.append(run)
    return [(x0 - 3, y - 2, x1 + 2, y + lh - 6) for x0, y, x1, lh in boxes]


def _lumon_paint_quote(draw: ImageDraw.ImageDraw, placed) -> None:
    """White Montserrat; the matched phrase Bold in yellow inside the
    refiner's white hover box."""
    white, yellow = SPECTRA6["white"], SPECTRA6["yellow"]
    for box in _lumon_hover_boxes(draw, placed):
        draw.rectangle(box, outline=white, width=1)
    _paint_placed(draw, placed, white, yellow)


def _lumon_paint_byline(draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """Author and title under the quote, in Inter."""
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "").strip()
    parts = [p for p in (author, title) if p]
    if not parts:
        return
    x0 = _LUMON_QUOTE_RECT[0]
    font, text = fit_text_to_width(draw, " — ".join(parts), [(INTER_VARIABLE, "Regular"), *META_FONT_CANDIDATES],
                                   16, _LUMON_QUOTE_RECT[2] - x0, floor=13)
    draw.text((x0, _LUMON_BYLINE_Y), text, font=font, fill=SPECTRA6["white"])


def _lumon_paint_bins(image: Image.Image, quote_row: dict) -> None:
    """The five bins along the foot, each boxed with a stippled progress bar
    at a level seeded from the quote."""
    draw = ImageDraw.Draw(image)
    white, blue = SPECTRA6["white"], SPECTRA6["blue"]
    x0, y0, x1, y1 = _LUMON_BINS_RECT
    width = (x1 - x0 - 4 * _LUMON_BIN_GAP) // 5
    rng = random.Random(_LUMON_SEED + 3 + _row_digest(quote_row))
    label = load_font([(MONTSERRAT_VARIABLE, "Medium"), *QUOTE_FONT_REGULAR_CANDIDATES], size=14)
    small = load_font([(MONTSERRAT_VARIABLE, "Medium"), *QUOTE_FONT_REGULAR_CANDIDATES], size=11)
    for i in range(5):
        bx0 = x0 + i * (width + _LUMON_BIN_GAP)
        bx1 = bx0 + width
        draw.rectangle((bx0, y0, bx1, y1), outline=white, width=1)
        draw.text((bx0 + 8, y0 + 5), f"0{i}", font=label, fill=white)
        level = rng.randint(4, 96)
        pct = f"{level}%"
        draw.text((bx1 - 8 - draw.textlength(pct, font=small), y0 + 7), pct, font=small, fill=white)
        bar = (bx0 + 8, y1 - 16, bx1 - 8, y1 - 7)
        draw.rectangle(bar, outline=white, width=1)
        fill_w = round((bar[2] - bar[0] - 4) * level / 100)
        if fill_w > 0:
            _fill_swatch_stipple(image, (bar[0] + 2, bar[1] + 2, bar[0] + 2 + fill_w, bar[3] - 1), blue, white, 0.5)


def render_lumon_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """The Macrodata Refinement terminal with the hour's file completion and
    the scary cluster in the hour's column (see the section comment above)."""
    hour = _clock_hour12(time_str)
    image = _lumon_scene().copy()
    draw = ImageDraw.Draw(image)
    _lumon_paint_header(draw, hour, quote_row)
    _lumon_paint_grid(draw, hour, quote_row)
    _lumon_paint_quote(draw, _lumon_layout(draw, quote_row))
    _lumon_paint_byline(draw, quote_row)
    _lumon_paint_bins(image, quote_row)
    b = _LUMON_BEZEL
    _crt_paint_scanlines(image, (b, b, 800 - b, 480 - b), (SPECTRA6["blue"],), period=_LUMON_SCANLINE_PERIOD)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# dsky — the Apollo Guidance Computer's display and keyboard (1966–1972)
# ---------------------------------------------------------------------------
# The Apollo Guidance Computer's display and keyboard (Block II geometry) on
# the grey main console, with a typed flight-plan page clipped beside it. Full
# design notes: docs/themes.md (``dsky``).
#
# The console and the unit are modelled in continuous tone (grey panel with a
# brushed grain, a shaded rim, domed keycaps, shaded screws, recessed dark
# windows, a reflection across the display, soft shadows) and Floyd–Steinberg
# dithered to white and black (``_dither_calibrated``); the card, legends,
# segments, lit lamp and type go on after the dither.
#
# The flight plan is typed in Special Elite in black, with the matched phrase
# in red like the pen-and-ink updates.
#
# The hour is the program: the PROG register shows 01..12, pinned across the
# minutes. VERB 06 NOUN 62 stays up and the three registers are telemetry
# seeded from the quote. Each digit is a true seven-segment glyph in a mask
# (``_dsky_draw_glyph``), painted white-hot with a green bloom through
# ``paint_neon_mask`` with ``ground`` pinned to black. COMP ACTY is the one
# lit lamp, solid green. Composed at 800x480 and NEAREST-downsampled otherwise
# (the ``metro`` convention).
# ---------------------------------------------------------------------------
_DSKY_SEED = 0x44534B59               # DSKY
_DSKY_INKS = ("white", "black")
_DSKY_PANEL = 0.52                    # the console grey, as a fraction of the way to black
_DSKY_CARD_RECT = (30, 34, 452, 452)
_DSKY_QUOTE_RECT = (54, 104, 428, 384)
_DSKY_BYLINE_Y = 404
_DSKY_UNIT_RECT = (476, 18, 786, 464)
_DSKY_RIM = 10
_DSKY_LAMP_WINDOW = (494, 40, 632, 230)
_DSKY_LAMP_ORIGIN = (501, 48)
_DSKY_LAMP_SIZE = (60, 21)
_DSKY_LAMP_GAP = (5, 5)
_DSKY_LAMPS = (("UPLINK", "TEMP"), ("NO ATT", "GIMBAL"), ("STBY", "PROG"), ("KEY REL", "RESTART"),
               ("OPR ERR", "TRACKER"), ("", "ALT"), ("", "VEL"))
_DSKY_DISPLAY_RECT = (642, 40, 770, 230)
_DSKY_KEYPAD_ORIGIN = (497, 252)
_DSKY_KEY = 36
_DSKY_KEY_GAP = 5
_DSKY_KEYS = (("VERB", "+", "7", "8", "9", "CLR", "ENTR"),
              ("NOUN", "-", "4", "5", "6", "PRO", "RSET"),
              ("", "0", "1", "2", "3", "KEY\nREL", ""))
_DSKY_VERB, _DSKY_NOUN = "06", "62"
_DSKY_SCENE: dict = {}
# Seven-segment encodings: a top, b upper right, c lower right, d bottom,
# e lower left, f upper left, g middle.
_DSKY_SEGMENTS = {
    "0": "abcdef", "1": "bc", "2": "abged", "3": "abgcd", "4": "fgbc", "5": "afgcd",
    "6": "afgedc", "7": "abc", "8": "abcdefg", "9": "abcdfg", "-": "g", "+": "g|", " ": "",
}


def _dsky_tone(t: float) -> tuple[int, int, int]:
    """A grey ``t`` of the way from the white ink to the black ink."""
    return tuple(round(w + (k - w) * t) for w, k in zip(_PANEL_INKS["white"], _PANEL_INKS["black"]))


def _dsky_segments(ch: str) -> str:
    return _DSKY_SEGMENTS.get(ch, "")


def _dsky_draw_glyph(draw: ImageDraw.ImageDraw, x: int, y: int, ch: str, *, h: int = 22, w: int = 12,
                     t: int = 3) -> None:
    """One seven-segment character into an ``L`` mask at (x, y)."""
    segs = _dsky_segments(ch)
    mid = y + h // 2
    if "a" in segs:
        draw.rectangle((x + 1, y, x + w - 1, y + t - 1), fill=255)
    if "b" in segs:
        draw.rectangle((x + w - t, y + 1, x + w - 1, mid - 1), fill=255)
    if "c" in segs:
        draw.rectangle((x + w - t, mid + 1, x + w - 1, y + h - 1), fill=255)
    if "d" in segs:
        draw.rectangle((x + 1, y + h - t, x + w - 1, y + h - 1), fill=255)
    if "e" in segs:
        draw.rectangle((x, mid + 1, x + t - 1, y + h - 1), fill=255)
    if "f" in segs:
        draw.rectangle((x, y + 1, x + t - 1, mid - 1), fill=255)
    if "g" in segs:
        draw.rectangle((x + 1, mid - t // 2, x + w - 1, mid - t // 2 + t - 1), fill=255)
    if "|" in segs:
        draw.rectangle((x + w // 2 - t // 2, mid - 6, x + w // 2 - t // 2 + t - 1, mid + 6), fill=255)


def _dsky_registers(quote_row: dict) -> list[str]:
    """Three signed five-digit registers of telemetry, seeded from the quote."""
    rng = random.Random(_DSKY_SEED ^ _row_digest(quote_row))
    return [f"{rng.choice('+-')}{rng.randint(0, 99999):05d}" for _ in range(3)]


def _dsky_label_font(size: int):
    return load_font([(JOST_VARIABLE, "Medium"), *META_FONT_BOLD_CANDIDATES], size=size)


def _dsky_key_rects() -> list:
    rects = []
    ox, oy = _DSKY_KEYPAD_ORIGIN
    k, g = _DSKY_KEY, _DSKY_KEY_GAP
    for r, row in enumerate(_DSKY_KEYS):
        for c, label in enumerate(row):
            if label:
                x, y = ox + c * (k + g), oy + r * (k + g)
                rects.append((x, y, x + k, y + k, label))
    return rects


def _dsky_lamp_rects() -> list:
    rects = []
    ox, oy = _DSKY_LAMP_ORIGIN
    w, h = _DSKY_LAMP_SIZE
    gx, gy = _DSKY_LAMP_GAP
    for r, row in enumerate(_DSKY_LAMPS):
        for c, label in enumerate(row):
            x, y = ox + c * (w + gx), oy + r * (h + gy)
            rects.append((x, y, x + w, y + h, label))
    return rects


def _dsky_paint_console(scene: Image.Image) -> None:
    """The grey panel with its brushed grain, the unit's shadow and the
    card's shadow."""
    size = scene.size
    scene.paste(Image.new("RGB", size, _dsky_tone(_DSKY_PANEL)), (0, 0))
    grain = _smooth_noise(size, (200, 9), _DSKY_SEED + 1).point(lambda v: v * 14 // 255)
    scene.paste(ImageChops.subtract(ImageChops.add(scene, Image.merge("RGB", (grain, grain, grain))),
                                    Image.new("RGB", size, (7, 7, 7))))
    for rect, blur, depth in ((_DSKY_UNIT_RECT, 6, 0.86), (_DSKY_CARD_RECT, 4, 0.80)):
        shadow = Image.new("L", size, 0)
        ImageDraw.Draw(shadow).rounded_rectangle((rect[0] + 5, rect[1] + 6, rect[2] + 7, rect[3] + 8), radius=8, fill=255)
        shadow = shadow.filter(ImageFilter.GaussianBlur(blur)).point(lambda v: int(v * 0.8))
        scene.paste(Image.new("RGB", size, _dsky_tone(depth)), (0, 0), shadow)
        shadow.close()


def _dsky_paint_unit(scene: Image.Image) -> None:
    """The unit in tone: the black face plate with a raised, lit rim, the
    recessed windows, the reflection, the keycaps, the screws."""
    size = scene.size
    x0, y0, x1, y1 = _DSKY_UNIT_RECT
    draw = ImageDraw.Draw(scene)
    # The face plate, and the rim modelled as a ring under the upper-left light.
    plate = Image.new("L", size, 0)
    ImageDraw.Draw(plate).rounded_rectangle((x0, y0, x1, y1), radius=10, fill=255)
    rim = ImageChops.subtract(plate, plate.filter(ImageFilter.MinFilter(2 * _DSKY_RIM + 1)))
    shaded = _shade_silhouette(rim, _dsky_tone(0.80), _dsky_tone(0.40), _dsky_tone(0.97), offset=5, blur=3)
    scene.paste(Image.new("RGB", size, _dsky_tone(0.90)), (0, 0), plate)
    scene.paste(shaded, (0, 0), rim)
    # The windows: recessed dark glass, a touch lighter at their top edge.
    for wx0, wy0, wx1, wy1 in (_DSKY_LAMP_WINDOW, _DSKY_DISPLAY_RECT):
        draw.rectangle((wx0, wy0, wx1, wy1), fill=_dsky_tone(0.96))
        draw.rectangle((wx0, wy0, wx1, wy0 + 2), fill=_dsky_tone(0.70))
        draw.rectangle((wx0, wy0, wx0 + 2, wy1), fill=_dsky_tone(0.78))
    # The unlit lamps: smoked glass a shade above the window.
    for lx0, ly0, lx1, ly1, label in _dsky_lamp_rects():
        draw.rectangle((lx0, ly0, lx1, ly1), fill=_dsky_tone(0.92))
    # A reflection across the display glass.
    reflection = Image.new("L", size, 0)
    dx0, dy0, dx1, dy1 = _DSKY_DISPLAY_RECT
    ImageDraw.Draw(reflection).polygon([(dx0 + 30, dy0), (dx0 + 70, dy0), (dx1, dy1 - 70), (dx1, dy1 - 30)], fill=255)
    reflection = reflection.filter(ImageFilter.GaussianBlur(6)).point(lambda v: int(v * 0.22))
    scene.paste(Image.new("RGB", size, _dsky_tone(0.40)), (0, 0), reflection)
    # The keypad: a recessed grey tray, and on it the keycaps — near-black
    # domes with a lit upper-left edge and a core shadow, so each key reads
    # as a dark square on the lighter tray.
    rects = _dsky_key_rects()
    tx0 = min(r[0] for r in rects) - 8
    ty0 = min(r[1] for r in rects) - 8
    tx1 = max(r[2] for r in rects) + 8
    ty1 = max(r[3] for r in rects) + 8
    draw.rounded_rectangle((tx0, ty0, tx1, ty1), radius=6, fill=_dsky_tone(0.62))
    draw.rectangle((tx0, ty0, tx1, ty0 + 2), fill=_dsky_tone(0.80))
    keys = Image.new("L", size, 0)
    kd = ImageDraw.Draw(keys)
    for kx0, ky0, kx1, ky1, label in rects:
        kd.rounded_rectangle((kx0, ky0, kx1, ky1), radius=6, fill=255)
    caps = _shade_silhouette(keys, _dsky_tone(0.90), _dsky_tone(0.40), _dsky_tone(0.99), offset=4, blur=3)
    scene.paste(caps, (0, 0), keys)
    # Screws at the plate's corners.
    for sx, sy in ((x0 + 14, y0 + 14), (x1 - 14, y0 + 14), (x0 + 14, y1 - 14), (x1 - 14, y1 - 14)):
        screw = Image.new("L", size, 0)
        ImageDraw.Draw(screw).ellipse((sx - 5, sy - 5, sx + 5, sy + 5), fill=255)
        head = _shade_silhouette(screw, _dsky_tone(0.55), _dsky_tone(0.20), _dsky_tone(0.92), offset=3, blur=2)
        scene.paste(head, (0, 0), screw)
        screw.close()
    for m in (plate, rim, shaded, reflection, keys, caps):
        m.close()


def _dsky_scene() -> Image.Image:
    """The console, the unit and the card — everything the hour and the
    quote do not touch — dithered. Painted once per process."""
    key = (_dsky_paint_console, _dsky_paint_unit, _dsky_paint_card)
    cached = _DSKY_SCENE.get("frame")
    if cached is not None and cached[0] == key:
        return cached[1]
    size = (800, 480)
    scene = Image.new("RGB", size, _PANEL_INKS["white"])
    _dsky_paint_console(scene)
    _dsky_paint_unit(scene)
    image = _dither_calibrated(scene, _DSKY_INKS)
    _dsky_paint_card(image)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)       # the card's typed header is antialiased
    _DSKY_SCENE["frame"] = (key, image)
    return image


def _dsky_paint_card(image: Image.Image) -> None:
    """The flight-plan card after the dither: cream paper, a hairline edge,
    the clip at its head, the typed header and rule."""
    draw = ImageDraw.Draw(image)
    x0, y0, x1, y1 = _DSKY_CARD_RECT
    black, white = SPECTRA6["black"], SPECTRA6["white"]
    _fill_swatch_stipple(image, (x0, y0, x1, y1), white, SPECTRA6["yellow"], 0.25)
    draw.rectangle((x0, y0, x1, y1), outline=black, width=1)
    # The clip: a bulldog clip's two plates and its loop, in solid inks.
    cx = (x0 + x1) // 2
    draw.rounded_rectangle((cx - 34, y0 - 10, cx + 34, y0 + 14), radius=4, fill=black)
    draw.rectangle((cx - 30, y0 - 6, cx + 30, y0 + 10), outline=white, width=1)
    draw.arc((cx - 16, y0 - 22, cx + 16, y0 + 2), 180, 360, fill=black, width=4)
    font = load_font([SPECIALELITE_REGULAR, *META_FONT_CANDIDATES], size=13)
    draw.text((x0 + 24, y0 + 30), "APOLLO FLIGHT PLAN      CSM/LM TIMELINE", font=font, fill=black)
    draw.text((x1 - 24 - draw.textlength("PAGE 3-61", font=font), y0 + 30), "PAGE 3-61", font=font, fill=black)
    draw.line((x0 + 24, y0 + 52, x1 - 24, y0 + 52), fill=black, width=1)
    for hx in range(x0 + 10, x1 - 10, 2):
        draw.point((hx, y0 + 18), fill=black)


def _dsky_paint_legends(draw: ImageDraw.ImageDraw) -> None:
    """After the dither: the lamp words, the key caps' legends, the window
    labels and the nameplate."""
    white, black = SPECTRA6["white"], SPECTRA6["black"]
    font = _dsky_label_font(10)
    for lx0, ly0, lx1, ly1, label in _dsky_lamp_rects():
        draw.rectangle((lx0, ly0, lx1, ly1), outline=black, width=1)
        if label:
            tw = draw.textlength(label, font=font)
            draw.text((lx0 + (lx1 - lx0 - tw) / 2, ly0 + 5), label, font=font, fill=white,
                      stroke_width=1, stroke_fill=black)
    for kx0, ky0, kx1, ky1, label in _dsky_key_rects():
        lines = label.split("\n")
        ty = ky0 + (_DSKY_KEY - 12 * len(lines)) / 2
        for line in lines:
            tw = draw.textlength(line, font=font)
            draw.text((kx0 + (_DSKY_KEY - tw) / 2, ty), line, font=font, fill=white, stroke_width=1, stroke_fill=black)
            ty += 12
    small = _dsky_label_font(9)
    ux0, uy0, ux1, uy1 = _DSKY_UNIT_RECT
    label = "DSKY  ·  BLOCK II"
    lx = (ux0 + ux1) / 2 - tracked_width(draw, label, small, tracking=2) / 2
    draw.rectangle((lx - 6, uy1 - 24, lx + tracked_width(draw, label, small, tracking=2) + 6, uy1 - 10), fill=black)
    draw_tracked(draw, (lx, uy1 - 22), label, small, white, tracking=2)


def _dsky_paint_display(image: Image.Image, hour: int, quote_row: dict) -> None:
    """PROG / VERB / NOUN and the three registers as glowing segments; the
    COMP ACTY lamp lit in green."""
    draw = ImageDraw.Draw(image)
    x0, y0, x1, y1 = _DSKY_DISPLAY_RECT
    white, green, black = SPECTRA6["white"], SPECTRA6["green"], SPECTRA6["black"]
    font = _dsky_label_font(10)
    draw.rectangle((x0 + 8, y0 + 8, x0 + 40, y0 + 36), fill=green)
    draw.text((x0 + 10, y0 + 11), "COMP", font=font, fill=black)
    draw.text((x0 + 10, y0 + 22), "ACTY", font=font, fill=black)
    mask = Image.new("L", image.size, 0)
    md = ImageDraw.Draw(mask)
    pair_x = x1 - 8 - 2 * 16
    draw.text((pair_x, y0 + 8), "PROG", font=font, fill=white)
    for i, ch in enumerate(f"{hour:02d}"):
        _dsky_draw_glyph(md, pair_x + i * 16, y0 + 22, ch, h=18, w=11)
    row_y = y0 + 52
    for label, value, lx in (("VERB", _DSKY_VERB, x0 + 8), ("NOUN", _DSKY_NOUN, pair_x)):
        draw.text((lx, row_y), label, font=font, fill=white)
        for i, ch in enumerate(value):
            _dsky_draw_glyph(md, lx + i * 16, row_y + 14, ch, h=18, w=11)
    draw.rectangle((x0 + 8, row_y + 40, x1 - 8, row_y + 40), fill=white)
    reg_y = row_y + 48
    for r, value in enumerate(_dsky_registers(quote_row)):
        y = reg_y + r * 40
        for i, ch in enumerate(value):
            _dsky_draw_glyph(md, x0 + 10 + i * 19, y, ch, h=24, w=13)
        if r < 2:
            draw.rectangle((x0 + 8, y + 32, x1 - 8, y + 32), fill=white)
    paint_neon_mask(image, mask, white, green, radius=4, gamma=1.4, cap=0.6, ground=(black,))
    mask.close()


def _dsky_layout(draw: ImageDraw.ImageDraw, quote_row: dict):
    return _place_quote(draw, quote_row, _DSKY_QUOTE_RECT, theme="dsky",
                        font_max=28, font_min=15, line_height_mult=1.42)


def _dsky_paint_quote(draw: ImageDraw.ImageDraw, placed) -> None:
    """Typed on the card: black, with the matched phrase in red ink."""
    _paint_placed(draw, placed, SPECTRA6["black"], SPECTRA6["red"])


def _dsky_paint_byline(draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """Author and title typed under the quote."""
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "").strip()
    parts = [p.upper() for p in (author, title) if p]
    if not parts:
        return
    x0 = _DSKY_QUOTE_RECT[0]
    font, text = fit_text_to_width(draw, "  /  ".join(parts), [SPECIALELITE_REGULAR, *META_FONT_CANDIDATES],
                                   14, _DSKY_QUOTE_RECT[2] - x0, floor=12)
    draw.text((x0, _DSKY_BYLINE_Y), text, font=font, fill=SPECTRA6["black"])


def render_dsky_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """The Apollo DSKY on its console, the hour in its PROG register, the
    quote typed on the flight plan beside it (see the section comment above)."""
    hour = _clock_hour12(time_str)
    image = _dsky_scene().copy()
    draw = ImageDraw.Draw(image)
    _dsky_paint_legends(draw)
    _dsky_paint_display(image, hour, quote_row)
    draw = ImageDraw.Draw(image)
    _dsky_paint_quote(draw, _dsky_layout(draw, quote_row))
    _dsky_paint_byline(draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# oblivion — *Oblivion* (2013): the Sky Tower's light table
# ---------------------------------------------------------------------------
# The Sky Tower's desk is a light table whose glass is the interface: a glow
# pooled under the hand, frosted panes, hairline geometry, a topographic map
# with the hydro rigs, a drone, and one warm accent. Full design notes:
# docs/themes.md (``oblivion``).
#
# The glass (grey edges, a white pool under the quote, darker soft-edged
# panes, the drone's blurred shadow, a fine grain) and the drone (a sphere
# shaded by ``shade_height_field``, pods by ``_shade_silhouette``) are painted in
# continuous tone and Floyd–Steinberg dithered to white and black
# (``_dither_calibrated``). The map's contours (a seeded height field sliced at
# ``_OBLIVION_CONTOUR_LEVELS`` levels, each slice's one-pixel rim), the
# hairlines, the type and the red go on after the dither.
#
# The hour is the rig and the bearing: the hour's rig is red with a leader to
# its number, the dial's tick at the hour's clock-face position is a red wedge
# with a red dot on station, and the hour's cell in the status row is filled.
# All pinned across the minutes; the matched phrase carries the minute. The
# waveform and numeral columns are seeded from the quote. Composed at 800x480
# and NEAREST-downsampled otherwise (the ``metro`` convention).
# ---------------------------------------------------------------------------
_OBLIVION_SEED = 0x4F424C56           # OBLV
_OBLIVION_INKS = ("white", "black")
_OBLIVION_QUOTE_RECT = (40, 112, 450, 366)
_OBLIVION_BYLINE_Y = 380
_OBLIVION_MAP_RECT = (470, 104, 770, 398)
_OBLIVION_DIAL_CENTRE = (600, 270)
_OBLIVION_DIAL_RADII = (112, 86, 34)
_OBLIVION_DRONE_CENTRE = (728, 146)
_OBLIVION_DRONE_RADIUS = 34
_OBLIVION_WAVE_RECT = (40, 416, 450, 458)
_OBLIVION_RIG_BAND = (470, 416, 770, 458)
_OBLIVION_RIG_GAP = 4
_OBLIVION_CONTOUR_LEVELS = 5
_OBLIVION_SCENE: dict = {}
# Calibrated end points of ``_oblivion_tone``: the white ink is the pool.
_OBLIVION_WHITE = _PANEL_INKS["white"]
_OBLIVION_BLACK = _PANEL_INKS["black"]


def _oblivion_tone(t: float) -> tuple[int, int, int]:
    """A grey ``t`` of the way from the white ink to the black ink."""
    return tuple(round(w + (k - w) * t) for w, k in zip(_OBLIVION_WHITE, _OBLIVION_BLACK))


def _oblivion_font(size: int, instance: str = "Light"):
    return load_font([(EXO2_VARIABLE, instance), *META_FONT_CANDIDATES], size=size)


def _oblivion_polar(radius: float, hour: int) -> tuple[float, float]:
    cx, cy = _OBLIVION_DIAL_CENTRE
    a = math.radians((hour % 12) * 30)
    return cx + radius * math.sin(a), cy - radius * math.cos(a)


def _oblivion_rig_rects() -> list:
    x0, y0, x1, y1 = _OBLIVION_RIG_BAND
    width = (x1 - x0 - 11 * _OBLIVION_RIG_GAP) // 12
    return [(x0 + i * (width + _OBLIVION_RIG_GAP), y0, x0 + i * (width + _OBLIVION_RIG_GAP) + width, y1)
            for i in range(12)]


def _oblivion_numeral_rect() -> tuple[int, int, int, int]:
    """The column of readouts at the map's upper left, under its label."""
    x0, y0, x1, y1 = _OBLIVION_MAP_RECT
    return (x0 + 4, y0 + 22, x0 + 62, y0 + 92)


def _oblivion_rig_points() -> list:
    """The twelve rigs' positions on the map, seeded, kept off the dial's
    hub and inside the pane."""
    rng = random.Random(_OBLIVION_SEED + 3)
    x0, y0, x1, y1 = _OBLIVION_MAP_RECT
    cx, cy = _OBLIVION_DIAL_CENTRE
    points = []
    while len(points) < 12:
        x, y = rng.randint(x0 + 22, x1 - 22), rng.randint(y0 + 22, y1 - 22)
        if math.hypot(x - cx, y - cy) < _OBLIVION_DIAL_RADII[2] + 14:
            continue
        if math.hypot(x - _OBLIVION_DRONE_CENTRE[0], y - _OBLIVION_DRONE_CENTRE[1]) < _OBLIVION_DRONE_RADIUS + 26:
            continue
        nx0, ny0, nx1, ny1 = _oblivion_numeral_rect()
        if nx0 - 12 <= x <= nx1 + 20 and ny0 - 12 <= y <= ny1 + 12:
            continue
        if any(math.hypot(x - px, y - py) < 30 for px, py in points):
            continue
        points.append((x, y))
    return points


def _oblivion_paint_glass(scene: Image.Image) -> Image.Image:
    """The light table in continuous tone: grey glass, the white pool under
    the quote, the frosted panes, the drone's shadow, the grain. Returns the
    pool's mask, whose saturated heart is cleaned after the dither."""
    size = scene.size
    scene.paste(Image.new("RGB", size, _oblivion_tone(0.07)), (0, 0))
    # Saturated inside so the pool's heart is clean white; the blur only softens its edge.
    pool = _soft_ellipse_mask(size, (-60, 30, 540, 430), 50).point(lambda v: min(255, v * 2))
    scene.paste(Image.new("RGB", size, _OBLIVION_WHITE), (0, 0), pool)
    # The panes: the map and the two strips, a shade darker with soft edges.
    for rect in (_OBLIVION_MAP_RECT, _OBLIVION_WAVE_RECT, _OBLIVION_RIG_BAND):
        pane = Image.new("L", size, 0)
        ImageDraw.Draw(pane).rectangle(rect, fill=255)
        pane = pane.filter(ImageFilter.GaussianBlur(2)).point(lambda v: int(v * 0.55))
        scene.paste(Image.new("RGB", size, _oblivion_tone(0.13)), (0, 0), pane)
    # The drone's shadow on the glass beneath it.
    dx, dy = _OBLIVION_DRONE_CENTRE
    r = _OBLIVION_DRONE_RADIUS
    shadow = _soft_ellipse_mask(size, (dx - r + 2, dy + r + 6, dx + r + 12, dy + r + 22), 6).point(lambda v: int(v * 0.4))
    scene.paste(Image.new("RGB", size, _oblivion_tone(0.34)), (0, 0), shadow)
    # The glass's grain, kept out of the pool so the quote sits on clean white.
    grain = _smooth_noise(size, (120, 72), _OBLIVION_SEED + 1).point(lambda v: v * 6 // 255)
    grain = ImageChops.multiply(grain, pool.point(lambda v: 255 - v))
    scene.paste(ImageChops.subtract(ImageChops.add(scene, Image.merge("RGB", (grain, grain, grain))),
                                    Image.new("RGB", size, (3, 3, 3))))
    shadow.close()
    return pool


def _oblivion_paint_drone_tone(scene: Image.Image) -> None:
    """The drone before the dither: a shaded sphere and two shaded pods."""
    size = scene.size
    cx, cy = _OBLIVION_DRONE_CENTRE
    r = _OBLIVION_DRONE_RADIUS
    pods = Image.new("L", size, 0)
    pd = ImageDraw.Draw(pods)
    pd.rounded_rectangle((cx - r - 16, cy - 9, cx - r + 8, cy + 11), radius=5, fill=255)
    pd.rounded_rectangle((cx + r - 8, cy - 9, cx + r + 16, cy + 11), radius=5, fill=255)
    shaded = _shade_silhouette(pods, _oblivion_tone(0.34), _oblivion_tone(0.08), _oblivion_tone(0.66), offset=4, blur=3)
    disc = Image.new("L", size, 0)
    ImageDraw.Draw(disc).ellipse((cx - r, cy - r, cx + r, cy + r), fill=255)
    field = disc.filter(ImageFilter.GaussianBlur(r * 0.55))
    tone = shade_height_field(field, relief=0.03, ambient=0.18, diffuse=0.75, specular=0.9, shininess=30)
    # Map the shading onto the white hull: lit faces to the white ink, the
    # terminator toward a mid grey, never full black — it is white plastic.
    def hull_tone(v, lo=60, hi=150):
        t = max(0.0, min(1.0, (v - lo) / (hi - lo)))
        return _oblivion_tone(0.55 * (1.0 - t))

    lut = [hull_tone(v) for v in range(256)]
    hull = Image.merge("RGB", tuple(tone.point([lut[v][c] for v in range(256)]) for c in range(3)))
    scene.paste(hull, (0, 0), disc)
    # The pods, mounted either side of the hull.
    scene.paste(shaded, (0, 0), ImageChops.subtract(pods, disc))
    for m in (pods, shaded, disc, field, tone, hull):
        m.close()


def _oblivion_contours(size) -> Image.Image:
    """The map's contour lines as an ``L`` mask: a seeded height field
    sliced at ``_OBLIVION_CONTOUR_LEVELS`` levels, each slice's one-pixel rim."""
    x0, y0, x1, y1 = _OBLIVION_MAP_RECT
    w, h = x1 - x0, y1 - y0
    field = _smooth_noise((w, h), (5, 4), _OBLIVION_SEED + 2)
    lines = Image.new("L", (w, h), 0)
    for level in range(1, _OBLIVION_CONTOUR_LEVELS + 1):
        cut = round(255 * level / (_OBLIVION_CONTOUR_LEVELS + 1))
        slab = field.point(lambda v, c=cut: 255 if v >= c else 0)
        rim = ImageChops.subtract(slab, slab.filter(ImageFilter.MinFilter(3)))
        lines = ImageChops.lighter(lines, rim)
    mask = Image.new("L", size, 0)
    mask.paste(lines, (x0 + 1, y0 + 1))
    inner = Image.new("L", size, 0)
    idr = ImageDraw.Draw(inner)
    idr.rectangle((x0 + 2, y0 + 2, x1 - 2, y1 - 2), fill=255)
    # The hub of the dial and the drone's station are clear glass.
    cx, cy = _OBLIVION_DIAL_CENTRE
    r1 = _OBLIVION_DIAL_RADII[1]
    idr.ellipse((cx - r1, cy - r1, cx + r1, cy + r1), fill=0)
    # And the numeral column at the pane's upper left.
    idr.rectangle(_oblivion_numeral_rect(), fill=0)
    dx, dy = _OBLIVION_DRONE_CENTRE
    dr = _OBLIVION_DRONE_RADIUS + 4
    idr.ellipse((dx - dr, dy - dr, dx + dr, dy + dr), fill=0)
    return ImageChops.multiply(mask, inner)


def _oblivion_scene() -> Image.Image:
    """The glass, the panes, the drone and the contours — everything the
    hour and the quote do not touch. Painted once per process."""
    key = (_oblivion_paint_glass, _oblivion_paint_drone_tone, _oblivion_contours)
    cached = _OBLIVION_SCENE.get("frame")
    if cached is not None and cached[0] == key:
        return cached[1]
    size = (800, 480)
    scene = Image.new("RGB", size, _OBLIVION_WHITE)
    pool = _oblivion_paint_glass(scene)
    _oblivion_paint_drone_tone(scene)
    image = _dither_calibrated(scene, _OBLIVION_INKS)
    # Error diffusion carries the grey glass's residue a little way into the
    # pool; wipe its saturated heart back to white.
    if pool is not None:        # the decoration fence neuters the glass painter
        image.paste(Image.new("RGB", size, SPECTRA6["white"]), (0, 0), pool.point(lambda v: 255 if v == 255 else 0))
        pool.close()
    image.paste(Image.new("RGB", size, SPECTRA6["black"]), (0, 0), _oblivion_contours(size))
    _OBLIVION_SCENE["frame"] = (key, image)
    return image


def _oblivion_paint_chrome(draw: ImageDraw.ImageDraw) -> None:
    """Corner brackets, the header's tracked capitals, the pane borders and
    the rules."""
    black = SPECTRA6["black"]
    for (x, y), (dx, dy) in (((20, 20), (1, 1)), ((780, 20), (-1, 1)), ((20, 460), (1, -1)), ((780, 460), (-1, -1))):
        draw.line((x, y, x + 18 * dx, y), fill=black, width=1)
        draw.line((x, y, x, y + 18 * dy), fill=black, width=1)
    font = _oblivion_font(13, "Regular")
    draw_tracked(draw, (40, 44), "TECH 49", _oblivion_font(22, "Regular"), black, tracking=4)
    draw_tracked(draw, (40, 74), "TOWER 49   ·   TET LINK ESTABLISHED", font, black, tracking=3)
    draw_tracked(draw, (760, 48), "SKY TOWER", font, black, tracking=3, anchor_right=True)
    draw_tracked(draw, (760, 68), "DRONE 166   ONLINE", font, black, tracking=3, anchor_right=True)
    draw.line((40, 96, 760, 96), fill=black, width=1)
    for rect in (_OBLIVION_MAP_RECT, _OBLIVION_WAVE_RECT, _OBLIVION_RIG_BAND):
        draw.rectangle(rect, outline=black, width=1)
    small = _oblivion_font(9, "Regular")
    x0, y0, x1, y1 = _OBLIVION_MAP_RECT
    draw.rectangle((x0 + 1, y0 + 1, x0 + 118, y0 + 18), fill=SPECTRA6["white"])
    draw_tracked(draw, (x0 + 8, y0 + 6), "SECTOR 17   ·   TOPO", small, black, tracking=2)
    draw_tracked(draw, (_OBLIVION_WAVE_RECT[0] + 8, _OBLIVION_WAVE_RECT[1] + 4), "HYDRO FLOW", small, black, tracking=2)
    draw_tracked(draw, (_OBLIVION_RIG_BAND[0] + 8, _OBLIVION_RIG_BAND[1] - 12), "RIG STATUS", small, black, tracking=2)


def _oblivion_paint_dial(draw: ImageDraw.ImageDraw, hour: int) -> None:
    """The dial over the map: hairline rings, a crosshair, twelve ticks, the
    hour's tick as a red wedge and a red dot on station."""
    black, red = SPECTRA6["black"], SPECTRA6["red"]
    cx, cy = _OBLIVION_DIAL_CENTRE
    r0, r1, r2 = _OBLIVION_DIAL_RADII
    for r in (r0, r1, r2):
        draw.ellipse((cx - r, cy - r, cx + r, cy + r), outline=black, width=1)
    draw.line((cx - r2 - 8, cy, cx + r2 + 8, cy), fill=black, width=1)
    draw.line((cx, cy - r2 - 8, cx, cy + r2 + 8), fill=black, width=1)
    draw.rectangle((cx - 4, cy - 4, cx + 4, cy + 4), fill=black)
    font = _oblivion_font(10, "Regular")
    for h in range(1, 13):
        (ax, ay), (bx, by) = _oblivion_polar(r0, h), _oblivion_polar(r0 - 8, h)
        draw.line((ax, ay, bx, by), fill=black, width=1)
        lx, ly = _oblivion_polar(r0 + 11, h)
        label = f"{(h % 12) * 30:03d}"
        draw.text((lx - draw.textlength(label, font=font) / 2, ly - 5), label, font=font, fill=black)
    a = math.radians((hour % 12) * 30)
    wedge = [(cx + r0 * math.sin(a + d), cy - r0 * math.cos(a + d)) for d in (-0.06, 0.06)]
    wedge += [(cx + (r0 - 12) * math.sin(a + d), cy - (r0 - 12) * math.cos(a + d)) for d in (0.06, -0.06)]
    draw.polygon(wedge, fill=red)
    dx, dy = _oblivion_polar((r1 + r2) / 2, hour)
    draw.ellipse((dx - 5, dy - 5, dx + 5, dy + 5), fill=red)
    draw.ellipse((dx - 9, dy - 9, dx + 9, dy + 9), outline=black, width=1)


def _oblivion_paint_rigs(image: Image.Image, hour: int) -> None:
    """The rigs on the map as hairline glyphs with their numbers; the hour's
    in red with a leader. And the status row along the foot, the hour's
    cell filled."""
    draw = ImageDraw.Draw(image)
    black, white, red = SPECTRA6["black"], SPECTRA6["white"], SPECTRA6["red"]
    font = _oblivion_font(9, "Regular")
    for i, (x, y) in enumerate(_oblivion_rig_points()):
        active = (i + 1) == hour
        if active:
            draw.ellipse((x - 6, y - 6, x + 6, y + 6), fill=red)
            draw.ellipse((x - 10, y - 10, x + 10, y + 10), outline=red, width=1)
            # The leader runs toward the pane's centre so the label stays inside it.
            side = -1 if x > (_OBLIVION_MAP_RECT[0] + _OBLIVION_MAP_RECT[2]) / 2 else 1
            draw.line((x + 10 * side, y, x + 24 * side, y - 12), fill=red, width=1)
            label = f"RIG {i + 1:02d}"
            lx = x + 26 if side > 0 else x - 26 - draw.textlength(label, font=font)
            draw.text((lx, y - 18), label, font=font, fill=red, stroke_width=2, stroke_fill=white)
        else:
            draw.ellipse((x - 5, y - 5, x + 5, y + 5), fill=white, outline=black, width=1)
            draw.ellipse((x - 1, y - 1, x + 1, y + 1), fill=black)
            draw.text((x + 8, y - 5), f"{i + 1:02d}", font=font, fill=black, stroke_width=2, stroke_fill=white)
    cell_font = _oblivion_font(9, "Regular")
    for i, (x0, y0, x1, y1) in enumerate(_oblivion_rig_rects()):
        active = (i + 1) == hour
        draw.rectangle((x0, y0 + 14, x1, y1 - 4), fill=black if active else None, outline=black, width=1)
        ink = white if active else black
        label = f"{i + 1:02d}"
        draw.text((x0 + (x1 - x0 - draw.textlength(label, font=cell_font)) / 2, y0 + 17), label, font=cell_font,
                  fill=ink)
        if active:
            draw.ellipse(((x0 + x1) / 2 - 3, y1 - 15, (x0 + x1) / 2 + 3, y1 - 9), fill=red)
        else:
            draw.rectangle(((x0 + x1) / 2 - 4, y1 - 13, (x0 + x1) / 2 + 4, y1 - 11), fill=black)


def _oblivion_paint_drone_detail(image: Image.Image) -> None:
    """After the dither: the lens, its catchlight, a red bloom into the
    glass, and the hull's seam."""
    draw = ImageDraw.Draw(image)
    cx, cy = _OBLIVION_DRONE_CENTRE
    r = _OBLIVION_DRONE_RADIUS
    black, white, red = SPECTRA6["black"], SPECTRA6["white"], SPECTRA6["red"]
    lx, ly = cx - 8, cy - 4
    glow = Image.new("L", image.size, 0)
    ImageDraw.Draw(glow).ellipse((lx - 9, ly - 9, lx + 9, ly + 9), fill=255)
    paint_neon_mask(image, glow, None, red, radius=5, gamma=1.8, cap=0.4, ground=(white,))
    glow.close()
    draw.ellipse((lx - 9, ly - 9, lx + 9, ly + 9), fill=red, outline=black, width=1)
    draw.ellipse((lx - 4, ly - 4, lx + 4, ly + 4), fill=black)
    draw.ellipse((lx - 6, ly - 7, lx - 3, ly - 4), fill=white)
    draw.arc((cx - r, cy - r, cx + r, cy + r), 200, 340, fill=black, width=1)
    for x0, x1 in ((cx - r - 16, cx - r + 8), (cx + r - 8, cx + r + 16)):
        draw.rounded_rectangle((x0, cy - 9, x1, cy + 11), radius=5, outline=black, width=1)


def _oblivion_paint_data(draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The waveform strip and the numeral columns, seeded from the quote."""
    black = SPECTRA6["black"]
    rng = random.Random(_OBLIVION_SEED ^ _row_digest(quote_row))
    x0, y0, x1, y1 = _OBLIVION_WAVE_RECT
    base = (y0 + y1) / 2 + 7
    amp = (y1 - y0) / 2 - 14
    phases = [(rng.uniform(0, math.tau), rng.uniform(0.04, 0.12), rng.uniform(0.3, 1.0)) for _ in range(3)]
    points = []
    for x in range(x0 + 6, x1 - 6):
        v = sum(math.sin(x * f + p) * a for p, f, a in phases) / 2.2
        points.append((x, base + v * amp))
    draw.line(points, fill=black, width=1)
    for x in range(x0 + 6, x1 - 6, 20):
        draw.line((x, y1 - 5, x, y1 - 2), fill=black, width=1)
    font = _oblivion_font(9, "Regular")
    mx0, my0, mx1, my1 = _OBLIVION_MAP_RECT
    nx0, ny0, nx1, ny1 = _oblivion_numeral_rect()
    for i in range(6):
        draw.text((nx0 + 4, ny0 + 2 + i * 11), f"{rng.randint(0, 9999):04d}.{rng.randint(0, 9)}", font=font,
                  fill=black)


def _oblivion_layout(draw: ImageDraw.ImageDraw, quote_row: dict):
    return _place_quote(draw, quote_row, _OBLIVION_QUOTE_RECT, theme="oblivion",
                        font_max=34, font_min=18, line_height_mult=1.34)


def _oblivion_paint_quote(draw: ImageDraw.ImageDraw, placed) -> None:
    _paint_placed(draw, placed, SPECTRA6["black"], SPECTRA6["red"])


def _oblivion_paint_byline(draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "").strip()
    parts = [p.upper() for p in (author, title) if p]
    if not parts:
        return
    x0 = _OBLIVION_QUOTE_RECT[0]
    font, text = fit_text_to_width(draw, "   ·   ".join(parts), [(EXO2_VARIABLE, "Regular"), *META_FONT_CANDIDATES],
                                   14, _OBLIVION_QUOTE_RECT[2] - x0, floor=12, tracking=3)
    draw_tracked(draw, (x0, _OBLIVION_BYLINE_Y), text, font, SPECTRA6["black"], tracking=3)


def render_oblivion_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """The Sky Tower's light table with the hour's rig and bearing (see the
    section comment above)."""
    hour = _clock_hour12(time_str)
    image = _oblivion_scene().copy()
    draw = ImageDraw.Draw(image)
    _oblivion_paint_chrome(draw)
    _oblivion_paint_dial(draw, hour)
    _oblivion_paint_rigs(image, hour)
    _oblivion_paint_drone_detail(image)
    draw = ImageDraw.Draw(image)
    _oblivion_paint_data(draw, quote_row)
    _oblivion_paint_quote(draw, _oblivion_layout(draw, quote_row))
    _oblivion_paint_byline(draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# yorha — *NieR: Automata* (2017): the YoRHa system menu, Intel › Archives
# ---------------------------------------------------------------------------
# The pause menu's Intel › Archives: a cream sheet hatched and dotted over
# the blurred city, a dark tab bar, a boxed menu with the selected row
# inverted, a content pane, and Pod 042. Full design notes: docs/themes.md
# (``yorha``).
#
# The sheet (vignette, blurred city silhouettes, diagonal hatch, the panels'
# soft shadows) and the Pod (``_shade_silhouette`` under the upper-left light) are
# painted in continuous tone and Floyd–Steinberg dithered to white, yellow and
# black (``_dither_calibrated``). Panel faces, hairlines, corner ticks, dot
# grid, tab bar, crest and type go on after the dither.
#
# The hour is the open entry: ARCHIVE 01..12, the hour's row inverted with a
# white pointer and the pane's counter reading ``NN / 12``. The quote is EB
# Garamond (the closest open face to the game's UI serif), the matched phrase
# knocked out white of a black box, the game's selected-item mark. Pinned
# across the minutes; the matched phrase carries the minute. One glitch sliver
# at the pane's foot is seeded from the quote. Composed at 800x480 and
# NEAREST-downsampled otherwise (the ``metro`` convention).
# ---------------------------------------------------------------------------
_YORHA_SEED = 0x594F5248              # YORH
_YORHA_INKS = ("white", "yellow", "black")
_YORHA_DOT_PITCH = 16
_YORHA_HATCH_PITCH = 9
_YORHA_HEADER_RECT = (0, 18, 800, 54)
_YORHA_TABS = ("MAP", "QUESTS", "ITEMS", "WEAPONS", "SKILLS", "INTEL", "SYSTEM")
_YORHA_MENU_RECT = (30, 76, 226, 388)
_YORHA_POD_CENTRE = (112, 428)
_YORHA_PANE_RECT = (254, 76, 770, 448)
_YORHA_QUOTE_RECT = (272, 134, 752, 398)
_YORHA_BYLINE_Y = 416
_YORHA_SCENE: dict = {}


def _yorha_cream(y: float, k: float = 0.0) -> tuple[int, int, int]:
    """A calibrated mix: white with ``y`` of yellow and ``k`` of black."""
    w, yel, blk = (_PANEL_INKS[n] for n in ("white", "yellow", "black"))
    return tuple(round(a * (1 - y - k) + b * y + c * k) for a, b, c in zip(w, yel, blk))


def _yorha_font(size: int, weight: str = "Regular"):
    """EB Garamond: the two static cuts, with the lighter labels on Regular
    and the emphasised ones on Bold."""
    file = EBGARAMOND_BOLD if weight in ("SemiBold", "Bold") else EBGARAMOND_REGULAR
    return load_font([file, *META_FONT_CANDIDATES], size=size)


def _yorha_menu_rows() -> list:
    x0, y0, x1, y1 = _YORHA_MENU_RECT
    step = (y1 - y0) // 12
    return [(x0, y0 + i * step, x1, y0 + i * step + step - 4) for i in range(12)]


def _yorha_scene() -> Image.Image:
    """The sheet, the panels, the shadows and the Pod — everything the hour
    and the quote do not touch — dithered and ruled. Painted once per
    process."""
    key = (_yorha_paint_ground, _yorha_paint_panels, _yorha_paint_pod_tone, _yorha_paint_rules)
    cached = _YORHA_SCENE.get("frame")
    if cached is not None and cached[0] == key:
        return cached[1]
    size = (800, 480)
    scene = Image.new("RGB", size, _yorha_cream(0.25))
    _yorha_paint_ground(scene)
    _yorha_paint_panels(scene)
    _yorha_paint_pod_tone(scene)
    image = _dither_calibrated(scene, _YORHA_INKS)
    _yorha_paint_rules(image)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)       # the tab bar's type is antialiased
    _YORHA_SCENE["frame"] = (key, image)
    return image


def _yorha_paint_ground(scene: Image.Image) -> None:
    """The cream sheet in tone: a vignette, the blurred city along the foot,
    and the diagonal hatch."""
    size = scene.size
    width, height = size
    vignette = Image.new("L", (width // 4, height // 4), 0)
    vp = vignette.load()
    cx, cy = vignette.size[0] / 2.0, vignette.size[1] / 2.0
    rmax = math.hypot(cx, cy)
    for y in range(vignette.size[1]):
        for x in range(vignette.size[0]):
            t = (math.hypot(x + 0.5 - cx, y + 0.5 - cy) / rmax) ** 2.6
            vp[x, y] = int(255 * min(1.0, t * 0.5))
    vignette = vignette.resize(size, Image.Resampling.BICUBIC)
    scene.paste(Image.new("RGB", size, _yorha_cream(0.22, 0.42)), (0, 0), vignette)
    # The city: blurred silhouettes along the foot, the world behind the menu.
    rng = random.Random(_YORHA_SEED + 1)
    city = Image.new("L", size, 0)
    cd = ImageDraw.Draw(city)
    x = -20
    while x < width + 20:
        w = rng.randint(24, 70)
        h = rng.randint(30, 110)
        cd.rectangle((x, height - h, x + w, height + 20), fill=rng.randint(120, 220))
        x += w + rng.randint(4, 18)
    city = city.filter(ImageFilter.GaussianBlur(9)).point(lambda v: int(v * 0.55))
    scene.paste(Image.new("RGB", size, _yorha_cream(0.18, 0.62)), (0, 0), city)
    # The hatch: fine diagonals, a shade darker, that dither to faint dashes.
    hatch = Image.new("L", size, 0)
    hd = ImageDraw.Draw(hatch)
    for d in range(-height, width + height, _YORHA_HATCH_PITCH):
        hd.line((d, 0, d + height, height), fill=255, width=1)
    scene.paste(Image.new("RGB", size, _yorha_cream(0.30, 0.16)), (0, 0), hatch.point(lambda v: int(v * 0.55)))
    for m in (vignette, city, hatch):
        m.close()


def _yorha_panel_rects() -> list:
    return [_YORHA_PANE_RECT, *_yorha_menu_rows()]


def _yorha_paint_panels(scene: Image.Image) -> None:
    """The pane and the menu rows in tone: their soft shadows on the sheet,
    and a lighter cream under them (the fill itself is laid crisp after the
    dither — error diffusion worms at a light density, and a page should
    not)."""
    size = scene.size
    panels = Image.new("L", size, 0)
    pd = ImageDraw.Draw(panels)
    for rect in _yorha_panel_rects():
        pd.rectangle(rect, fill=255)
    shadow = _shift_no_wrap(panels, 4, 5).filter(ImageFilter.GaussianBlur(4)).point(lambda v: int(v * 0.7))
    scene.paste(Image.new("RGB", size, _yorha_cream(0.20, 0.5)), (0, 0), shadow)
    scene.paste(Image.new("RGB", size, _yorha_cream(0.12)), (0, 0), panels)
    panels.close()
    shadow.close()


def _yorha_fill_panel(image: Image.Image, rect) -> None:
    """A panel's face: white with a yellow eighth on the 4x4 Bayer tile."""
    x0, y0, x1, y1 = rect
    px = image.load()
    white, yellow = SPECTRA6["white"], SPECTRA6["yellow"]
    for y in range(y0, y1 + 1):
        row = BAYER_4x4[y % 4]
        for x in range(x0, x1 + 1):
            px[x, y] = yellow if row[x % 4] < 2 else white


def _yorha_paint_pod_tone(scene: Image.Image) -> None:
    """Pod 042 in tone: a capsule hull shaded under the upper-left light,
    its face plate, its fins, and its shadow on the sheet."""
    size = scene.size
    cx, cy = _YORHA_POD_CENTRE
    shadow = Image.new("L", size, 0)
    ImageDraw.Draw(shadow).ellipse((cx - 52, cy + 30, cx + 56, cy + 44), fill=255)
    shadow = shadow.filter(ImageFilter.GaussianBlur(5)).point(lambda v: int(v * 0.6))
    scene.paste(Image.new("RGB", size, _yorha_cream(0.18, 0.55)), (0, 0), shadow)
    hull = Image.new("L", size, 0)
    hd = ImageDraw.Draw(hull)
    hd.rounded_rectangle((cx - 58, cy - 20, cx + 38, cy + 20), radius=20, fill=255)
    hd.polygon([(cx - 40, cy - 20), (cx - 18, cy - 40), (cx, cy - 20)], fill=255)          # the dorsal fin
    hd.polygon([(cx - 48, cy + 18), (cx - 64, cy + 34), (cx - 26, cy + 20)], fill=255)     # the ventral fin
    body = _shade_silhouette(hull, _yorha_cream(0.12, 0.16), _yorha_cream(0.06, 0.0), _yorha_cream(0.16, 0.58),
                         offset=6, blur=4)
    scene.paste(body, (0, 0), hull)
    face = Image.new("L", size, 0)
    ImageDraw.Draw(face).rounded_rectangle((cx + 16, cy - 15, cx + 46, cy + 15), radius=7, fill=255)
    plate = _shade_silhouette(face, _yorha_cream(0.10, 0.70), _yorha_cream(0.08, 0.34), _yorha_cream(0.12, 0.92),
                          offset=3, blur=2)
    scene.paste(plate, (0, 0), face)
    for m in (shadow, hull, body, face, plate):
        m.close()


def _yorha_paint_rules(image: Image.Image) -> None:
    """After the dither: the dot grid, the pane's and rows' hairlines with
    their corner ticks, the tab bar with the crest, and the Pod's lens,
    antenna and legend."""
    for rect in _yorha_panel_rects():
        _yorha_fill_panel(image, rect)
    draw = ImageDraw.Draw(image)
    black, white = SPECTRA6["black"], SPECTRA6["white"]
    width, height = image.size
    px = image.load()
    p = _YORHA_DOT_PITCH
    for y in range(p // 2, height, p):
        for x in range(p // 2, width, p):
            if px[x, y] != black:
                px[x, y] = black
    for rect in (_YORHA_PANE_RECT, *_yorha_menu_rows()):
        x0, y0, x1, y1 = rect
        draw.rectangle(rect, outline=black, width=1)
        for (x, y), (dx, dy) in (((x0, y0), (1, 1)), ((x1, y0), (-1, 1)), ((x0, y1), (1, -1)), ((x1, y1), (-1, -1))):
            draw.line((x, y, x + 5 * dx, y), fill=black, width=2)
            draw.line((x, y, x, y + 5 * dy), fill=black, width=2)
    # The tab bar, with INTEL open.
    draw.rectangle(_YORHA_HEADER_RECT, fill=black)
    font = _yorha_font(15, "Regular")
    x = 30
    for tab in _YORHA_TABS:
        tw = draw.textlength(tab, font=font)
        if tab == "INTEL":
            draw.rectangle((x - 8, _YORHA_HEADER_RECT[1] + 6, x + tw + 8, _YORHA_HEADER_RECT[3] - 6), fill=white)
            draw.text((x, _YORHA_HEADER_RECT[1] + 8), tab, font=font, fill=black)
        else:
            draw.text((x, _YORHA_HEADER_RECT[1] + 8), tab, font=font, fill=white)
        x += tw + 26
    # The crest: a ring with its wing bars, and the unit beside it.
    cx, cy = 752, (_YORHA_HEADER_RECT[1] + _YORHA_HEADER_RECT[3]) // 2
    draw.ellipse((cx - 10, cy - 10, cx + 10, cy + 10), outline=white, width=2)
    draw.ellipse((cx - 3, cy - 3, cx + 3, cy + 3), fill=white)
    for i in range(3):
        draw.line((cx - 14 - i * 5, cy - 4 + i * 4, cx - 24 - i * 5, cy - 4 + i * 4), fill=white, width=1)
        draw.line((cx + 14 + i * 5, cy - 4 + i * 4, cx + 24 + i * 5, cy - 4 + i * 4), fill=white, width=1)
    small = _yorha_font(14, "Regular")
    draw_tracked(draw, (cx - 48, cy - 8), "UNIT 2B", small, white, tracking=2, anchor_right=True)
    # The Pod's silhouette, lens, antenna and legend.
    pxc, pyc = _YORHA_POD_CENTRE
    draw.rounded_rectangle((pxc - 58, pyc - 20, pxc + 38, pyc + 20), radius=20, outline=black, width=1)
    draw.polygon([(pxc - 40, pyc - 20), (pxc - 18, pyc - 40), (pxc, pyc - 20)], outline=black)
    draw.polygon([(pxc - 48, pyc + 18), (pxc - 64, pyc + 34), (pxc - 26, pyc + 20)], outline=black)
    draw.rounded_rectangle((pxc + 16, pyc - 15, pxc + 46, pyc + 15), radius=7, outline=black, width=1)
    draw.ellipse((pxc + 24, pyc - 8, pxc + 40, pyc + 8), fill=black)
    draw.ellipse((pxc + 28, pyc - 5, pxc + 32, pyc - 1), fill=white)
    draw.line((pxc - 18, pyc - 40, pxc - 18, pyc - 54), fill=black, width=1)
    draw.ellipse((pxc - 20, pyc - 58, pxc - 16, pyc - 54), fill=black)
    draw.text((pxc + 56, pyc - 7), "POD 042", font=_yorha_font(13, "Bold"), fill=black, stroke_width=2,
              stroke_fill=white)


def _yorha_paint_menu(draw: ImageDraw.ImageDraw, hour: int) -> None:
    """The twelve archive rows' labels; the hour's row inverted."""
    black, white = SPECTRA6["black"], SPECTRA6["white"]
    font = _yorha_font(16, "Regular")
    for i, (x0, y0, x1, y1) in enumerate(_yorha_menu_rows()):
        active = (i + 1) == hour
        if active:
            draw.rectangle((x0, y0, x1, y1), fill=black)
            draw.polygon([(x1 - 16, y0 + 7), (x1 - 8, (y0 + y1) / 2), (x1 - 16, y1 - 7)], fill=white)
        else:
            draw.rectangle((x0 + 8, (y0 + y1) / 2 - 3, x0 + 14, (y0 + y1) / 2 + 3), outline=black, width=1)
        draw.text((x0 + 22, y0 + 3), f"ARCHIVE {i + 1:02d}", font=font, fill=white if active else black)


def _yorha_paint_pane(draw: ImageDraw.ImageDraw, hour: int, quote_row: dict) -> None:
    """The open entry's head: the title over a rule, the counter."""
    black = SPECTRA6["black"]
    x0, y0, x1, y1 = _YORHA_PANE_RECT
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "").strip() or "Untitled"
    font, text = fit_text_to_width(draw, title, [EBGARAMOND_BOLD, *META_FONT_BOLD_CANDIDATES], 22, x1 - x0 - 120, floor=15)
    draw.text((x0 + 18, y0 + 14), text, font=font, fill=black)
    counter = f"{hour:02d} / 12"
    small = _yorha_font(15, "Regular")
    draw.text((x1 - 18 - draw.textlength(counter, font=small), y0 + 18), counter, font=small, fill=black)
    draw.line((x0 + 18, y0 + 46, x1 - 18, y0 + 46), fill=black, width=1)


def _yorha_layout(draw: ImageDraw.ImageDraw, quote_row: dict):
    return _place_quote(draw, quote_row, _YORHA_QUOTE_RECT, theme="yorha",
                        font_max=34, font_min=18, line_height_mult=1.34)


def _yorha_paint_quote(draw: ImageDraw.ImageDraw, placed) -> None:
    """Black EB Garamond; the matched phrase white, knocked out of a black
    box per run — the selected item."""
    black, white = SPECTRA6["black"], SPECTRA6["white"]
    for box in _lumon_hover_boxes(draw, placed):
        draw.rectangle(box, fill=black)
    _paint_placed(draw, placed, black, white)


def _yorha_paint_byline(draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    author = (quote_row.get("author") or "").strip()
    if not author:
        return
    x0 = _YORHA_QUOTE_RECT[0]
    font, text = fit_text_to_width(draw, author, [EBGARAMOND_REGULAR, *META_FONT_CANDIDATES], 18,
                                   _YORHA_QUOTE_RECT[2] - x0, floor=13)
    draw.text((x0, _YORHA_BYLINE_Y), text, font=font, fill=SPECTRA6["black"])


def _yorha_paint_glitch(image: Image.Image, quote_row: dict) -> None:
    """One sliver of the pane's foot shifted sideways — the game's tic."""
    rng = random.Random(_YORHA_SEED ^ _row_digest(quote_row))
    x0, y0, x1, y1 = _YORHA_PANE_RECT
    y = rng.randint(y1 - 60, y1 - 12)
    h = rng.randint(2, 4)
    shift = rng.choice((-6, -4, 4, 6))
    band = image.crop((x0 + 1, y, x1, y + h))
    image.paste(band, (x0 + 1 + shift, y))
    band.close()


def render_yorha_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """The YoRHa archives with the hour's entry open (see the section
    comment above)."""
    hour = _clock_hour12(time_str)
    image = _yorha_scene().copy()
    draw = ImageDraw.Draw(image)
    _yorha_paint_menu(draw, hour)
    _yorha_paint_pane(draw, hour, quote_row)
    _yorha_paint_quote(draw, _yorha_layout(draw, quote_row))
    _yorha_paint_byline(draw, quote_row)
    _yorha_paint_glitch(image, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# hitchhiker — *The Hitchhiker's Guide to the Galaxy* (BBC, 1981): the Guide
# ---------------------------------------------------------------------------
# A Guide entry as the 1981 series animated them by hand: a black screen,
# square-shouldered capitals, flat-colour diagrams with numbered callouts and
# DON'T PANIC. Full design notes: docs/themes.md (``hitchhiker``).
#
# The entry's subject is the quoted author; its text is the quote in white
# with the matched phrase in yellow, each line headed by a marker in the inks
# in rotation. Every glyph is set on its own with a seeded one-pixel
# registration wobble (``_hitchhiker_draw``), the look of held cel lettering.
#
# Figure 1 is the Babel fish under a CRT raster. Figure 2 is a seeded
# two-armed galaxy with twelve sector lines, and that is the clock: the hour's
# sector, clockwise from the top like a clock face, is outlined in yellow with
# the Earth ringed inside it and a YOU ARE HERE leader. Pinned across the
# minutes; the matched phrase carries the minute. Composed at 800x480 and
# NEAREST-downsampled otherwise (the ``metro`` convention).
# ---------------------------------------------------------------------------
_HITCHHIKER_SEED = 0x48484747         # HHGG
_HITCHHIKER_ENTRY_Y = 58
_HITCHHIKER_QUOTE_RECT = (62, 116, 456, 392)
_HITCHHIKER_SEEALSO_Y = 414
_HITCHHIKER_FISH_RECT = (474, 102, 770, 268)
_HITCHHIKER_GALAXY_RECT = (474, 286, 770, 462)
_HITCHHIKER_GALAXY_CENTRE = (596, 384)
_HITCHHIKER_GALAXY_RADIUS = 62
_HITCHHIKER_MARKER_INKS = ("blue", "green", "yellow", "red")
_HITCHHIKER_CALLOUTS = (
    ("1", "BRAINWAVE SENSOR"), ("2", "TELEPATHIC MATRIX"), ("3", "GILL SLITS"),
    ("4", "NERVE SIGNAL"), ("5", "THOUGHT OUTFLOW"),
)


def _hitchhiker_font(size: int):
    return load_font([MICHROMA_REGULAR, (JOST_VARIABLE, "Bold"), *ORNAMENT_FONT_CANDIDATES], size=size)


def _hitchhiker_draw(draw: ImageDraw.ImageDraw, xy, text: str, font, fill, rng: random.Random, *,
                     tracking: float = 0.0) -> float:
    """Hand-animated lettering: each glyph set on its own with a seeded
    one-pixel registration wobble. Returns the run's width."""
    x, y = xy
    start = x
    for ch in text:
        if ch != " ":
            draw.text((x + rng.choice((-1, 0, 0, 1)), y + rng.choice((-1, 0, 0, 1))), ch, font=font, fill=fill)
        x += draw.textlength(ch, font=font) + tracking
    return x - start


def _hitchhiker_paint_masthead(draw: ImageDraw.ImageDraw) -> None:
    """The Guide's name, a rule, and the DON'T PANIC badge."""
    yellow, black = SPECTRA6["yellow"], SPECTRA6["black"]
    rng = random.Random(_HITCHHIKER_SEED + 1)
    _hitchhiker_draw(draw, (40, 20), "THE HITCH HIKER'S GUIDE TO THE GALAXY", _hitchhiker_font(13), yellow, rng,
                     tracking=2)
    draw.rectangle((40, 44, 760, 45), fill=yellow)
    font = _hitchhiker_font(12)
    label = "DON'T PANIC"
    tw = draw.textlength(label, font=font)
    draw.rounded_rectangle((760 - tw - 20, 14, 760, 38), radius=6, fill=yellow)
    draw.text((760 - tw - 10, 19), label, font=font, fill=black)


def _hitchhiker_paint_entry(draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The entry's subject — the author — under an ENTRY label, with the
    colour bars at its left."""
    white, green = SPECTRA6["white"], SPECTRA6["green"]
    y = _HITCHHIKER_ENTRY_Y
    for i, ink in enumerate(_HITCHHIKER_MARKER_INKS):
        draw.rectangle((40, y + i * 11, 54, y + i * 11 + 7), fill=SPECTRA6[ink])
    draw.text((62, y - 2), "ENTRY", font=_hitchhiker_font(11), fill=green)
    subject = (quote_row.get("author") or "").strip() or "ANONYMOUS"
    font, text = fit_text_to_width(draw, subject.upper(), [MICHROMA_REGULAR, (JOST_VARIABLE, "Bold"),
                                                            *ORNAMENT_FONT_CANDIDATES], 24, 394, floor=14)
    _hitchhiker_draw(draw, (62, y + 13), text, font, white, random.Random(_HITCHHIKER_SEED ^ _row_digest(quote_row)))


def _hitchhiker_layout(draw: ImageDraw.ImageDraw, quote_row: dict):
    return _place_quote(draw, quote_row, _HITCHHIKER_QUOTE_RECT, theme="hitchhiker",
                        font_max=22, font_min=12, line_height_mult=1.55)


def _hitchhiker_paint_quote(draw: ImageDraw.ImageDraw, placed, quote_row: dict) -> None:
    """The entry's text, hand-lettered: white with the matched phrase in
    yellow, each line headed by a marker in the inks in rotation."""
    white, yellow = SPECTRA6["white"], SPECTRA6["yellow"]
    rng = random.Random(_HITCHHIKER_SEED + 2 + _row_digest(quote_row))
    lines = sorted({y for _, y, *_ in placed})
    for i, y in enumerate(lines):
        lh = next(p[6] for p in placed if p[1] == y)
        ink = SPECTRA6[_HITCHHIKER_MARKER_INKS[i % len(_HITCHHIKER_MARKER_INKS)]]
        draw.rectangle((_HITCHHIKER_QUOTE_RECT[0] - 18, y + lh // 2 - 7, _HITCHHIKER_QUOTE_RECT[0] - 12, y + lh // 2 - 1),
                       fill=ink)
    for x, y, chunk, font, is_bold, *_ in placed:
        _hitchhiker_draw(draw, (x, y), chunk, font, yellow if is_bold else white, rng)


def _hitchhiker_paint_seealso(draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "").strip()
    if not title:
        return
    font, text = fit_text_to_width(draw, "SEE ALSO:  " + title.upper(), [MICHROMA_REGULAR, (JOST_VARIABLE, "Bold"),
                                                                           *ORNAMENT_FONT_CANDIDATES], 12, 416,
                                   floor=10)
    draw.text((40, _HITCHHIKER_SEEALSO_Y), text, font=font, fill=SPECTRA6["white"])


def _hitchhiker_fish_centre() -> tuple[int, int]:
    x0, y0, x1, y1 = _HITCHHIKER_FISH_RECT
    return x0 + 134, y0 + 76


def _hitchhiker_fish_outline() -> list:
    """The Babel fish in side view, a spline through its control points."""
    x0, y0, x1, y1 = _HITCHHIKER_FISH_RECT
    cx, cy = _hitchhiker_fish_centre()
    body = [(cx - 118, cy), (cx - 96, cy - 22), (cx - 50, cy - 36), (cx + 10, cy - 32), (cx + 70, cy - 18),
            (cx + 108, cy - 6), (cx + 132, cy - 28), (cx + 144, cy - 24), (cx + 130, cy), (cx + 144, cy + 24),
            (cx + 132, cy + 28), (cx + 108, cy + 6), (cx + 70, cy + 18), (cx + 10, cy + 32), (cx - 50, cy + 36),
            (cx - 96, cy + 22)]
    return _catmull_rom(body, closed=True, samples=6)


def _hitchhiker_paint_fish(image: Image.Image) -> None:
    """Figure 1: the Babel fish in cross-section under a CRT raster, its
    organs in the inks, five numbered callouts on leaders."""
    draw = ImageDraw.Draw(image)
    x0, y0, x1, y1 = _HITCHHIKER_FISH_RECT
    white, yellow, blue, green, red, black = (SPECTRA6[k] for k in ("white", "yellow", "blue", "green", "red", "black"))
    draw.rectangle((x0, y0, x1, y1), outline=blue, width=1)
    draw.text((x0 + 8, y0 + 6), "FIG. 1   BABEL FISH", font=_hitchhiker_font(10), fill=green)
    cx, cy = _hitchhiker_fish_centre()
    outline = [(round(x), round(y)) for x, y in _hitchhiker_fish_outline()]
    draw.polygon(outline, fill=yellow)
    _crt_paint_scanlines(image, (x0 + 1, y0 + 1, x1, y1), (yellow,), period=3, phase=1)
    draw = ImageDraw.Draw(image)
    draw.line(outline + [outline[0]], fill=white, width=1)
    # The organs.
    draw.ellipse((cx - 108, cy - 7, cx - 94, cy + 7), fill=black)                   # the eye
    draw.ellipse((cx - 104, cy - 5, cx - 99, cy), fill=white)
    for i in range(3):
        draw.arc((cx - 86 + i * 7, cy - 18, cx - 70 + i * 7, cy + 18), 300, 60, fill=red, width=2)   # the gills
    draw.ellipse((cx - 56, cy - 22, cx - 14, cy + 4), fill=blue, outline=white, width=1)          # the sensor
    draw.ellipse((cx - 44, cy - 14, cx - 30, cy - 4), outline=white, width=1)
    matrix = [(cx - 12 + i * 10, cy + (10 if i % 2 else 18)) for i in range(10)]                     # the matrix
    draw.line(matrix, fill=green, width=2)
    draw.line((cx - 14, cy - 8, cx + 110, cy - 2), fill=white, width=1)                              # the nerve
    for i in range(4):
        draw.line((cx + 20 + i * 24, cy - 6, cx + 26 + i * 24, cy - 14), fill=white, width=1)
    draw.polygon([(cx + 130, cy - 2), (cx + 152, cy - 10), (cx + 152, cy + 6)], fill=green)         # the outflow
    # Callouts: numbered discs on the organs, and the legend in two columns
    # under the rule.
    anchors = ((cx - 36, cy - 10), (cx + 30, cy + 14), (cx - 78, cy - 10), (cx + 70, cy - 4), (cx + 144, cy - 2))
    font = _hitchhiker_font(9)
    rule_y = y1 - 42
    draw.line((x0 + 8, rule_y, x1 - 8, rule_y), fill=blue, width=1)
    for i, ((n, label), (ax, ay)) in enumerate(zip(_HITCHHIKER_CALLOUTS, anchors)):
        tx = x0 + 8 + (0 if i < 3 else 150)
        ty = rule_y + 5 + (i % 3) * 12
        draw.ellipse((ax - 5, ay - 5, ax + 5, ay + 5), fill=black, outline=white, width=1)
        draw.text((ax - 2, ay - 6), n, font=font, fill=white)
        draw.text((tx, ty), f"{n} {label}", font=font, fill=white)


def _hitchhiker_sector_angle(hour: int) -> tuple[float, float]:
    """The hour's sector on the chart: thirty degrees, clockwise from the
    top, like a clock face."""
    start = math.radians((hour % 12) * 30 - 90 - 15)
    return start, start + math.radians(30)


def _hitchhiker_paint_galaxy(draw: ImageDraw.ImageDraw, hour: int) -> None:
    """Figure 2: the galaxy as a seeded two-armed spiral of stars in a boxed
    chart with twelve sector lines; the hour's sector outlined, the Earth
    ringed in it, and YOU ARE HERE on a leader."""
    x0, y0, x1, y1 = _HITCHHIKER_GALAXY_RECT
    white, yellow, blue = SPECTRA6["white"], SPECTRA6["yellow"], SPECTRA6["blue"]
    draw.rectangle((x0, y0, x1, y1), outline=blue, width=1)
    draw.text((x0 + 8, y0 + 6), "FIG. 2   SECTOR ZZ9 PLURAL Z ALPHA", font=_hitchhiker_font(9), fill=SPECTRA6["green"])
    cx, cy = _HITCHHIKER_GALAXY_CENTRE
    radius = _HITCHHIKER_GALAXY_RADIUS
    for h in range(12):
        a = math.radians(h * 30 - 90 - 15)
        draw.line((cx, cy, cx + (radius + 10) * math.cos(a), cy + (radius + 10) * math.sin(a)), fill=blue, width=1)
    draw.ellipse((cx - radius - 10, cy - radius - 10, cx + radius + 10, cy + radius + 10), outline=blue, width=1)
    rng = random.Random(_HITCHHIKER_SEED + 3)
    for arm in (0.0, math.pi):
        for i in range(140):
            t = i / 140.0
            a = arm + t * 2.6 * math.pi
            r = 4 + t * (radius - 4)
            jitter = rng.gauss(0, 3 + 6 * t)
            px = cx + r * math.cos(a) + jitter
            py = cy + r * math.sin(a) + rng.gauss(0, 3 + 6 * t)
            if math.hypot(px - cx, py - cy) > radius:
                continue
            draw.point((round(px), round(py)), fill=yellow if rng.random() < 0.25 else white)
    draw.ellipse((cx - 5, cy - 5, cx + 5, cy + 5), fill=white)
    a0, a1 = _hitchhiker_sector_angle(hour)
    wedge = [(cx, cy)] + [(cx + (radius + 10) * math.cos(a0 + (a1 - a0) * k / 8), cy + (radius + 10) * math.sin(a0 + (a1 - a0) * k / 8))
                          for k in range(9)]
    draw.line(wedge + [(cx, cy)], fill=yellow, width=2)
    am = (a0 + a1) / 2
    ex, ey = cx + (radius - 12) * math.cos(am), cy + (radius - 12) * math.sin(am)
    draw.ellipse((ex - 2, ey - 2, ex + 2, ey + 2), fill=blue)
    draw.ellipse((ex - 6, ey - 6, ex + 6, ey + 6), outline=yellow, width=1)
    # The leader runs to the chart's free right column, where the label lives.
    lx, ly = x1 - 112, y0 + 60
    draw.line((ex + 6 * math.cos(am), ey + 6 * math.sin(am), lx - 6, ly + 6), fill=yellow, width=1)
    draw.text((lx, ly), "YOU ARE", font=_hitchhiker_font(10), fill=yellow)
    draw.text((lx, ly + 14), "HERE", font=_hitchhiker_font(10), fill=yellow)
    draw.text((lx, ly + 40), "MOSTLY", font=_hitchhiker_font(9), fill=white)
    draw.text((lx, ly + 52), "HARMLESS", font=_hitchhiker_font(9), fill=white)


def render_hitchhiker_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A Guide entry on the quoted author with its two figures, the hour's
    sector marked (see the section comment above)."""
    hour = _clock_hour12(time_str)
    image = Image.new("RGB", (800, 480), SPECTRA6["black"])
    draw = ImageDraw.Draw(image)
    _hitchhiker_paint_masthead(draw)
    _hitchhiker_paint_entry(draw, quote_row)
    _hitchhiker_paint_quote(draw, _hitchhiker_layout(draw, quote_row), quote_row)
    _hitchhiker_paint_seealso(draw, quote_row)
    _hitchhiker_paint_fish(image)
    draw = ImageDraw.Draw(image)
    _hitchhiker_paint_galaxy(draw, hour)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# cardcatalog — a library catalogue card with a date-due stamp grid
# ---------------------------------------------------------------------------
# A manila catalogue card: call number, typed author/title header, the quote
# as the card's annotation, and a grid of date-due stamps down the right
# margin. The panel's 5:3 ratio is a 3x5 index card, so the page is the card
# face at full bleed.
#
# A custom frame, not a border painter with a ``clear_rect`` knockout (as
# #210 proposed): at 800x480 the shared layout's body rect leaves no right
# margin, and the stamp column is both the composition and the time carrier.
#
# The time carrier is the freshest stamp. Earlier impressions are faded and
# askew with varying ink density; the current one is crisp, square, spans both
# columns and reads ``DUE`` over the hour (reserve collections ran two-hour
# loans). The minute stays with the matched phrase. Distinct from ``dispatch``
# despite sharing Special Elite: manila and violet library ink, not a white
# dossier with one maroon stamp.
# ---------------------------------------------------------------------------
_CARDCATALOG_EDGE = 12
_CARDCATALOG_CALL_X = 36
_CARDCATALOG_COL_X = 168              # annotation column left edge
_CARDCATALOG_COL_RIGHT = 556          # annotation column right edge
_CARDCATALOG_DIVIDER_X = 568          # rule between annotation and stamps
_CARDCATALOG_HEADER_TOP = 44
_CARDCATALOG_HEADER_RULE = 118
_CARDCATALOG_BODY = (168, 136, 556, 374)
_CARDCATALOG_STAMP_X = (582, 770)
_CARDCATALOG_STAMP_TOP = 84
_CARDCATALOG_STAMP_SIZE = (88, 34)
_CARDCATALOG_STAMP_STEP = 42
_CARDCATALOG_STAMP_ROWS = 7
_CARDCATALOG_PUNCH = (400, 452, 10)   # centre x, centre y, radius
# Foxing density on the manila: 2 hits per modulus, ~1.2% of the card —
# sparser than ``tarot``'s vellum. See ``_cardcatalog_paint_manila`` for why
# the sampling lattice must not alias with the 4-pixel Bayer cream tile.
_CARDCATALOG_FOXING_MOD = 167


def _cardcatalog_paint_manila(image: Image.Image) -> None:
    """Cream base wash plus a sparse sepia foxing scatter — aged card stock.

    The two-layer aged-paper recipe ``tarot`` uses (Y+W cream under R+G sepia),
    run lighter. Both passes only touch white ground pixels, so the painter is
    idempotent and cannot re-tint furniture drawn over it.
    """
    width, height = image.size
    px = image.load()
    white, yellow, red, green = (
        SPECTRA6["white"], SPECTRA6["yellow"], SPECTRA6["red"], SPECTRA6["green"],
    )
    for y in range(height):
        row = BAYER_4x4[y % 4]
        for x in range(width):
            if px[x, y] == white and row[x % 4] < 2:
                px[x, y] = yellow
    # Sepia foxing: adjacent red and green flecks average to rust-brown at
    # panel distance (the ``newsprint`` / ``tarot`` R+G recipe), painted over
    # the cream too — oxidation does not dodge the paper's tone.
    #
    # The sampling lattice must stay coprime with the 4-pixel Bayer period: a
    # lattice that forces ``x % 4 == y % 4`` lands only on cells the cream
    # wash already claimed and paints nothing.
    for y in range(height):
        for x in range(width):
            if (x * 31 + y * 17) % _CARDCATALOG_FOXING_MOD >= 2:
                continue
            if px[x, y] not in (white, yellow):
                continue
            px[x, y] = red if (x * 5 + y * 3) % 7 < 4 else green


def _cardcatalog_call_number(quote_row: dict) -> list[str]:
    """The call-number block: a Dewey class, a cutter, a date, a copy mark.

    Derived from the row digest so it is stable for a given book. Dewey
    800-819 keeps it inside literature.
    """
    digest = _row_digest(quote_row)
    author = (quote_row.get("author") or "").strip()
    surname = author.split(",")[0].split()[-1] if author else "ANON"
    cutter = "".join(ch for ch in surname.upper() if ch.isalpha())[:3] or "ANO"
    dewey = 800 + digest % 20
    decimal = (digest >> 6) % 100
    year = 1890 + (digest >> 12) % 40
    copy = 1 + (digest >> 20) % 3
    return [f"{dewey}.{decimal:02d}", cutter, str(year), f"c.{copy}"]


def _cardcatalog_header(quote_row: dict) -> tuple[str, str]:
    """``(author in catalogue inversion, title)``.

    Catalogue cards file on the surname, so the main entry is inverted:
    "L. M. Montgomery" is filed as "Montgomery, L. M." An author already stored
    inverted (containing a comma) is passed through untouched.
    """
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or "").strip() or (fallback_title(quote_row) or "")
    if author and "," not in author:
        parts = author.split()
        if len(parts) > 1:
            author = f"{parts[-1]}, {' '.join(parts[:-1])}"
    return author or "Anonymous", title


def _cardcatalog_stamp_mask(size: tuple[int, int], lines: list[tuple[str, int]],
                            *, boxed: bool) -> Image.Image:
    """An ``L`` mask of one stamp impression: optional box rule plus its lines."""
    w, h = size
    mask = Image.new("L", (w, h), 0)
    draw = ImageDraw.Draw(mask)
    if boxed:
        draw.rectangle((0, 0, w - 1, h - 1), outline=255, width=2)
    total = sum(size for _, size in lines) + 2 * (len(lines) - 1)
    y = max(0, (h - total) // 2)
    for text, font_size in lines:
        font = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=font_size)
        draw.text((w // 2, y), text, font=font, fill=255, anchor="ma")
        y += font_size + 2
    return mask


def _cardcatalog_stamp(image: Image.Image, origin: tuple[int, int],
                       mask: Image.Image, *, angle: float, coverage: float,
                       rng: random.Random) -> None:
    """Paste one impression in violet library ink at a given angle and density.

    Violet is R+B 1:1 (the Tyrian recipe); library date stamps were purple.
    ``coverage`` drops a different fraction of each impression's ink, so the
    older stamps read as a history from a drying pad. The rotated mask is
    binary-thresholded so no antialiased fringe is left for the final snap.
    """
    if angle:
        mask = mask.rotate(angle, resample=Image.BICUBIC, expand=True)
    mp = mask.load()
    px = image.load()
    width, height = image.size
    red, blue = SPECTRA6["red"], SPECTRA6["blue"]
    ox, oy = origin
    for my in range(mask.size[1]):
        iy = oy + my
        if not 0 <= iy < height:
            continue
        for mx in range(mask.size[0]):
            ix = ox + mx
            if not 0 <= ix < width:
                continue
            if mp[mx, my] < 128:
                continue
            if coverage < 1.0 and rng.random() > coverage:
                continue
            px[ix, iy] = red if (ix + iy) & 1 else blue


def _cardcatalog_paint_stamps(image: Image.Image, quote_row: dict, time_str: str) -> None:
    """The date-due grid: a faded borrowing history, then today's impression."""
    months = ("JAN", "FEB", "MAR", "APR", "MAY", "JUN",
              "JUL", "AUG", "SEP", "OCT", "NOV", "DEC")
    digest = _row_digest(quote_row)
    rng = random.Random(digest)
    left, right = _CARDCATALOG_STAMP_X
    sw, sh = _CARDCATALOG_STAMP_SIZE
    col_step = (right - left) // 2
    # Leave at least one whole row for the current impression, which spans both
    # columns, so a long history can never push it off the card.
    history = 3 + digest % (2 * (_CARDCATALOG_STAMP_ROWS - 1) - 2)
    year = 1948 + (digest >> 8) % 30
    for index in range(history):
        row, col = divmod(index, 2)
        month = months[(digest >> (index % 12)) % 12]
        day = 1 + (digest >> (index + 3)) % 28
        mask = _cardcatalog_stamp_mask(
            (sw, sh), [(f"{month} {day:2d}", 13), (f"{year + row}", 12)], boxed=False,
        )
        _cardcatalog_stamp(
            image,
            (left + col * col_step + rng.randint(-3, 3),
             _CARDCATALOG_STAMP_TOP + row * _CARDCATALOG_STAMP_STEP + rng.randint(-2, 2)),
            mask,
            angle=rng.uniform(-4.5, 4.5),
            coverage=rng.uniform(0.62, 0.92),
            rng=rng,
        )
    # The current impression: crisp, square to the card, spanning both columns,
    # and carrying the hour. This is the theme's time carrier.
    row = (history + 1) // 2
    hour, meridiem = _cardcatalog_due_hour(time_str)
    mask = _cardcatalog_stamp_mask(
        (right - left, sh + 20), [("DUE", 12), (f"{hour} {meridiem}", 26)], boxed=True,
    )
    _cardcatalog_stamp(
        image,
        (left, _CARDCATALOG_STAMP_TOP + row * _CARDCATALOG_STAMP_STEP),
        mask, angle=0.0, coverage=1.0, rng=rng,
    )


def _cardcatalog_due_hour(time_str: str) -> tuple[int, str]:
    """``(1..12, "AM"|"PM")`` parsed defensively from ``HH:MM``.

    Only the hour reaches the stamp (a reserve-desk loan was due on the hour);
    the minute stays with the matched phrase.
    """
    try:
        hour = int((time_str or "").split(":")[0]) % 24
    except (ValueError, IndexError):
        hour = 12
    meridiem = "PM" if hour >= 12 else "AM"
    return (hour % 12) or 12, meridiem


def _cardcatalog_paint_chrome(image: Image.Image, draw: ImageDraw.ImageDraw,
                              quote_row: dict, width: int, height: int) -> None:
    """Card edge, call number, typed header, column rule, and the rod hole."""
    black, red = SPECTRA6["black"], SPECTRA6["red"]
    edge = _CARDCATALOG_EDGE
    draw.rectangle((edge, edge, width - edge - 1, height - edge - 1), outline=black, width=1)

    call = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=15)
    y = _CARDCATALOG_HEADER_TOP
    for line in _cardcatalog_call_number(quote_row):
        draw.text((_CARDCATALOG_CALL_X, y), line, font=call, fill=black)
        y += 20

    author, title = _cardcatalog_header(quote_row)
    column = _CARDCATALOG_COL_RIGHT - _CARDCATALOG_COL_X
    main = load_font([SPECIALELITE_REGULAR, *META_FONT_BOLD_CANDIDATES], size=19)
    sub = load_font([SPECIALELITE_REGULAR, *META_FONT_CANDIDATES], size=16)
    y = _CARDCATALOG_HEADER_TOP
    for text, font in ((author, main), (title, sub)):
        if not text:
            continue
        while len(text) > 1 and draw.textlength(text, font=font) > column:
            text = text[:-2] + "…"
        draw.text((_CARDCATALOG_COL_X, y), text, font=font, fill=black)
        y += 30
    # Rule under the main entry, and the column rule holding the stamps off the
    # annotation — both are ruled on real card stock, not decoration.
    draw.line((_CARDCATALOG_COL_X, _CARDCATALOG_HEADER_RULE,
               _CARDCATALOG_COL_RIGHT, _CARDCATALOG_HEADER_RULE), fill=black, width=1)
    draw.line((_CARDCATALOG_DIVIDER_X, _CARDCATALOG_HEADER_TOP - 8,
               _CARDCATALOG_DIVIDER_X, height - 56), fill=black, width=1)

    heading = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=13)
    centre = (_CARDCATALOG_STAMP_X[0] + _CARDCATALOG_STAMP_X[1]) // 2
    draw.text((centre, _CARDCATALOG_HEADER_TOP), "DATE DUE", font=heading, fill=black, anchor="ma")
    draw.line((_CARDCATALOG_STAMP_X[0], _CARDCATALOG_HEADER_TOP + 22,
               _CARDCATALOG_STAMP_X[1], _CARDCATALOG_HEADER_TOP + 22), fill=black, width=1)

    # The rod hole every drawer card is punched for: filled black with a red
    # rim (the torn fibre), so it reads as a hole rather than a printed dot.
    cx, cy, r = _CARDCATALOG_PUNCH
    if cy + r < height:
        draw.ellipse((cx - r - 1, cy - r - 1, cx + r + 1, cy + r + 1), outline=red, width=1)
        draw.ellipse((cx - r, cy - r, cx + r, cy + r), fill=black)


def _cardcatalog_paint_annotation(image: Image.Image, draw: ImageDraw.ImageDraw,
                                  quote_row: dict) -> None:
    """The quote, typed into the card's annotation column.

    The matched phrase takes the stamps' violet, tying the readable time to
    the stamped one.
    """
    x0, y0, x1, y1 = _CARDCATALOG_BODY
    if x1 - x0 < 40 or y1 - y0 < 40:
        return
    black, red, blue = SPECTRA6["black"], SPECTRA6["red"], SPECTRA6["blue"]
    # Top-aligned, not centred: a card's annotation begins directly under the
    # main-entry rule; the tracing block fills the foot.
    placed = _place_quote(draw, quote_row, _CARDCATALOG_BODY, theme="cardcatalog",
                          font_max=26, font_min=12, line_height_mult=1.34)
    for x, y, chunk, font, is_bold, *_ in placed:
        if is_bold:
            draw_text_dithered(image, (x, y), chunk, font, red, blue)
        else:
            draw.text((x, y), chunk, font=font, fill=black)


def _cardcatalog_paint_tracing(draw: ImageDraw.ImageDraw, quote_row: dict, height: int) -> None:
    """The added-entries tracing and accession mark at the foot of the card.

    Invents nothing: a title added entry exists for every work, the holding
    collection is this appliance, and the accession number is the row's real
    Gutenberg ID. Don't add subject headings — that would fabricate
    bibliographic data about a real book.
    """
    black = SPECTRA6["black"]
    x0 = _CARDCATALOG_COL_X
    x1 = _CARDCATALOG_COL_RIGHT
    y = height - 96
    draw.line((x0, y, x0 + 120, y), fill=black, width=1)
    body = load_font([SPECIALELITE_REGULAR, *META_FONT_CANDIDATES], size=14)
    draw.text((x0, y + 10), "I. Title.   II. Idle Hours Collection.", font=body, fill=black)
    source_id = str(quote_row.get("source_id") or "").strip()
    if source_id:
        mono = load_font([SPACEMONO_REGULAR, *META_FONT_CANDIDATES], size=12)
        draw.text((x1, y + 12), f"ACC. PG-{source_id}", font=mono, fill=black, anchor="ra")


def render_cardcatalog_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A library catalogue card (see the section comment above).

    Every rectangle is a fixed panel coordinate, so the card is composed at
    800x480 and NEAREST-downsampled otherwise (the ``metro`` convention); a
    direct small render would put the stamp column off the canvas. NEAREST
    because the manila stipple would average to off-palette colours.
    """
    image = Image.new("RGB", (800, 480), color=SPECTRA6["white"])
    _cardcatalog_paint_manila(image)
    draw = ImageDraw.Draw(image)
    _cardcatalog_paint_chrome(image, draw, quote_row, 800, 480)
    _cardcatalog_paint_annotation(image, draw, quote_row)
    _cardcatalog_paint_tracing(draw, quote_row, 480)
    _cardcatalog_paint_stamps(image, quote_row, time_str)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# bakelite — an amber-phosphor CRT readout in a moulded bakelite console.
#
# The one *appliance* in the rotation: a moulded butterscotch slab with a
# sunken CRT face, and the quote is what the tube displays. Full design notes:
# docs/themes.md (``bakelite``).
#
# **The screen's brown is the scanlines, not a wash.** Only every third row is
# lit (``_BAKELITE_PITCH``), stippled red and green at 3:1
# (``_BAKELITE_TUBE_GREEN``) so it averages to a dark warm brown with visible
# line structure; the rows between stay black. Thinning the lit rows toward
# the rim carries the vignette, with a mild lift toward the upper left for the
# glass's reflection.
#
# **The glow is a synthesised tangerine.** No single ink is amber: a red halo
# is lost against a screen made of red, and yellow alone reads olive (the
# panel's yellow is a green one). So ``paint_neon_mask`` blooms red with a
# yellow minor share (``glow_minor`` / ``core_minor``), the ratio riding the
# density's own Bayer read as a split band (see its docstring);
# ``_bakelite_paint_phosphor`` only supplies this theme's inks. Two tiers: the
# prose has a gold stipple core, the matched phrase a solid white core and a
# wider, denser bloom — an over-driven character on a one-phosphor tube.
#
# **The chrome is unlit.** Labels are flat solid yellow with no bloom, so the
# legend sits behind the emissive readouts it names. Don't set them in red
# (lowest contrast on black; 11 px caps vanish into the scanlines) or in a
# tangerine stipple (shreds a letterform that small). The rules are wider than
# a stem, so they can carry the tangerine.
#
# **The hour rides a setting index**, ``HOUR 2/12``. Hour only: every minute
# of an hour renders byte-identically for a given row (pinned by
# ``TestBakeliteHourIndex``).
_BAKELITE_SCREEN = (46, 36, 754, 444)          # the CRT face, inset into the slab
_BAKELITE_SCREEN_RADIUS = 26
_BAKELITE_PITCH = 3                            # one lit scanline in every three
_BAKELITE_SCAN_PEAK = 1.0                      # lit-row density at the tube centre
_BAKELITE_SCAN_EDGE = 0.28                     # ... and out at its rim
_BAKELITE_BEVEL = 7                            # moulded-edge band width, both faces
_BAKELITE_RULE_TOP = 150
_BAKELITE_RULE_BOTTOM = 382
_BAKELITE_QUOTE_RECT = (88, 168, 712, 368)
_BAKELITE_MARGIN = 34                          # chrome inset from the screen edge
_BAKELITE_TRACKING = 3.6                       # letterspacing on the small labels
# Split-band fractions: the share of each lit run's lowest ranks that takes the
# minority ink. See ``_bakelite_paint_phosphor`` for why the ratio has to ride
# the density's own read rather than a second key.
_BAKELITE_HALO_YELLOW = 0.375                  # R+Y 5/8:3/8 tangerine, the halo
_BAKELITE_CORE_YELLOW = 0.625                  # Y+R 5/8:3/8 gold, the lit stroke
_BAKELITE_TUBE_GREEN = 0.25                    # R+G 3:1 warm brown, the scanlines
_BAKELITE_HOUR_WORDS = {
    "twelve": 12, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
    "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10, "eleven": 11,
}


def _bakelite_screen_inks() -> frozenset:
    """Inks a text bloom may overwrite: the tube's own ground, nothing else.

    Excluding white and yellow keeps a later halo off the cores an earlier pass
    already lit, and excluding the bezel's tan mix stops any bloom from bleeding
    out through the screen's rounded edge onto the moulding.
    """
    return frozenset({SPECTRA6["black"], SPECTRA6["red"], SPECTRA6["green"]})


def _bakelite_screen_mask() -> Image.Image:
    mask = Image.new("L", (800, 480), 0)
    ImageDraw.Draw(mask).rounded_rectangle(
        _BAKELITE_SCREEN, radius=_BAKELITE_SCREEN_RADIUS, fill=255
    )
    return mask


def _bakelite_grain(x: int, y: int) -> float:
    """A deterministic 0..1 value per pixel — the moulding's fine grain.

    A pure integer hash of position, so the frame re-renders byte-identically.
    """
    h = (x * 0x1F1F1F1F) ^ (y * 0x2545F491)
    h = ((h ^ (h >> 13)) * 0x27D4EB2D) & 0xFFFFFFFF
    return ((h ^ (h >> 15)) & 0xFFFF) / 65535.0


def _bakelite_paint_moulding(image: Image.Image) -> None:
    """Layer 0: the butterscotch slab the tube is set into.

    A three-way white:yellow:red partition at roughly 9:4:3, judged on the
    calibrated inks. Straight Y+W cream lands on khaki (the panel's yellow is
    a green one) and yellow-dominant snaps to flat lemon; red pulls the
    average onto warm sand, and white leading at 9/16 keeps the slab lighter
    than the maroon bevel shadow.

    The ink is chosen by a jittered ordered dither (the Bayer rank plus a
    positional hash at ~40% of a cell): ordered alone lattices and bands the
    marbling, hash alone reads as sandpaper. The marbling sines are safe only
    because of the jitter — two periodic patterns otherwise beat into a plaid.
    Both terms are deterministic, so a re-render is byte-identical.
    """
    pixels = image.load()
    yellow, white, red = SPECTRA6["yellow"], SPECTRA6["white"], SPECTRA6["red"]
    for y in range(480):
        row = BAYER_4x4[y % 4]
        for x in range(800):
            # Two incommensurate low frequencies: a single one corrugates. The
            # swing is kept to about one part in sixteen — enough to see as
            # marbling, not so much that a patch reads as its own colour.
            swirl = 0.035 * (math.sin(x * 0.021 + y * 0.013) + math.sin(x * 0.0075 - y * 0.019))
            level = (row[x % 4] + 0.5) / 16.0 + (_bakelite_grain(x, y) - 0.5) * 0.42
            pale = 0.5625 + swirl
            pixels[x, y] = white if level < pale else (yellow if level < pale + 0.25 else red)


def _bakelite_bevel_face(x: int, y: int, rect: tuple[int, int, int, int]) -> tuple[str, int]:
    """Which face of a moulded edge a band pixel sits on, and how deep into it.

    The edge the pixel has travelled furthest past wins, so corners resolve
    to the nearer face. The caller maps ``"near"`` (top / left) and ``"far"``
    (bottom / right) onto highlight or shadow for a raised or sunken feature
    (light from the upper left). Depth is measured against the straight
    edges, an approximation along a rounded corner that is invisible at 7 px.
    """
    x0, y0, x1, y1 = rect
    return max((x0 - x, "near"), (y0 - y, "near"), (x - x1, "far"), (y - y1, "far"))[::-1]


def _bakelite_paint_bevels(image: Image.Image) -> None:
    """The two moulded edges: a raised outer lip and the sunken screen recess.

    Painted per pixel from ring masks because PIL strokes a rounded rectangle
    in one colour. White is the highlight; the shadow is R+K maroon, not the
    frame's R+G brown, which sits too close to the slab's tone to read as
    dark. The ink falls in Bayer density from full at the feature's edge to
    nothing across the band, so each face reads as a curved surface rather
    than a drawn outline.
    """
    pixels = image.load()
    shadow = (SPECTRA6["red"], SPECTRA6["black"])
    white = SPECTRA6["white"]

    # The slab's own edge is square: the canvas *is* the moulding, and a
    # rounded corner would fall outside the band and paint solid wedges.
    outer = (_BAKELITE_BEVEL, _BAKELITE_BEVEL, 799 - _BAKELITE_BEVEL, 479 - _BAKELITE_BEVEL)

    screen = _bakelite_screen_mask()
    recess = Image.new("L", (800, 480), 0)
    ImageDraw.Draw(recess).rounded_rectangle(
        (_BAKELITE_SCREEN[0] - _BAKELITE_BEVEL, _BAKELITE_SCREEN[1] - _BAKELITE_BEVEL,
         _BAKELITE_SCREEN[2] + _BAKELITE_BEVEL, _BAKELITE_SCREEN[3] + _BAKELITE_BEVEL),
        radius=_BAKELITE_SCREEN_RADIUS + _BAKELITE_BEVEL, fill=255,
    )
    rc_px, sc_px = recess.load(), screen.load()

    for y in range(480):
        row = BAYER_8x8[y % 8]
        for x in range(800):
            if x < outer[0] or y < outer[1] or x > outer[2] or y > outer[3]:
                # The raised outer lip: lit on the near faces, shadowed on the far.
                side, depth = _bakelite_bevel_face(x, y, outer)
                rect_edge = 0
            elif rc_px[x, y] >= 128 and sc_px[x, y] < 128:
                # The ring between moulding and glass. Sunken, so the polarity
                # of the outer lip inverts.
                side, depth = _bakelite_bevel_face(x, y, _BAKELITE_SCREEN)
                side = "far" if side == "near" else "near"
                rect_edge = 1
            else:
                continue
            # Depth runs outward from the feature's edge on the recess and
            # inward from the canvas edge on the lip, so the fade is anchored on
            # whichever edge the eye reads as the fold.
            travelled = depth if rect_edge else _BAKELITE_BEVEL - depth
            weight = max(0.0, 1.0 - travelled / (_BAKELITE_BEVEL + 1.0))
            if row[x % 8] < weight * 64:
                pixels[x, y] = white if side == "near" else shadow[(x + y) & 1]


def _bakelite_paint_tube(image: Image.Image, screen: Image.Image) -> None:
    """The CRT face: black glass carrying warm scanlines (see section comment)."""
    pixels = image.load()
    sc_px = screen.load()
    black, red, green = SPECTRA6["black"], SPECTRA6["red"], SPECTRA6["green"]
    x0, y0, x1, y1 = _BAKELITE_SCREEN
    cx, cy = (x0 + x1) / 2.0, (y0 + y1) / 2.0
    half_w, half_h = max(1.0, (x1 - x0) / 2.0), max(1.0, (y1 - y0) / 2.0)

    # Peak density is 1.0 so the lit rows are solid at the centre and the line
    # structure is legible; the vignette is carried by thinning them toward
    # the rim.
    #
    # Both ranges include the far bound: ``_BAKELITE_SCREEN`` is inclusive
    # (``rounded_rectangle`` fills both endpoints, and ``_bakelite_bevel_face``
    # assumes the same). A half-open range leaves a 1 px line of moulding
    # inside the CRT's right and bottom edges.
    for y in range(y0, y1 + 1):
        lit = (y - y0) % _BAKELITE_PITCH == 0
        for x in range(x0, x1 + 1):
            if sc_px[x, y] < 128:
                continue
            pixels[x, y] = black
            if not lit:
                continue
            # Radial falloff, lifted toward the upper left for the ambient
            # reflection real glass carries.
            radial = min(1.0, (((x - cx) / half_w) ** 2 + ((y - cy) / half_h) ** 2) ** 0.5)
            sheen = 0.10 * max(0.0, 1.0 - ((x - x0) / half_w + (y - y0) / half_h) / 1.4)
            # A high exponent confines the falloff to the corners; a low one
            # (1.6) greys the whole screen.
            density = _BAKELITE_SCAN_EDGE + (_BAKELITE_SCAN_PEAK - _BAKELITE_SCAN_EDGE) * (1.0 - radial ** 3.0)
            lit = (density + sheen) * 64
            rank = BAYER_8x8[y % 8][x % 8]
            if rank < lit:
                # 3:1 red:green, not sepia's 1:1: the panel's green is cool and
                # 1:1 reads grey-green; red-weighted reads as unlit-phosphor
                # brown. Green must come off the same Bayer read as the density
                # (the split band ``paint_neon_mask`` documents): a positional
                # key either hits ranks the threshold already rejected or misses
                # the target ratio.
                pixels[x, y] = green if rank < lit * _BAKELITE_TUBE_GREEN else red


def _bakelite_tracked_width(draw, text: str, font) -> float:
    return tracked_width(draw, text, font, tracking=_BAKELITE_TRACKING)


def _bakelite_draw_tracked(draw, x: float, y: int, text: str, font, fill) -> None:
    """The silkscreened legend at this theme's tracking — see ``draw_tracked``."""
    draw_tracked(draw, (x, y), text, font, fill, tracking=_BAKELITE_TRACKING)


def _bakelite_fit_text(draw, text: str, size: int, max_width: int, floor: int = 17):
    """A chrome readout shrunk to its cell, then ellipsised at the floor — see
    ``fit_text_to_width``; the cells are drawn as single kerned runs."""
    return fit_text_to_width(draw, text, theme_font_candidates("bakelite", "quote_regular"),
                             size, max_width, floor=floor)


def _bakelite_paint_phosphor(image: Image.Image, mask: Image.Image, core=None,
                             *, radius: int = 7, gamma: float = 1.5, cap: float = 0.68) -> None:
    """Bloom one glyph mask as lit amber phosphor (see the section comment).

    A thin wrapper over ``paint_neon_mask`` supplying this theme's inks and
    tuning; the mechanism is documented there. ``core=None`` (the prose and
    every chrome readout) strokes the glyph as a yellow-dominant amber, 5/8
    against the halo's 3/8, so a character steps gold, orange, brown — solid
    yellow would read lemon. An explicit ``core`` ink pins the core solid
    (the matched phrase's white). The ground is the tube's own inks, so a
    later call cannot dim what an earlier one lit.
    """
    paint_neon_mask(
        image, mask,
        core if core is not None else SPECTRA6["red"], SPECTRA6["red"],
        radius=radius, gamma=gamma, cap=cap, ground=_bakelite_screen_inks(), tile=BAYER_8x8,
        glow_minor=SPECTRA6["yellow"], glow_minor_share=_BAKELITE_HALO_YELLOW,
        core_minor=None if core is not None else SPECTRA6["yellow"],
        core_minor_share=_BAKELITE_CORE_YELLOW,
    )


def _bakelite_paint_rule(image: Image.Image, y: int, x0: int, x1: int) -> None:
    """A dim tangerine divider: red with 3/8 flipped to yellow on the Bayer
    tile (R+Y 5/8:3/8, red-biased so it does not read as lit). A rule's runs
    are wide enough to carry a stipple, unlike the small labels."""
    pixels = image.load()
    red, yellow = SPECTRA6["red"], SPECTRA6["yellow"]
    for x in range(max(0, x0), min(image.size[0], x1)):
        pixels[x, y] = yellow if BAYER_4x4[y % 4][x % 4] < 6 else red


def _bakelite_paint_chrome(image: Image.Image, draw: ImageDraw.ImageDraw,
                           quote_row: dict, time_str: str) -> None:
    """Labels, rules and readouts — the instrument furniture around the quote.

    Labels are flat solid yellow and rules a dim tangerine stipple; every
    value is bloomed, so the legend reads as silkscreened behind the emissive
    readout. All values accumulate into one mask and bloom in a single pass.
    """
    label_ink = SPECTRA6["yellow"]
    x0, _, x1, _ = _BAKELITE_SCREEN
    left = x0 + _BAKELITE_MARGIN
    right = x1 - _BAKELITE_MARGIN
    label_font = load_font(theme_font_candidates("bakelite", "ornament"), size=11)
    glow = Image.new("L", image.size, 0)
    glow_draw = ImageDraw.Draw(glow)

    for rule_y in (_BAKELITE_RULE_TOP, _BAKELITE_RULE_BOTTOM):
        _bakelite_paint_rule(image, rule_y, left, right)

    # Top left: the hour as a discrete setting index out of twelve.
    _bakelite_draw_tracked(draw, left, 66, "HOUR", label_font, label_ink)
    hour_font = load_font(theme_font_candidates("bakelite", "quote_regular"), size=62)
    scale_font = load_font(theme_font_candidates("bakelite", "quote_regular"), size=24)
    hour_text = str(_clock_hour12(time_str))
    glow_draw.text((left, 84), hour_text, font=hour_font, fill=255)
    hour_w = draw.textlength(hour_text, font=hour_font)
    glow_draw.text((left + hour_w + 10, 122), f"/{len(_BAKELITE_HOUR_WORDS)}",
                   font=scale_font, fill=255)

    # Top right: the book; bottom left: its author. A missing value prints "—"
    # in its labelled cell, as an instrument shows a sensor with no data,
    # rather than dropping the cell (bare corpus rows are common).
    title = (quote_row.get("title") or fallback_title(quote_row) or "").strip()
    label_w = _bakelite_tracked_width(draw, "NOW READING", label_font)
    _bakelite_draw_tracked(draw, right - label_w, 66, "NOW READING", label_font, label_ink)
    title_font, title_text = _bakelite_fit_text(draw, title or "—", 28, 330)
    glow_draw.text((right, 96), title_text, font=title_font, fill=255, anchor="ra")

    author = (quote_row.get("author") or "").strip()
    _bakelite_draw_tracked(draw, left, 396, "AUTHOR", label_font, label_ink)
    author_font, author_text = _bakelite_fit_text(draw, author or "—", 24, 400, floor=16)
    glow_draw.text((left, 410), author_text, font=author_font, fill=255, anchor="la")

    # Right: an unlit maker's mark, silkscreened on the bezel side of the glass.
    mark_w = _bakelite_tracked_width(draw, "IDLE HOURS", label_font)
    _bakelite_draw_tracked(draw, right - mark_w, 416, "IDLE HOURS", label_font, label_ink)

    _bakelite_paint_phosphor(image, glow)


def _bakelite_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The quote as lit phosphor: prose amber, matched phrase over-driven.

    Two masks from ``wrap_quote_into_masks`` so each tier blooms exactly once.
    The hot pass runs last so its wider halo reads as nearer;
    ``_bakelite_paint_phosphor``'s ground keeps it off the prose's already-lit
    halo and cores.
    """
    prose, hot, _ = wrap_quote_into_masks(
        draw, image.size, quote_row, _BAKELITE_QUOTE_RECT,
        theme="bakelite", line_height_mult=1.46,
    )
    _bakelite_paint_phosphor(image, prose)
    _bakelite_paint_phosphor(image, hot, SPECTRA6["white"], radius=11, gamma=1.3, cap=0.78)


def render_bakelite_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """An amber-phosphor CRT in a bakelite console (see the section comment).

    Every element is an absolute panel coordinate, so the frame is composed at
    800x480 and NEAREST-downsampled otherwise (the ``metro`` convention);
    NEAREST because the frame is per-pixel stipple.
    """
    image = Image.new("RGB", (800, 480), color=SPECTRA6["white"])
    _bakelite_paint_moulding(image)
    _bakelite_paint_bevels(image)
    screen = _bakelite_screen_mask()
    _bakelite_paint_tube(image, screen)
    draw = ImageDraw.Draw(image)
    _bakelite_paint_chrome(image, draw, quote_row, time_str)
    _bakelite_paint_quote(image, draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# intaglio — a banknote face, engraved
#
# A promissory note rendering tone as **line-work** (``paint_hatched_tone``):
# engraved parallel lines whose weight carries the grey at constant pitch,
# plus guilloché roulettes. Both read as drawing at panel distance, where a
# stipple reads as tone. No committed plate: guilloché is parametric, so the
# face is procedural and exact. Full design notes: docs/themes.md
# (``intaglio``).
#
# **Three plates, three inks.** Black is the intaglio plate (masthead, quote,
# rules, medallion hubs), green the tint plate (lathework band, rosettes,
# safety tint, the matched-phrase ribbon), red the numbering press (serial
# only). White is the paper. Nothing is synthesised.
#
# **The time carrier is the denomination**: the corner medallions spell the
# hour as a face value (SEVEN, TWELVE), pinned by ``TestIntaglioEngraving``.
# The minute stays with the matched phrase, bold black over a green lathework
# ribbon — not green glyphs, which read pale at body size. The serial comes
# from ``_row_digest``, never the clock: it must not put readable digits of
# the time on the panel.
#
# **Moiré is the risk the constants manage.** The final snap is nearest-ink,
# so the only beats are hatch-vs-pixel-grid: spacing stays >= 4 (chosen 5) and
# the two hatch families sit at 33/123 degrees — off the axes, off 45, and 90
# apart so their interference is a stable lattice. The cartouche interior is
# pure white with no wash beneath. Guilloché polylines keep segments under
# ~1.5 px (coarser leaves dotted gaps on shallow arcs), and each closed curve
# is ONE ``draw.line`` call, because per-segment calls drop corner pixels at
# width 1.
_INTAGLIO_BORDER = (14, 14, 786, 466)          # outer rule of the lathework frame
_INTAGLIO_INNER = (44, 44, 756, 436)           # inner rule; the band lies between
_INTAGLIO_MEDALLION_R = 34
_INTAGLIO_ROSETTE = (400, 250, 190)            # cx, cy, R of the ground rosette
_INTAGLIO_CARTOUCHE = (128, 148, 672, 372)
_INTAGLIO_QUOTE_RECT = (162, 168, 638, 314)
_INTAGLIO_HATCH_ANGLES = (33.0, 123.0)         # off-axis, off-45; families 90 apart
_INTAGLIO_HATCH_SPACING = 5.0
_INTAGLIO_TINT_PERIOD = 14                     # safety-tint wave pitch
_INTAGLIO_HOUR_WORDS = {
    1: "ONE", 2: "TWO", 3: "THREE", 4: "FOUR", 5: "FIVE", 6: "SIX",
    7: "SEVEN", 8: "EIGHT", 9: "NINE", 10: "TEN", 11: "ELEVEN", 12: "TWELVE",
}


def _intaglio_serial(quote_row: dict) -> str:
    """Numbering-press serial: prefix letter, seven digits, suffix letter.

    Derived from ``_row_digest`` so it is stable per quote and carries no trace
    of the clock — see the section comment for why it must not.
    """
    digest = _row_digest(quote_row)
    prefix = chr(65 + digest % 26)
    suffix = chr(65 + (digest >> 8) % 26)
    return f"{prefix} {(digest >> 5) % 10_000_000:07d} {suffix}"


def _intaglio_roulette_points(cx: float, cy: float, big_r: int, small_r: int, pen_d: float,
                              *, phase: float = 0.0, squash: float = 1.0) -> list[tuple[float, float]]:
    """Sample one closed hypotrochoid — the spirograph curve of a rose lathe.

    ``x = (R-r)cos t + d cos(((R-r)/r) t)``, ``y = (R-r)sin t - d sin(...)``.
    The curve closes after ``q`` revolutions where ``(R-r)/r = p/q`` in lowest
    terms, so both radii are ints and the closure is computed, not eyeballed.
    Step count is scaled to the curve's arc-length estimate so no polyline
    segment exceeds ~1.5 px — the anti-gap discipline the section comment
    describes. ``squash`` flattens y for the oval medallion hubs.
    """
    g = math.gcd(big_r - small_r, small_r)
    revolutions = small_r // g
    t_max = 2 * math.pi * revolutions
    # The divisor is the target segment length; the pen's own epicycle makes
    # the true arc longer than t_max * reach, so it errs on the dense side.
    reach = (big_r - small_r) + pen_d
    steps = max(64, int(t_max * reach))
    k = (big_r - small_r) / small_r
    points = []
    for i in range(steps + 1):
        t = t_max * i / steps
        x = (big_r - small_r) * math.cos(t) + pen_d * math.cos(k * t)
        y = (big_r - small_r) * math.sin(t) - pen_d * math.sin(k * t)
        c, s = math.cos(phase), math.sin(phase)
        points.append((cx + x * c - y * s, cy + (x * s + y * c) * squash))
    return points


def _intaglio_cartouche_tone(x: int, y: int) -> float:
    """The engraved pillow: 0 across the cartouche's interior, rising through
    a thin rim band at its edge.

    Clipped to a superellipse (exponent 4) so the hatch never escapes onto the
    rosette, but graded by straight distance-to-edge so the band is a uniform
    ~26 px on every side. The peak is shallow (0.55) so it reads as an
    engraved bevel and leaves the legend's outer words clear.
    """
    x0, y0, x1, y1 = _INTAGLIO_CARTOUCHE
    nx = abs((x - (x0 + x1) / 2) / ((x1 - x0) / 2))
    ny = abs((y - (y0 + y1) / 2) / ((y1 - y0) / 2))
    if (nx ** 4 + ny ** 4) ** 0.25 > 1.0:
        return 0.0
    edge = min(x - x0, x1 - x, y - y0, y1 - y)
    return 0.55 * max(0.0, 1.0 - edge / 26.0) ** 1.3


def _intaglio_paint_tint(image: Image.Image) -> None:
    """The protectographic safety tint: faint green waves across the paper.

    Half-density along each wave (every other pixel) so the field reads as a
    tint rather than as ruling; everything later paints over it.
    """
    px = image.load()
    green = SPECTRA6["green"]
    x0, y0, x1, y1 = _INTAGLIO_INNER
    row = y0 + _INTAGLIO_TINT_PERIOD // 2
    band = 0
    while row < y1 - 2:
        for x in range(x0, x1):
            y = int(row + 3.0 * math.sin(x * 0.05 + band * 1.7))
            if y0 <= y < y1 and x % 3 == 0:
                px[x, y] = green
        row += _INTAGLIO_TINT_PERIOD
        band += 1


def _intaglio_paint_lathework_band(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """The border frame: black rules enclosing a woven green cycloid band.

    Two mirrored sinusoid trains per edge — the braid a straight-line lathe
    cuts — with the corner miters covered by the medallions painted after.
    """
    black, green = SPECTRA6["black"], SPECTRA6["green"]
    draw.rectangle(_INTAGLIO_BORDER, outline=black, width=2)
    draw.rectangle(_INTAGLIO_INNER, outline=black, width=1)
    bx0, by0, bx1, by1 = _INTAGLIO_BORDER
    mid_top = (by0 + _INTAGLIO_INNER[1]) // 2
    mid_bottom = (by1 + _INTAGLIO_INNER[3]) // 2
    mid_left = (bx0 + _INTAGLIO_INNER[0]) // 2
    mid_right = (bx1 + _INTAGLIO_INNER[2]) // 2
    amp = 9.0
    freq = 0.22
    for sign in (1.0, -1.0):
        for mid, horizontal in ((mid_top, True), (mid_bottom, True)):
            pts = [(x, mid + sign * amp * math.sin(x * freq)) for x in range(bx0 + 2, bx1 - 1)]
            draw.line(pts, fill=green, width=1)
        for mid in (mid_left, mid_right):
            pts = [(mid + sign * amp * math.sin(y * freq), y) for y in range(by0 + 2, by1 - 1)]
            draw.line(pts, fill=green, width=1)


def _intaglio_paint_rosette(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """The ground rosette: one large faint guilloché rose behind the cartouche.

    Petal spacing stays >= 6 px so black text over its exposed ring never loses
    a stroke to a green line crossing it.
    """
    cx, cy, big_r = _INTAGLIO_ROSETTE
    green = SPECTRA6["green"]
    draw.line(_intaglio_roulette_points(cx, cy, big_r, 130, 52.0), fill=green, width=1)
    draw.line(_intaglio_roulette_points(cx, cy, big_r - 26, 112, 40.0, phase=0.26), fill=green, width=1)
    draw.line(_intaglio_roulette_points(cx, cy, big_r - 10, 144, 34.0, phase=0.55), fill=green, width=1)


def _intaglio_paint_medallions(image: Image.Image, draw: ImageDraw.ImageDraw, hour: int) -> None:
    """Corner denomination medallions: a dense rosette, an oval hub, the word.

    The hub is wiped white before the word goes down — a real medallion's
    centre is burnished clear so the counter can overprint the value — and the
    word shrinks to fit the oval, since SEVEN and TWELVE differ by half.
    """
    black, green, white = SPECTRA6["black"], SPECTRA6["green"], SPECTRA6["white"]
    word = _INTAGLIO_HOUR_WORDS[hour]
    ix0, iy0, ix1, iy1 = _INTAGLIO_INNER
    for cx, cy in ((ix0, iy0), (ix1, iy0), (ix0, iy1), (ix1, iy1)):
        draw.line(_intaglio_roulette_points(cx, cy, _INTAGLIO_MEDALLION_R, 10, 8.0), fill=green, width=1)
        draw.line(_intaglio_roulette_points(cx, cy, _INTAGLIO_MEDALLION_R, 12, 10.0, phase=0.4), fill=green, width=1)
        hub = (cx - 27, cy - 12, cx + 27, cy + 12)
        draw.ellipse(hub, fill=white, outline=black, width=1)
        for size in (11, 10, 9, 8):
            font = load_font(theme_font_candidates("intaglio", "ornament"), size=size)
            if draw.textlength(word, font=font) <= 48:
                break
        draw.text((cx, cy - 1), word, font=font, fill=black, anchor="mm")


def _intaglio_paint_cartouche(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """The quote panel: a white superellipse pillow shaded by engraved hatching.

    The capability showcase. One family carries the full tone, the second lays
    cross-hatch only into the deepest half — see ``paint_hatched_tone`` for why
    that split is the engraver's own — and both stop below saturation so paper
    always shows between the lines.
    """
    x0, y0, x1, y1 = _INTAGLIO_CARTOUCHE
    white, black = SPECTRA6["white"], SPECTRA6["black"]
    px = image.load()
    for y in range(y0, y1 + 1):
        for x in range(x0, x1 + 1):
            nx = abs((x - (x0 + x1) / 2) / ((x1 - x0) / 2))
            ny = abs((y - (y0 + y1) / 2) / ((y1 - y0) / 2))
            if (nx ** 4 + ny ** 4) ** 0.25 <= 1.0:
                px[x, y] = white
    # The panel's own fine frame: the superellipse contour as a polyline.
    # Parametrised as X = a*sgn(cos)|cos|^(1/2) (the exponent-4 curve's exact
    # parameter form), dense enough that no segment gaps at 1 px.
    a, b = (x1 - x0) / 2, (y1 - y0) / 2
    ccx, ccy = (x0 + x1) / 2, (y0 + y1) / 2
    outline = []
    for i in range(721):
        t = 2 * math.pi * i / 720
        c, s = math.cos(t), math.sin(t)
        outline.append((ccx + a * math.copysign(abs(c) ** 0.5, c),
                        ccy + b * math.copysign(abs(s) ** 0.5, s)))
    draw.line(outline, fill=black, width=1)
    pad = (x0 - 2, y0 - 2, x1 + 2, y1 + 2)
    paint_hatched_tone(image, pad, _intaglio_cartouche_tone,
                       _INTAGLIO_HATCH_ANGLES[0], _INTAGLIO_HATCH_SPACING, black,
                       ground=frozenset({white}))
    paint_hatched_tone(image, pad,
                       lambda x, y: max(0.0, _intaglio_cartouche_tone(x, y) - 0.5) * 2.0,
                       _INTAGLIO_HATCH_ANGLES[1], _INTAGLIO_HATCH_SPACING, black,
                       ground=frozenset({white}))


def _intaglio_paint_masthead(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """Bank-title chrome: letterspaced Cinzel caps over a script promise line."""
    black = SPECTRA6["black"]
    title_font = load_font(theme_font_candidates("intaglio", "ornament"), size=27)
    title = "THE IDLE HOURS"
    tracking = 5.0
    width_px = sum(draw.textlength(ch, font=title_font) for ch in title) + tracking * (len(title) - 1)
    x = (800 - width_px) / 2
    for ch in title:
        draw.text((x, 52), ch, font=title_font, fill=black)
        x += draw.textlength(ch, font=title_font) + tracking
    script_font = load_font([PINYONSCRIPT_REGULAR, *ORNAMENT_FONT_CANDIDATES], size=21)
    draw.text((400, 108), "Promises to pay the bearer on demand", font=script_font,
              fill=black, anchor="mm")


def _intaglio_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The engraved legend: solid black prose, bold matched phrase over a
    green lathework ribbon.

    Draws text directly rather than through the mask pipeline: drawn text
    keeps its antialiased edges through the palette snap. The ribbon is two
    phase-mirrored sinusoids under each bold run, the border band's braid, so
    the phrase reads as a security feature rather than an underline.
    """
    x0, y0, x1, y1 = _INTAGLIO_QUOTE_RECT
    box_w, box_h = x1 - x0, y1 - y0
    black, green = SPECTRA6["black"], SPECTRA6["green"]
    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    quote_font, quote_font_bold, wrapped, line_height, _ = fit_quote(
        draw, display_quote, quote_row.get("matched_text") or "", box_w, box_h,
        font_max=30, font_min=15, line_height_mult=1.3, theme="intaglio",
    )
    y = y0 + max(0, (box_h - len(wrapped) * line_height) // 2)
    body_ascent = _font_ascent(quote_font)
    for line in wrapped:
        start, end = 0, len(line)
        while start < end and line[start][0].strip() == "":
            start += 1
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        segment = line[start:end]
        width_px = sum(draw.textbbox((0, 0), c, font=quote_font_bold if b else quote_font)[2]
                       for c, b in segment)
        x = x0 + max(0, (box_w - width_px) // 2)
        for chunk, is_bold in segment:
            font = quote_font_bold if is_bold else quote_font
            draw.text((x, y + (body_ascent - _font_ascent(font))), chunk, font=font, fill=black)
            advance = draw.textbbox((0, 0), chunk, font=font)[2]
            if is_bold and chunk.strip():
                ry = y + body_ascent + 4
                for sign in (1.0, -1.0):
                    pts = [(rx, ry + sign * 1.6 * math.sin(rx * 0.55))
                           for rx in range(int(x), int(x + advance))]
                    if len(pts) >= 2:
                        draw.line(pts, fill=green, width=1)
            x += advance
        y += line_height


def _intaglio_paint_microprint_rule(image: Image.Image, draw: ImageDraw.ImageDraw) -> None:
    """The rule under the legend is microprint: IDLEHOURS· repeated at 6 px.

    Reads as a hairline at panel distance and resolves as text at arm's length
    — the canonical security feature, essentially free to print.
    """
    font = load_font([SPACEMONO_REGULAR, *META_FONT_CANDIDATES], size=6)
    unit = "IDLEHOURS·"
    x0, x1 = _INTAGLIO_CARTOUCHE[0] + 60, _INTAGLIO_CARTOUCHE[2] - 60
    text = unit * (int((x1 - x0) / max(1.0, draw.textlength(unit, font=font))) + 1)
    while text and draw.textlength(text, font=font) > (x1 - x0):
        text = text[:-1]
    draw.text((x0, 322), text, font=font, fill=SPECTRA6["black"])


def _intaglio_paint_serial(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The numbering press: the same red serial twice, as on a real note."""
    serial = _intaglio_serial(quote_row)
    font = load_font([SPACEMONO_BOLD, *META_FONT_BOLD_CANDIDATES], size=15)
    red = SPECTRA6["red"]
    draw.text((62, 54), serial, font=font, fill=red, anchor="la")
    draw.text((738, 408), serial, font=font, fill=red, anchor="ra")


def _intaglio_paint_attribution(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """Attribution as the note's imprint line, letterspaced inside the panel."""
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or fallback_title(quote_row) or "").strip()
    parts = " — ".join(p for p in (author, title) if p)
    if not parts:
        return
    font = load_font(theme_font_candidates("intaglio", "quote_regular"), size=14)
    while draw.textlength(parts, font=font) > 480 and len(parts) > 8:
        parts = parts[:-2].rstrip(" ,.;:") + "…"
    draw.text((400, 334), parts, font=font, fill=SPECTRA6["black"], anchor="ma")


def render_intaglio_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A banknote face in engraved line-work (see the section comment).

    Composed at 800x480 and NEAREST-downsampled otherwise (the ``metro``
    convention): the geometry and hatch pitch are absolute, and interpolation
    would average the line-work into greys the panel cannot print.
    """
    image = Image.new("RGB", (800, 480), color=SPECTRA6["white"])
    draw = ImageDraw.Draw(image)
    _intaglio_paint_tint(image)
    _intaglio_paint_lathework_band(image, draw)
    _intaglio_paint_rosette(image, draw)
    _intaglio_paint_medallions(image, draw, _clock_hour12(time_str))
    _intaglio_paint_cartouche(image, draw)
    _intaglio_paint_masthead(image, draw)
    _intaglio_paint_quote(image, draw, quote_row)
    _intaglio_paint_microprint_rule(image, draw)
    _intaglio_paint_serial(image, draw, quote_row)
    _intaglio_paint_attribution(image, draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# nocturne — Whistler, Nocturne in Blue and Gold
#
# The Thames at Battersea as Whistler painted it around 1875: a near-black
# blue night of brushwork, punctured by gold. Sky and water are short
# streamline strokes advected through direction fields (``paint_flow_strokes``)
# rather than per-pixel stipple. Full design notes: docs/themes.md
# (``nocturne``).
#
# **Two fields, one vocabulary.** The sky's strokes are sparse, thin and
# near-horizontal, thinning with altitude; the water's are denser, wider and
# shimmer, with an occasional stroke flipped to green in the mid-water (the
# verdigris glaze). The shore is painted *after* the strokes as a solid
# silhouette (plus the shot tower and a chimney), so land reads as the
# absence of light and crops any stroke overhang.
#
# **The gold is bakelite's split-band recipe** (red-major tangerine halo at
# Y 3/8, yellow-major core at Y 5/8, on the 8x8 tile): shore lights, the
# rocket's sparks, the matched phrase and the butterfly monogram. The
# reflections are a third ``paint_flow_strokes`` pass with a near-vertical
# swaying field. Each gold tier accumulates into ONE mask and blooms once (no
# double exposure), and every pass takes ``ground=_nocturne_ground()`` so
# later light never eats earlier light.
#
# **The quote sits in the night.** Prose has white cores with a faint cold
# blue halo; the matched phrase is the brightest gold after the rocket. The
# block sits left of centre so the spark shower owns the upper right.
#
# **No hour carrier: ``time_str`` is del-asserted**, so every render of a row
# is byte-identical at any clock time (pinned by ``TestNocturneBrushwork``).
_NOCTURNE_SKY_BOTTOM = 238
_NOCTURNE_SHORE = (238, 272)
_NOCTURNE_TOWER = (588, 196, 610, 238)         # the Battersea shot tower
_NOCTURNE_CHIMNEY = (636, 212, 644, 238)
_NOCTURNE_QUOTE_RECT = (72, 70, 556, 232)
_NOCTURNE_ROCKET_APEX = (668, 62)
_NOCTURNE_LIGHTS = ((58, 268), (150, 266), (232, 269), (335, 267), (452, 268),
                    (540, 266), (622, 269), (700, 267), (762, 268))
_NOCTURNE_GOLD_HALO_YELLOW = 0.375             # R+Y 5/8:3/8 tangerine, the halo
_NOCTURNE_GOLD_CORE_YELLOW = 0.625             # Y+R 5/8:3/8 gold, the lit stroke
_NOCTURNE_SKY_CELL = 13
_NOCTURNE_WATER_CELL = 8


def _nocturne_ground() -> frozenset:
    """Inks a stroke pass or bloom may overwrite: the night's own colours.

    White, yellow and red are excluded so no later pass can dim a core, a
    spark or a reflection an earlier one already lit.
    """
    return frozenset({SPECTRA6["black"], SPECTRA6["blue"], SPECTRA6["green"]})


def _nocturne_field_sky(x: float, y: float) -> float:
    """Direction of the sky's brushwork: near-horizontal, gently arcing.

    Wavelengths (140 / 220 px) sit far above the 13 px stroke cell so
    neighbouring strokes agree — the coherence rule in ``paint_flow_strokes``.
    """
    return 0.06 * math.sin(x / 140.0) + 0.05 * math.sin((x + y) / 220.0)


def _nocturne_field_water(x: float, y: float) -> float:
    """Direction of the water: horizontal with a shimmer that calms with depth."""
    depth = max(0.0, y - _NOCTURNE_SHORE[1])
    return 0.07 * math.sin(x / 70.0 + y / 45.0) * max(0.35, 1.0 - depth / 300.0)


def _nocturne_sky_ink(x: int, y: int, r: float):
    """Sky stroke acceptance: near-empty at the zenith, quarter-cover at the
    horizon, all blue."""
    density = 0.05 + 0.30 * (y / _NOCTURNE_SKY_BOTTOM) ** 2
    return SPECTRA6["blue"] if r < density else None


def _nocturne_water_ink(x: int, y: int, r: float):
    """Water stroke acceptance, thinning with depth; about one accepted stroke
    in seventeen is green in the mid-water — Whistler's verdigris glaze."""
    depth = max(0.0, y - _NOCTURNE_SHORE[1]) / 208.0
    if r > 0.85 - 0.38 * depth:
        return None
    if 300 <= y <= 400 and int(r * 997) % 17 == 0:
        return SPECTRA6["green"]
    return SPECTRA6["blue"]


def _nocturne_paint_gold(image: Image.Image, mask: Image.Image, core=None,
                         *, radius: int = 4, gamma: float = 1.6, cap: float = 0.55) -> None:
    """Bloom a mask as Whistler's gold — the bakelite amber recipe on the
    night's ground.

    Thin wrapper over ``paint_neon_mask``: red halo carrying 3/8 yellow, gold
    core carrying 5/8 (solid yellow reads lemon). Pass an explicit ``core``
    ink to pin it solid.
    """
    paint_neon_mask(
        image, mask,
        core if core is not None else SPECTRA6["red"], SPECTRA6["red"],
        radius=radius, gamma=gamma, cap=cap, ground=_nocturne_ground(), tile=BAYER_8x8,
        glow_minor=SPECTRA6["yellow"], glow_minor_share=_NOCTURNE_GOLD_HALO_YELLOW,
        core_minor=None if core is not None else SPECTRA6["yellow"],
        core_minor_share=_NOCTURNE_GOLD_CORE_YELLOW,
    )


def _nocturne_paint_night(image: Image.Image) -> None:
    """Layer 0: the black night, with a whisper of blue haze at the horizon,
    kept faint so the light sources stay the subject."""
    ImageDraw.Draw(image).rectangle((0, 0, 799, 479), fill=SPECTRA6["black"])
    px = image.load()
    blue = SPECTRA6["blue"]
    # BAYER_8x8, not 4x4: a ramp on the 17-level tile steps visibly into a
    # hard halftone stripe. The rank is jittered by the position hash (~half a
    # cell) so the ramp doesn't lay a dot lattice.
    for y in range(_NOCTURNE_SKY_BOTTOM - 90, _NOCTURNE_SKY_BOTTOM):
        lift = (y - (_NOCTURNE_SKY_BOTTOM - 90)) / 90.0
        row = BAYER_8x8[y % 8]
        threshold = lift * lift * 7.0
        for x in range(800):
            rank = row[x % 8] + (_flow_stroke_hash(x, y, 11) - 0.5) * 30.0
            if rank < threshold:
                px[x, y] = blue


def _nocturne_paint_strokes(image: Image.Image) -> None:
    """The capability showcase: sky and water as advected brushwork."""
    ground = _nocturne_ground()
    paint_flow_strokes(image, (0, 0, 800, _NOCTURNE_SKY_BOTTOM),
                       _nocturne_field_sky, _nocturne_sky_ink,
                       cell=_NOCTURNE_SKY_CELL, length=16, width=1, ground=ground, salt=1)
    paint_flow_strokes(image, (0, _NOCTURNE_SHORE[1], 800, 480),
                       _nocturne_field_water, _nocturne_water_ink,
                       cell=_NOCTURNE_WATER_CELL, length=30, width=2, ground=ground, salt=2)


def _nocturne_paint_shore(image: Image.Image) -> None:
    """The far bank as absence of light: a solid band, the tower, a chimney.

    Painted after the strokes so it crops their overhang, which is also what
    makes its edge read as a horizon rather than a drawn line.
    """
    draw = ImageDraw.Draw(image)
    black = SPECTRA6["black"]
    draw.rectangle((0, _NOCTURNE_SHORE[0], 799, _NOCTURNE_SHORE[1]), fill=black)
    draw.rectangle(_NOCTURNE_TOWER, fill=black)
    tx0, ty0, tx1, _ = _NOCTURNE_TOWER
    draw.polygon([(tx0, ty0), (tx1, ty0), ((tx0 + tx1) // 2, ty0 - 14)], fill=black)
    draw.rectangle(_NOCTURNE_CHIMNEY, fill=black)


def _nocturne_paint_lights(image: Image.Image) -> None:
    """Gold pinpoints along the far bank, and their smeared reflections.

    The lights accumulate into one mask and bloom once. The reflections are a
    third ``paint_flow_strokes`` pass — near-vertical, swaying, thinning with
    depth — confined by its ``ink_at`` to narrow columns under each light, so
    the same primitive that painted the water also breaks its surface.
    """
    mask = Image.new("L", image.size, 0)
    mask_draw = ImageDraw.Draw(mask)
    for lx, ly in _NOCTURNE_LIGHTS:
        mask_draw.rectangle((lx, ly, lx + 1, ly + 1), fill=255)
    _nocturne_paint_gold(image, mask, radius=4, gamma=1.5, cap=0.6)

    columns = tuple(lx for lx, _ in _NOCTURNE_LIGHTS)

    def reflection_ink(x: int, y: int, r: float):
        depth = (y - _NOCTURNE_SHORE[1]) / 160.0
        if depth > 1.0 or r > max(0.15, 0.85 - depth):
            return None
        sway = 3.0 * math.sin(y / 22.0 + x)
        if min(abs(x + sway - c) for c in columns) > 2.5:
            return None
        return SPECTRA6["yellow"] if int(r * 991) % 3 else SPECTRA6["red"]

    paint_flow_strokes(image, (0, _NOCTURNE_SHORE[1] + 2, 800, _NOCTURNE_SHORE[1] + 164),
                       lambda x, y: math.pi / 2 + 0.28 * math.sin(y / 30.0 + x / 90.0),
                       reflection_ink, cell=5, length=11, width=1,
                       ground=_nocturne_ground(), salt=3)


def _nocturne_spark_points() -> list[tuple[int, int, int]]:
    """The Falling Rocket's spark shower: a fan of parabolic arcs, jittered
    deterministically. Returns ``(x, y, size)`` triples."""
    ax, ay = _NOCTURNE_ROCKET_APEX
    sparks = []
    for j in range(11):
        vx = -1.1 + 2.2 * j / 10.0
        for k in range(10):
            t = (k + 1) / 10.0
            jx = (_flow_stroke_hash(j, k, 41) - 0.5) * 12.0
            jy = (_flow_stroke_hash(j, k, 43) - 0.5) * 14.0
            x = int(ax + vx * 112.0 * t + jx)
            y = int(ay + (0.22 * t + 1.05 * t * t) * 170.0 + jy)
            if 8 <= x <= 792 and 4 <= y <= 256:
                sparks.append((x, y, 3 if t > 0.72 else 2))
    return sparks


def _nocturne_paint_rocket(image: Image.Image) -> None:
    """The Falling Rocket: gold sparks raining down the upper right.

    One mask, one bloom — brighter heads lower down the fall, the way burnt
    charges flare before they die.
    """
    mask = Image.new("L", image.size, 0)
    mask_draw = ImageDraw.Draw(mask)
    for x, y, size in _nocturne_spark_points():
        mask_draw.rectangle((x, y, x + size - 1, y + size - 1), fill=255)
    _nocturne_paint_gold(image, mask, radius=4, gamma=1.6, cap=0.55)


def _nocturne_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The quote in the night sky: white prose in cold halo, gold time phrase."""
    prose, hot, _ = wrap_quote_into_masks(
        draw, image.size, quote_row, _NOCTURNE_QUOTE_RECT,
        theme="nocturne", font_max=32, font_min=16, line_height_mult=1.5,
    )
    paint_neon_mask(image, prose, SPECTRA6["white"], SPECTRA6["blue"],
                    radius=3, gamma=2.0, cap=0.35, ground=_nocturne_ground())
    _nocturne_paint_gold(image, hot, radius=5, gamma=1.5, cap=0.55)


def _nocturne_paint_butterfly(image: Image.Image) -> None:
    """Whistler's butterfly monogram, bottom-right: the signature cartouche.

    Two wing silhouettes and a dropped sting, drawn small and bloomed at the
    tightest radius so it reads as a pressed gold seal rather than a light.
    """
    mask = Image.new("L", image.size, 0)
    mask_draw = ImageDraw.Draw(mask)
    bx, by = 754, 430
    mask_draw.polygon([(bx, by), (bx - 12, by - 9), (bx - 11, by + 7)], fill=255)
    mask_draw.polygon([(bx + 3, by), (bx + 14, by - 10), (bx + 14, by + 6)], fill=255)
    mask_draw.line([(bx + 1, by + 2), (bx - 2, by + 14)], fill=255, width=1)
    _nocturne_paint_gold(image, mask, radius=2, gamma=1.8, cap=0.4)


def _nocturne_paint_credits(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """Attribution, small and solid in the darkest water: unlit by design —
    bloom-vs-no-bloom is the hierarchy, per ``bakelite``."""
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or fallback_title(quote_row) or "").strip()
    parts = " — ".join(p for p in (author, title) if p)
    if not parts:
        return
    font = load_font(theme_font_candidates("nocturne", "quote_regular"), size=14)
    while draw.textlength(parts, font=font) > 470 and len(parts) > 8:
        parts = parts[:-2].rstrip(" ,.;:") + "…"
    draw.text((24, 452), parts, font=font, fill=SPECTRA6["white"], anchor="ls",
              stroke_width=2, stroke_fill=SPECTRA6["black"])


def render_nocturne_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """Whistler's blue-and-gold night river (see the section comment).

    Composed at 800x480 and NEAREST-downsampled otherwise (the ``metro``
    convention): the geometry is absolute, and interpolation would average the
    strokework into blues the panel cannot print.
    """
    del time_str  # see the section comment; deliberately unused.
    image = Image.new("RGB", (800, 480), color=SPECTRA6["black"])
    _nocturne_paint_night(image)
    _nocturne_paint_strokes(image)
    _nocturne_paint_shore(image)
    _nocturne_paint_lights(image)
    _nocturne_paint_rocket(image)
    draw = ImageDraw.Draw(image)
    _nocturne_paint_quote(image, draw, quote_row)
    _nocturne_paint_butterfly(image)
    _nocturne_paint_credits(image, draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# plaque — a patinated bronze memorial plaque
#
# A cast-bronze dedication tablet with relief-lit lettering
# (``paint_relief_mask``): the blurred glyph mask is read as a height field
# and lit from the upper left, so each letter takes a white highlight on its
# lit bevels and a black core shadow opposite. Full design notes:
# docs/themes.md (``plaque``).
#
# **The patina is dark verdigris**: G+B+K at ~33/17/50, see
# ``_plaque_paint_patina`` for why it must be dark. Two incommensurate sine
# fields swing the green/blue balance and a hash jitters the partition so the
# tile never lattices; on an RGB preview it reads lime — judge on the panel's
# muted inks.
#
# **One metal family, one light.** The bead and bolts are the Y+R gold; the
# lettering is burnished brass (Y+W), because the gold is too dark to carry
# text on any ground the panel can make. The matched phrase is the polished
# passage: more white in its face and cut deeper. The dedication and
# attribution are cast too, smaller, in the same brass (see
# ``_plaque_paint_cast_line``).
#
# **The hour is the dedication year**, ``ERECTED · ANNO XI`` in Roman
# numerals. Hour only: every minute of an hour renders byte-identically
# (pinned by ``TestPlaqueRelief``); the minute stays with the matched phrase.
_PLAQUE_RIM = (12, 12, 787, 467)               # outer edge of the cast bead
_PLAQUE_RIM_WIDTH = 7
_PLAQUE_QUOTE_RECT = (84, 96, 716, 330)
_PLAQUE_BOLT_R = 9
_PLAQUE_BOLTS = ((38, 38), (762, 38), (38, 442), (762, 442))
_PLAQUE_GOLD_RED = 0.375                       # Y+R 5/8:3/8 — the documented gold
# Ground: 32 of the 64 tile cells go to green+blue, the rest to black. Every
# share is load-bearing for legibility — see _plaque_paint_patina.
_PLAQUE_PATINA_CELLS = 32.0                    # cells of 64 that are NOT black
# Green takes two thirds of the non-black cells: at an even split the
# panel's more chromatic blue wins the hue and the patina reads navy.
_PLAQUE_GREEN_BASE = 21.0                      # cells of the 32, before the swing
_PLAQUE_SWING = 8.0                            # green<->blue sine amplitude, in cells
# Letter faces, as the white share of a Y+W mix. The Y+R gold is too dark to
# carry text on any ground this panel can make (3.3:1 at best), so it stays on
# the bead and bolts; burnished brass gives the prose ~6.3:1 and the matched
# phrase ~6.6:1.
_PLAQUE_PROSE_WHITE = 0.25                     # pale burnished brass
_PLAQUE_POLISH_WHITE = 0.60                    # rubbed to bright bare metal
# Occlusion crease cut on the radius-2 halo. Measured on a *stroke*: one pixel
# outside a 3 px stem the halo is ~93 and two pixels out ~57, so 55 takes those
# two pixels; much lower (~25) starts closing small counters, and a cut near 96
# creases a glyph nowhere.
_PLAQUE_CONTACT_CUT = 55


def _plaque_ground() -> frozenset:
    """Inks exterior relief shading may overwrite: the patina's own colours."""
    return frozenset({SPECTRA6["green"], SPECTRA6["blue"], SPECTRA6["yellow"], SPECTRA6["black"]})


def _plaque_paint_patina(image: Image.Image) -> None:
    """Layer 0: verdigris over dark bronze — half black, half green/blue.

    Of each 8x8 tile, black takes a fixed half and green/blue the rest
    (~33/17 before the swing). The green/blue boundary is swung by two slow
    sine fields (corrosion pools and streaks) and the read is jittered by the
    position hash so the ordered tile cannot lattice.

    **The ground is dark because no lighter one can carry text.** On a
    mid-tone like the catalogue's forest-teal (G+B+Y 40/40/20) even pure white
    reaches only ~3.85:1. Recessed bronze genuinely darkens with grime while
    the raised letters stay burnished.

    **The swing trades hue, not luminance.** It moves only green against blue
    while black keeps its half. Don't let it spend on a bright ink (yellow):
    patches of ground then match the letters' brightness and the inscription
    vanishes. ``TestPlaqueRelief`` fences the local luminance band, since a
    whole-canvas average hides the fault.
    """
    px = image.load()
    green, blue, black = (SPECTRA6[c] for c in ("green", "blue", "black"))
    for y in range(480):
        row = BAYER_8x8[y % 8]
        for x in range(800):
            h = _flow_stroke_hash(x, y, 5)
            swing = _PLAQUE_SWING * (math.sin(x / 97.0 + y / 61.0) + math.sin(x / 41.0 - y / 149.0))
            rank = (row[x % 8] + (h - 0.5) * 3.0) % 64
            # Both cuts move as one, so the swing trades green against blue
            # while black keeps its fixed half; face contrast holds
            # 6.1-6.4:1 across the sweep.
            green_cut = min(_PLAQUE_PATINA_CELLS, max(0.0, _PLAQUE_GREEN_BASE + swing))
            if rank < green_cut:
                px[x, y] = green
            elif rank < _PLAQUE_PATINA_CELLS:
                px[x, y] = blue
            else:
                px[x, y] = black


def _plaque_paint_rim(image: Image.Image) -> None:
    """The cast border bead: a raised bronze ring under the shared light."""
    mask = Image.new("L", image.size, 0)
    mask_draw = ImageDraw.Draw(mask)
    mask_draw.rounded_rectangle(_PLAQUE_RIM, radius=18, outline=255, width=_PLAQUE_RIM_WIDTH)
    paint_relief_mask(image, mask, highlight=SPECTRA6["white"], shadow=SPECTRA6["black"],
                      face=SPECTRA6["yellow"], face_minor=SPECTRA6["red"],
                      face_minor_share=_PLAQUE_GOLD_RED,
                      radius=2, strength=3.2, cap=0.6, ground=_plaque_ground())


def _plaque_paint_bolts(image: Image.Image) -> None:
    """Four bolt heads pinning the tablet, each with its own specular tick."""
    draw = ImageDraw.Draw(image)
    mask = Image.new("L", image.size, 0)
    mask_draw = ImageDraw.Draw(mask)
    r = _PLAQUE_BOLT_R
    for cx, cy in _PLAQUE_BOLTS:
        mask_draw.ellipse((cx - r, cy - r, cx + r, cy + r), fill=255)
    paint_relief_mask(image, mask, highlight=SPECTRA6["white"], shadow=SPECTRA6["black"],
                      face=SPECTRA6["yellow"], face_minor=SPECTRA6["red"],
                      face_minor_share=_PLAQUE_GOLD_RED,
                      radius=2, strength=3.6, cap=0.65, ground=_plaque_ground())
    for cx, cy in _PLAQUE_BOLTS:
        draw.ellipse((cx - r + 2, cy - r + 2, cx - r + 4, cy - r + 4), fill=SPECTRA6["white"])


def _plaque_paint_quote(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The inscription: raised brass prose, polished matched phrase.

    Two masks from ``wrap_quote_into_masks``, each relief-lit once. The hot
    pass cuts deeper and its face carries more white, so the time phrase
    reads as the tablet's brightest metal under the same light.

    Both passes lay a ``contact`` crease — the occlusion line where a raised
    letter meets the plate — closing the contour on the arcs the raking light
    leaves unshaded. On the dark ground it is a modest edge-contrast gain, not
    load-bearing.
    """
    prose, hot, _ = wrap_quote_into_masks(
        draw, image.size, quote_row, _PLAQUE_QUOTE_RECT,
        theme="plaque", font_max=40, font_min=17, line_height_mult=1.42,
    )
    paint_relief_mask(image, prose, highlight=SPECTRA6["white"], shadow=SPECTRA6["black"],
                      face=SPECTRA6["yellow"], face_minor=SPECTRA6["white"],
                      face_minor_share=_PLAQUE_PROSE_WHITE,
                      radius=2, strength=3.4, cap=0.6, ground=_plaque_ground(),
                      shade_face=False,
                      contact=SPECTRA6["black"], contact_cut=_PLAQUE_CONTACT_CUT)
    paint_relief_mask(image, hot, highlight=SPECTRA6["white"], shadow=SPECTRA6["black"],
                      face=SPECTRA6["yellow"], face_minor=SPECTRA6["white"],
                      face_minor_share=_PLAQUE_POLISH_WHITE,
                      radius=2, strength=4.2, cap=0.75, ground=_plaque_ground(),
                      shade_face=False,
                      contact=SPECTRA6["black"], contact_cut=_PLAQUE_CONTACT_CUT)


def _plaque_paint_cast_line(image: Image.Image, draw: ImageDraw.ImageDraw, text: str, y: int, size: int) -> None:
    """A line of small cast text, raised and lit like the inscription above it.

    Cast rather than engraved: on the dark patina an incised black groove
    measures ~1.3:1 (invisible), and a recess with a lit lip reads as an
    outline rather than as metal. The fine print stays subordinate by size,
    in the same brass under the same light.
    """
    font = load_font(theme_font_candidates("plaque", "quote_regular"), size=size)
    while draw.textlength(text, font=font) > 560 and len(text) > 8:
        text = text[:-2].rstrip(" ,.;:") + "…"
    mask = Image.new("L", image.size, 0)
    ImageDraw.Draw(mask).text((400, y), text, font=font, fill=255, anchor="ma")
    paint_relief_mask(image, mask, highlight=SPECTRA6["white"], shadow=SPECTRA6["black"],
                      face=SPECTRA6["yellow"], face_minor=SPECTRA6["white"],
                      face_minor_share=_PLAQUE_PROSE_WHITE,
                      radius=1, strength=3.0, cap=0.55,
                      ground=_plaque_ground(), shade_face=False,
                      contact=SPECTRA6["black"], contact_cut=_PLAQUE_CONTACT_CUT)


def _plaque_paint_dedication(image: Image.Image, draw: ImageDraw.ImageDraw, hour: int) -> None:
    numeral = _TAROT_ROMAN_NUMERALS[hour]
    _plaque_paint_cast_line(image, draw, f"ERECTED · ANNO {numeral}", 412, 20)


def _plaque_paint_attribution(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or fallback_title(quote_row) or "").strip()
    parts = " — ".join(p for p in (author, title) if p)
    if not parts:
        return
    _plaque_paint_cast_line(image, draw, parts, 376, 19)


def render_plaque_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A patinated bronze tablet with relief-lit lettering (see the section
    comment).

    Composed at 800x480 and NEAREST-downsampled otherwise (the ``metro``
    convention): the geometry is absolute, and interpolation would average
    the patina's inks into colours the panel cannot print.
    """
    image = Image.new("RGB", (800, 480), color=SPECTRA6["green"])
    _plaque_paint_patina(image)
    _plaque_paint_rim(image)
    _plaque_paint_bolts(image)
    draw = ImageDraw.Draw(image)
    _plaque_paint_quote(image, draw, quote_row)
    _plaque_paint_attribution(image, draw, quote_row)
    _plaque_paint_dedication(image, draw, _clock_hour12(time_str))
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# Shared mount furniture for the photographic frames.
#
# ``daguerreotype``, ``autochrome`` and ``photo`` present a plate with the
# quote on a cream card beside it; the card stock, the centred styled-line
# loop and the truncating byline live here. ``pulp``, ``vhs``, ``intaglio``
# and ``wrap_quote_into_masks`` keep near copies of the line loop (anchoring,
# mask vs canvas and phrase colouring differ); folding them in would churn
# golden fixtures for no behaviour change.


def paint_mount_card(image: Image.Image, draw: ImageDraw.ImageDraw,
                     rect: tuple[int, int, int, int], ledge: int, *,
                     outline_width: int = 1) -> None:
    """Cream card stock on a drop-shadow ledge, keylined in black.

    The Y+W cream at the aged-paper themes' 12.5% density, over a black
    ledge: without it a light card on a light plate reads as a hole cut in
    the picture. ``outline_width`` defaults to a 1 px keyline; ``photo`` asks
    for 2, since an operator's photograph may be pale right up to the card.
    """
    x0, y0, x1, y1 = rect
    black, white, yellow = SPECTRA6["black"], SPECTRA6["white"], SPECTRA6["yellow"]
    draw.rectangle((x0 + ledge, y0 + ledge, x1 + ledge, y1 + ledge), fill=black)
    draw.rectangle((x0, y0, x1, y1), fill=white)
    px = image.load()
    for y in range(y0, y1 + 1):
        row = BAYER_4x4[y % 4]
        for x in range(x0, x1 + 1):
            if row[x % 4] < 2:
                px[x, y] = yellow
    draw.rectangle((x0, y0, x1, y1), outline=black, width=outline_width)


def draw_centred_styled_lines(draw: ImageDraw.ImageDraw, wrapped, *, x0: int, x1: int,
                              top: int, line_height: int, regular, bold,
                              fill, accent, min_inset: int = 18) -> int:
    """Draw ``fit_quote``'s wrapped output centred in ``x0..x1``, returning the
    y after the last line.

    Leading and trailing whitespace chunks are trimmed off each line before it
    is measured, or a wrapped line's trailing space shifts the centring; and
    every chunk is aligned on the body font's ascent, so a size difference
    between the regular and bold faces cannot make the matched phrase float.
    """
    body_ascent = _font_ascent(regular)
    y = top
    for line in wrapped:
        start, end = 0, len(line)
        while start < end and line[start][0].strip() == "":
            start += 1
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        segment = line[start:end]
        width_px = sum(draw.textbbox((0, 0), c, font=bold if b else regular)[2]
                       for c, b in segment)
        x = x0 + max(min_inset, ((x1 - x0) - width_px) // 2)
        for chunk, is_bold in segment:
            font = bold if is_bold else regular
            draw.text((x, y + (body_ascent - _font_ascent(font))), chunk,
                      font=font, fill=accent if is_bold else fill)
            x += draw.textbbox((0, 0), chunk, font=font)[2]
        y += line_height
    return y


def tracked_width(draw, text: str, font, *, tracking: float) -> float:
    """Width of ``text`` as ``draw_tracked`` will paint it: per-glyph advances
    plus ``tracking`` between glyphs. A per-glyph sum, not ``textlength`` of the
    whole string, because the glyph-by-glyph draw drops kerning."""
    if not text:
        return 0.0
    return sum(draw.textlength(ch, font=font) for ch in text) + tracking * (len(text) - 1)


def draw_tracked(draw, xy, text: str, font, fill, *, tracking: float, anchor_right: bool = False) -> float:
    """Letterspaced caps — an instrument panel's silkscreened legend, a
    wayfinding sign, a banknote masthead. Returns the run's width.

    PIL has no tracking, so the string is stepped a glyph at a time. Works
    against an ``"L"`` bloom mask as readily as against the image. With
    ``anchor_right`` the run ends at ``xy[0]`` instead of starting there.
    """
    x, y = xy
    width = tracked_width(draw, text, font, tracking=tracking)
    if anchor_right:
        x -= width
    for ch in text:
        draw.text((x, y), ch, font=font, fill=fill)
        x += draw.textlength(ch, font=font) + tracking
    return width


def fit_text_to_width(draw, text: str, candidates, size: int, max_width: float, *,
                      floor: int, tracking: float = 0):
    """Shrink a chrome string until it fits, then ellipsise at the floor.

    Returns ``(font, text)``. The floor keeps the string readable across a
    room; below it the value is truncated with an ellipsis instead of shrunk
    further. Measured the way it will be painted: as one kerned run when
    ``tracking`` is 0, glyph by glyph (via ``tracked_width``) otherwise.
    """
    def measure(candidate: str, font) -> float:
        if tracking:
            return tracked_width(draw, candidate, font, tracking=tracking)
        return draw.textlength(candidate, font=font)

    while size > floor:
        font = load_font(candidates, size=size)
        if measure(text, font) <= max_width:
            return font, text
        size -= 2
    font = load_font(candidates, size=floor)
    while len(text) > 1 and measure(text, font) > max_width:
        text = text[:-2].rstrip(" ,.;:") + "…"
    return font, text


def _fit_from_title(draw: ImageDraw.ImageDraw, quote_row: dict, font, max_w: int) -> str | None:
    """``— from {Title} —`` shortened to ``max_w`` with a trailing ellipsis.

    ``None`` when the row has no title, or no room for even a stub of one —
    the caller drops the footer. The loop guards on ``title``, the string that
    shrinks, not on the text: that is rebuilt from a template and never
    empties, so guarding on it spins forever when even ``— from … —``
    overflows, hanging the render path.
    """
    title = (quote_row.get("title") or "").strip()
    if not title:
        return None
    text = f"— from {title} —"
    while title and draw.textlength(text, font=font) > max_w:
        title = title[:-1]
        text = f"— from {title.rstrip()}… —"
    return text if title else None


def _fit_dotted_byline(draw: ImageDraw.ImageDraw, quote_row: dict, font, max_w: int):
    """``author · title`` shortened to ``max_w``, title side first.

    Returns ``(text, bbox)`` for the caller to align, or ``None`` when the row
    has neither author nor title. The tail part loses three characters to an
    ellipsis per step until it is six characters or fewer, then is dropped.
    """
    author = quote_row.get("author") or ""
    title = quote_row.get("title") or fallback_title(quote_row)
    parts = [p for p in (author, title) if p]
    if not parts:
        return None
    text = " · ".join(parts)
    bbox = draw.textbbox((0, 0), text, font=font)
    while parts and bbox[2] - bbox[0] > max_w:
        if len(parts[-1]) > 6:
            parts[-1] = parts[-1][:-3] + "…"
        else:
            parts.pop()
        text = " · ".join(parts)
        bbox = draw.textbbox((0, 0), text, font=font)
    return text, bbox


def draw_truncated_centred_byline(draw: ImageDraw.ImageDraw, quote_row: dict, *,
                                  centre: int, baseline: int, max_width: int,
                                  font, fill) -> None:
    """Author and title centred on a baseline, ellipsised to fit.

    ``max_width`` is the panel the byline actually sits in, passed in rather
    than hardcoded.
    """
    author = (quote_row.get("author") or "").strip()
    title = (quote_row.get("title") or fallback_title(quote_row) or "").strip()
    parts = " — ".join(p for p in (author, title) if p)
    if not parts:
        return
    while draw.textlength(parts, font=font) > max_width and len(parts) > 8:
        parts = parts[:-2].rstrip(" ,.;:") + "…"
    draw.text((centre, baseline), parts, font=font, fill=fill, anchor="ms")


# ---------------------------------------------------------------------------
# daguerreotype — a cased monochrome photograph
#
# An 1850s cased daguerreotype: brass mat, oval window, a silvered plate, and
# the quote on a cream caption slip. Full design notes: docs/themes.md
# (``daguerreotype``).
#
# The plate is a committed continuous-tone landscape
# (``scripts/generate_daguerreotype_plate.py``) Atkinson-dithered at render
# time against white+black only (``dither_image_to_palette``: Atkinson's
# discarded error blows highlights to silver and crushes shadows, the
# process's tonal signature), so no chroma scatters into the silver. All
# colour belongs to the case: the brass mat (Y+R gold), the pewter rim (K+W
# 50/50), and an R+G tarnish ring creeping in from the oval's rim that
# doubles as the vignette. The mat's pressed double ring is
# ``paint_relief_mask``. A missing plate degrades to
# ``_daguerreotype_paint_plate_fallback``.
#
# A photograph carries no clock: ``time_str`` is del-asserted (pinned by
# ``TestDaguerreotypePlate``). The matched phrase is solid red on the slip —
# R+K maroon shreds at caption size and gold on cream goes pale.
_DAG_OVAL = (58, 40, 482, 440)                 # the mat's window, bbox
_DAG_RING_GAP = 7                              # pressed ring offset outside the oval
_DAG_RIM = 16                                  # pewter case band width
_DAG_SLIP = (508, 86, 766, 394)                # the caption slip
_DAG_TARNISH_START = 0.80                      # radial fraction where tarnish begins
_DAG_GOLD_RED = 0.375                          # Y+R 5/8:3/8 — the documented gold


def _daguerreotype_oval_radial(x: float, y: float) -> float:
    """Normalised radial position inside the oval window: 0 centre, 1 rim."""
    x0, y0, x1, y1 = _DAG_OVAL
    nx = (x - (x0 + x1) / 2) / ((x1 - x0) / 2)
    ny = (y - (y0 + y1) / 2) / ((y1 - y0) / 2)
    return math.hypot(nx, ny)


def _daguerreotype_paint_mat(image: Image.Image) -> None:
    """The case: brass mat field (Y+R gold) inside a pewter rim (the K+W
    50/50 checkerboard, which reads as brushed metal next to the brass)."""
    px = image.load()
    yellow, red, white, black = (SPECTRA6[c] for c in ("yellow", "red", "white", "black"))
    gold_cut = 64 * _DAG_GOLD_RED
    for y in range(480):
        row = BAYER_8x8[y % 8]
        for x in range(800):
            if x < _DAG_RIM or y < _DAG_RIM or x >= 800 - _DAG_RIM or y >= 480 - _DAG_RIM:
                px[x, y] = white if (x + y) & 1 else black
            else:
                px[x, y] = red if row[x % 8] < gold_cut else yellow
    draw = ImageDraw.Draw(image)
    draw.rectangle((_DAG_RIM, _DAG_RIM, 799 - _DAG_RIM, 479 - _DAG_RIM),
                   outline=black, width=1)


def _daguerreotype_paint_plate(image: Image.Image) -> None:
    """The silver image: the committed landscape, Atkinson-dithered W/K,
    clipped to the oval window."""
    x0, y0, x1, y1 = _DAG_OVAL
    ow, oh = x1 - x0, y1 - y0
    plate = _load_dithered_plate(DAGUERREOTYPE_PLATE, ow, oh,
                                 method="atkinson", palette=_SILVER_PALETTE)
    px = image.load()
    if plate is None:
        _daguerreotype_paint_plate_fallback(image)
        return
    pp = plate.load()
    for y in range(y0, y1):
        for x in range(x0, x1):
            if _daguerreotype_oval_radial(x, y) <= 1.0:
                px[x, y] = pp[x - x0, y - y0]


def _daguerreotype_paint_plate_fallback(image: Image.Image) -> None:
    """A stripped install still gets a photograph-shaped silver image: sky
    blowing to white, a Bayer-graded mid band, a crushed dark foreground."""
    px = image.load()
    white, black = SPECTRA6["white"], SPECTRA6["black"]
    x0, y0, x1, y1 = _DAG_OVAL
    for y in range(y0, y1):
        t = (y - y0) / (y1 - y0)
        row = BAYER_8x8[y % 8]
        threshold = 0.0 if t < 0.45 else (t - 0.45) * 150.0
        for x in range(x0, x1):
            if _daguerreotype_oval_radial(x, y) <= 1.0:
                px[x, y] = black if row[x % 8] < threshold else white


def _daguerreotype_paint_tarnish(image: Image.Image) -> None:
    """The sepia bloom creeping in from the oval's rim: R+G on pixel parity
    (the documented sepia), hash-gated at a density that rises toward the
    edge so it is also the plate's vignette."""
    px = image.load()
    red, green = SPECTRA6["red"], SPECTRA6["green"]
    x0, y0, x1, y1 = _DAG_OVAL
    for y in range(y0, y1):
        for x in range(x0, x1):
            radial = _daguerreotype_oval_radial(x, y)
            if radial > 1.0 or radial < _DAG_TARNISH_START:
                continue
            reach = (radial - _DAG_TARNISH_START) / (1.0 - _DAG_TARNISH_START)
            if _flow_stroke_hash(x, y, 7) < reach * reach * 0.85:
                px[x, y] = red if (x + y) & 1 else green


def _daguerreotype_paint_ring(image: Image.Image) -> None:
    """The mat's pressed double ring: ``paint_relief_mask``'s second consumer,
    embossing brass around the window under the shared upper-left light."""
    mask = Image.new("L", image.size, 0)
    mask_draw = ImageDraw.Draw(mask)
    g = _DAG_RING_GAP
    x0, y0, x1, y1 = _DAG_OVAL
    mask_draw.ellipse((x0 - g, y0 - g, x1 + g, y1 + g), outline=255, width=3)
    mask_draw.ellipse((x0 - g - 8, y0 - g - 8, x1 + g + 8, y1 + g + 8), outline=255, width=2)
    paint_relief_mask(image, mask, highlight=SPECTRA6["white"], shadow=SPECTRA6["black"],
                      face=SPECTRA6["yellow"], face_minor=SPECTRA6["red"],
                      face_minor_share=_DAG_GOLD_RED,
                      radius=2, strength=3.4, cap=0.6,
                      ground=frozenset({SPECTRA6["yellow"], SPECTRA6["red"]}))


def _daguerreotype_paint_slip(image: Image.Image, draw: ImageDraw.ImageDraw, quote_row: dict) -> None:
    """The caption slip: cream stock lifted on a shadow ledge, the quote in
    Libre Caslon with the matched phrase in the studio's red ink."""
    x0, y0, x1, y1 = _DAG_SLIP
    black = SPECTRA6["black"]
    paint_mount_card(image, draw, _DAG_SLIP, ledge=3)

    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    quote_font, quote_font_bold, wrapped, line_height, _ = fit_quote(
        draw, display_quote, quote_row.get("matched_text") or "",
        x1 - x0 - 36, y1 - y0 - 88, font_max=26, font_min=14,
        line_height_mult=1.32, theme="daguerreotype",
    )
    draw_centred_styled_lines(
        draw, wrapped, x0=x0, x1=x1, top=y0 + 26, line_height=line_height,
        regular=quote_font, bold=quote_font_bold,
        fill=black, accent=SPECTRA6["red"],
    )
    draw_truncated_centred_byline(
        draw, quote_row, centre=(x0 + x1) // 2, baseline=y1 - 20,
        max_width=x1 - x0 - 30, fill=black,
        font=load_font(theme_font_candidates("daguerreotype", "quote_regular"), size=13),
    )


def render_daguerreotype_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A cased daguerreotype (see the section comment).

    Composed at 800x480 and NEAREST-downsampled otherwise (the ``metro``
    convention): the case geometry is absolute, and interpolation would
    average the silver stipple into greys the panel cannot print.
    """
    del time_str  # see the section comment; deliberately unused.
    image = Image.new("RGB", (800, 480), color=SPECTRA6["white"])
    _daguerreotype_paint_mat(image)
    _daguerreotype_paint_plate(image)
    _daguerreotype_paint_tarnish(image)
    _daguerreotype_paint_ring(image)
    draw = ImageDraw.Draw(image)
    _daguerreotype_paint_slip(image, draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# autochrome — a colour photograph, in the panel's own idiom
#
# Autochrome Lumière plates were a stochastic mosaic of dyed starch grains
# the eye integrates — the same object as a dither to six inks. Full design
# notes: docs/themes.md (``autochrome``).
#
# The only plate dithered against the full six-ink palette: the other plate
# themes restrict the candidates so diffusion cannot scatter chroma into
# their ground, but here the chroma is the subject. The source is muted and
# high-key on purpose: a saturated source quantises to chunky colour bars,
# while a soft desaturated one breaks into fine grain. The committed garden
# (``scripts/generate_autochrome_plate.py``) puts all six inks on the page;
# ``TestAutochromePlate`` checks every ink is present and none but white
# dominates.
#
# The mount is a passe-partout of black binding tape; the quote sits on a
# cream card on a black shadow ledge (``paint_mount_card``). The matched
# phrase is solid red: the nearest solid ink to the dominant orange-red
# grain, and a two-ink stipple at caption size shreds a serif.
#
# A photograph carries no clock: ``time_str`` is del-asserted. Composed at
# 800x480 and NEAREST-downsampled otherwise (the ``metro`` convention).
_AUTOCHROME_TAPE = 13                       # passe-partout binding tape, px
_AUTOCHROME_CORNER = 7                      # extra reach where tape strips overlap
_AUTOCHROME_CARD = (458, 56, 770, 424)      # the caption card
_AUTOCHROME_LEDGE = 3                       # the card's drop shadow


def _autochrome_paint_plate(image: Image.Image) -> None:
    """The photograph: the committed garden, Floyd-Steinberg-dithered against
    all six inks, full bleed."""
    plate = _load_dithered_plate(AUTOCHROME_PLATE, 800, 480, palette=_AUTOCHROME_PALETTE)
    if plate is None:
        _autochrome_paint_garden_fallback(image)
        return
    image.paste(plate, (0, 0))


def _autochrome_paint_garden_fallback(image: Image.Image) -> None:
    """A stripped install still gets a garden-shaped colour field: the plate's
    three bands (sky hazing to white, tree line and lawn, a bloom-scattered
    bed) as ``BAYER_8x8`` density ramps, so the theme still reads as a colour
    picture rather than a blank ground.
    """
    px = image.load()
    white, black, blue, green, yellow, red = (
        SPECTRA6[c] for c in ("white", "black", "blue", "green", "yellow", "red"))
    horizon, beds = 192, 250
    for y in range(480):
        row = BAYER_8x8[y % 8]
        if y < horizon:
            # Sky: blue density falling toward the horizon haze.
            density = 0.42 * (1.0 - y / horizon) ** 0.8
            ink, ground = blue, white
        elif y < beds:
            density = 0.34
            ink, ground = green, white
        else:
            # Lawn deepening toward the viewer, warmed by the beds.
            t = (y - beds) / (480 - beds)
            density = 0.30 + 0.24 * t
            ink, ground = green, yellow
        cut = 64 * density
        for x in range(800):
            px[x, y] = ink if row[x % 8] < cut else ground
    # A drift of blooms across the beds, and the shadow under them: painted
    # from a positional hash so the fallback stays deterministic.
    for y in range(beds, 480):
        for x in range(800):
            h = _flow_stroke_hash(x // 3, y // 3, 11)
            if h < 0.020:
                px[x, y] = red
            elif h < 0.032:
                px[x, y] = yellow
            elif h < 0.044:
                px[x, y] = black


def _autochrome_paint_tape(draw: ImageDraw.ImageDraw) -> None:
    """The passe-partout: black gummed tape binding the glass sandwich, with a
    hairline of light at the paper mask's edge just inside it. The corners
    are thicker where the four strips overlap, which reads as tape rather
    than as a drawn frame.
    """
    black, white = SPECTRA6["black"], SPECTRA6["white"]
    t = _AUTOCHROME_TAPE
    draw.rectangle((0, 0, 799, t - 1), fill=black)
    draw.rectangle((0, 480 - t, 799, 479), fill=black)
    draw.rectangle((0, 0, t - 1, 479), fill=black)
    draw.rectangle((800 - t, 0, 799, 479), fill=black)
    c = t + _AUTOCHROME_CORNER
    for x0, y0 in ((0, 0), (800 - c, 0), (0, 480 - c), (800 - c, 480 - c)):
        draw.rectangle((x0, y0, x0 + c - 1, y0 + c - 1), fill=black)
    draw.rectangle((t, t, 799 - t, 479 - t), outline=white, width=1)


def _autochrome_paint_card(image: Image.Image, draw: ImageDraw.ImageDraw,
                           quote_row: dict) -> None:
    """The caption card: cream stock on a shadow ledge, carrying the quote in
    Libre Caslon with the matched phrase in the studio's red ink."""
    x0, y0, x1, y1 = _AUTOCHROME_CARD
    black, red = SPECTRA6["black"], SPECTRA6["red"]
    paint_mount_card(image, draw, _AUTOCHROME_CARD, ledge=_AUTOCHROME_LEDGE)

    # Mount chrome: the process name letterspaced with plain spaces under a
    # hairline rule, in the metadata sans.
    draw.text(((x0 + x1) // 2, y0 + 18), " ".join("AUTOCHROME"),
              font=load_font(META_FONT_BOLD_CANDIDATES, size=10), fill=black, anchor="ms")
    draw.line((x0 + 34, y0 + 26, x1 - 34, y0 + 26), fill=black, width=1)

    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    quote_font, quote_font_bold, wrapped, line_height, _ = fit_quote(
        draw, display_quote, quote_row.get("matched_text") or "",
        x1 - x0 - 36, y1 - y0 - 92, font_max=26, font_min=13,
        line_height_mult=1.34, theme="autochrome",
    )
    draw_centred_styled_lines(
        draw, wrapped, x0=x0, x1=x1, top=y0 + 46, line_height=line_height,
        regular=quote_font, bold=quote_font_bold, fill=black, accent=red,
    )
    draw_truncated_centred_byline(
        draw, quote_row, centre=(x0 + x1) // 2, baseline=y1 - 18,
        max_width=x1 - x0 - 30, fill=black,
        font=load_font(theme_font_candidates("autochrome", "quote_regular"), size=13),
    )


def render_autochrome_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """An autochrome plate in its passe-partout (see the section comment)."""
    del time_str  # a photograph carries no clock; see the section comment.
    image = Image.new("RGB", (800, 480), color=SPECTRA6["white"])
    _autochrome_paint_plate(image)
    draw = ImageDraw.Draw(image)
    _autochrome_paint_tape(draw)
    _autochrome_paint_card(image, draw, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# photo — the operator's own picture
#
# ``autochrome``'s machinery pointed at a file the operator chooses — the only
# theme whose art is not committed. Full design notes: docs/themes.md
# (``photo``).
#
# **The path arrives through the environment, not argv**
# (``IDLE_HOURS_PHOTO_PATH``): an operator's own ``--render-script`` would
# reject an unknown flag and send the appliance into render backoff (see
# ``run_clock._corpus_render_args``). ``run_clock.main`` exports it into its
# own environment, so render children inherit it and in-process callers
# (``/api/preview``, ``contact_sheet``) read the same value.
#
# **An arbitrary photograph does not dither well**: a saturated source
# quantises to chunky colour bars. ``_photo_condition`` pulls saturation and
# contrast into the band that survives, adaptively — factors computed from the
# source and clamped so they only ever reduce, leaving a gentle photo alone.
#
# **The card cannot sit in a fixed place**, because that place might be the
# face. ``_photo_card_rect`` scores candidate positions by the detail and
# salience each would cover, measured on the conditioned image before
# dithering, and takes the cheapest.
#
# Everything else is defensive. The source is a file or a directory (rotated
# with the quote via ``_row_digest``), and every operator failure mode — a
# missing path, a misnamed file, CMYK, EXIF rotation, a decompression bomb, an
# empty directory — degrades to the bundled ``autochrome`` plate with a
# latched warning rather than raising into the per-tick render path.

# Extensions attempted from a directory listing: an allowlist, because probing
# every file with Image.open is slow and a wider attack surface.
_PHOTO_SUFFIXES = frozenset({".jpg", ".jpeg", ".png", ".webp", ".bmp", ".gif", ".tif", ".tiff"})

# Bounded: a directory can hold thousands of files and each decoded 800x480
# frame is ~1.1 MB. The key includes caller-controlled geometry, so an
# unbounded cache would let /api/preview clients retain memory per size.
_PHOTO_CACHE: "collections.OrderedDict[tuple, tuple[Image.Image, tuple[int, int, int, int]]]" = (
    collections.OrderedDict())
_PHOTO_CACHE_MAX = 6
# Decode cap: a 56 MP PNG costs ~212 MiB of RSS (~3.8 MiB per megapixel), so
# 40 MP bounds a non-draftable decode at ~150 MiB, which a 512 MB Pi survives
# alongside the main loop. JPEGs are drafted down first (see ``_photo_open``).
_PHOTO_MAX_PIXELS = 40_000_000
# Warnings latch per resolved source so a stale path does not write a line per
# render (SD-card wear) — the ``pick_quote._DEGRADED_WARNED`` pattern.
_PHOTO_WARNED: set = set()

# Conditioning targets, read off the shipped ``autochrome`` plate (chroma
# 0.163, mean luminance 0.671, spread 0.142), which dithers to a fine grain
# with white carrying the tone. They are ceilings: a gentler photograph is
# left alone.
#
# Chroma is ``(max - min) / 255`` per pixel, NOT HSV saturation, and that is
# load-bearing: ``ImageEnhance.Color`` blends toward grey, so it scales this
# quantity linearly and ``target / measured`` lands in one pass. HSV
# saturation is a ratio, and the same factor badly undershoots on dark colours.
_PHOTO_TARGET_CHROMA = 0.18
_PHOTO_TARGET_MEAN = 0.63
_PHOTO_SPREAD_CEILING = 0.22     # only compress contrast well above the reference
_PHOTO_MIN_CONTRAST = 0.75       # ...and never flatten it
_PHOTO_MEAN_TOLERANCE = 0.06
_PHOTO_SOFT_FOCUS = 0.6

# How much a tonally-unusual region costs relative to a detailed one. At 0.5
# a smooth bright subject is about as expensive to cover as moderate
# texture, which is the balance that keeps the card off a sun without
# driving it onto foliage.
_PHOTO_SALIENCE_WEIGHT = 0.5
# How much the single worst cell under a candidate counts alongside its mean.
_PHOTO_PEAK_WEIGHT = 0.5

_PHOTO_CARD_W, _PHOTO_CARD_H = 312, 368
_PHOTO_CARD_MARGIN = 34
# Candidate card anchors, in the order ties are broken. Right-hand positions
# come first because a caption on the right is the conventional reading order
# for a picture-plus-text plate, so an image with no quiet region at all still
# lands somewhere deliberate.
_PHOTO_CARD_ANCHORS = ((1, 0.5), (0, 0.5), (1, 0.0), (0, 0.0), (1, 1.0), (0, 1.0))


def _photo_source() -> str | None:
    """The configured photo file or directory, or ``None``.

    Read per render rather than captured at import: ``run_clock`` exports the
    variable during ``main``, after this module is already imported by the
    in-process peek path, and a test that sets it must not have to reload the
    module.
    """
    value = os.environ.get(PHOTO_PATH_ENV, "").strip()
    return value or None


def _photo_warn_once(key: str, message: str) -> None:
    if key not in _PHOTO_WARNED:
        _PHOTO_WARNED.add(key)
        print(f"photo theme: {message}", file=sys.stderr)


def clear_photo_cache() -> None:
    """Drop the decoded-frame cache and the warning latch.

    Public because a test asserting on a warning must not be silenced by a
    previous one, the same contract ``pick_quote.clear_corpus_cache`` keeps.
    """
    _PHOTO_CACHE.clear()
    _PHOTO_WARNED.clear()


def _photo_candidates(source: str) -> list[Path]:
    """Resolve the configured source to a list of candidate image files.

    A file yields itself (whatever its extension — the operator named it
    explicitly, so honour that); a directory yields its sorted image-suffixed
    entries. Sorted so the digest-driven pick is stable across filesystems,
    whose directory order is not.
    """
    path = resolve_input_path(source, BASE_DIR)
    try:
        if path.is_file():
            return [path]
        if path.is_dir():
            return sorted(p for p in path.iterdir()
                          if p.is_file() and p.suffix.lower() in _PHOTO_SUFFIXES)
    except OSError:
        return []
    return []


def _photo_for_row(quote_row: dict) -> Path | None:
    """Pick this render's photograph.

    A directory rotates with the *quote* rather than with the clock, which is
    the cadence the appliance already moves at — and it keeps the frame
    deterministic for a given row, which run_clock's "quote unchanged, skip the
    redraw" dedup depends on.
    """
    source = _photo_source()
    if source is None:
        return None
    candidates = _photo_candidates(source)
    if not candidates:
        _photo_warn_once(f"empty:{source}",
                         f"{source!r} holds no readable image; using the bundled plate")
        return None
    return candidates[_row_digest(quote_row) % len(candidates)]


def _photo_measure(image: Image.Image) -> tuple[float, float, float]:
    """Mean chroma, mean luminance and luminance spread, each 0..1.

    Measured on a thumbnail: the numbers only steer a global correction, and
    walking every pixel of a 12-megapixel phone photo to compute them would
    cost more than the render. See ``_PHOTO_TARGET_CHROMA`` for why chroma is
    ``max - min`` rather than HSV saturation.
    """
    small = image.resize((64, 40), Image.Resampling.BILINEAR)
    pixels = small.width * small.height
    bands = small.split()
    lightest = ImageChops.lighter(ImageChops.lighter(bands[0], bands[1]), bands[2])
    darkest = ImageChops.darker(ImageChops.darker(bands[0], bands[1]), bands[2])
    chroma_hist = ImageChops.subtract(lightest, darkest).histogram()
    chroma = sum(i * n for i, n in enumerate(chroma_hist)) / pixels / 255.0
    value_hist = lightest.histogram()
    mean = sum(i * n for i, n in enumerate(value_hist)) / pixels / 255.0
    variance = sum(n * ((i / 255.0) - mean) ** 2 for i, n in enumerate(value_hist)) / pixels
    return chroma, mean, math.sqrt(variance)


def _photo_condition(image: Image.Image) -> Image.Image:
    """Pull an arbitrary photograph into the band that dithers to grain.

    **Chroma first, levels last.** Blending toward grey lowers the lightest
    channel of a saturated pixel, so a chroma correction drags luminance
    down; levels applied first would be knocked off target. The reverse order
    is stable: levels is ``v * scale + offset`` with ``scale <= 1``, which
    leaves ``max - min`` unchanged or lower, so chroma never rises back above
    target. Both corrections are computed from the source and clamped to only
    reduce, so a photograph already in the band comes through untouched.
    """
    chroma, _, _ = _photo_measure(image)
    out = image
    if chroma > _PHOTO_TARGET_CHROMA:
        out = ImageEnhance.Color(out).enhance(_PHOTO_TARGET_CHROMA / chroma)
    _, mean, spread = _photo_measure(out)
    scale = 1.0
    if spread > _PHOTO_SPREAD_CEILING:
        scale = max(_PHOTO_MIN_CONTRAST, _PHOTO_SPREAD_CEILING / spread)
    if scale < 1.0 or abs(mean - _PHOTO_TARGET_MEAN) > _PHOTO_MEAN_TOLERANCE:
        offset = (_PHOTO_TARGET_MEAN - mean * scale) * 255.0
        out = out.point(lambda v, s=scale, o=offset: max(0, min(255, int(round(v * s + o)))))
    return out.filter(ImageFilter.GaussianBlur(_PHOTO_SOFT_FOCUS))


def _photo_cover_crop(image: Image.Image, width: int, height: int) -> Image.Image:
    """Scale to cover the panel and centre-crop the overflow.

    Cover rather than fit: letterboxing an operator's photo would paint bars
    the panel has no good colour for, and a picture frame shows a picture.
    """
    src_w, src_h = image.size
    scale = max(width / src_w, height / src_h)
    scaled = image.resize((max(width, int(round(src_w * scale))),
                           max(height, int(round(src_h * scale)))),
                          Image.Resampling.LANCZOS)
    left = (scaled.width - width) // 2
    top = (scaled.height - height) // 2
    return scaled.crop((left, top, left + width, top + height))


def _photo_open(path: Path, width: int, height: int) -> Image.Image | None:
    """Open, orient, crop and condition an operator's photograph.

    Handles EXIF rotation, palette / CMYK / alpha modes and a size bound; any
    failure returns ``None`` and the caller falls back to the bundled plate.

    **Draft first, then cap, then decode.** ``Image.open`` is lazy, so both
    checks run before any pixel is materialised. ``draft`` lets the JPEG
    decoder scale down during the DCT pass (a no-op for other formats), so a
    48 MP phone JPEG is under the cap once drafted. The cap then rejects what
    draft could not shrink: Pillow's own bomb guard only raises above ~179 MP,
    and a large PNG well under that can OOM the render child on a 512 MB Pi
    before it reaches the fallback.
    """
    try:
        with Image.open(path) as raw:
            # Ask for twice the target box so the LANCZOS cover-crop still has
            # resampling headroom; draft only ever overshoots upward.
            raw.draft("RGB", (width * 2, height * 2))
            pixels = raw.width * raw.height
            if pixels > _PHOTO_MAX_PIXELS:
                _photo_warn_once(
                    f"toobig:{path}",
                    f"{path} is {pixels / 1e6:.0f} MP after draft, over the "
                    f"{_PHOTO_MAX_PIXELS / 1e6:.0f} MP decode cap; using the bundled plate",
                )
                return None
            raw.load()
            oriented = ImageOps.exif_transpose(raw) or raw
            rgb = oriented.convert("RGB")
    except (OSError, ValueError, SyntaxError, Image.DecompressionBombError) as exc:
        _photo_warn_once(f"open:{path}", f"cannot read {path}: {exc!r}; using the bundled plate")
        return None
    return _photo_condition(_photo_cover_crop(rgb, width, height))


def photo_source_stamp(quote_row: dict) -> tuple | None:
    """A hashable stamp for the photograph this row would render, or ``None``.

    Public for the curator UI's ``/api/preview`` cache, whose key (theme,
    time, quote identity, corpus stamps) does not move when the operator swaps
    the file, and which answers before ``_photo_frame_for``'s mtime-aware
    cache is consulted. The stamp resolves the row's own photograph, so a
    directory whose membership changed is covered too.
    """
    path = _photo_for_row(quote_row)
    if path is None:
        return None
    try:
        stat = path.stat()
    except OSError:
        # Still distinguishes one missing path from another, and from a
        # readable one — which is all the cache key needs.
        return (str(path), None, None)
    return (str(path), stat.st_mtime_ns, stat.st_size)


def _photo_frame_for(quote_row: dict, width: int, height: int) -> tuple[Image.Image, tuple[int, int, int, int]]:
    """The dithered background and the card rectangle chosen for it.

    Returned together because placement is measured on the continuous-tone
    image, before dithering. Don't measure the dithered plate: a dither turns
    smooth regions into high-edge-energy stipple, inverting the score so the
    card lands on the part of the picture worth keeping.

    Falls back to the bundled ``autochrome`` garden when nothing is configured
    or the source cannot be read, so the theme always renders and, with the
    environment variable unset, is byte-deterministic (it has a golden
    fixture).
    """
    path = _photo_for_row(quote_row)
    key: tuple | None = None
    if path is not None:
        try:
            stat = path.stat()
            key = (str(path), stat.st_mtime_ns, stat.st_size, width, height)
        except OSError:
            key = None
        if key is not None:
            cached = _PHOTO_CACHE.get(key)
            if cached is not None:
                _PHOTO_CACHE.move_to_end(key)
                return cached
        conditioned = _photo_open(path, width, height)
        if conditioned is not None:
            result = (dither_image_to_palette(conditioned, SPECTRA6_PALETTE),
                      _photo_card_rect(conditioned, width, height))
            if key is not None:
                _PHOTO_CACHE[key] = result
                while len(_PHOTO_CACHE) > _PHOTO_CACHE_MAX:
                    _PHOTO_CACHE.popitem(last=False)
            return result
    return _photo_fallback_frame(width, height)


def _photo_fallback_frame(width: int, height: int) -> tuple[Image.Image, tuple[int, int, int, int]]:
    """The bundled ``autochrome`` garden, measured for card placement the same
    way an operator's photograph is - off the continuous-tone source, not the
    dithered plate."""
    plate = _load_dithered_plate(AUTOCHROME_PLATE, width, height, palette=_AUTOCHROME_PALETTE)
    try:
        with Image.open(AUTOCHROME_PLATE) as raw:
            source = raw.convert("RGB").resize((width, height), Image.Resampling.LANCZOS)
    except (OSError, ValueError):
        source = None
    if plate is None:
        plate = Image.new("RGB", (width, height), SPECTRA6["white"])
        _autochrome_paint_garden_fallback(plate)
    rect = _photo_card_rect(source if source is not None else plate, width, height)
    return plate, rect


def _photo_cost_map(image: Image.Image, cols: int = 20, rows: int = 12) -> list[list[float]]:
    """Per-cell cost of covering that part of the picture.

    Two terms, because either alone picks a bad spot:

    * **Detail** — mean edge energy. Flat sky, wall and shadow are cheap to
      cover; foliage, a horizon or a face is not.
    * **Salience** — distance of the cell's luminance from the frame's mean.
      A smooth bright subject (a sun, a lit face, a window) has little edge
      energy inside it, so detail alone would put the card on it.

    Both are computed on the continuous-tone image (see ``_photo_frame_for``).
    """
    grey = image.convert("L")
    detail = grey.filter(ImageFilter.FIND_EDGES).resize((cols, rows), Image.Resampling.BOX)
    coarse = grey.resize((cols, rows), Image.Resampling.BOX)
    dpx, cpx = detail.load(), coarse.load()
    cells = [[cpx[c, r] for c in range(cols)] for r in range(rows)]
    mean = sum(sum(row) for row in cells) / (cols * rows)
    return [
        [dpx[c, r] / 255.0 + _PHOTO_SALIENCE_WEIGHT * abs(cells[r][c] - mean) / 255.0
         for c in range(cols)]
        for r in range(rows)
    ]


def _photo_card_rect(image: Image.Image, width: int, height: int) -> tuple[int, int, int, int]:
    """Place the caption card over the quietest candidate region."""
    card_w = max(1, min(_PHOTO_CARD_W, width - 2 * _PHOTO_CARD_MARGIN))
    card_h = max(1, min(_PHOTO_CARD_H, height - 2 * _PHOTO_CARD_MARGIN))
    detail = _photo_cost_map(image)
    rows, cols = len(detail), len(detail[0])
    best, best_score = None, None
    for side, vertical in _PHOTO_CARD_ANCHORS:
        x0 = _PHOTO_CARD_MARGIN if side == 0 else width - _PHOTO_CARD_MARGIN - card_w
        y0 = int(round(_PHOTO_CARD_MARGIN + vertical * (height - 2 * _PHOTO_CARD_MARGIN - card_h)))
        x0 = max(0, min(width - card_w, x0))
        y0 = max(0, min(height - card_h, y0))
        c0, c1 = int(x0 / width * cols), max(int(x0 / width * cols) + 1, int((x0 + card_w) / width * cols))
        r0, r1 = int(y0 / height * rows), max(int(y0 / height * rows) + 1, int((y0 + card_h) / height * rows))
        cells = [detail[r][c] for r in range(r0, min(r1, rows)) for c in range(c0, min(c1, cols))]
        # Mean plus a share of the worst cell: across a 312x368 card the mean
        # dilutes a small face on an empty lawn to nothing, while the peak asks
        # whether this position clips anything important.
        score = (sum(cells) / len(cells) + _PHOTO_PEAK_WEIGHT * max(cells)) if cells else 0.0
        if best_score is None or score < best_score - 1e-9:
            best, best_score = (x0, y0), score
    x0, y0 = best if best is not None else (_PHOTO_CARD_MARGIN, _PHOTO_CARD_MARGIN)
    return (x0, y0, x0 + card_w, y0 + card_h)


def _photo_paint_card(image: Image.Image, draw: ImageDraw.ImageDraw,
                      rect: tuple[int, int, int, int], quote_row: dict) -> None:
    """The caption card: the shared cream mount, keylined heavier than
    ``daguerreotype``'s because an arbitrary photograph may be pale right up
    against the card's edge, where a controlled plate never is."""
    x0, y0, x1, y1 = rect
    black, red = SPECTRA6["black"], SPECTRA6["red"]
    paint_mount_card(image, draw, rect, ledge=3, outline_width=2)

    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    quote_font, quote_font_bold, wrapped, line_height, _ = fit_quote(
        draw, display_quote, quote_row.get("matched_text") or "",
        x1 - x0 - 40, y1 - y0 - 74, font_max=26, font_min=12,
        line_height_mult=1.34, theme="photo",
    )
    block_h = len(wrapped) * line_height
    draw_centred_styled_lines(
        draw, wrapped, x0=x0, x1=x1,
        top=y0 + max(24, ((y1 - y0) - 34 - block_h) // 2),
        line_height=line_height, regular=quote_font, bold=quote_font_bold,
        fill=black, accent=red,
    )
    draw_truncated_centred_byline(
        draw, quote_row, centre=(x0 + x1) // 2, baseline=y1 - 16,
        max_width=x1 - x0 - 30, fill=black,
        font=load_font(theme_font_candidates("photo", "quote_regular"), size=13),
    )


def render_photo_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """The operator's photograph with the quote on a card (see the section
    comment).

    Composed at 800x480 and NEAREST-downsampled otherwise (the ``metro``
    convention), not re-laid out per size: the card's minimum size exceeds a
    thumbnail canvas, and a preview should show what the panel will show.
    """
    del time_str  # a photograph carries no clock; the daguerreotype rule.
    plate, rect = _photo_frame_for(quote_row, 800, 480)
    image = plate.copy()
    draw = ImageDraw.Draw(image)
    _photo_paint_card(image, draw, rect, quote_row)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# ---------------------------------------------------------------------------
# escritoire — a handwritten letter on a writing desk, seen at an angle
# ---------------------------------------------------------------------------
# The quote is the last paragraph of a letter on a mahogany desk, seen from
# the writer's chair: the sheet is a foreshortened, slightly rolled
# trapezoid, with out-of-focus brass beyond it, a second page under it and a
# fountain pen across it. Full design notes: docs/themes.md (``escritoire``).
#
# **Only the near half of the page is legible, on purpose.** At the far edge
# a glyph is 60% of its near-edge size, which is noise at panel resolution, so
# the far band carries the letter's earlier lines as faint asemic script
# (``_codex_script``, seeded from the row) and the quote sits in the near band.
#
# **The page is laid out flat, then warped.** The quote is fitted on an
# upright 900x560 sheet at 2x (``fit_quote_balanced``) into three ``"L"``
# masks (prose, phrase, faint), each carried through one bicubic perspective
# transform, box-reduced and thresholded so every ink pixel lands solid. Don't
# warp a finished RGB frame: the resampled glyph edges become a grey fringe
# that the palette snap turns into a ragged stipple.
#
# **Inks.** Prose black, matched phrase blue (fountain-pen ink). The paper is
# white with a yellow stipple warming toward the near corner. The desk is
# black with a red stipple pooled under the lamp, 30% of it yellow (red alone
# reads aubergine). The brass is a blurred luminance field stippled on a
# black-red-yellow-white ramp; the pen's gold is R+Y 5/8:3/8.
#
# **Cost.** The scene is quote-independent and cached for in-process callers,
# keyed on the painters (the ``expanse`` convention) so the decoration fence's
# neutered painters rebuild it. The appliance renders cold, so the smooth
# fields are computed at reduced resolution and the per-pixel passes are
# confined to their bounding boxes.
#
# No clock: ``time_str`` is deleted at entry. Fixed geometry, composed at
# 800x480 and NEAREST-downsampled.

_ESCRITOIRE_SEED = 0x45534352          # ESCR
_ESCRITOIRE_SS = 2                     # supersample for the sheet masks
_ESCRITOIRE_SHEET = (900, 560)         # the upright sheet, in sheet units
# The sheet's corners on the canvas (TL, TR, BR, BL). The near corners run off
# the panel, as a sheet does when it is close enough to write on.
_ESCRITOIRE_QUAD = ((168, 158), (706, 128), (860, 512), (-70, 470))
_ESCRITOIRE_LAMP = (560, 150)          # the light pool's centre on the desk
_ESCRITOIRE_LEFT = 100                 # the writing's left margin, sheet units
_ESCRITOIRE_MEASURE = 600              # the quote's measure, sheet units
_ESCRITOIRE_FAINT_TOP = 62             # the first faint line's baseline
_ESCRITOIRE_FAINT_PITCH = 44
_ESCRITOIRE_BAND = (196, 520)          # the near band the quote is centred in
# (font_max, font_min) per layout, in sheet units. The hero sizes are large on
# purpose: a short quote set at a dense size leaves the near band half empty.
_ESCRITOIRE_SIZES = {"hero": (64, 38), "standard": (50, 30), "dense": (42, 26)}
# The size of last resort. The clock never picks a quote that needs it, but the
# curator previews raw rows of up to ~470 characters, which overflow the band
# at every layout floor; they get smaller rather than running off the page.
_ESCRITOIRE_FLOOR = 18
_ESCRITOIRE_SIG_MAX = 38               # the signature's largest size, sheet units
_ESCRITOIRE_TITLE_MAX = 26             # the title's under it
_ESCRITOIRE_LINE_MULT = 1.36
_ESCRITOIRE_FIELD_SCALE = 4            # the smooth fields' downsampling factor
# The pen, nib tip to cap end, and its half-width at the nib end.
_ESCRITOIRE_PEN = ((262.0, 212.0), (738.0, 102.0), 10.0)
# A second sheet under the letter, turned a few degrees further, so a wedge of
# it shows along the far edge and past the top-right corner: a page of the
# same letter, and the cheapest cue that the sheet lies on a real desk.
_ESCRITOIRE_UNDER_QUAD = ((182, 146), (726, 133), (842, 520), (-60, 482))
# The brass beyond the sheet, each a turned piece given as a lathe profile:
# its axis x and (y, half-width) knots down the silhouette, joined linearly.
# A knot pair a few pixels apart is a step in the turning, where a moulding
# line falls. Tops stay on the panel: pieces cut off by the top edge read as
# lit columns, not as things on a desk.
_ESCRITOIRE_BRASS = (
    # The inkwell: a ball finial on a domed lid, a squat body, a stepped foot.
    (560, ((30, 0), (31, 5), (38, 7), (44, 4), (47, 10), (52, 22), (60, 31), (66, 36), (70, 34),
           (74, 38), (132, 38), (136, 43), (146, 44), (150, 40))),
    # The pen cup: a rolled rim, a band at the waist, a flared foot.
    (672, ((40, 30), (46, 30), (48, 27), (94, 27), (96, 30), (102, 30), (104, 27), (136, 28),
           (140, 33), (150, 35), (154, 32))),
    # The sander: a pierced dome, a waisted neck, a bell foot on the desk
    # beyond the sheet's right edge, where its reflection shows.
    (756, ((54, 0), (56, 12), (62, 20), (70, 22), (74, 15), (92, 13), (110, 18), (140, 30),
           (154, 36), (162, 37), (166, 33))),
)
# Lamp glints on the brass, which the blur turns into soft bokeh: (x, y, r).
_ESCRITOIRE_GLINTS = ((546, 30, 4), (543, 58, 5), (545, 100, 5), (657, 44, 4), (659, 116, 4),
                      (746, 66, 4), (742, 150, 5))
# The two pens standing in the cup: where each leaves the rim, and where it
# leaves the panel.
_ESCRITOIRE_CUP_PENS = (((662, 42), (638, -4)), ((684, 42), (706, -4)))
# The pens lying further back on the left: nib tip to cap end, half-width.
_ESCRITOIRE_BACK_PENS = (((330, 120), (64, 150), 9), ((236, 64), (18, 92), 8))
_ESCRITOIRE_SCENE: dict = {}


def _escritoire_solve(a: list, b: list) -> list:
    """Solve a small dense linear system by Gaussian elimination."""
    n = len(a)
    m = [row[:] + [b[i]] for i, row in enumerate(a)]
    for c in range(n):
        p = max(range(c, n), key=lambda r: abs(m[r][c]))
        m[c], m[p] = m[p], m[c]
        for r in range(n):
            if r != c:
                f = m[r][c] / m[c][c]
                for k in range(c, n + 1):
                    m[r][k] -= f * m[c][k]
    return [m[i][n] / m[i][i] for i in range(n)]


@functools.lru_cache(maxsize=None)
def _escritoire_coeffs(scale: int = 1) -> tuple:
    """Pillow's PERSPECTIVE coefficients mapping the canvas onto the sheet
    (output to input, which is the direction Pillow samples in)."""
    sw, sh = _ESCRITOIRE_SHEET
    sheet = ((0, 0), (sw, 0), (sw, sh), (0, sh))
    a, b = [], []
    for (x, y), (u, v) in zip(_ESCRITOIRE_QUAD, sheet):
        x, y, u, v = x * scale, y * scale, u * scale, v * scale
        a.append([x, y, 1, 0, 0, 0, -u * x, -u * y])
        a.append([0, 0, 0, x, y, 1, -v * x, -v * y])
        b += [u, v]
    return tuple(_escritoire_solve(a, b))


def _escritoire_field(size, fn, step: int = _ESCRITOIRE_FIELD_SCALE) -> Image.Image:
    """A smooth ``"L"`` field from ``fn(x, y) -> 0..1``, sampled every
    ``_ESCRITOIRE_FIELD_SCALE`` pixels and scaled up bilinearly. The lamp pool
    and the paper's warmth have no detail finer than tens of pixels, and
    evaluating them per pixel was most of a cold render."""
    width, height = size
    cols, rows = width // step + 2, height // step + 2
    data = bytes(int(255 * min(1.0, max(0.0, fn(x * step, y * step))))
                 for y in range(rows) for x in range(cols))
    small = Image.frombytes("L", (cols, rows), data)
    return small.resize((cols * step, rows * step), Image.Resampling.BILINEAR).crop((0, 0, width, height))


def _escritoire_stipple(density: Image.Image) -> Image.Image:
    """``"L"`` density (0-255) to a 0/255 ordered-dither mask on ``BAYER_8x8``."""
    threshold = _ESCRITOIRE_SCENE.get(("tile", density.size))
    if threshold is None:
        threshold = _bayer_threshold_field(density.size)
        _ESCRITOIRE_SCENE[("tile", density.size)] = threshold
    return ImageChops.subtract(density, threshold).point(lambda v: 255 if v else 0)


def _escritoire_sheet_mask(size, quad=_ESCRITOIRE_QUAD) -> Image.Image:
    mask = Image.new("L", size, 0)
    ImageDraw.Draw(mask).polygon(quad, fill=255)
    return mask


def _escritoire_paper_mask(size) -> Image.Image:
    """Both sheets: everything the brass sits behind."""
    return ImageChops.lighter(_escritoire_sheet_mask(size), _escritoire_sheet_mask(size, _ESCRITOIRE_UNDER_QUAD))


def _escritoire_paint_desk(image: Image.Image) -> None:
    """Mahogany: black with a red stipple pooled under the lamp, a share of
    yellow inside the red, and a grain that wanders.

    Red over black alone reads as aubergine, so a fixed share of every lit run
    is yellow (the print-sepia direction). The share rides the same tile read
    as the red (``tile < d * share`` is a subset of ``tile < d``), so the hue
    holds down the pool's falloff. The grain drifts with x so it does not read
    as ruled lines; it is computed at half resolution, the pool at quarter."""
    width, height = image.size
    lx, ly = _ESCRITOIRE_LAMP
    pool = _escritoire_field(
        (width, height), lambda x, y: max(0.0, 1.0 - math.hypot(x - lx, (y - ly) * 1.6) / 520) ** 1.6)
    grain = _escritoire_field(
        (width, height),
        lambda x, y: (0.24 + 0.09 * (0.5 + 0.5 * math.sin(
            y * 0.55 + 1.8 * math.sin(y * 0.07) + 1.3 * math.sin(x * 0.011 + y * 0.031)))) / 0.33,
        step=2)
    density = ImageChops.multiply(pool, grain).point(lambda v: int(255 * 0.04 + v * 0.33))
    image.paste(SPECTRA6["black"], (0, 0, width, height))
    image.paste(SPECTRA6["red"], (0, 0), _escritoire_stipple(density))
    image.paste(SPECTRA6["yellow"], (0, 0), _escritoire_stipple(density.point(lambda v: v * 30 // 100)))


def _escritoire_paint_shadow(image: Image.Image) -> None:
    """The sheets' shadow, cast down and to the right onto the desk: a soft
    black stipple, painted before the brass so it falls on the desk only.

    The shift must not wrap (hence ``_shift_no_wrap``, not ``ImageChops.offset``):
    the sheet runs off the bottom and right of the panel."""
    paper = _escritoire_paper_mask(image.size)
    shadow = _shift_no_wrap(paper, 6, 9).filter(ImageFilter.GaussianBlur(7))
    image.paste(SPECTRA6["black"], (0, 0), _escritoire_stipple(ImageChops.subtract(shadow, paper)))


def _escritoire_lathe(lp, ap, cx: float, knots, *, gain: float = 1.0, mirror_at: float | None = None,
                      fade: float = 0.0) -> None:
    """Shade one turned brass piece into the ``lum`` / ``alpha`` pixel access
    objects: across each row a cylinder's falloff with a narrow glint left of
    the axis, darkened on the rows where the profile steps (the mouldings).
    With ``mirror_at`` it paints the piece's reflection instead, flipped about
    that y and fading out over ``fade`` pixels."""
    ys = [k[0] for k in knots]
    steps = {round(ys[i]) for i in range(1, len(ys) - 1) if ys[i + 1] - ys[i] <= 6 or ys[i] - ys[i - 1] <= 6}

    def half_width(y):
        for (y0, w0), (y1, w1) in zip(knots, knots[1:]):
            if y0 <= y <= y1:
                return w0 + (w1 - w0) * (y - y0) / max(1e-6, y1 - y0)
        return 0.0

    top, foot = ys[0], ys[-1]
    rows = range(int(top), int(foot) + 1)
    for y in rows:
        hw = half_width(y)
        if hw < 0.5:
            continue
        ring = 0.72 if any(abs(y - k) <= 1 for k in steps) else 1.0
        if mirror_at is None:
            out_y, a = y, 255
        else:
            out_y = int(2 * mirror_at - y)
            a = int(255 * 0.45 * max(0.0, 1 - (out_y - mirror_at) / fade))
            if a <= 0:
                continue
        if not 0 <= out_y < 480:          # the scene is always composed at 800x480
            continue
        for x in range(max(0, int(cx - hw)), min(800, int(cx + hw) + 1)):
            t = (x - cx) / hw
            if abs(t) > 1:
                continue
            body = math.sqrt(1 - t * t)
            glint = math.exp(-((t + 0.42) / 0.15) ** 2)
            v = int(255 * gain * ring * min(1.0, 0.1 + 0.42 * body + 0.5 * glint))
            if v > lp[x, out_y]:
                lp[x, out_y] = v
            if a > ap[x, out_y]:
                ap[x, out_y] = a


def _escritoire_paint_brass(image: Image.Image) -> None:
    """The out-of-focus things on the far side of the desk: three turned brass
    pieces with their tops on the panel, lamp glints that the blur turns into
    bokeh, reflections on the polished desk, and two pens lying further back.
    All of it is shaded as a luminance field and an alpha field, blurred
    together, then stippled on a black-red-yellow-white ramp."""
    width, height = image.size
    lum = Image.new("L", (width, height), 0)
    alpha = Image.new("L", (width, height), 0)
    lp, ap = lum.load(), alpha.load()
    for cx, knots in _ESCRITOIRE_BRASS:
        _escritoire_lathe(lp, ap, cx, knots)
        foot = knots[-1][0]
        _escritoire_lathe(lp, ap, cx, knots, gain=0.8, mirror_at=foot, fade=40)
    draw_l, draw_a = ImageDraw.Draw(lum), ImageDraw.Draw(alpha)
    for gx, gy, r in _ESCRITOIRE_GLINTS:
        draw_l.ellipse((gx - r, gy - r, gx + r, gy + r), fill=255)
    # The back pens. Dark barrels vanish on a dark desk, so each is drawn by
    # what the lamp catches: a gold nib and section, a gold cap band and
    # finial, and a bright line along the top of the barrel.
    for (nx, ny), (ex, ey), r in _ESCRITOIRE_BACK_PENS:
        length = math.hypot(ex - nx, ey - ny)
        ux, uy = (ex - nx) / length, (ey - ny) / length
        px_, py_ = -uy, ux

        def quad(t0, t1, w0, w1):
            return [(nx + ux * t0 + px_ * w0, ny + uy * t0 + py_ * w0),
                    (nx + ux * t1 + px_ * w1, ny + uy * t1 + py_ * w1),
                    (nx + ux * t1 - px_ * w1, ny + uy * t1 - py_ * w1),
                    (nx + ux * t0 - px_ * w0, ny + uy * t0 - py_ * w0)]

        draw_a.polygon(quad(0, length, 1, r), fill=255)
        draw_l.polygon(quad(30, length, r * 0.8, r), fill=8)
        draw_l.polygon(quad(0, 34, 1, r * 0.75), fill=150)                  # nib + section
        draw_l.polygon(quad(length * 0.62, length * 0.62 + 7, r, r), fill=150)  # cap band
        draw_l.polygon(quad(length - 6, length, r, r), fill=150)            # finial
        hl = quad(40, length * 0.92, r * 0.45, r * 0.5)
        draw_l.line([hl[0], hl[1]], fill=235, width=2)
    # Two pens standing in the cup, which is what makes it read as one: dark
    # shafts leaning out of the rim, each drawn by its highlight.
    for (bx, by), (tx, ty) in _ESCRITOIRE_CUP_PENS:
        draw_a.line([(bx, by), (tx, ty)], fill=255, width=7)
        draw_l.line([(bx, by), (tx, ty)], fill=8, width=7)
        draw_l.line([(bx - 2, by), (tx - 2, ty)], fill=225, width=1)
    lum = lum.filter(ImageFilter.GaussianBlur(3))
    alpha = alpha.filter(ImageFilter.GaussianBlur(4))
    # Ramp black < red < yellow < white, two adjacent inks mixed by the tile.
    ramp = (SPECTRA6["black"], SPECTRA6["red"], SPECTRA6["yellow"], SPECTRA6["white"])
    px, lp, ap = image.load(), lum.load(), alpha.load()
    paper = _escritoire_paper_mask((width, height)).load()
    bx0, by0, bx1, by1 = alpha.getbbox() or (0, 0, 0, 0)
    for y in range(by0, by1):
        row = BAYER_8x8[y % 8]
        for x in range(bx0, bx1):
            a = ap[x, y]
            if a < 8 or paper[x, y]:
                continue
            rank = row[x % 8]
            if rank >= a / 4:
                continue
            level = lp[x, y] / 255 * 3
            step = min(2, int(level))
            px[x, y] = ramp[step + 1] if rank < (level - step) * 64 else ramp[step]


def _escritoire_paint_sheet(image: Image.Image) -> None:
    """The paper: the page underneath, the letter's shadow falling on it, then
    the letter. Both are white with a yellow stipple warming toward the near,
    shadowed corner and thinning under the lamp; the page underneath carries
    more yellow, so the two separate without an outline."""
    sw, sh = _ESCRITOIRE_SHEET
    a, b, c, d, e, f, g, h = _escritoire_coeffs()

    def warm(x, y):
        den = g * x + h * y + 1
        if den <= 1e-6:
            return 0.0
        u, v = (a * x + b * y + c) / den, (d * x + e * y + f) / den
        return 0.05 + 0.22 * min(1.0, max(0.0, 0.55 * v / sh + 0.45 * (1 - u / sw))) ** 1.3

    warmth = _escritoire_field(image.size, warm)
    under = _escritoire_sheet_mask(image.size, _ESCRITOIRE_UNDER_QUAD)
    sheet = _escritoire_sheet_mask(image.size)
    image.paste(SPECTRA6["white"], (0, 0), under)
    image.paste(SPECTRA6["yellow"], (0, 0),
                ImageChops.multiply(_escritoire_stipple(warmth.point(lambda v: min(255, v + 46))), under))
    # The letter's own shadow, on the page under it.
    shadow = _shift_no_wrap(sheet, 4, 6).filter(ImageFilter.GaussianBlur(4))
    shadow = ImageChops.multiply(ImageChops.subtract(shadow, sheet), under)
    image.paste(SPECTRA6["black"], (0, 0), _escritoire_stipple(shadow.point(lambda v: v * 3 // 4)))
    image.paste(SPECTRA6["white"], (0, 0), sheet)
    image.paste(SPECTRA6["yellow"], (0, 0), ImageChops.multiply(_escritoire_stipple(warmth), sheet))


def _escritoire_scene() -> Image.Image:
    """The desk, its shadow, the brass and the empty sheet: identical for
    every quote. Cached keyed on the painters (see the section comment)."""
    key = (_escritoire_paint_desk, _escritoire_paint_shadow, _escritoire_paint_brass, _escritoire_paint_sheet)
    cached = _ESCRITOIRE_SCENE.get("frame")
    if cached is not None and cached[0] == key:
        return cached[1]
    scene = Image.new("RGB", (800, 480), SPECTRA6["black"])
    _escritoire_paint_desk(scene)
    _escritoire_paint_shadow(scene)
    _escritoire_paint_brass(scene)
    _escritoire_paint_sheet(scene)
    _ESCRITOIRE_SCENE["frame"] = (key, scene)
    return scene


def _escritoire_layout(quote_row: dict) -> dict:
    """Fit the quote and its signature into the near band of the upright
    sheet. Returns the fitted fonts, the wrapped lines, and the block's top and
    bottom in sheet units (``block``)."""
    ss = _ESCRITOIRE_SS
    probe = ImageDraw.Draw(Image.new("L", (1, 1)))
    text = normalize_dashes(strip_underscore_emphasis(quote_row.get("display_quote") or ""))
    match_text = quote_row.get("matched_text") or ""
    font_max, font_min = _ESCRITOIRE_SIZES[choose_layout(text)]
    band_top, band_bottom = _ESCRITOIRE_BAND
    author = quote_row.get("author") or ""
    title = quote_row.get("title") or fallback_title(quote_row) or ""
    # Room for the signature as it will actually be set: one line per field
    # present, at the capped sizes, plus the gap above it. An upper bound, so
    # the fitted block plus its signature cannot outgrow the band.
    reserve = (int(_ESCRITOIRE_SIG_MAX * 1.15) if author else 0) + (int(_ESCRITOIRE_TITLE_MAX * 1.2) if title else 0)
    if reserve:
        reserve += int(font_max * _ESCRITOIRE_LINE_MULT * 0.3)
    room = (band_bottom - band_top - reserve) * ss

    def fit(floor):
        return fit_quote_balanced(probe, text, match_text, _ESCRITOIRE_MEASURE * ss, room,
                                  font_max * ss, floor * ss, _ESCRITOIRE_LINE_MULT, theme="escritoire")

    reg, bold, wrapped, line_h, size, _ = fit(font_min)
    if len(wrapped) * line_h > room and font_min > _ESCRITOIRE_FLOOR:
        reg, bold, wrapped, line_h, size, _ = fit(_ESCRITOIRE_FLOOR)
    # The signature follows the hand's size but stops short of shouting on a
    # hero quote, and keeps the byline floors legible on a dense one.
    sig_size = min(max(int(size * 0.8), 18 * ss), _ESCRITOIRE_SIG_MAX * ss)
    title_size = min(max(int(size * 0.56), 16 * ss), _ESCRITOIRE_TITLE_MAX * ss)
    sig_h = (int(sig_size * 1.15) if author else 0) + (int(title_size * 1.2) if title else 0)
    gap = int(line_h * 0.3) if sig_h else 0
    total = len(wrapped) * line_h + gap + sig_h
    top = max(band_top * ss, (band_top * ss + band_bottom * ss - total) // 2)
    if top + total > band_bottom * ss:
        # Even the last-resort size overflowed: lift the block into the faint
        # band, which only ever holds filler, rather than off the near edge.
        top = max(_ESCRITOIRE_FAINT_TOP * ss, band_bottom * ss - total)
    return {"regular": reg, "bold": bold, "lines": wrapped, "line_h": line_h, "size": size,
            "author": author, "title": title, "sig_size": sig_size, "title_size": title_size,
            "gap": gap, "top": top, "block": (top / ss, (top + total) / ss)}


def _escritoire_masks(quote_row: dict, layout: dict) -> tuple[Image.Image, Image.Image, Image.Image]:
    """Write the letter onto the upright sheet as (prose, phrase, faint) masks
    at the supersampled resolution."""
    ss = _ESCRITOIRE_SS
    size = (_ESCRITOIRE_SHEET[0] * ss, _ESCRITOIRE_SHEET[1] * ss)
    prose, phrase, faint = (Image.new("L", size, 0) for _ in range(3))
    dp, dph, df = ImageDraw.Draw(prose), ImageDraw.Draw(phrase), ImageDraw.Draw(faint)
    left = _ESCRITOIRE_LEFT * ss
    right = (_ESCRITOIRE_SHEET[0] - 70) * ss

    # The earlier lines of the letter, down to just above the quote.
    rng = random.Random(_ESCRITOIRE_SEED ^ _row_digest(quote_row))
    base = _ESCRITOIRE_FAINT_TOP * ss
    last = layout["top"] - int(layout["line_h"] * 0.55)
    while base + _ESCRITOIRE_FAINT_PITCH * ss <= last:
        x = left + rng.uniform(0, 18) * ss
        _codex_script(df, x, base, right, xh=12 * ss, rng=rng, fill=255, width=ss)
        base += _ESCRITOIRE_FAINT_PITCH * ss
    if base <= last:
        # The paragraph before the quote ends part-way across.
        _codex_script(df, left + rng.uniform(0, 18) * ss, base, right - rng.uniform(140, 320) * ss,
                      xh=12 * ss, rng=rng, fill=255, width=ss)

    y = layout["top"]
    ascent = max(_font_ascent(layout["regular"]), _font_ascent(layout["bold"]))
    for line in layout["lines"]:
        x = left
        for chunk, is_bold in _trim_line(line):
            font = layout["bold"] if is_bold else layout["regular"]
            offset = ascent - _font_ascent(font)
            (dph if is_bold else dp).text((x, y + offset), chunk, font=font, fill=255)
            x += dp.textlength(chunk, font=font)
        y += layout["line_h"]
    y += layout["gap"]
    sig_right = left + _ESCRITOIRE_MEASURE * ss
    if layout["author"]:
        font = load_font(theme_font_candidates("escritoire", "quote_bold"), size=layout["sig_size"])
        author = _metro_ellipsize(dp, layout["author"], font, _ESCRITOIRE_MEASURE * ss)
        dp.text((sig_right - dp.textlength(author, font=font), y), author, font=font, fill=255)
        y += int(layout["sig_size"] * 1.15)
    if layout["title"]:
        font = load_font(theme_font_candidates("escritoire", "quote_regular"), size=layout["title_size"])
        title = _metro_ellipsize(dp, layout["title"], font, _ESCRITOIRE_MEASURE * ss)
        dp.text((sig_right - dp.textlength(title, font=font), y), title, font=font, fill=255)
    return prose, phrase, faint


def _escritoire_warp(mask: Image.Image, threshold: int) -> Image.Image:
    """Carry a supersampled sheet mask onto the canvas: bicubic perspective at
    twice the panel size, a 2:1 box reduce, then a hard threshold so the ink
    lands solid instead of as a grey fringe."""
    ss = _ESCRITOIRE_SS
    big = mask.transform((800 * ss, 480 * ss), Image.Transform.PERSPECTIVE, _escritoire_coeffs(ss),
                         resample=Image.Resampling.BICUBIC)
    return big.reduce(ss).point(lambda v: 255 if v >= threshold else 0)


def _escritoire_paint_letter(image: Image.Image, quote_row: dict) -> None:
    """The letter: faint earlier lines stippled in black, the quote solid
    black, the matched phrase solid blue, all clipped to the paper."""
    layout = _escritoire_layout(quote_row)
    prose, phrase, faint = _escritoire_masks(quote_row, layout)
    paper = _escritoire_sheet_mask(image.size)
    faint = ImageChops.multiply(_escritoire_warp(faint, 110),
                                _escritoire_stipple(Image.new("L", image.size, 104)))
    image.paste(SPECTRA6["black"], (0, 0), ImageChops.multiply(faint, paper))
    image.paste(SPECTRA6["black"], (0, 0), ImageChops.multiply(_escritoire_warp(prose, 120), paper))
    image.paste(SPECTRA6["blue"], (0, 0), ImageChops.multiply(_escritoire_warp(phrase, 120), paper))


def _escritoire_pen_axis() -> tuple:
    (ax, ay), (bx, by), radius = _ESCRITOIRE_PEN
    length = math.hypot(bx - ax, by - ay)
    return ax, ay, (bx - ax) / length, (by - ay) / length, length, radius


def _escritoire_paint_pen(image: Image.Image) -> None:
    """The fountain pen across the far band, nib toward the quote: black
    lacquer, a gold section band, cap ring, clip and finial, a gold nib with its
    slit and breather hole, a dotted highlight along the barrel, a shadow on
    the paper. It tapers a little toward the cap so it recedes with the page."""
    ax, ay, ux, uy, length, r = _escritoire_pen_axis()
    nx, ny = -uy, ux
    black, gold = SPECTRA6["black"], SPECTRA6["green"]     # green is a sentinel for gold

    def taper(t):
        return 1.0 - 0.15 * t / length

    def section(draw, t0, t1, rad, fill):
        draw.polygon([(ax + ux * t + nx * rad * taper(t) * s, ay + uy * t + ny * rad * taper(t) * s)
                      for t, s in ((t0, 1), (t1, 1), (t1, -1), (t0, -1))], fill=fill)

    shadow = Image.new("L", image.size, 0)
    section(ImageDraw.Draw(shadow), 0, length, r + 1, 255)
    shadow = _shift_no_wrap(shadow, 5, 10).filter(ImageFilter.GaussianBlur(5))
    shadow = Image.eval(shadow, lambda v: v * 44 // 64)
    image.paste(black, (0, 0), _escritoire_stipple(shadow))

    draw = ImageDraw.Draw(image)
    draw.polygon([(ax, ay), (ax + ux * 46 + nx * 7, ay + uy * 46 + ny * 7),
                  (ax + ux * 46 - nx * 7, ay + uy * 46 - ny * 7)], fill=gold)
    section(draw, 44, 120, r * 0.8, black)
    section(draw, 120, 134, r * 0.95, gold)
    section(draw, 134, length - 72, r, black)
    section(draw, length - 72, length - 64, r * 1.1, gold)
    section(draw, length - 64, length - 4, r * 1.1, black)
    for t, rad in ((44, r * 0.8), (length - 4, r * 1.1)):
        rr, cx, cy = rad * taper(t), ax + ux * t, ay + uy * t
        draw.ellipse((cx - rr, cy - rr, cx + rr, cy + rr), fill=black)
    cx, cy = ax + ux * (length - 2), ay + uy * (length - 2)
    draw.ellipse((cx - 4, cy - 4, cx + 4, cy + 4), fill=gold)
    clip = -(r - 1)
    draw.line([(ax + ux * (length - 60) + nx * clip, ay + uy * (length - 60) + ny * clip),
               (ax + ux * (length - 12) + nx * clip, ay + uy * (length - 12) + ny * clip)], fill=gold, width=3)
    draw.line([(ax + ux * 4, ay + uy * 4), (ax + ux * 34, ay + uy * 34)], fill=black, width=1)
    cx, cy = ax + ux * 34, ay + uy * 34
    draw.ellipse((cx - 2, cy - 2, cx + 2, cy + 2), fill=black)
    px = image.load()
    width, height = image.size
    for t in range(50, int(length) - 70, 3):
        off = -(r * taper(t) - 4)
        hx, hy = int(ax + ux * t + nx * off), int(ay + uy * t + ny * off)
        if 0 <= hx < width and 0 <= hy < height:
            px[hx, hy] = SPECTRA6["white"]
    # Gold: 5/8 red, 3/8 yellow, on the ordered tile, over the pen's own box.
    reach = int(r * 1.1) + 6
    x0, x1 = max(0, int(min(ax, ax + ux * length)) - reach), min(width, int(max(ax, ax + ux * length)) + reach + 1)
    y0, y1 = max(0, int(min(ay, ay + uy * length)) - reach), min(height, int(max(ay, ay + uy * length)) + reach + 1)
    for y in range(y0, y1):
        row = BAYER_8x8[y % 8]
        for x in range(x0, x1):
            if px[x, y] == gold:
                px[x, y] = SPECTRA6["yellow"] if row[x % 8] < 24 else SPECTRA6["red"]


def render_escritoire_frame(time_str: str, quote_row: dict, width: int, height: int) -> Image.Image:
    """A handwritten letter on a writing desk, seen at an angle (see the
    section comment above).

    ``time_str`` is unused by design: the matched phrase carries the time.
    """
    del time_str
    image = _escritoire_scene().copy()
    _escritoire_paint_letter(image, quote_row)
    _escritoire_paint_pen(image)
    image = snap_image_to_palette(image, SPECTRA6_PALETTE)
    if (width, height) != (800, 480):
        image = image.resize((width, height), Image.Resampling.NEAREST)
    return image


# Themes that compose their whole frame instead of painting a border round
# the shared quote layout. ``render`` dispatches through this table; it sits
# here because every frame function above must exist before it is built.
_FRAME_RENDERERS = {
    "diags": render_diags_frame,
    "astrarium": render_astrarium_frame,
    "marquee": render_marquee_frame,
    "tarot": render_tarot_frame,
    "vinyl": render_vinyl_frame,
    "vitrail": render_vitrail_frame,
    "questline": render_questline_frame,
    "chrono": render_chrono_frame,
    "outrun": render_outrun_frame,
    "sampler": render_sampler_frame,
    "lieder": render_lieder_frame,
    "izakaya": render_izakaya_frame,
    "abyssal": render_abyssal_frame,
    "pride": render_pride_frame,
    "pulp": render_pulp_frame,
    "vhs": render_vhs_frame,
    "cardcatalog": render_cardcatalog_frame,
    "metro": render_metro_frame,
    "bakelite": render_bakelite_frame,
    "intaglio": render_intaglio_frame,
    "nocturne": render_nocturne_frame,
    "plaque": render_plaque_frame,
    "daguerreotype": render_daguerreotype_frame,
    "autochrome": render_autochrome_frame,
    "photo": render_photo_frame,
    "control": render_control_frame,
    "observation": render_observation_frame,
    "trisolaris": render_trisolaris_frame,
    "biomech": render_biomech_frame,
    "codex": render_codex_frame,
    "culture": render_culture_frame,
    "orbital": render_orbital_frame,
    "furies": render_furies_frame,
    "bosch": render_bosch_frame,
    "semiotic": render_semiotic_frame,
    "atropos": render_atropos_frame,
    "saros": render_saros_frame,
    "expedition": render_expedition_frame,
    "witcher": render_witcher_frame,
    "hades": render_hades_frame,
    "expanse": render_expanse_frame,
    "beksinski": render_beksinski_frame,
    "goya": render_goya_frame,
    "hal": render_hal_frame,
    "lumon": render_lumon_frame,
    "dsky": render_dsky_frame,
    "oblivion": render_oblivion_frame,
    "yorha": render_yorha_frame,
    "hitchhiker": render_hitchhiker_frame,
    "escritoire": render_escritoire_frame,
}


def render(time_str: str, quote_row: dict, width: int, height: int, mode: str = "debug", theme: str = "default") -> Image.Image:
    # Swap characters the theme's text faces cannot draw for ASCII stand-ins
    # before any layout or frame dispatch, so custom frames get it too.
    quote_row = apply_theme_glyph_fallbacks(quote_row, theme)
    if mode == "card":
        return render_source_card(quote_row, width, height, theme=theme)
    frame_renderer = _FRAME_RENDERERS.get(theme)
    if frame_renderer is not None:
        return frame_renderer(time_str, quote_row, width, height)
    colors = THEMES[theme]
    image = Image.new("RGB", (width, height), color=colors["page_bg"])
    _paint_theme_border(image, theme, colors)
    draw = ImageDraw.Draw(image)

    display_quote = normalize_dashes(strip_underscore_emphasis(quote_row["display_quote"]))
    layout_name = choose_layout(display_quote)
    layout = LAYOUTS[layout_name]

    debug_font = load_font(META_FONT_CANDIDATES, size=15)
    debug_label_font = load_font(META_FONT_BOLD_CANDIDATES, size=15)
    quote_font, quote_font_bold, wrapped_quote, line_height, chosen_size, wrap_width = fit_quote_balanced(
        draw,
        display_quote,
        quote_row.get("matched_text") or "",
        layout["max_width"],
        layout["quote_height"],
        layout["font_max"],
        layout["font_min"],
        layout["line_height_mult"],
        theme=theme,
    )
    bold_stroke = _bold_stroke_for_theme(theme)
    quote_block_height = len(wrapped_quote) * line_height
    # Floors of 18 / 16 px: the byline is read from across a room. Above the
    # floor it still scales with the body.
    author_size = max(18, int(chosen_size * 0.52))
    source_size = max(16, int(chosen_size * 0.47))
    attribution_font = load_font(theme_font_candidates(theme, "quote_regular"), size=author_size)
    attribution_title_font = load_font(theme_font_candidates(theme, "quote_regular"), size=source_size)

    author_text = quote_row.get("author") or None
    title_text = quote_row.get("title") or fallback_title(quote_row)
    author_lines = wrap_text(draw, author_text, attribution_font, width - 160)[:1] if author_text else []
    title_lines = wrap_text(draw, title_text, attribution_title_font, width - 200)[:2] if title_text else []

    attrib_height = 0
    if author_lines:
        attrib_height += author_size
    if title_lines:
        attrib_height += layout["author_gap"] + len(title_lines) * source_size
        if len(title_lines) > 1:
            attrib_height += (len(title_lines) - 1) * layout["title_gap"]

    total_h = quote_block_height + (layout["author_gap"] if (author_lines or title_lines) else 0) + attrib_height
    block_top = max(72, (height - total_h) // 2)
    block_bottom = block_top + total_h
    quote_top = block_top

    line_metrics = [
        (
            _line_ink_width(draw, line, quote_font, quote_font_bold, bold_stroke),
            sum(1 for chunk, _ in _trim_line(line) if chunk == " "),
        )
        for line in wrapped_quote
    ]
    justify = justify_flags(theme, line_metrics, wrap_width, chosen_size)

    quote_line_boxes = []
    quote_left_edge = width
    quote_right_edge = 0
    y_probe = quote_top
    for line_index, line in enumerate(wrapped_quote):
        start = 0
        while start < len(line) and line[start][0].strip() == "":
            start += 1
        end = len(line)
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        drawable = line[start:end]

        current_width = 0
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            # Match ``wrap_styled_text``: stroke only widens non-space
            # tokens; inter-word spaces stay at their natural advance so
            # the rendered line width here matches the wrap decision.
            stroke = bold_stroke if (is_bold and chunk.strip()) else 0
            bbox = draw.textbbox((0, 0), chunk, font=font, stroke_width=stroke)
            current_width += bbox[2] - bbox[0]

        space_slots = sum(1 for chunk, _ in drawable if chunk == " ")
        slack = wrap_width - current_width
        distribute = []
        if justify[line_index] and space_slots:
            base = slack // space_slots
            remainder = slack - base * space_slots
            distribute = [base + (1 if i < remainder else 0) for i in range(space_slots)]

        line_x = (width - layout["max_width"]) // 2
        line_left = None
        line_right = line_x
        space_idx = 0
        for chunk, is_bold in drawable:
            if line_left is None and chunk.strip():
                line_left = line_x
            font = quote_font_bold if is_bold else quote_font
            stroke = bold_stroke if (is_bold and chunk.strip()) else 0
            bbox = draw.textbbox((0, 0), chunk, font=font, stroke_width=stroke)
            line_x += bbox[2] - bbox[0]
            if chunk.strip():
                line_right = line_x
            if distribute and chunk == " ":
                line_x += distribute[space_idx]
                space_idx += 1
        if line_left is not None:
            quote_line_boxes.append((line_left, y_probe, line_right, y_probe + line_height))
            quote_left_edge = min(quote_left_edge, line_left)
            quote_right_edge = max(quote_right_edge, line_right)
        y_probe += line_height

    # The knockout rect must cover the attribution as well as the quote
    # lines, or a long title runs out of the cleared panel into the border
    # decoration (#328).
    attribution_left = (width - layout["max_width"]) // 2
    for line, font in [(author_line, attribution_font) for author_line in author_lines] + [
        (title_line, attribution_title_font) for title_line in title_lines
    ]:
        bbox = draw.textbbox((0, 0), line, font=font)
        quote_left_edge = min(quote_left_edge, attribution_left)
        quote_right_edge = max(quote_right_edge, attribution_left + bbox[2] - bbox[0])

    clear_rect = None
    # Per-theme clear-rect padding (x, top, bottom), wide enough that each
    # theme's framing decoration clears the body text (kanagawa's seigaiha
    # crescents, cartograph's doubled rule and corner ticks). blueprint's grid
    # repaints inside the rect, so its 2/2/2 only guards a 1 px stroke.
    _CLEAR_RECT_PADS = {
        "blueprint": (2, 2, 2),
        "kanagawa": (14, 6, 6),
        "cartograph": (22, 12, 12),
        # circuit knocks the body region back to clean forest soldermask and
        # frames it with a 1 px white silkscreen outline + a pin-1 corner dot;
        # the 16/10/10 pad keeps that outline (and the dot just outside the
        # top-left corner) clear of the first / last text lines.
        "circuit": (16, 10, 10),
        # synoptic boxes the quote as a chart legend: a 2 px black frame with
        # blue rules inset 8 px, so the pad has to clear both.
        "synoptic": (20, 14, 14),
        # anna_atkins deliberately omits a body-text knockout — the white /
        # sky-blue text is rendered directly on the cyanotype plate with a
        # subtle per-glyph black halo (see ``_draw_text_body``) instead of a
        # panel, so the full photogram stays visible behind the quote.
        # letter knocks the writing area back to clean cream (no foxing) so the
        # thin Dancing Script body doesn't blur against the plate's foxing
        # speckle; a generous 26/18/18 pad leaves clean margin around the text
        # even after the 16 px feathered edge, with no drawn frame.
        "letter": (26, 18, 18),
        # betweenus knocks the body out to a rounded card (radius 18) floated
        # on a soft shadow; the pad is the app's card padding scaled up, and
        # wide enough that the corner arcs never cut into a first / last line.
        "betweenus": (28, 18, 24),
        "betweenus_dark": (28, 18, 24),
        # risograph knocks the body rect back to paper and frames it with a
        # misregistered double rule (2 px red + 2 px blue offset by 5/3);
        # 20/14/14 keeps both rules outside the text's own bounds.
        "risograph": (20, 14, 14),
    }
    if theme in _CLEAR_RECT_PADS and quote_line_boxes:
        clear_pad_x, clear_pad_top, clear_pad_bottom = _CLEAR_RECT_PADS[theme]
        clear_top = max(0, quote_line_boxes[0][1] - clear_pad_top)
        clear_bottom = min(height - 1, block_bottom + clear_pad_bottom)
        clear_rect = (
            max(0, quote_left_edge - clear_pad_x),
            clear_top,
            min(width - 1, quote_right_edge + clear_pad_x),
            clear_bottom,
        )
        # Drop a degenerate rect (x1 < x0 or y1 < y0): on a small preview
        # canvas the layout can land partly off-screen and invert the box,
        # which would raise in the knockout / border painters. None means "no
        # body-region knockout", which the branches below handle.
        if clear_rect[2] < clear_rect[0] or clear_rect[3] < clear_rect[1]:
            clear_rect = None

    if theme == "blueprint":
        _paint_theme_border(image, theme, colors)
        if clear_rect is not None:
            clear_draw = ImageDraw.Draw(image)
            clear_draw.rectangle(clear_rect, fill=colors["page_bg"])
            draw_blueprint_border(image, colors, clear_rect=clear_rect)
    elif theme == "kanagawa":
        # One call with ``clear_rect`` threaded through: the painter resets
        # the body rect to page_bg at the end, with no grid to re-add inside
        # it (unlike blueprint).
        draw_kanagawa_border(image, colors, clear_rect=clear_rect)
    elif theme == "cartograph":
        # Same single-call dispatch as kanagawa — cartograph paints all
        # eight map layers in one pass, knocking out the body-text rect
        # to a clean cream-washed rounded cartouche at the end.
        draw_cartograph_border(image, colors, clear_rect=clear_rect)
    elif theme == "circuit":
        # Same single-call dispatch as kanagawa / cartograph — the PCB
        # painter routes copper / pads / silkscreen across the board, then
        # knocks the body-text rect back to clean forest soldermask and
        # frames it with a white silkscreen component outline.
        draw_circuit_border(image, colors, clear_rect=clear_rect)
    elif theme == "synoptic":
        # Same single-call dispatch as kanagawa / cartograph / circuit — the
        # analysis paints graticule, isobars, fronts and station plots in one
        # pass, then wipes the body-text rect and boxes it as a chart legend.
        draw_synoptic_border(image, colors, clear_rect=clear_rect, time_str=time_str)
    elif theme == "risograph":
        # Same single-call dispatch — the print-test shapes paint across the
        # sheet, then the body rect is knocked back to paper and framed as a
        # misregistered pasted-up label.
        draw_risograph_border(image, colors, clear_rect=clear_rect)
    elif theme == "letter":
        # Same single-call dispatch — the letter painter pastes the dithered
        # aged-paper plate, knocks the writing area back to clean cream so the
        # thin script reads without foxing speckle, then paints creases + the
        # wax seal on top.
        draw_letter_border(image, colors, clear_rect=clear_rect)
    elif theme in _BETWEENUS_THEMES:
        # Same single-call dispatch — the painter lays the paper, floats the
        # quote card over it, and needs ``time_str`` for the day-progress bar
        # and the daypart pill (the registry contract carries no clock).
        draw_betweenus_border(image, colors, clear_rect=clear_rect, time_str=time_str)
    else:
        # anna_atkins falls through here too: it paints the dithered photogram +
        # ferns + labels via _paint_theme_border with no body-rect knockout, and
        # the quote text is drawn directly over the plate with a per-glyph halo.
        _paint_theme_border(image, theme, colors)

    draw = ImageDraw.Draw(image)
    show_debug = mode == "debug"

    mark_size = min(layout["mark_max"], max(layout["mark_min"], int(chosen_size * layout["mark_scale"])))
    mark_font = load_font(theme_font_candidates(theme, "ornament"), size=mark_size)

    # The mark hangs at a fixed x with its lower two thirds level with the
    # first line, so on the standard and dense measures it runs under the
    # first word. Deliberate (a pull-quote mark behind the text): don't shrink
    # it to clear the gutter — small marks lose the gesture.
    open_bb = draw.textbbox((0, 0), "“", font=mark_font)
    open_h = open_bb[3] - open_bb[1]
    open_x = SIDE_MARGIN + 18
    open_y = quote_top - open_h // 3
    _paint_ornament_mark(
        image,
        (open_x - open_bb[0], open_y - open_bb[1]),
        "“",
        font=mark_font,
        theme=theme,
        colors=colors,
        pattern_offset=(0, 0),
    )

    y = quote_top
    for line_index, line in enumerate(wrapped_quote):
        start = 0
        while start < len(line) and line[start][0].strip() == "":
            start += 1
        end = len(line)
        while end > start and line[end - 1][0].strip() == "":
            end -= 1
        drawable = line[start:end]

        current_width = 0
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            # See the layout pass above: spaces stay at natural advance.
            stroke = bold_stroke if (is_bold and chunk.strip()) else 0
            bbox = draw.textbbox((0, 0), chunk, font=font, stroke_width=stroke)
            current_width += bbox[2] - bbox[0]

        # Themes in ``_THEMES_RIGID_MATCH_SPACING`` exclude the
        # bold-internal inter-word gaps from slack distribution so the
        # matched phrase keeps its face's natural rhythm on a justified
        # line. Default for every other theme: all inter-word spaces
        # are equally elastic.
        space_is_bold = [is_bold for chunk, is_bold in drawable if chunk == " "]
        rigid_match = theme in _THEMES_RIGID_MATCH_SPACING
        slack = wrap_width - current_width

        distribute: list[int] = []
        # Full justification only where it will not open rivers -- see
        # ``justify_flags`` for the block-level decision.
        if justify[line_index] and space_is_bold:
            distribute = _justify_distribution(space_is_bold, slack, rigid_match)

        x = (width - layout["max_width"]) // 2
        space_idx = 0
        # PIL's default anchor "la" puts ``y`` at the top of each font's
        # ascent band, not on a shared baseline. When the body and bold faces
        # come from different families (gothic: EB Garamond + UnifrakturMaguntia)
        # the phrase would float, so each chunk is shifted by
        # ``body_ascent - chunk_ascent``.
        body_ascent = _font_ascent(quote_font)
        for chunk, is_bold in drawable:
            font = quote_font_bold if is_bold else quote_font
            fill = colors["accent"] if is_bold else colors["text"]
            chunk_y = y + (body_ascent - _font_ascent(font))
            # See the layout pass above: spaces stay at natural advance.
            stroke = bold_stroke if (is_bold and chunk.strip()) else 0
            _draw_text_body(image, draw, (x, chunk_y), chunk, font=font, fill=fill, theme=theme)
            bbox = draw.textbbox((0, 0), chunk, font=font, stroke_width=stroke)
            x += bbox[2] - bbox[0]
            if distribute and chunk == " ":
                x += distribute[space_idx]
                space_idx += 1
        y += line_height

    close_bb = draw.textbbox((0, 0), "”", font=mark_font)
    close_w = close_bb[2] - close_bb[0]
    close_h = close_bb[3] - close_bb[1]
    close_x = width - SIDE_MARGIN - 18 - close_w
    close_y = block_bottom - close_h * 2 // 3
    _paint_ornament_mark(
        image,
        (close_x - close_bb[0], close_y - close_bb[1]),
        "”",
        font=mark_font,
        theme=theme,
        colors=colors,
        pattern_offset=(1, 0),
    )

    y = quote_top + quote_block_height + layout["author_gap"]
    if author_lines:
        author_text_line = author_lines[0]
        author_x = (width - layout["max_width"]) // 2
        _draw_text_body(image, draw, (author_x, y), author_text_line, font=attribution_font, fill=colors["text"], theme=theme)
        y += author_size + layout["title_gap"]

    for line in title_lines:
        title_x = (width - layout["max_width"]) // 2
        _draw_text_body(image, draw, (title_x, y), line, font=attribution_title_font, fill=colors["source"], theme=theme)
        y += source_size + layout["title_gap"]

    if show_debug:
        debug_label = "DEBUG MODE"
        label_bbox = draw.textbbox((0, 0), debug_label, font=debug_label_font)
        label_w = label_bbox[2] - label_bbox[0]
        # Themes that paint a decorative top-right corner element push the
        # debug label inward past the graphic so it isn't clipped. Keep in
        # sync with the border helpers (``draw_bauhaus_border`` /
        # ``draw_blueprint_border``) — inset is measured past the outer edge
        # of the corner graphic with a small breathing gap.
        label_right_inset = _DEBUG_LABEL_RIGHT_INSET.get(theme, SIDE_MARGIN)
        label_x = width - label_right_inset - label_w
        label_y = 14

        draw_text(draw, (label_x, label_y), debug_label, font=debug_label_font, fill=colors["accent"])

        bucket_value = quote_row.get("bucket") or ""
        resolved = quote_row.get("resolved_bucket") or bucket_value
        if quote_row.get("used_fallback") and resolved and bucket_value and resolved != bucket_value:
            bucket_piece = f"{bucket_value} → {resolved}"
        else:
            bucket_piece = resolved or bucket_value

        debug_parts = [time_str]
        if bucket_piece:
            debug_parts.append(bucket_piece)
        debug_parts.append(f"layout {layout_name}")
        if quote_row.get("quality_score") is not None:
            debug_parts.append(f"quality {quote_row['quality_score']}")
        quote_id = debug_quote_id(quote_row)
        if quote_id:
            debug_parts.append(f"id {quote_id}")
        debug_strip = " · ".join(debug_parts)

        strip_bbox = draw.textbbox((0, 0), debug_strip, font=debug_font)
        strip_w = strip_bbox[2] - strip_bbox[0]
        strip_h = strip_bbox[3] - strip_bbox[1]
        strip_y = height - 14 - strip_h
        strip_x = (width - strip_w) // 2

        rule_y = strip_y - 8
        rule_left = max(SIDE_MARGIN, (width - strip_w) // 2 - 24)
        rule_right = min(width - SIDE_MARGIN, (width + strip_w) // 2 + 24)
        for x in range(rule_left, rule_right, 5):
            draw.point((x, rule_y), fill=colors["faint"])

        _draw_text_body(image, draw, (strip_x, strip_y), debug_strip, font=debug_font, fill=colors["faint"], theme=theme)

    return snap_image_to_palette(image, SPECTRA6_PALETTE)


def main() -> int:
    args = parse_args()
    if args.photo_path:
        os.environ[PHOTO_PATH_ENV] = args.photo_path
    # Output is a runtime artifact: resolve relative paths against CWD, not
    # ``BASE_DIR``, which lives inside the installed package.
    output_path = Path(args.output) if args.output else Path("output/current.png")
    output_path.parent.mkdir(parents=True, exist_ok=True)
    if args.mode == "goodnight":
        # --message is the opt-in override, not the default: a bare headline
        # cannot carry the attribution stack or the accent-coloured phrase the
        # sleep quote wants, so the unflagged path goes through the full
        # literary layout instead. ``args.time`` is optional in this mode, and
        # render_sleep_frame falls back to the wall clock when it is absent.
        if args.message is not None:
            image = render_static_message(args.message, args.width, args.height, theme=args.theme)
        else:
            image = render_sleep_frame(args.time, args.width, args.height, theme=args.theme)
    else:
        quote_row = pick_quote(
            args.time,
            history_path=args.history_path,
            history_days=args.history_days,
            database_path=args.database,
            input_path=args.input,
            overrides_path=args.overrides,
            pin_key=parse_pin_quote(args.pin_quote, args.pin_matched_text),
        )
        image = render(args.time, quote_row, args.width, args.height, mode=args.mode, theme=args.theme)
    try:
        # Encode to an in-memory buffer first so a mid-save exception can't leave
        # ``output/current.png`` truncated — display_inky.py loads that path every
        # tick, and a torn PNG there blocks the panel until the next bucket change.
        buffer = io.BytesIO()
        image.save(buffer, format="PNG")
        atomic_io.atomic_write_bytes(output_path, buffer.getvalue())
    finally:
        image.close()
    print(output_path)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
